# ── Auth helpers ────────────────────────────────────────────────────


def _impersonation_target_uid(req: Request) -> int | None:
    """6.6.2026: dokud běží impersonace (httponly imp_token cookie + otevřený
    fw.impersonation_log row), je cílový user ZDROJ PRAVDY — i kdyby auto-login
    mezitím přepsal user_id cookie zpět na rodiče. Žádný imp_token → None
    (nulová režie pro běžné usery)."""
    tok = req.cookies.get("imp_token")
    if not tok:
        return None
    from core.database_data import get_data_session as _gds_imp
    from sqlalchemy import text as _sql_imp
    ds = _gds_imp()
    try:
        return ds.execute(_sql_imp(
            "SELECT target_user_id FROM fw.impersonation_log "
            "WHERE token = :t AND ended_at IS NULL"), {"t": tok}).scalar()
    except Exception:
        return None
    finally:
        ds.close()


def _get_uid(req: Request) -> int:
    """Extract user_id z cookie. Raise 401 bez auth. Respektuje impersonaci."""
    imp = _impersonation_target_uid(req)
    if imp is not None:
        return int(imp)
    user_id_str = req.cookies.get("user_id")
    if not user_id_str:
        raise HTTPException(status_code=401, detail="Nejsi přihlášen.")
    try:
        return int(user_id_str)
    except ValueError:
        raise HTTPException(status_code=401, detail="Neplatný user_id cookie.")


def _active_imp_target(parent_uid):
    """Cílový user aktivní impersonace daného rodiče (max 8 h). Čte přes
    strategie_pg engine (stejný jako docházka/bridge — vidí fw.impersonation_log).
    Marti 14.6.: get_data_session mířil na jinou DB, kde řádek nebyl."""
    from sqlalchemy import text as _t
    try:
        cm, s = _att_session()
        try:
            r = s.execute(_t(
                "SELECT target_user_id FROM fw.impersonation_log "
                "WHERE parent_user_id = :p AND ended_at IS NULL "
                "ORDER BY id DESC LIMIT 1"), {"p": int(parent_uid)}).scalar()
            return (int(r) if r is not None else None)
        finally:
            cm.__exit__(None, None, None)
    except Exception:
        return None


def _uid_from_token_or_cookie(req: Request) -> int:
    """Efektivní user_id pro endpointy. Nad surovým resolverem přidává
    AMBASADORSKÝ režim (Marti 18.6.): pokud je přihlášený ambasador (role
    ambassador) NEBO rodič se zapnutým náhledem (cookie amb_demo=1), appka
    běží 'jako Marti' (uid 1) v REŽIMU JEN PRO ČTENÍ — req.state.amb_session=True.
    Zápisy blokuje read-only guard v main.py; cizí mzdy/pásky blokuje
    _amb_block_others. Memo na req.state, ať se neptáme DB víckrát za request."""
    raw = _resolve_uid_raw(req)
    if not raw:
        return raw
    st = getattr(req, "state", None)
    memo = getattr(st, "_amb_eff", None) if st is not None else None
    if memo is not None:
        return _AMBASSADOR_PERSONAL_UID if memo else raw
    amb = False
    try:
        if int(raw) != _AMBASSADOR_PERSONAL_UID:
            if _is_ambassador(raw):
                amb = True
            elif _amb_demo_cookie(req) and is_marti_parent(raw):
                amb = True
    except Exception:
        amb = False
    try:
        if st is not None:
            st._amb_eff = amb
            if amb:
                st.amb_session = True
    except Exception:
        pass
    return _AMBASSADOR_PERSONAL_UID if amb else raw


def _resolve_uid_raw(req: Request) -> int:
    """user_id z Bearer tokenu (nativní mobilní appka — sdílí CardDAV device
    token z "user".carddav_token) NEBO z cookie (PWA). Marti 4.6.2026 —
    background služba nemá cookie, autentizuje se tokenem (jeden token pro
    kontakty i vytáčení). Fallback na cookie když token chybí/neplatí."""
    auth = req.headers.get("authorization") or ""
    if auth.lower().startswith("bearer "):
        tok = auth[7:].strip()
        if tok:
            import hashlib
            from sqlalchemy import text as _sql_tok
            th = hashlib.sha256(tok.encode("utf-8")).hexdigest()
            uid = None
            _ov = None
            _tgt = None
            # Vše READ-ONLY v jedné session: token → uid, shared_active, impersonace.
            # UPDATE last_used až NAKONEC (best-effort) — dřív shazoval navazující
            # čtení (abort transakce přes Marti-AI roli). Marti 14.6.
            try:
                cm, s = _att_session()
                try:
                    uid = s.execute(_sql_tok(
                        'SELECT user_id FROM "user".carddav_token '
                        'WHERE token_hash = :h AND revoked_at IS NULL'), {"h": th}).scalar()
                    if uid is not None:
                        _ov = s.execute(_sql_tok(
                            "SELECT user_id FROM tenant.shared_active "
                            "WHERE token_hash = :h"), {"h": th}).scalar()
                        if _ov is None:
                            _tgt = s.execute(_sql_tok(
                                "SELECT target_user_id FROM fw.impersonation_log "
                                "WHERE parent_user_id = :p AND ended_at IS NULL "
                                "ORDER BY id DESC LIMIT 1"), {"p": int(uid)}).scalar()
                finally:
                    cm.__exit__(None, None, None)
            except Exception:
                pass
            # last_used best-effort, vlastní session, na resolution nezáleží
            if uid is not None:
                try:
                    cmu, su = _att_session()
                    try:
                        su.execute(_sql_tok('UPDATE "user".carddav_token SET last_used_at = now() WHERE token_hash = :h'), {"h": th}); su.commit()
                    finally:
                        cmu.__exit__(None, None, None)
                except Exception:
                    pass
            if _ov is not None:           # sdílený telefon (switch+PIN) má přednost
                return int(_ov)
            if _tgt is not None:          # aktivní impersonace vlastníka tokenu
                return int(_tgt)
            if uid is not None:
                return int(uid)
    # Cookie cesta (PWA / WebView appky). _get_uid ctí httponly imp_token cookie;
    # navíc respektujeme aktivní impersonaci podle user_id cookie — WebView appky
    # nemusí imp_token poslat, tak ji bereme z fw.impersonation_log (parent=user_id,
    # ended_at NULL, max 8 h) stejně jako Bearer cesta výše. Marti 14.6.
    imp = _impersonation_target_uid(req)
    if imp is not None:
        return int(imp)
    uid_c = req.cookies.get("user_id")
    if uid_c:
        try:
            cuid = int(uid_c)
        except ValueError:
            return _get_uid(req)
        t = _active_imp_target(cuid)
        if t is not None:
            return int(t)
        return cuid
    return _get_uid(req)


def _require_parent(user_id: int) -> None:
    """Auth gate pro OSOBNÍ/INTIMNÍ data (paměť/diář, HR citlivá, výplatnice,
    trezor, consents, personal konverzace) — JEN rodiče (is_marti_parent=true:
    Marti + Kristý). Systémové/admin endpointy používají _require_admin (sysadmini)."""
    if not is_marti_parent(user_id):
        raise HTTPException(
            status_code=403,
            detail=(
                "Tato část STRATEGIE (osobní data / rodičovská) je dostupná "
                "jen rodičům (is_marti_parent=true)."
            ),
        )


def _require_admin(user_id: int) -> None:
    """Auth gate pro SYSTÉMOVÉ/ADMIN endpointy (framework, design, deploy, ops,
    správa uživatelů-členů, system audit) — tier SYSADMIN: rodič NEBO is_admin
    (Marti / Kristý / Jirka). Marti 25.6.2026 (Marti-AI kustod). POZOR: is_admin
    NENÍ cross-tenant a NEDÁVÁ osobní/intimní data — ta zůstávají na _require_parent."""
    if not is_parent_or_admin(user_id):
        raise HTTPException(
            status_code=403,
            detail=(
                "Tato část STRATEGIE (systém / administrace) je dostupná jen "
                "správcům systému (rodič nebo is_admin)."
            ),
        )


