_AMBASSADOR_PERSONAL_UID = 1  # jediná osoba, jejíž osobní data ambasador vidí (Marti)


def _is_ambassador(uid: int | None) -> bool:
    """True pokud user má roli 'ambassador' v EUROSOFT tenantu (read-only showcase)."""
    if not uid:
        return False
    from sqlalchemy import text as _t
    try:
        cm, s = _att_session()
        try:
            r = s.execute(_t(
                "SELECT 1 FROM public.user_tenants WHERE user_id=:u AND tenant_id=2 "
                "AND role='ambassador' AND membership_status IN ('active','invited') LIMIT 1"),
                {"u": int(uid)}).first()
            return r is not None
        finally:
            try:
                cm.__exit__(None, None, None)
            except Exception:
                pass
    except Exception:
        return False


def _is_obchod(uid: int | None) -> bool:
    """True pokud user je člen skupiny Obchod (EUROSOFT tenant 2, group_id 7).
    Pro přístup obchodu (Pavel 30, Martin Pašek jr. 35, …) k vytížení/plánu hovorů. Kristý 29.6.2026."""
