def _can_showcase_view(uid: int | None) -> bool:
    """Read gate pro provozní přehledy: rodič NEBO ambasador (read-only)."""
    if not uid:
        return False
    return is_marti_parent(uid) or _is_ambassador(uid)


def _amb_demo_cookie(req) -> bool:
    """Rodič si může zapnout náhled 'jako ambasador' přes cookie amb_demo=1."""
    try:
        return (req.cookies.get("amb_demo") or "") == "1"
    except Exception:
        return False


def _is_amb_session(req) -> bool:
    """True, pokud aktuální request běží v ambasadorském (read-only) režimu.
    Nastavuje _uid_from_token_or_cookie do req.state.amb_session."""
    try:
        return bool(getattr(req.state, "amb_session", False))
    except Exception:
        return False


def _amb_block_others(req) -> JSONResponse | None:
    """Vrať 403, pokud běží ambasadorský režim — pro endpointy, které ukazují
    CIZÍ citlivá data (mzdy/výplatnice/karty jiných lidí). Marti 18.6.: 'moje
    výplatní pásky ano, cizí ne'."""
    if _is_amb_session(req):
        return JSONResponse({"ok": False, "error": "ambassador_hidden",
                             "detail": "V prezentačním režimu nejsou data jiných osob dostupná."},
                            status_code=403)
    return None


def _amb_or_pin_gate(s, uid: int, pin: str, req):
    """PIN brána, která v ambasadorském režimu akceptuje DEMO PIN (fw.ambassador_pin
    pro Martiho), jinak normální _pin_gate. Bez SMS. Pro Martiho pásky + trezor."""
    if _is_amb_session(req):
        from sqlalchemy import text as _t
        prow = s.execute(_t("SELECT pin_hash FROM fw.ambassador_pin WHERE user_id=:u"),
                         {"u": _AMBASSADOR_PERSONAL_UID}).first()
        if not prow:
            return {"ok": False, "error": "demo_pin_not_set",
                    "note": "Marti zatím nenastavil demo PIN."}
        if not (pin or "").strip():
            return {"ok": False, "error": "pin_required"}
        salt, _, hsh = (prow[0] or "").partition("$")
        if not (pin.strip().isdigit() and _pin_hash(pin.strip(), salt) == hsh):
            return {"ok": False, "error": "pin_wrong"}
        return None
    return _pin_gate(s, uid, (pin or "").strip())


# Design/system string entity types — blokované pro non-parent v data CRUD
# (design_patch/insert/delete_entity). Člen smí editovat jen business data
# (numeric core_id resolved na datovou tabulku), ne framework metadata
# (comp_def/menu_node/core/data_source/...) ani user management.
_DESIGN_ENTITY_TYPES = frozenset({
    "comp_def", "comp_def_design", "menu_node", "menu_node_design",
    "core", "data_source", "data_source_op", "data_set", "fw_form", "user",
})


def _require_data_write_access(user_id: int, entity_type: str) -> None:
    """Data CRUD gate (design_patch/insert/delete_entity). Rodič smí vše.
    Člen smí jen business data (numeric core_id) — NE framework/system entity
    (string v _DESIGN_ENTITY_TYPES). Defense in depth nad _require_erp_member."""
    _require_erp_member(user_id)
    if is_marti_parent(user_id):
        return
    et = (entity_type or "").strip()
    if not et.isdigit() or et in _DESIGN_ENTITY_TYPES:
        raise HTTPException(
            status_code=403,
            detail=(
                "Úprava framework/system entit je dostupná jen rodičům. "
                "Členové mohou editovat jen business záznamy."
            ),
        )


def _get_tenant_id(user_id: int) -> int:
    """
    Phase B+8.1 (6.5.2026): resolve current tenant pro per-tenant user state.
    Bere users.last_active_tenant_id, fallback na 1 (EUROSOFT default).
    """
    from core.database_core import get_core_session
    from modules.core.infrastructure.models_core import User
    cs = get_core_session()
    try:
        u = cs.query(User).filter(User.id == user_id).one_or_none()
        if u and getattr(u, "last_active_tenant_id", None):
            return int(u.last_active_tenant_id)
        return 1  # EUROSOFT default
    finally:
        cs.close()


