def _screenshot_token_ok(req: Request) -> bool:
    import os as _os_st
    tok = req.headers.get("X-Deploy-Token")
    env = _os_st.environ.get("STRATEGIE_DEPLOY_TOKEN")
    return bool(tok and env and tok == env)


# ---- CRM hromadne osloveni: suppression (odhlaseni) + odhlasovaci token ----
# Klic na podpis odhlasovaciho odkazu = STRATEGIE_DEPLOY_TOKEN (sdileny secret).
# Token round-trip: rutina Marti-AI vola crm_optout_make_token() pri sestaveni mailu,
# verejna odhlasovaci stranka (main.py) vola crm_optout_parse_token().
def _optout_secret() -> str:
    import os as _os_ou
    return _os_ou.environ.get("STRATEGIE_DEPLOY_TOKEN") or ""


def crm_optout_make_token(email: str, firma_id=None) -> str:
    """Vytvori podepsany odhlasovaci token pro dany e-mail (+volitelne firma_id/IDHlav).
    Pouziva ji odesilaci rutina (Marti-AI) pri sestaveni odhlasovaciho odkazu:
      https://strategie-ai.com/crm/odhlasit/<token>
    """
    import hmac as _hm, hashlib as _hl, base64 as _b64
    email_norm = (email or "").strip().lower()
    payload = email_norm + "|" + (str(firma_id) if firma_id not in (None, "") else "")
    b = _b64.urlsafe_b64encode(payload.encode("utf-8")).rstrip(b"=").decode("ascii")
    sig = _b64.urlsafe_b64encode(
        _hm.new(_optout_secret().encode("utf-8"), b.encode("ascii"), _hl.sha256).digest()
    ).rstrip(b"=").decode("ascii")[:22]
    return b + "." + sig


def crm_optout_parse_token(token: str):
    """Overi podpis a vrati (email_norm, firma_id|None), nebo None pri nevalidnim tokenu."""
    import hmac as _hm, hashlib as _hl, base64 as _b64
    try:
        b, sig = (token or "").split(".", 1)
        exp = _b64.urlsafe_b64encode(
            _hm.new(_optout_secret().encode("utf-8"), b.encode("ascii"), _hl.sha256).digest()
        ).rstrip(b"=").decode("ascii")[:22]
        if not _hm.compare_digest(sig, exp):
            return None
        pad = "=" * (-len(b) % 4)
        payload = _b64.urlsafe_b64decode(b + pad).decode("utf-8")
        email_norm, _, firma = payload.partition("|")
        if "@" not in email_norm:
            return None
        return (email_norm, int(firma) if firma.strip().isdigit() else None)
    except Exception:
        return None


@api_router.post("/crm/optout/check")
async def crm_optout_check(req: Request) -> JSONResponse:
    """Suppression check pro hromadne osloveni. Vstup {"emails":[...]} -> vrati
    {"opted_out":[...]} = podmnozina adres, ktere jsou odhlasene (mod.crm_email_optout).
    Auth: X-Deploy-Token (server-to-server, vola odesilaci rutina Marti-AI)."""
    if not _screenshot_token_ok(req):
        return JSONResponse({"ok": False, "error": "Neautorizováno"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatné tělo"}, status_code=400)
    emails = body.get("emails") or []
    norm = sorted({(e or "").strip().lower() for e in emails if e and "@" in e})
    if not norm:
        return JSONResponse({"ok": True, "opted_out": []})
    from core.database_data import get_data_session as _gds_oc
    from sqlalchemy import text as _sql_oc
    ds = _gds_oc()
    try:
        rows = ds.execute(_sql_oc(
            "SELECT DISTINCT email_norm FROM mod.crm_email_optout WHERE email_norm = ANY(:list)"
        ), {"list": norm}).scalars().all()
        return JSONResponse({"ok": True, "opted_out": list(rows)})
    finally:
        ds.close()


@api_router.post("/crm/osloveni/preview")
async def crm_osloveni_preview(req: Request) -> JSONResponse:
    """Nahled pred zarazenim: u vybranych firem (IDHlav) vrati prijemce (osobni
    z akce 17, jinak firemni z akce 16), prijmeni, kdy naposled osloveno (akce 22)
    a priznak odhlaseni. Read-only z CRM pres MCP. Auth: clen ERP NEBO rodic."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "Nepřihlášen"}, status_code=401)
    try:
        _require_erp_member(uid)
    except HTTPException as he:
        return JSONResponse({"ok": False, "error": he.detail}, status_code=he.status_code)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatné tělo"}, status_code=400)
    ids = []
    for x in (body.get("idhlav_list") or []):
        try:
            ids.append(int(x))
        except Exception:
            pass
    ids = sorted(set(ids))
    if not ids:
        return JSONResponse({"ok": False, "error": "Nevybral jsi žádné firmy"}, status_code=400)
    ids = ids[:200]
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    import json as _j_op
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return JSONResponse({"ok": False, "error": "CRM (MCP) nedostupné"}, status_code=503)
    id_list = ",".join(str(i) for i in ids)
    sql = (
        "SELECT a.IDHlav AS firma_id,"
        " MAX(CASE WHEN a.IDAkce=16 THEN a.FirmaText END) AS firma,"
        " MAX(CASE WHEN a.IDAkce=16 THEN a.Email END) AS firma_email,"
        " MAX(CASE WHEN a.IDAkce=17 AND a.Email LIKE '%@%' THEN a.Email END) AS osobni_email,"
        " MAX(CASE WHEN a.IDAkce=17 AND a.Email LIKE '%@%' THEN a.Prijmeni END) AS prijmeni,"
        " CONVERT(varchar, MAX(CASE WHEN a.IDAkce=22 THEN a.DatPorizeni END), 104) AS osloven_kdy"
        " FROM st.CRM_Kontakt_Akce a WITH(NOLOCK)"
        " WHERE a.IDHlav IN (" + id_list + ") GROUP BY a.IDHlav"
    )
    try:
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _j_op.loads(raw) if isinstance(raw, str) else raw
        rows = []
        if isinstance(r, dict):
            if r.get("ok") is False:
                raise RuntimeError(str(r.get("error"))[:200])
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    rows = r[k]
                    break
        elif isinstance(r, list):
            rows = r
    except Exception as exc:
        logger.exception("[crm_osloveni_preview] %s", exc)
        return JSONResponse({"ok": False, "error": "CRM dotaz selhal"}, status_code=502)
    by_id = {}
    for d in rows:
        dd = {(k or "").lower(): v for k, v in d.items()}
        try:
            by_id[int(dd.get("firma_id"))] = dd
        except Exception:
            pass
    out, recips = [], []
    for fid in ids:
        dd = by_id.get(fid, {})
        osobni = (dd.get("osobni_email") or "").strip()
        firemni = (dd.get("firma_email") or "").strip()
        if osobni:
            recipient, kind = osobni, "osobni"
        elif firemni:
            recipient, kind = firemni, "info"
        else:
            recipient, kind = "", "zadny"
        if recipient:
            recips.append(recipient.lower())
        out.append({"firma_id": fid, "firma": dd.get("firma") or ("#" + str(fid)),
                    "recipient": recipient, "kind": kind,
                    "prijmeni": dd.get("prijmeni") or "",
                    "osloven_kdy": dd.get("osloven_kdy") or ""})
    opted = set()
    if recips:
        from core.database_data import get_data_session as _gds_pp
        from sqlalchemy import text as _sql_pp
        ds = _gds_pp()
        try:
            opted = set(ds.execute(_sql_pp(
                "SELECT DISTINCT email_norm FROM mod.crm_email_optout WHERE email_norm = ANY(:l)"
            ), {"l": sorted(set(recips))}).scalars().all())
        finally:
            ds.close()
    for it in out:
        it["opted_out"] = (it["recipient"].lower() in opted) if it["recipient"] else False
    return JSONResponse({"ok": True, "items": out})


@api_router.post("/crm/osloveni/enqueue")
async def crm_osloveni_enqueue(req: Request) -> JSONResponse:
    """Pavel z UI zaradi vybrane firmy (IDHlav) do fronty mod.crm_outreach (status pending).
    NEPOSILA — odeslani je krok odesilaci rutiny (Marti-AI), zatim za test_mode / pravnim OK.
    Auth: aktivni clen EUROSOFT ERP (Pavel) NEBO rodic.
    Telo:  {"idhlav_list":[11431, ...], "template_id":9}
    Vrati: {"ok":true,"queued":N,"skipped":M}  (skipped = uz ve fronte pending)"""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "Nepřihlášen"}, status_code=401)
    try:
        _require_erp_member(uid)
    except HTTPException as he:
        return JSONResponse({"ok": False, "error": he.detail}, status_code=he.status_code)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatné tělo"}, status_code=400)
    ids = []
    for x in (body.get("idhlav_list") or []):
        try:
            ids.append(int(x))
        except Exception:
            pass
    ids = sorted(set(ids))
    if not ids:
        return JSONResponse({"ok": False, "error": "Nevybral jsi žádné firmy"}, status_code=400)
    if len(ids) > 100:
        return JSONResponse({"ok": False, "error": "Najednou max 100 firem"}, status_code=400)
    template_code = str(body.get("template_id") or body.get("template_code") or "9")[:32]
    from core.database_data import get_data_session as _gds_oe
    from sqlalchemy import text as _sql_oe
    ds = _gds_oe()
    try:
        existing = set(ds.execute(_sql_oe(
            "SELECT firma_id FROM mod.crm_outreach WHERE status='pending' AND firma_id = ANY(:ids)"
        ), {"ids": ids}).scalars().all())
        to_add = [i for i in ids if i not in existing]
        for fid in to_add:
            ds.execute(_sql_oe(
                "INSERT INTO mod.crm_outreach (firma_id, template_code, requested_by, status) "
                "VALUES (:f, :t, :by, 'pending')"
            ), {"f": fid, "t": template_code, "by": "uid:%d" % uid})
        ds.commit()
        logger.info("[crm_osloveni_enqueue] uid=%d queued=%d skipped=%d tmpl=%s",
                    uid, len(to_add), len(ids) - len(to_add), template_code)
        return JSONResponse({"ok": True, "queued": len(to_add),
                             "skipped": len(ids) - len(to_add)})
    except Exception as exc:
        logger.exception("[crm_osloveni_enqueue] %s", exc)
        try:
            ds.rollback()
        except Exception:
            pass
        return JSONResponse({"ok": False, "error": "Zápis do fronty selhal"}, status_code=500)
    finally:
        ds.close()


