@api_router.post("/crm/import/preview")
async def crm_import_preview(req: Request) -> JSONResponse:
    """Náhled importu: parse souboru, validace, dedup dle FirmaEmail. Vrací rows+summary."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "Nepřihlášen"}, status_code=401)
    try:
        _require_erp_member(uid)
    except HTTPException as he:
        return JSONResponse({"ok": False, "error": he.detail}, status_code=he.status_code)
    try:
        form = await req.form()
    except Exception:
        return JSONResponse({"ok": False, "error": "Chybí soubor"}, status_code=400)
    up = form.get("file")
    if up is None or not hasattr(up, "read"):
        return JSONResponse({"ok": False, "error": "Nahraj prosím soubor (Excel/CSV)."}, status_code=400)
    try:
        raw = await up.read()
    except Exception:
        return JSONResponse({"ok": False, "error": "Soubor nelze načíst"}, status_code=400)
    if not raw or len(raw) > 8 * 1024 * 1024:
        return JSONResponse({"ok": False, "error": "Soubor je prázdný nebo > 8 MB."}, status_code=400)
    rows, err = _crm_import_parse_rows(raw, getattr(up, "filename", ""))
    if err:
        return JSONResponse({"ok": False, "error": err}, status_code=400)
    if not rows:
        return JSONResponse({"ok": False, "error": "Soubor neobsahuje žádné firmy."}, status_code=400)
    if len(rows) > 2000:
        return JSONResponse({"ok": False, "error": "Najednou max 2000 firem."}, status_code=400)
    pairs = set()
    try:
        mcp = _crm_import_mcp()
        if mcp is not None:
            pairs = _crm_import_existing_pairs(mcp, [r["email"] for r in rows])
    except Exception:
        pairs = set()
    n_akce = n_ndr = n_dup = 0
    for r in rows:
        r["_dup"] = bool(r["email"] and (r["firma"].strip().lower(), r["email"].lower()) in pairs)
        r["_akce"] = bool(r["datum"])
        r["_bounced"] = (_crm_import_delivered(r["doruceno"]) is False)
        n_dup += 1 if r["_dup"] else 0
        n_akce += 1 if r["_akce"] else 0
        n_ndr += 1 if r["_bounced"] else 0
    summary = {"total": len(rows), "novych": sum(1 for r in rows if not r["_dup"]),
               "duplicit": n_dup, "s_akci": n_akce, "nedoruceno": n_ndr}
    return JSONResponse({"ok": True, "summary": summary, "rows": rows})


_CRM_IMPORT_JOBS = {}  # job_id → progress dict (in-memory, per API instance)


def _crm_import_write(rows, obchodnik, create_akce, zdroj, progress=None):
    """Sync zápis dávky do Centrály (běží v executoru/vlákně, ne v event loopu → neblokuje app).
    Per firma: hlavička st.CRM_Kontakt + akce „Získání firmy" (IDAkce=16, kvůli zobrazení
    názvu v CRM) + volitelně „Email na info" (IDAkce=1). Dedup dle (FirmaText, FirmaEmail).
    Retry na MCP rate-limit. Malé pauzy kvůli MCP limitu ~60 ops/min."""
    import time as _time
    import datetime as _dt
    mcp = _crm_import_mcp()
    if mcp is None:
        return {"created": 0, "skipped_dup": 0, "akce_created": 0, "akce16": 0,
                "bounced": 0, "errors": ["CRM (MCP) nedostupné"], "obchodnik": obchodnik}
    try:
        existing = _crm_import_existing_pairs(mcp, [str(r.get("email") or "") for r in rows])
    except Exception:
        existing = set()
    today = _dt.date.today().strftime("%Y-%m-%d")
    created = skipped = akce_created = akce16 = bounced = 0
    errors = []

    def _ins(table, data, retries=6):
        for att in range(retries):
            try:
                return _crm_mcp_insert(mcp, table, data)
            except Exception as exc:
                msg = str(exc).lower()
                is_rate = (("rate" in msg and "limit" in msg) or "exceeded" in msg
                           or "429" in msg or "too many" in msg)
                if is_rate and att < retries - 1:
                    _time.sleep((att + 1) * 5)  # 5,10,15,20,25 s backoff
                    continue
                raise
        return None

    for _i, r in enumerate(rows):
        if progress is not None:
            progress.update({"done": _i, "created": created, "akce16": akce16,
                             "akce_email": akce_created, "skipped": skipped,
                             "bounced": bounced, "errors": len(errors)})
        firma = str(r.get("firma") or "").strip()[:256]
        if not firma:
            continue
        email = str(r.get("email") or "").strip()[:256]
        _key = (firma.lower(), email.lower())
        if email and _key in existing:
            skipped += 1
            continue
        datum = r.get("datum") or None
        popis = _crm_import_popis(r) or None
        web = str(r.get("web") or "").strip()[:1000] or None
        try:
            new_id = _ins("CRM_Kontakt", {
                "Autor": obchodnik, "DatPorizeni": (datum or today), "FirmaText": firma,
                "FirmaEmail": (email or None), "FirmaWeb": web,
                "Zeme": (str(r.get("zeme") or "").strip()[:128] or None),
                "ZdrojKontaktu": zdroj, "Popis": popis, "KontaktOveren": 0,
            })
        except Exception as exc:
            errors.append("[" + firma[:40] + "] kontakt: " + str(exc)[:110])
            continue
        created += 1
        if email:
            existing.add(_key)
        _time.sleep(1.1)
        # akce „Získání firmy" (IDAkce=16) — CRM z ní bere zobrazovaný název/web/e-mail
        if new_id:
            try:
                _ins("CRM_Kontakt_Akce", {
                    "IDHlav": int(new_id), "Poradi": 1, "IDAkce": 16, "Splneno": 1,
                    "Autor": obchodnik, "DatPorizeni": (datum or today),
                    "FirmaText": firma, "FirmaWeb": web, "Email": (email or None),
                    "Popis": popis,
                })
                akce16 += 1
            except Exception as exc:
                errors.append("[" + firma[:40] + "] akce16: " + str(exc)[:110])
            _time.sleep(1.1)
        # akce „Email na info" (IDAkce=1)
        if create_akce and datum and new_id:
            deliv = _crm_import_delivered(r.get("doruceno"))
            splneno = 0 if deliv is False else 1
            duvod = str(r.get("duvod") or "").strip()
            if deliv is False:
                prubeh = ("Odesláno oslovení na " + (email or firma) + " – NEDORUČENO"
                          + ((" (" + duvod + ")") if duvod else ""))
                pozn = ("E-mail nedoručen " + str(datum) + (" – " + duvod if duvod else ""))[:4000]
            else:
                prubeh = "Odesláno oslovení (Email na info) na " + (email or firma)
                pozn = None
            try:
                _ins("CRM_Kontakt_Akce", {
                    "IDHlav": int(new_id), "Poradi": 2, "IDAkce": _CRM_IMPORT_EMAIL_AKCE,
                    "Autor": obchodnik, "DatumAkce": datum, "DatPorizeni": datum,
                    "Splneno": splneno, "Email": (email or None), "FirmaText": firma,
                    "Prubeh": prubeh[:3900], "Poznamka": pozn,
                })
                akce_created += 1
                bounced += 1 if deliv is False else 0
            except Exception as exc:
                errors.append("[" + firma[:40] + "] akce: " + str(exc)[:110])
            _time.sleep(1.1)
    return {"created": created, "skipped_dup": skipped, "akce_created": akce_created,
            "akce16": akce16, "bounced": bounced, "errors": errors[:50], "obchodnik": obchodnik}


def _crm_import_existing_map(mcp, emails):
    """(firma_lower, email_lower) -> ID pro už existující kontakty v st.CRM_Kontakt."""
    ems = sorted({(e or "").strip().lower() for e in emails if e and "@" in e})
    m = {}
    for i in range(0, len(ems), 200):
        inlist = ", ".join("'" + e.replace("'", "''") + "'" for e in ems[i:i + 200])
        try:
            for d in _crm_mcp_rows(mcp, "SELECT ID, FirmaText, FirmaEmail FROM st.CRM_Kontakt "
                                   "WITH(NOLOCK) WHERE FirmaEmail IS NOT NULL AND "
                                   "LOWER(LTRIM(RTRIM(FirmaEmail))) IN (" + inlist + ")"):
                dd = {(k or "").lower(): v for k, v in d.items()}
                if dd.get("id") is not None:
                    m[(str(dd.get("firmatext") or "").strip().lower(),
                       str(dd.get("firmaemail") or "").strip().lower())] = int(dd["id"])
        except Exception:
            pass
    return m


def _crm_import_bulk(rows, obchodnik, create_akce, zdroj, progress=None):
    """RYCHLÝ hromadný import do Centrály přes strategie_query_raw (bulk INSERT do st.*).
    NOVÉ firmy: kontakt + akce „Získání firmy" + „Email na info". Firmy UŽ v CRM: jen se
    DOPLNÍ akce „Email na info" (má-li řádek datum a firma tu akci k tomu datu ještě nemá)
    — kvůli opakovanému oslovování stejných leadů. Pár příkazů → sekundy, obchází rate-limit."""
    import datetime as _dt
    mcp = _crm_import_mcp()
    if mcp is None:
        return {"created": 0, "skipped_dup": 0, "akce_created": 0, "akce16": 0,
                "bounced": 0, "errors": ["CRM (MCP) nedostupné"], "obchodnik": obchodnik}

    def _sq(v):
        if v is None or str(v).strip() == "":
            return "NULL"
        s = str(v).replace("'", "''").replace("\r", " ").replace("\n", " ")
        return "N'" + s + "'"

    def _dsql(v):
        return ("'" + str(v) + "'") if v else "NULL"

    def _exec(sql):
        import json as _j
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _j.loads(raw) if isinstance(raw, str) else raw
        if isinstance(r, dict) and r.get("ok") is False:
            raise RuntimeError(str(r.get("error"))[:300])
        return r

    def _akce_email_vals(idh, r):
        deliv = _crm_import_delivered(r.get("doruceno"))
        splneno = 0 if deliv is False else 1
        duvod = str(r.get("duvod") or "").strip()
        if deliv is False:
            prubeh = ("Odesláno oslovení na " + (r["_email"] or r["_firma"]) + " – NEDORUČENO"
                      + ((" (" + duvod + ")") if duvod else ""))
            pozn = "E-mail nedoručen " + str(r["_datum"]) + (" – " + duvod if duvod else "")
        else:
            prubeh = "Odesláno oslovení (Email na info) na " + (r["_email"] or r["_firma"])
            pozn = None
        return ("(" + ",".join([
            str(idh), "2", str(_CRM_IMPORT_EMAIL_AKCE), _sq(obchodnik),
            _dsql(r["_datum"]), _dsql(r["_datum"]), str(splneno),
            _sq(r["_email"]), _sq(r["_firma"]), _sq(prubeh), _sq(pozn)]) + ")", deliv is False)

    def _insert_email_akce(evals):
        for j in range(0, len(evals), CH):
            try:
                _exec("INSERT INTO st.CRM_Kontakt_Akce (IDHlav,Poradi,IDAkce,Autor,DatumAkce,"
                      "DatPorizeni,Splneno,Email,FirmaText,Prubeh,Poznamka) VALUES "
                      + ",".join(evals[j:j + CH]))
            except Exception as exc:
                errors.append("akce email: " + str(exc)[:160])

    today = _dt.date.today().strftime("%Y-%m-%d")
    CH = 60
    errors = []
    try:
        existing_map = _crm_import_existing_map(mcp, [str(r.get("email") or "") for r in rows])
    except Exception:
        existing_map = {}

    seen = set()
    new_rows, existing_hits = [], []
    for r in rows:
        firma = str(r.get("firma") or "").strip()[:256]
        if not firma:
            continue
        email = str(r.get("email") or "").strip()[:256]
        key = (firma.lower(), email.lower())
        if email and key in seen:
            continue
        seen.add(key)
        r["_firma"] = firma
        r["_email"] = email
        r["_web"] = str(r.get("web") or "").strip()[:1000]
        r["_zeme"] = str(r.get("zeme") or "").strip()[:128]
        r["_datum"] = r.get("datum") or None
        r["_popis"] = _crm_import_popis(r)
        if email and key in existing_map:
            existing_hits.append((r, existing_map[key]))
        else:
            new_rows.append(r)
    if progress is not None:
        progress["total"] = len(rows)

    created = akce16 = akce_email = bounced = akce_existing = 0

    # ── NOVÉ firmy: kontakt + akce Získání firmy + Email na info ──
    if new_rows:
        marker = None
        try:
            mrows = _crm_mcp_rows(mcp, "SELECT ISNULL(MAX(ID),0) AS m FROM st.CRM_Kontakt WITH(NOLOCK)")
            marker = int((mrows[0].get("m") if mrows else 0) or 0)
        except Exception as exc:
            errors.append("marker: " + str(exc)[:120])
        if marker is not None:
            for i in range(0, len(new_rows), CH):
                chunk = new_rows[i:i + CH]
                vals = []
                for r in chunk:
                    vals.append("(" + ",".join([
                        _sq(obchodnik), _dsql(r["_datum"] or today), _sq(r["_firma"]),
                        _sq(r["_email"]), _sq(r["_web"]), _sq(r["_zeme"]),
                        _sq(zdroj), _sq(r["_popis"]), "0"]) + ")")
                try:
                    _exec("INSERT INTO st.CRM_Kontakt (Autor,DatPorizeni,FirmaText,FirmaEmail,"
                          "FirmaWeb,Zeme,ZdrojKontaktu,Popis,KontaktOveren) VALUES " + ",".join(vals))
                    created += len(chunk)
                    if progress is not None:
                        progress["created"] = created
                        progress["done"] = created
                except Exception as exc:
                    errors.append("kontakty: " + str(exc)[:160])
            try:
                _exec("INSERT INTO st.CRM_Kontakt_Akce (IDHlav,Poradi,IDAkce,Splneno,Autor,"
                      "DatPorizeni,FirmaText,FirmaWeb,Email,Popis) "
                      "SELECT ID,1,16,1,Autor,DatPorizeni,FirmaText,FirmaWeb,FirmaEmail,Popis "
                      "FROM st.CRM_Kontakt WITH(NOLOCK) WHERE ZdrojKontaktu=" + _sq(zdroj)
                      + " AND ID > " + str(marker))
                akce16 = created
            except Exception as exc:
                errors.append("akce16: " + str(exc)[:160])
            if create_akce:
                idmap = {}
                try:
                    for b in _crm_mcp_rows(mcp, "SELECT ID, FirmaText, FirmaEmail FROM st.CRM_Kontakt "
                                           "WITH(NOLOCK) WHERE ZdrojKontaktu=" + _sq(zdroj)
                                           + " AND ID > " + str(marker)):
                        bb = {(k or "").lower(): v for k, v in b.items()}
                        if bb.get("id") is not None:
                            idmap[(str(bb.get("firmatext") or "").strip().lower(),
                                   str(bb.get("firmaemail") or "").strip().lower())] = int(bb["id"])
                except Exception as exc:
                    errors.append("readback: " + str(exc)[:120])
                evals = []
                for r in new_rows:
                    if not r["_datum"]:
                        continue
                    idh = idmap.get((r["_firma"].lower(), r["_email"].lower()))
                    if not idh:
                        continue
                    v, isb = _akce_email_vals(idh, r)
                    evals.append(v)
                    akce_email += 1
                    bounced += 1 if isb else 0
                _insert_email_akce(evals)

    # ── EXISTUJÍCÍ firmy: doplnit akci „Email na info" (dedup dle (ID, datum)) ──
    skipped = 0
    if create_akce and existing_hits:
        want = [(r, cid) for (r, cid) in existing_hits if r["_datum"]]
        ids = sorted({cid for (_, cid) in want})
        have = set()
        for i in range(0, len(ids), 200):
            idlist = ",".join(str(x) for x in ids[i:i + 200])
            try:
                for a in _crm_mcp_rows(mcp, "SELECT IDHlav, CONVERT(varchar(10),DatumAkce,23) AS d "
                                       "FROM st.CRM_Kontakt_Akce WITH(NOLOCK) WHERE IDAkce="
                                       + str(_CRM_IMPORT_EMAIL_AKCE) + " AND IDHlav IN (" + idlist + ")"):
                    aa = {(k or "").lower(): v for k, v in a.items()}
                    if aa.get("idhlav") is not None:
                        have.add((int(aa["idhlav"]), str(aa.get("d") or "")))
            except Exception as exc:
                errors.append("existing readback: " + str(exc)[:120])
        evals = []
        for (r, cid) in want:
            if (int(cid), str(r["_datum"])) in have:
                continue
            v, isb = _akce_email_vals(cid, r)
            evals.append(v)
            akce_existing += 1
            bounced += 1 if isb else 0
        _insert_email_akce(evals)
        skipped = len(existing_hits) - akce_existing

    if progress is not None:
        progress.update({"done": len(rows), "created": created, "akce16": akce16,
                         "akce_email": akce_email + akce_existing, "akce_existing": akce_existing,
                         "bounced": bounced, "skipped": skipped, "errors": len(errors)})
    return {"created": created, "skipped_dup": skipped, "akce_created": akce_email + akce_existing,
            "akce16": akce16, "akce_existing": akce_existing, "bounced": bounced,
            "errors": errors[:50], "obchodnik": obchodnik}


@api_router.post("/crm/import/commit")
async def crm_import_commit(req: Request) -> JSONResponse:
    """Zápis importu do Centrály: kontakty + akce Email na info (Autor=obchodník)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "Nepřihlášen"}, status_code=401)
    try:
        _require_erp_member(uid)
    except HTTPException as he:
        return JSONResponse({"ok": False, "error": he.detail}, status_code=he.status_code)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatné tělo"}, status_code=400)
    rows = body.get("rows") or []
    obchodnik = str(body.get("obchodnik") or "").strip()
    create_akce = bool(body.get("create_akce", True))
    zdroj = (str(body.get("zdroj") or "Import").strip() or "Import")[:50]
    if not rows:
        return JSONResponse({"ok": False, "error": "Žádné řádky k importu"}, status_code=400)
    if len(rows) > 2000:
        return JSONResponse({"ok": False, "error": "Max 2000 firem"}, status_code=400)
    if not obchodnik:
        return JSONResponse({"ok": False, "error": "Vyber obchodníka"}, status_code=400)
    ok_login = True
    try:
        from core.database_data import get_data_session as _gds
        from sqlalchemy import text as _t
        ds = _gds()
        try:
            ok_login = ds.execute(_t("SELECT 1 FROM public.users WHERE lower(login_name)=lower(:l) LIMIT 1"),
                                  {"l": obchodnik}).first() is not None
        finally:
            ds.close()
    except Exception:
        ok_login = True
    if not ok_login:
        return JSONResponse({"ok": False, "error": "Neznámý obchodník: " + obchodnik}, status_code=400)
    import uuid as _uuid, threading as _thr
    job_id = _uuid.uuid4().hex
    progress = {"job_id": job_id, "total": len(rows), "done": 0, "created": 0,
                "akce16": 0, "akce_email": 0, "skipped": 0, "bounced": 0,
                "errors": 0, "finished": False, "obchodnik": obchodnik}
    _CRM_IMPORT_JOBS[job_id] = progress

    def _run():
        try:
            rep = _crm_import_bulk(rows, obchodnik, create_akce, zdroj, progress=progress)
            progress.update({"created": rep.get("created", 0), "akce16": rep.get("akce16", 0),
                             "akce_email": rep.get("akce_created", 0),
                             "akce_existing": rep.get("akce_existing", 0),
                             "skipped": rep.get("skipped_dup", 0), "bounced": rep.get("bounced", 0),
                             "errors": len(rep.get("errors", [])),
                             "error_list": rep.get("errors", [])[:20]})
        except Exception as exc:
            progress["fatal"] = str(exc)[:200]
            logger.exception("[crm_import_job] %s", exc)
        finally:
            progress["done"] = len(rows)
            progress["finished"] = True
            logger.info("[crm_import_job] job=%s obchodnik=%s created=%d a16=%d aemail=%d skip=%d err=%d",
                        job_id, obchodnik, progress.get("created", 0), progress.get("akce16", 0),
                        progress.get("akce_email", 0), progress.get("skipped", 0),
                        progress.get("errors", 0))

    _thr.Thread(target=_run, daemon=True).start()
    return JSONResponse({"ok": True, "job_id": job_id, "total": len(rows)})


@api_router.get("/crm/import/status")
async def crm_import_status(req: Request) -> JSONResponse:
    """Průběh importní úlohy (in-memory per instance)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "Nepřihlášen"}, status_code=401)
    try:
        _require_erp_member(uid)
    except HTTPException as he:
        return JSONResponse({"ok": False, "error": he.detail}, status_code=he.status_code)
    prog = _CRM_IMPORT_JOBS.get(req.query_params.get("job_id") or "")
    if not prog:
        return JSONResponse({"ok": False, "error": "neznámá úloha"}, status_code=404)
    return JSONResponse({"ok": True, "progress": prog})


@api_router.post("/app/mail/stav")
async def app_mail_stav(req: Request) -> JSONResponse:
    """Uklidit e-mail: přesun mezi 'nove' (Doručené) a 'zpracovane' (Zpracované).
    ACL: majitel schránky NEBO rodič. Nezapisuje do Outlooku — jen náš stav."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "Nepřihlášen"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatné tělo"}, status_code=400)
    try:
        mid = int(body.get("id"))
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "chybí id"}, status_code=400)
    stav = (body.get("stav") or "zpracovane").strip()
    if stav not in ("nove", "zpracovane"):
        return JSONResponse({"ok": False, "error": "stav musí být nove|zpracovane"}, status_code=400)
    from sqlalchemy import text as _tms
    from core.database_data import get_data_session as _gdms
    s = _gdms()
    try:
        row = s.execute(_tms("SELECT user_id FROM tenant.mail_message WHERE id=:i"), {"i": mid}).fetchone()
        if not row:
            return JSONResponse({"ok": False, "error": "zpráva nenalezena"}, status_code=404)
        if row[0] != uid and not is_marti_parent(uid):
            return JSONResponse({"ok": False, "error": "nemáš oprávnění"}, status_code=403)
        s.execute(_tms("UPDATE tenant.mail_message SET stav=:s, stav_kdy=now(), stav_kdo=:u WHERE id=:i"),
                  {"s": stav, "u": uid, "i": mid})
        s.commit()
    finally:
        s.close()
    return JSONResponse({"ok": True, "id": mid, "stav": stav})


@api_router.get("/app/mail/detail/{mid}")
async def app_mail_detail(mid: int, req: Request) -> JSONResponse:
    """Detail e-mailu (hlavičky + plné tělo + přílohy). ACL: majitel nebo rodič."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "Nepřihlášen"}, status_code=401)
    import json as _jmd
    from sqlalchemy import text as _tmd
    from core.database_data import get_data_session as _gdmd
    s = _gdmd()
    try:
        row = s.execute(_tmd(
            "SELECT user_id, od_jmeno, od_email, komu, kopie, "
            "to_char(datum,'DD.MM.YYYY HH24:MI') AS d, predmet, telo_text, slozka, stav, "
            "prilohy_doc_ids, ma_prilohy, telo_html FROM tenant.mail_message WHERE id=:i"), {"i": mid}).fetchone()
        if not row:
            return JSONResponse({"ok": False, "error": "e-mail nenalezen"}, status_code=404)
        if row[0] != uid and not is_marti_parent(uid):
            return JSONResponse({"ok": False, "error": "nemáš oprávnění"}, status_code=403)
        prilohy = []
        doc_ids = row[10]
        if doc_ids:
            try:
                ids = doc_ids if isinstance(doc_ids, list) else _jmd.loads(doc_ids)
                for did in ids:
                    dn = s.execute(_tmd("SELECT COALESCE(original_filename, name) FROM public.documents WHERE id=:i"),
                                   {"i": did}).scalar()
                    prilohy.append({"id": did, "name": dn or ("priloha_%s" % did),
                                    "url": "/api/v1/documents/%s/raw" % did})
            except Exception:
                pass
        return JSONResponse({"ok": True, "id": mid, "od_jmeno": row[1], "od_email": row[2],
                             "komu": row[3], "kopie": row[4], "datum": row[5], "predmet": row[6],
                             "telo_text": row[7], "slozka": row[8], "stav": row[9],
                             "ma_prilohy": row[11], "telo_html": row[12], "prilohy": prilohy})
    finally:
        s.close()


@api_router.post("/app/connect-mailbox")
async def app_connect_mailbox(req: Request) -> JSONResponse:
    """Self-service: přihlášený uživatel připojí SVOU EWS poštovní schránku
    (login + heslo + server + zobrazovaná adresa). Heslo se šifruje (Fernet) a
    NEprochází přes AI ani do logů. Umožní „posílat z mojí schránky"
    (send_email from_identity='user'). Cíl = přihlášený uid. (Kristý 25.6.2026.)"""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "Nepřihlášen"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatné tělo"}, status_code=400)
    # Funkční schránka (Marti 3.7.2026): rodič smí připojit schránku PRO jiný účet
    # (target_uid, např. projects@ = uid 111). Heslo se šifruje Fernetem, AI ho nevidí.
    _tuid = body.get("target_uid")
    if _tuid and is_marti_parent(uid):
        try:
            uid = int(_tuid)
        except (TypeError, ValueError):
            pass
    login = (body.get("login") or "").strip()
    password = body.get("password") or ""
    server = (body.get("server") or "https://mail.eurosoft-control.cz").strip()
    display = (body.get("display") or "").strip()
    if not login or not password:
        return JSONResponse({"ok": False, "error": "Vyplň přihlašovací jméno i heslo."},
                            status_code=400)
    # 1) Ověření údajů proti EWS (best-effort) — ať uživatel hned ví, jestli sedí.
    verified = False
    try:
        from modules.notifications.application.email_service import _get_account
        acct = _get_account(email=login, password=password, server=server)
        _ = acct.inbox.total_count  # vynutí reálné přihlášení
        verified = True
    except Exception as exc:
        _auth = False
        try:
            from modules.notifications.application.email_service import _is_auth_error as _iae
            _auth = _iae(exc)
        except Exception:
            _auth = False
        if _auth:
            return JSONResponse(
                {"ok": False, "error": "Přihlášení ke schránce selhalo — zkontroluj "
                                       "přihlašovací jméno a heslo."}, status_code=400)
        logger.warning("[connect-mailbox] uid=%s validace (non-auth): %s", uid, str(exc)[:160])
    # 2) Uložit (heslo se šifruje uvnitř upsert_user_email).
    try:
        from modules.notifications.application.user_channel_service import upsert_user_email
        res = upsert_user_email(uid, email=login, password=password, server=server,
                                display_email=(display or None))
    except Exception as exc:
        logger.exception("[connect-mailbox] uid=%s upsert selhal", uid)
        return JSONResponse({"ok": False, "error": "Uložení selhalo: " + str(exc)[:120]},
                            status_code=500)
    logger.info("[connect-mailbox] uid=%s ulozeno (verified=%s)", uid, verified)
    return JSONResponse({"ok": True, "verified": verified,
                         "display": res.get("ews_display_email") or res.get("ews_email")})


