# CRM Akce → STRATEGIE edit-jadro mapping (Kristy 26.6.2026). Picker na gridu
# Akci nabidne typ akce; podle IDAkce se otevre prislusne edit jadro. Default =
# jadro 82 (osobni jednani / Centrala 1495). Doplnuj jak vznikaji jadra per akce.
_CRM_AKCE_DEFAULT_CORE = 82
_CRM_AKCE_CORE_MAP = {
    1: 132,   # Email na info
    2: 130,   # Telefonat na firmu
    3: 133,   # Email odpovedne osobe
    4: 131,   # Telefonat na OO
    5: 129,   # Info o zakaznikovi
    6: 82,    # Osobni jednani = vychozi jadro
    16: 134,  # Ziskani firmy obecne (nejpouzivanejsi, 9186 zaznamu)
    17: 81,   # Ziskani kontaktu na osobu z firmy = hotove jadro 81
    19: 135,  # Sem zavolej = jadro s vnorenym gridem kontaktu firmy
    # 1499 zakazky / 1497 poptavky = odlozeno (Kristy 26.6. - nestavet na dbo).
    # NULL akce (20 Nema zajem / 21 LinkedIn / 22 Osloveni) -> default 82.
}


@api_router.get("/app/crm/akce-typy")
async def app_crm_akce_typy(req: Request) -> JSONResponse:
    """Picker typu akce pro grid CRM Akce (Kristy 26.6.2026).

    Vraci seznam typu akci z st.CRM_Kontakt_AkceCis (DB_EC, MCP) + namapovane
    STRATEGIE edit-jadro (core_id, default 82). Frontend (erp_grid_actions.js)
    z toho staví picker pri 'Novy' a routuje edit podle IDAkce zaznamu.
    Auth: clen ERP NEBO rodic."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "Neprihlasen"}, status_code=401)
    try:
        _require_erp_member(uid)
    except HTTPException as he:
        return JSONResponse({"ok": False, "error": he.detail}, status_code=he.status_code)
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    import json as _j_at
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return JSONResponse({"ok": False, "error": "CRM (MCP) nedostupne"}, status_code=503)
    sql = (
        "SELECT c.ID AS id, c.Nazev AS nazev, c.ID_Edit AS id_edit "
        "FROM st.CRM_Kontakt_AkceCis c WITH(NOLOCK) ORDER BY c.Poradi, c.ID"
    )
    try:
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _j_at.loads(raw) if isinstance(raw, str) else raw
        rows = []
        if isinstance(r, dict):
            if r.get("ok") is False:
                raise RuntimeError(str(r.get("error"))[:200])
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    rows = r[k]
                    break
        elif isinstance(r, list):
            rows = r
    except Exception as exc:
        logger.exception("[crm_akce_typy] %s", exc)
        return JSONResponse({"ok": False, "error": "CRM dotaz selhal"}, status_code=502)
    types = []
    for row in rows:
        try:
            _id = int(row.get("id"))
        except Exception:
            continue
        types.append({
            "id": _id,
            "nazev": (row.get("nazev") or "").strip(),
            "core_id": _CRM_AKCE_CORE_MAP.get(_id, _CRM_AKCE_DEFAULT_CORE),
        })
    return JSONResponse({"ok": True, "types": types,
                         "default_core": _CRM_AKCE_DEFAULT_CORE})


@api_router.get("/app/crm/aktivity-souhrn")
async def app_crm_aktivity_souhrn(req: Request) -> JSONResponse:
    """A.3 (Pavlovy připomínky): souhrnná čísla NAD přehledem „Aktivity obchodníka".
    Read-only agregace z st.CRM_Kontakt_Akce (MCP DB_EC): oslovené firmy / e-maily /
    hovory / osobní / poptávky / zakázky / nezájem za období, per obchodník (Autor).
    Query: ?autor=<Autor>&obdobi=mesic|rok|vse (autor vynechán = můj login; prázdný = všichni).
    Auth: člen ERP NEBO rodič. (Kristý 25.6.2026.)"""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "Nepřihlášen"}, status_code=401)
    try:
        _require_erp_member(uid)
    except HTTPException as he:
        return JSONResponse({"ok": False, "error": he.detail}, status_code=he.status_code)
    q = req.query_params
    obdobi = (q.get("obdobi") or "rok").lower()
    # muj_autor = login_name uzivatele (Autor v CRM = login, napr. Pavel = 'PZeman')
    muj_autor = ""
    try:
        from core.database_data import get_data_session as _gds_au
        from sqlalchemy import text as _t_au
        _sa = _gds_au()
        try:
            muj_autor = (_sa.execute(_t_au("SELECT login_name FROM public.users WHERE id=:i"),
                                     {"i": uid}).scalar() or "").strip()
        finally:
            _sa.close()
    except Exception:
        muj_autor = ""
    autor_eff = (q.get("autor") or "").strip() if "autor" in q else muj_autor
    import datetime as _dt_au
    today = _dt_au.date.today()
    od = do = None
    if obdobi == "mesic":
        od, do = today.replace(day=1), today
    elif obdobi == "rok":
        od, do = today.replace(month=1, day=1), today

    def _lit(v):  # MSSQL string literál
        return "'" + str(v).replace("'", "''") + "'"
    where = ["1=1"]
    if autor_eff:
        where.append("LTRIM(RTRIM(a.Autor)) = " + _lit(autor_eff))
    if od:
        where.append("COALESCE(a.DatumAkce, CAST(a.DatPorizeni AS date)) >= " + _lit(od.isoformat()))
    if do:
        where.append("COALESCE(a.DatumAkce, CAST(a.DatPorizeni AS date)) <= " + _lit(do.isoformat()))
    wsql = " AND ".join(where)
    sql_counts = (
        "SELECT"
        " COUNT(DISTINCT CASE WHEN a.IDakce IN (1,3,22) THEN a.IDHlav END) AS oslovene_firmy,"
        " SUM(CASE WHEN a.IDakce IN (1,3,22) THEN 1 ELSE 0 END) AS emaily,"
        " SUM(CASE WHEN a.IDakce IN (2,4) THEN 1 ELSE 0 END) AS hovory,"
        " SUM(CASE WHEN a.IDakce = 6 THEN 1 ELSE 0 END) AS osobni,"
        " SUM(CASE WHEN a.IDakce = 7 THEN 1 ELSE 0 END) AS poptavky,"
        " SUM(CASE WHEN a.IDakce = 8 THEN 1 ELSE 0 END) AS zakazky,"
        " SUM(CASE WHEN a.IDakce = 20 THEN 1 ELSE 0 END) AS nezajem"
        " FROM st.CRM_Kontakt_Akce a WITH(NOLOCK) WHERE " + wsql
    )
    sql_autori = (
        "SELECT LTRIM(RTRIM(a.Autor)) AS autor, COUNT(*) AS pocet"
        " FROM st.CRM_Kontakt_Akce a WITH(NOLOCK)"
        " WHERE a.Autor IS NOT NULL AND LTRIM(RTRIM(a.Autor)) <> ''"
        " GROUP BY LTRIM(RTRIM(a.Autor)) ORDER BY COUNT(*) DESC"
    )
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    import json as _j_au
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return JSONResponse({"ok": False, "error": "CRM (MCP) nedostupné"}, status_code=503)

    def _run(sql):
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _j_au.loads(raw) if isinstance(raw, str) else raw
        rows = []
        if isinstance(r, dict):
            if r.get("ok") is False:
                raise RuntimeError(str(r.get("error"))[:200])
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    rows = r[k]
                    break
        elif isinstance(r, list):
            rows = r
        return rows

    try:
        crows = _run(sql_counts)
        arows = _run(sql_autori)
    except Exception as exc:
        logger.exception("[crm_aktivity_souhrn] %s", exc)
        return JSONResponse({"ok": False, "error": "CRM dotaz selhal"}, status_code=502)

    def _ci(d, key):
        dd = {(k or "").lower(): v for k, v in d.items()}
        try:
            return int(dd.get(key) or 0)
        except Exception:
            return 0
    keys = ("oslovene_firmy", "emaily", "hovory", "osobni", "poptavky", "zakazky", "nezajem")
    counts = {k: (_ci(crows[0], k) if crows else 0) for k in keys}
    obchodnici = []
    for d in arows:
        dd = {(k or "").lower(): v for k, v in d.items()}
        a = (dd.get("autor") or "").strip()
        if a:
            obchodnici.append({"autor": a, "pocet": _ci(d, "pocet")})
    return JSONResponse({"ok": True, "counts": counts, "obchodnici": obchodnici,
                         "muj_autor": muj_autor, "autor": autor_eff, "obdobi": obdobi})


@api_router.post("/crm/optout/make-tokens")
async def crm_optout_make_tokens(req: Request) -> JSONResponse:
    """Vrati hotove odhlasovaci tokeny + URL pro dane (email, firma_id) pary, aby
    odesilaci rutina (Marti-AI) NEMUSELA znat podpisovy secret — podpis zustava na serveru.
    Soucasne vrati priznak opted_out (suppression), takze staci jedno volani.
    Auth: X-Deploy-Token. E-maily v TELE (ne v query — osobni udaj).
    Telo:  {"items": [{"email":"a@x.cz","firma_id":11431}, ...]}
    Vrati: {"ok":true,"items":[{"email","firma_id","opted_out","token","url"}, ...]}"""
    if not _screenshot_token_ok(req):
        return JSONResponse({"ok": False, "error": "Neautorizováno"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatné tělo"}, status_code=400)
    items = body.get("items") or []
    base = (body.get("base_url") or "https://strategie-ai.com").rstrip("/")
    norm_map = {}
    for it in items:
        e = (it.get("email") or "").strip().lower()
        if e and "@" in e:
            norm_map.setdefault(e, it.get("firma_id"))
    if not norm_map:
        return JSONResponse({"ok": True, "items": []})
    from core.database_data import get_data_session as _gds_mt
    from sqlalchemy import text as _sql_mt
    ds = _gds_mt()
    try:
        opted = set(ds.execute(_sql_mt(
            "SELECT DISTINCT email_norm FROM mod.crm_email_optout WHERE email_norm = ANY(:list)"
        ), {"list": sorted(norm_map.keys())}).scalars().all())
    finally:
        ds.close()
    out = []
    for e, fid in norm_map.items():
        tok = crm_optout_make_token(e, fid)
        out.append({"email": e, "firma_id": fid, "opted_out": (e in opted),
                    "token": tok, "url": base + "/crm/odhlasit/" + tok})
    return JSONResponse({"ok": True, "items": out})


def crm_optout_record(email_norm: str, firma_id=None, source: str = "unsubscribe_link",
                      note: str = None) -> bool:
    """Zapise odhlaseni do mod.crm_email_optout (idempotentne). Vola odhlasovaci stranka."""
    from core.database_data import get_data_session as _gds_or
    from sqlalchemy import text as _sql_or
    ds = _gds_or()
    try:
        ds.execute(_sql_or("""
            INSERT INTO mod.crm_email_optout (email_norm, firma_id, source, note, created_by)
            VALUES (:e, :f, :s, :n, 'odhlasovaci_odkaz')
            ON CONFLICT (email_norm) DO NOTHING
        """), {"e": (email_norm or "").strip().lower(), "f": firma_id, "s": source, "n": note})
        ds.commit()
        return True
    except Exception as exc:
        logger.exception("[crm_optout_record] %s", exc)
        try:
            ds.rollback()
        except Exception:
            pass
        return False
    finally:
        ds.close()


@api_router.post("/app/screenshot")
async def app_screenshot_upload(req: Request) -> JSONResponse:
    """Appka posle anotovany snimek obrazovky (zmrazit + nakreslit). Cil zatim
    Claude (user 23) — ulozi se na cloud, bridge ho stahne. Token NEBO cookie."""
    import os as _os_ss, base64 as _b64_ss, time as _t_ss, json as _j_ss
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "Nepřihlášen"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatné tělo"}, status_code=400)
    b64 = (body.get("img_b64") or "").strip()
    if b64[:5].lower() == "data:" and "," in b64[:64]:
        b64 = b64.split(",", 1)[1]
    if not b64:
        return JSONResponse({"ok": False, "error": "Chybí obrázek"}, status_code=400)
    try:
        raw = _b64_ss.b64decode(b64)
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatný base64"}, status_code=400)
    if len(raw) > 12 * 1024 * 1024:
        return JSONResponse({"ok": False, "error": "Snímek > 12 MB"}, status_code=400)
    note = (body.get("note") or "").strip()[:500]
    target = (body.get("target") or "claude").strip()[:32]
    d = _screenshot_dir()
    ts = _t_ss.strftime("%Y%m%d_%H%M%S")
    fname = "u%d_%s.png" % (uid, ts)
    try:
        with open(_os_ss.path.join(d, fname), "wb") as f:
            f.write(raw)
        with open(_os_ss.path.join(d, "latest_u%d.png" % uid), "wb") as f:
            f.write(raw)
        meta = {"ts": ts, "note": note, "target": target, "fname": fname,
                "uid": uid, "epoch": int(_t_ss.time())}
        with open(_os_ss.path.join(d, "latest_u%d.json" % uid), "w", encoding="utf-8") as f:
            _j_ss.dump(meta, f)
    except Exception as exc:
        logger.exception("[app_screenshot] save failed: %s", exc)
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    logger.info("[app_screenshot] uid=%d ts=%s %dB note=%r", uid, ts, len(raw), note[:60])
    return JSONResponse({"ok": True, "ts": ts})


@api_router.get("/app/screenshot/poll")
async def app_screenshot_poll(req: Request, uid: int = 0) -> JSONResponse:
    """Bridge zjisti, jestli je novy snimek od usera <uid>. X-Deploy-Token."""
    import os as _os_sp, json as _j_sp
    if not _screenshot_token_ok(req):
        return JSONResponse({"ok": False, "error": "Neautorizováno"}, status_code=401)
    p = _os_sp.path.join(_screenshot_dir(), "latest_u%d.json" % int(uid))
    if not _os_sp.path.isfile(p):
        return JSONResponse({"ok": True, "has": False})
    try:
        with open(p, "r", encoding="utf-8") as f:
            meta = _j_sp.load(f)
    except Exception:
        return JSONResponse({"ok": True, "has": False})
    return JSONResponse({"ok": True, "has": True, "ts": meta.get("ts"),
                         "note": meta.get("note", ""), "epoch": meta.get("epoch", 0)})


