# ---- Trezor hesel/tokenu (Marti 11.6.): Fernet + PIN + SMS 2FA + email -------
# Marti 20.6.2026: vault klíč SAMOBOOTSTRAP — nesmí čekat na ruční env/klik.
# Priorita: (1) env STRATEGIE_VAULT_KEY (override, silnější separace klíče od dat),
# (2) persistovaný klíč v fw.app_secret (sdílený přes blue-green obě instance),
# (3) auto-vygeneruj a ulož při prvním použití. Memoizováno.
# Pozn. tradeoff: klíč v DB = DB dump odhalí i klíč; pro interní nástroj za VPN
# přijatelné a hlavně to běží automaticky. Env override zůstává pro tvrdší režim.
_VAULT_FERNET_CACHE = [None]


def _vault_fernet():
    import os
    try:
        from cryptography.fernet import Fernet
    except Exception:
        return None
    key = (os.environ.get("STRATEGIE_VAULT_KEY") or "").strip()
    if key:
        try:
            return Fernet(key.encode())
        except Exception:
            pass
    if _VAULT_FERNET_CACHE[0] is not None:
        return _VAULT_FERNET_CACHE[0]
    try:
        from core.database_data import get_data_session as _g
        from sqlalchemy import text as _t
        s = _g()
        try:
            row = s.execute(_t("SELECT sval FROM fw.app_secret WHERE skey='vault_key'")).first()
            if row and row[0]:
                k = row[0]
            else:
                k = Fernet.generate_key().decode()
                s.execute(_t("INSERT INTO fw.app_secret(skey,sval) VALUES('vault_key',:v) "
                             "ON CONFLICT (skey) DO NOTHING"), {"v": k})
                s.commit()
                r2 = s.execute(_t("SELECT sval FROM fw.app_secret WHERE skey='vault_key'")).first()
                k = r2[0] if r2 and r2[0] else k  # kdyby druhá instance vložila dřív
            f = Fernet(k.encode())
            _VAULT_FERNET_CACHE[0] = f
            return f
        finally:
            s.close()
    except Exception:
        return None


def _self_owner_phone(s, uid: int):
    from sqlalchemy import text as _t
    return s.execute(_t(
        "SELECT contact_value FROM public.user_contacts WHERE user_id=:u "
        "AND contact_type='phone' AND COALESCE(status,'active')='active' "
        "ORDER BY COALESCE(is_verified,false) DESC, COALESCE(is_primary,false) DESC, id LIMIT 1"),
        {"u": uid}).scalar()


def _self_owner_email(s, uid: int):
    from sqlalchemy import text as _t
    return s.execute(_t(
        "SELECT contact_value FROM public.user_contacts WHERE user_id=:u "
        "AND contact_type='email' AND COALESCE(status,'active')='active' "
        "ORDER BY COALESCE(is_primary,false) DESC, id LIMIT 1"), {"u": uid}).scalar()


def _self_notify_owner(s, uid: int, subject: str, msg: str) -> None:
    """Zprava VLASTNIKOVI (in-app cink + email). Best-effort."""
    from sqlalchemy import text as _t
    try:
        s.execute(_t(
            "INSERT INTO fw.mobile_command (app_key, target_user_id, command_type, title, message, created_by) "
            "VALUES ('mobile', :u, 'claude_msg', :ti, :m, :u)"),
            {"u": uid, "ti": subject[:120], "m": msg[:6000]})
    except Exception:
        pass
    try:
        em = _self_owner_email(s, uid)
        if em:
            from modules.notifications.application.email_service import queue_email
            queue_email(to=em, subject=subject, body=msg, user_id=uid, purpose="self_data_alert")
    except Exception:
        pass


