# ---- HR sprava lidi (Marti 11.6.): prehled + karty pro HR skupinu/rodice -----
def _hr_can_manage(s, uid: int) -> bool:
    from sqlalchemy import text as _t
    r = s.execute(_t("SELECT COALESCE(is_marti_parent,false) FROM public.users WHERE id=:u"),
                  {"u": uid}).first()
    if r and r[0]:
        return True
    m = s.execute(_t(
        "SELECT 1 FROM tenant.staff_group_member m JOIN tenant.staff_group g ON g.id=m.group_id "
        "WHERE g.tenant_id=2 AND NOT g.archived AND g.name='HR' AND m.user_id=:u"),
        {"u": uid}).first()
    return m is not None


def _banka_can_uid(uid: int) -> bool:
    """Přístup k bankovní sekci: rodič NEBO Petra Šafránková (uid 18, účetní) NEBO
    člen skupiny Účetnictví/Banka/Finance. (Marti 23.6.2026 — Banka = věc Petry.)"""
    if not uid:
        return False
    try:
        if is_marti_parent(uid):
            return True
    except Exception:
        pass
    if int(uid) == 18:
        return True
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        m = s.execute(_t(
            "SELECT 1 FROM tenant.staff_group_member m JOIN tenant.staff_group g ON g.id=m.group_id "
            "WHERE g.tenant_id=2 AND NOT g.archived AND g.name IN ('Účetnictví','Banka','Finance') "
            "AND m.user_id=:u"), {"u": uid}).first()
        return m is not None
    finally:
        try:
            s.close()
        except Exception:
            pass


def _has_capability(uid: int, cap: str, level: str = "read") -> bool:
    """Fáze 2a práv — capability gate (data-driven, per-modul read/write).
    Rodič (is_marti_parent) má vše = bypass (Q3). Jinak aktivní grant
    v tenant.user_capability pro (uid, cap) s úrovní >= level (write >= read).
    Tenant 2 (EUROSOFT). Granty/odběr = řádek v DB + audit, ne deploy."""
    if not uid:
        return False
    try:
        if is_marti_parent(uid):
            return True
    except Exception:
        pass
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        cond = " AND level='write'" if level == "write" else ""
        r = s.execute(_t(
            "SELECT 1 FROM tenant.user_capability "
            "WHERE tenant_id=2 AND user_id=:u AND capability_code=:c "
            "AND revoked_at IS NULL" + cond + " LIMIT 1"),
            {"u": uid, "c": cap}).first()
        return r is not None
    finally:
        try:
            s.close()
        except Exception:
            pass


@api_router.get("/app/hr/people")
async def app_hr_people(req: Request) -> JSONResponse:
    """Seznam lidí pro HR (rodiče + HR skupina). Hledání přes ?q=."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    _ab = _amb_block_others(req)
    if _ab is not None:
        return _ab
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        if not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        rows = s.execute(_t(
            "SELECT u.id, "
            " COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),''), "
            "   (SELECT em.full_name FROM tenant.att_employee em WHERE em.user_id=u.id AND em.tenant_id=2 LIMIT 1)) AS jmeno, "
            " (SELECT d.perm_city FROM tenant.user_self_data d WHERE d.user_id=u.id AND d.tenant_id=2) AS mesto, "
            " EXISTS(SELECT 1 FROM tenant.user_self_data d WHERE d.user_id=u.id AND d.tenant_id=2) AS ma_kartu "
            "FROM public.users u "
            "WHERE EXISTS (SELECT 1 FROM public.user_tenants ut WHERE ut.user_id=u.id AND ut.tenant_id=2 "
            "   AND ut.membership_status IN ('active','invited')) AND u.id NOT IN (2,3,23,24) "
            "ORDER BY jmeno")).fetchall()
        q = (req.query_params.get("q") or "").strip().lower()
        out = []
        for r in rows:
            nm = (r[1] or ("#" + str(r[0])))
            if q and q not in nm.lower():
                continue
            out.append({"user_id": r[0], "jmeno": nm, "mesto": r[2] or "", "ma_kartu": bool(r[3])})
        return JSONResponse({"ok": True, "lide": out})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/hr/dashboard")
async def app_hr_dashboard(req: Request) -> JSONResponse:
    """HR nástěnka (Šárka 23.6.): badge počty + Aktuality.
    badges: mimo (kdo dnes není ve firmě vč. HO) · naroz (narozeniny+výročí 7 dní) ·
    novi (noví do roka) · vyberka (běžící výběrová řízení).
    aktuality: noví · narozeniny · výročí · konec zkušebky (4 měs) · roční prodloužení · běžící výběrka."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    _ab = _amb_block_others(req)
    if _ab is not None:
        return _ab
    from sqlalchemy import text as _t
    import datetime as _dt
    _MES = ["", "ledna", "února", "března", "dubna", "května", "června",
            "července", "srpna", "září", "října", "listopadu", "prosince"]
    def _cz(d):
        return ("%d. %s %d" % (d.day, _MES[d.month], d.year)) if d else ""
    cm, s = _att_session()
    try:
        if not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        mimo = s.execute(_t(
            "SELECT count(*) FROM (SELECT e.user_id,"
            " (array_agg(t.code ORDER BY en.id DESC) FILTER (WHERE t.category='absence'))[1] abs_code,"
            " bool_or(t.code='homeoffice' OR (t.code='work' AND en.note ILIKE :hopat)) ho"
            " FROM tenant.att_entry en JOIN tenant.att_employee e ON e.id=en.employee_id AND e.tenant_id=2"
            " JOIN tenant.att_entry_type t ON t.id=en.entry_type_id"
            " WHERE en.entry_date=current_date AND COALESCE(en.status,'') NOT IN ('superseded','announced')"
            " GROUP BY e.user_id) q WHERE q.abs_code IS NOT NULL OR q.ho"),
            {"hopat": "%home office%"}).scalar() or 0
        vyb = s.execute(_t(
            "SELECT title, position_text, date_open, date_valid_to FROM tenant.recruit_posting"
            " WHERE tenant_id=2 AND COALESCE(published,false)=true AND date_open<=current_date"
            " AND (date_valid_to IS NULL OR date_valid_to>=current_date) ORDER BY date_open DESC")).fetchall()
        akt_rows = s.execute(_t(
            "WITH eng AS (SELECT ae.user_id, e.smlouva_od, e.zkusebni_do, e.smlouva_do, e.pozice_text"
            "  FROM tenant.engagement e JOIN tenant.att_employee ae ON ae.id=e.employee_id"
            "  WHERE e.tenant_id=2 AND e.is_current AND ae.user_id IS NOT NULL),"
            " nm AS (SELECT user_id, max(trim(coalesce(first_name,'')||' '||coalesce(last_name,''))) jmeno,"
            "  max(birth_date) birth FROM tenant.hr_person WHERE tenant_id=2 AND is_current GROUP BY user_id)"
            " SELECT typ, jmeno, dat, info FROM ("
            "  SELECT 'novy' typ, n.jmeno, eng.smlouva_od dat, eng.pozice_text info FROM eng JOIN nm n ON n.user_id=eng.user_id WHERE eng.smlouva_od >= current_date-365"
            "  UNION ALL SELECT 'zkusebka', n.jmeno, eng.zkusebni_do, NULL FROM eng JOIN nm n ON n.user_id=eng.user_id WHERE eng.zkusebni_do BETWEEN current_date AND current_date+14"
            "  UNION ALL SELECT 'prodlouzeni', n.jmeno, eng.smlouva_do, NULL FROM eng JOIN nm n ON n.user_id=eng.user_id WHERE eng.smlouva_do BETWEEN current_date AND current_date+30"
            "  UNION ALL SELECT 'narozeniny', n.jmeno, n.birth, NULL FROM nm n WHERE n.birth IS NOT NULL AND ((date_part('doy',n.birth)-date_part('doy',current_date)+366)::int%366) <= 7"
            "  UNION ALL SELECT 'vyroci', n.jmeno, eng.smlouva_od, NULL FROM eng JOIN nm n ON n.user_id=eng.user_id WHERE eng.smlouva_od IS NOT NULL AND eng.smlouva_od < current_date-300 AND ((date_part('doy',eng.smlouva_od)-date_part('doy',current_date)+366)::int%366) <= 7"
            " ) q ORDER BY dat")).fetchall()
        akt = []
        cnt = {"novy": 0, "narozeniny": 0, "vyroci": 0, "zkusebka": 0, "prodlouzeni": 0}
        IK = {"novy": "🆕", "narozeniny": "🎂", "vyroci": "🎉", "zkusebka": "📋", "prodlouzeni": "📝"}
        today = _dt.date.today()
        for typ, jm, dat, info in akt_rows:
            cnt[typ] = cnt.get(typ, 0) + 1
            jm = jm or "?"
            if typ == "novy":
                txt = "%s nastoupil(a) %s%s" % (jm, _cz(dat), (" jako " + info) if info else "")
            elif typ == "narozeniny":
                txt = "%s — narozeniny %s" % (jm, _cz(dat))
            elif typ == "vyroci":
                txt = "%s — %d. výročí nástupu (%s)" % (jm, max(1, today.year - dat.year), _cz(dat))
            elif typ == "zkusebka":
                txt = "%s — končí zkušební doba %s" % (jm, _cz(dat))
            elif typ == "prodlouzeni":
                txt = "%s — řešit prodloužení smlouvy (do %s)" % (jm, _cz(dat))
            else:
                txt = jm
            akt.append({"typ": typ, "ikona": IK.get(typ, "•"), "text": txt})
        for title, pos, do, dv in vyb:
            akt.insert(0, {"typ": "vyberka", "ikona": "🧲",
                           "text": "Výběrové řízení: %s — běží od %s%s" % (title or pos or "?", _cz(do), (" do " + _cz(dv)) if dv else "")})
        # Vlastní stálé aktuality (Šárka 8.7.2026) — dokud nebude editovatelný seznam z UI.
        akt.append({"typ": "info", "ikona": "🎓",
                    "text": "Praxe studenta SOUE — Marek Horník (od 7. 9. 2026, liché týdny)"})
        akt.append({"typ": "info", "ikona": "📋",
                    "text": "Dušanovi na konci kvartálu poslat výrobní směrnice"})
        if today <= _dt.date(2026, 12, 18):
            akt.append({"typ": "info", "ikona": "🎄",
                        "text": "18. 12. 2026 — vánoční večírek v Srdcovce (jako loni)"})
        badges = {"mimo": int(mimo), "naroz": cnt["narozeniny"] + cnt["vyroci"], "novi": cnt["novy"], "vyberka": len(vyb)}
        return JSONResponse({"ok": True, "badges": badges, "aktuality": akt})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/hr/mimo")
async def app_hr_mimo(req: Request) -> JSONResponse:
    """Krok 1 HR modul (Šárka 3.7.2026): rozpad badge 'mimo' na seznam lidí, kteří
    DNES nejsou v kanceláři (absence + home office) + důvod. Stejný zdroj jako badge
    v /app/hr/dashboard (att_entry + att_employee + att_entry_type). HR-gated."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    _ab = _amb_block_others(req)
    if _ab is not None:
        return _ab
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        if not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        rows = s.execute(_t(
            "SELECT q.user_id, q.abs_code, q.abs_label, q.ho, COALESCE("
            "  (SELECT trim(coalesce(p.first_name,'')||' '||coalesce(p.last_name,''))"
            "     FROM tenant.hr_person p WHERE p.user_id=q.user_id AND p.tenant_id=2 AND p.is_current"
            "     ORDER BY p.id DESC LIMIT 1),"
            "  (SELECT trim(coalesce(u.first_name,'')||' '||coalesce(u.last_name,''))"
            "     FROM public.users u WHERE u.id=q.user_id)) AS jmeno"
            " FROM (SELECT e.user_id,"
            "   (array_agg(t.code  ORDER BY en.id DESC) FILTER (WHERE t.category='absence'))[1] abs_code,"
            "   (array_agg(t.label ORDER BY en.id DESC) FILTER (WHERE t.category='absence'))[1] abs_label,"
            "   bool_or(t.code='homeoffice' OR (t.code='work' AND en.note ILIKE :hopat)) ho"
            "   FROM tenant.att_entry en"
            "   JOIN tenant.att_employee e ON e.id=en.employee_id AND e.tenant_id=2"
            "   JOIN tenant.att_entry_type t ON t.id=en.entry_type_id"
            "   WHERE en.entry_date=current_date AND COALESCE(en.status,'') NOT IN ('superseded','announced')"
            "   GROUP BY e.user_id) q"
            " WHERE q.abs_code IS NOT NULL OR q.ho"
            " ORDER BY jmeno"),
            {"hopat": "%home office%"}).fetchall()
        def _ic(abs_code, ho):
            c = (abs_code or "").lower()
            if "nemoc" in c or "sick" in c:
                return "🤒"
            if "dovol" in c or "vacation" in c:
                return "🏖️"
            if "lekar" in c or "lékař" in c or "doctor" in c:
                return "🩺"
            if "ocr" in c or "osetr" in c or "ošetr" in c:
                return "🧑‍⚕️"
            if abs_code:
                return "📋"
            return "🏠"
        lide = []
        for user_id, abs_code, abs_label, ho, jmeno in rows:
            duv = []
            if abs_label:
                duv.append(abs_label)
            if ho:
                duv.append("Home office")
            nm = (jmeno or "").strip() or ("ID " + str(user_id))
            lide.append({
                "user_id": user_id,
                "jmeno": nm,
                "duvod": " + ".join(duv) if duv else "—",
                "ikona": _ic(abs_code, ho),
            })
        return JSONResponse({"ok": True, "lide": lide, "pocet": len(lide)})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/hr/jubilea")
async def app_hr_jubilea(req: Request) -> JSONResponse:
    """Krok 2 HR modul (Šárka 3.7.2026): nadcházející narozeniny + pracovní výročí
    v okně N dní, s výpočtem let a zvýrazněním jubileí. Významná pracovní výročí
    10/20 = 'major' (🏆), 5/15/25/30/35/40 + kulaté narozeniny = 'minor' (⭐).
    HR-gated. Slouží k panelu i k předstihovému upozornění."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    _ab = _amb_block_others(req)
    if _ab is not None:
        return _ab
    import datetime as _dt
    try:
        days = int(req.query_params.get("days") or 30)
    except Exception:
        days = 30
    days = max(1, min(days, 366))
    _MES = ["", "ledna", "února", "března", "dubna", "května", "června",
            "července", "srpna", "září", "října", "listopadu", "prosince"]
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        if not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        rows = s.execute(_t(
            "WITH eng AS (SELECT ae.user_id, min(e.smlouva_od) smlouva_od"
            "  FROM tenant.engagement e JOIN tenant.att_employee ae ON ae.id=e.employee_id"
            "  WHERE e.tenant_id=2 AND e.is_current AND ae.user_id IS NOT NULL"
            "  GROUP BY ae.user_id),"
            " nm AS (SELECT user_id,"
            "  max(trim(coalesce(first_name,'')||' '||coalesce(last_name,''))) jmeno,"
            "  max(birth_date) birth FROM tenant.hr_person"
            "  WHERE tenant_id=2 AND is_current GROUP BY user_id)"
            " SELECT n.user_id, n.jmeno, n.birth, eng.smlouva_od"
            " FROM nm n LEFT JOIN eng ON eng.user_id=n.user_id"
            " WHERE n.birth IS NOT NULL OR eng.smlouva_od IS NOT NULL")).fetchall()
        today = _dt.date.today()

        def _next_occ(d):
            if not d:
                return None
            y = today.year
            try:
                occ = d.replace(year=y)
            except ValueError:
                occ = _dt.date(y, 2, 28)
            if occ < today:
                try:
                    occ = d.replace(year=y + 1)
                except ValueError:
                    occ = _dt.date(y + 1, 2, 28)
            return occ

        def _cz(d):
            return "%d. %s" % (d.day, _MES[d.month]) if d else ""

        WORK_MAJOR = {10, 20}
        WORK_MINOR = {5, 15, 25, 30, 35, 40}
        BDAY_MAJOR = {50, 60}
        BDAY_MINOR = {30, 40, 70, 80}
        items = []
        for user_id, jmeno, birth, smlouva_od in rows:
            jm = (jmeno or "").strip() or ("ID " + str(user_id))
            occ = _next_occ(birth)
            if occ is not None and 0 <= (occ - today).days <= days:
                age = occ.year - birth.year
                if age >= 1:
                    tier = "major" if age in BDAY_MAJOR else ("minor" if age in BDAY_MINOR else "normal")
                    items.append({
                        "user_id": user_id, "jmeno": jm, "kind": "narozeniny", "ikona": "🎂",
                        "datum": occ.isoformat(), "datum_cz": _cz(occ),
                        "za_dni": (occ - today).days, "roky": age, "tier": tier,
                        "popis": "%d. narozeniny" % age,
                    })
            occ2 = _next_occ(smlouva_od)
            if occ2 is not None and 0 <= (occ2 - today).days <= days:
                yrs = occ2.year - smlouva_od.year
                if yrs >= 1:
                    tier = "major" if yrs in WORK_MAJOR else ("minor" if yrs in WORK_MINOR else "normal")
                    items.append({
                        "user_id": user_id, "jmeno": jm, "kind": "vyroci",
                        "ikona": "🏆" if tier == "major" else ("⭐" if tier == "minor" else "🎉"),
                        "datum": occ2.isoformat(), "datum_cz": _cz(occ2),
                        "za_dni": (occ2 - today).days, "roky": yrs, "tier": tier,
                        "popis": "%d let ve firmě" % yrs,
                    })
        items.sort(key=lambda x: (x["za_dni"], 0 if x["tier"] == "major" else (1 if x["tier"] == "minor" else 2)))
        return JSONResponse({"ok": True, "jubilea": items, "pocet": len(items)})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


