def _recruit_scope(s, uid: int):
    """Marti-AI Q2 (13.6.): rodiče + HR skupina vidí vše ('all'); recruiter jen
    svá výběrová řízení ('own'); ostatní nic (None)."""
    if _hr_can_manage(s, uid):
        return "all"
    from sqlalchemy import text as _t
    r = s.execute(_t("SELECT 1 FROM tenant.recruit_application WHERE tenant_id=2 AND recruiter_user_id=:u LIMIT 1"),
                  {"u": uid}).first()
    return "own" if r else None


@api_router.get("/app/recruit/pipeline")
async def app_recruit_pipeline(req: Request) -> JSONResponse:
    """Nábor — dashboard pipeline (počty per fáze, bez PII). Rodiče+HR vše, recruiter svá."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        scope = _recruit_scope(s, uid)
        if not scope:
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        pf = " AND a.recruiter_user_id = :u" if scope == "own" else ""
        prm = {"u": uid} if scope == "own" else {}
        rows = s.execute(_t(
            "SELECT COALESCE(p.label,'(bez fáze)') f, COALESCE(p.priority_order,999) ord, "
            " COALESCE(p.is_hired,false) hired, count(*) c "
            "FROM tenant.recruit_application a LEFT JOIN tenant.recruit_phase p ON p.id=a.phase_id "
            "WHERE a.tenant_id=2" + pf + " GROUP BY p.label, p.priority_order, p.is_hired ORDER BY ord"), prm).fetchall()
        tot = s.execute(_t("SELECT count(*) FROM tenant.recruit_application a WHERE a.tenant_id=2" + pf), prm).scalar()
        cand = s.execute(_t(
            "SELECT count(DISTINCT a.candidate_id) FROM tenant.recruit_application a "
            "JOIN tenant.recruit_candidate c ON c.id=a.candidate_id "
            "WHERE a.tenant_id=2 AND c.anonymized_at IS NULL" + pf), prm).scalar()
        return JSONResponse({"ok": True, "total": int(tot or 0), "candidates": int(cand or 0), "scope": scope,
                             "phases": [{"faze": r[0], "hired": bool(r[2]), "pocet": int(r[3])} for r in rows]})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


# ─── Bakaláři Nerudovka (tenant 13) — rozvrhové přehledy ze zrcadla. ───
_BK_TENANT = 13
_BK_DNY = {1: "Po", 2: "Út", 3: "St", 4: "Čt", 5: "Pá"}


def _bk_can_view(s, uid: int) -> bool:
    from sqlalchemy import text as _t
    r = s.execute(_t("SELECT COALESCE(is_marti_parent,false) FROM public.users WHERE id=:u"), {"u": uid}).first()
    if r and r[0]:
        return True
    # členové tenantu NERUDOVKA (učitelé školy) vidí svůj rozvrh
    m = s.execute(_t("SELECT 1 FROM public.user_tenants WHERE user_id=:u AND tenant_id=:t "
                     "AND membership_status='active' LIMIT 1"), {"u": uid, "t": _BK_TENANT}).first()
    return bool(m)


def _bk_plat_od(s) -> str:
    from sqlalchemy import text as _t
    r = s.execute(_t("SELECT MAX(plat_od) FROM tenant.bakalari_uvaz WHERE tenant_id=:t"), {"t": _BK_TENANT}).scalar()
    return r or ""


def _bk_skolrok(po: str) -> str:
    if not po or len(po) < 6:
        return po or ""
    try:
        y = int(po[:4]); m = int(po[4:6])
    except Exception:
        return po
    return ("%d/%d" % (y, y + 1)) if m >= 8 else ("%d/%d" % (y - 1, y))


def _bk_po(req, s) -> str:
    """Vybraná verze rozvrhu (PLAT_OD) z ?po=, jinak nejnovější v zrcadle."""
    p = (req.query_params.get("po") or "").strip()
    if p:
        from sqlalchemy import text as _t
        ok = s.execute(_t("SELECT 1 FROM tenant.bakalari_uvaz WHERE tenant_id=:t AND plat_od=:p LIMIT 1"),
                       {"t": _BK_TENANT, "p": p}).first()
        if ok:
            return p
    return _bk_plat_od(s)


@api_router.get("/app/bakalari/versions")
async def app_bakalari_versions(req: Request) -> JSONResponse:
    """Dostupné školní roky/verze rozvrhu v zrcadle (pro přepínač)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        if not _bk_can_view(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        rows = s.execute(_t("SELECT DISTINCT plat_od FROM tenant.bakalari_uvaz WHERE tenant_id=:t ORDER BY plat_od DESC"),
                         {"t": _BK_TENANT}).fetchall()
        # jeden záznam na školní rok (nejnovější verze v roce)
        seen = {}
        order = []
        for r in rows:
            po = r[0]
            sr = _bk_skolrok(po)
            if sr not in seen:
                seen[sr] = po
                order.append(sr)
        cur = _bk_plat_od(s)
        items = [{"po": seen[sr], "skolrok": sr, "aktualni": (seen[sr] == cur)} for sr in order]
        return JSONResponse({"ok": True, "items": items, "aktualni_po": cur})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/bakalari/overview")
async def app_bakalari_overview(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        if not _bk_can_view(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        po = _bk_po(req, s)
        if not po:
            return JSONResponse({"ok": True, "plat_od": "", "empty": True})
        def _c(tbl):
            return int(s.execute(_t("SELECT count(*) FROM tenant.%s WHERE tenant_id=:t AND plat_od=:p" % tbl),
                                 {"t": _BK_TENANT, "p": po}).scalar() or 0)
        bud = s.execute(_t("SELECT TRIM(COALESCE(kod_budo,'')) b, count(*) FROM tenant.bakalari_mist "
                           "WHERE tenant_id=:t AND plat_od=:p GROUP BY TRIM(kod_budo) ORDER BY 2 DESC"),
                        {"t": _BK_TENANT, "p": po}).fetchall()
        budovy = [{"kod": b[0], "nazev": _bk_budova(b[0]), "mistnosti": int(b[1])} for b in bud if b[0]]
        return JSONResponse({"ok": True, "plat_od": po,
                             "trid": _c("bakalari_trid"), "ucitelu": _c("bakalari_ucit"),
                             "predmetu": _c("bakalari_pred"), "mistnosti": _c("bakalari_mist"),
                             "budovy": budovy,
                             "hodin": int(s.execute(_t("SELECT count(*) FROM tenant.bakalari_uvaz WHERE tenant_id=:t AND plat_od=:p AND den BETWEEN 1 AND 5"), {"t": _BK_TENANT, "p": po}).scalar() or 0)})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


