def _kara_band(v):
    if v is None:
        return ("none", "Nezařazeno")
    if v > 500:
        return ("raketa", "Raketa")
    if v > 100:
        return ("letadlo", "Letadlo")
    if v >= 50:
        return ("tahoun", "Tahoun")
    if v >= 0:
        return ("efektivni", "Efektivní")
    if v >= -49:
        return ("rozvoj", "Rozvoj")
    return ("prostor", "Prostor pro změnu")


