@api_router.post("/app/attendance/absence/cancel")
async def att_absence_cancel(req: Request) -> JSONResponse:
    """Zaměstnanec zruší VLASTNÍ nevyřízenou (pending) žádost o absenci.
    Pokud už byla materializovaná do docházky, uklidí i att_entry té žádosti
    (source_system='absence_req', source_id=rid). Jirka 29.6.2026 (souhlas Marti)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        b = await req.json()
    except Exception:
        b = {}
    try:
        rid = int((b or {}).get("id") or 0)
    except Exception:
        rid = 0
    if not rid:
        return JSONResponse({"ok": False, "error": "missing_id"}, status_code=400)
    cm, s = _att_session()
    try:
        r = s.execute(_t("SELECT stav, materialized FROM tenant.att_absence_request "
                         "WHERE id=:i AND user_id=:u"), {"i": rid, "u": uid}).first()
        if not r:
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        stav, materialized = r[0], r[1]
        if stav != "pending":
            return JSONResponse({"ok": False, "error": "not_cancellable"}, status_code=400)
        if materialized:
            s.execute(_t("DELETE FROM tenant.att_entry WHERE tenant_id=2 "
                         "AND source_system='absence_req' AND source_id=:i"), {"i": rid})
        s.execute(_t("UPDATE tenant.att_absence_request SET stav='cancelled', materialized=false, "
                     "status_text='Zrušeno zaměstnancem', decided_at=now() WHERE id=:i"), {"i": rid})
        return JSONResponse({"ok": True})
    finally:
        cm.__exit__(None, None, None)


# ── OČR (ošetřovné) — Fáze 1: strukturovaný případ (bez ČSSZ API) ──────────
# Zaměstnanec zadá identifikátor ze SMS + ošetřovanou osobu + datum od;
# na konci doplní datum do + dny; HR/vedoucí schválí. Firma EC/ES z engagementu.
# Fáze 2 (až bude certifikát): ověření identifikátoru + stažení dokumentů +
# podání NEMPRI přes VREP. Složka + podklad pro účetní = Fáze 1b.

def _ocr_fill_dochazka(s, emp, d0, d1, uid, note, source="ocr", code="family_care") -> int:
    """Absence (family_care/sick) → docházka att_entry na každý pracovní den d0..d1 (Po–Pá), idempotentně.
    **Absenční den = ŽÁDNÉ jiné záznamy** (Marti 28.6.: kdo je na OČR/nemocenské nesmí mít docházku — úklid).
    Na těch dnech SMAŽE všechny ostatní att_entry (práce/režie/pauza/…) a nechá jen daný absenční typ."""
    from sqlalchemy import text as _t
    import datetime as _dt
    tr = s.execute(_t("SELECT id FROM tenant.att_entry_type WHERE tenant_id=2 AND code=:c"), {"c": code}).first()
    if not tr:
        return 0
    tid = tr[0]
    created = 0
    day = d0
    while day <= d1:
        if day.weekday() < 5:
            # OČR den = jen OČR → smaž vše ostatní (práce/režie/pauza/nenároková/automat…)
            s.execute(_t("DELETE FROM tenant.att_entry WHERE tenant_id=2 AND employee_id=:e "
                         "AND entry_date=:d AND entry_type_id<>:et"), {"e": emp, "d": day, "et": tid})
            res = s.execute(_t(
                "UPDATE tenant.att_entry SET hours=8, status='pending', source=:src, note=:n, updated_at=now() "
                "WHERE tenant_id=2 AND employee_id=:e AND entry_date=:d AND entry_type_id=:et"),
                {"src": source, "n": note, "e": emp, "d": day, "et": tid})
            if (res.rowcount or 0) == 0:
                s.execute(_t(
                    "INSERT INTO tenant.att_entry (tenant_id,employee_id,entry_date,entry_type_id,hours,"
                    "status,source,note,is_active,created_by_id,created_at,updated_at) "
                    "VALUES (2,:e,:d,:et,8,'pending',:src,:n,false,:u,now(),now())"),
                    {"e": emp, "d": day, "et": tid, "src": source, "n": note, "u": uid})
                created += 1
        day = day + _dt.timedelta(days=1)
    return created


_OCR_EXTEND_LAST = [0.0]  # self-gate (1×/hod)


def _ocr_extend_active():
    """Aktivní OČR (stav novy/probiha, bez datum_do) → označ dnešek family_care v docházce.
    Volá se z _att_sync_loop (self-gated 1×/hod). Tím průběžné dny OČR padají do docházky samy."""
    import time as _tm
    if _tm.time() - _OCR_EXTEND_LAST[0] < 3600:
        return
    _OCR_EXTEND_LAST[0] = _tm.time()
    from sqlalchemy import text as _t
    import datetime as _dt
    today = _dt.date.today()
    if today.weekday() >= 5:
        return
    cm, s = _att_session()
    try:
        rows = s.execute(_t(
            "SELECT employee_id, user_id, osoba_jmeno, datum_od FROM tenant.att_ocr_case "
            "WHERE tenant_id=2 AND stav IN ('novy','probiha') AND datum_do IS NULL "
            "AND datum_od <= :t"), {"t": today}).fetchall()
        for r in rows:
            try:
                d0 = r[3] if r[3] and r[3] >= (today - _dt.timedelta(days=60)) else today
                _ocr_fill_dochazka(s, r[0], d0, today, r[1],
                                   "OČR (probíhá): " + (r[2] or ""), "ocr_auto", "family_care")
            except Exception:
                pass
        # aktivní nemocenská → docházka (sick)
        srows = s.execute(_t(
            "SELECT employee_id, user_id, cislo_dpn, datum_od FROM tenant.att_sick_case "
            "WHERE tenant_id=2 AND stav IN ('novy','probiha') AND datum_do IS NULL "
            "AND datum_od <= :t"), {"t": today}).fetchall()
        for r in srows:
            try:
                d0 = r[3] if r[3] and r[3] >= (today - _dt.timedelta(days=60)) else today
                _ocr_fill_dochazka(s, r[0], d0, today, r[1],
                                   "Nemocenská (probíhá)" + ((" DPN " + r[2]) if r[2] else ""),
                                   "sick_auto", "sick")
            except Exception:
                pass
        s.commit()
    except Exception:
        try:
            s.rollback()
        except Exception:
            pass
    finally:
        cm.__exit__(None, None, None)


def _eneschopenka_to_sick():
    """AUTOMAT (Marti 28.6.2026): ČSSZ DPN z datovky (tenant.eneschopenka) → registr nemocí
    (att_sick_case) → docházka (sick). OBECNĚ přes VŠECHNY řádky, párování přes RODNÉ ČÍSLO
    (ne jméno): emp_rc → cloud Helios TabCisZam.RodCislo → firma+číslo → att_employee.
    Idempotentní na cislo_dpn=id_pripadu. Uzavřené DPN rovnou naplní docházku za celý rozsah;
    otevřené dobíhá _ocr_extend_active. Odtud teče do plánu (vytížení) i do monitoru mezd."""
    from sqlalchemy import text as _t
    import datetime as _dt
    created = updated = skipped = filled = 0
    cm, s = _att_session()
    try:
        rows = s.execute(_t(
            "SELECT id, id_pripadu, emp_rc, datum_od, datum_do, druh_nemoci "
            "FROM tenant.eneschopenka WHERE tenant_id=2 AND COALESCE(emp_rc,'')<>'' "
            "AND datum_od IS NOT NULL")).fetchall()
        for r in rows:
            dpn = str(r[1] or "").strip()
            rc = str(r[2]).replace("/", "").replace(" ", "").strip()
            if not dpn or not rc:
                skipped += 1
                continue
            firma = cislo = None
            for f, cdb in (("EC", "UCTO_EC"), ("ES", "UCTO_ES")):
                q = _mssql188_query("SELECT TOP 1 Cislo FROM " + cdb +
                                    ".dbo.TabCisZam WHERE RodneCisloBezLomitka='" + rc + "'")
                if q.get("ok") and q.get("rows"):
                    try:
                        firma, cislo = f, int(q["rows"][0][0])
                    except Exception:
                        firma = cislo = None
                    if cislo:
                        break
            if not cislo:
                skipped += 1
                continue
            emp = s.execute(_t("SELECT id, user_id FROM tenant.att_employee "
                               "WHERE tenant_id=2 AND cislo_zam=:c LIMIT 1"), {"c": str(cislo)}).first()
            if not emp:
                skipped += 1
                continue
            eid, uid = emp[0], emp[1]
            d_od, d_do = r[3], r[4]
            stav = "ukonceno" if d_do else "probiha"
            ex = s.execute(_t("SELECT id FROM tenant.att_sick_case WHERE tenant_id=2 AND cislo_dpn=:d"),
                           {"d": dpn}).first()
            if ex:
                s.execute(_t("UPDATE tenant.att_sick_case SET employee_id=:e, user_id=:u, company=:f, "
                             "datum_od=:od, datum_do=:dd, stav=:st, updated_at=now() WHERE id=:i"),
                          {"e": eid, "u": uid, "f": firma, "od": d_od, "dd": d_do, "st": stav, "i": ex[0]})
                updated += 1
            else:
                s.execute(_t("INSERT INTO tenant.att_sick_case "
                             "(tenant_id, employee_id, user_id, company, cislo_dpn, datum_od, datum_do, stav, created_at, updated_at) "
                             "VALUES (2,:e,:u,:f,:d,:od,:dd,:st, now(), now())"),
                          {"e": eid, "u": uid, "f": firma, "d": dpn, "od": d_od, "dd": d_do, "st": stav})
                created += 1
            # uzavřené DPN → rovnou doplnit docházku za celý rozsah (otevřené dobíhá _ocr_extend_active)
            try:
                end = d_do if d_do else _dt.date.today()
                filled += _ocr_fill_dochazka(s, eid, d_od, end, uid,
                                             "Nemocenská (DPN " + dpn + ")", "cssz_dpn", "sick")
            except Exception:
                pass
        s.commit()
    except Exception as _e:
        try:
            s.rollback()
        except Exception:
            pass
        return {"ok": False, "error": str(_e)[:200]}
    finally:
        cm.__exit__(None, None, None)
    return {"ok": True, "vytvoreno": created, "aktualizovano": updated,
            "preskoceno": skipped, "dochazka_dnu": filled}


def _ocr_company(s, emp) -> str | None:
    """Kód firmy (EC/ES) z aktivního engagementu zaměstnance. Best-effort."""
    from sqlalchemy import text as _t
    try:
        return s.execute(_t(
            "SELECT c.code FROM tenant.engagement e "
            "JOIN tenant.company c ON c.id = e.company_id "
            "WHERE e.employee_id=:e AND (e.smlouva_do IS NULL OR e.smlouva_do >= CURRENT_DATE) "
            "ORDER BY e.smlouva_od DESC NULLS LAST LIMIT 1"), {"e": emp}).scalar()
    except Exception:
        return None


@api_router.post("/app/ocr/start")
async def ocr_start(req: Request) -> JSONResponse:
    """Zaměstnanec zakládá OČR: identifikátor (ze SMS) + ošetřovaná osoba + datum od.
    Vznikne OČR případ + navázaná absence (typ ocr) routovaná na vedoucího."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    import datetime as _dt
    try:
        b = await req.json()
    except Exception:
        b = {}
    ident = str((b or {}).get("identifikator") or "").strip()[:120] or None
    osoba = str((b or {}).get("osoba_jmeno") or "").strip()[:160] or None
    rc = str((b or {}).get("osoba_rc") or "").strip()[:20] or None
    vztah = str((b or {}).get("osoba_vztah") or "").strip()[:60] or None
    try:
        d_od = _dt.date.fromisoformat(str((b or {}).get("od") or "")[:10])
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatné datum od."})
    if not osoba:
        return JSONResponse({"ok": False, "error": "Vyplň ošetřovanou osobu."})
    cm, s = _att_session()
    try:
        emp = _att_employee(s, uid)
        if not emp:
            return JSONResponse({"ok": False, "error": "Nejsi v evidenci docházky."})
        company = _ocr_company(s, emp)
        mgr = None
        try:
            mgr = s.execute(_t("SELECT tenant.resolve_role(2, :e, 'attendance_supervisor')"),
                            {"e": emp}).scalar()
        except Exception:
            mgr = None
        # navázaná absence (datum_do zatím = od; doplní se na konci)
        arid = s.execute(_t(
            "INSERT INTO tenant.att_absence_request (tenant_id,employee_id,user_id,typ,datum_od,datum_do,"
            "hours_per_day,note,stav,manager_user_id) "
            "VALUES (2,:e,:u,'family_care',:od,:od,8,:n,'pending',:m) RETURNING id"),
            {"e": emp, "u": uid, "od": d_od, "n": ("OČR: " + osoba), "m": mgr}).scalar()
        cid = s.execute(_t(
            "INSERT INTO tenant.att_ocr_case (tenant_id,employee_id,user_id,company,identifikator,"
            "osoba_jmeno,osoba_rc,osoba_vztah,datum_od,stav,absence_request_id,created_by_id) "
            "VALUES (2,:e,:u,:co,:id,:oj,:rc,:vz,:od,'novy',:ar,:u) RETURNING id"),
            {"e": emp, "u": uid, "co": company, "id": ident, "oj": osoba, "rc": rc, "vz": vztah,
             "od": d_od, "ar": arid}).scalar()
        who = s.execute(_t(
            "SELECT COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),''), em.full_name) "
            "FROM tenant.att_employee em LEFT JOIN public.users u ON u.id=em.user_id WHERE em.id=:e"),
            {"e": emp}).scalar() or "Zaměstnanec"
        try:  # OČR z appky → rovnou do docházky (start den)
            _ocr_fill_dochazka(s, emp, d_od, d_od, uid, "OČR: " + (osoba or ""), "ocr_app")
        except Exception:
            pass
        msg = (who + " zahájil OČR (péče o: " + osoba + ") od "
               + str(d_od.day) + "." + str(d_od.month) + ". Po skončení doplní dny ke schválení.")
        _abs_notify(s, mgr if mgr and int(mgr) != uid else 1, "🧑‍⚕️ Nové ošetřovné (OČR)", msg)
        s.commit()
        return JSONResponse({"ok": True, "id": cid, "company": company})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/ocr/end")
async def ocr_end(req: Request) -> JSONResponse:
    """Zaměstnanec ukončuje OČR: datum do + počet dní ošetřování → ke schválení."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    import datetime as _dt
    try:
        b = await req.json()
    except Exception:
        b = {}
    try:
        cid = int((b or {}).get("id"))
    except Exception:
        return JSONResponse({"ok": False, "error": "Chybí id případu."})
    try:
        d_do = _dt.date.fromisoformat(str((b or {}).get("do") or "")[:10])
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatné datum do."})
    try:
        dny = int((b or {}).get("dny") or 0)
    except Exception:
        dny = 0
    cm, s = _att_session()
    try:
        row = s.execute(_t("SELECT employee_id, user_id, datum_od, absence_request_id, osoba_jmeno "
                           "FROM tenant.att_ocr_case WHERE id=:i AND tenant_id=2"), {"i": cid}).first()
        if not row:
            return JSONResponse({"ok": False, "error": "Případ nenalezen."})
        if int(row[1] or 0) != uid and not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "Není tvůj případ."}, status_code=403)
        if d_do < row[2]:
            return JSONResponse({"ok": False, "error": "Datum do je před datem od."})
        s.execute(_t("UPDATE tenant.att_ocr_case SET datum_do=:dd, dny_count=:dn, stav='ukonceno', "
                     "updated_at=now() WHERE id=:i"), {"dd": d_do, "dn": dny, "i": cid})
        if row[3]:
            s.execute(_t("UPDATE tenant.att_absence_request SET datum_do=:dd WHERE id=:a"),
                      {"dd": d_do, "a": row[3]})
        try:  # celý rozsah OČR do docházky (od..do)
            _ocr_fill_dochazka(s, row[0], row[2], d_do, row[1], "OČR: " + (row[4] or ""), "ocr_end")
        except Exception:
            pass
        mgr = None
        try:
            mgr = s.execute(_t("SELECT tenant.resolve_role(2, :e, 'attendance_supervisor')"),
                            {"e": row[0]}).scalar()
        except Exception:
            mgr = None
        msg = ("OČR (péče o: " + (row[4] or "") + ") ukončeno k " + str(d_do.day) + "." + str(d_do.month)
               + ". (" + str(dny) + " dní) — ke schválení v Docházce → OČR.")
        _abs_notify(s, mgr if mgr and int(mgr) != uid else 1, "🧑‍⚕️ OČR ke schválení", msg)
        s.commit()
        return JSONResponse({"ok": True})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


