# ── ČSSZ eOČR SMS most (Marti/Kristý 23.6.2026) ─────────────────────────────
# eOČR NECHODÍ do datovky → zaměstnanec přepošle ČSSZ SMS na číslo Marti-AI,
# brána ji zachytí (sms_preprocessor → cssz_ocr_dispatch) a TADY z ní založíme
# OČR případ: spárování odesílatel→zaměstnanec přes user_contacts, dohledání
# dítěte v osobní kartě (RČ se NIKDY neposílá po SMS — bere se z karty),
# auto-reply zaměstnanci + notifikace Péťě (18) a vedoucímu s ePortál odkazem.

_OCR_HR_USER = 18  # Péťa — zpracovává OČR (notifikace + ePortál link ke stažení)


def handle_cssz_ocr_sms(from_phone: str, body: str, extra: dict) -> dict:
    """Zpracuje přeposlanou ČSSZ eOČR SMS. Vrací {'matched': bool, 'summary': str}.

    matched=False → caller (store_inbound_sms) SMS uloží do inboxu, ať to vyřeší
    člověk. Sync funkce, volá se z store_inbound_sms (lazy import) v API procesu.
    """
    from sqlalchemy import text as _t
    import re as _re
    import datetime as _dt
    ident = (extra or {}).get("identifikator")
    osoba_sms = ((extra or {}).get("osoba") or "").strip() or None
    rok = (extra or {}).get("rok")
    link = (extra or {}).get("link")
    if not ident:
        return {"matched": False, "summary": "chybi identifikator"}
    # posledních 9 číslic odesílatele = robustní párování (formáty +420/420/0…)
    d9 = _re.sub(r"\D", "", from_phone or "")[-9:]
    if len(d9) < 9:
        return {"matched": False, "summary": "neplatne cislo odesilatele"}
    cid = None
    rc = None
    osoba = osoba_sms
    d_od = _dt.date.today()
    cm, s = _att_session()
    try:
        uid = s.execute(_t(
            "SELECT user_id FROM public.user_contacts "
            "WHERE contact_type='phone' AND COALESCE(status,'active')='active' "
            "AND right(regexp_replace(contact_value,'\\D','','g'),9)=:d9 "
            "ORDER BY COALESCE(is_verified,false) DESC, COALESCE(is_primary,false) DESC, id "
            "LIMIT 1"), {"d9": d9}).scalar()
        if not uid:
            return {"matched": False, "summary": "odesilatel nenalezen mezi zamestnanci"}
        uid = int(uid)
        emp = _att_employee(s, uid)
        if not emp:
            return {"matched": False, "summary": "neni v evidenci dochazky"}
        # ── UKONČENÍ vs VZNIK + dedup (Kristý/Claude-24 29.6.2026) ──
        # Ukončovací ČSSZ SMS má STEJNÝ identifikátor, ale text "ukonceni osetrovani"
        # (vznik = "vzniku osetrovani"). Když případ existuje: ukončení → doplň datum do
        # + konec-odkaz Péťě + potvrzení; duplicitní vznik → krátké potvrzení (pojistka).
        je_ukonceni = "ukonc" in (body or "").lower()
        exr = s.execute(_t(
            "SELECT id, absence_request_id, osoba_jmeno FROM tenant.att_ocr_case "
            "WHERE tenant_id=2 AND employee_id=:e AND identifikator=:id "
            "ORDER BY id DESC LIMIT 1"), {"e": emp, "id": ident}).first()
        if exr:
            ex_id, ex_ar = exr[0], exr[1]
            osoba = exr[2] or osoba
            who = s.execute(_t(
                "SELECT COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),''), em.full_name) "
                "FROM tenant.att_employee em LEFT JOIN public.users u ON u.id=em.user_id WHERE em.id=:e"),
                {"e": emp}).scalar() or "Zaměstnanec"
            mgr = None
            try:
                mgr = s.execute(_t("SELECT tenant.resolve_role(2, :e, 'attendance_supervisor')"),
                                {"e": emp}).scalar()
            except Exception:
                mgr = None
            if je_ukonceni:
                s.execute(_t("UPDATE tenant.att_ocr_case SET datum_do=:dd, cssz_link_konec=COALESCE(:lnk, cssz_link_konec), updated_at=now() WHERE id=:i"),
                          {"dd": d_od, "i": ex_id, "lnk": link})
                if ex_ar:
                    s.execute(_t("UPDATE tenant.att_absence_request SET datum_do=:dd WHERE id=:a"),
                              {"dd": d_od, "a": ex_ar})
                _note = (who + " nahlásil UKONČENÍ OČR (péče o: " + (osoba or "?") + ") k "
                         + str(d_od.day) + "." + str(d_od.month) + ". Identifikátor: " + ident + ". "
                         + ("Stáhni dokument ukončení z ePortálu: " + link if link else "")).strip()
                seen = set()
                for tgt in (_OCR_HR_USER, mgr):
                    try:
                        t_i = int(tgt) if tgt is not None else None
                    except Exception:
                        t_i = None
                    if t_i and t_i not in seen:
                        seen.add(t_i)
                        _abs_notify(s, t_i, "🧑‍⚕️ OČR — ukončení", _note)
                _rep = ("STRATEGIE: Zaznamenali jsme ukončení ošetřovného"
                        + ((" (péče o: " + osoba + ")") if osoba else "")
                        + " k " + str(d_od.day) + "." + str(d_od.month) + "."
                        + " Doplň prosím počet dní v appce: https://strategie-ai.com/mobile#ocr")
                _summary = "ukonceni zaznamenano (case " + str(ex_id) + ")"
            else:
                _rep = ("STRATEGIE: Toto ošetřovné už evidujeme"
                        + ((" (péče o: " + osoba + ")") if osoba else "")
                        + ". Není potřeba nic dalšího — po skončení potvrď dny v appce (Docházka → OČR).")
                _summary = "duplikat vzniku (case " + str(ex_id) + "), potvrzeno"
            s.commit()
            try:
                from modules.notifications.application.sms_service import queue_sms
                queue_sms(to=from_phone, body=_rep, purpose="ocr_autoreply",
                          user_id=uid, tenant_id=2, persona_id=1)
            except Exception:
                pass
            return {"matched": True, "summary": _summary}
        # dohledání dítěte v osobní kartě → RČ + vztah (RČ NIKDY po SMS)
        vztah = None
        try:
            if osoba_sms:
                like = osoba_sms.split()[0] + "%"
                params = {"u": uid, "nm": like}
                ysql = ""
                if rok:
                    ysql = "AND EXTRACT(YEAR FROM birth_date)=:yr "
                    params["yr"] = int(rok)
                ch = s.execute(_t(
                    "SELECT child_name, birth_number, relation FROM tenant.user_self_child "
                    "WHERE tenant_id=2 AND user_id=:u AND child_name ILIKE :nm "
                    + ysql + "ORDER BY id LIMIT 1"), params).first()
                if ch:
                    osoba = ch[0] or osoba_sms
                    rc = ch[1]
                    vztah = ch[2]
        except Exception:
            pass
        company = _ocr_company(s, emp)
        mgr = None
        try:
            mgr = s.execute(_t("SELECT tenant.resolve_role(2, :e, 'attendance_supervisor')"),
                            {"e": emp}).scalar()
        except Exception:
            mgr = None
        arid = s.execute(_t(
            "INSERT INTO tenant.att_absence_request (tenant_id,employee_id,user_id,typ,datum_od,"
            "datum_do,hours_per_day,note,stav,manager_user_id) "
            "VALUES (2,:e,:u,'family_care',:od,:od,8,:n,'pending',:m) RETURNING id"),
            {"e": emp, "u": uid, "od": d_od, "n": ("OČR (SMS): " + (osoba or "")), "m": mgr}).scalar()
        cid = s.execute(_t(
            "INSERT INTO tenant.att_ocr_case (tenant_id,employee_id,user_id,company,identifikator,"
            "osoba_jmeno,osoba_rc,osoba_vztah,datum_od,stav,absence_request_id,created_by_id,cssz_link) "
            "VALUES (2,:e,:u,:co,:id,:oj,:rc,:vz,:od,'novy',:ar,:u,:lnk) RETURNING id"),
            {"e": emp, "u": uid, "co": company, "id": ident, "oj": osoba, "rc": rc, "vz": vztah,
             "od": d_od, "ar": arid, "lnk": link}).scalar()
        who = s.execute(_t(
            "SELECT COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),''), em.full_name) "
            "FROM tenant.att_employee em LEFT JOIN public.users u ON u.id=em.user_id WHERE em.id=:e"),
            {"e": emp}).scalar() or "Zaměstnanec"
        try:  # OČR ze SMS → rovnou do docházky (start den; průběžné dny doplní _ocr_extend_active)
            _ocr_fill_dochazka(s, emp, d_od, d_od, uid, "OČR (SMS): " + (osoba or ""), "cssz_sms")
        except Exception:
            pass
        note = (who + " nahlásil OČR ze SMS (péče o: " + (osoba or "?") + "). "
                + "Identifikátor: " + ident + ". "
                + ("Otevři ePortál a stáhni dokument: " + link if link else "")).strip()
        seen = set()
        for tgt in (_OCR_HR_USER, mgr):
            try:
                t_i = int(tgt) if tgt is not None else None
            except Exception:
                t_i = None
            if t_i and t_i not in seen:
                seen.add(t_i)
                _abs_notify(s, t_i, "🧑‍⚕️ Nové OČR ze SMS", note)
        s.commit()
    except Exception:
        try:
            s.rollback()
        except Exception:
            pass
        raise
    finally:
        cm.__exit__(None, None, None)
    # auto-reply zaměstnanci (mimo att session) — potvrzení + odkaz do appky, BEZ RČ
    try:
        from modules.notifications.application.sms_service import queue_sms
        rep = ("STRATEGIE: Zachytili jsme oznámení o ošetřovném"
               + ((" (péče o: " + osoba + ")") if osoba else "")
               + ". Eviduji ti ho od " + str(d_od.day) + "." + str(d_od.month) + "."
               + " Po skončení potvrď dny v appce: https://strategie-ai.com/mobile#ocr"
               + " Mzdová účtárna dostala upozornění.")
        queue_sms(to=from_phone, body=rep, purpose="ocr_autoreply",
                  user_id=uid, tenant_id=2, persona_id=1)
    except Exception:
        pass
    return {"matched": True,
            "summary": "case " + str(cid) + " zalozen (emp " + str(emp) + ", rc=" + ("ano" if rc else "ne") + ")"}


# ── OČR formulář (ČSSZ Oznámení o potřebě ošetřování) — Fáze 1, Kristý 29.6. ──
# Klikací formulář v appce, předvyplněný z dat případu + identity zaměstnance.
# data = jsonb (additivně). Vlastník případu nebo HR.

@api_router.get("/app/ocr/form")
async def ocr_form_get(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        case_id = int(req.query_params.get("case") or 0)
    except Exception:
        case_id = 0
    cm, s = _att_session()
    try:
        c = s.execute(_t(
            "SELECT user_id, osoba_jmeno, osoba_rc, osoba_vztah, identifikator, "
            "to_char(datum_od,'YYYY-MM-DD'), to_char(datum_do,'YYYY-MM-DD'), cssz_link, cssz_link_konec "
            "FROM tenant.att_ocr_case WHERE id=:i AND tenant_id=2"), {"i": case_id}).first()
        if not c:
            return JSONResponse({"ok": False, "error": "Případ nenalezen."})
        if int(c[0] or 0) != uid and not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        u = s.execute(_t("SELECT first_name, last_name FROM public.users WHERE id=:u"),
                      {"u": c[0]}).first()
        zam_rc = s.execute(_t("SELECT birth_number FROM tenant.user_self_data "
                              "WHERE tenant_id=2 AND user_id=:u"), {"u": c[0]}).scalar() or ""
        prefill = {
            "zam_jmeno": (u[0] if u else "") or "",
            "zam_prijmeni": (u[1] if u else "") or "",
            "zam_rc": zam_rc or "",
            "os_jmeno": c[1] or "", "os_rc": c[2] or "", "os_vztah": c[3] or "",
            "cislo_rozhodnuti": c[4] or "", "datum_od": c[5] or "", "datum_do": c[6] or "",
        }
        row = s.execute(_t("SELECT data, stav FROM tenant.att_ocr_form "
                           "WHERE tenant_id=2 AND case_id=:i"), {"i": case_id}).first()
        data = dict(prefill)
        if row and row[0]:
            try:
                data.update(row[0])
            except Exception:
                pass
        return JSONResponse({"ok": True, "case_id": case_id, "prefill": prefill,
                             "data": data, "cssz_link": (c[7] or ""), "cssz_link_konec": (c[8] or ""),
                             "can_manage": bool(_hr_can_manage(s, uid)),
                             "stav": (row[1] if row else "rozpracovany")})
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/ocr/form/save")
async def ocr_form_save(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    import json as _j
    try:
        b = await req.json()
    except Exception:
        b = {}
    try:
        case_id = int((b or {}).get("case") or 0)
    except Exception:
        case_id = 0
    data = (b or {}).get("data") or {}
    if not isinstance(data, dict):
        data = {}
    stav = str((b or {}).get("stav") or "rozpracovany")[:30]
    cm, s = _att_session()
    try:
        c = s.execute(_t("SELECT user_id FROM tenant.att_ocr_case WHERE id=:i AND tenant_id=2"),
                      {"i": case_id}).first()
        if not c:
            return JSONResponse({"ok": False, "error": "Případ nenalezen."})
        if int(c[0] or 0) != uid and not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        s.execute(_t(
            "INSERT INTO tenant.att_ocr_form (tenant_id, case_id, data, stav, updated_by_user_id, updated_at) "
            "VALUES (2, :c, CAST(:d AS jsonb), :st, :u, now()) "
            "ON CONFLICT (tenant_id, case_id) DO UPDATE SET "
            "data=CAST(:d AS jsonb), stav=:st, updated_by_user_id=:u, updated_at=now()"),
            {"c": case_id, "d": _j.dumps(data, ensure_ascii=False), "st": stav, "u": uid})
        s.commit()
        return JSONResponse({"ok": True})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)[:160]}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/ocr/file")
async def ocr_file_upload(req: Request) -> JSONResponse:
    """Nahraje PDF/obrázek jako přílohu OČR případu. Vlastník případu nebo HR.
    JSON {case, kind, filename, file_b64} (base64) — funguje i v nativní appce
    přes bridge (na rozdíl od multipart, který v nativu nenese přihlášení).
    Soubor → public.documents (tenant 2) → naváže přes tenant.att_ocr_file."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    import base64 as _b64
    try:
        b = await req.json()
    except Exception:
        b = {}
    try:
        case = int((b or {}).get("case") or 0)
    except Exception:
        case = 0
    kind = (str((b or {}).get("kind") or "priloha").strip()[:20]) or "priloha"
    fname = (str((b or {}).get("filename") or "priloha.pdf").strip()) or "priloha.pdf"
    raw = (b or {}).get("file_b64") or ""
    if isinstance(raw, str) and raw[:5] == "data:" and "," in raw:
        raw = raw.split(",", 1)[1]
    try:
        content = _b64.b64decode(raw) if raw else b""
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatný soubor (base64)."})
    if not content:
        return JSONResponse({"ok": False, "error": "Prázdný soubor."})
    if len(content) > 25 * 1024 * 1024:
        return JSONResponse({"ok": False, "error": "Soubor je příliš velký (>25 MB)."})
    cm, s = _att_session()
    try:
        c = s.execute(_t("SELECT user_id FROM tenant.att_ocr_case WHERE id=:i AND tenant_id=2"),
                      {"i": case}).first()
        if not c:
            return JSONResponse({"ok": False, "error": "Případ nenalezen."})
        if int(c[0] or 0) != uid and not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        from modules.rag.application.service import upload_document as _upl
        doc_id = _upl(file_bytes=content, filename=fname, tenant_id=2, user_id=uid,
                      display_name="OČR příloha: " + fname[:150])
        s.execute(_t(
            "INSERT INTO tenant.att_ocr_file (tenant_id, case_id, document_id, kind, filename, uploaded_by_user_id) "
            "VALUES (2, :c, :d, :k, :fn, :u)"),
            {"c": case, "d": int(doc_id), "k": kind, "fn": fname[:200], "u": uid})
        s.commit()
        return JSONResponse({"ok": True, "document_id": int(doc_id), "filename": fname})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)[:160]}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


