@api_router.get("/app/hr/np-overview")
async def hr_np_overview(req: Request) -> JSONResponse:
    """HR přehled: kdo je a byl na OČR a nemocenské (UNION obou typů).
    ?active=1 → jen probíhající/ke schválení; jinak vše."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    active = str(req.query_params.get("active") or "") in ("1", "true", "yes")
    cm, s = _att_session()
    try:
        if not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        flt = "AND c.stav IN ('novy','trva','ukonceno')" if active else ""
        sql = (
            "SELECT kind, id, zamestnanec, osoba, company, datum_od, datum_do, stav, ref FROM ("
            "  SELECT 'ocr' AS kind, o.id, "
            "    COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),''), em.full_name) AS zamestnanec, "
            "    o.osoba_jmeno AS osoba, o.company, o.datum_od, o.datum_do, o.stav, o.identifikator AS ref "
            "  FROM tenant.att_ocr_case o "
            "  LEFT JOIN tenant.att_employee em ON em.id=o.employee_id "
            "  LEFT JOIN public.users u ON u.id=o.user_id WHERE o.tenant_id=2 "
            "  UNION ALL "
            "  SELECT 'sick' AS kind, sc.id, "
            "    COALESCE(NULLIF(TRIM(COALESCE(u2.first_name,'')||' '||COALESCE(u2.last_name,'')),''), em2.full_name) AS zamestnanec, "
            "    NULL AS osoba, sc.company, sc.datum_od, sc.datum_do, sc.stav, sc.cislo_dpn AS ref "
            "  FROM tenant.att_sick_case sc "
            "  LEFT JOIN tenant.att_employee em2 ON em2.id=sc.employee_id "
            "  LEFT JOIN public.users u2 ON u2.id=sc.user_id WHERE sc.tenant_id=2 "
            ") c WHERE 1=1 " + flt + " ORDER BY datum_od DESC NULLS LAST LIMIT 200"
        )
        rows = s.execute(_t(sql)).fetchall()
        out = [{"kind": r[0], "id": r[1], "zamestnanec": r[2], "osoba": r[3], "company": r[4],
                "od": r[5].isoformat() if r[5] else None, "do": r[6].isoformat() if r[6] else None,
                "stav": r[7], "ref": r[8]} for r in rows]
        return JSONResponse({"ok": True, "items": out})
    finally:
        cm.__exit__(None, None, None)


# ── Lísteček od lékaře — evidence návštěvy + foto + krytí sick day/lísteček ─

def _sick_balance_h(s, user_id):
    """Zůstatek sick day v hodinách = nárok (dní/rok × denní h) − vyčerpané (kryto_sick_h letos)."""
    from sqlalchemy import text as _t
    import datetime as _dt
    try:
        days = float(_resolve_cond_num(s, user_id, "sick_days_rok", 0.0) or 0.0)
    except Exception:
        days = 0.0
    try:
        week = float(_resolve_cond_num(s, user_id, "uvazek_h_tyden", 40.0) or 40.0)
    except Exception:
        week = 40.0
    daily = (week / 5.0) if week else 8.0
    entitlement = days * daily
    yr = _dt.date.today().year
    consumed = s.execute(_t(
        "SELECT COALESCE(SUM(kryto_sick_h),0) FROM tenant.att_med_note "
        "WHERE tenant_id=2 AND user_id=:u AND EXTRACT(YEAR FROM datum)=:y AND stav<>'zamitnuto'"),
        {"u": user_id, "y": yr}).scalar() or 0
    rem = entitlement - float(consumed)
    return {"entitlement_h": round(entitlement, 2), "consumed_h": round(float(consumed), 2),
            "remaining_h": round(max(0.0, rem), 2), "daily_h": round(daily, 2)}


def _med_limit_h(s, user_id):
    try:
        return float(_resolve_cond_num(s, user_id, "lekar_listecek_limit_h", 4.0) or 4.0)
    except Exception:
        return 4.0


def _hhmm_h(v):
    try:
        p = str(v).split(":"); return int(p[0]) + int(p[1]) / 60.0
    except Exception:
        return None


def _parse_dataurl(s_):
    """'data:image/jpeg;base64,xxxx' → (bytes, mime). Snese i holé base64."""
    import base64
    if not s_:
        return None, None
    mime = "image/jpeg"
    data = s_
    if str(s_).startswith("data:"):
        try:
            head, data = s_.split(",", 1)
            mime = head.split(";")[0].replace("data:", "") or mime
        except Exception:
            data = s_
    try:
        return base64.b64decode(data), mime
    except Exception:
        return None, None


