# Marti 12.6.: zaměstnanec vidí SVÉ resolvované podmínky (nefinanční — hranice Marti-AI Q8).
_MY_COND_CODES = ["uvazek_h_tyden", "nastup_max", "absence_nahlasit_do", "neplaceny_prescas_h_den",
                  "home_office_h", "sick_days_rok", "dovolena_dni", "stravenka_kc", "vikend_jen_schvaleni"]


@api_router.get("/app/my-conditions")
async def app_my_conditions(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        defrows = {r[0]: (r[1], r[2] or "") for r in s.execute(_t(
            "SELECT code,label,unit FROM tenant.staff_cond_def WHERE tenant_id=2 AND active=true")).fetchall()}
        grp = _cond_group_of(s, uid)
        glab = "—"
        if grp:
            glab = s.execute(_t("SELECT name FROM tenant.staff_group WHERE tenant_id=2 AND id=:g"),
                             {"g": int(grp)}).scalar() or "—"
        out = []
        for c in _MY_COND_CODES:
            if c not in defrows:
                continue
            val, src = _resolve_cond(s, uid, c, grp)
            if val is None:
                continue
            out.append({"code": c, "label": defrows[c][0], "unit": defrows[c][1], "value": val, "src": src})
        return JSONResponse({"ok": True, "skupina": glab, "podminky": out})
    finally:
        cm.__exit__(None, None, None)


_WD = [(1, "Pondělí"), (2, "Úterý"), (3, "Středa"), (4, "Čtvrtek"), (5, "Pátek"),
       (6, "Sobota"), (7, "Neděle")]


@api_router.get("/app/hr/schedule")
async def app_hr_schedule(req: Request) -> JSONResponse:
    """Vzor týdne (Marti 12.6.): které dny člověk pracuje + kolik h + volitelně pevný konec.
    Když nemá vlastní vzor, odvodí se z úvazku (Po–Pá rovnoměrně)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        tu = int(req.query_params.get("user_id") or 0)
    except Exception:
        tu = 0
    cm, s = _att_session()
    try:
        if not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        rowmap = {}
        for r in s.execute(_t("SELECT weekday,works,hours,to_char(end_time,'HH24:MI') FROM tenant.work_schedule "
                              "WHERE tenant_id=2 AND user_id=:u"), {"u": tu}).fetchall():
            rowmap[r[0]] = {"works": r[1], "hours": float(r[2]), "end_time": r[3]}
        uvazek = _resolve_cond_num(s, tu, "uvazek_h_tyden", 40.0)
        per_day = round(uvazek / 5.0, 2) if uvazek else 8.0
        dny = []
        for wd, label in _WD:
            if wd in rowmap:
                r = rowmap[wd]
                dny.append({"weekday": wd, "label": label, "works": bool(r["works"]),
                            "hours": r["hours"], "end_time": r["end_time"], "explicit": True})
            else:
                w = wd <= 5
                dny.append({"weekday": wd, "label": label, "works": w,
                            "hours": (per_day if w else 0.0), "end_time": None, "explicit": False})
        suma = round(sum(d["hours"] for d in dny if d["works"]), 2)
        return JSONResponse({"ok": True, "user_id": tu, "uvazek": uvazek, "dny": dny, "suma_h": suma})
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/learn/frames")
async def app_learn_frames(req: Request) -> JSONResponse:
    """Výukové framy Ano/Možná/Ne + glosář (zdroj MP_STRAG_Komun + elektro rozváděče).
    Neinvazivní výuka po vzoru Hubbarda (3 bariéry). Marti 17.6.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    src = (req.query_params.get("source") or "").strip()
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        q = ("SELECT id, source, source_id, tema, typ, poradi, parent_source_id, "
             "caption, description_html, question "
             "FROM tenant.learn_frame WHERE tenant_id=2 AND aktivni=true")
        params = {}
        if src:
            q += " AND source=:src"
            params["src"] = src
        q += " ORDER BY source, tema, typ, poradi, source_id"
        frames = []
        for r in s.execute(_t(q), params).fetchall():
            frames.append({"id": r[0], "source": r[1], "source_id": r[2], "tema": r[3],
                           "typ": r[4], "poradi": r[5], "parent": r[6],
                           "caption": r[7] or "", "description_html": r[8] or "",
                           "question": r[9] or "", "media": []})
        fmap = {f["id"]: f for f in frames}
        for r in s.execute(_t("SELECT frame_id, kind, url, caption FROM tenant.learn_media "
                              "WHERE tenant_id=2 ORDER BY frame_id, poradi")).fetchall():
            if r[0] in fmap:
                fmap[r[0]]["media"].append({"kind": r[1], "url": r[2], "caption": r[3] or ""})
        glos = [{"term": r[0], "definition_html": r[1] or ""}
                for r in s.execute(_t("SELECT term, definition_html FROM tenant.learn_glossary "
                                      "WHERE tenant_id=2 ORDER BY term")).fetchall()]
        return JSONResponse({"ok": True, "frames": frames, "glossary": glos})
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/hr/send-activation")
async def app_hr_send_activation(req: Request) -> JSONResponse:
    """Pošle aktivační (pozvánkový) e-mail pending uživateli — onboarding z HR/appky.
    Parent/HR only. Nezávislé na e-mailovém loginu (appka jede přes sms-login).
    Vytvoří reset token (allow_pending) + zařadí mail do outboxu. Marti 17.6.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        body = {}
    target = body.get("user_id")
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        if not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        if not target:
            return JSONResponse({"ok": False, "error": "missing_user_id"}, status_code=400)
        row = s.execute(_t(
            "SELECT u.first_name, u.gender, u.status, "
            "(SELECT c.contact_value FROM public.user_contacts c "
            " WHERE c.user_id=u.id AND c.contact_type='email' AND c.status='active' "
            " ORDER BY c.is_primary DESC, c.id LIMIT 1) AS email "
            "FROM public.users u WHERE u.id=:u"), {"u": int(target)}).first()
    finally:
        cm.__exit__(None, None, None)
    if not row:
        return JSONResponse({"ok": False, "error": "user_not_found"}, status_code=404)
    first_name, gender, status, email = row[0], row[1], row[2], row[3]
    if not email:
        return JSONResponse({"ok": False, "error": "no_email",
                             "message": "Uživatel nemá aktivní e-mailový kontakt — doplň ho a zkus znovu."},
                            status_code=400)
    from modules.auth.application.password_reset_service import create_reset_token
    from modules.notifications.application.email_service import send_activation_email, send_password_reset_email
    res = create_reset_token(email, allow_pending=True)
    if not res:
        return JSONResponse({"ok": False, "error": "no_token",
                             "message": "Token se nepodařilo vytvořit (uživatel není pending ani active?)."},
                            status_code=400)
    tok, t_uid, t_fname = res
    try:
        if status == "pending":
            sent = bool(send_activation_email(to=email, token=tok, first_name=t_fname, gender=gender))
        else:
            sent = bool(send_password_reset_email(to=email, token=tok, first_name=t_fname, gender=gender))
    except Exception as exc:
        return JSONResponse({"ok": False, "error": "send_failed", "message": str(exc)[:160]}, status_code=500)
    return JSONResponse({"ok": True, "to_email": email, "sent": sent, "status": status})


def _rtf_to_html(rtf):
    """Jednoduchý RTF -> HTML (pro MP_STRAG_Komun). Decoduje \\uN a \\'XX (cp1250),
    \\par -> odstavec, ignoruje font/color/list tabulky. Marti 17.6.2026."""
    import re as _re
    if not rtf:
        return ""
    if "\\rtf" not in rtf[:20]:
        t = rtf.strip()
        esc = t.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        return "".join("<p>" + p.strip() + "</p>" for p in esc.split("\n") if p.strip())
    ign = {"fonttbl", "colortbl", "stylesheet", "listtable", "listoverridetable", "info",
           "generator", "pict", "object", "themedata", "colorschememapping", "latentstyles",
           "datastore", "pntext", "pntxta", "pntxtb", "listtext", "xmlnstbl", "filetbl", "revtbl"}
    buf = []
    stack = [{"ig": False}]
    i = 0
    n = len(rtf)
    while i < n:
        c = rtf[i]
        if c == "{":
            stack.append(dict(stack[-1]))
            i += 1
            continue
        if c == "}":
            if len(stack) > 1:
                stack.pop()
            i += 1
            continue
        if c == "\\":
            m = _re.match(r"\\([a-zA-Z]+)(-?\d+)? ?", rtf[i:])
            if m:
                w = m.group(1)
                a = m.group(2)
                i += m.end()
                if w == "u":
                    if not stack[-1]["ig"]:
                        try:
                            buf.append(chr(int(a)))
                        except Exception:
                            pass
                    if rtf[i:i + 2] == "\\'":
                        i += 4
                    elif i < n and rtf[i] not in "\\{}":
                        i += 1
                elif w in ("par", "line"):
                    if not stack[-1]["ig"]:
                        buf.append("\n")
                elif w == "tab":
                    if not stack[-1]["ig"]:
                        buf.append(" ")
                elif w in ign:
                    stack[-1]["ig"] = True
                continue
            two = rtf[i:i + 2]
            if two == "\\'":
                hx = rtf[i + 2:i + 4]
                i += 4
                if not stack[-1]["ig"]:
                    try:
                        buf.append(bytes([int(hx, 16)]).decode("cp1250"))
                    except Exception:
                        pass
                continue
            if two in ("\\\\", "\\{", "\\}"):
                if not stack[-1]["ig"]:
                    buf.append(two[1])
                i += 2
                continue
            if two == "\\*":
                stack[-1]["ig"] = True
                i += 2
                continue
            i += 1
            continue
        if not stack[-1]["ig"]:
            buf.append(c)
        i += 1
    txt = "".join(buf)
    paras = [p.strip() for p in txt.split("\n") if p.strip()]
    esc = lambda x: x.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    return "".join("<p>" + esc(p) + "</p>" for p in paras)


def _learn_term_of(cap):
    t = (cap or "").strip()
    for pref in ("Co to jsou ", "Co to je ", "Kdo to je ", "Kdo je ", "Kdo byl "):
        if t.lower().startswith(pref.lower()):
            t = t[len(pref):]
            break
    return t.rstrip("? ").strip()


@api_router.get("/app/flow")
def app_flow(req: Request, section: str = "", cz: str = "") -> JSONResponse:
    """Read-only 'Stav zakazek' board nad DB_EC (Centrala) - Marti 17.6.2026.
    Faze odvozena z existence ZL / vyroby / zkusebny / faktury (vse pres CisloZakazky).
    Typ VR/SW/PR z prefixu cisla zakazky. Zaseknute: po zkusebne nefakturovano; fakturovano neuzavreno.
    NIC nezapisuje do Centraly (jen cte pres eurosoft_strategie_query_raw)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    import json as _j
    cm, s = _att_session()
    try:
        isp = s.execute(_t("SELECT COALESCE(is_marti_parent,false) FROM public.users WHERE id=:u"),
                        {"u": int(uid)}).scalar()
    finally:
        try:
            cm.__exit__(None, None, None)
        except Exception:
            pass
    # rodič / ambasador / vedoucí výroby (Dušan 41, Marek 85, Michaela 16)
    if not isp and not _is_ambassador(uid) and int(uid) not in (16, 41, 85):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return JSONResponse({"ok": False, "error": "mcp_unavailable"}, status_code=503)

    def _q(sql):
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _j.loads(raw) if isinstance(raw, str) else raw
        rows = []
        if isinstance(r, dict):
            if r.get("ok") is False:
                raise RuntimeError(str(r.get("error"))[:200])
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    rows = r[k]
                    break
        elif isinstance(r, list):
            rows = r
        return [{(k or "").lower(): v for k, v in d.items()} for d in rows]

    _typ = ("CASE WHEN z.CisloZakazky LIKE 'VR%' THEN 'VR' WHEN z.CisloZakazky LIKE 'SW%' THEN 'SW' "
            "WHEN z.CisloZakazky LIKE 'PR%' THEN 'PR' ELSE 'OST' END")
    stages_sql = (
        "SELECT typ, faza, COUNT(*) AS pocet FROM ("
        " SELECT " + _typ + " AS typ,"
        " CASE WHEN f.c>0 THEN '6_fakt' WHEN zk.c>0 THEN '5_zkus' WHEN v.c>0 THEN '4_vyr'"
        " WHEN zl.c>0 THEN '3_zl' ELSE '2_bezzl' END AS faza"
        " FROM DB_EC.dbo.TabZakazka z WITH(NOLOCK)"
        " OUTER APPLY (SELECT COUNT(*) c FROM DB_EC.dbo.EC_ZakListy WITH(NOLOCK) WHERE CisloZakazky=z.CisloZakazky) zl"
        " OUTER APPLY (SELECT COUNT(*) c FROM DB_EC.dbo.EC_PlanovaniVyroby WITH(NOLOCK) WHERE CisloZakazky=z.CisloZakazky) v"
        " OUTER APPLY (SELECT COUNT(*) c FROM DB_EC.dbo.EC_ZkusebniProtokoly WITH(NOLOCK) WHERE CisloZakazky=z.CisloZakazky) zk"
        " OUTER APPLY (SELECT COUNT(*) c FROM DB_EC.dbo.TabDokladyZbozi fa WITH(NOLOCK)"
        "   WHERE fa.CisloZakazky=z.CisloZakazky AND fa.DruhPohybuZbo BETWEEN 13 AND 14 AND fa.IDSklad IS NULL) f"
        " WHERE z.Ukonceno=0"
        ") q GROUP BY typ, faza"
    )
    funnel_sql = (
        "SELECT RadaDokladu AS rada, COUNT(*) AS pocet,"
        " SUM(CASE WHEN Splneno=1 THEN 1 ELSE 0 END) AS splneno"
        " FROM DB_EC.dbo.TabDokladyZbozi WITH(NOLOCK)"
        " WHERE RadaDokladu IN ('900','910','920') AND DatPorizeni >= '2024-01-01'"
        " GROUP BY RadaDokladu"
    )
    nefakt_sql = (
        "SELECT TOP 150 " + _typ + " AS typ, z.CisloZakazky AS cz, z.Nazev AS nazev,"
        " CONVERT(varchar,(SELECT MAX(DatumVyroby) FROM DB_EC.dbo.EC_ZkusebniProtokoly WITH(NOLOCK)"
        "   WHERE CisloZakazky=z.CisloZakazky),104) AS dat,"
        " DATEDIFF(day,(SELECT MAX(DatumVyroby) FROM DB_EC.dbo.EC_ZkusebniProtokoly WITH(NOLOCK)"
        "   WHERE CisloZakazky=z.CisloZakazky),GETDATE()) AS dni"
        " FROM DB_EC.dbo.TabZakazka z WITH(NOLOCK)"
        " WHERE z.Ukonceno=0"
        " AND EXISTS (SELECT 1 FROM DB_EC.dbo.EC_ZkusebniProtokoly WITH(NOLOCK) WHERE CisloZakazky=z.CisloZakazky)"
        " AND NOT EXISTS (SELECT 1 FROM DB_EC.dbo.TabDokladyZbozi fa WITH(NOLOCK)"
        "   WHERE fa.CisloZakazky=z.CisloZakazky AND fa.DruhPohybuZbo BETWEEN 13 AND 14 AND fa.IDSklad IS NULL)"
        " ORDER BY (SELECT MAX(DatumVyroby) FROM DB_EC.dbo.EC_ZkusebniProtokoly WITH(NOLOCK) WHERE CisloZakazky=z.CisloZakazky) ASC"
    )
    neuzavr_sql = (
        "SELECT TOP 150 " + _typ + " AS typ, z.CisloZakazky AS cz, z.Nazev AS nazev,"
        " CONVERT(varchar,(SELECT MAX(DatPorizeni) FROM DB_EC.dbo.TabDokladyZbozi fa WITH(NOLOCK)"
        "   WHERE fa.CisloZakazky=z.CisloZakazky AND fa.DruhPohybuZbo BETWEEN 13 AND 14 AND fa.IDSklad IS NULL),104) AS dat,"
        " DATEDIFF(day,(SELECT MAX(DatPorizeni) FROM DB_EC.dbo.TabDokladyZbozi fa WITH(NOLOCK)"
        "   WHERE fa.CisloZakazky=z.CisloZakazky AND fa.DruhPohybuZbo BETWEEN 13 AND 14 AND fa.IDSklad IS NULL),GETDATE()) AS dni,"
        " CAST((SELECT SUM(fa.SumaKcBezDPH) FROM DB_EC.dbo.TabDokladyZbozi fa WITH(NOLOCK)"
        "   WHERE fa.CisloZakazky=z.CisloZakazky AND fa.DruhPohybuZbo BETWEEN 13 AND 14 AND fa.IDSklad IS NULL) AS bigint) AS kc"
        " FROM DB_EC.dbo.TabZakazka z WITH(NOLOCK)"
        " WHERE z.Ukonceno=0"
        " AND EXISTS (SELECT 1 FROM DB_EC.dbo.TabDokladyZbozi fa WITH(NOLOCK)"
        "   WHERE fa.CisloZakazky=z.CisloZakazky AND fa.DruhPohybuZbo BETWEEN 13 AND 14 AND fa.IDSklad IS NULL)"
        " ORDER BY (SELECT MAX(DatPorizeni) FROM DB_EC.dbo.TabDokladyZbozi fa WITH(NOLOCK)"
        "   WHERE fa.CisloZakazky=z.CisloZakazky AND fa.DruhPohybuZbo BETWEEN 13 AND 14 AND fa.IDSklad IS NULL) ASC"
    )
    material_sql = (
        "SELECT TOP 150 d.CisloZakazky AS cz, ISNULL(o.Nazev,'') AS dodavatel,"
        " CONVERT(varchar,d.TerminDodavkyDat,104) AS termin,"
        " DATEDIFF(day,d.TerminDodavkyDat,GETDATE()) AS dni,"
        " CONVERT(varchar,d.PoradoveCislo) AS doklad"
        " FROM DB_EC.dbo.TabDokladyZbozi d WITH(NOLOCK)"
        " LEFT OUTER JOIN DB_EC.dbo.TabCisOrg o WITH(NOLOCK) ON d.CisloOrg=o.CisloOrg"
        " WHERE d.RadaDokladu='800' AND d.IDSklad='001'"
        " AND ISNULL(d.Splneno,0)=0 AND d.TerminDodavkyDat IS NOT NULL AND d.TerminDodavkyDat < GETDATE()"
        " ORDER BY d.TerminDodavkyDat ASC"
    )
    souhrn_sql = (
        "SELECT CAST(ISNULL(SUM(t.kc),0) AS bigint) AS kc_neuzavr, COUNT(*) AS pocet_neuzavr FROM ("
        " SELECT (SELECT SUM(fa.SumaKcBezDPH) FROM DB_EC.dbo.TabDokladyZbozi fa WITH(NOLOCK)"
        "   WHERE fa.CisloZakazky=z.CisloZakazky AND fa.DruhPohybuZbo BETWEEN 13 AND 14 AND fa.IDSklad IS NULL) AS kc"
        " FROM DB_EC.dbo.TabZakazka z WITH(NOLOCK)"
        " WHERE z.Ukonceno=0 AND EXISTS (SELECT 1 FROM DB_EC.dbo.TabDokladyZbozi fa WITH(NOLOCK)"
        "   WHERE fa.CisloZakazky=z.CisloZakazky AND fa.DruhPohybuZbo BETWEEN 13 AND 14 AND fa.IDSklad IS NULL)"
        ") t"
    )
    jednani_sql = (
        "SELECT TOP 120 CONVERT(varchar,a.DatumAkce,104) AS dat,"
        " ISNULL(cis.Nazev,'') AS akce,"
        " ISNULL(a.FirmaText,'') AS firma,"
        " LTRIM(RTRIM(ISNULL(a.Prijmeni,'')+' '+ISNULL(a.Jmeno,''))) AS osoba,"
        " LEFT(REPLACE(REPLACE(ISNULL(a.Popis,a.Prubeh),CHAR(13),' '),CHAR(10),' '),140) AS popis,"
        " ISNULL(a.Autor,'') AS autor,"
        " CONVERT(int,ISNULL(a.Splneno,0)) AS splneno"
        " FROM DB_EC.dbo.CRM_Kontakt_Akce a WITH(NOLOCK)"
        " LEFT OUTER JOIN DB_EC.dbo.CRM_Kontakt_AkceCis cis WITH(NOLOCK) ON cis.ID=a.IDAkce"
        " WHERE a.DatumAkce >= DATEADD(month,-3,GETDATE())"
        " ORDER BY a.DatumAkce DESC"
    )
    vyroba_sql = (
        "SELECT TOP 150 CisloZakazky AS cz, CONVERT(varchar,MIN(DatumOd),104) AS od,"
        " CONVERT(varchar,MAX(DatumDo),104) AS dodatum,"
        " CASE WHEN MIN(DatumOd)>GETDATE() THEN 'naplanovano' WHEN MAX(DatumDo)<GETDATE() THEN 'po terminu' ELSE 'probiha' END AS stav"
        " FROM DB_EC.dbo.EC_PlanovaniVyroby WITH(NOLOCK)"
        " WHERE DatumDo >= DATEADD(day,-30,GETDATE())"
        " GROUP BY CisloZakazky ORDER BY MIN(DatumOd) ASC"
    )
    zkusebna_sql = (
        "SELECT TOP 150 CisloZakazky AS cz, CONVERT(varchar,DatumVyroby,104) AS dat,"
        " DATEDIFF(day,DatumVyroby,GETDATE()) AS dni"
        " FROM DB_EC.dbo.EC_ZkusebniProtokoly WITH(NOLOCK)"
        " WHERE DatumVyroby >= DATEADD(month,-3,GETDATE())"
        " ORDER BY DatumVyroby DESC"
    )
    odvozy_sql = (
        "SELECT TOP 150 CisloZakazky AS cz, ISNULL(NazevZakazkyTisk,'') AS nazev,"
        " CONVERT(varchar,DatumOdvozu,104) AS odvoz, CONVERT(varchar,DatumOdvezeni,104) AS odvezeno,"
        " ISNULL(DopravceKontakt,'') AS dopravce"
        " FROM DB_EC.dbo.EC_DopravaZakaznikovi WITH(NOLOCK)"
        " WHERE ISNULL(DatumOdvozu,DatumOdvezeni) >= DATEADD(month,-3,GETDATE())"
        " ORDER BY ISNULL(DatumOdvozu,DatumOdvezeni) DESC"
    )
    faktstav_sql = (
        "SELECT ISNULL(NULLIF(LTRIM(RTRIM(StavFakturace)),''),'(bez stavu)') AS stav, COUNT(*) AS pocet"
        " FROM DB_EC.dbo.EC_Zakazky_KontrolaFakturace WITH(NOLOCK) GROUP BY StavFakturace"
    )
    faktchybi_sql = (
        "SELECT TOP 200 CisloZakazky AS cz, ISNULL(NazevZakazky,'') AS nazev, ISNULL(Zakaznik,'') AS zakaznik,"
        " CONVERT(varchar,DatumPorizeni,104) AS dat"
        " FROM DB_EC.dbo.EC_Zakazky_KontrolaFakturace WITH(NOLOCK)"
        " WHERE LTRIM(RTRIM(StavFakturace))='Chybi faktury' OR LTRIM(RTRIM(StavFakturace))=N'Chybí faktury'"
        " ORDER BY DatumPorizeni DESC"
    )
    priprava_sql = (
        "SELECT TOP 150 CONVERT(varchar,ISNULL(d.DatSplneni,d.DatRealizace),104) AS dat,"
        " ISNULL(o.Nazev,'') AS dodavatel,"
        " CONVERT(varchar,d.PoradoveCislo) AS doklad,"
        " ISNULL(STUFF((SELECT DISTINCT ', '+CAST(PP.CisloZakazky AS varchar(max))"
        "   FROM DB_EC.dbo.TabPohybyZbozi PP WITH(NOLOCK)"
        "   WHERE PP.IDDoklad=d.ID AND PP.CisloZakazky IS NOT NULL AND PP.CisloZakazky<>'' FOR XML PATH('')),1,2,''),'') AS zakazky"
        " FROM DB_EC.dbo.TabDokladyZbozi d WITH(NOLOCK)"
        " LEFT OUTER JOIN DB_EC.dbo.TabCisOrg o WITH(NOLOCK) ON d.CisloOrg=o.CisloOrg"
        " WHERE d.RadaDokladu='800' AND d.IDSklad='001' AND ISNULL(d.Splneno,0)=1"
        " AND ISNULL(d.DatSplneni,d.DatRealizace) >= DATEADD(day,-45,GETDATE())"
        " ORDER BY ISNULL(d.DatSplneni,d.DatRealizace) DESC"
    )
    vyhodnoceni_sql = (
        "SELECT TOP 100 LTRIM(RTRIM(ISNULL(Prijmeni,'')+' '+ISNULL(Jmeno,''))) AS osoba,"
        " Efektivita AS efektivita, PocetProjektu AS projekty, CAST(PocetHodinProZak AS int) AS hodiny"
        " FROM DB_EC.dbo.EC_Vytizeni_Efektivita WITH(NOLOCK)"
        " WHERE Efektivita IS NOT NULL ORDER BY Efektivita DESC"
    )
    zl_sql = (
        "SELECT TOP 200"
        " CASE WHEN zl.CisloZakazky LIKE 'VR%' THEN 'VR' WHEN zl.CisloZakazky LIKE 'SW%' THEN 'SW'"
        "   WHEN zl.CisloZakazky LIKE 'PR%' THEN 'PR' ELSE 'OST' END AS typ,"
        " zl.CisloZakazky AS cz, ISNULL(z.Nazev,'') AS nazev, zl.PocetHodin AS hodiny,"
        " CONVERT(int,ISNULL(zl.KompletniObjednani,0)) AS objednano,"
        " CONVERT(varchar,zl.TerminDodaniMaterialu,104) AS termat,"
        " CONVERT(varchar,zl.TerminDoruceniKZak,104) AS termzak,"
        " DATEDIFF(day,GETDATE(),zl.TerminDoruceniKZak) AS dnydozak"
        " FROM DB_EC.dbo.EC_ZakListy zl WITH(NOLOCK)"
        " JOIN DB_EC.dbo.TabZakazka z WITH(NOLOCK) ON z.CisloZakazky=zl.CisloZakazky"
        " WHERE z.Ukonceno=0"
        " ORDER BY zl.TerminDoruceniKZak ASC"
    )
    # Casova osa: okno vyroby = MIN/MAX planovaneho dne monteru (EC_Vytizeni_PlanMonteri, ZIVE),
    # kalkulovane hodiny ze ZL + planovane hodiny + pocet lidi + terminy material/k zakaznikovi + zkusebna/odvoz.
    timeline_sql = (
        "SELECT TOP 300"
        " CASE WHEN z.CisloZakazky LIKE 'VR%' THEN 'VR' WHEN z.CisloZakazky LIKE 'SW%' THEN 'SW'"
        "   WHEN z.CisloZakazky LIKE 'PR%' THEN 'PR' ELSE 'OST' END AS typ,"
        " z.CisloZakazky AS cz, ISNULL(z.Nazev,'') AS nazev,"
        " CONVERT(varchar(10),pm.od,23) AS vyr_od, CONVERT(varchar(10),pm.do2,23) AS vyr_do,"
        " ISNULL(pm.lidi,0) AS lidi, ISNULL(pm.planhod,0) AS planhod, ISNULL(zl.hod,0) AS kalkhod,"
        " CONVERT(varchar(10),zl.term_mat,23) AS term_mat, CONVERT(varchar(10),zl.term_zak,23) AS term_zak,"
        " CONVERT(varchar(10),zk.dat,23) AS zkusebna, CONVERT(varchar(10),od.dat,23) AS odvoz"
        " FROM DB_EC.dbo.TabZakazka z WITH(NOLOCK)"
        " OUTER APPLY (SELECT MIN(Datum) od, MAX(Datum) do2, COUNT(DISTINCT CisloZam) lidi, SUM(PocetHodin) planhod FROM DB_EC.dbo.EC_Vytizeni_PlanMonteri WITH(NOLOCK) WHERE CisloZakazky=z.CisloZakazky) pm"
        " OUTER APPLY (SELECT PocetHodin hod, TerminDodaniMaterialu term_mat, TerminDoruceniKZak term_zak FROM DB_EC.dbo.EC_ZakListy WITH(NOLOCK) WHERE CisloZakazky=z.CisloZakazky) zl"
        " OUTER APPLY (SELECT MAX(DatumVyroby) dat FROM DB_EC.dbo.EC_ZkusebniProtokoly WITH(NOLOCK) WHERE CisloZakazky=z.CisloZakazky) zk"
        " OUTER APPLY (SELECT MAX(ISNULL(DatumOdvezeni,DatumOdvozu)) dat FROM DB_EC.dbo.EC_DopravaZakaznikovi WITH(NOLOCK) WHERE CisloZakazky=z.CisloZakazky) od"
        " WHERE z.Ukonceno=0 AND (pm.od IS NOT NULL OR zl.term_zak IS NOT NULL OR zk.dat IS NOT NULL)"
        " ORDER BY ISNULL(pm.od, ISNULL(zl.term_zak, zk.dat)) ASC"
    )
    # Detail jedne zakazky: kdo je naplanovany, jeho usek a hodiny (planovani lidi do useku vyroby).
    czf = (cz or "").strip().replace("'", "")[:40]
    # detail po jednotlivych dnech (segmenty dle realne naplanovane dochazky)
    timeline_det_sql = (
        "SELECT pm.CisloZam AS cislo,"
        " RTRIM(ISNULL(za.Jmeno,''))+' '+RTRIM(ISNULL(za.Prijmeni,'')) AS jmeno,"
        " CONVERT(varchar(10),pm.Datum,23) AS den,"
        " SUM(pm.PocetHodin) AS hod"
        " FROM DB_EC.dbo.EC_Vytizeni_PlanMonteri pm WITH(NOLOCK)"
        " LEFT JOIN DB_EC.dbo.TabCisZam za WITH(NOLOCK) ON za.Cislo=pm.CisloZam"
        " WHERE pm.CisloZakazky=N'" + czf + "'"
        " GROUP BY pm.CisloZam, za.Jmeno, za.Prijmeni, pm.Datum"
        " ORDER BY pm.CisloZam, pm.Datum ASC"
    )
    import datetime as _dt
    out = {"ok": True, "generated": _dt.datetime.now().strftime("%d.%m.%Y %H:%M")}
    sec = (section or "").strip().lower()
    try:
        if sec in ("", "core", "analyza", "vp", "nakup"):
            out["stages"] = _q(stages_sql)
            out["funnel"] = _q(funnel_sql)
            out["nefakturovano"] = _q(nefakt_sql)
            out["neuzavreno"] = _q(neuzavr_sql)
            out["material_po_terminu"] = _q(material_sql)
            sr = _q(souhrn_sql)
            out["souhrn"] = sr[0] if sr else {}
        elif sec == "obchod":
            out["jednani"] = _q(jednani_sql)
        elif sec == "vyroba":
            out["vyroba"] = _q(vyroba_sql)
        elif sec == "zkusebna":
            out["zkusebna"] = _q(zkusebna_sql)
        elif sec == "odvozy":
            out["odvozy"] = _q(odvozy_sql)
        elif sec == "fakturace":
            out["fakt_stav"] = _q(faktstav_sql)
            out["fakt_chybi"] = _q(faktchybi_sql)
        elif sec == "priprava":
            out["priprava"] = _q(priprava_sql)
        elif sec == "vyhodnoceni":
            out["vyhodnoceni"] = _q(vyhodnoceni_sql)
        elif sec == "zl":
            out["zl"] = _q(zl_sql)
        elif sec == "vytizeni":
            # Vytížení montérů (Dušan): požadavek (plán zakázek) vs kapacita
            # (naplánovaná docházka Výroby) — Marti 18.6. „z naší docházky".
            try:
                out["dem"] = _q("SELECT CONVERT(varchar(10),Datum,23) AS d, SUM(PocetHodin) AS h"
                                " FROM DB_EC.dbo.EC_Vytizeni_PlanMonteri WITH(NOLOCK)"
                                " WHERE Datum>='2026-01-01' GROUP BY Datum ORDER BY Datum")
                cap = []
                cm2, s2 = _att_session()
                try:
                    rs = s2.execute(_t(
                        "SELECT pe.plan_date::text AS d, SUM(pe.expected_hours) AS h"
                        " FROM tenant.att_plan_effective pe"
                        " WHERE pe.tenant_id=2 AND pe.user_id IN ("
                        "   SELECT m.user_id FROM tenant.staff_group_member m"
                        "   WHERE m.tenant_id=2 AND m.group_id=3"
                        "   AND m.user_id NOT IN (SELECT user_id FROM tenant.vyroba_plan_excl WHERE tenant_id=2))"
                        " GROUP BY pe.plan_date ORDER BY pe.plan_date")).fetchall()
                    cap = [{"d": row[0], "h": float(row[1] or 0)} for row in rs]
                finally:
                    try:
                        cm2.__exit__(None, None, None)
                    except Exception:
                        pass
                out["cap"] = cap
            except Exception:
                out["cap"] = []; out["dem"] = []
        elif sec == "timeline":
            if czf:
                out["lide"] = _q(timeline_det_sql)
            else:
                out["timeline"] = _q(timeline_sql)
                # Dve krivky: kapacita (naplanovana dochazka monteru) vs pozadavek (plan zakazek)
                try:
                    out["dem"] = _q("SELECT CONVERT(varchar(10),Datum,23) AS d, SUM(PocetHodin) AS h"
                                    " FROM DB_EC.dbo.EC_Vytizeni_PlanMonteri WITH(NOLOCK)"
                                    " WHERE Datum>='2026-01-01' GROUP BY Datum ORDER BY Datum")
                    # kapacita = naplanovana dochazka podskupiny "Vyroba" zarazene do planovani (mimo vyjmute)
                    cap = []
                    cm2, s2 = _att_session()
                    try:
                        rs = s2.execute(_t(
                            "SELECT pe.plan_date::text AS d, SUM(pe.expected_hours) AS h"
                            " FROM tenant.att_plan_effective pe"
                            " WHERE pe.tenant_id=2 AND pe.user_id IN ("
                            "   SELECT m.user_id FROM tenant.staff_group_member m"
                            "   WHERE m.tenant_id=2 AND m.group_id=3"
                            "   AND m.user_id NOT IN (SELECT user_id FROM tenant.vyroba_plan_excl WHERE tenant_id=2))"
                            # odečíst plánované volno: kdo má ten den naplánovanou nepřítomnost, nepočítá se do kapacity
                            "   AND NOT EXISTS (SELECT 1 FROM tenant.att_planned_absence pa"
                            "     WHERE pa.tenant_id=2 AND pa.user_id=pe.user_id AND pa.datum=pe.plan_date)"
                            " GROUP BY pe.plan_date ORDER BY pe.plan_date")).fetchall()
                        cap = [{"d": row[0], "h": float(row[1] or 0)} for row in rs]
                    finally:
                        try:
                            cm2.__exit__(None, None, None)
                        except Exception:
                            pass
                    out["cap"] = cap
                except Exception as _e:
                    out["cap"] = []; out["dem"] = []
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:200]}, status_code=502)
    return JSONResponse(out)


def _flow_people_gate(req: Request):
    """Parent NEBO vedoucí výroby (41/85) NEBO Michaela (16). Vrací uid nebo None."""
