@api_router.get("/app/flow/people")
def app_flow_people(req: Request) -> JSONResponse:
    """Lidé skupiny Výroba (group_id=3) + příznak, zda jsou v podskupině plánování."""
    uid = _flow_people_gate(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        rows = s.execute(_t(
            "SELECT m.user_id AS uid,"
            " RTRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')) AS jmeno,"
            " (x.user_id IS NULL) AS included"
            " FROM tenant.staff_group_member m"
            " LEFT JOIN public.users u ON u.id=m.user_id"
            " LEFT JOIN tenant.vyroba_plan_excl x ON x.tenant_id=2 AND x.user_id=m.user_id"
            " WHERE m.tenant_id=2 AND m.group_id=3"
            " ORDER BY jmeno")).fetchall()
        ppl = [{"uid": r[0], "jmeno": (r[1] or ("#" + str(r[0]))).strip(), "included": bool(r[2])} for r in rows]
    finally:
        try:
            cm.__exit__(None, None, None)
        except Exception:
            pass
    return JSONResponse({"ok": True, "people": ppl})


@api_router.post("/app/flow/people/toggle")
async def app_flow_people_toggle(req: Request) -> JSONResponse:
    """Zařadit/vyjmout člověka z podskupiny plánování výroby."""
    uid = _flow_people_gate(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        tgt = int(body.get("user_id"))
    except Exception:
        return JSONResponse({"ok": False, "error": "bad user_id"}, status_code=400)
    included = bool(body.get("included"))
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        if included:
            s.execute(_t("DELETE FROM tenant.vyroba_plan_excl WHERE tenant_id=2 AND user_id=:u"), {"u": tgt})
        else:
            s.execute(_t("INSERT INTO tenant.vyroba_plan_excl(tenant_id,user_id,excluded_by) VALUES(2,:u,:by)"
                         " ON CONFLICT (tenant_id,user_id) DO NOTHING"), {"u": tgt, "by": uid})
        s.commit()
    finally:
        try:
            cm.__exit__(None, None, None)
        except Exception:
            pass
    return JSONResponse({"ok": True})


@api_router.get("/app/vytizeni-mesice")
def app_vytizeni_mesice(req: Request) -> JSONResponse:
    """Měsíční vytížení dílny. AKTUÁLNÍ ROK ze STRATEGIE (živě): naplánováno z
    tenant.vyroba_plan, kapacita z docházky Výroby (att_plan_effective, group 3).
    LONI z DB_EC (EC_Vytizeni_Historie) — jen pro porovnání. Měsíc bez plánu ve
    vyroba_plan má bez_planu=True (frontend ukáže „zatím neplánováno", ne 0 %).
    Pro dashboard 'Vytížení dílny' (baterky + tank). Read-only. Přístup: rodič /
    ambasador / vedoucí výroby (16,41,85) / obchod (skupina 7). Kristý 1.7.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    import json as _j
    cm, s = _att_session()
    try:
        isp = s.execute(_t("SELECT COALESCE(is_marti_parent,false) FROM public.users WHERE id=:u"),
                        {"u": int(uid)}).scalar()
    finally:
        try:
            cm.__exit__(None, None, None)
        except Exception:
            pass
    if not isp and not _is_ambassador(uid) and not _is_obchod(uid) and int(uid) not in (16, 41, 85):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return JSONResponse({"ok": False, "error": "mcp_unavailable"}, status_code=503)
    # LONI z DB_EC (EC_Vytizeni_Historie) — jen minulý rok pro porovnání baterek.
    # Aktuální rok se čte ze STRATEGIE níže (PG). Per měsíc nejnovější log (ROW_NUMBER).
    sql = ("WITH base AS ("
           " SELECT vh.Rok, vh.Mesic, vh.Kapacita,"
           " vh.HodinyMinRok AS Hodiny, vh.HodinyBezNabMinRok AS HodinyBezNab,"
           " ROW_NUMBER() OVER (PARTITION BY vh.Rok, vh.Mesic"
           "   ORDER BY h.DatPorizeni DESC, h.ID DESC) AS rn"
           " FROM EC_Vytizeni_Historie vh"
           " JOIN EC_Vytizeni_LogPlanSumaHlav h ON vh.IDHlavLogu = h.ID"
           " WHERE vh.Rok = YEAR(GETDATE())-1)"
           " SELECT Rok, Mesic, Hodiny, HodinyBezNab, Kapacita,"
           " CONVERT(numeric(5,2), CASE WHEN ISNULL(Kapacita,0)=0 THEN 0"
           " ELSE Hodiny*100.0/Kapacita END) AS Vytizeni"
           " FROM base WHERE rn = 1 ORDER BY Rok, Mesic")
    try:
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _j.loads(raw) if isinstance(raw, str) else raw
        rows = []
        if isinstance(r, dict):
            if r.get("ok") is False:
                return JSONResponse({"ok": False, "error": str(r.get("error"))[:200]}, status_code=502)
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    rows = r[k]
                    break
        elif isinstance(r, list):
            rows = r
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:200]}, status_code=502)

    def _n(x):
        try:
            return round(float(x), 2)
        except Exception:
            return 0.0

    out = []
    for d in rows:
        dl = {(k or "").lower(): v for k, v in d.items()}
        out.append({
            "rok": int(_n(dl.get("rok"))),
            "mesic": int(_n(dl.get("mesic"))),
            "hodiny": _n(dl.get("hodiny")),
            "hodiny_bez_nab": _n(dl.get("hodinybeznab")),
            "kapacita": _n(dl.get("kapacita")),
            "vytizeni": _n(dl.get("vytizeni")),
            "bez_planu": False,
        })

    # AKTUÁLNÍ ROK ze STRATEGIE (Kristý 1.7.2026): naplánováno z tenant.vyroba_plan,
    # kapacita z docházky Výroby (att_plan_effective, group 3, mimo vyjmuté + plánované absence).
    # bez_planu=True → měsíc nemá v vyroba_plan žádný plán → frontend „zatím neplánováno".
    import datetime as _dt
    _cy = _dt.date.today().year
    cm2, s2 = _att_session()
    try:
        rows_cy = s2.execute(_t(
            "WITH napl AS (SELECT EXTRACT(MONTH FROM datum)::int AS m, SUM(pocet_hodin) AS napl"
            " FROM tenant.vyroba_plan WHERE tenant_id=2 AND EXTRACT(YEAR FROM datum)=:cy GROUP BY 1),"
            " kap AS (SELECT EXTRACT(MONTH FROM pe.plan_date)::int AS m, SUM(pe.expected_hours) AS kap"
            "   FROM tenant.att_plan_effective pe"
            "   WHERE pe.tenant_id=2 AND EXTRACT(YEAR FROM pe.plan_date)=:cy"
            "     AND pe.user_id IN (SELECT gm.user_id FROM tenant.staff_group_member gm"
            "        WHERE gm.tenant_id=2 AND gm.group_id=3"
            "        AND gm.user_id NOT IN (SELECT user_id FROM tenant.vyroba_plan_excl WHERE tenant_id=2))"
            "     AND NOT EXISTS (SELECT 1 FROM tenant.att_planned_absence pa"
            "        WHERE pa.tenant_id=2 AND pa.user_id=pe.user_id AND pa.datum=pe.plan_date)"
            "   GROUP BY 1)"
            " SELECT COALESCE(napl.m, kap.m) AS mesic, COALESCE(kap.kap,0) AS kapacita,"
            "        napl.napl AS naplanovano"
            " FROM napl FULL OUTER JOIN kap ON napl.m=kap.m ORDER BY 1"),
            {"cy": _cy}).fetchall()
        for rr in rows_cy:
            _mes = int(rr[0]); _kap = float(rr[1] or 0); _napl_raw = rr[2]
            _bez = _napl_raw is None
            _napl = float(_napl_raw or 0)
            _vyt = round(100.0 * _napl / _kap, 2) if _kap > 0 else 0.0
            out.append({
                "rok": _cy, "mesic": _mes,
                "hodiny": _napl, "hodiny_bez_nab": _napl,
                "kapacita": _kap, "vytizeni": _vyt, "bez_planu": _bez,
            })
    finally:
        try:
            cm2.__exit__(None, None, None)
        except Exception:
            pass

    return JSONResponse({"ok": True, "rows": out,
                         "generated": _dt.datetime.now().strftime("%d.%m.%Y %H:%M")})


@api_router.get("/app/crm/plan-hovoru")
def app_crm_plan_hovoru(req: Request) -> JSONResponse:
    """Plán hovorů na týden — firmy s vyplněným PristiKontakt (DB_EC st.CRM_Kontakt),
    stav vztahu z číselníku CRM_Kontakt_StavVztahuCis, název+telefon+poznámka z poslední
    akce (na firmě bývají prázdné). BEZ filtru na autora — obvolává Pavel, vidí celý plán.
    Read-only přes EUROSOFT MCP. Přístup: rodič / ambasador / obchod Pavel (30).
    Kristý 27.6.2026 (prototyp k budoucímu framework přehledu)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    import json as _j
    cm, s = _att_session()
    try:
        isp = s.execute(_t("SELECT COALESCE(is_marti_parent,false) FROM public.users WHERE id=:u"),
                        {"u": int(uid)}).scalar()
    finally:
        try:
            cm.__exit__(None, None, None)
        except Exception:
            pass
    if not isp and not _is_ambassador(uid) and not _is_obchod(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return JSONResponse({"ok": False, "error": "mcp_unavailable"}, status_code=503)
    sql = (
        "SELECT k.ID AS id,"
        " COALESCE(NULLIF(LTRIM(RTRIM(k.FirmaText)),''), NULLIF(LTRIM(RTRIM(a.FirmaText)),'')) AS firma,"
        " CONVERT(varchar(10), k.PristiKontakt, 23) AS pristi,"
        " s.Nazev AS stav, s.Kod AS stav_kod, k.StavVztahuID AS stav_id,"
        " k.Atraktivita AS atraktivita,"
        " COALESCE(NULLIF(LTRIM(RTRIM(k.FirmaTelefon)),''), NULLIF(LTRIM(RTRIM(a.Telefon)),''),"
        "          NULLIF(LTRIM(RTRIM(a.Mobil)),'')) AS telefon,"
        " LTRIM(RTRIM(CONCAT(a.Jmeno, ' ', a.Prijmeni))) AS osoba,"
        " a.Prubeh AS poznamka"
        " FROM st.CRM_Kontakt k"
        " LEFT JOIN st.CRM_Kontakt_StavVztahuCis s ON s.ID = k.StavVztahuID"
        " OUTER APPLY ("
        "   SELECT TOP 1 aa.Prubeh, aa.FirmaText, aa.Telefon, aa.Mobil, aa.Jmeno, aa.Prijmeni"
        "   FROM st.CRM_Kontakt_Akce aa WHERE aa.IDHlav = k.ID"
        "   ORDER BY aa.DatPorizeni DESC, aa.ID DESC) a"
        " WHERE k.PristiKontakt IS NOT NULL"
        " ORDER BY k.PristiKontakt ASC"
    )
    try:
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _j.loads(raw) if isinstance(raw, str) else raw
        rows = []
        if isinstance(r, dict):
            if r.get("ok") is False:
                return JSONResponse({"ok": False, "error": str(r.get("error"))[:200]}, status_code=502)
            for kk in ("rows", "data", "result", "records"):
                if isinstance(r.get(kk), list):
                    rows = r[kk]
                    break
        elif isinstance(r, list):
            rows = r
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:200]}, status_code=502)
    out = []
    for d in rows:
        dl = {(c or "").lower(): v for c, v in d.items()}
        fid = dl.get("id")
        out.append({
            "id": fid,
            "firma": (str(dl.get("firma") or "").strip()) or ("Firma #" + str(fid)),
            "pristi": dl.get("pristi"),
            "stav": dl.get("stav"),
            "stav_kod": dl.get("stav_kod"),
            "stav_id": dl.get("stav_id"),
            "atraktivita": dl.get("atraktivita"),
            "telefon": str(dl.get("telefon") or "").strip(),
            "osoba": str(dl.get("osoba") or "").strip(),
            "poznamka": str(dl.get("poznamka") or "").strip(),
        })
    import datetime as _dt
    return JSONResponse({"ok": True, "rows": out,
                         "generated": _dt.datetime.now().strftime("%d.%m.%Y %H:%M")})


@api_router.post("/app/crm/hovor-zapis")
async def app_crm_hovor_zapis(req: Request) -> JSONResponse:
    """Zápis průběhu hovoru → nová akce telefonát (IDAkce=2) do st.CRM_Kontakt_Akce (DB_EC),
    volitelně posun PristiKontakt na firmě. Diktování průběhu řeší frontend přes /app/transcribe
    (Whisper). Autor = login_name uživatele (Autor v CRM = login, např. Pavel = 'PZeman').
    Přístup: rodič / ambasador / obchod — stejně jako plán hovorů. Kristý 7.7.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        isp = s.execute(_t("SELECT COALESCE(is_marti_parent,false) FROM public.users WHERE id=:u"),
                        {"u": int(uid)}).scalar()
    finally:
        try:
            cm.__exit__(None, None, None)
        except Exception:
            pass
    if not isp and not _is_ambassador(uid) and not _is_obchod(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        idh = int((body or {}).get("id") or 0)
    except Exception:
        idh = 0
    prubeh = str((body or {}).get("prubeh") or "").strip()
    pristi = str((body or {}).get("pristi") or "").strip()
    firma = str((body or {}).get("firma") or "").strip()[:256] or None
    if not idh:
        return JSONResponse({"ok": False, "error": "Chybí firma (id)."})
    if not prubeh:
        return JSONResponse({"ok": False, "error": "Prázdný průběh hovoru."})
    # Autor = login uživatele (v CRM je Autor login_name)
    autor = ""
    try:
        from core.database_data import get_data_session as _gds_au
        _sa = _gds_au()
        try:
            autor = (_sa.execute(_t(
                "SELECT COALESCE(NULLIF(login_name,''), NULLIF(short_name,''), '') "
                "FROM public.users WHERE id=:i"), {"i": int(uid)}).scalar() or "").strip()
        finally:
            _sa.close()
    except Exception:
        autor = ""
    if not autor:
        return JSONResponse({"ok": False, "error": "Uživatel nemá login (Autor pro CRM)."})
    import datetime as _dt
    pristi_ok = None
    if pristi:
        try:
            pristi_ok = _dt.date.fromisoformat(pristi).isoformat()
        except Exception:
            return JSONResponse({"ok": False, "error": "Neplatné datum příštího kontaktu."})
    mcp = _crm_import_mcp()
    if mcp is None:
        return JSONResponse({"ok": False, "error": "mcp_unavailable"}, status_code=503)
    today = _dt.date.today().isoformat()
    # Další pořadí akce v rámci firmy
    poradi = 1
    try:
        prows = _crm_mcp_rows(mcp, "SELECT ISNULL(MAX(Poradi),0)+1 AS p "
                              "FROM st.CRM_Kontakt_Akce WITH(NOLOCK) WHERE IDHlav=" + str(idh))
        pl = {(k or "").lower(): v for k, v in (prows[0] if prows else {}).items()}
        poradi = int(pl.get("p") or 1)
    except Exception:
        poradi = 1
    # INSERT telefonát (IDAkce=2 = telefonát na firmu) — objeví se i v „proběhlé hovory za týden"
    try:
        new_id = _crm_mcp_insert(mcp, "CRM_Kontakt_Akce", {
            "IDHlav": idh, "Poradi": poradi, "IDAkce": 2, "Splneno": 1,
            "Autor": autor, "DatumAkce": today, "DatPorizeni": today,
            "FirmaText": firma, "Prubeh": prubeh[:3900],
        })
    except Exception as exc:
        return JSONResponse({"ok": False, "error": "Zápis hovoru selhal: " + str(exc)[:200]},
                            status_code=502)
    # Volitelný posun příštího kontaktu na firmě
    pristi_set = False
    if pristi_ok:
        try:
            import json as _j
            raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                {"sql": "UPDATE st.CRM_Kontakt SET PristiKontakt='" + pristi_ok
                        + "' WHERE ID=" + str(idh), "db_name": "DB_EC"}, conversation_id=None)
            rr = _j.loads(raw) if isinstance(raw, str) else raw
            if isinstance(rr, dict) and rr.get("ok") is False:
                raise RuntimeError(str(rr.get("error"))[:200])
            pristi_set = True
        except Exception as exc:
            return JSONResponse({"ok": True, "akce_id": new_id, "pristi_set": False,
                                 "warn": "Hovor uložen, ale posun příštího kontaktu selhal: "
                                         + str(exc)[:160]})
    return JSONResponse({"ok": True, "akce_id": new_id, "pristi_set": pristi_set})


