# Pracovní vztah osoby (číselník) — konfigurovatelné z HR karty, měnitelné, auditované.
_WORK_RELATIONS = [
    {"key": "zamestnanec", "label": "Zaměstnanec"},
    {"key": "osvc", "label": "OSVČ (faktura)"},
    {"key": "dohoda", "label": "Dohoda (DPP/DPČ)"},
    {"key": "jednatel", "label": "Jednatel"},
]
_WORK_RELATION_KEYS = {r["key"] for r in _WORK_RELATIONS}


@api_router.post("/app/hr/person/work-relation")
async def app_hr_person_work_relation(req: Request) -> JSONResponse:
    """Nastavení/změna pracovního vztahu osoby (zaměstnanec/OSVČ/dohoda/jednatel).
    HR + rodiče, auditováno do work_relation_log."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        b = await req.json()
    except Exception:
        b = {}
    from sqlalchemy import text as _t
    tuid = int((b or {}).get("uid") or 0)
    rel = str((b or {}).get("relation") or "").strip()
    ico = (str((b or {}).get("ico") or "").strip() or None)
    note = (str((b or {}).get("note") or "").strip() or None)
    if rel not in _WORK_RELATION_KEYS:
        return JSONResponse({"ok": False, "error": "bad_relation"}, status_code=400)
    cm, s = _att_session()
    try:
        if not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        old = s.execute(_t("SELECT relation FROM tenant.work_relation WHERE tenant_id=2 AND user_id=:u"),
                        {"u": tuid}).first()
        old_rel = old[0] if old else None
        nm = _self_person_name(s, uid)
        s.execute(_t(
            "INSERT INTO tenant.work_relation (tenant_id, user_id, relation, ico, note, updated_by_text, updated_at) "
            "VALUES (2, :u, :r, :i, :n, :by, now()) "
            "ON CONFLICT (tenant_id, user_id) DO UPDATE SET relation=:r, ico=:i, note=:n, "
            "updated_by_text=:by, updated_at=now()"),
            {"u": tuid, "r": rel, "i": ico, "n": note, "by": nm})
        if old_rel != rel:
            s.execute(_t("INSERT INTO tenant.work_relation_log "
                         "(tenant_id, user_id, old_relation, new_relation, changed_by_text) "
                         "VALUES (2, :u, :o, :r, :by)"),
                      {"u": tuid, "o": old_rel, "r": rel, "by": nm})
        s.commit()
        return JSONResponse({"ok": True, "relation": rel})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/hr/person/save")
async def app_hr_person_save(req: Request) -> JSONResponse:
    """HR úprava úředních polí člověka. Loguje + upozorní dotyčného. BEZ paměti."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        b = await req.json()
    except Exception:
        b = {}
    from sqlalchemy import text as _t
    tuid = int((b or {}).get("uid") or 0)
    vals_in = (b or {}).get("values") or {}
    valid = {f[0]: f for f in _SELF_FIELDS if f[2] != "pamet" and not f[4]}
    cm, s = _att_session()
    try:
        if not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        cols = list(valid.keys())
        prev = s.execute(_t("SELECT " + ", ".join(cols) + " FROM tenant.user_self_data "
                            "WHERE tenant_id=2 AND user_id=:u"), {"u": tuid}).first()
        oldv = {}
        if prev:
            for i, c in enumerate(cols):
                ov = prev[i]
                if valid[c][3] == "date" and ov is not None:
                    ov = ov.isoformat()
                oldv[c] = ("" if ov is None else str(ov))
        newv = {}
        for c in cols:
            raw = vals_in.get(c)
            sv = ("" if raw is None else str(raw)).strip()
            newv[c] = (sv if sv != "" else None)
        changed = [(c, valid[c][1]) for c in cols
                   if oldv.get(c, "") != ("" if newv[c] is None else str(newv[c]))]
        if not changed:
            return JSONResponse({"ok": True, "changed": 0})
        set_cl = ", ".join(c + "=EXCLUDED." + c for c in cols)
        params = {"u": tuid}
        for c in cols:
            params[c] = newv[c]
        s.execute(_t(
            "INSERT INTO tenant.user_self_data (tenant_id, user_id, " + ", ".join(cols) +
            ", updated_at, updated_by) VALUES (2, :u, " + ", ".join(":" + c for c in cols) +
            ", now(), :u) ON CONFLICT (tenant_id, user_id) DO UPDATE SET " + set_cl +
            ", updated_at=now(), updated_by=:u"), params)
        for c, lab in changed:
            s.execute(_t("INSERT INTO tenant.user_self_data_log "
                         "(tenant_id, user_id, field_name, old_value, new_value, changed_by, change_source) "
                         "VALUES (2, :u, :fn, :ov, :nv, :by, 'hr')"),
                      {"u": tuid, "fn": c, "ov": oldv.get(c, ""),
                       "nv": ("" if newv[c] is None else str(newv[c])), "by": uid})
        nm = _self_person_name(s, uid)
        _self_notify_owner(s, tuid, "🪪 Úprava tvých údajů personalistikou",
            "Personální oddělení (" + nm + ") upravilo tvé údaje: "
            + ", ".join(x[1] for x in changed) + ". Pokud něco nesedí, ozvi se.")
        s.commit()
        return JSONResponse({"ok": True, "changed": len(changed)})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/devices")
async def app_devices(req: Request) -> JSONResponse:
    """Audit flotily appek: kdo má appku, verzi, jestli běží/pinguje. Jen rodiče."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not is_marti_parent(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        latest = s.execute(_t("SELECT COALESCE(max(version_code),0) FROM fw.mobile_device")).scalar() or 0
        rows = s.execute(_t(
            "SELECT d.device_label, d.user_id, "
            " COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),''), "
            "   d.device_label, '#'||d.user_id::text) AS jmeno, "
            " d.version_name, d.version_code, "
            " round(extract(epoch from (now()-d.last_seen_at)))::bigint AS age_s, "
            " to_char(d.last_seen_at,'DD.MM. HH24:MI') AS naposledy, "
            " COALESCE(d.service_enabled,false) "
            "FROM fw.mobile_device d LEFT JOIN public.users u ON u.id=d.user_id "
            "WHERE d.user_id NOT IN (3) "
            "ORDER BY d.last_seen_at DESC NULLS LAST")).fetchall()
        out = []
        for r in rows:
            age = int(r[5] or 999999)
            out.append({"zarizeni": r[0] or "?", "user_id": r[1], "jmeno": (r[2] or "").strip(),
                        "verze": r[3] or "?", "vc": int(r[4] or 0),
                        "online": age < 300, "min_ago": age // 60, "naposledy": r[6] or "",
                        "service": bool(r[7]),
                        "outdated": (int(r[4] or 0) < latest and latest > 0)})
        return JSONResponse({"ok": True, "latest_vc": latest, "zarizeni": out})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


