@api_router.post("/app/{app_key}/upload")
async def app_upload(
    app_key: str,
    req: Request,
    file: UploadFile = File(...),
    version_code: int = Form(...),
    version_name: str = Form(""),
    app_name: str = Form(""),
    notes: str = Form(""),
) -> JSONResponse:
    """Nahraje novou verzi APK appky {app_key} (jen rodič). Uloží APK + záznam
    verze do fw.app_version (datum+čas vydání = released_at)."""
    import os as _os_au
    from core.database_data import get_data_session as _gds_up
    from sqlalchemy import text as _sql_up

    if not _app_key_ok(app_key):
        return JSONResponse({"ok": False, "error": "Neplatný app_key"}, status_code=400)
    # Auth: parent session (UI) NEBO X-Deploy-Token (watcher „nahraj z buildu").
    _tok = req.headers.get("X-Deploy-Token")
    _env_tok = _os_au.environ.get("STRATEGIE_DEPLOY_TOKEN")
    if _tok and _env_tok and _tok == _env_tok:
        uid = 0  # systémový (watcher publish z NB buildu)
    else:
        uid = _get_uid(req)
        _require_admin(uid)

    name = (file.filename or "").lower()
    if not name.endswith(".apk"):
        return JSONResponse({"ok": False, "error": "Jen soubor .apk"}, status_code=400)
    if int(version_code) <= 0:
        return JSONResponse({"ok": False, "error": "Neplatný version_code"}, status_code=400)

    rel_dir = _app_releases_dir(app_key)
    fname = "%s-%d.apk" % (app_key, int(version_code))
    dest = _os_au.path.join(rel_dir, fname)
    size = 0
    try:
        with open(dest, "wb") as out:
            while True:
                chunk = await file.read(1024 * 1024)
                if not chunk:
                    break
                out.write(chunk)
                size += len(chunk)
                if size > 200 * 1024 * 1024:  # cap 200 MB
                    out.close()
                    _os_au.remove(dest)
                    return JSONResponse(
                        {"ok": False, "error": "APK je příliš velké (>200 MB)"},
                        status_code=400,
                    )
    except Exception as exc:
        logger.exception("[app_upload] save failed: %s", exc)
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)

    ds = _gds_up()
    try:
        ds.execute(_sql_up("""
            INSERT INTO fw.app_version
              (app_key, app_name, version_code, version_name, apk_file, size, notes,
               released_at, uploaded_by)
            VALUES (:app,:aname,:vc,:vn,:file,:size,:notes, now(), :uid)
            ON CONFLICT (app_key, version_code) DO UPDATE SET
              app_name=EXCLUDED.app_name, version_name=EXCLUDED.version_name,
              apk_file=EXCLUDED.apk_file, size=EXCLUDED.size, notes=EXCLUDED.notes,
              released_at=now(), uploaded_by=EXCLUDED.uploaded_by
        """), {"app": app_key, "aname": app_name.strip() or None,
               "vc": int(version_code), "vn": version_name.strip() or None,
               "file": fname, "size": size, "notes": notes.strip() or None,
               "uid": uid})
        ds.commit()
    except Exception as exc:
        ds.rollback()
        logger.exception("[app_upload] db insert failed: %s", exc)
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        ds.close()

    logger.info("[app_upload] %s verze %s (code %d, %d B) nahrál uid=%d",
                app_key, version_name, int(version_code), size, uid)
    return JSONResponse({"ok": True, "app_key": app_key, "version_code": int(version_code),
                         "version_name": version_name.strip(), "size": size})


@api_router.post("/app/docs/push-blob")
async def docs_push_blob(req: Request) -> JSONResponse:
    """Watcher (X-Deploy-Token) nahraje bajty dokumentu z lokálního stroje na cloud:
    uloží do documents_storage_dir (aby appka soubor otevřela + šel reindex) + srovná
    storage_path + (best-effort) zrcadlí do ZZ-Marti-AI RO přes MCP. Marti 5.7.2026 —
    TISAX binárky ležely na workstation místo na serveru."""
    import os as _osdb, base64 as _b64db, json as _jdb
    _tok = req.headers.get("X-Deploy-Token")
    _env = _osdb.environ.get("STRATEGIE_DEPLOY_TOKEN")
    if not (_tok and _env and _tok == _env):
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        b = await req.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "bad json"}, status_code=400)
    try:
        doc_id = int(b.get("doc_id"))
    except Exception:
        return JSONResponse({"ok": False, "error": "doc_id"}, status_code=400)
    try:
        data = _b64db.b64decode(b.get("b64") or "")
    except Exception:
        data = b""
    if not data:
        return JSONResponse({"ok": False, "error": "prázdné b64"}, status_code=400)
    ro_subdir = (b.get("ro_subdir") or "").strip().strip("/")
    from core.database_data import get_data_session as _gdp
    from sqlalchemy import text as _tp
    from core.config import settings as _cfg
    s = _gdp()
    try:
        row = s.execute(_tp("SELECT tenant_id, file_type, original_filename, name "
                            "FROM public.documents WHERE id=:i"), {"i": doc_id}).first()
        if not row:
            return JSONResponse({"ok": False, "error": "doc %s neexistuje" % doc_id})
        tid = int(row[0] or 0)
        ext = (row[1] or _osdb.path.splitext(row[2] or row[3] or "")[1].lstrip(".") or "bin").lower()
        tdir = _osdb.path.join(_cfg.documents_storage_dir, str(tid))
        _osdb.makedirs(tdir, exist_ok=True)
        dest = _osdb.path.abspath(_osdb.path.join(tdir, "%d.%s" % (doc_id, ext)))
        with open(dest, "wb") as fh:
            fh.write(data)
        s.execute(_tp("UPDATE public.documents SET storage_path=:p WHERE id=:i"), {"p": dest, "i": doc_id})
        s.commit()
        orig = row[2] or row[3] or ("%d.%s" % (doc_id, ext))
    finally:
        s.close()
    ro_ok = None
    if ro_subdir:
        try:
            from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
            mcp = get_eurosoft_mcp_client()
            if mcp is not None:
                raw = mcp.call_tool_sync("eurosoft_eurosoft_file_write",
                    {"user_namespace": "ro", "path": ro_subdir + "/" + orig,
                     "content": _b64db.b64encode(data).decode("ascii"),
                     "encoding": "base64", "mode": "overwrite"}, conversation_id=None)
                rr = _jdb.loads(raw) if isinstance(raw, str) else raw
                ro_ok = bool(isinstance(rr, dict) and rr.get("ok"))
        except Exception:
            ro_ok = False
    return JSONResponse({"ok": True, "doc_id": doc_id, "bytes": len(data),
                         "path": dest, "ro_mirror": ro_ok})


