@api_router.post("/app/{app_key}/heartbeat")
async def app_heartbeat(app_key: str, req: Request) -> JSONResponse:
    """Appka hlásí svůj stav (verze + nastavení) → fw.mobile_device. Token NEBO cookie."""
    from core.database_data import get_data_session as _gds_hb
    from sqlalchemy import text as _sql_hb

    if not _app_key_ok(app_key):
        return JSONResponse({"ok": False, "error": "Neplatný app_key"}, status_code=400)
    uid = _uid_from_token_or_cookie(req)
    try:
        body = await req.json()
    except Exception:
        body = {}
    dev = (str(body.get("device_id") or "")).strip()[:120]
    if not dev:
        return JSONResponse({"ok": False, "error": "device_id required"}, status_code=400)

    def _b(v):
        return bool(v) if v is not None else None

    params = {
        "app": app_key, "uid": uid, "dev": dev,
        "label": (str(body.get("device_label") or "")[:120]) or None,
        "vc": body.get("version_code"),
        "vn": (str(body.get("version_name") or "")[:40]) or None,
        "rel": (str(body.get("android_release") or "")[:40]) or None,
        "svc": _b(body.get("service_enabled")),
        "clog": _b(body.get("call_log_enabled")),
        "notif": _b(body.get("notif_enabled")),
        "fs": _b(body.get("fullscreen_enabled")),
        "url": (str(body.get("server_url") or "")[:200]) or None,
    }
    ds = _gds_hb()
    try:
        ds.execute(_sql_hb("""
            INSERT INTO fw.mobile_device
              (app_key, user_id, device_id, device_label, version_code, version_name,
               android_release, service_enabled, call_log_enabled, notif_enabled,
               fullscreen_enabled, server_url, last_seen_at)
            VALUES (:app,:uid,:dev,:label,:vc,:vn,:rel,:svc,:clog,:notif,:fs,:url, now())
            ON CONFLICT (app_key, user_id, device_id) DO UPDATE SET
              device_label=COALESCE(NULLIF(fw.mobile_device.device_label,''), EXCLUDED.device_label),
              version_code=EXCLUDED.version_code,
              version_name=EXCLUDED.version_name, android_release=EXCLUDED.android_release,
              service_enabled=EXCLUDED.service_enabled, call_log_enabled=EXCLUDED.call_log_enabled,
              notif_enabled=EXCLUDED.notif_enabled, fullscreen_enabled=EXCLUDED.fullscreen_enabled,
              server_url=EXCLUDED.server_url, last_seen_at=now()
        """), params)
        ds.commit()

        # HR inventura + presence (5.6.): telefon appky → fw.hr_device.
        # in_building z firemní IP NEBO firemní WiFi (SSID hlásí appka).
        # Best-effort, neovlivní odpověď heartbeatu.
        try:
            from modules.hr.presence import (touch_device as _hr_td,
                                             client_ip as _hr_ip,
                                             ip_in_building as _hr_inb,
                                             ssid_in_building as _hr_sib)
            _hb_ip = _hr_ip(req)
            _hb_ssid = (str(body.get("wifi_ssid") or "")[:64]) or None
            _hr_td(device_key=dev, device_type="phone",
                   name=params.get("label"), uid=uid, ip_str=_hb_ip,
                   source="mobile_app", ssid=_hb_ssid)
            try:
                from core.log_queue import log_event as _hb_log
                _hb_log(level="info", source="py", module_id="hr.heartbeat",
                        message=(f"heartbeat uid={uid} dev={dev} ip={_hb_ip} "
                                 f"ssid={_hb_ssid} in_building="
                                 f"{_hr_inb(_hb_ip) or _hr_sib(_hb_ssid)}"))
            except Exception:
                pass
        except Exception:
            pass

        try:
            _sms_gateway_watchdog(ds)
        except Exception:
            pass

        return JSONResponse({"ok": True})
    except Exception as exc:
        ds.rollback()
        logger.exception("[app_heartbeat] failed: %s", exc)
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        ds.close()


# ── Ověření telefonního čísla přes SMS (Marti 6.6.2026) ──────────────────
# Appka po potvrzení uživatelem pošle z telefonu SMS s tokenem STG-PAIR-XXXX
# na trusted SIM STRATEGIE; příchozí SMS (sms_preprocessor purpose=PAIR) z ní
# přečte číslo odesílatele → zapíše k zařízení + označí ověřeno. App pollne /status.
_SMS_VERIFY_TO = "+420778117879"  # Marti-AI / trusted SIM (sdílí 2FA)


@api_router.post("/app/phone-verify/start")
async def app_phone_verify_start(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        body = {}
    dev = (str((body or {}).get("device_id") or "")).strip()[:120] or None
    lbl = (str((body or {}).get("device_label") or "")).strip()[:120] or None
    # Zjisti id carddav_tokenu, kterým se appka autentizovala — ať umíme zapsat
    # ověřené číslo přímo na ten záznam (a dedupovat podle čísla). Marti 6.6.2026.
    _ctid = None
    _auth = req.headers.get("authorization") or ""
    if _auth.lower().startswith("bearer "):
        _tk = _auth[7:].strip()
        if _tk:
            import hashlib as _h_pv
            from core.database_data import get_data_session as _gds_t
            from sqlalchemy import text as _sql_t
            _th = _h_pv.sha256(_tk.encode("utf-8")).hexdigest()
            _dt = _gds_t()
            try:
                _ctid = _dt.execute(_sql_t(
                    'SELECT id FROM "user".carddav_token '
                    'WHERE token_hash = :h AND revoked_at IS NULL'
                ), {"h": _th}).scalar()
            except Exception:
                _ctid = None
            finally:
                _dt.close()
    import secrets as _sec_pv
    token = "STG-PAIR-" + _sec_pv.token_hex(4).upper()
    from core.database_data import get_data_session as _gds_pv
    from sqlalchemy import text as _sql_pv
    ds = _gds_pv()
    try:
        ds.execute(_sql_pv("DELETE FROM fw.phone_verify WHERE expires_at < now()"))
        ds.execute(_sql_pv(
            "INSERT INTO fw.phone_verify (token, user_id, device_id, device_label, carddav_token_id, expires_at) "
            "VALUES (:t, :u, :d, :l, :ct, now() + interval '15 minutes')"
        ), {"t": token, "u": uid, "d": dev, "l": lbl, "ct": _ctid})
        ds.commit()
    except Exception as exc:
        ds.rollback()
        logger.warning("[phone-verify start] %s", exc)
        return JSONResponse({"ok": False, "error": "server"}, status_code=500)
    finally:
        ds.close()
    return JSONResponse({"ok": True, "token": token, "send_to": _SMS_VERIFY_TO,
                         "body": token, "ttl_min": 15})


@api_router.post("/app/sms-inbound")
async def app_sms_inbound(req: Request) -> JSONResponse:
    """Marti 8.6.: VLASTNÍ příjem příchozích SMS — naše appka (SMS_RECEIVED
    receiver na gateway telefonu) sem POSTne příchozí SMS. Žádný cizí provider
    (capcom6/sms-gate.app). Uloží do sms_inbox + spustí PAIR preprocessor
    (ověření telefonu). Auth: carddav token appky (trusted zařízení)."""
    from starlette.concurrency import run_in_threadpool
    uid = _uid_from_token_or_cookie(req)
    try:
        body = await req.json()
    except Exception:
        body = {}
    from_phone = str((body or {}).get("from") or (body or {}).get("from_phone") or "").strip()
    text = str((body or {}).get("body") or (body or {}).get("message") or "").strip()
    to_phone = str((body or {}).get("to") or (body or {}).get("to_phone") or "").strip() or None
    _ip = (req.client.host if req.client else "") or ""
    # Marti 11.6.: audit KAŽDÉHO pokusu (i bez auth) — vidíme, jestli brána klepe
    if not uid:
        try:
            await run_in_threadpool(_sms_inbound_hit, "app", False, from_phone, text, _ip, "NO_AUTH 401")
        except Exception:
            pass
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    if not (from_phone and text):
        try:
            await run_in_threadpool(_sms_inbound_hit, "app", True, from_phone, text, _ip, "missing from/body")
        except Exception:
            pass
        return JSONResponse({"ok": False, "error": "from+body required"}, status_code=400)
    # trezor 2FA caller-ID (token STG-VLT-)
    vstatus = "not_vault"
    try:
        vstatus = await run_in_threadpool(_vault_match_inbound, from_phone, text)
    except Exception as _ve:
        vstatus = "error:" + str(_ve)[:50]
    try:
        await run_in_threadpool(_sms_inbound_hit, "app", True, from_phone, text, _ip, "vault=" + vstatus)
    except Exception:
        pass
    if vstatus != "not_vault":
        return JSONResponse({"ok": True, "vault": vstatus})
    try:
        from modules.notifications.application.sms_service import store_inbound_sms
        result = await run_in_threadpool(store_inbound_sms, from_phone, text, to_phone)
        return JSONResponse({"ok": True, "id": result.get("id")})
    except Exception as exc:
        logger.warning("[app sms-inbound] %s", exc)
        return JSONResponse({"ok": False, "error": str(exc)[:160]}, status_code=500)


# ── Odchozí SMS přes bránu (pull model, Kristý/Claude-24 23.6.2026) ──────────
# 11.6. se provider přepnul na android_gateway (pull), ale chyběl konzument fronty.
# Bránový telefon (JS poller v mobile.html) si tudy stáhne pending sms_outbox,
# pošle přes B.sendSms a potvrdí. PŘÍSNÉ omezení: jen bránový telefon (carddav
# phone == SMS_FROM_NUMBER) — fronta obsahuje PIN/aktivace, nesmí ji vidět nikdo jiný.

def _is_gateway_request(req) -> bool:
    from sqlalchemy import text as _t
    import hashlib as _h, re as _re
    from core.config import settings as _cfg
    auth = req.headers.get("authorization") or ""
    if not auth.lower().startswith("bearer "):
        return False
    tok = auth[7:].strip()
    if not tok:
        return False
    gw = _re.sub(r"\D", "", (_cfg.sms_from_number or ""))[-9:]
    if len(gw) < 9:
        return False
    th = _h.sha256(tok.encode("utf-8")).hexdigest()
    cm, s = _att_session()
    try:
        ph = s.execute(_t('SELECT phone_number FROM "user".carddav_token '
                          'WHERE token_hash=:h AND revoked_at IS NULL'), {"h": th}).scalar()
    except Exception:
        ph = None
    finally:
        cm.__exit__(None, None, None)
    if not ph:
        return False
    return _re.sub(r"\D", "", str(ph))[-9:] == gw


@api_router.get("/app/sms-outbound/pending")
async def app_sms_outbound_pending(req: Request) -> JSONResponse:
    """Bránový telefon si stáhne pending odchozí SMS. Jen brána (viz _is_gateway_request)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    if not _is_gateway_request(req):
        return JSONResponse({"ok": False, "error": "not_gateway"}, status_code=403)
    from starlette.concurrency import run_in_threadpool
    from modules.notifications.application.sms_service import list_pending
    try:
        items = await run_in_threadpool(list_pending, 20)
        return JSONResponse({"ok": True, "items": items})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)[:160]}, status_code=500)


@api_router.post("/app/sms-outbound/sent")
async def app_sms_outbound_sent(req: Request) -> JSONResponse:
    """Bránový telefon potvrzuje odeslání (ok=true → sent, jinak failed)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    if not _is_gateway_request(req):
        return JSONResponse({"ok": False, "error": "not_gateway"}, status_code=403)
    try:
        b = await req.json()
    except Exception:
        b = {}
    try:
        oid = int((b or {}).get("id"))
    except Exception:
        return JSONResponse({"ok": False, "error": "id required"}, status_code=400)
    from starlette.concurrency import run_in_threadpool
    from modules.notifications.application.sms_service import mark_sent, mark_failed
    try:
        if (b or {}).get("ok", True):
            await run_in_threadpool(mark_sent, oid)
        else:
            await run_in_threadpool(mark_failed, oid, str((b or {}).get("error") or "gateway send failed")[:300])
        return JSONResponse({"ok": True})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)[:160]}, status_code=500)


@api_router.get("/app/phone-verify/status")
async def app_phone_verify_status(req: Request, token: str = "") -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from core.database_data import get_data_session as _gds_ps
    from sqlalchemy import text as _sql_ps
    ds = _gds_ps()
    try:
        row = ds.execute(_sql_ps(
            "SELECT phone_number, verified_at FROM fw.phone_verify "
            "WHERE token = :t AND user_id = :u"
        ), {"t": (token or "").strip(), "u": uid}).first()
    finally:
        ds.close()
    if not row:
        return JSONResponse({"ok": True, "verified": False, "unknown": True})
    return JSONResponse({"ok": True, "verified": row[1] is not None,
                         "phone_number": row[0]})


@api_router.post("/app/phone-set")
async def app_phone_set(req: Request) -> JSONResponse:
    """Uloží číslo telefonu přímo z appky (přečtené ze SIM + potvrzené uživatelem)
    — bez SMS brány. Zapíše k carddav_tokenu (kterým se appka hlásí) + k zařízení
    a dedupuje: jiné aktivní tokeny téhož uživatele se stejným číslem odpojí.
    Marti 6.6.2026 (vlastní appka = nepotřebujeme cizí SMS providera)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        body = {}
    phone = (str((body or {}).get("phone_number") or "")).strip()[:32]
    dev = (str((body or {}).get("device_id") or "")).strip()[:120] or None
    if len(phone.replace("+", "").replace(" ", "")) < 6:
        return JSONResponse({"ok": False, "error": "invalid_phone"}, status_code=400)
    import hashlib as _h_set
    from core.database_data import get_data_session as _gds_set
    from sqlalchemy import text as _sql_set
    # id tokenu, kterým se appka autentizovala (ať číslo zapíšeme na ten záznam)
    ctid = None
    _auth = req.headers.get("authorization") or ""
    if _auth.lower().startswith("bearer "):
        _tk = _auth[7:].strip()
        if _tk:
            _dh = _gds_set()
            try:
                ctid = _dh.execute(_sql_set(
                    'SELECT id FROM "user".carddav_token '
                    'WHERE token_hash = :h AND revoked_at IS NULL'
                ), {"h": _h_set.sha256(_tk.encode("utf-8")).hexdigest()}).scalar()
            except Exception:
                ctid = None
            finally:
                _dh.close()
    ds = _gds_set()
    try:
        if dev:
            ds.execute(_sql_set(
                "UPDATE fw.mobile_device SET phone_number=:p, phone_verified_at=now() "
                "WHERE user_id=:u AND device_id=:d"
            ), {"p": phone, "u": uid, "d": dev})
        else:
            ds.execute(_sql_set(
                "UPDATE fw.mobile_device SET phone_number=:p, phone_verified_at=now() "
                "WHERE user_id=:u"
            ), {"p": phone, "u": uid})
        if ctid:
            ds.execute(_sql_set(
                'UPDATE "user".carddav_token SET phone_number=:p WHERE id=:c'
            ), {"p": phone, "c": ctid})
            # dedup: stejné číslo u téhož uživatele → ostatní odpoj (drž jen tenhle)
            ds.execute(_sql_set(
                'UPDATE "user".carddav_token SET revoked_at=now() '
                'WHERE user_id=:u AND phone_number=:p AND revoked_at IS NULL AND id<>:c'
            ), {"u": uid, "p": phone, "c": ctid})
        ds.commit()
    except Exception as exc:
        ds.rollback()
        logger.warning("[phone-set] %s", exc)
        return JSONResponse({"ok": False, "error": "server"}, status_code=500)
    finally:
        ds.close()
    return JSONResponse({"ok": True, "phone_number": phone})


# ── Mobilní docházka (check-in/out + přehled) — Marti 6.6.2026 ──────────────
# Zapisuje do tenant.att_* přes strategie_pg (Marti-AI engine, vlastní tenant.*).
_ATT_TENANT = 2  # EUROSOFT (TODO: odvodit z usera pro multi-tenant prodej)


def _att_session():
    from modules.strategie_pg.application import service as _pg
    cm = _pg.get_session()
    return cm, cm.__enter__()


def _att_employee(sess, uid):
    from sqlalchemy import text as _t
    r = sess.execute(_t("SELECT id FROM tenant.att_employee WHERE tenant_id=:t AND user_id=:u"),
                     {"t": _ATT_TENANT, "u": uid}).first()
    if r:
        return r[0]
    nm = None
    try:
        from core.database_data import get_data_session as _g
        d = _g()
        try:
            rr = d.execute(_t("SELECT NULLIF(TRIM(COALESCE(first_name,'')||' '||COALESCE(last_name,'')),'') "
                              "FROM public.users WHERE id=:u"), {"u": uid}).first()
            nm = rr[0] if rr else None
        finally:
            d.close()
    except Exception:
        nm = None
    # Zkus adoptovat existujícího (Centrála) zaměstnance podle jména, ať nevznikne dvojník.
    if nm:
        ra = sess.execute(_t(
            "SELECT id FROM tenant.att_employee WHERE tenant_id=:t AND user_id IS NULL "
            "AND cislo_zam NOT LIKE 'U%' AND lower(full_name)=lower(:n) "
            "ORDER BY id LIMIT 1"), {"t": _ATT_TENANT, "n": nm}).first()
        if ra:
            sess.execute(_t("UPDATE tenant.att_employee SET user_id=:u, updated_at=now() WHERE id=:id"),
                         {"u": uid, "id": ra[0]})
            return ra[0]
    r = sess.execute(_t(
        "INSERT INTO tenant.att_employee (tenant_id,cislo_zam,user_id,full_name,is_active,created_at,updated_at) "
        "VALUES (:t, :cz, :u, :n, true, now(), now()) RETURNING id"),
        {"t": _ATT_TENANT, "cz": "U" + str(uid), "u": uid, "n": nm}).first()
    return r[0]


def _att_work_type(sess):
    from sqlalchemy import text as _t
    r = sess.execute(_t("SELECT id FROM tenant.att_entry_type WHERE tenant_id=:t AND code='work'"),
                     {"t": _ATT_TENANT}).first()
    return r[0] if r else None


def _att_close_stale(sess, emp):
    """Marti 12.6.: půlnoční uzávěrka — jakýkoli AKTIVNÍ job z minulého dne se uzavře
    ke konci svého dne (23:59:59). Řeší 'konec dne' běžící přes půlnoc i zapomenuté
    odchody, ať příští den začíná čistě."""
    from sqlalchemy import text as _t
    try:
        sess.execute(_t(
            "UPDATE tenant.att_entry "
            "SET ended_at = entry_date + interval '1 day' - interval '1 second', is_active=false, "
            "hours = round((EXTRACT(EPOCH FROM (entry_date + interval '1 day' - interval '1 second' - started_at))/3600.0)::numeric,2), "
            "updated_at = now() "
            "WHERE tenant_id=:t AND employee_id=:e AND is_active=true "
            "AND entry_date < current_date AND started_at IS NOT NULL"),
            {"t": _ATT_TENANT, "e": emp})
    except Exception:
        pass


@api_router.get("/app/attendance/status")
async def att_status(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        emp = _att_employee(s, uid)
        _att_close_stale(s, emp)
        opn = s.execute(_t("SELECT a.id, to_char(a.started_at,'YYYY-MM-DD\"T\"HH24:MI:SS'), a.project_ref, "
                           "COALESCE(et.code,'') "
                           "FROM tenant.att_entry a LEFT JOIN tenant.att_entry_type et ON et.id=a.entry_type_id "
                           "WHERE a.tenant_id=:t AND a.employee_id=:e AND a.is_active=true "
                           "AND a.status IS DISTINCT FROM 'superseded' "
                           "ORDER BY a.id DESC LIMIT 1"), {"t": _ATT_TENANT, "e": emp}).first()
        # Marti 7.6.: do "dnes odpracovano" pocitej i bezici (otevrenou) smenu —
        # is_active radek nema hours, tak vezmeme now()-started_at.
        # Marti 12.6.: do odpracovaného počítej jen práci (presence) — přestávka/konec dne ne.
        today = s.execute(_t("SELECT COALESCE(round(sum("
                             "CASE WHEN a.is_active THEN GREATEST(EXTRACT(EPOCH FROM (now() - a.started_at)),0)/3600.0 "
                             "ELSE COALESCE(a.hours,0) END"
                             ")::numeric,2),0), count(*) "
                             "FROM tenant.att_entry a "
                             "LEFT JOIN tenant.att_entry_type et ON et.id=a.entry_type_id "
                             "WHERE a.tenant_id=:t AND a.employee_id=:e AND a.entry_date=current_date "
                             "AND a.status IS DISTINCT FROM 'superseded' "
                             "AND COALESCE(et.category,'presence')='presence'"),
                          {"t": _ATT_TENANT, "e": emp}).first()
        ann = s.execute(_t("SELECT note FROM tenant.att_entry "
                           "WHERE tenant_id=:t AND employee_id=:e AND entry_date=current_date "
                           "AND status='announced' ORDER BY id DESC LIMIT 1"),
                        {"t": _ATT_TENANT, "e": emp}).first()
        # Marti 7.6. večer: „Od" = první reálné píchnutí dne + název zakázky.
        first = s.execute(_t(
            "SELECT to_char(MIN(started_at),'YYYY-MM-DD\"T\"HH24:MI:SS') FROM tenant.att_entry "
            "WHERE tenant_id=:t AND employee_id=:e AND entry_date=current_date "
            "AND started_at IS NOT NULL AND status NOT IN ('announced','superseded')"),
            {"t": _ATT_TENANT, "e": emp}).first()
        pname = None
        ptyp = None
        # reálná zakázka (ne režijní marker) → načti název/typ z číselníku
        _pref = (opn[2] or "").strip() if opn else ""
        if _pref and _pref.lower() not in ("rezie", "režie"):
            prow = s.execute(_t("SELECT nazev, typ FROM tenant.zakazka WHERE tenant_id=:t AND cislo=:c"),
                             {"t": _ATT_TENANT, "c": opn[2]}).first()
            if prow:
                pname = prow[0]
                ptyp = prow[1]
        # Marti 12.6.: bez píchnuté zakázky = skupina Režie (jen pro práci/overhead, NE přestávku)
        if ptyp is None and opn and opn[3] in ("work", "overhead") and (not _pref or _pref.lower() in ("rezie", "režie")):
            ptyp = "REZIE"
        # Marti 7.6. večer: poslední odchod dne — pro přívětivý stav mimo směnu.
        lend = s.execute(_t(
            "SELECT to_char(MAX(ended_at),'YYYY-MM-DD\"T\"HH24:MI:SS') FROM tenant.att_entry "
            "WHERE tenant_id=:t AND employee_id=:e AND entry_date=current_date "
            "AND ended_at IS NOT NULL AND status NOT IN ('announced','superseded')"),
            {"t": _ATT_TENANT, "e": emp}).first()
        # Marti 12.6.: „mám volno" — existuje dnes job 'Konec dne' (uzavřený do půlnoci)
        day_off = s.execute(_t(
            "SELECT 1 FROM tenant.att_entry a JOIN tenant.att_entry_type et ON et.id=a.entry_type_id "
            "WHERE a.tenant_id=:t AND a.employee_id=:e AND a.entry_date=current_date "
            "AND et.code='day_end' AND a.status IS DISTINCT FROM 'superseded' LIMIT 1"),
            {"t": _ATT_TENANT, "e": emp}).first() is not None
        # Marti 12.6.: mzdový režim (hodinovy / volny / pausal) — píchají všichni, režim řeší odměnu/řízení
        mode = s.execute(_t("SELECT COALESCE(rez_mzdovy,'hodinovy') FROM tenant.att_employee WHERE id=:e"),
                         {"e": emp}).scalar() or "hodinovy"
        # Petra 25.6.2026: OSVČ vidí v „Teď to bude jinak" volbu „Nepřítomnost OSVČ".
        is_osvc = (str(s.execute(_t("SELECT COALESCE(rez_forma,'') FROM tenant.att_employee WHERE id=:e"),
                                 {"e": emp}).scalar() or "").upper() == "OSVC")
        s.commit()
        return JSONResponse({"ok": True, "mode": mode, "is_osvc": is_osvc,
                             "open": ({"id": opn[0], "started_at": opn[1], "project_ref": opn[2],
                                       "project_name": pname, "project_type": ptyp,
                                       "open_type": opn[3]} if opn else None),
                             "day_off": day_off,
                             "announced": (ann[0] if ann else None),
                             "morning_start": (first[0] if first else None),
                             "last_end": (lend[0] if lend else None),
                             "today_hours": float(today[0] or 0), "today_entries": int(today[1] or 0)})
    finally:
        cm.__exit__(None, None, None)


def _att_presence_note(body: dict) -> str:
    """Marti 7.6.: lidský status — text [+ ' od HH:MM'] [+ ' do cca HH:MM' z eta]
    [+ ' do <until_txt>']. Bez textu = default „Už jedu do práce, dorazím ~X"."""
    from datetime import datetime as _dt, timedelta as _td
    txt = str((body or {}).get("text") or "").strip()[:160]
    try:
        eta = max(0, min(480, int((body or {}).get("eta_min") or 0)))
    except Exception:
        eta = 0
    until_txt = str((body or {}).get("until_txt") or "").strip()[:40]
    add_since = bool((body or {}).get("add_since", True))
    if not txt:
        eta = eta or 30
        return "Už jedu do práce, dorazím ~" + (_dt.now() + _td(minutes=eta)).strftime("%H:%M")
    note = txt
    if add_since:
        note += " od " + _dt.now().strftime("%H:%M")
    if eta:
        note += " do cca " + (_dt.now() + _td(minutes=eta)).strftime("%H:%M")
    if until_txt:
        note += " do " + until_txt
    return note[:240]


# ── Fáze 1 schvalování docházky (Marti 7.6.2026): samopotvrzení dne ──
# „Každý user zodpovídá za svou docházku sám. Systém VYŽADUJE po ukončení
# dne, nejdéle do začátku další směny, kontrolu a potvrzení předchozí směny."
_ATT_CONFIRM_SINCE = "2026-06-06"  # od kdy se potvrzování vyžaduje (start pilotu)


def _att_unconfirmed_days(s, emp) -> list:
    """Dny s odpracovanými záznamy bez potvrzení (max 14 dní zpět, od pilotu)."""
    from sqlalchemy import text as _t
    rows = s.execute(_t(
        "SELECT e.entry_date, "
        "  min(to_char(e.started_at,'HH24') || ':' || to_char(e.started_at,'MI')) AS od, "
        "  max(COALESCE(to_char(e.ended_at,'HH24') || ':' || to_char(e.ended_at,'MI'), '…')) AS do_, "
        "  round(sum(COALESCE(e.hours,0))::numeric,2) AS hodin, count(*) AS zaznamu "
        "FROM tenant.att_entry e "
        "JOIN tenant.att_entry_type et ON et.id = e.entry_type_id "
        "WHERE e.tenant_id = :t AND e.employee_id = :e "
        "  AND e.entry_date < current_date "
        "  AND e.entry_date >= GREATEST(current_date - 14, CAST(:since AS date)) "
        "  AND et.category = 'presence' AND e.started_at IS NOT NULL "
        "  AND e.status NOT IN ('superseded','announced') "
        "  AND NOT EXISTS (SELECT 1 FROM tenant.att_day_confirm c "
        "       WHERE c.tenant_id = :t AND c.employee_id = :e AND c.day = e.entry_date) "
        "GROUP BY e.entry_date ORDER BY e.entry_date"),
        {"t": _ATT_TENANT, "e": emp, "since": _ATT_CONFIRM_SINCE}).fetchall()
    return [{"day": r[0].isoformat(), "od": r[1], "do": r[2],
             "hodin": float(r[3] or 0), "zaznamu": int(r[4] or 0)} for r in rows]


@api_router.get("/app/attendance/unconfirmed")
async def att_unconfirmed(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    cm, s = _att_session()
    try:
        emp = _att_employee(s, uid)
        days = _att_unconfirmed_days(s, emp)
        # Marti 7.6. večer: dnešek „odmakáno a nepotvrzeno" — pro pulz rámečku
        # i nabídku ke schválení. JEN při statusu konce dne („nepočítej" /
        # „dnes už nedorazím") — normální pauza s tím neprudí.
        from sqlalchemy import text as _t
        tod = s.execute(_t(
            "SELECT 1 FROM tenant.att_entry e "
            "JOIN tenant.att_entry_type et ON et.id = e.entry_type_id "
            "WHERE e.tenant_id = :t AND e.employee_id = :e AND e.entry_date = current_date "
            "  AND et.category = 'presence' AND e.started_at IS NOT NULL "
            "  AND e.status NOT IN ('superseded','announced') "
            "  AND NOT EXISTS (SELECT 1 FROM tenant.att_entry o WHERE o.tenant_id = :t "
            "       AND o.employee_id = :e AND o.is_active = true) "
            "  AND EXISTS (SELECT 1 FROM tenant.att_entry a2 WHERE a2.tenant_id = :t "
            "       AND a2.employee_id = :e AND a2.entry_date = current_date "
            "       AND a2.status = 'announced' "
            "       AND (a2.note ILIKE '%nepočítej%' OR a2.note ILIKE '%nedorazím%')) "
            "  AND NOT EXISTS (SELECT 1 FROM tenant.att_day_confirm c WHERE c.tenant_id = :t "
            "       AND c.employee_id = :e AND c.day = current_date) LIMIT 1"),
            {"t": _ATT_TENANT, "e": emp}).first() is not None
        # Marti 7.6. večer: „dnes odmakáno" → dnešek NABÍDNOUT ke schválení
        # (jen v kartě — záchytka před píchnutím hlídá pouze minulé dny,
        # jinak by návrat z pauzy vyžadoval potvrzení rozdělaného dne).
        if tod:
            r2 = s.execute(_t(
                "SELECT current_date::text, "
                "  min(to_char(e.started_at,'HH24:MI')), "
                "  max(COALESCE(to_char(e.ended_at,'HH24:MI'),'…')), "
                "  round(sum(COALESCE(e.hours,0))::numeric,2), count(*) "
                "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id = e.entry_type_id "
                "WHERE e.tenant_id = :t AND e.employee_id = :e AND e.entry_date = current_date "
                "AND et.category = 'presence' AND e.started_at IS NOT NULL "
                "AND e.status NOT IN ('superseded','announced')"),
                {"t": _ATT_TENANT, "e": emp}).first()
            if r2 and r2[4]:
                days.append({"day": r2[0], "od": r2[1], "do": r2[2],
                             "hodin": float(r2[3] or 0), "zaznamu": int(r2[4] or 0)})
        s.commit()
        return JSONResponse({"ok": True, "days": days, "today_unconfirmed": tod})
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/attendance/confirm-day")
async def att_confirm_day(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    from datetime import datetime as _dt
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        day = _dt.strptime(str((body or {}).get("day") or "")[:10], "%Y-%m-%d").date()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid_day"}, status_code=400)
    if day > _dt.now().date():
        return JSONResponse({"ok": False, "error": "Budoucí den potvrdit nejde."}, status_code=400)
    cm, s = _att_session()
    try:
        emp = _att_employee(s, uid)
        # Marti 7.6. večer: dnešek lze potvrdit, jen když je den UZAVŘENÝ —
        # žádná běžící směna + status konce dne (nepočítej / dnes už nedorazím).
        if day == _dt.now().date():
            uzavren = s.execute(_t(
                "SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM tenant.att_entry o "
                "  WHERE o.tenant_id = :t AND o.employee_id = :e AND o.is_active = true) "
                "AND EXISTS (SELECT 1 FROM tenant.att_entry a2 WHERE a2.tenant_id = :t "
                "  AND a2.employee_id = :e AND a2.entry_date = current_date "
                "  AND a2.status = 'announced' "
                "  AND (a2.note ILIKE '%nepočítej%' OR a2.note ILIKE '%nedorazím%'))"),
                {"t": _ATT_TENANT, "e": emp}).first() is not None
            if not uzavren:
                s.commit()
                return JSONResponse({"ok": False, "error": "Dnešek potvrdíš, až den ukončíš."}, status_code=400)
        s.execute(_t(
            "INSERT INTO tenant.att_day_confirm (tenant_id, employee_id, day, confirmed_by_user_id) "
            "VALUES (:t, :e, :d, :u) ON CONFLICT (tenant_id, employee_id, day) DO NOTHING"),
            {"t": _ATT_TENANT, "e": emp, "d": day.isoformat(), "u": uid})
        # Marti 7.7.2026: po potvrzení dne UKLIDIT jeho anomálii i mobilní notifikaci
        # „🖊 Potvrď si docházku" — jinak notifikace svítí dál i po odsouhlasení.
        s.execute(_t(
            "DELETE FROM tenant.att_anomaly a USING tenant.att_entry e "
            "WHERE a.tenant_id = :t AND a.rule = 'nepotvrzeny_den' AND a.employee_id = :e "
            "  AND e.id = a.entry_id AND e.entry_date = :d"),
            {"t": _ATT_TENANT, "e": emp, "d": day.isoformat()})
        # notifikace nese v title '🖊 Potvrď si docházku' a message začíná 'DD.MM. …'
        s.execute(_t(
            "UPDATE fw.mobile_command SET status='done', decided_at=now() "
            "WHERE target_user_id = :u AND command_type = 'claude_msg' AND status = 'pending' "
            "  AND title LIKE '%Potvrď si docházku%' AND message LIKE :dp"),
            {"u": uid, "dp": day.strftime("%d.%m.") + "%"})
        # když už žádný den nečeká na potvrzení, zhasni i případné zbylé připomínky
        if not _att_unconfirmed_days(s, emp):
            s.execute(_t(
                "UPDATE fw.mobile_command SET status='done', decided_at=now() "
                "WHERE target_user_id = :u AND command_type = 'claude_msg' AND status = 'pending' "
                "  AND title LIKE '%Potvrď si docházku%'"),
                {"u": uid})
        s.commit()
        return JSONResponse({"ok": True, "day": day.isoformat()})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


# ── PIN pro výplatní pásku (Marti 7.6. večer) ────────────────────────────
# „Aby si mezi sebou lidé neukazovali v pracovní době kolik kdo bere."
# 1) Páska jen mimo směnu (odhlášen / na pauze — žádný att_entry is_active).
# 2) Vlastní 4místný PIN (hash v fw.user_pin), 5 pokusů → zámek 15 minut.
#    Zapomenutý PIN → SMS kód (reuse fw.phone_verify_code infra z onboardingu).

def _pin_hash(pin: str, salt: str) -> str:
    import hashlib
    return hashlib.pbkdf2_hmac("sha256", pin.encode("utf-8"),
                               salt.encode("utf-8"), 50000).hex()


def _pin_gate(s, uid: int, pin: str):
    """Vrátí None (PIN ok) nebo error dict pro JSONResponse (200)."""
    from sqlalchemy import text as _t
    row = s.execute(_t(
        "SELECT pin_hash, failed_attempts, "
        "       COALESCE(locked_until > now(), false), "
        "       GREATEST(CEIL(EXTRACT(EPOCH FROM (locked_until - now())) / 60.0), 1) "
        "FROM fw.user_pin WHERE user_id = :u"), {"u": uid}).first()
    if not row:
        return {"ok": False, "error": "pin_not_set"}
    if row[2]:
        return {"ok": False, "error": "pin_locked", "minutes": int(row[3] or 15)}
    if not pin:
        return {"ok": False, "error": "pin_required"}
    ph = row[0] or ""
    salt, _, hsh = ph.partition("$")
    if not (pin.isdigit() and _pin_hash(pin, salt) == hsh):
        fa = int(row[1] or 0) + 1
        if fa >= 5:
            s.execute(_t("UPDATE fw.user_pin SET failed_attempts = 0, "
                         "locked_until = now() + interval '15 minutes', "
                         "updated_at = now() WHERE user_id = :u"), {"u": uid})
            s.commit()
            return {"ok": False, "error": "pin_locked", "minutes": 15}
        s.execute(_t("UPDATE fw.user_pin SET failed_attempts = :f, "
                     "updated_at = now() WHERE user_id = :u"), {"f": fa, "u": uid})
        s.commit()
        return {"ok": False, "error": "pin_wrong", "left": 5 - fa}
    if int(row[1] or 0):
        s.execute(_t("UPDATE fw.user_pin SET failed_attempts = 0, "
                     "updated_at = now() WHERE user_id = :u"), {"u": uid})
        s.commit()
    return None


def _pin_consume_sms_code(s, uid: int, code: str) -> bool:
    """Ověří + spotřebuje SMS kód z fw.phone_verify_code (stejná logika
    jako onboarding confirm — poslední nepoužitý, neexpirovaný, max 5 pokusů)."""
    from sqlalchemy import text as _t
    code = (code or "").strip()
    if not (code.isdigit() and len(code) == 6):
        return False
    row = s.execute(_t(
        "SELECT id, code, attempts FROM fw.phone_verify_code "
        "WHERE user_id = :u AND used_at IS NULL AND expires_at > now() "
        "ORDER BY id DESC LIMIT 1"), {"u": uid}).first()
    if not row or int(row[2] or 0) >= 5:
        return False
    if code != row[1]:
        s.execute(_t("UPDATE fw.phone_verify_code SET attempts = attempts + 1 "
                     "WHERE id = :i"), {"i": row[0]})
        s.commit()
        return False
    s.execute(_t("UPDATE fw.phone_verify_code SET used_at = now() WHERE id = :i"),
              {"i": row[0]})
    s.commit()
    return True


@api_router.post("/app/pin/set")
async def app_pin_set(req: Request) -> JSONResponse:
    """Nastavení / změna PINu. První nastavení bez ověření; změna vyžaduje
    starý PIN NEBO SMS kód (zapomenutý PIN přes /app/pin/forgot)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    import secrets as _sec
    try:
        body = await req.json()
    except Exception:
        body = {}
    pin = str((body or {}).get("pin") or "").strip()
    if not (pin.isdigit() and len(pin) == 4):
        return JSONResponse({"ok": False, "error": "pin_invalid",
                             "note": "PIN jsou 4 číslice."})
    cm, s = _att_session()
    try:
        exists = s.execute(_t("SELECT 1 FROM fw.user_pin WHERE user_id = :u"),
                           {"u": uid}).first() is not None
        if exists:
            old_pin = str((body or {}).get("old_pin") or "").strip()
            code = str((body or {}).get("code") or "").strip()
            allowed = False
            if code:
                allowed = _pin_consume_sms_code(s, uid, code)
                if not allowed:
                    return JSONResponse({"ok": False, "error": "code_wrong",
                                         "note": "SMS kód nesedí nebo vypršel."})
            elif old_pin:
                err = _pin_gate(s, uid, old_pin)
                if err:
                    return JSONResponse(err)
                allowed = True
            if not allowed:
                return JSONResponse({"ok": False, "error": "verify_required"})
        salt = _sec.token_hex(8)
        s.execute(_t(
            "INSERT INTO fw.user_pin (user_id, pin_hash, failed_attempts, locked_until) "
            "VALUES (:u, :h, 0, NULL) "
            "ON CONFLICT (user_id) DO UPDATE SET pin_hash = EXCLUDED.pin_hash, "
            "failed_attempts = 0, locked_until = NULL, updated_at = now()"),
            {"u": uid, "h": salt + "$" + _pin_hash(pin, salt)})
        s.commit()
        return JSONResponse({"ok": True})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/pin/forgot")
async def app_pin_forgot(req: Request) -> JSONResponse:
    """Zapomenutý PIN → SMS kód na ověřený mobil (rate limit 3 SMS / 15 min)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    import secrets as _sec
    from modules.notifications.application.sms_service import queue_sms
    cm, s = _att_session()
    try:
        phone = s.execute(_t(
            "SELECT contact_value FROM public.user_contacts "
            "WHERE user_id = :u AND contact_type = 'phone' "
            "  AND COALESCE(status,'active') = 'active' "
            "ORDER BY COALESCE(is_verified,false) DESC, "
            "         COALESCE(is_primary,false) DESC, id LIMIT 1"),
            {"u": uid}).scalar()
        if not phone:
            s.commit()
            return JSONResponse({"ok": False, "error": "no_phone",
                                 "note": "Nemáš u nás ověřený mobil — ozvi se prosím Marti."})
        cnt = s.execute(_t(
            "SELECT count(*) FROM fw.phone_verify_code "
            "WHERE user_id = :u AND created_at > now() - interval '15 minutes'"),
            {"u": uid}).scalar() or 0
        if cnt >= 3:
            s.commit()
            return JSONResponse({"ok": False, "error": "rate_limited",
                                 "note": "Příliš mnoho SMS. Zkus to za 15 minut."})
        s.execute(_t("UPDATE fw.phone_verify_code SET used_at = now() "
                     "WHERE user_id = :u AND used_at IS NULL"), {"u": uid})
        code = f"{_sec.randbelow(1000000):06d}"
        s.execute(_t(
            "INSERT INTO fw.phone_verify_code (user_id, phone, code, expires_at) "
            "VALUES (:u, :p, :c, now() + interval '10 minutes')"),
            {"u": uid, "p": phone, "c": code})
        s.commit()
        queue_sms(to=phone,
                  body=f"STRATEGIE: kod pro obnovu PIN je {code}. Plati 10 minut.",
                  purpose="pin_reset", user_id=uid)
        masked = ("*" * max(len(phone) - 3, 0)) + phone[-3:]
        return JSONResponse({"ok": True, "phone": masked})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/payslip")
async def app_payslip(req: Request) -> JSONResponse:
    """Marti 7.6.: výplatní páska — PŘÍSNĚ jen vlastní data (uid → employee).
    Body {y, m, pin}; bez y/m poslední dostupné období. POST kvůli PINu v body
    (nativní authedFetch neumí custom headers). Ochrana (Marti 7.6. večer):
    jen mimo běžící směnu + 4místný PIN."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        body = await req.json()
    except Exception:
        body = {}
    cm, s = _att_session()
    try:
        emps = [r[0] for r in s.execute(_t(
            "SELECT id FROM tenant.att_employee WHERE tenant_id = 2 AND user_id = :u"),
            {"u": uid}).fetchall()]
        if not emps:
            s.commit()
            return JSONResponse({"ok": True, "periods": [], "items": [], "note": "Žádné mzdové záznamy."})
        # Marti 14.6.: Gate „běžící směna" ZRUŠEN — páska se otevírá rovnou přes PIN
        # (PIN je dostatečná ochrana; bránit otevření během směny jen otravovalo).
        # Gate — PIN (v ambasadorském režimu DEMO PIN bez SMS).
        err = _amb_or_pin_gate(s, uid, str((body or {}).get("pin") or ""), req)
        if err:
            s.commit()
            return JSONResponse(err)
        periods = s.execute(_t(
            "SELECT DISTINCT rok, mesic FROM tenant.payslip_item "
            "WHERE tenant_id = 2 AND employee_id = ANY(:e) "
            "ORDER BY rok DESC, mesic DESC LIMIT 24"), {"e": emps}).fetchall()
        if not periods:
            s.commit()
            return JSONResponse({"ok": True, "periods": [], "items": [], "note": "Zatím žádné pásky."})
        try:
            y = int((body or {}).get("y") or req.query_params.get("y") or 0)
            m = int((body or {}).get("m") or req.query_params.get("m") or 0)
        except Exception:
            y = m = 0
        if not (y and m):
            y, m = int(periods[0][0]), int(periods[0][1])
        rows = s.execute(_t(
            "SELECT c.code, COALESCE(c.nazev, c.code), p.cislo_ms, "
            "       COALESCE(p.nazev_ms, 'složka ' || p.cislo_ms), "
            "       p.koruny, p.hodiny, p.dny, p.je_hruba "
            "FROM tenant.payslip_item p "
            "LEFT JOIN tenant.company c ON c.id = p.company_id "
            "WHERE p.tenant_id = 2 AND p.employee_id = ANY(:e) AND p.rok = :y AND p.mesic = :m "
            "ORDER BY c.code, p.cislo_ms"), {"e": emps, "y": y, "m": m}).fetchall()
        # Mzdový LIST k pásce (Marti 26.6.2026) — savepoint, ať chybějící tabulka nerozbije pásku
        mzdovy_list = []
        try:
            with s.begin_nested():
                lrows = s.execute(_t(
                    "SELECT c.code, ps.tydenni_uvazek, ps.denni_uvazek, ps.zakladni_mzda,"
                    " ps.zdrav_pojistovna, ps.prum_vydelek, ps.prum_vydelek_hod, ps.dov_prumer,"
                    " ps.fond_dny, ps.fond_hod, ps.odprac_dny, ps.odprac_hod, ps.prescas_hod,"
                    " ps.svatek_tarif_hod, ps.svatek_nahrada_hod "
                    "FROM tenant.payslip_sheet ps LEFT JOIN tenant.company c ON c.id = ps.company_id "
                    "WHERE ps.tenant_id=2 AND ps.employee_id = ANY(:e) AND ps.rok=:y AND ps.mesic=:m "
                    "ORDER BY c.code"), {"e": emps, "y": y, "m": m}).fetchall()
            mzdovy_list = [{"firma": lr[0],
                            "tydenni_uvazek": (float(lr[1]) if lr[1] is not None else None),
                            "denni_uvazek": (float(lr[2]) if lr[2] is not None else None),
                            "zakladni_mzda": (float(lr[3]) if lr[3] is not None else None),
                            "zdrav_pojistovna": lr[4],
                            "prum_vydelek": (float(lr[5]) if lr[5] is not None else None),
                            "prum_vydelek_hod": (float(lr[6]) if lr[6] is not None else None),
                            "dov_prumer": (float(lr[7]) if lr[7] is not None else None),
                            "fond_dny": (float(lr[8]) if lr[8] is not None else None),
                            "fond_hod": (float(lr[9]) if lr[9] is not None else None),
                            "odprac_dny": (float(lr[10]) if lr[10] is not None else None),
                            "odprac_hod": (float(lr[11]) if lr[11] is not None else None),
                            "prescas_hod": (float(lr[12]) if lr[12] is not None else None),
                            "svatek_tarif_hod": (float(lr[13]) if lr[13] is not None else None),
                            "svatek_nahrada_hod": (float(lr[14]) if lr[14] is not None else None)}
                           for lr in lrows]
        except Exception:
            mzdovy_list = []
        jmeno = s.execute(_t(
            "SELECT COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')),''), u.login_name) "
            "FROM public.users u WHERE u.id = :u"), {"u": uid}).scalar() or ""
        s.commit()
        items = [{"firma": r[0], "firma_nazev": r[1], "ms": r[2], "nazev": r[3],
                  "kc": (float(r[4]) if r[4] is not None else None),
                  "hod": (float(r[5]) if r[5] is not None else None),
                  "dny": (float(r[6]) if r[6] is not None else None),
                  "hruba": bool(r[7])} for r in rows]
        return JSONResponse({"ok": True, "y": y, "m": m, "jmeno": jmeno,
                             "periods": [{"y": int(p[0]), "m": int(p[1])} for p in periods],
                             "items": items, "list": mzdovy_list})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/attendance/dispute-day")
async def att_dispute_day(req: Request) -> JSONResponse:
    """Marti 7.6.: „Musím mít volbu — něco se mi na docházce nezdá." Den se
    místo potvrzení ROZPORUJE (s poznámkou) → odblokuje příchod (zodpovědnost
    splněna ozváním se), kontrola docházky dostane notifikaci a řeší."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    from datetime import datetime as _dt
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        day = _dt.strptime(str((body or {}).get("day") or "")[:10], "%Y-%m-%d").date()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid_day"}, status_code=400)
    note = str((body or {}).get("note") or "").strip()[:500]
    cm, s = _att_session()
    try:
        emp = _att_employee(s, uid)
        s.execute(_t(
            "INSERT INTO tenant.att_day_confirm (tenant_id, employee_id, day, confirmed_by_user_id, disputed, note) "
            "VALUES (:t, :e, :d, :u, true, :n) "
            "ON CONFLICT (tenant_id, employee_id, day) DO UPDATE SET disputed = true, note = EXCLUDED.note"),
            {"t": _ATT_TENANT, "e": emp, "d": day.isoformat(), "u": uid, "n": note or None})
        # Marti 7.7.: rozporovaný den je taky vyřešený → zhasni vlastní připomínku
        # „🖊 Potvrď si docházku" a ukliď anomálii nepotvrzeného dne.
        s.execute(_t(
            "DELETE FROM tenant.att_anomaly a USING tenant.att_entry e "
            "WHERE a.tenant_id = :t AND a.rule = 'nepotvrzeny_den' AND a.employee_id = :e "
            "  AND e.id = a.entry_id AND e.entry_date = :d"),
            {"t": _ATT_TENANT, "e": emp, "d": day.isoformat()})
        s.execute(_t(
            "UPDATE fw.mobile_command SET status='done', decided_at=now() "
            "WHERE target_user_id = :u AND command_type = 'claude_msg' AND status = 'pending' "
            "  AND title LIKE '%Potvrď si docházku%' AND message LIKE :dp"),
            {"u": uid, "dp": day.strftime("%d.%m.") + "%"})
        # Marti 10.7.: rozpory chodí editorům oprav dle působnosti (kancelář/výroba),
        # už NE Martimu/supervizorovi. Fallback {1}, kdyby editoři nebyli k nalezení.
        who = s.execute(_t(
            "SELECT COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')),''), em.full_name) "
            "FROM tenant.att_employee em LEFT JOIN public.users u ON u.id = em.user_id WHERE em.id = :e"),
            {"e": emp}).scalar() or ("zaměstnanec " + str(emp))
        targets = _att_fix_editors_for_emp(s, emp) or {1}
        msg = (who + " rozporoval docházku za " + str(day.day) + ". " + str(day.month) + "."
               + ((" — „" + note + "“") if note else "") + " Mrkni na záznamy a doladěte to spolu.")
        for uid2 in sorted(targets):
            s.execute(_t(
                "INSERT INTO fw.mobile_command (app_key, target_user_id, command_type, title, message, created_by) "
                "VALUES ('mobile', :uid, 'claude_msg', :ti, :msg, NULL)"),
                {"uid": uid2, "ti": "✋ Rozporovaná docházka", "msg": msg[:600]})
        s.commit()
        return JSONResponse({"ok": True, "day": day.isoformat(), "disputed": True})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


