@api_router.post("/app/hr/att-source")
async def app_hr_att_source_set(req: Request) -> JSONResponse:
    """Přepínač docházkového zdroje pro člověka (rodiče + HR). app_only=true →
    (A) EC sync ho přeskočí + (B) zablokuje píchání v Centrále. false = zase povolí."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        body = await req.json()
    except Exception:
        body = {}
    tgt = int(body.get("user_id") or 0)
    app_only = bool(body.get("app_only"))
    if not tgt:
        return JSONResponse({"ok": False, "error": "bad_user_id"}, status_code=400)
    cm, s = _att_session()
    try:
        if not _hr_can_manage(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        autor = s.execute(_t("SELECT NULLIF(TRIM(COALESCE(first_name,'')||' '||COALESCE(last_name,'')),'') "
                             "FROM public.users WHERE id=:u"), {"u": uid}).scalar() or "HR"
        s.execute(_t(
            "INSERT INTO tenant.att_source_pref (user_id, app_only, changed_by, changed_at) "
            "VALUES (:u, :a, :by, now()) "
            "ON CONFLICT (user_id) DO UPDATE SET app_only=:a, changed_by=:by, changed_at=now()"),
            {"u": tgt, "a": app_only, "by": autor})
        cislo = s.execute(_t("SELECT cislo_zam FROM tenant.att_employee "
                             "WHERE tenant_id=2 AND user_id=:u AND cislo_zam IS NOT NULL LIMIT 1"),
                          {"u": tgt}).scalar()
        ec_ok, ec_err = (None, None)
        if cislo:
            ec_ok, ec_err = _ec_set_block_dochazka(cislo, app_only, actor_uid=uid, actor_name=autor)
            s.execute(_t("UPDATE tenant.att_source_pref SET ec_blocked=:b WHERE user_id=:u"),
                      {"b": bool(ec_ok), "u": tgt})
        s.commit()
        return JSONResponse({"ok": True, "app_only": app_only,
                             "ec_blocked": bool(ec_ok), "ec_error": ec_err})
    except Exception as exc:
        s.rollback()
        logger.exception("[att-source] failed: %s", exc)
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/admin/apid/backups")
async def app_apid_backups(req: Request) -> JSONResponse:
    """Marti 16.6.: seznam dostupných záloh data_db (jen rodiče) + stav poslední
    obnovy do API D. Zálohy jsou na DATOVÉM serveru (.12), proto se NEčtou z disku
    API, ale z tabulky fw.apid_backup, kterou plní watcher na .12."""
    from sqlalchemy import text as _t
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        _require_admin(uid)
    except Exception:
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    cm, s = _att_session()
    try:
        rows = s.execute(_t(
            "SELECT name, COALESCE(dir,''), size_mb, to_char(mtime,'DD.MM.YYYY HH24:MI') "
            "FROM fw.apid_backup ORDER BY mtime DESC NULLS LAST, name")).fetchall()
        items = [{"name": r[0], "dir": r[1], "size_mb": (float(r[2]) if r[2] is not None else None),
                  "mtime": r[3] or ""} for r in rows]
        last = s.execute(_t(
            "SELECT file, status, result, to_char(finished_at,'DD.MM HH24:MI') "
            "FROM fw.apid_restore_req WHERE status IN ('done','error') "
            "ORDER BY finished_at DESC LIMIT 1")).first()
        status = None
        if last:
            status = {"ok": (last[1] == "done"), "file": last[0], "finished": last[3] or "",
                      "result": last[2] or ""}
        pending = bool(s.execute(_t(
            "SELECT 1 FROM fw.apid_restore_req WHERE status IN ('pending','running') LIMIT 1")).first())
        listed = s.execute(_t("SELECT to_char(max(listed_at),'DD.MM HH24:MI') FROM fw.apid_backup")).scalar()
        return JSONResponse({"ok": True, "items": items, "status": status,
                             "pending": pending, "listed_at": listed or ""})
    except Exception as exc:
        # tabulka ještě neexistuje / watcher nepublikoval
        return JSONResponse({"ok": True, "items": [], "status": None, "pending": False,
                             "listed_at": "", "note": str(exc)})
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/admin/apid/restore")
async def app_apid_restore(req: Request) -> JSONResponse:
    """Zařadí obnovu vybrané zálohy do API D (řádek do fw.apid_restore_req). Jen rodiče.
    Watcher na datovém serveru (.12) ji vezme, obnoví do data_db_test. Produkce se NEDOTKNE."""
    from sqlalchemy import text as _t
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        _require_admin(uid)
    except Exception:
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        body = await req.json()
    except Exception:
        body = {}
    fname = (str(body.get("file") or "")).strip()
    cm, s = _att_session()
    try:
        if not fname or not s.execute(_t("SELECT 1 FROM fw.apid_backup WHERE name=:n"),
                                      {"n": fname}).first():
            return JSONResponse({"ok": False, "error": "Neplatný soubor zálohy."}, status_code=400)
        # pojistka: neřaď duplicitní obnovu, když už jedna běží/čeká (anti-backlog z opakovaných kliků)
        if s.execute(_t("SELECT 1 FROM fw.apid_restore_req WHERE status IN ('pending','running') LIMIT 1")).first():
            return JSONResponse({"ok": False, "error": "Obnova už probíhá — počkej, než dojede (~1 min), pak klikni znovu."}, status_code=409)
        s.execute(_t("INSERT INTO fw.apid_restore_req (file, requested_by, status) "
                     "VALUES (:f, :u, 'pending')"), {"f": fname, "u": uid})
        s.commit()
        return JSONResponse({"ok": True, "queued": fname,
                             "info": "Obnova zařazena. Watcher na datovém serveru ji zpracuje (~1-3 min). Stav se objeví v seznamu."})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


