@api_router.post("/app/plan/approvals/reapply")
async def app_plan_approvals_reapply(req: Request) -> JSONResponse:
    """Promítne do plánu všechny schválené, dosud nepromítnuté korekce (hodiny/volno).
    Idempotentní — co projde, dostane applied_at. Vrací počet + případné chyby."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        if not _can_approve_plans(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        rows = s.execute(_t(
            "SELECT id, user_id, req_date::text, kind, hours, start_time::text "
            "FROM tenant.att_plan_request WHERE tenant_id=:t AND status='approved' "
            "  AND applied_at IS NULL AND kind IN ('hours','off') ORDER BY req_date, id"),
            {"t": _ATT_TENANT}).fetchall()
        done = 0
        errs = []
        for r in rows:
            try:
                _apply_plan_correction(s, r[1], r[2], r[3], r[4], r[5], uid)
                s.execute(_t("UPDATE tenant.att_plan_request SET applied_at=now() WHERE id=:i AND tenant_id=:t"),
                          {"i": r[0], "t": _ATT_TENANT})
                done += 1
            except Exception as e:
                errs.append({"id": r[0], "error": str(e)[:200]})
        s.commit()
        return JSONResponse({"ok": True, "applied": done, "errors": errs})
    except Exception as exc:
        try:
            s.rollback()
        except Exception:
            pass
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/attendance/announce-delete")
async def att_announce_delete(req: Request) -> JSONResponse:
    """Marti 10.6.: smazání hlášené (budoucí) nepřítomnosti — supersedne řádek
    + zapíše do tenant.att_audit (kdo/co/kdy/původní hodnota). Jen vlastní."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        eid = int((body or {}).get("id") or 0)
    except Exception:
        eid = 0
    if eid <= 0:
        return JSONResponse({"ok": False, "error": "missing_id"}, status_code=400)
    cm, s = _att_session()
    try:
        emp = _att_employee(s, uid)
        row = s.execute(_t("SELECT entry_date::text, note FROM tenant.att_entry "
                           "WHERE id=:i AND tenant_id=:t AND employee_id=:e"),
                        {"i": eid, "t": _ATT_TENANT, "e": emp}).first()
        if not row:
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        actor = s.execute(_t("SELECT trim(coalesce(first_name,'')||' '||coalesce(last_name,'')) "
                             "FROM public.users WHERE id=:u"), {"u": uid}).scalar() or ("user " + str(uid))
        s.execute(_t("INSERT INTO tenant.att_audit (tenant_id, entry_id, employee_id, action, "
                     "actor_user_id, actor_text, old_entry_date, old_note, detail, created_at) "
                     "VALUES (:t,:i,:e,'delete',:u,:at,CAST(:d AS date),:n,'smazano z mobilu',now())"),
                  {"t": _ATT_TENANT, "i": eid, "e": emp, "u": uid, "at": actor,
                   "d": row[0], "n": row[1]})
        s.execute(_t("UPDATE tenant.att_entry SET status='superseded', is_active=false, updated_at=now() "
                     "WHERE id=:i AND tenant_id=:t AND employee_id=:e"),
                  {"i": eid, "t": _ATT_TENANT, "e": emp})
        s.commit()
        return JSONResponse({"ok": True})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


# ── Detail dne + samoobsluha záznamů (Marti 7.6. večer) ──────────────────
# „Raději chci vidět detaily…" — redukci času akceptujeme (zapomenutý odchod
# si zkrátí sám), cokoliv jiného = poznámka na záznam → kontrola docházky.

@api_router.get("/app/attendance/day-detail")
async def att_day_detail(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    from datetime import datetime as _dt
    try:
        day = _dt.strptime(str(req.query_params.get("day") or "")[:10], "%Y-%m-%d").date()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid_day"}, status_code=400)
    cm, s = _att_session()
    try:
        # Marti 19.6.: lze zobrazit i denní joby jiného člověka (👁 v panelu skupin).
        # Stejná viditelnost jako /app/skupina/lidi ("zatím vidí všichni vše") — read-only seznam jobů.
        target = uid
        tu = req.query_params.get("user_id")
        if tu and int(tu) != uid:
            target = int(tu)
        emp = _att_employee(s, target)
        rows = s.execute(_t(
            "SELECT e.id, to_char(e.started_at,'HH24:MI'), to_char(e.ended_at,'HH24:MI'), "
            "       e.hours, e.project_ref, e.note, et.label, et.code, et.category "
            "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id = e.entry_type_id "
            "WHERE e.tenant_id = :t AND e.employee_id = :e AND e.entry_date = :d "
            "AND e.status NOT IN ('superseded','announced') "
            "AND et.code <> 'day_end' "  # day_end = interní marker do 23:59, nezobrazovat lidem (Marti 19.6.)
            "ORDER BY e.started_at NULLS LAST, e.id"),
            {"t": _ATT_TENANT, "e": emp, "d": day.isoformat()}).fetchall()
        s.commit()
        return JSONResponse({"ok": True, "entries": [
            {"id": r[0], "zac": r[1], "kon": r[2],
             "hours": (float(r[3]) if r[3] is not None else None),
             "project_ref": r[4], "note": r[5], "typ": r[6],
             "code": r[7], "cat": r[8]} for r in rows]})
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/attendance/entry-trim")
async def att_entry_trim(req: Request) -> JSONResponse:
    """Redukce času záznamu (zapomenutý odchod apod.) — JEN zkrácení konce,
    mezi začátkem a původním koncem. Původní čas zůstává v poznámce."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    import re as _re
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        eid = int((body or {}).get("id") or 0)
    except Exception:
        eid = 0
    endt = str((body or {}).get("end") or "").strip()[:5]
    logger.warning("ENTRY-TRIM | start | uid=%s id=%s end=%r", uid, (body or {}).get("id"), endt)
    if not (eid and _re.fullmatch(r"[0-2][0-9]\x3a[0-5][0-9]", endt)):
        logger.warning("ENTRY-TRIM | invalid time | uid=%s end=%r", uid, endt)
        return JSONResponse({"ok": False, "error": "Neplatný čas."})
    cm, s = _att_session()
    try:
        row = s.execute(_t(
            "SELECT e.id, to_char(e.ended_at,'HH24:MI') "
            "FROM tenant.att_entry e JOIN tenant.att_employee em ON em.id = e.employee_id "
            "WHERE e.id = :i AND em.tenant_id = :t AND em.user_id = :u"),
            {"i": eid, "t": _ATT_TENANT, "u": uid}).first()
        if not row:
            s.commit()
            return JSONResponse({"ok": False, "error": "Záznam nenalezen."})
        if not row[1]:
            s.commit()
            return JSONResponse({"ok": False, "error": "Běžící záznam zkrátit nejde — nejdřív se odpíchni."})
        nn = "zkráceno uživatelem (původně do " + row[1] + ")"
        # Marti 7.6. večer fix: nový konec na DEN PŮVODNÍHO KONCE (ne entry_date) —
        # job přes půlnoc (start 6.6. večer, konec 7.6. ráno) jinak nešel zkrátit.
        upd = s.execute(_t(
            "UPDATE tenant.att_entry e SET "
            "  ended_at = (e.ended_at::date::text || ' ' || :endt)::timestamp, "
            "  hours = round(GREATEST(EXTRACT(EPOCH FROM ((e.ended_at::date::text || ' ' || :endt)::timestamp - e.started_at))/3600.0 "
            "        - COALESCE(e.break_minutes,0)/60.0, 0)::numeric,2), "
            "  note = CASE WHEN COALESCE(e.note,'') = '' THEN :nn ELSE e.note || ' / ' || :nn END, "
            "  updated_at = now() "
            "WHERE e.id = :i "
            "  AND (e.ended_at::date::text || ' ' || :endt)::timestamp > e.started_at "
            "  AND (e.ended_at::date::text || ' ' || :endt)::timestamp < e.ended_at "
            "RETURNING e.id"),
            {"i": eid, "endt": endt, "nn": nn}).first()
        s.commit()
        if not upd:
            logger.warning("ENTRY-TRIM | guard fail (ne-redukce) | uid=%s id=%s end=%s puvodni=%s", uid, eid, endt, row[1])
            return JSONResponse({"ok": False, "error": "Čas jde jen ZKRÁTIT — mezi začátkem a původním koncem (" + row[1] + ")."})
        logger.warning("ENTRY-TRIM | OK | uid=%s id=%s end=%s", uid, eid, endt)
        return JSONResponse({"ok": True, "id": eid})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/attendance/entry-project")
async def att_entry_project(req: Request) -> JSONResponse:
    """Marti 7.6. večer: špatné číslo zakázky na jobu — user si ho změní sám.
    Validace proti tenant.zakazka (píchatelné), typ REZIE → overhead. Původní
    zakázka zůstává v poznámce."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        eid = int((body or {}).get("id") or 0)
    except Exception:
        eid = 0
    ref = str((body or {}).get("project_ref") or "").strip()[:40]
    if not (eid and ref):
        return JSONResponse({"ok": False, "error": "Chybí zakázka."})
    cm, s = _att_session()
    try:
        row = s.execute(_t(
            "SELECT e.id, e.project_ref, COALESCE(e.note,''), COALESCE(et.label,'') FROM tenant.att_entry e "
            "JOIN tenant.att_employee em ON em.id = e.employee_id "
            "LEFT JOIN tenant.att_entry_type et ON et.id = e.entry_type_id "
            "WHERE e.id = :i AND em.tenant_id = :t AND em.user_id = :u"),
            {"i": eid, "t": _ATT_TENANT, "u": uid}).first()
        if not row:
            s.commit()
            return JSONResponse({"ok": False, "error": "Záznam nenalezen."})
        # Marti 11.6.: neproduktivní záznam (pauza/relax/oběd/jednání/pochůzka/lékař)
        # nesmí nést číslo zakázky.
        import re as _re_np
        if _re_np.search(r"pauz|relax|energ|j[íi]dl|prov[ěe]tr|naj[íi]st|ob[ěe]d|jedn[aá]n|poch[uů]z|l[ée]ka[řr]|doktor",
                         ((row[2] or "") + " " + (row[3] or "")).lower()):
            s.commit()
            return JSONResponse({"ok": False, "error": "Neproduktivní záznam (pauza/relax) nemůže nést zakázku."})
        zak = s.execute(_t(
            "SELECT typ FROM tenant.zakazka WHERE tenant_id = :t AND cislo = :c AND pichatelna = true"),
            {"t": _ATT_TENANT, "c": ref}).first()
        if not zak:
            s.commit()
            return JSONResponse({"ok": False, "error": "Zakázka " + ref + " není píchatelná / neexistuje."})
        tcode = "overhead" if (zak[0] == "REZIE") else "work"
        # Marti 12.6.: oprava na režii = skupina Režie, ale číslo zakázky do jobu necpat.
        stored_ref = None if (zak[0] == "REZIE") else ref
        nn = ("zakázka změněna uživatelem (původně " + (row[1] or "žádná") + ")")
        s.execute(_t(
            "UPDATE tenant.att_entry SET project_ref = :c, "
            "entry_type_id = COALESCE((SELECT id FROM tenant.att_entry_type WHERE tenant_id = :t AND code = :tc), entry_type_id), "
            "note = CASE WHEN COALESCE(note,'') = '' THEN :nn ELSE note || ' / ' || :nn END, "
            "updated_at = now() WHERE id = :i"),
            {"c": stored_ref, "t": _ATT_TENANT, "tc": tcode, "nn": nn, "i": eid})
        s.commit()
        return JSONResponse({"ok": True, "id": eid, "project_ref": stored_ref})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/attendance/entry-dispute")
async def att_entry_dispute(req: Request) -> JSONResponse:
    """„Na tomhle jobu je něco špatně" — poznámka na záznam + notifikace
    kontrole docházky (resolver) a tatínkovi jako anchor."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        eid = int((body or {}).get("id") or 0)
    except Exception:
        eid = 0
    note = str((body or {}).get("note") or "").strip()[:500]
    if not (eid and note):
        return JSONResponse({"ok": False, "error": "Napiš prosím, co nesedí."})
    cm, s = _att_session()
    try:
        row = s.execute(_t(
            "SELECT e.id, e.entry_date::text, to_char(e.started_at,'HH24:MI'), "
            "       to_char(e.ended_at,'HH24:MI'), e.employee_id "
            "FROM tenant.att_entry e JOIN tenant.att_employee em ON em.id = e.employee_id "
            "WHERE e.id = :i AND em.tenant_id = :t AND em.user_id = :u"),
            {"i": eid, "t": _ATT_TENANT, "u": uid}).first()
        if not row:
            s.commit()
            return JSONResponse({"ok": False, "error": "Záznam nenalezen."})
        nn = "✋ ROZPOR: " + note
        s.execute(_t(
            "UPDATE tenant.att_entry SET note = CASE WHEN COALESCE(note,'') = '' THEN :nn "
            "ELSE note || ' / ' || :nn END, updated_at = now() WHERE id = :i"),
            {"nn": nn, "i": eid})
        # Rozpor na jobu = zodpovědnost za den splněna → den označit disputed
        # (odblokuje nový příchod — denní tlačítko bylo zrušeno, tohle ho nahrazuje).
        s.execute(_t(
            "INSERT INTO tenant.att_day_confirm (tenant_id, employee_id, day, confirmed_by_user_id, disputed, note) "
            "VALUES (:t, :e, :d, :u, true, :n) "
            "ON CONFLICT (tenant_id, employee_id, day) DO UPDATE SET disputed = true"),
            {"t": _ATT_TENANT, "e": int(row[4]), "d": str(row[1]), "u": uid, "n": note[:300]})
        who = _user_jmeno(s, uid)
        # Marti 10.7.: rozpor na jobu → editorům oprav dle působnosti, ne Martimu.
        targets = _att_fix_editors_for_emp(s, int(row[4])) or {1}
        msg = (who + " hlásí problém na záznamu " + str(row[1]) + " "
               + (row[2] or "?") + "–" + (row[3] or "…") + " — „" + note + "“")
        for uid2 in sorted(targets):
            s.execute(_t(
                "INSERT INTO fw.mobile_command (app_key, target_user_id, command_type, title, message, created_by) "
                "VALUES ('mobile', :uid, 'claude_msg', :ti, :msg, NULL)"),
                {"uid": uid2, "ti": "✋ Problém na záznamu docházky", "msg": msg[:600]})
        s.commit()
        return JSONResponse({"ok": True})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


# ---------------------------------------------------------------------------
# OPRAVY DOCHÁZKY POVĚŘENÝMI OSOBAMI (Jirka 9.7.2026, zadal Marti Pašek).
# Skupina staff_group 'DOCHÁZKA - OPRAVY' (bez parent/admin bypassu — „zpětně
# opravují jen jmenovaní"). Oprava = supersede původního řádku + nový řádek
# source='manual_fix' s povinným důvodem; audit tenant.att_audit; notifikace
# dotčenému (✋ může rozporovat). Zámek období tenant.att_period_lock (mzdy).
# Návrh: docs/dochazka_opravy_navrh.md. Konzultace Marti-AI 9.7. (msg 10626).
# ---------------------------------------------------------------------------

_ATT_FIX_GROUP = "DOCHÁZKA - OPRAVY"
_ATT_FIX_TYPES = ("work", "overhead", "homeoffice", "commute", "break")
_ATT_LOCK_UIDS = frozenset({18, 13})  # Peťa (mzdy/finance) + Šárka (HR) — Jirka 9.7.: „obě"


def _att_can_fix(s, uid) -> bool:
    """Členství ve skupině DOCHÁZKA - OPRAVY. Vědomě BEZ parent/admin bypassu."""
    if not uid:
        return False
    from sqlalchemy import text as _t
    m = s.execute(_t(
        "SELECT 1 FROM tenant.staff_group_member m JOIN tenant.staff_group g ON g.id=m.group_id "
        "WHERE g.tenant_id=2 AND COALESCE(g.archived,false)=false AND g.name=:g AND m.user_id=:u"),
        {"g": _ATT_FIX_GROUP, "u": uid}).first()
    return m is not None


def _att_fix_scope(s, uid):
    """Působnost editora oprav (rozhodl Marti, 10.7.2026): None = není editor;
    'vse' (Jirka) / 'vyroba' (Míša, Dušan) / 'kancelar' (Peťa). Zdroj:
    tenant.att_fix_scope; editor bez řádku = 'vse' (bezpečný default pilotu)."""
    if not _att_can_fix(s, uid):
        return None
    from sqlalchemy import text as _t
    try:
        sc = s.execute(_t("SELECT scope FROM tenant.att_fix_scope WHERE user_id=:u"),
                       {"u": uid}).scalar()
        return (sc or "vse")
    except Exception:
        s.rollback()
        return "vse"


def _att_fix_scope_emps(s, scope):
    """None = bez omezení (vše). Jinak set employee_id v působnosti editora:
    'vyroba' = podřízení Dušana Havláta (org podstrom pod jeho posty, user 41);
    'kancelar' = všichni ostatní; lidé BEZ aktivního org zařazení = OBĚ strany
    (Jirka 10.7., rozhodl Marti — hraniční lidi vidí kancelář i výroba)."""
    if scope in (None, "vse"):
        return None
    from sqlalchemy import text as _t
    rows = s.execute(_t(
        "WITH RECURSIVE dp AS ("
        "  SELECT a.post_id AS id FROM tenant.org_post_assign a"
        "  JOIN tenant.att_employee de ON de.id = a.employee_id"
        "  WHERE de.tenant_id=2 AND de.user_id=41 AND a.aktivni AND COALESCE(a.potencialni,false)=false"
        "  UNION"
        "  SELECT c.id FROM tenant.org_post c JOIN dp ON c.parent_post_id = dp.id"
        "), vyr AS ("
        "  SELECT DISTINCT a.employee_id FROM tenant.org_post_assign a"
        "  JOIN dp ON dp.id = a.post_id WHERE a.aktivni AND COALESCE(a.potencialni,false)=false"
        "), zar AS ("
        "  SELECT DISTINCT a.employee_id FROM tenant.org_post_assign a"
        "  WHERE a.aktivni AND COALESCE(a.potencialni,false)=false"
        ") "
        "SELECT e.id, (e.id IN (SELECT employee_id FROM vyr)), "
        "       (e.id IN (SELECT employee_id FROM zar)) "
        "FROM tenant.att_employee e WHERE e.tenant_id=2")).fetchall()
    out = set()
    for r in rows:
        eid, je_vyroba, ma_zarazeni = int(r[0]), bool(r[1]), bool(r[2])
        if not ma_zarazeni:
            out.add(eid)  # nezařazený → vidí ho obě strany
        elif scope == "vyroba" and je_vyroba:
            out.add(eid)
        elif scope == "kancelar" and not je_vyroba:
            out.add(eid)
    return out


def _att_fix_editors_for_emp(s, emp_id):
    """Editoři oprav, do jejichž působnosti osoba spadá (Marti 10.7.: chyby
    v docházce a rozpory lidí chodí Petře=kanceláře / Míše+Dušanovi=výroba,
    už NE Martimu). Správce se scope 'vse' se nenotifikuje. Vrací set user_id
    (může být prázdný — volající si řeší fallback)."""
    out = set()
    from sqlalchemy import text as _t
    try:
        rows = s.execute(_t(
            "SELECT f.user_id, f.scope FROM tenant.att_fix_scope f "
            "JOIN tenant.staff_group_member m ON m.user_id = f.user_id AND m.tenant_id = 2 "
            "JOIN tenant.staff_group g ON g.id = m.group_id AND g.tenant_id = 2 "
            "  AND COALESCE(g.archived,false) = false AND g.name = :g "
            "WHERE f.scope IN ('kancelar','vyroba')"),
            {"g": _ATT_FIX_GROUP}).fetchall()
        for sc in {r[1] for r in rows}:
            emps = _att_fix_scope_emps(s, sc)
            if emps is None or int(emp_id) in emps:
                out |= {int(r[0]) for r in rows if r[1] == sc}
    except Exception:
        pass
    return out


def _att_can_lock(s, uid) -> bool:
    """Zámek období smí Peťa/Šárka (Jirka 9.7. „obě") + rodiče."""
    if uid in _ATT_LOCK_UIDS:
        return True
    try:
        return bool(is_marti_parent(uid))
    except Exception:
        return False


def _att_period_locked(s, d) -> bool:
    """True = měsíc dne d je uzamčen (mzdy zpracovány). Bez tabulky (před DDL) → False."""
    from sqlalchemy import text as _t
    try:
        r = s.execute(_t("SELECT 1 FROM tenant.att_period_lock WHERE tenant_id=:t AND rok=:r AND mesic=:m"),
                      {"t": _ATT_TENANT, "r": d.year, "m": d.month}).first()
        return r is not None
    except Exception:
        s.rollback()
        return False


def _att_fix_audit(s, action, entry_id, emp_id, actor_uid, actor_name,
                   old_note=None, new_note=None, detail=None, old_date=None):
    from sqlalchemy import text as _t
    s.execute(_t(
        "INSERT INTO tenant.att_audit (tenant_id, entry_id, employee_id, action, "
        "actor_user_id, actor_text, old_entry_date, old_note, new_note, detail, created_at) "
        "VALUES (:t,:i,:e,:a,:u,:at,CAST(:d AS date),:onn,:nnn,:dt,now())"),
        {"t": _ATT_TENANT, "i": entry_id, "e": emp_id, "a": action, "u": actor_uid,
         "at": actor_name, "d": old_date, "onn": old_note, "nnn": new_note, "dt": detail})


def _att_fix_notify(s, emp_id, actor_uid, actor_name, title, msg):
    """Notifikace dotčenému (fw.mobile_command). Sám sobě editor nenotifikuje."""
    from sqlalchemy import text as _t
    try:
        r = s.execute(_t("SELECT user_id FROM tenant.att_employee WHERE id=:e"), {"e": emp_id}).first()
        emp_uid = int(r[0]) if (r and r[0]) else None
        if emp_uid and emp_uid != actor_uid:
            s.execute(_t(
                "INSERT INTO fw.mobile_command (app_key, target_user_id, command_type, title, message, created_by) "
                "VALUES ('mobile', :uid, 'claude_msg', :ti, :msg, :by)"),
                {"uid": emp_uid, "ti": title, "msg": msg[:600], "by": actor_uid})
    except Exception:
        pass


