@api_router.get("/app/attendance/fix/queue")
async def att_fix_queue(req: Request) -> JSONResponse:
    """Fronta „K vyřešení": nevyřešené anomálie (mimo nepotvrzený den — to je
    osobní zodpovědnost) + rozporované dny (✋). S návrhem konce u zapomenutého
    odchodu (poslední aktivita na zakázce)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        _sc = _att_fix_scope(s, uid)
        if _sc is None:
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        _emps = _att_fix_scope_emps(s, _sc)
        anom = s.execute(_t(
            "SELECT a.id, a.rule, a.detail, a.entry_id, a.employee_id, e.entry_date::text, "
            "       em.user_id, COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),''), em.full_name), "
            "       (SELECT to_char(max(w.ended_at),'HH24:MI') FROM tenant.work_alloc w "
            "         WHERE w.user_id = em.user_id AND w.started_at::date = e.entry_date AND w.ended_at IS NOT NULL), "
            "       EXISTS(SELECT 1 FROM tenant.att_entry fe WHERE fe.tenant_id=:t AND fe.employee_id=a.employee_id AND fe.entry_date=e.entry_date AND fe.source='manual_fix' AND fe.status<>'superseded') "
            "FROM tenant.att_anomaly a "
            "JOIN tenant.att_entry e ON e.id = a.entry_id "
            "JOIN tenant.att_employee em ON em.id = a.employee_id "
            "LEFT JOIN public.users u ON u.id = em.user_id "
            "WHERE a.tenant_id = :t AND a.resolved_at IS NULL AND a.rule <> 'nepotvrzeny_den' "
            "  AND e.status <> 'superseded' "
            "ORDER BY e.entry_date DESC, a.id DESC LIMIT 120"),
            {"t": _ATT_TENANT}).fetchall()
        disp = s.execute(_t(
            "SELECT c.id, c.employee_id, c.day::text, COALESCE(c.note,''), em.user_id, "
            "       COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),''), em.full_name), "
            "       EXISTS(SELECT 1 FROM tenant.att_entry fe WHERE fe.tenant_id=:t AND fe.employee_id=c.employee_id AND fe.entry_date=c.day AND fe.source='manual_fix' AND fe.status<>'superseded') "
            "FROM tenant.att_day_confirm c "
            "JOIN tenant.att_employee em ON em.id = c.employee_id "
            "LEFT JOIN public.users u ON u.id = em.user_id "
            "WHERE c.tenant_id = :t AND c.disputed = true AND c.day >= current_date - 60 "
            "ORDER BY c.day DESC LIMIT 60"),
            {"t": _ATT_TENANT}).fetchall()
        s.commit()
        if _emps is not None:  # působnost editora (kancelář/výroba)
            anom = [r for r in anom if int(r[4]) in _emps]
            disp = [r for r in disp if int(r[1]) in _emps]
        return JSONResponse({"ok": True,
            "anomalie": [{"id": r[0], "rule": r[1], "detail": r[2], "entry_id": r[3],
                          "employee_id": r[4], "day": r[5], "user_id": r[6], "name": r[7],
                          "navrh_konec": r[8], "opraveno": bool(r[9])} for r in anom],
            "rozpory": [{"id": r[0], "employee_id": r[1], "day": r[2], "note": r[3],
                         "user_id": r[4], "name": r[5], "opraveno": bool(r[6])} for r in disp]})
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/attendance/fix/day")
async def att_fix_day(req: Request) -> JSONResponse:
    """Detail dne pro editora — VŠECHNY záznamy vč. superseded (šedě) a day_end,
    s příznakem editovatelnosti (jen STRATEGIE řádky, neuzamčené období)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    from datetime import datetime as _dt
    cm, s = _att_session()
    try:
        _sc = _att_fix_scope(s, uid)
        if _sc is None:
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        try:
            day = _dt.strptime(str(req.query_params.get("day") or "")[:10], "%Y-%m-%d").date()
            tuid = int(req.query_params.get("uid") or 0)
        except Exception:
            return JSONResponse({"ok": False, "error": "invalid_params"}, status_code=400)
        emp = s.execute(_t("SELECT id FROM tenant.att_employee WHERE tenant_id=:t AND user_id=:u"),
                        {"t": _ATT_TENANT, "u": tuid}).scalar()
        if not emp:
            return JSONResponse({"ok": False, "error": "Osoba nemá docházkovou kartu."})
        _emps = _att_fix_scope_emps(s, _sc)
        if _emps is not None and int(emp) not in _emps:
            return JSONResponse({"ok": False, "error": "Osoba není ve tvé působnosti (kancelář/výroba)."}, status_code=403)
        locked = _att_period_locked(s, day)
        _lock_ovr = _att_can_lock(s, uid)
        rows = s.execute(_t(
            "SELECT e.id, to_char(e.started_at,'HH24:MI'), to_char(e.ended_at,'HH24:MI'), "
            "       e.hours, e.project_ref, e.note, et.label, et.code, et.category, "
            "       e.status, e.is_active, COALESCE(e.source_system,''), COALESCE(e.source,''), "
            "       (SELECT w.cinnost_name FROM tenant.work_alloc w WHERE w.user_id=:u AND w.cinnost_name IS NOT NULL "
            "          AND w.started_at >= e.started_at - interval '1 minute' AND w.started_at < COALESCE(e.ended_at, e.started_at + interval '1 minute') ORDER BY w.started_at LIMIT 1), "
            "       (SELECT w.cinnost_id FROM tenant.work_alloc w WHERE w.user_id=:u AND w.cinnost_id IS NOT NULL "
            "          AND w.started_at >= e.started_at - interval '1 minute' AND w.started_at < COALESCE(e.ended_at, e.started_at + interval '1 minute') ORDER BY w.started_at LIMIT 1) "
            "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id = e.entry_type_id "
            "WHERE e.tenant_id = :t AND e.employee_id = :e AND e.entry_date = :d "
            "AND e.status <> 'announced' "
            "ORDER BY e.started_at ASC NULLS LAST, e.id ASC"),
            {"t": _ATT_TENANT, "e": emp, "d": day.isoformat(), "u": tuid}).fetchall()
        jm = _user_jmeno(s, tuid)
        # Jirka 12.7.: rozpor dne (co člověk napsal přes ✋ Nesedí) — do panelu nad tabulkou
        disp = s.execute(_t(
            "SELECT COALESCE(note,''), disputed FROM tenant.att_day_confirm "
            "WHERE tenant_id=:t AND employee_id=:e AND day=:d"),
            {"t": _ATT_TENANT, "e": emp, "d": day.isoformat()}).first()
        s.commit()
        return JSONResponse({"ok": True, "person": jm, "employee_id": emp, "locked": locked, "lock_override": bool(locked and _lock_ovr),
            "dispute": ({"disputed": bool(disp[1]), "note": disp[0]} if disp else None),
            "entries": [
            {"id": r[0], "zac": r[1], "kon": r[2],
             "hours": (float(r[3]) if r[3] is not None else None),
             "project_ref": r[4], "note": r[5], "typ": r[6], "code": r[7], "cat": r[8],
             "status": r[9], "running": bool(r[10] and not r[2]),
             "source_system": r[11], "source": r[12], "cin_name": r[13], "cin_id": r[14],
             "editable": ((not locked) or _lock_ovr) and (not r[11]) and r[9] != "superseded"} for r in rows]})
    finally:
        cm.__exit__(None, None, None)


def _att_fix_parse_hhmm(v):
    import re as _re
    v = str(v or "").strip()[:5]
    return v if _re.fullmatch(r"[0-2][0-9]:[0-5][0-9]", v) else None


def _att_fix_overlap(s, emp, new_start, new_end, exclude_id):
    """Vrátí popis kolidujícího záznamu, nebo None. Porovnává jen presence
    segmenty s oběma časy; day_end marker se nepočítá."""
    from sqlalchemy import text as _t
    r = s.execute(_t(
        "SELECT to_char(e.started_at,'HH24:MI') || CHR(8211) || to_char(e.ended_at,'HH24:MI') || ' ' || et.label "
        "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id = e.entry_type_id "
        "WHERE e.tenant_id = :t AND e.employee_id = :e AND e.id <> :x "
        "  AND e.status NOT IN ('superseded','announced') AND et.code <> 'day_end' "
        "  AND et.category IN ('presence','break','travel') AND e.started_at IS NOT NULL AND e.ended_at IS NOT NULL "
        "  AND date_trunc('minute', e.started_at) < CAST(:ne AS timestamp) AND date_trunc('minute', e.ended_at) > CAST(:ns AS timestamp) LIMIT 1"),
        {"t": _ATT_TENANT, "e": emp, "x": exclude_id or 0,
         "ne": new_end.isoformat(sep=" "), "ns": new_start.isoformat(sep=" ")}).scalar()
    return r


@api_router.post("/app/attendance/fix/entry")
async def att_fix_entry(req: Request) -> JSONResponse:
    """Oprava časů/typu záznamu editorem: supersede původního + nový řádek
    source='manual_fix'. Povinný důvod. Srovná work_alloc, uklidí anomálie,
    audituje a notifikuje dotčeného."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    from datetime import datetime as _dt, timedelta as _td
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        eid = int((body or {}).get("id") or 0)
    except Exception:
        eid = 0
    zac = _att_fix_parse_hhmm((body or {}).get("zac"))
    kon = _att_fix_parse_hhmm((body or {}).get("kon"))
    tcode = str((body or {}).get("type_code") or "").strip() or None
    reason = str((body or {}).get("reason") or "").strip()[:300]
    try:
        cin_new = int((body or {}).get("cinnost_id") or 0) or None
    except Exception:
        cin_new = None
    # Jirka 12.7.: volitelná změna zakázky — klíč chybí = nechat původní (zpětně kompatibilní)
    pref_sent = isinstance(body, dict) and ("project_ref" in body)
    pref_new = (str((body or {}).get("project_ref") or "").strip()[:40] or None) if pref_sent else None
    if not (eid and zac and kon):
        return JSONResponse({"ok": False, "error": "Zadej platné časy od–do (HH:MM)."})
    if not reason:
        return JSONResponse({"ok": False, "error": "Důvod opravy je povinný."})
    if tcode and tcode not in _ATT_FIX_TYPES:
        return JSONResponse({"ok": False, "error": "Nepovolený typ záznamu."})
    cm, s = _att_session()
    try:
        if not _att_can_fix(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        row = s.execute(_t(
            "SELECT e.id, e.employee_id, e.entry_date, e.started_at, e.ended_at, "
            "       e.entry_type_id, et.code, e.project_ref, COALESCE(e.break_minutes,0), "
            "       e.status, COALESCE(e.source_system,''), e.is_active, "
            "       to_char(e.started_at,'HH24:MI'), COALESCE(to_char(e.ended_at,'HH24:MI'),'…'), et.label "
            "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id = e.entry_type_id "
            "WHERE e.id = :i AND e.tenant_id = :t"),
            {"i": eid, "t": _ATT_TENANT}).first()
        if not row:
            return JSONResponse({"ok": False, "error": "Záznam nenalezen."})
        if row[9] == "superseded":
            return JSONResponse({"ok": False, "error": "Záznam už byl nahrazen novější opravou."})
        if row[10]:
            return JSONResponse({"ok": False, "error": "Záznam vlastní stará Centrála — oprav ho v Centrále, sem se přezrcadlí."})
        if row[11] and row[4] is None:
            return JSONResponse({"ok": False, "error": "Běžící záznam nelze opravit — člověk zrovna maká (počkej na odchod)."})
        if row[3] is None:
            return JSONResponse({"ok": False, "error": "Záznam bez času začátku (absence) — oprav přes absence, ne tady."})
        if _att_period_locked(s, row[2]):
            if not _att_can_lock(s, uid):
                return JSONResponse({"ok": False, "error": "Tento měsíc je uzavřený (mzdy zpracovány) — opravu musí nejdřív povolit Peťa/Šárka odemčením období."}, status_code=409)
            reason = (reason + " [oprava v uzavřeném období]").strip()
        emp = int(row[1])
        _emps = _att_fix_scope_emps(s, _att_fix_scope(s, uid))
        if _emps is not None and emp not in _emps:
            return JSONResponse({"ok": False, "error": "Osoba není ve tvé působnosti (kancelář/výroba)."}, status_code=403)
        sd = row[3].date()
        ed = row[4].date() if row[4] is not None else sd
        # konec se drží na dni PŮVODNÍHO konce (job přes půlnoc — vzor entry-trim, Marti 7.6.)
        new_start = _dt.combine(sd, _dt.strptime(zac, "%H:%M").time())
        new_end = _dt.combine(ed, _dt.strptime(kon, "%H:%M").time())
        if new_end <= new_start:
            return JSONResponse({"ok": False, "error": "Konec musí být po začátku."})
        if (new_end - new_start) > _td(hours=20):
            return JSONResponse({"ok": False, "error": "Úsek přes 20 hodin — to nebude správně."})
        ovl = _att_fix_overlap(s, emp, new_start, new_end, eid)
        if ovl:
            return JSONResponse({"ok": False, "error": "Nové časy se překrývají se záznamem " + str(ovl) + "."})
        new_code = tcode or row[6]
        tid = s.execute(_t("SELECT id FROM tenant.att_entry_type WHERE tenant_id=:t AND code=:c"),
                        {"t": _ATT_TENANT, "c": new_code}).scalar()
        if not tid:
            return JSONResponse({"ok": False, "error": "Typ záznamu nenalezen."})
        pref = row[7] if new_code in ("work",) else None
        if pref_sent and new_code == "work":
            if pref_new:
                zk = s.execute(_t("SELECT nazev FROM tenant.zakazka WHERE tenant_id=:t AND cislo=:c AND pichatelna=true"),
                               {"t": _ATT_TENANT, "c": pref_new}).first()
                if not zk:
                    return JSONResponse({"ok": False, "error": "Zakázka " + pref_new + " není píchatelná / neexistuje."})
            pref = pref_new
        brk = int(row[8])
        hrs = round(max((new_end - new_start).total_seconds() / 3600.0 - brk / 60.0, 0.0), 2)
        actor = _user_jmeno(s, uid)
        old_desc = (row[14] or "") + " " + (row[12] or "?") + "–" + (row[13] or "…")
        nn = "🛠 OPRAVA (" + actor + "): " + reason + " (původně " + old_desc.strip() + ", #" + str(eid) + ")"
        nid = s.execute(_t(
            "INSERT INTO tenant.att_entry (tenant_id, employee_id, entry_date, entry_type_id, hours, "
            "started_at, ended_at, break_minutes, project_ref, note, status, source, is_active, "
            "created_by_id, created_at, updated_at) "
            "VALUES (:t,:e,:d,:ti,:h,CAST(:ns AS timestamp),CAST(:ne AS timestamp),:b,:pr,:n,"
            "'approved','manual_fix',false,:u,now(),now()) RETURNING id"),
            {"t": _ATT_TENANT, "e": emp, "d": sd.isoformat(), "ti": tid, "h": hrs,
             "ns": new_start.isoformat(sep=" "), "ne": new_end.isoformat(sep=" "),
             "b": brk, "pr": pref, "n": nn, "u": uid}).scalar()
        s.execute(_t(
            "UPDATE tenant.att_entry SET status='superseded', is_active=false, "
            "note = CASE WHEN COALESCE(note,'')='' THEN :nn ELSE note || ' / ' || :nn END, updated_at=now() "
            "WHERE id=:i"),
            {"i": eid, "nn": "nahrazeno opravou #" + str(nid) + " (" + actor + ")"})
        # work_alloc: úseky zakázek patřící k původnímu segmentu zkrátit na nový konec
        if row[6] in ("work", "overhead") and row[4] is not None:
            try:
                tu = s.execute(_t("SELECT user_id FROM tenant.att_employee WHERE id=:e"), {"e": emp}).scalar()
                if tu:
                    s.execute(_t(
                        "UPDATE tenant.work_alloc SET "
                        "ended_at = GREATEST(CAST(:ns AS timestamptz), LEAST(ended_at, CAST(:ne AS timestamptz))), "
                        "started_at = LEAST(CAST(:ne AS timestamptz), GREATEST(started_at, CAST(:ns AS timestamptz))), "
                        "updated_at = now() "
                        "WHERE user_id=:u AND started_at >= CAST(:os AS timestamptz) - interval '1 minute' "
                        "  AND started_at < CAST(:oe AS timestamptz) "
                        "  AND (ended_at IS NULL OR ended_at > CAST(:ne AS timestamptz) OR started_at < CAST(:ns AS timestamptz))"),
                        {"u": tu, "ns": new_start.isoformat(sep=" "), "ne": new_end.isoformat(sep=" "),
                         "os": row[3].isoformat(sep=" "), "oe": row[4].isoformat(sep=" ")})
                    # Jirka 12.7.: změna zakázky → přepiš JEN úseky nesoucí PŮVODNÍ
                    # zakázku záznamu (multi-zakázková okna se nedotknou — pravda
                    # o segmentech je work_alloc, precedent Voříšek 27.6.)
                    if pref_sent and new_code == "work" and pref != row[7]:
                        s.execute(_t(
                            "UPDATE tenant.work_alloc SET project_ref = :np, "
                            "project_nazev = (SELECT z.nazev FROM tenant.zakazka z WHERE z.tenant_id = :t AND z.cislo = :np), "
                            "updated_at = now() "
                            "WHERE user_id=:u AND started_at >= CAST(:ns AS timestamptz) - interval '1 minute' "
                            "  AND started_at < CAST(:ne AS timestamptz) "
                            "  AND project_ref IS NOT DISTINCT FROM :op"),
                            {"t": _ATT_TENANT, "u": tu, "np": pref, "op": row[7],
                             "ns": new_start.isoformat(sep=" "), "ne": new_end.isoformat(sep=" ")})
            except Exception:
                pass
        if cin_new and new_code in ("work", "overhead"):
            try:
                _tu = s.execute(_t("SELECT user_id FROM tenant.att_employee WHERE id=:e"), {"e": emp}).scalar()
                _cn = s.execute(_t("SELECT name, COALESCE(icon,'') FROM tenant.vyroba_cinnost WHERE tenant_id=2 AND id=:c AND active"), {"c": cin_new}).first()
                if _tu and _cn:
                    s.execute(_t(
                        "UPDATE tenant.work_alloc SET cinnost_id=:ci, cinnost_name=:cn, cinnost_icon=:cic, updated_at=now() "
                        "WHERE user_id=:u AND started_at >= CAST(:ns AS timestamptz) - interval '1 minute' "
                        "  AND started_at < CAST(:ne AS timestamptz)"),
                        {"u": _tu, "ci": cin_new, "cn": _cn[0], "cic": _cn[1],
                         "ns": new_start.isoformat(sep=" "), "ne": new_end.isoformat(sep=" ")})
            except Exception:
                pass
        s.execute(_t("UPDATE tenant.att_anomaly SET resolved_at=now() "
                     "WHERE tenant_id=:t AND entry_id=:i AND resolved_at IS NULL"),
                  {"t": _ATT_TENANT, "i": eid})
        zm_zak = (" | zakázka " + (row[7] or "—") + " → " + (pref or "—")) if (pref_sent and new_code == "work" and pref != row[7]) else ""
        _att_fix_audit(s, "fix", nid, emp, uid, actor,
                       old_note=old_desc.strip(), new_note=(new_code + " " + zac + "–" + kon + ((" 🧾 " + pref) if pref else "")),
                       detail=reason + zm_zak + " | původní #" + str(eid), old_date=sd.isoformat())
        _att_fix_notify(s, emp, uid, actor, "🛠 Oprava docházky",
                        actor + " opravil(a) tvou docházku " + sd.strftime("%d.%m.") + ": "
                        + old_desc.strip() + " → " + zac + "–" + kon
                        + ((" (zakázka → " + pref + ")") if (pref_sent and new_code == "work" and pref != row[7] and pref) else "")
                        + " (" + reason + "). "
                        "Pokud to nesedí, otevři den v Docházce a dej ✋ Nesedí.")
        s.commit()
        return JSONResponse({"ok": True, "id": nid, "hours": hrs})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/attendance/fix/add")
async def att_fix_add(req: Request) -> JSONResponse:
    """Doplnění chybějícího záznamu (zapomenutý příchod) editorem."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    from datetime import datetime as _dt, timedelta as _td, date as _date
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        tuid = int((body or {}).get("uid") or 0)
    except Exception:
        tuid = 0
    zac = _att_fix_parse_hhmm((body or {}).get("zac"))
    kon = _att_fix_parse_hhmm((body or {}).get("kon"))
    tcode = str((body or {}).get("type_code") or "work").strip()
    try:
        cin_add = int((body or {}).get("cinnost_id") or 0) or None
    except Exception:
        cin_add = None
    pref = str((body or {}).get("project_ref") or "").strip()[:40] or None
    reason = str((body or {}).get("reason") or "").strip()[:300]
    try:
        day = _dt.strptime(str((body or {}).get("day") or "")[:10], "%Y-%m-%d").date()
    except Exception:
        return JSONResponse({"ok": False, "error": "Neplatné datum."})
    if not (tuid and zac and kon):
        return JSONResponse({"ok": False, "error": "Zadej osobu a časy od–do (HH:MM)."})
    if not reason:
        return JSONResponse({"ok": False, "error": "Důvod je povinný."})
    if tcode not in _ATT_FIX_TYPES:
        return JSONResponse({"ok": False, "error": "Nepovolený typ záznamu."})
    if day > _date.today():
        return JSONResponse({"ok": False, "error": "Do budoucnosti se nedoplňuje — na to je Výhled/ohlášení."})
    cm, s = _att_session()
    try:
        if not _att_can_fix(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        if _att_period_locked(s, day):
            if not _att_can_lock(s, uid):
                return JSONResponse({"ok": False, "error": "Tento měsíc je uzavřený (mzdy zpracovány) — přidání musí nejdřív povolit Peťa/Šárka odemčením období."}, status_code=409)
            reason = (reason + " [oprava v uzavřeném období]").strip()
        emp = s.execute(_t("SELECT id FROM tenant.att_employee WHERE tenant_id=:t AND user_id=:u"),
                        {"t": _ATT_TENANT, "u": tuid}).scalar()
        if not emp:
            return JSONResponse({"ok": False, "error": "Osoba nemá docházkovou kartu."})
        _emps = _att_fix_scope_emps(s, _att_fix_scope(s, uid))
        if _emps is not None and int(emp) not in _emps:
            return JSONResponse({"ok": False, "error": "Osoba není ve tvé působnosti (kancelář/výroba)."}, status_code=403)
        new_start = _dt.combine(day, _dt.strptime(zac, "%H:%M").time())
        new_end = _dt.combine(day, _dt.strptime(kon, "%H:%M").time())
        if new_end <= new_start:
            return JSONResponse({"ok": False, "error": "Konec musí být po začátku."})
        if (new_end - new_start) > _td(hours=20):
            return JSONResponse({"ok": False, "error": "Úsek přes 20 hodin — to nebude správně."})
        ovl = _att_fix_overlap(s, emp, new_start, new_end, None)
        if ovl:
            return JSONResponse({"ok": False, "error": "Časy se překrývají se záznamem " + str(ovl) + "."})
        if pref and tcode == "work":
            zk = s.execute(_t("SELECT typ FROM tenant.zakazka WHERE tenant_id=:t AND cislo=:c AND pichatelna=true"),
                           {"t": _ATT_TENANT, "c": pref}).first()
            if not zk:
                return JSONResponse({"ok": False, "error": "Zakázka " + pref + " není píchatelná / neexistuje."})
        else:
            pref = None
        tid = s.execute(_t("SELECT id FROM tenant.att_entry_type WHERE tenant_id=:t AND code=:c"),
                        {"t": _ATT_TENANT, "c": tcode}).scalar()
        if not tid:
            return JSONResponse({"ok": False, "error": "Typ záznamu nenalezen."})
        hrs = round((new_end - new_start).total_seconds() / 3600.0, 2)
        actor = _user_jmeno(s, uid)
        nn = "🛠 DOPLNĚNO (" + actor + "): " + reason
        nid = s.execute(_t(
            "INSERT INTO tenant.att_entry (tenant_id, employee_id, entry_date, entry_type_id, hours, "
            "started_at, ended_at, project_ref, note, status, source, is_active, "
            "created_by_id, created_at, updated_at) "
            "VALUES (:t,:e,:d,:ti,:h,CAST(:ns AS timestamp),CAST(:ne AS timestamp),:pr,:n,"
            "'approved','manual_fix',false,:u,now(),now()) RETURNING id"),
            {"t": _ATT_TENANT, "e": emp, "d": day.isoformat(), "ti": tid, "h": hrs,
             "ns": new_start.isoformat(sep=" "), "ne": new_end.isoformat(sep=" "),
             "pr": pref, "n": nn, "u": uid}).scalar()
        if tcode in ("work", "overhead"):
            try:
                _tu = s.execute(_t("SELECT user_id FROM tenant.att_employee WHERE id=:e"), {"e": emp}).scalar()
                _cn = s.execute(_t("SELECT name, COALESCE(icon,'') FROM tenant.vyroba_cinnost WHERE tenant_id=2 AND id=:c AND active"), {"c": cin_add}).first() if cin_add else None
                _pn = s.execute(_t("SELECT nazev FROM tenant.zakazka WHERE tenant_id=:t AND cislo=:c"), {"t": _ATT_TENANT, "c": pref}).scalar() if pref else None
                if _tu:
                    s.execute(_t(
                        "INSERT INTO tenant.work_alloc (tenant_id,user_id,started_at,ended_at,project_ref,project_nazev,"
                        "cinnost_id,cinnost_name,cinnost_icon,is_rezie,source,created_at,updated_at) "
                        "VALUES (:t,:u,CAST(:ns AS timestamptz),CAST(:ne AS timestamptz),:pr,:pn,:ci,:cn,:cic,:rz,'manual_fix',now(),now())"),
                        {"t": _ATT_TENANT, "u": _tu, "ns": new_start.isoformat(sep=" "), "ne": new_end.isoformat(sep=" "),
                         "pr": pref, "pn": _pn, "ci": cin_add, "cn": (_cn[0] if _cn else None), "cic": (_cn[1] if _cn else None),
                         "rz": (tcode == "overhead")})
            except Exception:
                pass
        _att_fix_audit(s, "add", nid, emp, uid, actor,
                       new_note=(tcode + " " + zac + "–" + kon), detail=reason,
                       old_date=day.isoformat())
        _att_fix_notify(s, emp, uid, actor, "🛠 Doplnění docházky",
                        actor + " doplnil(a) do tvé docházky " + day.strftime("%d.%m.") + " záznam "
                        + zac + "–" + kon + " (" + reason + "). "
                        "Pokud to nesedí, otevři den v Docházce a dej ✋ Nesedí.")
        s.commit()
        return JSONResponse({"ok": True, "id": nid, "hours": hrs})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/attendance/fix/void")
async def att_fix_void(req: Request) -> JSONResponse:
    """Storno omylného záznamu editorem (supersede, nikdy DELETE)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        eid = int((body or {}).get("id") or 0)
    except Exception:
        eid = 0
    reason = str((body or {}).get("reason") or "").strip()[:300]
    if not eid:
        return JSONResponse({"ok": False, "error": "missing_id"}, status_code=400)
    if not reason:
        return JSONResponse({"ok": False, "error": "Důvod storna je povinný."})
    cm, s = _att_session()
    try:
        if not _att_can_fix(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        row = s.execute(_t(
            "SELECT e.employee_id, e.entry_date, COALESCE(to_char(e.started_at,'HH24:MI'),'?'), "
            "       COALESCE(to_char(e.ended_at,'HH24:MI'),'…'), e.status, COALESCE(e.source_system,''), et.label, "
            "       e.started_at, e.ended_at "
            "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id = e.entry_type_id "
            "WHERE e.id=:i AND e.tenant_id=:t"),
            {"i": eid, "t": _ATT_TENANT}).first()
        if not row:
            return JSONResponse({"ok": False, "error": "Záznam nenalezen."})
        if row[4] == "superseded":
            return JSONResponse({"ok": False, "error": "Záznam už je zneplatněný."})
        if row[5]:
            return JSONResponse({"ok": False, "error": "Záznam vlastní stará Centrála — oprav ho v Centrále."})
        if _att_period_locked(s, row[1]):
            if not _att_can_lock(s, uid):
                return JSONResponse({"ok": False, "error": "Tento měsíc je uzavřený (mzdy zpracovány) — storno musí nejdřív povolit Peťa/Šárka odemčením období."}, status_code=409)
            reason = (reason + " [storno v uzavřeném období]").strip()
        emp = int(row[0])
        _emps = _att_fix_scope_emps(s, _att_fix_scope(s, uid))
        if _emps is not None and emp not in _emps:
            return JSONResponse({"ok": False, "error": "Osoba není ve tvé působnosti (kancelář/výroba)."}, status_code=403)
        actor = _user_jmeno(s, uid)
        desc = (row[6] or "") + " " + row[2] + "–" + row[3]
        s.execute(_t(
            "UPDATE tenant.att_entry SET status='superseded', is_active=false, "
            "note = CASE WHEN COALESCE(note,'')='' THEN :nn ELSE note || ' / ' || :nn END, updated_at=now() "
            "WHERE id=:i"),
            {"i": eid, "nn": "🛠 STORNO (" + actor + "): " + reason})
        s.execute(_t("UPDATE tenant.att_anomaly SET resolved_at=now() "
                     "WHERE tenant_id=:t AND entry_id=:i AND resolved_at IS NULL"),
                  {"t": _ATT_TENANT, "i": eid})
        _att_fix_audit(s, "void", eid, emp, uid, actor, old_note=desc.strip(),
                       detail=reason, old_date=row[1].isoformat())
        _att_fix_notify(s, emp, uid, actor, "🛠 Storno záznamu docházky",
                        actor + " stornoval(a) v tvé docházce " + row[1].strftime("%d.%m.")
                        + " záznam " + desc.strip() + " (" + reason + "). "
                        "Pokud to nesedí, otevři den v Docházce a dej ✋ Nesedí.")
        # Jirka 10.7.: storno přerušení (odchod/omyl) může nechat den rozstřižený —
        # když na sebe okolní záznamy navazují a mají STEJNÝ typ i zakázku, nabídni
        # sloučení (UI se zeptá, sešití dělá /fix/merge).
        offer = _att_fix_merge_candidate(s, emp, row[1], row[7], row[8], eid)
        s.commit()
        return JSONResponse({"ok": True, "merge_offer": offer})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


def _att_fix_merge_candidate(s, emp, day, x_start, x_end, exclude_id):
    """Po stornu přerušení X najdi navazující segmenty: A končí ~u začátku X,
    B začíná ~u konce X (tolerance 3 min). Kandidát na sloučení JEN při přesné
    shodě typu i zakázky (Jirka 10.7.: práce×režie se neslučuje). Vrací dict
    {a_id, b_id, popis} nebo None."""
    from sqlalchemy import text as _t
    if x_start is None:
        return None
    xe = x_end or x_start
    try:
        a = s.execute(_t(
            "SELECT e.id, e.entry_type_id, COALESCE(e.project_ref,''), et.label, "
            "       to_char(e.started_at,'HH24:MI'), to_char(e.ended_at,'HH24:MI') "
            "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id=e.entry_type_id "
            "WHERE e.tenant_id=:t AND e.employee_id=:e AND e.entry_date=:d AND e.id<>:x "
            "  AND e.status NOT IN ('superseded','announced') AND COALESCE(e.source_system,'')='' "
            "  AND et.category='presence' AND et.code NOT IN ('day_end','break') "
            "  AND e.ended_at IS NOT NULL "
            "  AND abs(EXTRACT(EPOCH FROM (e.ended_at - CAST(:xs AS timestamp)))) <= 180 "
            "ORDER BY e.ended_at DESC LIMIT 1"),
            {"t": _ATT_TENANT, "e": emp, "d": day.isoformat(), "x": exclude_id,
             "xs": x_start.isoformat(sep=" ")}).first()
        b = s.execute(_t(
            "SELECT e.id, e.entry_type_id, COALESCE(e.project_ref,''), et.label, "
            "       to_char(e.started_at,'HH24:MI'), COALESCE(to_char(e.ended_at,'HH24:MI'),'…') "
            "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id=e.entry_type_id "
            "WHERE e.tenant_id=:t AND e.employee_id=:e AND e.entry_date=:d AND e.id<>:x "
            "  AND e.status NOT IN ('superseded','announced') AND COALESCE(e.source_system,'')='' "
            "  AND et.category='presence' AND et.code NOT IN ('day_end','break') "
            "  AND e.started_at IS NOT NULL "
            "  AND abs(EXTRACT(EPOCH FROM (e.started_at - CAST(:xe AS timestamp)))) <= 180 "
            "ORDER BY e.started_at LIMIT 1"),
            {"t": _ATT_TENANT, "e": emp, "d": day.isoformat(), "x": exclude_id,
             "xe": xe.isoformat(sep=" ")}).first()
    except Exception:
        return None
    if not (a and b) or a[0] == b[0]:
        return None
    if a[1] != b[1] or a[2] != b[2]:
        return None  # jiný typ nebo zakázka → neslučovat
    return {"a_id": a[0], "b_id": b[0],
            "popis": (a[3] or "") + " " + (a[4] or "?") + "–" + (a[5] or "?")
                     + "  +  " + (b[3] or "") + " " + (b[4] or "?") + "–" + (b[5] or "…")}


@api_router.post("/app/attendance/fix/merge")
async def att_fix_merge(req: Request) -> JSONResponse:
    """Sešití navazujících záznamů po stornu přerušení (Jirka 10.7.): B se
    zneplatní, A převezme jeho konec (běžící B → A se znovu otevře jako běžící).
    Jen při přesné shodě typu i zakázky. Auditované, dotčený dostane notifikaci."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        a_id = int((body or {}).get("a_id") or 0)
        b_id = int((body or {}).get("b_id") or 0)
    except Exception:
        a_id = b_id = 0
    reason = str((body or {}).get("reason") or "sloučení navazujících záznamů po stornu").strip()[:300]
    if not (a_id and b_id) or a_id == b_id:
        return JSONResponse({"ok": False, "error": "missing_ids"}, status_code=400)
    cm, s = _att_session()
    try:
        if not _att_can_fix(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        rows = {}
        for rid in (a_id, b_id):
            rows[rid] = s.execute(_t(
                "SELECT e.id, e.employee_id, e.entry_date, e.started_at, e.ended_at, "
                "       e.entry_type_id, COALESCE(e.project_ref,''), COALESCE(e.break_minutes,0), "
                "       e.status, COALESCE(e.source_system,''), e.is_active, et.label, e.project_ref "
                "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id=e.entry_type_id "
                "WHERE e.id=:i AND e.tenant_id=:t"), {"i": rid, "t": _ATT_TENANT}).first()
        A, B = rows[a_id], rows[b_id]
        if not (A and B):
            return JSONResponse({"ok": False, "error": "Záznam nenalezen."})
        if A[1] != B[1]:
            return JSONResponse({"ok": False, "error": "Záznamy nepatří stejné osobě."})
        if A[8] == "superseded" or B[8] == "superseded":
            return JSONResponse({"ok": False, "error": "Jeden ze záznamů už je zneplatněný."})
        if A[9] or B[9]:
            return JSONResponse({"ok": False, "error": "Záznam vlastní stará Centrála — sloučení tady nejde."})
        if A[5] != B[5] or A[6] != B[6]:
            return JSONResponse({"ok": False, "error": "Záznamy nemají stejný typ a zakázku — neslučuji."})
        if A[4] is None or B[3] is None:
            return JSONResponse({"ok": False, "error": "Chybí časy pro sešití."})
        gap = (B[3] - A[4]).total_seconds()
        if gap < -60 or gap > 900:
            return JSONResponse({"ok": False, "error": "Záznamy na sebe nenavazují (mezera přes 15 min)."})
        if _att_period_locked(s, A[2]):
            return JSONResponse({"ok": False, "error": "Období je uzamčeno (mzdy zpracovány)."}, status_code=409)
        emp = int(A[1])
        _emps = _att_fix_scope_emps(s, _att_fix_scope(s, uid))
        if _emps is not None and emp not in _emps:
            return JSONResponse({"ok": False, "error": "Osoba není ve tvé působnosti (kancelář/výroba)."}, status_code=403)
        actor = _user_jmeno(s, uid)
        b_running = bool(B[10]) and B[4] is None
        brk = int(A[7]) + int(B[7])
        if b_running:
            new_end = None
            hrs = None
        else:
            new_end = B[4]
            hrs = round(max((B[4] - A[3]).total_seconds() / 3600.0 - brk / 60.0, 0.0), 2)
        a_zac = A[3].strftime("%H:%M")
        a_kon = A[4].strftime("%H:%M")
        b_kon = B[4].strftime("%H:%M") if B[4] is not None else "…"
        nn = "🛠 SLOUČENO (" + actor + "): " + reason + " (navázán #" + str(b_id) + ", původně do " + a_kon + ")"
        s.execute(_t(
            "UPDATE tenant.att_entry SET ended_at=CAST(:ne AS timestamp), is_active=:ia, hours=:h, "
            "break_minutes=:b, note = CASE WHEN COALESCE(note,'')='' THEN :nn ELSE note || ' / ' || :nn END, "
            "updated_at=now() WHERE id=:i"),
            {"ne": (new_end.isoformat(sep=" ") if new_end is not None else None),
             "ia": b_running, "h": hrs, "b": brk, "nn": nn, "i": a_id})
        s.execute(_t(
            "UPDATE tenant.att_entry SET status='superseded', is_active=false, "
            "note = CASE WHEN COALESCE(note,'')='' THEN :nn ELSE note || ' / ' || :nn END, updated_at=now() "
            "WHERE id=:i"),
            {"i": b_id, "nn": "sloučeno do #" + str(a_id) + " (" + actor + ")"})
        # Osa zakázek: sešij i work_alloc — úsek A protáhni přes úsek B (stejná
        # zakázka+činnost), úsek B zparazituj na nulovou délku (<60 s se ignoruje).
        try:
            tu = s.execute(_t("SELECT user_id FROM tenant.att_employee WHERE id=:e"), {"e": emp}).scalar()
            if tu:
                wa = s.execute(_t(
                    "SELECT a.id, b.id, b.ended_at "
                    "FROM tenant.work_alloc a, tenant.work_alloc b "
                    "WHERE a.user_id=:u AND b.user_id=:u AND a.id<>b.id "
                    "  AND a.ended_at IS NOT NULL "
                    "  AND abs(EXTRACT(EPOCH FROM (a.ended_at - CAST(:ae AS timestamptz)))) <= 180 "
                    "  AND abs(EXTRACT(EPOCH FROM (b.started_at - CAST(:bs AS timestamptz)))) <= 180 "
                    "  AND COALESCE(a.project_ref,'') = COALESCE(b.project_ref,'') "
                    "  AND COALESCE(a.cinnost_id,0) = COALESCE(b.cinnost_id,0) LIMIT 1"),
                    {"u": tu, "ae": A[4].isoformat(sep=" "), "bs": B[3].isoformat(sep=" ")}).first()
                if wa:
                    s.execute(_t("UPDATE tenant.work_alloc SET ended_at=:e, updated_at=now() WHERE id=:i"),
                              {"e": wa[2], "i": wa[0]})
                    s.execute(_t("UPDATE tenant.work_alloc SET ended_at=started_at, updated_at=now() WHERE id=:i"),
                              {"i": wa[1]})
        except Exception:
            pass
        s.execute(_t("UPDATE tenant.att_anomaly SET resolved_at=now() "
                     "WHERE tenant_id=:t AND entry_id IN (:a,:b) AND resolved_at IS NULL"),
                  {"t": _ATT_TENANT, "a": a_id, "b": b_id})
        _att_fix_audit(s, "merge", a_id, emp, uid, actor,
                       old_note=(A[11] or "") + " " + a_zac + "–" + a_kon + " + " + B[3].strftime("%H:%M") + "–" + b_kon,
                       new_note=(A[11] or "") + " " + a_zac + "–" + (new_end.strftime("%H:%M") if new_end else "běží"),
                       detail=reason + " | sloučen #" + str(b_id) + " do #" + str(a_id),
                       old_date=A[2].isoformat())
        _att_fix_notify(s, emp, uid, actor, "🛠 Sloučení záznamů docházky",
                        actor + " sloučil(a) v tvé docházce " + A[2].strftime("%d.%m.")
                        + " navazující záznamy do jednoho: " + (A[11] or "") + " " + a_zac + "–"
                        + (new_end.strftime("%H:%M") if new_end else "běží") + " (" + reason + "). "
                        "Pokud to nesedí, otevři den v Docházce a dej ✋ Nesedí.")
        s.commit()
        return JSONResponse({"ok": True, "id": a_id, "running": b_running})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/attendance/fix/resolve")
async def att_fix_resolve(req: Request) -> JSONResponse:
    """Odbavení položky fronty bez zásahu: anomálie (anomaly_id) nebo rozpor
    dne (uid+day) — s poznámkou proč je to v pořádku."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    from datetime import datetime as _dt
    try:
        body = await req.json()
    except Exception:
        body = {}
    reason = str((body or {}).get("reason") or "").strip()[:300]
    aid = 0
    tuid = 0
    try:
        aid = int((body or {}).get("anomaly_id") or 0)
    except Exception:
        pass
    try:
        tuid = int((body or {}).get("uid") or 0)
    except Exception:
        pass
    cm, s = _att_session()
    try:
        _sc = _att_fix_scope(s, uid)
        if _sc is None:
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        _emps = _att_fix_scope_emps(s, _sc)
        actor = _user_jmeno(s, uid)
        if aid:
            _ae = s.execute(_t("SELECT employee_id FROM tenant.att_anomaly WHERE tenant_id=:t AND id=:i"),
                            {"t": _ATT_TENANT, "i": aid}).scalar()
            if _ae is not None and _emps is not None and int(_ae) not in _emps:
                return JSONResponse({"ok": False, "error": "Osoba není ve tvé působnosti (kancelář/výroba)."}, status_code=403)
            r = s.execute(_t("UPDATE tenant.att_anomaly SET resolved_at=now() "
                             "WHERE tenant_id=:t AND id=:i AND resolved_at IS NULL RETURNING employee_id, entry_id"),
                          {"t": _ATT_TENANT, "i": aid}).first()
            if r:
                _att_fix_audit(s, "resolve", r[1], r[0], uid, actor, detail="anomálie OK: " + (reason or "-"))
            s.commit()
            return JSONResponse({"ok": True})
        if tuid:
            try:
                day = _dt.strptime(str((body or {}).get("day") or "")[:10], "%Y-%m-%d").date()
            except Exception:
                return JSONResponse({"ok": False, "error": "Neplatné datum."})
            emp = s.execute(_t("SELECT id FROM tenant.att_employee WHERE tenant_id=:t AND user_id=:u"),
                            {"t": _ATT_TENANT, "u": tuid}).scalar()
            if emp and _emps is not None and int(emp) not in _emps:
                return JSONResponse({"ok": False, "error": "Osoba není ve tvé působnosti (kancelář/výroba)."}, status_code=403)
            if emp:
                s.execute(_t(
                    "UPDATE tenant.att_day_confirm SET disputed=false, "
                    "note = COALESCE(note,'') || ' | vyřešeno (' || :a || '): ' || :r "
                    "WHERE tenant_id=:t AND employee_id=:e AND day=:d AND disputed=true"),
                    {"t": _ATT_TENANT, "e": emp, "d": day.isoformat(), "a": actor, "r": (reason or "-")})
                _att_fix_audit(s, "resolve", None, emp, uid, actor,
                               detail="rozpor dne vyřešen: " + (reason or "-"), old_date=day.isoformat())
            s.commit()
            return JSONResponse({"ok": True})
        return JSONResponse({"ok": False, "error": "missing_target"}, status_code=400)
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/attendance/fix/audit")
async def att_fix_audit_list(req: Request) -> JSONResponse:
    """Přehled oprav (att_audit) pro editory — kdo, komu, kdy, co, před→po."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        _sc = _att_fix_scope(s, uid)
        if _sc is None:
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        _emps = _att_fix_scope_emps(s, _sc)
        rows = s.execute(_t(
            "SELECT a.id, a.action, a.entry_id, a.old_entry_date::text, a.old_note, a.new_note, "
            "       a.detail, a.actor_text, to_char(a.created_at,'DD.MM. HH24:MI'), "
            "       COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),''), em.full_name), "
            "       a.employee_id "
            "FROM tenant.att_audit a "
            "LEFT JOIN tenant.att_employee em ON em.id = a.employee_id "
            "LEFT JOIN public.users u ON u.id = em.user_id "
            "WHERE a.tenant_id = :t AND a.action IN ('fix','add','void','merge','resolve','period_lock','period_unlock') "
            "ORDER BY a.id DESC LIMIT 200"),
            {"t": _ATT_TENANT}).fetchall()
        s.commit()
        if _emps is not None:  # působnost: cizí lidi nezobrazovat (řádky bez osoby, např. zámek, zůstávají)
            rows = [r for r in rows if r[10] is None or int(r[10]) in _emps]
        return JSONResponse({"ok": True, "items": [
            {"id": r[0], "action": r[1], "entry_id": r[2], "day": r[3], "old": r[4],
             "new": r[5], "detail": r[6], "actor": r[7], "ts": r[8], "person": r[9]} for r in rows]})
    finally:
        cm.__exit__(None, None, None)


