@api_router.post("/app/attendance/period-lock")
async def att_period_lock_set(req: Request) -> JSONResponse:
    """Zamknout/odemknout měsíc pro opravy (mzdy). Peťa/Šárka + rodiče."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        rok = int((body or {}).get("rok") or 0)
        mesic = int((body or {}).get("mesic") or 0)
    except Exception:
        rok = mesic = 0
    lock = bool((body or {}).get("lock"))
    note = str((body or {}).get("note") or "").strip()[:200]
    if not (2020 <= rok <= 2100 and 1 <= mesic <= 12):
        return JSONResponse({"ok": False, "error": "Neplatné období."})
    cm, s = _att_session()
    try:
        if not _att_can_lock(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        actor = _user_jmeno(s, uid)
        if lock:
            s.execute(_t(
                "INSERT INTO tenant.att_period_lock (tenant_id, rok, mesic, locked_by, note) "
                "VALUES (:t,:r,:m,:u,:n) ON CONFLICT (tenant_id, rok, mesic) DO NOTHING"),
                {"t": _ATT_TENANT, "r": rok, "m": mesic, "u": uid, "n": note or None})
        else:
            s.execute(_t("DELETE FROM tenant.att_period_lock WHERE tenant_id=:t AND rok=:r AND mesic=:m"),
                      {"t": _ATT_TENANT, "r": rok, "m": mesic})
        _att_fix_audit(s, "period_lock" if lock else "period_unlock", None, None, uid, actor,
                       detail=str(mesic) + "/" + str(rok) + (" — " + note if note else ""))
        s.commit()
        return JSONResponse({"ok": True})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/zakazky")
async def app_zakazky(req: Request) -> JSONResponse:
    """Marti 7.6.: picker zakázek pro píchání (VR/SW/PR/Rezie). Jen píchatelné
    (zrcadlo tenant.zakazka, ⚙ sync_zakazky). Volitelný filtr ?q= (číslo/název)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    q = (req.query_params.get("q") or "").strip()[:60]
    cm, s = _att_session()
    try:
        # Marti 7.6. večer: Režie na první místo — je to taky zakázka.
        if q:
            rows = s.execute(_t(
                "SELECT cislo, COALESCE(nazev,''), typ FROM tenant.zakazka "
                "WHERE tenant_id = 2 AND pichatelna = true "
                "AND (cislo ILIKE :q OR nazev ILIKE :q) "
                "ORDER BY (typ = 'REZIE') DESC, cislo DESC LIMIT 30"), {"q": "%" + q + "%"}).fetchall()
        else:
            rows = s.execute(_t(
                "SELECT cislo, COALESCE(nazev,''), typ FROM tenant.zakazka "
                "WHERE tenant_id = 2 AND pichatelna = true "
                "ORDER BY (typ = 'REZIE') DESC, cislo DESC LIMIT 30")).fetchall()
        # Marti 8.6.: „Dnes naplánováno" — zakázky, na které je člověk dnes
        # naplánovaný dle plánu výroby (tenant.vyroba_plan, read-only z Centrály).
        planned = []
        try:
            prow = s.execute(_t(
                "SELECT vp.cislo_zakazky, COALESCE(z.nazev, vp.zakazka_nazev, ''), z.typ, vp.pocet_hodin, "
                " COALESCE(o.poznamka,'') "
                "FROM tenant.vyroba_plan vp "
                "LEFT JOIN tenant.zakazka z ON z.tenant_id = 2 AND z.cislo = vp.cislo_zakazky "
                "LEFT JOIN tenant.vyroba_plan_overlay o "
                "  ON o.tenant_id = 2 AND o.user_id = vp.user_id AND o.cislo_zakazky = vp.cislo_zakazky "
                "WHERE vp.tenant_id = 2 AND vp.user_id = :uid AND vp.datum = CURRENT_DATE "
                "  AND COALESCE(o.hidden,false) = false AND COALESCE(o.done,false) = false "
                "ORDER BY COALESCE(o.poradi,999), vp.pocet_hodin DESC NULLS LAST, vp.cislo_zakazky"),
                {"uid": uid}).fetchall()
            planned = [{"cislo": r[0], "nazev": r[1], "typ": r[2],
                        "hodin": (float(r[3]) if r[3] is not None else None),
                        "poznamka": r[4]} for r in prow]
        except Exception:
            planned = []
        # Marti 8.6.: ruční přiřazení od vedoucího výroby (s pokynem, v pořadí).
        assigned = []
        try:
            arow = s.execute(_t(
                "SELECT cislo_zakazky, COALESCE(zakazka_nazev,''), COALESCE(pokyn,''), COALESCE(kdy_ozvat,'') "
                "FROM tenant.vyroba_prirazeni "
                "WHERE tenant_id = 2 AND user_id = :uid AND status = 'active' "
                "ORDER BY poradi, id"), {"uid": uid}).fetchall()
            assigned = [{"cislo": r[0], "nazev": r[1], "pokyn": r[2], "kdy_ozvat": r[3]} for r in arow]
        except Exception:
            assigned = []
        s.commit()
        return JSONResponse({"ok": True, "zakazky": [
            {"cislo": r[0], "nazev": r[1], "typ": r[2]} for r in rows],
            "planned": planned, "assigned": assigned})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


# ═══ Plánování výroby — ruční přiřazení (Marti 8.6.) ═══════════════════════
# Vedoucí výroby Dušan Havlát (41) + zástupce Marek Honal (85) + rodiče.
# Michaela Hladíková (16) = zodpovědná za výrobu, plná práva (Marti 23.6.2026).
_VYROBA_MANAGERS = {16, 41, 85}


def _vyroba_can_manage(uid) -> bool:
    try:
        return int(uid) in _VYROBA_MANAGERS or is_marti_parent(uid)
    except Exception:
        return False


@api_router.get("/app/vyroba/can-manage")
async def app_vyroba_can_manage(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    return JSONResponse({"ok": True, "can_manage": _vyroba_can_manage(uid)})


@api_router.get("/app/vyroba/lidi")
async def app_vyroba_lidi(req: Request) -> JSONResponse:
    """Přehled pro vedoucího: lidé z plánu + jejich aktivní ruční přiřazení."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    if not _vyroba_can_manage(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        people = s.execute(_t(
            "SELECT vp.user_id, COALESCE(vp.zam_jmeno,'#'||vp.cislo_zam) AS jmeno, "
            " string_agg(DISTINCT vp.cislo_zakazky, ', ') FILTER (WHERE vp.datum = CURRENT_DATE) AS dnes "
            "FROM tenant.vyroba_plan vp "
            "WHERE vp.tenant_id=2 AND vp.user_id IS NOT NULL AND vp.cislo_zam < 10000 AND vp.datum >= CURRENT_DATE "
            "GROUP BY vp.user_id, COALESCE(vp.zam_jmeno,'#'||vp.cislo_zam) "
            "ORDER BY jmeno")).fetchall()
        pr = s.execute(_t(
            "SELECT id, user_id, cislo_zakazky, COALESCE(zakazka_nazev,''), COALESCE(pokyn,''), "
            " COALESCE(kdy_ozvat,''), poradi "
            "FROM tenant.vyroba_prirazeni WHERE tenant_id=2 AND status='active' "
            "ORDER BY user_id, poradi, id")).fetchall()
        amap = {}
        for r in pr:
            amap.setdefault(r[1], []).append({
                "id": r[0], "cislo": r[2], "nazev": r[3], "pokyn": r[4],
                "kdy_ozvat": r[5], "poradi": r[6]})
        # plán zakázek per člověk (z EC plánu, read-only) + náš overlay
        # (pořadí / skrytí / hotovo / poznámka navázané na člověka+zakázku)
        plan_rows = s.execute(_t(
            "SELECT g.user_id, g.cislo_zakazky, g.nazev, g.hod, "
            " o.poradi, COALESCE(o.hidden,false), COALESCE(o.done,false), o.poznamka "
            "FROM (SELECT user_id, cislo_zakazky, max(zakazka_nazev) AS nazev, "
            "        round(sum(pocet_hodin)::numeric,1) AS hod "
            "      FROM tenant.vyroba_plan "
            "      WHERE tenant_id=2 AND user_id IS NOT NULL AND cislo_zam < 10000 AND datum >= CURRENT_DATE "
            "      GROUP BY user_id, cislo_zakazky) g "
            "LEFT JOIN tenant.vyroba_plan_overlay o "
            "  ON o.tenant_id=2 AND o.user_id=g.user_id AND o.cislo_zakazky=g.cislo_zakazky "
            "ORDER BY g.user_id, COALESCE(o.poradi,999), g.cislo_zakazky")).fetchall()
        planmap = {}
        for r in plan_rows:
            planmap.setdefault(r[0], []).append({
                "cislo": r[1], "nazev": r[2] or "",
                "hod": (float(r[3]) if r[3] is not None else None),
                "poradi": r[4], "hidden": bool(r[5]), "done": bool(r[6]),
                "poznamka": r[7] or ""})
        # stav z docházky (dnes) per člověk: makam / pauza / jedu / pryc / byl / ''
        stavinfo = {}
        try:
            srows = s.execute(_t(
                "SELECT e.user_id, "
                " bool_or(a.is_active AND et.category IN ('presence','overhead') AND a.status NOT IN ('superseded','announced')) AS aktiv, "
                " count(*) FILTER (WHERE a.status NOT IN ('superseded','announced')) AS zazn, "
                " (array_agg(a.note ORDER BY a.id DESC) FILTER (WHERE a.status='announced' AND a.note IS NOT NULL))[1] AS note, "
                " (array_agg(CASE WHEN a.project_ref IS NOT NULL THEN a.project_ref WHEN et.code='overhead' THEN 'Režie' END ORDER BY a.id DESC) FILTER (WHERE a.is_active AND (a.project_ref IS NOT NULL OR et.code='overhead')))[1] AS proj, "
                " bool_or(a.is_active AND a.status NOT IN ('superseded','announced') AND (a.project_ref IS NOT NULL OR et.code='overhead')) AS prace, "
                " bool_or(a.is_active AND a.source_system='centrala1' AND a.status NOT IN ('superseded','announced')) AS ec_open "
                "FROM tenant.att_entry a "
                "JOIN tenant.att_employee e ON e.id=a.employee_id AND e.tenant_id=2 "
                "JOIN tenant.att_entry_type et ON et.id=a.entry_type_id "
                "WHERE a.tenant_id=2 AND a.entry_date=CURRENT_DATE AND e.user_id IS NOT NULL "
                "GROUP BY e.user_id")).fetchall()
            for r in srows:
                nl = (r[3] or "").lower()
                if ("jedu" in nl) or ("cest" in nl):
                    st = "jedu"
                elif r[1]:
                    # Marti 13.6.: ve směně + zakázka NEBO režie = Makám; ve směně bez práce = Čekám
                    st = "makam" if r[5] else "cekam"
                elif any(k in nl for k in ("pauz", "obed", "relax", "provetr", "jidl", "najist", "provětr", "jídl", "oběd", "najíst")):
                    st = "pauza"
                elif any(k in nl for k in ("nepocitej", "nepočítej", "nedoraz", "dovolen", "nemoc", "doktor", "lekar", "lékař")):
                    st = "pryc"
                elif (r[2] or 0) > 0:
                    st = "byl"
                else:
                    st = ""
                stavinfo[r[0]] = {"st": st, "note": (r[3] or ""), "proj": (r[4] or ""), "ec": bool(r[6])}
        except Exception:
            stavinfo = {}
        # Dnešní plán: kdo dle plánu vůbec nemá přijít (víkend/svátek/volno) → "mimo_plan"
        planoff = set()
        try:
            for r in s.execute(_t(
                "SELECT user_id, expected_hours, day_type FROM tenant.att_plan_effective "
                "WHERE tenant_id=2 AND plan_date=CURRENT_DATE")).fetchall():
                if float(r[1] or 0) <= 0 or (r[2] in ("weekend", "holiday", "off")):
                    planoff.add(r[0])
        except Exception:
            planoff = set()
        lidi = []
        for p in people:
            _plan = planmap.get(p[0], [])
            _pr = amap.get(p[0], [])
            _haswork = bool(_pr) or any((not o.get("hidden")) for o in _plan)
            _si = stavinfo.get(p[0], {})
            _st = _si.get("st", "")
            if _st == "":
                if p[0] in planoff:
                    _st = "mimo_plan"
                elif _haswork:
                    _st = "chybi"
            lidi.append({"user_id": p[0], "jmeno": p[1], "dnes": p[2] or "",
                         "plan": _plan, "prirazeni": _pr, "stav": _st,
                         "stav_pozn": _si.get("note", ""), "stav_zak": _si.get("proj", ""),
                         "ec_old": bool(_si.get("ec", False))})
        s.commit()
        return JSONResponse({"ok": True, "lidi": lidi})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/skupiny/bar")
async def app_skupiny_bar(req: Request) -> JSONResponse:
    """Skupiny pro spodní lištu Firma, s mým vztahem (vedoucí/zástupce/člen/
    ostatní) pro řazení zprava doleva. Marti 10.6.2026. Zatím vidí všichni vše."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        rows = s.execute(_t(
            "SELECT g.id, g.name, COALESCE(NULLIF(g.icon,''),'👥'), g.leader_user_id, g.deputy_user_id, "
            " EXISTS(SELECT 1 FROM tenant.staff_group_member m WHERE m.group_id=g.id AND m.user_id=:u) je_clen "
            "FROM tenant.staff_group g "
            "WHERE g.tenant_id=2 AND COALESCE(g.archived,false)=false "
            "ORDER BY g.sort_order, g.name"), {"u": int(uid)}).fetchall()
        out = []
        for r in rows:
            if r[3] == int(uid):
                rel = "lead"
            elif r[4] == int(uid):
                rel = "deputy"
            elif r[5]:
                rel = "member"
            else:
                rel = "other"
            out.append({"id": r[0], "name": r[1], "icon": r[2], "rel": rel})
        s.commit()
        return JSONResponse({"ok": True, "groups": out})
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/skupina/lidi")
async def app_skupina_lidi(req: Request) -> JSONResponse:
    """Konzole skupiny: lidé řazení vedoucí (král) → zástupce → ostatní podle
    skóre výkonnosti, s dnešním docházkovým stavem (stejná logika jako výroba).
    gid=0 = všichni lidé. Marti 10.6.2026. Zatím vidí všichni vše."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        gid = int(req.query_params.get("gid", "0"))
    except Exception:
        gid = 0
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        stavinfo = {}
        try:
            srows = s.execute(_t(
                "SELECT e.user_id, "
                " bool_or(a.is_active AND et.category IN ('presence','overhead') AND a.status NOT IN ('superseded','announced')) AS aktiv, "
                " count(*) FILTER (WHERE a.status NOT IN ('superseded','announced')) AS zazn, "
                " (array_agg(a.note ORDER BY a.id DESC) FILTER (WHERE a.status='announced' AND a.note IS NOT NULL))[1] AS note, "
                " (array_agg(CASE WHEN a.project_ref IS NOT NULL THEN a.project_ref WHEN et.code='overhead' THEN 'Režie' END ORDER BY a.id DESC) FILTER (WHERE a.is_active AND (a.project_ref IS NOT NULL OR et.code='overhead')))[1] AS proj, "
                " bool_or(a.is_active AND a.status NOT IN ('superseded','announced') AND (a.project_ref IS NOT NULL OR et.code='overhead')) AS prace, "
                " bool_or(a.is_active AND a.source_system='centrala1' AND a.status NOT IN ('superseded','announced')) AS ec_open "
                "FROM tenant.att_entry a "
                "JOIN tenant.att_employee e ON e.id=a.employee_id AND e.tenant_id=2 "
                "JOIN tenant.att_entry_type et ON et.id=a.entry_type_id "
                "WHERE a.tenant_id=2 AND a.entry_date=CURRENT_DATE AND e.user_id IS NOT NULL "
                "GROUP BY e.user_id")).fetchall()
            for r in srows:
                nl = (r[3] or "").lower()
                if ("jedu" in nl) or ("cest" in nl):
                    st = "jedu"
                elif r[1]:
                    # Marti 13.6.: ve směně + zakázka NEBO režie = Makám; ve směně bez práce = Čekám
                    st = "makam" if r[5] else "cekam"
                elif any(k in nl for k in ("pauz", "obed", "relax", "provetr", "jidl", "najist", "provětr", "jídl", "oběd", "najíst")):
                    st = "pauza"
                elif any(k in nl for k in ("nepocitej", "nepočítej", "nedoraz", "dovolen", "nemoc", "doktor", "lekar", "lékař")):
                    st = "pryc"
                elif (r[2] or 0) > 0:
                    st = "byl"
                else:
                    st = ""
                stavinfo[r[0]] = {"st": st, "note": (r[3] or ""), "proj": (r[4] or ""), "ec": bool(r[6])}
        except Exception:
            stavinfo = {}

        ordered = []
        if gid > 0:
            g = s.execute(_t("SELECT id, name, COALESCE(NULLIF(icon,''),'👥'), leader_user_id, deputy_user_id "
                             "FROM tenant.staff_group WHERE tenant_id=2 AND id=:g"), {"g": gid}).first()
            if not g:
                return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
            group = {"id": g[0], "name": g[1], "icon": g[2]}
            seen = set()
            if g[3]:
                ordered.append((g[3], "lead", None))
                seen.add(g[3])
            if g[4] and g[4] not in seen:
                ordered.append((g[4], "deputy", None))
                seen.add(g[4])
            for m in s.execute(_t("SELECT user_id, score FROM tenant.staff_group_member "
                                  "WHERE tenant_id=2 AND group_id=:g AND user_id IS NOT NULL "
                                  "ORDER BY COALESCE(score,0) DESC, user_id"), {"g": gid}).fetchall():
                if m[0] in seen:
                    continue
                ordered.append((m[0], "member", m[1]))
                seen.add(m[0])
        else:
            group = {"id": 0, "name": "Všichni", "icon": "🌐"}
            leaders, deputies = set(), set()
            for r in s.execute(_t("SELECT leader_user_id, deputy_user_id FROM tenant.staff_group "
                                  "WHERE tenant_id=2 AND COALESCE(archived,false)=false")).fetchall():
                if r[0]:
                    leaders.add(r[0])
                if r[1]:
                    deputies.add(r[1])
            scoremap = {}
            for r in s.execute(_t("SELECT user_id, max(score) FROM tenant.staff_group_member "
                                  "WHERE tenant_id=2 AND user_id IS NOT NULL GROUP BY user_id")).fetchall():
                scoremap[r[0]] = r[1]
            # „Všichni" = DISTINCT union lidí ze VŠECH skupin (vedoucí + zástupci +
            # členové) + docházkový roster — ať nikdo nevypadne, i když není v docházce
            # (Marti 10.6.: PLC členové chyběli, protože nebyli v att_employee).
            for r in s.execute(_t(
                "SELECT user_id FROM tenant.att_employee WHERE tenant_id=2 AND user_id IS NOT NULL AND is_active=true "
                "UNION SELECT leader_user_id FROM tenant.staff_group "
                "  WHERE tenant_id=2 AND leader_user_id IS NOT NULL AND COALESCE(archived,false)=false "
                "UNION SELECT deputy_user_id FROM tenant.staff_group "
                "  WHERE tenant_id=2 AND deputy_user_id IS NOT NULL AND COALESCE(archived,false)=false "
                "UNION SELECT m.user_id FROM tenant.staff_group_member m "
                "  JOIN tenant.staff_group g ON g.id=m.group_id "
                "  WHERE g.tenant_id=2 AND m.user_id IS NOT NULL AND COALESCE(g.archived,false)=false")).fetchall():
                u = r[0]
                role = "lead" if u in leaders else ("deputy" if u in deputies else "member")
                ordered.append((u, role, scoremap.get(u)))

        uids = [u for (u, _, _) in ordered]
        names = {}
        if uids:
            for r in s.execute(_t(
                "SELECT id, NULLIF(TRIM(COALESCE(first_name,'')||' '||COALESCE(last_name,'')),'') "
                "FROM public.users WHERE id = ANY(:ids)"), {"ids": uids}).fetchall():
                names[r[0]] = r[1]
        planoff = set()
        try:
            for r in s.execute(_t(
                "SELECT user_id, expected_hours, day_type FROM tenant.att_plan_effective "
                "WHERE tenant_id=2 AND plan_date=CURRENT_DATE")).fetchall():
                if float(r[1] or 0) <= 0 or (r[2] in ("weekend", "holiday", "off")):
                    planoff.add(r[0])
        except Exception:
            planoff = set()
        lidi = []
        for (u, role, score) in ordered:
            si = stavinfo.get(u, {})
            _st = si.get("st", "")
            if _st == "" and u in planoff:
                _st = "mimo_plan"
            lidi.append({"user_id": u, "jmeno": names.get(u) or ("#" + str(u)),
                         "role": role, "score": score, "stav": _st,
                         "stav_pozn": si.get("note", ""), "stav_zak": si.get("proj", ""),
                         "ec_old": bool(si.get("ec", False))})
        if gid == 0:
            _rr = {"lead": 0, "deputy": 1, "member": 2}
            lidi.sort(key=lambda x: (_rr.get(x["role"], 2),
                                     -(x["score"] if x["score"] is not None else -9999),
                                     (x["jmeno"] or "").lower()))
        s.commit()
        return JSONResponse(jsonable_encoder({"ok": True, "group": group, "lidi": lidi}))
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/all-users")
async def app_all_users(req: Request) -> JSONResponse:
    """Marti 10.6.2026: všichni uživatelé STRATEGIE napříč tenanty, přepínatelné
    podle tenantu. JEN PRO RODIČE (is_marti_parent). tenant=0 = všichni."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        isp = s.execute(_t("SELECT COALESCE(is_marti_parent,false) FROM public.users WHERE id=:u"),
                        {"u": int(uid)}).scalar()
        if not isp:
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        try:
            tid = int(req.query_params.get("tenant", "0"))
        except Exception:
            tid = 0
        tenants = [{"id": r[0], "name": r[1] or ("Tenant " + str(r[0]))}
                   for r in s.execute(_t(
                       "SELECT id, tenant_name FROM public.tenants "
                       "WHERE COALESCE(status,'') <> 'archived' ORDER BY id")).fetchall()]
        params = {}
        where = ""
        if tid:
            where = " AND ut.tenant_id = :tid"
            params["tid"] = tid
        rows = s.execute(_t(
            "SELECT u.id, NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),'') AS jmeno, "
            " u.short_name, u.login_name, u.status, COALESCE(u.is_marti_parent,false) AS parent, "
            " string_agg(DISTINCT t.tenant_name||' ('||COALESCE(ut.role,'?')||')', ', ') AS tenanty "
            "FROM public.users u "
            "JOIN public.user_tenants ut ON ut.user_id = u.id "
            "JOIN public.tenants t ON t.id = ut.tenant_id "
            "WHERE COALESCE(ut.membership_status,'active') IN ('active','invited') "
            "  AND COALESCE(u.status,'') <> 'disabled'" + where + " "
            "GROUP BY u.id, u.first_name, u.last_name, u.short_name, u.login_name, u.status, u.is_marti_parent "
            "ORDER BY CASE u.status WHEN 'active' THEN 0 WHEN 'pending' THEN 1 ELSE 2 END, "
            "         jmeno NULLS LAST, u.id"), params).fetchall()
        users = [{"user_id": r[0], "jmeno": r[1] or (r[2] or r[3] or ("#" + str(r[0]))),
                  "login": r[3], "status": r[4], "parent": r[5], "tenanty": r[6] or ""}
                 for r in rows]
        s.commit()
        return JSONResponse(jsonable_encoder({"ok": True, "tenants": tenants, "users": users, "tenant": tid}))
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/helios-recon")
async def app_helios_recon(req: Request) -> JSONResponse:
    """Marti 10.6.2026: pohled účetní — lidé z Heliosu (TabCisZam EC + ES) a kdo
    je NESPÁROVANÝ s našimi zaměstnanci/uživateli. JEN PRO RODIČE. 'účetní v tom
    má bordel' → ukáže díry. Stav: ok (zam+user) / no_user (zam bez usera) /
    no_emp (vůbec nespárovaný). filter=unmatched → jen no_emp+no_user."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    from core.database_data import get_data_session as _gd_hr
    sx = _gd_hr()
    try:
        isp = sx.execute(_t("SELECT COALESCE(is_marti_parent,false) FROM public.users WHERE id=:u"),
                         {"u": int(uid)}).scalar()
        if not isp:
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        empmap = {}
        for r in sx.execute(_t(
            "SELECT cislo_zam, max(user_id) FROM tenant.att_employee "
            "WHERE tenant_id=2 AND cislo_zam IS NOT NULL GROUP BY cislo_zam")).fetchall():
            empmap[str(r[0])] = r[1]
    finally:
        sx.close()
    import json as _j_hr
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return JSONResponse({"ok": False, "error": "mcp_unavailable"}, status_code=503)

    def rows_of(sql):
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _j_hr.loads(raw) if isinstance(raw, str) else raw
        if isinstance(r, dict):
            if r.get("ok") is False:
                raise RuntimeError(str(r.get("error")))
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    return r[k]
        return r if isinstance(r, list) else []

    only_unmatched = req.query_params.get("filter") == "unmatched"
    people = []
    errors = []
    for src, dbp in (("EC", ""), ("ES", "DB_IS.dbo.")):
        try:
            # Marti 10.6.: jen zaměstnanci aktivní ve mzdách v POSLEDNÍM období
            # (mají mzdové složky v MAX(IdObdobi)) — ať se do toho nezamotáme.
            data = rows_of(
                "SELECT z.Cislo c, LEFT(LTRIM(RTRIM(ISNULL(z.Prijmeni,'')+' '+ISNULL(z.Jmeno,''))),80) jm "
                "FROM %sTabCisZam z "
                "WHERE EXISTS (SELECT 1 FROM %sTabMzSloz s "
                "  WHERE s.ZamestnanecId = z.ID "
                "    AND s.IdObdobi = (SELECT MAX(IdObdobi) FROM %sTabMzSloz)) "
                "ORDER BY z.Cislo" % (dbp, dbp, dbp))
        except Exception as exc:
            errors.append("%s: %s" % (src, str(exc)[:120]))
            continue
        for d in data:
            cs = str(d.get("c"))
            if cs in empmap:
                st = "ok" if empmap[cs] else "no_user"
            else:
                st = "no_emp"
            if only_unmatched and st == "ok":
                continue
            people.append({"src": src, "cislo": d.get("c"), "jmeno": (d.get("jm") or "").strip(),
                           "typ": d.get("typ") or "", "stav": st})
    _ord = {"no_emp": 0, "no_user": 1, "ok": 2}
    people.sort(key=lambda x: (_ord.get(x["stav"], 9), x["src"], x["cislo"] if isinstance(x["cislo"], int) else 0))
    summary = {"celkem": len(people),
               "no_emp": sum(1 for p in people if p["stav"] == "no_emp"),
               "no_user": sum(1 for p in people if p["stav"] == "no_user"),
               "ok": sum(1 for p in people if p["stav"] == "ok")}
    return JSONResponse(jsonable_encoder({"ok": True, "people": people, "summary": summary, "errors": errors}))


@api_router.get("/app/vyroba/zakazky-lide")
async def app_vyroba_zakazky_lide(req: Request) -> JSONResponse:
    """Režim zakázek: zakázky (z plánu + ručních přiřazení) s lidmi na každé.
    Source 'plan' = z Excelu (read-only), 'manual' = přiřazeno vedoucím (lze odebrat)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    if not _vyroba_can_manage(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        zak = {}

        def ent(cislo, nazev):
            if cislo not in zak:
                zak[cislo] = {"cislo": cislo, "nazev": nazev or "", "lide": []}
            elif nazev and not zak[cislo]["nazev"]:
                zak[cislo]["nazev"] = nazev
            return zak[cislo]
        # z plánu (read-only) + overlay (skryté plán-přiřazení = odebrané z naší view)
        prows = s.execute(_t(
            "SELECT g.cislo_zakazky, g.nazev, g.user_id, g.jmeno, g.hod, "
            " COALESCE(o.hidden,false), COALESCE(o.done,false) "
            "FROM (SELECT cislo_zakazky, max(zakazka_nazev) AS nazev, user_id, "
            "        max(COALESCE(zam_jmeno,'#'||cislo_zam)) AS jmeno, round(sum(pocet_hodin)::numeric,1) AS hod "
            "      FROM tenant.vyroba_plan "
            "      WHERE tenant_id=2 AND user_id IS NOT NULL AND cislo_zam < 10000 AND datum >= CURRENT_DATE "
            "      GROUP BY cislo_zakazky, user_id) g "
            "LEFT JOIN tenant.vyroba_plan_overlay o "
            "  ON o.tenant_id=2 AND o.user_id=g.user_id AND o.cislo_zakazky=g.cislo_zakazky")).fetchall()
        for r in prows:
            if bool(r[5]):
                continue  # skryté = odebrané z naší view
            ent(r[0], r[1])["lide"].append({
                "user_id": r[2], "jmeno": r[3], "source": "plan",
                "done": bool(r[6]),
                "hod": (float(r[4]) if r[4] is not None else None)})
        # ruční přiřazení (lze odebrat)
        mrows = s.execute(_t(
            "SELECT vp.cislo_zakazky, vp.zakazka_nazev, vp.user_id, "
            " COALESCE(u.short_name, u.last_name, '#'||vp.user_id) AS jmeno, vp.id, COALESCE(vp.pokyn,'') "
            "FROM tenant.vyroba_prirazeni vp LEFT JOIN public.users u ON u.id = vp.user_id "
            "WHERE vp.tenant_id=2 AND vp.status='active'")).fetchall()
        for r in mrows:
            ent(r[0], r[1])["lide"].append({
                "user_id": r[2], "jmeno": r[3], "source": "manual",
                "prirazeni_id": r[4], "pokyn": r[5]})
        s.commit()
        out = sorted(zak.values(), key=lambda z: z["cislo"])
        for z in out:
            z["pocet"] = len(z["lide"])
        return JSONResponse({"ok": True, "zakazky": out})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


