# ── Úkoly z Centrály (EC_Ukoly, read-only v1) — Marti 9.6.2026 ──────────────
# User->EC cislo pres att_employee.cislo_zam. Resitel=Typ 1/4, Kopie=Typ 2 ve
# EC_UkolyResitelVazba. Zadavatel=EC_Ukoly.Zadavatel. Open=Stav 0/2/4/5/6/7.
def _ec_user_cisla(uid):
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        rows = s.execute(_t(
            "SELECT DISTINCT cislo_zam FROM tenant.att_employee "
            "WHERE user_id=:u AND tenant_id=2 AND cislo_zam IS NOT NULL"), {"u": uid}).fetchall()
    finally:
        cm.__exit__(None, None, None)
    return [str(r[0]) for r in rows if str(r[0]).isdigit()]


def _ec_mcp_rows(sql):
    import json as _json
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        raise RuntimeError("EUROSOFT MCP nedostupné")
    raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                             {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
    r = _json.loads(raw) if isinstance(raw, str) else raw
    if isinstance(r, dict):
        if r.get("ok") is False:
            raise RuntimeError(str(r.get("error")))
        for k in ("rows", "data", "result", "records"):
            if isinstance(r.get(k), list):
                return r[k]
        return []
    return r if isinstance(r, list) else []


@api_router.get("/app/ec-ukoly")
async def app_ec_ukoly(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    view = (req.query_params.get("view") or "resitel").strip().lower()
    nums = _ec_user_cisla(uid)
    if not nums:
        return JSONResponse({"ok": True, "ukoly": [], "note": "no_ec_number"})
    csv = ",".join(nums)
    cols = ("h.ID id, LEFT(ISNULL(h.Predmet,''),140) predmet, ISNULL(h.StavText,'') stav, "
            "ISNULL(h.HotovoProcent,0) hp, CONVERT(varchar(10),h.TerminSplneni,104) termin, "
            "ISNULL(h.CisloZakazky,'') zak, "
            "LTRIM(RTRIM(ISNULL(zz.Prijmeni,'')+' '+ISNULL(zz.Jmeno,''))) zadavatel, "
            "CASE WHEN h.TerminSplneni < GETDATE() AND ISNULL(h.HotovoProcent,0)<100 THEN 1 ELSE 0 END pozde")
    base = "EC_Ukoly h LEFT JOIN TabCisZam zz ON zz.Cislo=h.Zadavatel"
    if view == "zadavatel":
        sql = ("SELECT TOP 80 " + cols + " FROM " + base +
               " WHERE h.Zadavatel IN (" + csv + ") AND h.Stav IN (0,2,4,5,6,7) ORDER BY h.TerminSplneni")
    elif view in ("resitel", "kopie", "urgentni"):
        typ = "2" if view == "kopie" else "1,4"
        extra = " AND (v.TerminOsobni < GETDATE() OR h.TerminSplneni < GETDATE())" if view == "urgentni" else ""
        sql = ("SELECT TOP 80 " + cols + " FROM EC_UkolyResitelVazba v JOIN " + base +
               " ON h.ID=v.IDUkol WHERE v.Resitel IN (" + csv + ") AND v.Typ IN (" + typ +
               ") AND v.Stav IN (0,2,4,5,7)" + extra + " ORDER BY h.TerminSplneni")
    elif view == "splnene":
        sql = ("SELECT TOP 80 " + cols + " FROM EC_UkolyResitelVazba v JOIN " + base +
               " ON h.ID=v.IDUkol WHERE v.Resitel IN (" + csv + ") AND v.Stav IN (10,12) "
               "ORDER BY v.DatDokonceni DESC")
    else:
        return JSONResponse({"ok": False, "error": "neznámý pohled"})
    try:
        rows = _ec_mcp_rows(sql)
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    out = []
    for row in rows:
        if isinstance(row, dict):
            out.append({"id": row.get("id"), "predmet": row.get("predmet"), "stav": row.get("stav"),
                        "hp": row.get("hp"), "termin": row.get("termin"), "zak": row.get("zak"),
                        "zadavatel": (row.get("zadavatel") or "").strip(), "pozde": bool(row.get("pozde"))})
        elif isinstance(row, (list, tuple)) and len(row) >= 8:
            out.append({"id": row[0], "predmet": row[1], "stav": row[2], "hp": row[3],
                        "termin": row[4], "zak": row[5], "zadavatel": (row[6] or "").strip(), "pozde": bool(row[7])})
    return JSONResponse({"ok": True, "ukoly": out})


@api_router.get("/app/ec-ukoly/{tid}/detail")
async def app_ec_ukoly_detail(tid: int, req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        head = _ec_mcp_rows(
            "SELECT TOP 1 h.ID id, ISNULL(h.Predmet,'') predmet, "
            "CAST(ISNULL(h.Popis,'') AS nvarchar(max)) popis, ISNULL(h.StavText,'') stav, "
            "CONVERT(varchar(10),h.TerminSplneni,104) termin, ISNULL(h.CisloZakazky,'') zak, "
            "ISNULL(h.HotovoProcent,0) hp, "
            "LTRIM(RTRIM(ISNULL(zz.Prijmeni,'')+' '+ISNULL(zz.Jmeno,''))) zadavatel "
            "FROM EC_Ukoly h LEFT JOIN TabCisZam zz ON zz.Cislo=h.Zadavatel WHERE h.ID=" + str(int(tid)))
        pozn = _ec_mcp_rows(
            "SELECT TOP 20 ISNULL(p.Autor,'') autor, "
            "CONVERT(varchar(16),p.DatPorizeni,104) kdy, "
            "LEFT(CAST(ISNULL(p.Poznamka,'') AS nvarchar(max)),500) text "
            "FROM EC_UkolyPoznamky p WHERE p.IDUkol=" + str(int(tid)) + " ORDER BY p.DatPorizeni DESC")
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)

    def _d(row, keys):
        if isinstance(row, dict):
            return {k: row.get(k) for k in keys}
        return {keys[i]: (row[i] if i < len(row) else None) for i in range(len(keys))}
    hk = ["id", "predmet", "popis", "stav", "termin", "zak", "hp", "zadavatel"]
    h = _d(head[0], hk) if head else {}
    pk = ["autor", "kdy", "text"]
    pz = [_d(r, pk) for r in pozn]
    return JSONResponse({"ok": True, "ukol": h, "poznamky": pz})


# ── Nativní úkoly STRATEGIE (tenant.task*, schema od Marti-AI) — Marti 9.6.2026 ──
# Řešitel = člověk i AI agent (jeden user_id). Stavy: 0 zadáno,1 přijato,
# 2 zahájeno,3 vykonáno,4 reportováno,5 uzavřeno,9 zrušeno.
_TASK_STAV = {0: "zadáno", 1: "přijato", 2: "zahájeno", 3: "vykonáno",
              4: "reportováno", 5: "uzavřeno", 8: "vráceno", 9: "zrušeno"}
_TASK_NAME = ("(SELECT NULLIF(TRIM(COALESCE(uu.first_name,'')||' '||COALESCE(uu.last_name,'')),'') "
              "FROM public.users uu WHERE uu.id=%s)")

# Sdílený chat na úkol + rodičovský dohled (Marti 9.6.2026): u úkolů, kde je
# řešitelem Marti-AI (user 2), dostanou notifikaci i všichni rodiče
# (is_marti_parent) — při zadání i u každé zprávy ve vlákně. AI agenty
# (Marti-AI, Claude 23/24) mobilní notifikací nepingujeme (nemají mobil; mají
# vlastní kanál — inbox/CLAUDE_TASKS.txt).
_MARTI_AI_UID = 2
_TASK_AGENTS = {2, 23, 24}


def _is_parent(s, uid: int) -> bool:
    from sqlalchemy import text as _t
    r = s.execute(_t("SELECT COALESCE(is_marti_parent,false) FROM public.users WHERE id=:u"),
                  {"u": uid}).first()
    return bool(r and r[0])


def _is_fin_hr_group(s, uid: int) -> bool:
    """Člen skupiny HR / Finance / Účetnictví / Banka (tenant 2) = finanční+HR okruh.
    Marti 1.7.2026: účetní firma Martia2000 (Fajmonová/Šafaříková/Hrbek) + IT Jirka
    Honomichl (20) dostávají přístup k finančním/HR datům přes členství ve skupinách
    (DB-driven, bez deploye). Zrcadla/sync běh zůstává úžeji (viz _can_run_sync)."""
    from sqlalchemy import text as _t
    try:
        r = s.execute(_t(
            "SELECT 1 FROM tenant.staff_group_member m JOIN tenant.staff_group g ON g.id=m.group_id "
            "WHERE g.tenant_id=2 AND COALESCE(g.archived,false)=false "
            "  AND g.name IN ('HR','Finance','Účetnictví','Banka') AND m.user_id=:u LIMIT 1"),
            {"u": uid}).first()
        return r is not None
    except Exception:
        return False


def _can_run_sync(s, uid: int) -> bool:
    """Spouštění zrcadel / synchronizací (Helios mirror, wage-compare, learn sync) =
    JEN rodiče + IT Jirka Honomichl (20). Marti 1.7.2026: „zrcadla vidět může každý RO,
    ale spouštět jen rodiče a IT Jirka." Vidění zrcadel řeší běžná _is_cockpit/RO brána."""
    try:
        return _is_parent(s, uid) or int(uid) == 20
    except Exception:
        return False


def _is_cockpit(s, uid: int) -> bool:
    """Okruh řídicího pultu = rodiče + scoped approveři (Petra 18 finance+HR, Šárka 13
    personalistika) + členové skupin HR/Finance/Účetnictví/Banka (účetní firma Martia2000,
    IT Jirka 20). Marti 30.6.–1.7.2026. Pro reportní/účetní/mzdové/HR moduly cockpitu.
    Citlivé rodičovské operace (schvalování cizích zápisů, souhlasy, koordinace Claudů)
    zůstávají na _is_parent; SPOUŠTĚNÍ syncu na _can_run_sync (rodiče + Jirka)."""
    try:
        if _is_parent(s, uid):
            return True
        if uid in _SCOPED_APPROVER_UIDS:
            return True
        return _is_fin_hr_group(s, uid)
    except Exception:
        return False


def _task_parent_ids(s):
    from sqlalchemy import text as _t
    return [int(x[0]) for x in s.execute(_t(
        "SELECT id FROM public.users WHERE is_marti_parent=true")).fetchall()]


def _task_resitel_ids(s, tid: int):
    from sqlalchemy import text as _t
    return [int(x[0]) for x in s.execute(_t(
        "SELECT user_id FROM tenant.task_resitel WHERE task_id=:i"), {"i": tid}).fetchall()]


def _task_notify(s, recipients, actor_uid: int, title: str, message: str) -> None:
    """Notifikace (fw.mobile_command → appka cinkne) sadě příjemců kromě aktéra
    a kromě AI agentů. Dedup. Best-effort (nesmí shodit hlavní akci)."""
    from sqlalchemy import text as _t
    seen = set()
    for ru in (recipients or []):
        if ru is None:
            continue
        try:
            ru = int(ru)
        except Exception:
            continue
        if ru <= 0 or ru == actor_uid or ru in seen or ru in _TASK_AGENTS:
            continue
        seen.add(ru)
        try:
            s.execute(_t(
                "INSERT INTO fw.mobile_command (app_key, target_user_id, command_type, title, message, created_by) "
                "VALUES ('mobile', :u, 'claude_msg', :ti, :msg, :by)"),
                {"u": ru, "ti": (title or "")[:120], "msg": (message or "")[:6000], "by": actor_uid})
        except Exception:
            pass


@api_router.get("/app/task")
async def app_task_list(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    view = (req.query_params.get("view") or "moje").strip().lower()
    from sqlalchemy import text as _t
    zadname = _TASK_NAME % "t.zadavatel"
    cm, s = _att_session()
    try:
        parent = _is_parent(s, uid)
        if view == "marti_ai":
            # Rodičovský dohled: VŠECHNY úkoly, kde řešitelem je Marti-AI (2).
            if not parent:
                return JSONResponse({"ok": False, "error": "Jen pro rodiče."}, status_code=403)
            sql = ("SELECT t.id, t.predmet, "
                   "COALESCE((SELECT r.stav FROM tenant.task_resitel r WHERE r.task_id=t.id AND r.user_id=2), t.stav), "
                   "t.priorita, "
                   "to_char(t.termin,'DD.MM.YYYY') AS termin, COALESCE(t.zakazka,'') AS zak, "
                   "CASE WHEN t.termin IS NOT NULL AND t.termin<now() AND t.stav<2 THEN true ELSE false END AS pozde, "
                   + zadname + " AS zadavatel "
                   "FROM tenant.task t WHERE t.tenant_id=2 "
                   "AND EXISTS (SELECT 1 FROM tenant.task_resitel r WHERE r.task_id=t.id AND r.user_id=2) "
                   "ORDER BY t.stav, t.priorita DESC, t.id DESC")
        elif view == "zadane":
            sql = ("SELECT t.id, t.predmet, "
                   "COALESCE((SELECT MAX(r.stav) FROM tenant.task_resitel r WHERE r.task_id=t.id), t.stav), "
                   "t.priorita, "
                   "to_char(t.termin,'DD.MM.YYYY') AS termin, COALESCE(t.zakazka,'') AS zak, "
                   "CASE WHEN t.termin IS NOT NULL AND t.termin<now() AND t.stav<2 THEN true ELSE false END AS pozde, "
                   + zadname + " AS zadavatel "
                   "FROM tenant.task t WHERE t.tenant_id=2 AND t.zadavatel=:u AND t.stav<2 "
                   "ORDER BY t.termin NULLS LAST, t.priorita DESC, t.id DESC")
        else:
            if view == "splnene":
                cond, order, urg = "r.stav IN (3,4,5)", "r.updated_at DESC, t.id DESC", ""
            elif view == "urgentni":
                cond, order, urg = "r.stav IN (0,1,2)", "t.termin NULLS LAST", " AND t.termin IS NOT NULL AND t.termin<now()"
            else:
                cond, order, urg = "r.stav IN (0,1,2)", "t.termin NULLS LAST, t.priorita DESC, t.id DESC", ""
            sql = ("SELECT t.id, t.predmet, r.stav, t.priorita, "
                   "to_char(t.termin,'DD.MM.YYYY') AS termin, COALESCE(t.zakazka,'') AS zak, "
                   "CASE WHEN t.termin IS NOT NULL AND t.termin<now() AND r.stav<3 THEN true ELSE false END AS pozde, "
                   + zadname + " AS zadavatel "
                   "FROM tenant.task_resitel r JOIN tenant.task t ON t.id=r.task_id "
                   "WHERE t.tenant_id=2 AND r.user_id=:u AND " + cond + urg + " ORDER BY " + order)
        rows = s.execute(_t(sql), {"u": uid}).fetchall()
        out = [{"id": r[0], "predmet": r[1], "stav": int(r[2] or 0),
                "stav_txt": _TASK_STAV.get(int(r[2] or 0), ""), "priorita": int(r[3] or 0),
                "termin": r[4], "zak": r[5], "pozde": bool(r[6]), "zadavatel": (r[7] or "")} for r in rows]
        return JSONResponse({"ok": True, "ukoly": out, "is_parent": parent})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/task")
async def app_task_create(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        body = {}
    # Marti 9.6.: žádný povinný předmět — úkol je i vzkaz/poznámka. Jen text.
    # Předmět (titulek do seznamu) = první řádek; celý text → popis (nic se neztratí).
    text = str((body or {}).get("text") or (body or {}).get("predmet") or "").strip()
    if not text:
        return JSONResponse({"ok": False, "error": "Napiš text úkolu."})
    _lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    predmet = (_lines[0] if _lines else text)[:200]
    popis = (str((body or {}).get("popis") or "").strip() or None)
    if popis is None and text != predmet:
        popis = text
    termin = (str((body or {}).get("termin") or "").strip() or None)
    try:
        priorita = int((body or {}).get("priorita") or 0)
    except Exception:
        priorita = 0
    zakazka = (str((body or {}).get("zakazka") or "").strip() or None)
    resitele = (body or {}).get("resitele") or [uid]
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        r = s.execute(_t(
            "INSERT INTO tenant.task (tenant_id,predmet,popis,stav,priorita,termin,zakazka,zadavatel,created_by) "
            "VALUES (2,:p,:po,0,:pr, CAST(:tm AS timestamptz), :zk,:u,:u) RETURNING id"),
            {"p": predmet, "po": popis, "pr": priorita, "tm": termin, "zk": zakazka, "u": uid}).first()
        tid = r[0]
        seen = set()
        for ru in resitele:
            try:
                ruid = int(ru)
            except Exception:
                continue
            if ruid in seen:
                continue
            seen.add(ruid)
            s.execute(_t("INSERT INTO tenant.task_resitel (task_id,user_id,stav) VALUES (:t,:r,0) "
                         "ON CONFLICT (task_id,user_id) DO NOTHING"), {"t": tid, "r": ruid})
        s.execute(_t("INSERT INTO tenant.task_historie (task_id,actor_id,akce,novy_stav) "
                     "VALUES (:t,:u,'vytvořen',0)"), {"t": tid, "u": uid})
        # Notifikace (Marti 9.6.): řešitelům-lidem cinkni nový úkol; u Marti-AI i rodičům.
        try:
            _rids = [int(x) for x in seen]
            _an = _user_jmeno(s, uid)
            _task_notify(s, _rids, uid, "🗒 Nový úkol", (predmet[:80] + " — zadal " + _an))
            if _MARTI_AI_UID in _rids:
                _task_notify(s, _task_parent_ids(s), uid, "🤖 Marti-AI má nový úkol",
                             (predmet[:80] + " — zadal " + _an))
        except Exception:
            pass
        s.commit()
        return JSONResponse({"ok": True, "id": tid})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/task/{tid}")
async def app_task_detail(tid: int, req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        h = s.execute(_t(
            "SELECT t.id, t.predmet, COALESCE(t.popis,''), t.stav, t.priorita, "
            "to_char(t.termin,'DD.MM.YYYY'), COALESCE(t.zakazka,''), t.zadavatel, " + (_TASK_NAME % "t.zadavatel") +
            " FROM tenant.task t WHERE t.id=:i AND t.tenant_id=2"), {"i": tid}).first()
        if not h:
            return JSONResponse({"ok": False, "error": "úkol neexistuje"})
        res = s.execute(_t(
            "SELECT r.user_id, r.stav, " + (_TASK_NAME % "r.user_id") +
            " FROM tenant.task_resitel r WHERE r.task_id=:i ORDER BY r.id"), {"i": tid}).fetchall()
        poz = s.execute(_t(
            "SELECT " + (_TASK_NAME % "p.author_id") + ", p.obsah, to_char(p.created_at,'DD.MM HH24:MI'), p.author_id "
            "FROM tenant.task_poznamka p WHERE p.task_id=:i ORDER BY p.created_at DESC LIMIT 50"), {"i": tid}).fetchall()
        myr = s.execute(_t("SELECT stav FROM tenant.task_resitel WHERE task_id=:i AND user_id=:u"),
                        {"i": tid, "u": uid}).first()
        ukol = {"id": h[0], "predmet": h[1], "popis": h[2], "stav": int(h[3] or 0),
                "priorita": int(h[4] or 0), "termin": h[5], "zak": h[6], "zadavatel": (h[8] or "")}
        return JSONResponse({"ok": True, "ukol": ukol,
                             "resitele": [{"jmeno": (rr[2] or ("#" + str(rr[0]))), "stav": int(rr[1] or 0),
                                           "stav_txt": _TASK_STAV.get(int(rr[1] or 0), "")} for rr in res],
                             "poznamky": [{"autor": (pp[0] or ""), "text": pp[1], "kdy": pp[2],
                                           "autor_id": int(pp[3] or 0)} for pp in poz],
                             "me": uid,
                             "muj_stav": (int(myr[0]) if myr else None),
                             "jsem_zadavatel": (h[7] == uid)})
    except Exception as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


