@api_router.post("/app/shared/switch")
async def app_shared_switch(req: Request, response: Response) -> dict:
    cur = _uid_from_token_or_cookie(req)
    if not cur:
        return {"ok": False, "error": "unauthorized"}
    try:
        body = await req.json()
    except Exception:
        body = {}
    dk = str((body or {}).get("device_key") or "").strip()[:80]
    try:
        target = int((body or {}).get("user_id"))
    except Exception:
        return {"ok": False, "error": "chybí user_id"}
    pin = str((body or {}).get("pin") or "").strip()
    from sqlalchemy import text as _t
    from core.config import settings as _cfg
    cm, s = _att_session()
    try:
        inlist = s.execute(_t("SELECT 1 FROM tenant.shared_device_user "
                              "WHERE device_key=:d AND user_id=:u AND tenant_id=2"),
                           {"d": dk, "u": target}).first()
        if not inlist:
            return {"ok": False, "error": "Tento uživatel není na tomto telefonu."}
        g = _pin_gate(s, target, pin)
        if g is not None:
            return g
        # PIN OK → APK: override aktivního usera pro Bearer token (sdílený telefon)
        import hashlib as _hsw
        auth = req.headers.get("authorization") or ""
        if auth.lower().startswith("bearer "):
            tok = auth[7:].strip()
            if tok:
                th = _hsw.sha256(tok.encode("utf-8")).hexdigest()
                s.execute(_t("INSERT INTO tenant.shared_active (token_hash,user_id,device_key) "
                             "VALUES (:h,:u,:d) ON CONFLICT (token_hash) DO UPDATE SET "
                             "user_id=EXCLUDED.user_id, device_key=EXCLUDED.device_key, set_at=now()"),
                          {"h": th, "u": target, "d": dk})
                s.commit()
        # PWA: přepni aktivní cookie na target usera
        response.set_cookie(key="user_id", value=str(target), httponly=True,
                            max_age=60 * 60 * 24 * 30, secure=_cfg.cookie_secure,
                            samesite=_cfg.cookie_samesite)
        response.set_cookie(key="tenant_id", value="2", httponly=True,
                            max_age=60 * 60 * 24 * 30, secure=_cfg.cookie_secure,
                            samesite=_cfg.cookie_samesite)
        return {"ok": True, "user_id": target}
    except Exception as exc:
        return {"ok": False, "error": str(exc)}
    finally:
        cm.__exit__(None, None, None)


def _verify_active_handoff(raw: str) -> int | None:
    """Ověří podepsaný handoff `uid.exp.sig` (HMAC-SHA256, secret=SMS_GATEWAY_KEY).
    Vrátí user_id při platném podpisu a neexpirovaném tokenu, jinak None.
    Pár k modules.auth.api.router._sign_active_handoff. Kristý 15.6."""
    try:
        import hmac as _hm, hashlib as _hl, time as _tm
        from core.config import settings as _cfg
        secret = (_cfg.sms_gateway_key or "").encode("utf-8")
        if len(secret) < 16:
            return None
        parts = (raw or "").split(".")
        if len(parts) != 3:
            return None
        uid_s, exp_s, sig = parts
        if int(exp_s) < int(_tm.time()):
            return None
        msg = f"{int(uid_s)}.{int(exp_s)}"
        good = _hm.new(secret, msg.encode("utf-8"), _hl.sha256).hexdigest()[:32]
        if not _hm.compare_digest(good, sig):
            return None
        return int(uid_s)
    except Exception:
        return None


@api_router.post("/app/shared/sync-active")
async def app_shared_sync_active(req: Request) -> dict:
    """Po přihlášení e-mailem/SMS přepne aktivního uživatele na sdíleném telefonu.
    Nativní appka posílá jen Bearer (token zařízení) BEZ cookie, takže identitu
    z loginu serveru předáme PODEPSANÝM handoffem (cookie stg_active → JS → tělo).
    Bearer určí zařízení (token_hash → řádek tenant.shared_active), handoff určí
    ověřeného uživatele. Resolver _uid_from_token_or_cookie pak vrací tu identitu.
    PWA (bez Bearer) = no-op, ta jede čistě po cookie. Kristý 15.6."""
    auth = req.headers.get("authorization") or ""
    if not auth.lower().startswith("bearer "):
        return {"ok": True, "skipped": "no_bearer"}   # PWA: cookie cesta funguje sama
    tok = auth[7:].strip()
    if not tok:
        return {"ok": True, "skipped": "no_bearer"}
    try:
        body = await req.json()
    except Exception:
        body = {}
    handoff = str((body or {}).get("handoff") or "").strip()
    target = _verify_active_handoff(handoff)
    if target is None:
        return {"ok": False, "error": "bad_handoff"}
    dk = str((body or {}).get("device_key") or "").strip()[:80] or None
    import hashlib as _hsa
    from sqlalchemy import text as _t
    th = _hsa.sha256(tok.encode("utf-8")).hexdigest()
    cm, s = _att_session()
    try:
        # Bearer token musí patřit reálnému (živému) zařízení.
        owner = s.execute(_t('SELECT user_id FROM "user".carddav_token '
                             'WHERE token_hash=:h AND revoked_at IS NULL'),
                          {"h": th}).scalar()
        if owner is None:
            return {"ok": True, "skipped": "no_device"}
        if not s.execute(_t("SELECT 1 FROM public.users WHERE id=:u"),
                         {"u": target}).first():
            return {"ok": True, "skipped": "no_user"}
        s.execute(_t("INSERT INTO tenant.shared_active (token_hash,user_id,device_key) "
                     "VALUES (:h,:u,:d) ON CONFLICT (token_hash) DO UPDATE SET "
                     "user_id=EXCLUDED.user_id, device_key=COALESCE(EXCLUDED.device_key,tenant.shared_active.device_key), set_at=now()"),
                  {"h": th, "u": target, "d": dk})
        s.commit()
        return {"ok": True, "user_id": target}
    except Exception:
        try:
            s.rollback()
        except Exception:
            pass
        return {"ok": False, "error": "db_error"}
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/shared/remove")
async def app_shared_remove(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        body = {}
    dk = str((body or {}).get("device_key") or "").strip()[:80]
    try:
        target = int((body or {}).get("user_id"))
    except Exception:
        return JSONResponse({"ok": False, "error": "chybí user_id"})
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        s.execute(_t("DELETE FROM tenant.shared_device_user "
                     "WHERE device_key=:d AND user_id=:u AND tenant_id=2"),
                  {"d": dk, "u": target})
        s.commit()
        return JSONResponse({"ok": True})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


# ── Sdílený telefon: bootstrap (parent přidá lidi + PIN přes SMS) — Marti 9.6. ──
@api_router.post("/app/shared/assign")
async def app_shared_assign(req: Request) -> JSONResponse:
    """Rodič přidá libovolného usera na sdílené zařízení (až 4)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not is_marti_parent(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        body = await req.json()
    except Exception:
        body = {}
    dk = str((body or {}).get("device_key") or "").strip()[:80]
    try:
        target = int((body or {}).get("user_id"))
    except Exception:
        return JSONResponse({"ok": False, "error": "chybí user_id"})
    if not dk:
        return JSONResponse({"ok": False, "error": "chybí device_key"})
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        ex = s.execute(_t("SELECT 1 FROM tenant.shared_device_user "
                          "WHERE device_key=:d AND user_id=:u AND tenant_id=2"),
                       {"d": dk, "u": target}).first()
        if not ex:
            cnt = s.execute(_t("SELECT count(*) FROM tenant.shared_device_user "
                               "WHERE device_key=:d AND tenant_id=2"), {"d": dk}).scalar()
            if (cnt or 0) >= 4:
                return JSONResponse({"ok": False, "error": "Na telefonu jsou už 4 lidé."})
        s.execute(_t("INSERT INTO tenant.shared_device_user (tenant_id,device_key,user_id) "
                     "VALUES (2,:d,:u) ON CONFLICT (device_key,user_id) DO NOTHING"),
                  {"d": dk, "u": target})
        s.commit()
        return JSONResponse({"ok": True})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/shared/set-phone")
async def app_shared_set_phone(req: Request) -> JSONResponse:
    """Rodič zadá/aktualizuje telefonní číslo daného usera pro ověření PINu
    sdíleného telefonu — zacelení mezery: appka jinak číslo do user_contacts
    nezapisuje (phone-set/phone-verify míří do fw.mobile_device). Číslo se uloží
    jako NEOVĚŘENÉ (is_verified=false); fakticky ho ověří teprve SMS kód z
    'pin-send', který na něj přijde. Parent-only + audit. Claude-24 + Kristý 11.6.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not is_marti_parent(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        body = await req.json()
        target = int((body or {}).get("user_id"))
    except Exception:
        return JSONResponse({"ok": False, "error": "chybí user_id"})
    phone = (str((body or {}).get("phone_number") or "")).strip()[:32]
    if len(phone.replace("+", "").replace(" ", "")) < 6:
        return JSONResponse({"ok": False, "error": "invalid_phone", "note": "Zadej platné telefonní číslo."})
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        existing = s.execute(_t(
            "SELECT id FROM public.user_contacts "
            "WHERE user_id=:u AND contact_type='phone' "
            "ORDER BY COALESCE(is_primary,false) DESC, id LIMIT 1"),
            {"u": target}).scalar()
        if existing:
            s.execute(_t(
                "UPDATE public.user_contacts SET contact_value=:p, status='active', "
                "is_verified=false, updated_at=now() WHERE id=:id"),
                {"p": phone, "id": existing})
        else:
            s.execute(_t(
                "INSERT INTO public.user_contacts "
                "(user_id, contact_type, contact_value, label, is_primary, is_verified, status) "
                "VALUES (:u,'phone',:p,'work', true, false, 'active')"),
                {"u": target, "p": phone})
        s.commit()
        try:
            from core.log_queue import log_event as _le
            _le(level="info", source="py", module_id="app.shared.set_phone",
                message="rodic %s nastavil telefon userovi %s (sdileny telefon PIN)" % (uid, target),
                extra={"by_uid": uid, "target_user_id": target})
        except Exception:
            pass
        return JSONResponse({"ok": True})
    except Exception as exc:
        s.rollback()
        try:
            from core.log_queue import log_event as _le2
            _le2(level="error", source="py", module_id="app.shared.set_phone",
                 message="set_phone selhalo: " + type(exc).__name__, extra={"by_uid": uid})
        except Exception:
            pass
        return JSONResponse({"ok": False, "error": "ulozeni_selhalo"}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


