@api_router.post("/app/shared/pin-send")
async def app_shared_pin_send(req: Request) -> JSONResponse:
    """Rodič pošle SMS kód danému userovi na nastavení PINu sdíleného telefonu."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not is_marti_parent(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        body = await req.json()
        target = int((body or {}).get("user_id"))
    except Exception:
        return JSONResponse({"ok": False, "error": "chybí user_id"})
    from sqlalchemy import text as _t
    import secrets as _sec
    from modules.notifications.application.sms_service import queue_sms
    cm, s = _att_session()
    try:
        phone = s.execute(_t(
            "SELECT contact_value FROM public.user_contacts "
            "WHERE user_id=:u AND contact_type='phone' AND COALESCE(status,'active')='active' "
            "ORDER BY COALESCE(is_verified,false) DESC, COALESCE(is_primary,false) DESC, id LIMIT 1"),
            {"u": target}).scalar()
        if not phone:
            return JSONResponse({"ok": False, "error": "no_phone", "note": "Tento user nemá ověřený mobil."})
        cnt = s.execute(_t("SELECT count(*) FROM fw.phone_verify_code "
                           "WHERE user_id=:u AND created_at > now() - interval '15 minutes'"),
                        {"u": target}).scalar() or 0
        if cnt >= 3:
            return JSONResponse({"ok": False, "error": "rate_limited", "note": "Moc SMS, zkus za 15 min."})
        s.execute(_t("UPDATE fw.phone_verify_code SET used_at=now() WHERE user_id=:u AND used_at IS NULL"),
                  {"u": target})
        code = "%06d" % _sec.randbelow(1000000)
        s.execute(_t("INSERT INTO fw.phone_verify_code (user_id, phone, code, expires_at) "
                     "VALUES (:u,:p,:c, now() + interval '10 minutes')"),
                  {"u": target, "p": phone, "c": code})
        s.commit()
        queue_sms(to=phone, body="STRATEGIE: kod pro nastaveni PIN je " + code + ". Plati 10 minut.",
                  purpose="pin_reset", user_id=target)
        masked = ("*" * max(len(phone) - 3, 0)) + phone[-3:]
        return JSONResponse({"ok": True, "phone": masked})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/shared/pin-send-email")
async def app_shared_pin_send_email(req: Request) -> JSONResponse:
    """Rodič pošle ověřovací kód pro nastavení PINu na E-MAIL daného usera —
    alternativa k SMS (když SMS brána zlobí). Kód jde do STEJNÉ fw.phone_verify_code,
    takže /pin-set ho ověří beze změny. Parent-only. Kristý 15.6.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not is_marti_parent(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        body = await req.json()
        target = int((body or {}).get("user_id"))
    except Exception:
        return JSONResponse({"ok": False, "error": "chybí user_id"})
    from sqlalchemy import text as _t
    import secrets as _sec
    cm, s = _att_session()
    code = None
    email = None
    try:
        email = s.execute(_t(
            "SELECT contact_value FROM public.user_contacts "
            "WHERE user_id=:u AND contact_type='email' AND COALESCE(status,'active')='active' "
            "ORDER BY COALESCE(is_verified,false) DESC, COALESCE(is_primary,false) DESC, id LIMIT 1"),
            {"u": target}).scalar()
        if not email:
            return JSONResponse({"ok": False, "error": "no_email", "note": "Tento uživatel nemá e-mail."})
        cnt = s.execute(_t("SELECT count(*) FROM fw.phone_verify_code "
                           "WHERE user_id=:u AND created_at > now() - interval '15 minutes'"),
                        {"u": target}).scalar() or 0
        if cnt >= 5:
            return JSONResponse({"ok": False, "error": "rate_limited", "note": "Moc kódů, zkus za 15 min."})
        s.execute(_t("UPDATE fw.phone_verify_code SET used_at=now() WHERE user_id=:u AND used_at IS NULL"),
                  {"u": target})
        code = "%06d" % _sec.randbelow(1000000)
        s.execute(_t("INSERT INTO fw.phone_verify_code (user_id, phone, code, expires_at) "
                     "VALUES (:u,:p,:c, now() + interval '10 minutes')"),
                  {"u": target, "p": email, "c": code})
        s.commit()
    except Exception:
        s.rollback()
        return JSONResponse({"ok": False, "error": "db_error"}, status_code=500)
    finally:
        cm.__exit__(None, None, None)
    # E-mail posíláme MIMO DB session.
    try:
        from modules.notifications.application.email_service import send_email, _get_default_persona_id
        sent = send_email(
            to=email,
            subject="STRATEGIE: kód pro nastavení PIN",
            body=("Tvůj ověřovací kód pro nastavení PINu ve STRATEGII je: " + code +
                  "\n\nKód platí 10 minut. Zadej ho v aplikaci u 'Nastavit PIN'."
                  "\n\nPokud jsi o to nežádal(a), tento e-mail ignoruj."),
            persona_id=_get_default_persona_id(),
        )
    except Exception:
        sent = False
    if not sent:
        return JSONResponse({"ok": False, "error": "email_failed", "note": "E-mail se nepodařilo odeslat."})
    # maskovaný e-mail pro UI (a***@domena)
    try:
        _loc, _, _dom = (email or "").partition("@")
        masked = ((_loc[0] + "***") if _loc else "***") + "@" + _dom
    except Exception:
        masked = "e-mail"
    return JSONResponse({"ok": True, "email": masked})


@api_router.post("/app/shared/pin-set")
async def app_shared_pin_set(req: Request) -> JSONResponse:
    """Nastaví PIN danému userovi po ověření SMS kódem (kód = autorizace)."""
    try:
        body = await req.json()
        target = int((body or {}).get("user_id"))
    except Exception:
        return JSONResponse({"ok": False, "error": "chybí user_id"})
    code = str((body or {}).get("code") or "").strip()
    pin = str((body or {}).get("pin") or "").strip()
    if not (pin.isdigit() and len(pin) == 4):
        return JSONResponse({"ok": False, "error": "pin_invalid", "note": "PIN jsou 4 číslice."})
    from sqlalchemy import text as _t
    import secrets as _sec
    cm, s = _att_session()
    try:
        if not _pin_consume_sms_code(s, target, code):
            return JSONResponse({"ok": False, "error": "code_wrong", "note": "SMS kód nesedí nebo vypršel."})
        salt = _sec.token_hex(8)
        s.execute(_t(
            "INSERT INTO fw.user_pin (user_id, pin_hash, failed_attempts, locked_until) "
            "VALUES (:u,:h,0,NULL) ON CONFLICT (user_id) DO UPDATE SET pin_hash=EXCLUDED.pin_hash, "
            "failed_attempts=0, locked_until=NULL, updated_at=now()"),
            {"u": target, "h": salt + "$" + _pin_hash(pin, salt)})
        s.commit()
        return JSONResponse({"ok": True})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/attendance/announce")
async def att_announce(req: Request) -> JSONResponse:
    """Marti 7.6.: presence status v lidské řeči („Už jedu do práce…", „Mám
    jednání do cca…"). Řádek status='announced' (hours NULL → nepočítá se),
    checkin ho supersedne. Může běžet i vedle otevřené směny (jednání)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    try:
        body = await req.json()
    except Exception:
        body = {}
    note = _att_presence_note(body)
    # Marti 7.6. večer: volitelně i pro BUDOUCÍ den („v pátek končím dříve") —
    # status se uloží na ten den a „Kdo kde dnes" ho ten den ukáže.
    from datetime import datetime as _dta
    day = None
    draw = str((body or {}).get("day") or "").strip()[:10]
    if draw:
        try:
            dd = _dta.strptime(draw, "%Y-%m-%d").date()
            if dd < _dta.now().date():
                return JSONResponse({"ok": False, "error": "Minulý den ohlásit nejde."}, status_code=400)
            day = dd.isoformat()
        except Exception:
            return JSONResponse({"ok": False, "error": "invalid_day"}, status_code=400)
    cm, s = _att_session()
    try:
        emp = _att_employee(s, uid)
        # Marti 29.6.: když ohlášení znamená ABSENCI (dovolená/nemoc/lékař/OČR/neplacené),
        # NEzakládej 'work' ohlášení (vznikla past: Eliška ohlásila dovolenou → 'work' + automat
        # dopíchal práci). Místo toho založ žádost o absenci → schválení vedoucím rovnou zapíše
        # absenční job do docházky (/absence/decide materializuje att_entry).
        _abs_typ = _announce_absence_typ(note)
        if _abs_typ and emp:
            _dd = day or _dta.now().date().isoformat()
            _mgr = None
            try:
                _mgr = s.execute(_t("SELECT tenant.resolve_role(2, :e, 'attendance_supervisor')"), {"e": emp}).scalar()
            except Exception:
                _mgr = None
            _rid = s.execute(_t(
                "INSERT INTO tenant.att_absence_request (tenant_id,employee_id,user_id,typ,datum_od,datum_do,"
                "hours_per_day,note,stav,manager_user_id) "
                "VALUES (2,:e,:u,:ty,:d,:d,8,:n,'pending',:m) RETURNING id"),
                {"e": emp, "u": uid, "ty": _abs_typ, "d": _dd, "n": note, "m": _mgr}).scalar()
            _who = s.execute(_t(
                "SELECT COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),''), em.full_name) "
                "FROM tenant.att_employee em LEFT JOIN public.users u ON u.id=em.user_id WHERE em.id=:e"),
                {"e": emp}).scalar() or "Zaměstnanec"
            try:
                _abs_notify(s, _mgr if _mgr and int(_mgr) != uid else 1, "🗓️ Nová žádost o absenci",
                            _who + " žádá o „" + _ABS_TYP[_abs_typ] + "“ na " + _dd + ((" — " + note) if note else "")
                            + ". Rozhodni v Docházce → Žádosti o absenci (schválení rovnou zapíše do docházky).")
            except Exception:
                pass
            s.commit()
            return JSONResponse({"ok": True, "absence_request": _rid, "typ": _abs_typ,
                                 "note": "Rozpoznal jsem absenci („" + _ABS_TYP[_abs_typ] + "“) — založil jsem žádost, "
                                         "čeká na schválení vedoucím a pak se rovnou zapíše do docházky."})
        s.execute(_t("UPDATE tenant.att_entry SET status='superseded', updated_at=now() "
                     "WHERE tenant_id=:t AND employee_id=:e "
                     "AND entry_date = COALESCE(CAST(:d AS date), current_date) AND status='announced'"),
                  {"t": _ATT_TENANT, "e": emp, "d": day})
        wt = _att_work_type(s)
        s.execute(_t(
            "INSERT INTO tenant.att_entry (tenant_id,employee_id,entry_date,entry_type_id,started_at,"
            "status,source,is_active,note,created_by_id,created_at,updated_at) "
            "VALUES (:t,:e,COALESCE(CAST(:d AS date), current_date),:wt,now(),'announced','mobile_app',false,:n,:u,now(),now())"),
            {"t": _ATT_TENANT, "e": emp, "d": day, "wt": wt, "n": note, "u": uid})
        s.commit()
        return JSONResponse({"ok": True, "note": note})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


