# =====================================================================
# Marti 14.6.: Osa přiřazení práce (work_alloc) — overlay MIMO jádro docházky.
# Úsek = zakázka + činnost dohromady. Změna kterékoli = nový úsek.
# Životní cyklus vázán na směnu (otevře při práci, zavře při pauze/konci).
# =====================================================================
def _wa_close_running(s, uid: int) -> None:
    from sqlalchemy import text as _t
    s.execute(_t("UPDATE tenant.work_alloc SET ended_at=now(), updated_at=now() "
                 "WHERE tenant_id=:t AND user_id=:u AND ended_at IS NULL"),
              {"t": _ATT_TENANT, "u": uid})


def _wa_latest_today(s, uid: int):
    from sqlalchemy import text as _t
    return s.execute(_t(
        "SELECT project_ref, project_nazev, cinnost_id, cinnost_name, cinnost_icon, is_rezie "
        "FROM tenant.work_alloc WHERE tenant_id=:t AND user_id=:u "
        "AND started_at::date=current_date ORDER BY id DESC LIMIT 1"),
        {"t": _ATT_TENANT, "u": uid}).mappings().first()


def _wa_running(s, uid: int):
    from sqlalchemy import text as _t
    return s.execute(_t(
        "SELECT id, project_ref, project_nazev, cinnost_id, cinnost_name, cinnost_icon, is_rezie, "
        "to_char(started_at,'HH24:MI') AS since "
        "FROM tenant.work_alloc WHERE tenant_id=:t AND user_id=:u AND ended_at IS NULL "
        "ORDER BY id DESC LIMIT 1"),
        {"t": _ATT_TENANT, "u": uid}).mappings().first()


def _wa_open(s, uid: int, project_ref=None, project_nazev=None,
             cinnost_id=None, cinnost_name=None, cinnost_icon=None,
             is_rezie=False, source="mobile") -> None:
    from sqlalchemy import text as _t
    _wa_close_running(s, uid)
    # Marti 19.6.: přepnutí zakázky → výběr činnosti vytvářelo PARAZITNÍ úsek (skoro nula).
    # Smaž právě zavřený parazit (< 60 s) a nový úsek převezme jeho začátek (spojitě, bez mezery).
    st_override = None
    prev = s.execute(_t(
        "SELECT id, started_at, EXTRACT(EPOCH FROM (ended_at - started_at)) AS sec "
        "FROM tenant.work_alloc WHERE tenant_id=:t AND user_id=:u AND ended_at IS NOT NULL "
        "AND started_at::date=current_date ORDER BY id DESC LIMIT 1"),
        {"t": _ATT_TENANT, "u": uid}).mappings().first()
    if prev and prev["sec"] is not None and float(prev["sec"]) < 60:
        st_override = prev["started_at"]
        s.execute(_t("DELETE FROM tenant.work_alloc WHERE tenant_id=:t AND id=:id"),
                  {"t": _ATT_TENANT, "id": prev["id"]})
    s.execute(_t(
        "INSERT INTO tenant.work_alloc (tenant_id,user_id,started_at,project_ref,project_nazev,"
        "cinnost_id,cinnost_name,cinnost_icon,is_rezie,source,created_at,updated_at) "
        "VALUES (:t,:u,COALESCE(CAST(:st AS timestamptz),now()),:pr,:pn,:ci,:cn,:cic,:rz,:src,now(),now())"),
        {"t": _ATT_TENANT, "u": uid, "st": st_override, "pr": project_ref, "pn": project_nazev,
         "ci": cinnost_id, "cn": cinnost_name, "cic": cinnost_icon,
         "rz": bool(is_rezie), "src": source})


def _att_is_working(s, emp: int) -> bool:
    """True = běží pracovní/režijní směna (ne pauza / konec dne / cesta)."""
    from sqlalchemy import text as _t
    r = s.execute(_t(
        "SELECT COALESCE(et.code,'') FROM tenant.att_entry a "
        "LEFT JOIN tenant.att_entry_type et ON et.id=a.entry_type_id "
        "WHERE a.tenant_id=:t AND a.employee_id=:e AND a.is_active=true ORDER BY a.id DESC LIMIT 1"),
        {"t": _ATT_TENANT, "e": emp}).first()
    return bool(r) and (r[0] in ("work", "overhead", ""))


def _att_apply_work_selection(s, emp: int, project_ref, is_rezie) -> None:
    """Marti 15.6.: promítne výběr zakázka/režie do BĚŽÍCÍHO pracovního att_entry,
    aby přehledy klasifikovaly správně. Režie => typ 'overhead' (= maká, ne 'čekám').
    Mění typ a project_ref IN-PLACE (žádné dělení záznamu). Nesahá na pauzu/cestu/konec dne."""
    from sqlalchemy import text as _t
    cur = s.execute(_t(
        "SELECT a.id, COALESCE(et.code,'') FROM tenant.att_entry a "
        "LEFT JOIN tenant.att_entry_type et ON et.id=a.entry_type_id "
        "WHERE a.tenant_id=:t AND a.employee_id=:e AND a.is_active=true ORDER BY a.id DESC LIMIT 1"),
        {"t": _ATT_TENANT, "e": emp}).first()
    if not cur or cur[1] in ("break", "day_end", "commute"):
        return
    if is_rezie:
        ot = s.execute(_t("SELECT id FROM tenant.att_entry_type WHERE tenant_id=:t AND code='overhead'"),
                       {"t": _ATT_TENANT}).scalar()
        if ot:
            s.execute(_t("UPDATE tenant.att_entry SET entry_type_id=:ty, project_ref=NULL, updated_at=now() WHERE id=:id"),
                      {"ty": ot, "id": cur[0]})
    else:
        wt = s.execute(_t("SELECT id FROM tenant.att_entry_type WHERE tenant_id=:t AND code='work'"),
                       {"t": _ATT_TENANT}).scalar()
        s.execute(_t("UPDATE tenant.att_entry SET entry_type_id=COALESCE(:ty,entry_type_id), "
                     "project_ref=:pr, updated_at=now() WHERE id=:id"),
                  {"ty": wt, "pr": project_ref, "id": cur[0]})


def _wp_get(s, uid: int):
    from sqlalchemy import text as _t
    return s.execute(_t(
        "SELECT project_ref, project_nazev, cinnost_id, cinnost_name, cinnost_icon, is_rezie "
        "FROM tenant.work_pref WHERE tenant_id=:t AND user_id=:u"),
        {"t": _ATT_TENANT, "u": uid}).mappings().first()


def _wp_save(s, uid: int, project_ref=None, project_nazev=None,
             cinnost_id=None, cinnost_name=None, cinnost_icon=None, is_rezie=False) -> None:
    from sqlalchemy import text as _t
    s.execute(_t(
        "INSERT INTO tenant.work_pref (tenant_id,user_id,project_ref,project_nazev,"
        "cinnost_id,cinnost_name,cinnost_icon,is_rezie,updated_at) "
        "VALUES (:t,:u,:pr,:pn,:ci,:cn,:cic,:rz,now()) "
        "ON CONFLICT (tenant_id,user_id) DO UPDATE SET project_ref=:pr,project_nazev=:pn,"
        "cinnost_id=:ci,cinnost_name=:cn,cinnost_icon=:cic,is_rezie=:rz,updated_at=now()"),
        {"t": _ATT_TENANT, "u": uid, "pr": project_ref, "pn": project_nazev,
         "ci": cinnost_id, "cn": cinnost_name, "cic": cinnost_icon, "rz": bool(is_rezie)})


@api_router.get("/app/work/state")
async def app_work_state(req: Request) -> JSONResponse:
    """Předvýběr (work_pref) + zda makám + běžící úsek. Funguje i mimo práci."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    cm, s = _att_session()
    try:
        emp = _att_employee(s, uid)
        working = _att_is_working(s, emp)
        cur = _wa_running(s, uid) if working else None
        pref = _wp_get(s, uid)
        s.commit()
        return JSONResponse(jsonable_encoder({
            "ok": True, "at_work": working,
            "working_alloc": (dict(cur) if cur else None),
            "pref": (dict(pref) if pref else {})}))
    finally:
        cm.__exit__(None, None, None)


