@api_router.get("/app/cockpit/access")
async def cockpit_access(req: Request) -> JSONResponse:
    """Kdo má přístup do řídicího pultu /marti (ikonka avatarů vlevo od 🚀 +
    cockpit + moduly uvnitř). Okruh = rodiče + scoped approveři: Petra (18) a
    Šárka (13). Frontend (deploy_button.js) podle toho vykreslí avatary nezávisle
    na rocket-gate (ten zůstává jen rodičům). Marti 30.6.2026."""
    uid = _uid_from_token_or_cookie(req)
    cockpit_allowed = bool(uid and (is_marti_parent(uid) or uid in _SCOPED_APPROVER_UIDS))
    is_vp = bool(uid and uid in _VP_TEAM_UIDS)
    # Příznaky pro vykreslování dlaždic dle role (Marti 1.7.2026 — member RO rozcestník):
    #   fin  = plný finanční/HR okruh (rodiče + scoped + skupiny HR/Finance, vč. účetní firmy Martia2000)
    #   sync = smí spouštět zrcadla/sync (rodiče + IT Jirka 20)
    #   parent = rodič (řízení/ops/systém/AI)
    is_parent_f = bool(uid and is_marti_parent(uid))
    fin = is_sync = False
    if uid:
        from core.database_data import get_data_session as _gca
        _sca = _gca()
        try:
            fin = _is_cockpit(_sca, uid)
            is_sync = _can_run_sync(_sca, uid)
        except Exception:
            fin = is_sync = False
        finally:
            try:
                _sca.close()
            except Exception:
                pass
    team = []
    if cockpit_allowed:
        team += [
            {"uid": 1,  "ini": "M", "name": "Marti Pašek",     "role": "zakladatel",     "col": "#2e5d3a", "cockpit": "/marti"},
            {"uid": 11, "ini": "K", "name": "Kristýna",         "role": "procesy",        "col": "#4a3a6e", "cockpit": "/marti"},
            {"uid": 13, "ini": "Š", "name": "Šárka",            "role": "personalistika", "col": "#6e4a3a", "cockpit": "/marti"},
            {"uid": 18, "ini": "P", "name": "Petra Šafránková", "role": "finance + HR",   "col": "#3a566e", "cockpit": "/marti"},
        ]
    if is_vp:
        # Týmová ikonka „E" = Vedoucí projektů / digitalizace (Marti + Kristý + Jirka + Eliška).
        # Marti 1.7.2026: „náš tým, který pomůže Elišce nakopnout digitalizaci u VP".
        team.append({"uid": 34, "ini": "E", "name": "Vedoucí projektů — digitalizace (Eliščin tým)",
                     "role": "VP tým", "col": "#3a6e5a", "cockpit": "/vp"})
    return JSONResponse({"ok": True, "uid": uid or 0, "allowed": bool(cockpit_allowed or is_vp),
                         "team": team, "fin": bool(fin), "sync": bool(is_sync),
                         "parent": is_parent_f, "vp": is_vp,
                         "member": bool(uid and not (fin or is_parent_f or is_vp))})


@api_router.get("/app/attendance/list")
async def att_list(req: Request) -> JSONResponse:
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    days = 14
    try:
        days = max(1, min(120, int(req.query_params.get("days", "14"))))
    except Exception:
        days = 14
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        # Marti 19.6.: lze zobrazit i docházku jiného člověka (👁 „Dnešek" v panelu skupin).
        # Stejná viditelnost jako /app/skupina/lidi ("zatím vidí všichni vše") — read-only seznam jobů.
        target = uid
        tu = req.query_params.get("user_id")
        if tu and int(tu) != uid:
            target = int(tu)
        emp = _att_employee(s, target)
        rows = s.execute(_t(
            "SELECT e.id, e.note, to_char(e.entry_date,'YYYY-MM-DD') d, et.label typ, e.hours, e.project_ref, "
            "e.status, e.is_active, to_char(e.started_at,'HH24:MI') zac, to_char(e.ended_at,'HH24:MI') kon, "
            "et.code, et.category cat "
            "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id=e.entry_type_id "
            "WHERE e.tenant_id=:t AND e.employee_id=:e2 AND e.entry_date >= current_date - :dd "
            "AND e.status IS DISTINCT FROM 'superseded' AND e.status IS DISTINCT FROM 'announced' "
            "AND et.code <> 'day_end' "  # day_end = interní 'konec dne do 23:59', nezobrazovat lidem jako job (Marti 19.6.)
            "ORDER BY e.entry_date DESC, e.id DESC LIMIT 200"),
            {"t": _ATT_TENANT, "e2": emp, "dd": days}).mappings().all()
        s.commit()
        return JSONResponse(jsonable_encoder({"ok": True, "entries": [dict(r) for r in rows]}))
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/attendance/daily")
async def att_daily(req: Request) -> JSONResponse:
    """Přehled po dnech: kolik odpracováno / nepřítomnost za každý den. Marti 6.6.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    days = 14
    try:
        days = max(1, min(120, int(req.query_params.get("days", "14"))))
    except Exception:
        days = 14
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        emp = _att_employee(s, uid)
        rows = s.execute(_t(
            "SELECT to_char(e.entry_date,'YYYY-MM-DD') d, "
            "COALESCE(round(sum(CASE WHEN et.category='presence' THEN e.hours ELSE 0 END)::numeric,2),0) worked, "
            "COALESCE(round(sum(CASE WHEN et.category<>'presence' THEN e.hours ELSE 0 END)::numeric,2),0) absence, "
            "bool_or(e.is_active) active "
            "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id=e.entry_type_id "
            "WHERE e.tenant_id=:t AND e.employee_id=:e2 AND e.entry_date >= current_date - :dd "
            "GROUP BY e.entry_date ORDER BY e.entry_date DESC"),
            {"t": _ATT_TENANT, "e2": emp, "dd": days}).mappings().all()
        s.commit()
        return JSONResponse(jsonable_encoder({"ok": True, "days": [dict(r) for r in rows]}))
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/app/attendance/real")
async def att_real(req: Request) -> JSONResponse:
    """Reálná docházka po dnech v rozsahu from..to: reálný čas příchodu (první
    presence start) + odpracované hodiny. Pro kartu 'Realita tento týden'. Marti 14.6."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    from sqlalchemy import text as _t
    d_from = req.query_params.get("from") or None
    d_to = req.query_params.get("to") or None
    cm, s = _att_session()
    try:
        emp = _att_employee(s, uid)
        sql = ("SELECT to_char(e.entry_date,'YYYY-MM-DD') d, "
               "to_char(min(CASE WHEN et.category='presence' THEN e.started_at END),'HH24:MI') zac, "
               "COALESCE(round(sum(CASE WHEN et.category='presence' THEN e.hours ELSE 0 END)::numeric,2),0) worked "
               "FROM tenant.att_entry e JOIN tenant.att_entry_type et ON et.id=e.entry_type_id "
               "WHERE e.tenant_id=:t AND e.employee_id=:e2 "
               "AND e.status IS DISTINCT FROM 'superseded' AND e.status IS DISTINCT FROM 'announced'")
        par = {"t": _ATT_TENANT, "e2": emp}
        if d_from:
            sql += " AND e.entry_date >= :df"; par["df"] = d_from
        if d_to:
            sql += " AND e.entry_date <= :dt"; par["dt"] = d_to
        sql += " GROUP BY e.entry_date ORDER BY e.entry_date"
        rows = s.execute(_t(sql), par).mappings().all()
        s.commit()
        return JSONResponse(jsonable_encoder({"ok": True, "days": [dict(r) for r in rows]}))
    finally:
        cm.__exit__(None, None, None)


def _sickday_lekar_apply(s, emp, code, days_hours, uid, note):
    """Čerpání sick day PŘEDNOSTNĚ (Marti 28.6.). days_hours=[(date,hours)].
    - sickday: hodiny čerpá z balance (cap na zbytek nároku).
    - medical (lékař): cap 4 h/návštěva; čerpá se PŘEDNOSTNĚ ze sickday (ta část → entry 'sickday'),
      zbytek zůstává 'medical'. Hned ten den sníží sick_day_balance.cerpano_h. Nárok default 16 h (HR opraví)."""
    from sqlalchemy import text as _t
    import datetime as _dt
    if not days_hours:
        return None
    rok = days_hours[0][0].year
    eng = s.execute(_t(
        "SELECT id FROM tenant.engagement WHERE employee_id=:e AND tenant_id=2 "
        "AND (smlouva_do IS NULL OR smlouva_do>=CURRENT_DATE) ORDER BY smlouva_od DESC NULLS LAST LIMIT 1"),
        {"e": emp}).scalar() or s.execute(_t(
        "SELECT id FROM tenant.engagement WHERE employee_id=:e AND tenant_id=2 ORDER BY id DESC LIMIT 1"),
        {"e": emp}).scalar()
    if not eng:
        return None
    bal = s.execute(_t("SELECT narok_h, cerpano_h FROM tenant.sick_day_balance "
                       "WHERE tenant_id=2 AND engagement_id=:g AND rok=:r"), {"g": eng, "r": rok}).first()
    if not bal:
        s.execute(_t("INSERT INTO tenant.sick_day_balance (tenant_id,engagement_id,rok,narok_h,cerpano_h) "
                     "VALUES (2,:g,:r,16,0)"), {"g": eng, "r": rok})
        narok, cerp = 16.0, 0.0
    else:
        narok, cerp = float(bal[0] or 0), float(bal[1] or 0)
    sd_tid = s.execute(_t("SELECT id FROM tenant.att_entry_type WHERE tenant_id=2 AND code='sickday'")).scalar()
    med_tid = s.execute(_t("SELECT id FROM tenant.att_entry_type WHERE tenant_id=2 AND code='medical'")).scalar()
    for (d, h) in days_hours:
        avail = max(0.0, narok - cerp)
        if code == "medical":
            hcap = min(float(h or 0), 4.0)
            draw = min(hcap, avail)
            rest = round(hcap - draw, 2)
            s.execute(_t("DELETE FROM tenant.att_entry WHERE tenant_id=2 AND employee_id=:e AND entry_date=:d "
                         "AND entry_type_id IN (:m,:s)"), {"e": emp, "d": d, "m": med_tid, "s": sd_tid})
            if draw > 0 and sd_tid:
                s.execute(_t("INSERT INTO tenant.att_entry (tenant_id,employee_id,entry_date,entry_type_id,hours,"
                             "status,source,note,is_active,created_by_id,created_at,updated_at) "
                             "VALUES (2,:e,:d,:t,:h,'pending','mobile_app',:n,false,:u,now(),now())"),
                          {"e": emp, "d": d, "t": sd_tid, "h": draw, "n": ((note or "") + " [lékař→sickday]")[:250], "u": uid})
                cerp += draw
            if rest > 0 and med_tid:
                s.execute(_t("INSERT INTO tenant.att_entry (tenant_id,employee_id,entry_date,entry_type_id,hours,"
                             "status,source,note,is_active,created_by_id,created_at,updated_at) "
                             "VALUES (2,:e,:d,:t,:h,'pending','mobile_app',:n,false,:u,now(),now())"),
                          {"e": emp, "d": d, "t": med_tid, "h": rest, "n": (note or "lékař")[:250], "u": uid})
        else:  # sickday přímo
            req = float(h or 0)
            draw = min(req, avail)
            if sd_tid:
                s.execute(_t("UPDATE tenant.att_entry SET hours=:h, note=:n, updated_at=now() "
                             "WHERE tenant_id=2 AND employee_id=:e AND entry_date=:d AND entry_type_id=:t"),
                          {"h": draw, "n": (note or "sickday")[:250], "e": emp, "d": d, "t": sd_tid})
            cerp += draw
    s.execute(_t("UPDATE tenant.sick_day_balance SET cerpano_h=:c WHERE tenant_id=2 AND engagement_id=:g AND rok=:r"),
              {"c": cerp, "g": eng, "r": rok})
    return {"narok_h": narok, "cerpano_h": cerp, "zbyva_h": max(0.0, narok - cerp)}


@api_router.post("/app/attendance/absence")
async def att_absence(req: Request) -> JSONResponse:
    """Nahlášení nepřítomnosti z appky (dovolená/nemoc/lékař/OČR/sickday/neplacené).
    Vytvoří att_entry na každý pracovní den v rozsahu (Po–Pá), status 'pending'.
    Idempotentní per (employee, den, typ). Marti 6.6.2026.
    sickday/medical: čerpá sick_day_balance přednostně (lékař max 4 h, sickday first) — Marti 28.6."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        body = {}
    code = (str(body.get("type_code") or "")).strip().lower()
    # Marti 7.6.: + homeoffice — hlášení HO dopředu (presence, hours NULL = plán,
    # reálné hodiny vzniknou až píchnutím; nepočítá se do absencí ani odpracovaného).
    if code not in ("vacation", "sick", "medical", "family_care", "sickday", "unpaid", "homeoffice", "osvc_absence"):
        return JSONResponse({"ok": False, "error": "invalid_type"}, status_code=400)
    from datetime import datetime as _dt, timedelta as _td
    try:
        d0 = _dt.strptime(str(body.get("date_from") or "")[:10], "%Y-%m-%d").date()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid_date_from"}, status_code=400)
    dt_to = str(body.get("date_to") or "")[:10]
    try:
        d1 = _dt.strptime(dt_to, "%Y-%m-%d").date() if dt_to else d0
    except Exception:
        d1 = d0
    if d1 < d0:
        d1 = d0
    if (d1 - d0).days > 120:
        return JSONResponse({"ok": False, "error": "range_too_long"}, status_code=400)
    note = (str(body.get("note") or "").strip()[:250]) or None
    from sqlalchemy import text as _t
    cm, s = _att_session()
    created = 0
    try:
        emp = _att_employee(s, uid)
        tr = s.execute(_t("SELECT id FROM tenant.att_entry_type WHERE tenant_id=:t AND code=:c"),
                       {"t": _ATT_TENANT, "c": code}).first()
        if not tr:
            return JSONResponse({"ok": False, "error": "type_not_seeded"}, status_code=400)
        tid = tr[0]
        mode = (str(body.get("mode") or "days")).strip().lower()  # 'days' | 'hours'

        def _upsert(ds, hrs):
            nonlocal created
            res = s.execute(_t(
                "UPDATE tenant.att_entry SET entry_type_id=:et, hours=:h, status='pending', "
                "source='mobile_app', note=:n, updated_at=now() "
                "WHERE tenant_id=:t AND employee_id=:e AND entry_date=:d AND entry_type_id=:et"),
                {"et": tid, "h": hrs, "n": note, "t": _ATT_TENANT, "e": emp, "d": ds})
            if (res.rowcount or 0) == 0:
                s.execute(_t(
                    "INSERT INTO tenant.att_entry (tenant_id,employee_id,entry_date,entry_type_id,hours,"
                    "status,source,note,is_active,created_by_id,created_at,updated_at) "
                    "VALUES (:t,:e,:d,:et,:h,'pending','mobile_app',:n,false,:u,now(),now())"),
                    {"t": _ATT_TENANT, "e": emp, "d": ds, "et": tid, "h": hrs, "n": note, "u": uid})
                created += 1

        if mode == "hours":
            try:
                hrs = round(float(body.get("hours") or 0), 2)
            except Exception:
                hrs = 0
            if hrs <= 0 or hrs > 24:
                return JSONResponse({"ok": False, "error": "invalid_hours"}, status_code=400)
            _upsert(d0.isoformat(), hrs)  # část dne na jeden den
        else:
            day = d0
            while day <= d1:
                if day.weekday() < 5:  # Po–Pá
                    _upsert(day.isoformat(), None if code == "homeoffice" else 8)
                day += _td(days=1)
        # sickday/lékař: čerpání sick day přednostně, hned ten den (Marti 28.6.)
        if code in ("medical", "sickday"):
            try:
                if mode == "hours":
                    dh = [(d0, hrs)]
                else:
                    dh = []
                    dd = d0
                    while dd <= d1:
                        if dd.weekday() < 5:
                            dh.append((dd, 8.0))
                        dd += _td(days=1)
                _sickday_lekar_apply(s, emp, code, dh, uid, note)
            except Exception:
                pass
        # dovolená → čerpání holiday_balance (recompute z docházky = idempotentní)
        if code == "vacation":
            try:
                rok = d0.year
                eng = s.execute(_t(
                    "SELECT id FROM tenant.engagement WHERE employee_id=:e AND tenant_id=2 "
                    "AND (smlouva_do IS NULL OR smlouva_do>=CURRENT_DATE) ORDER BY smlouva_od DESC NULLS LAST LIMIT 1"),
                    {"e": emp}).scalar()
                if eng:
                    used = s.execute(_t(
                        "SELECT COALESCE(SUM(en.hours),0) FROM tenant.att_entry en "
                        "JOIN tenant.att_entry_type t ON t.id=en.entry_type_id "
                        "WHERE en.tenant_id=2 AND en.employee_id=:e AND t.code='vacation' "
                        "AND EXTRACT(YEAR FROM en.entry_date)=:r"), {"e": emp, "r": rok}).scalar() or 0
                    ex = s.execute(_t("SELECT narok_h, prevod_h FROM tenant.holiday_balance "
                                      "WHERE tenant_id=2 AND engagement_id=:g AND rok=:r"),
                                   {"g": eng, "r": rok}).first()
                    if not ex:
                        s.execute(_t("INSERT INTO tenant.holiday_balance (tenant_id,engagement_id,rok,narok_h,prevod_h,cerpano_h,zbytek_h) "
                                     "VALUES (2,:g,:r,0,0,:u,:z)"), {"g": eng, "r": rok, "u": used, "z": -float(used)})
                    else:
                        nar = float(ex[0] or 0); prv = float(ex[1] or 0)
                        s.execute(_t("UPDATE tenant.holiday_balance SET cerpano_h=:u, zbytek_h=:z, changed_at=now() "
                                     "WHERE tenant_id=2 AND engagement_id=:g AND rok=:r"),
                                  {"u": used, "z": nar + prv - float(used), "g": eng, "r": rok})
            except Exception:
                pass
        s.commit()
        # Marti 7.6.: notifikace rodičům (schvalování z kapsy) — kdo, co, odkdy dokdy.
        try:
            from sqlalchemy import text as _tn
            who = s.execute(_tn(
                "SELECT COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')),''), u.login_name, em.full_name) "
                "FROM tenant.att_employee em LEFT JOIN public.users u ON u.id = em.user_id WHERE em.id = :e"),
                {"e": emp}).scalar() or ("zaměstnanec " + str(emp))
            tlabel = s.execute(_tn("SELECT label FROM tenant.att_entry_type WHERE id = :i"), {"i": tid}).scalar() or code
            _fmt = lambda x: str(x.day) + ". " + str(x.month) + "."  # Windows nemá %-d
            rng = _fmt(d0) if d0 == d1 else (_fmt(d0) + " – " + _fmt(d1))
            msg = who + ": " + tlabel + " " + rng + ((" — " + note) if note else "") + " (čeká na schválení)"
            # Org resolver (Fáze A): schvalovatel dle org struktury; rodiče = pevný anchor
            # (Marti-AI: hardcoded ID zmizí před prvním externím zákazníkem — fallback drží).
            targets = {1, 11}
            try:
                appr = s.execute(_tn("SELECT tenant.resolve_role(2, :e, 'absence_approver')"),
                                 {"e": emp}).scalar()
                if appr:
                    targets.add(int(appr))
            except Exception:
                pass
            for puid in sorted(targets):
                s.execute(_tn(
                    "INSERT INTO fw.mobile_command (app_key, target_user_id, command_type, title, message, created_by) "
                    "VALUES ('mobile', :uid, 'claude_msg', :ti, :msg, NULL)"),
                    {"uid": puid, "ti": "🌴 Nahlášená nepřítomnost", "msg": msg[:600]})
            s.commit()
        except Exception:
            s.rollback()  # notifikace nesmí shodit nahlášení
        return JSONResponse({"ok": True, "created": created})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


# ── Živá docházka EC → naše (hybrid Fáze 1, inkrementální) — Marti 9.6.2026 ──
_LAST_DOCH_SYNC = [0.0]


def _sync_vyroba_work_ec(days: int = 3, tenant: int = 2, frm: str = None,
                         to: str = None) -> dict:
    """Přídavný sync EC_Dochazka → tenant.vyroba_work = ODDĚLENÝ zakázkový systém
    (zakázka + činnost + čas jako joby). NESahá na att_entry (docházka/mzdy zůstávají
    beze změny). Nese DruhCinnosti (drátování/zkoušení/...), kterou att_entry mirror
    zahazuje → z tohohle Petra/MD2-VP i Dušan vidí reálný stav výroby po činnostech.
    Idempotentní přes source_system='centrala1'+source_id (EC ID). Claude ID23 4.7.2026."""
    import json as _json_d
    from datetime import date as _date_d, timedelta as _td_d
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return {"ok": False, "error": "mcp_unavailable"}

    def _rows(sql):
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _json_d.loads(raw) if isinstance(raw, str) else raw
        if isinstance(r, dict):
            if r.get("ok") is False:
                raise RuntimeError(str(r.get("error")))
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    return r[k]
        return r if isinstance(r, list) else []

    if not frm:
        frm = (_date_d.today() - _td_d(days=days)).isoformat()
    _wh = "DatumPripadu >= '" + frm + "'"
    if to:
        _to_excl = (_date_d.fromisoformat(to) + _td_d(days=1)).isoformat()
        _wh += " AND DatumPripadu < '" + _to_excl + "'"
    sql = ("SELECT ID, CisloZam, CONVERT(varchar(10),DatumPripadu,23) d, "
           "CONVERT(varchar(19),CasZacatek,120) z, CONVERT(varchar(19),CasKonec,120) k, "
           "CisloZakazky, DruhCinnosti, ISNULL(CasCelkemZakazka,0) hod "
           "FROM EC_Dochazka WHERE " + _wh + " "
           "AND ISNULL(CisloZakazky,'')<>'' AND LOWER(ISNULL(CisloZakazky,''))<>'rezie' "
           "AND ISNULL(DruhCinnosti,0)>0 ORDER BY ID")

    cm = _pg.get_session()
    sess = cm.__enter__()
    ins = upd = total = 0
    try:
        # dedup: (cislo_zam, den) s app work_alloc segmenty → EC přeskoč (app má pravdu o činnosti)
        try:
            _appd = {(str(x[0]).strip(), str(x[1])) for x in sess.execute(_t(
                "SELECT e.cislo_zam, to_char(wa.started_at::date,'YYYY-MM-DD') "
                "FROM tenant.work_alloc wa JOIN tenant.att_employee e ON e.user_id=wa.user_id AND e.tenant_id=:t "
                "WHERE wa.ended_at IS NOT NULL AND wa.cinnost_id IS NOT NULL AND e.cislo_zam IS NOT NULL"), {"t": tenant}).fetchall()}
        except Exception:
            _appd = set()
        for r in _rows(sql):
            rid = int(r["ID"]); total += 1
            cz = str(r.get("CisloZam") or "").strip()
            zak = (r.get("CisloZakazky") or "").strip()
            if (cz, str(r.get("d"))) in _appd:
                continue
            try:
                cin = int(r.get("DruhCinnosti") or 0) or None
            except Exception:
                cin = None
            p = {"t": tenant, "cz": cz or None, "zak": zak, "cin": cin,
                 "d": r.get("d"), "z": r.get("z"), "k": r.get("k"),
                 "h": r.get("hod"), "sid": rid}
            res = sess.execute(_t(
                "UPDATE tenant.vyroba_work SET zakazka_ref=:zak, "
                "cinnost_id=(SELECT id FROM tenant.vyroba_cinnost WHERE id=:cin LIMIT 1), "
                "datum=:d, od=:z, konec=:k, hodiny=:h, cislo_zam=:cz, "
                "user_id=(SELECT user_id FROM tenant.att_employee WHERE tenant_id=:t AND cislo_zam=:cz AND user_id IS NOT NULL LIMIT 1), "
                "updated_at=now() "
                "WHERE tenant_id=:t AND source_system='centrala1' AND source_id=:sid"), p)
            if (res.rowcount or 0) == 0:
                sess.execute(_t(
                    "INSERT INTO tenant.vyroba_work (tenant_id,user_id,cislo_zam,datum,od,konec,"
                    "zakazka_ref,cinnost_id,hodiny,source_system,source_id,created_at,updated_at) "
                    "VALUES (:t,(SELECT user_id FROM tenant.att_employee WHERE tenant_id=:t AND cislo_zam=:cz AND user_id IS NOT NULL LIMIT 1),"
                    ":cz,:d,:z,:k,:zak,(SELECT id FROM tenant.vyroba_cinnost WHERE id=:cin LIMIT 1),:h,'centrala1',:sid,now(),now())"), p)
                ins += 1
            else:
                upd += 1
        sess.commit()
        cm.__exit__(None, None, None)
        return {"ok": True, "total": total, "ins": ins, "upd": upd, "frm": frm, "to": to}
    except Exception as exc:
        try:
            cm.__exit__(type(exc), exc, exc.__traceback__)
        except Exception:
            pass
        return {"ok": False, "error": "%s: %s" % (type(exc).__name__, str(exc)[:200])}


def _sync_vyroba_work_app(days: int = 3, tenant: int = 2, frm: str = None,
                          to: str = None) -> dict:
    """Fold app segmentů tenant.work_alloc → tenant.vyroba_work (source_system='app').
    App-lidi (mobile) volí činnost per úsek → work_alloc má PRAVDU (EC u nich jen agregát
    DruhCinnosti=4 natvrdo). Dedup: pro (user, den) s app segmenty smaž centrala1 řádky
    (EC agregát), ať se nezapočítá dvakrát. Claude ID23 4.7.2026."""
    from datetime import date as _date_d, timedelta as _td_d
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    if not frm:
        frm = (_date_d.today() - _td_d(days=days)).isoformat()
    cm = _pg.get_session()
    sess = cm.__enter__()
    ins = upd = total = 0
    try:
        _wh = "wa.started_at::date >= :frm"
        p0 = {"t": tenant, "frm": frm}
        if to:
            _wh += " AND wa.started_at::date <= :toe"
            p0["toe"] = to
        segs = sess.execute(_t(
            "SELECT wa.id, wa.user_id, wa.project_ref, wa.cinnost_id, "
            "  wa.started_at::date AS d, wa.started_at AS z, wa.ended_at AS k, "
            "  round((EXTRACT(EPOCH FROM (wa.ended_at-wa.started_at))/3600.0)::numeric,3) AS hod, "
            "  (SELECT cislo_zam FROM tenant.att_employee e WHERE e.user_id=wa.user_id AND e.tenant_id=:t LIMIT 1) AS cz "
            "FROM tenant.work_alloc wa "
            "WHERE wa.tenant_id=:t AND wa.ended_at IS NOT NULL AND wa.cinnost_id IS NOT NULL "
            "  AND COALESCE(wa.project_ref,'')<>'' AND LOWER(COALESCE(wa.project_ref,''))<>'rezie' "
            "  AND " + _wh + " ORDER BY wa.id"), p0).fetchall()
        # poziční: 0=id 1=user_id 2=project_ref 3=cinnost_id 4=d 5=z 6=k 7=hod 8=cz
        seen_ud = set()
        for sg in segs:
            ud = (sg[1], sg[4])
            if ud not in seen_ud:
                seen_ud.add(ud)
                sess.execute(_t(
                    "DELETE FROM tenant.vyroba_work WHERE tenant_id=:t AND source_system='centrala1' "
                    "AND datum=:d AND user_id=:u"),
                    {"t": tenant, "d": sg[4], "u": sg[1]})
        for sg in segs:
            total += 1
            p = {"t": tenant, "u": sg[1], "cz": sg[8], "zak": sg[2],
                 "cin": sg[3], "d": sg[4], "z": sg[5], "k": sg[6],
                 "h": sg[7], "sid": int(sg[0])}
            res = sess.execute(_t(
                "UPDATE tenant.vyroba_work SET zakazka_ref=:zak, "
                "cinnost_id=(SELECT id FROM tenant.vyroba_cinnost WHERE id=:cin LIMIT 1), "
                "datum=:d, od=:z, konec=:k, hodiny=:h, "
                "cislo_zam=:cz, user_id=:u, updated_at=now() "
                "WHERE tenant_id=:t AND source_system='app' AND source_id=:sid"), p)
            if (res.rowcount or 0) == 0:
                sess.execute(_t(
                    "INSERT INTO tenant.vyroba_work (tenant_id,user_id,cislo_zam,datum,od,konec,"
                    "zakazka_ref,cinnost_id,hodiny,source_system,source_id,created_at,updated_at) "
                    "VALUES (:t,:u,:cz,:d,:z,:k,:zak,"
                    "(SELECT id FROM tenant.vyroba_cinnost WHERE id=:cin LIMIT 1),:h,'app',:sid,now(),now())"), p)
                ins += 1
            else:
                upd += 1
        sess.commit()
        cm.__exit__(None, None, None)
        return {"ok": True, "total": total, "ins": ins, "upd": upd, "frm": frm, "to": to}
    except Exception as exc:
        try:
            cm.__exit__(type(exc), exc, exc.__traceback__)
        except Exception:
            pass
        return {"ok": False, "error": "%s: %s" % (type(exc).__name__, str(exc)[:200])}


def _sync_ec_dochazka_recent(days: int = 3, tenant: int = 2, frm: str = None,
                             to: str = None, wipe: bool = False) -> dict:
    """Inkrementální upsert EC_Dochazka → tenant.att_entry (klíč
    source_system='centrala1'+source_id). Lehká verze migrace bez enrichmentu.
    EUROSOFT/Helios zůstává zdroj pravdy.

    frm/to: explicitní rozsah (YYYY-MM-DD); když frm chybí, použije se posledních
    `days` dní. wipe=True → před importem smaže centrala1 řádky v rozsahu (čistý
    re-import; naše vlastní píchnutí source_system!=centrala1 zůstanou). Marti 9.6.2026."""
    import json as _json_d
    from datetime import date as _date_d, timedelta as _td_d
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return {"ok": False, "error": "mcp_unavailable"}

    def _rows(sql):
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _json_d.loads(raw) if isinstance(raw, str) else raw
        if isinstance(r, dict):
            if r.get("ok") is False:
                raise RuntimeError(str(r.get("error")))
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    return r[k]
        return r if isinstance(r, list) else []

    cm = _pg.get_session()
    sess = cm.__enter__()
    ins = upd = total = 0
    try:
        tw = sess.execute(_t("SELECT id FROM tenant.att_entry_type WHERE tenant_id=:t AND code='work'"), {"t": tenant}).first()
        toh = sess.execute(_t("SELECT id FROM tenant.att_entry_type WHERE tenant_id=:t AND code='overhead'"), {"t": tenant}).first()
        if not (tw and toh):
            return {"ok": False, "error": "missing_types"}
        type_work, type_oh = tw[0], toh[0]
        # Marti 16.6.: lidé „jen STRATEGIE" (att_source_pref.app_only) — NEimportovat
        # jejich EC píchnutí (jinak duplicita app × Centrála). Best-effort.
        try:
            app_only_cisla = {str(x[0]).strip() for x in sess.execute(_t(
                "SELECT e.cislo_zam FROM tenant.att_employee e "
                "JOIN tenant.att_source_pref p ON p.user_id = e.user_id AND p.app_only = true "
                "WHERE e.tenant_id = :t AND e.cislo_zam IS NOT NULL"), {"t": tenant}).fetchall()}
        except Exception:
            app_only_cisla = set()
        emp_cache = {}

        def emp_id(cislo):
            key = str(cislo).strip()
            if key in emp_cache:
                return emp_cache[key]
            rr = sess.execute(_t("SELECT id FROM tenant.att_employee WHERE tenant_id=:t AND cislo_zam=:c"), {"t": tenant, "c": key}).first()
            if not rr:
                rr = sess.execute(_t("INSERT INTO tenant.att_employee (tenant_id,cislo_zam,is_active,created_at,updated_at) VALUES (:t,:c,true,now(),now()) RETURNING id"), {"t": tenant, "c": key}).first()
            emp_cache[key] = rr[0]
            return rr[0]
        if not frm:
            frm = (_date_d.today() - _td_d(days=days)).isoformat()
        if wipe:
            wp = {"t": tenant, "f": frm}
            wsql = ("DELETE FROM tenant.att_entry WHERE tenant_id=:t "
                    "AND source_system='centrala1' AND entry_date >= :f")
            if to:
                wsql += " AND entry_date <= :to"
                wp["to"] = to
            sess.execute(_t(wsql), wp)
        _wh = "DatumPripadu >= '" + frm + "'"
        if to:
            # POZOR: DatumPripadu u zivych/dnesnich radku NENI pulnoc (ma realny
            # cas, napr. 04:53). '<= to' (= pulnoc) by vyriznul cely den. Proto
            # exkluzivni dalsi den. Marti 9.6.2026.
            _to_excl = (_date_d.fromisoformat(to) + _td_d(days=1)).isoformat()
            _wh += " AND DatumPripadu < '" + _to_excl + "'"
        sql = ("SELECT ID, CisloZam, CONVERT(varchar(10),DatumPripadu,23) d, "
               "CONVERT(varchar(19),CasZacatek,120) z, CONVERT(varchar(19),CasKonec,120) k, "
               "CasPauza, CasCelkemZakazka hod, CisloZakazky, LoginFrom, "
               "CAST(ISNULL(PraceAktivni,0) AS int) akt, "
               "CAST(VedSchvaleno AS int) ved, CAST(SefSchvaleno AS int) sef, CAST(Uzavreno AS int) uz "
               # Jirka 27.6.2026: NEimportuj zpět naše vlastní zrcadlené řádky (Autor='STRATEGIE') —
               # jinak mirror(STRATEGIE→EC, DELETE+INSERT=nová EC.ID) × import(EC→STRATEGIE) tvořily
               # zpětnou smyčku → 1 nová centrala1 duplicita/den (Iva Hrůzová 24.6: 3×). Originál
               # máme jako app záznam (source_system NULL), takže nic neztrácíme.
               "FROM EC_Dochazka WHERE " + _wh + " AND ISNULL(Autor,'')<>'STRATEGIE' ORDER BY ID")
        # Marti 27.6.: „běžící" (is_active) smí být JEN dnešní den. Centrála drží u starých
        # režijních/zapomenutých záznamů PraceAktivni=1 → import je dřív kopíroval jako otevřenou
        # směnu z minulých dnů → bogus „zapomenutý odchod" notifikace. Past day = vždy uzavřeno.
        _today_iso = _date_d.today().isoformat()
        for r in _rows(sql):
            rid = int(r["ID"])
            total += 1
            if str(r.get("CisloZam") or "").strip() in app_only_cisla:
                continue  # „jen STRATEGIE" — EC píchnutí neimportujeme
            zak = (r.get("CisloZakazky") or "").strip()
            rezie = zak.lower() == "rezie"
            lf = (r.get("LoginFrom") or "").strip().upper()
            src = {"D": "tablet", "C": "manual", "A": "mobile_app"}.get(lf, "import")
            st = "locked" if int(r.get("uz") or 0) else ("approved" if (int(r.get("ved") or 0) and int(r.get("sef") or 0)) else "pending")
            p = {"t": tenant, "emp": emp_id(r["CisloZam"]), "d": r.get("d"),
                 "et": type_oh if rezie else type_work, "h": r.get("hod"),
                 "z": r.get("z"), "k": r.get("k"), "br": int(r.get("CasPauza") or 0),
                 "proj": ("Režie" if rezie else (zak or None)), "st": st, "src": src, "sid": rid,
                 "akt": (int(r.get("akt") or 0) == 1 and str(r.get("d") or "") == _today_iso)}
            res = sess.execute(_t(
                "UPDATE tenant.att_entry SET employee_id=:emp,entry_date=:d,entry_type_id=:et,hours=:h,"
                "started_at=:z,ended_at=:k,break_minutes=:br,project_ref=:proj,status=:st,source=:src,"
                "is_active=:akt,updated_at=now() "
                "WHERE tenant_id=:t AND source_system='centrala1' AND source_id=:sid"), p)
            if (res.rowcount or 0) == 0:
                sess.execute(_t(
                    "INSERT INTO tenant.att_entry (tenant_id,employee_id,entry_date,entry_type_id,hours,"
                    "started_at,ended_at,break_minutes,project_ref,status,source,source_system,source_id,"
                    "is_active,created_at,updated_at) VALUES (:t,:emp,:d,:et,:h,:z,:k,:br,:proj,:st,:src,"
                    "'centrala1',:sid,:akt,now(),now())"), p)
                ins += 1
            else:
                upd += 1
        # Marti 19.6.: appka = zdroj pravdy (hybrid). Kdo má dnes ŽIVOU směnu z appky,
        # tomu importovanou OTEVŘENOU směnu z Centrály schovej (superseded) — ať nejsou
        # dva joby od 5:18. A jeho běžící směnu zavři i v EC_Dochazka, ať se nereimportuje.
        app_active = sess.execute(_t(
            "SELECT em.cislo_zam, to_char(min(a.started_at),'YYYY-MM-DD HH24:MI:SS') AS app_start "
            "FROM tenant.att_entry a "
            "JOIN tenant.att_employee em ON em.id=a.employee_id "
            "WHERE a.tenant_id=:t AND a.entry_date=current_date AND a.is_active=true "
            "AND COALESCE(a.source_system,'')<>'centrala1' AND em.cislo_zam IS NOT NULL "
            "GROUP BY em.cislo_zam"),
            {"t": tenant}).fetchall()
        sess.execute(_t(
            "UPDATE tenant.att_entry ec SET is_active=false, status='superseded', updated_at=now() "
            "WHERE ec.tenant_id=:t AND ec.source_system='centrala1' AND ec.entry_date=current_date "
            "AND ec.is_active=true AND EXISTS (SELECT 1 FROM tenant.att_entry app "
            "  WHERE app.tenant_id=:t AND app.employee_id=ec.employee_id AND app.entry_date=current_date "
            "  AND app.is_active=true AND COALESCE(app.source_system,'')<>'centrala1')"),
            {"t": tenant})
        sess.commit()
        ec_closed = 0
        for _row in app_active:
            try:
                _n, _ = _ec_close_open_shift(_row[0], end_ts=_row[1], via="sync")
                ec_closed += int(_n or 0)
            except Exception:
                pass
        return {"ok": True, "total": total, "inserted": ins, "updated": upd, "ec_closed": ec_closed}
    except Exception as exc:
        try:
            sess.rollback()
        except Exception:
            pass
        return {"ok": False, "error": str(exc)}
    finally:
        try:
            cm.__exit__(None, None, None)
        except Exception:
            pass


