_MIRROR_SCHED_STOP = [False]
_MIRROR_SCHED_TASK = [None]


_MIRROR_EC_AUTOR = "STRATEGIE"  # tag našich zrcadlených EC_Dochazka řádků (idempotence + reverzibilita)


def _mirror_att_to_ec(_unused=None, datum_od="2026-06-01", test_one=False, dry=False):
    """Přechodové ZRCADLO docházky STRATEGIE → EUROSOFT Helios (Marti 23.6.2026).
    Lidé, co píchají JEN ve STRATEGII (source_system IS NULL) a mají numerické EC číslo,
    se propíšou do EC_Dochazka (záznam/den) + EC_Dochazka_SumaDen (souhrn/den), aby byli
    vidět i ve starém systému. Idempotentní (přeskočí den, který už v EC existuje),
    reverzibilní (EC_Dochazka.Autor='STRATEGIE'; SumaDen dle fw.att_ec_mirror_log), auditované.
    test_one=zapiš max 1 den (validace write-kanálu); dry=jen spočítej, nezapisuj."""
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    import json as _j, datetime as _dt
    s = _g()
    try:
        rows = s.execute(_t(
            "SELECT ae.cislo_zam cz, e.entry_date dt, "
            " to_char(MIN(e.started_at) AT TIME ZONE 'Europe/Prague','YYYY-MM-DD HH24:MI:SS') zac, "
            " to_char(MAX(e.ended_at) AT TIME ZONE 'Europe/Prague','YYYY-MM-DD HH24:MI:SS') kon, "
            " ROUND(SUM(COALESCE(e.hours,0))::numeric,2) hod, MAX(e.project_ref) zak, "
            " COALESCE((SELECT wr.relation FROM tenant.work_relation wr WHERE wr.user_id=ae.user_id LIMIT 1),'zamestnanec') vztah "
            "FROM tenant.att_entry e JOIN tenant.att_employee ae ON ae.id=e.employee_id "
            "WHERE e.tenant_id=2 AND e.source_system IS NULL AND e.entry_date < CURRENT_DATE "
            " AND e.entry_date >= :od AND ae.cislo_zam ~ '^[0-9]+$' AND COALESCE(e.hours,0) > 0 "
            "GROUP BY ae.cislo_zam, e.entry_date, ae.user_id ORDER BY e.entry_date DESC, ae.cislo_zam"),
            {"od": datum_od}).mappings().all()
    finally:
        s.close()
    if not rows:
        return {"ok": True, "lidi": 0, "doch": 0, "suma": 0}
    cisla = sorted({int(r["cz"]) for r in rows})
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return {"ok": False, "error": "mcp_unavailable"}

    def _ec(sql):
        rj = mcp.call_tool_sync("eurosoft_strategie_query_raw", {"sql": sql, "db_name": "DB_EC"},
                                conversation_id=None)
        return (_j.loads(rj) if isinstance(rj, str) else rj) or {}

    def _ecw(sql):
        r = _ec(sql)
        if not r.get("ok"):
            raise RuntimeError("EC write blokován: " + str(r.get("message") or r.get("error"))[:240])
        return r

    inlist = ",".join(str(c) for c in cisla)

    def _have(table):
        r = _ec("SELECT DISTINCT CisloZam, CONVERT(varchar(10),DatumPripadu,23) d FROM %s "
                "WHERE CisloZam IN (%s) AND DatumPripadu >= '%s'" % (table, inlist, datum_od))
        out, cols = set(), (r.get("columns") or [])
        for x in (r.get("rows") or []):
            d = dict(zip(cols, x)) if isinstance(x, list) else x
            try:
                out.add((int(d["CisloZam"]), str(d["d"])[:10]))
            except Exception:
                pass
        return out

    have_d = _have("EC_Dochazka")

    # EC denní souhrn s HODINAMI — klíč pro novou idempotenci (Marti 24.6.2026):
    # den je v EC "kompletní", když souhrn >= náš počet hodin. Pak respektuj.
    # Jinak (chybí nebo jen útržek z tabletu) nahradíme naším plným dnem.
    def _have_sum_h():
        r = _ec("SELECT CisloZam, CONVERT(varchar(10),DatumPripadu,23) d, CasCelkem h "
                "FROM EC_Dochazka_SumaDen WHERE CisloZam IN (%s) AND DatumPripadu >= '%s'"
                % (inlist, datum_od))
        out, cols = {}, (r.get("columns") or [])
        for x in (r.get("rows") or []):
            dd = dict(zip(cols, x)) if isinstance(x, list) else x
            try:
                out[(int(dd["CisloZam"]), str(dd["d"])[:10])] = float(dd["h"] or 0)
            except Exception:
                pass
        return out
    have_s_h = _have_sum_h()
    dow = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"]
    nd = ns = did = 0
    for r in rows:
        if test_one and did >= 1:
            break
        cz = int(r["cz"]); dt = str(r["dt"])[:10]; hod = float(r["hod"] or 0)
        zac = r["zac"] or (dt + " 08:00:00"); kon = r["kon"]
        zak = (r["zak"] or "").replace("'", "").strip() or "Rezie"
        je_zak = zak.upper().startswith(("VR", "SW", "PR"))
        dc = 1 if je_zak else 6
        do = _dt.date.fromisoformat(dt); dvt = dow[do.weekday()]
        v = (r["vztah"] or "").lower()
        hpp, dpp, osvc = (0, 0, 1) if v == "osvc" else (0, 1, 0) if v == "dohoda" else (1, 0, 0)
        konv = ("'%s'" % kon) if kon else "NULL"
        # Nová idempotence (Marti 24.6.2026): den je v EC "hotový", když souhrn
        # >= náš počet hodin (tolerance 0.25 h) → respektuj a přeskoč. Jinak
        # (chybí úplně NEBO je tam jen útržek z tabletu s méně hodinami) →
        # nahraď naším plným dnem: smaž útržek/naše (cizí ruční Autor zůstane!),
        # pak zapiš plný záznam + souhrn.
        ec_h = have_s_h.get((cz, dt))
        if ec_h is not None and ec_h >= (hod - 0.25):
            continue
        cmont = hod if je_zak else 0
        crez = 0 if je_zak else hod
        if not dry:
            _ecw("DELETE FROM EC_Dochazka WHERE CisloZam=%d AND DatumPripadu='%s' "
                 "AND (Autor='%s' OR Autor='DochazkaTablet' OR Autor IS NULL)"
                 % (cz, dt, _MIRROR_EC_AUTOR))
            _ecw("DELETE FROM EC_Dochazka_SumaDen WHERE CisloZam=%d AND DatumPripadu='%s'"
                 % (cz, dt))
            _ecw("INSERT INTO EC_Dochazka (CisloZam,DatumPripadu,DruhCinnosti,"
                "CisloZakazky,CasZacatek,CasKonec,Status,Import,Autor,DatPorizeni) VALUES "
                "(%d,'%s',%d,'%s','%s',%s,0,1,'%s',GETDATE())"
                % (cz, dt, dc, zak[:15], zac, konv, _MIRROR_EC_AUTOR))
            _ecw("INSERT INTO EC_Dochazka_SumaDen (CisloZam,DatumPripadu,CasCelkem,CasMontaz,CasRezie,"
                "CasZacatek,CasKonec,Uzavreno,HPP,DPP,OSVC) VALUES "
                "(%d,'%s',%.2f,%.2f,%.2f,'%s',%s,0,%d,%d,%d)"
                % (cz, dt, hod, cmont, crez, zac, konv, hpp, dpp, osvc))
        nd += 1
        ns += 1
        if not dry:
            s2 = _g()
            try:
                s2.execute(_t("INSERT INTO fw.att_ec_mirror_log (cislo_zam,datum,hodiny,doch_zapsano,suma_zapsano) "
                              "VALUES (:c,:d,:h,:dd,:ss)"),
                           {"c": cz, "d": dt, "h": hod, "dd": True, "ss": True})
                s2.commit()
            finally:
                s2.close()
        did += 1
    return {"ok": True, "lidi": len(cisla), "doch": nd, "suma": ns,
            "dry": bool(dry), "test_one": bool(test_one)}


def _mirror_ec_probe(_unused=None):
    """Diagnostika write-kanálu do DB_EC: zkusí 1 INSERT do EC_Dochazka_SumaDen
    (cislo 999999, fiktivní) + čtení zpět + úklid. Vrací surové MCP odpovědi."""
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    import json as _j
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return {"ok": False, "error": "mcp_unavailable"}

    def _ec(sql):
        rj = mcp.call_tool_sync("eurosoft_strategie_query_raw", {"sql": sql, "db_name": "DB_EC"},
                                conversation_id=None)
        return rj

    ins = _ec("INSERT INTO EC_Dochazka_SumaDen (CisloZam,DatumPripadu,DatumPripadu_Y,DatumPripadu_M,"
              "DatumPripadu_D,CasCelkem,Uzavreno) VALUES (999999,'2099-01-01',2099,1,1,1.0,0)")
    rd = _ec("SELECT COUNT(*) c FROM EC_Dochazka_SumaDen WHERE CisloZam=999999")
    cl = _ec("DELETE FROM EC_Dochazka_SumaDen WHERE CisloZam=999999")
    return {"ok": True, "_msg": ("INS=%s | RD=%s | DEL=%s" % (str(ins)[:400], str(rd)[:150], str(cl)[:150]))}


def _mirror_run_job(job_key):
    """Spustí jeden sync dle klíče. Vrací (ok, done, rows, msg)."""
    fnmap = {
        "mirror_att_to_ec": lambda: _mirror_att_to_ec(),
        "mirror_ec_probe": lambda: _mirror_ec_probe(),
        "mirror_att_to_ec_test": lambda: _mirror_att_to_ec(test_one=True),
        "mirror_att_to_ec_dry": lambda: _mirror_att_to_ec(dry=True),
        "sync_ec_dochazka_sumaden": lambda: _sync_dochazka_sumaden(),
        "sync_sumaden_2026_05": lambda: _sync_dochazka_sumaden(2026, 5),
        "sync_ec_doklady": lambda: _sync_ec_doklady_zbozi(cap_per_table=300000),
        "sync_ec_kalkulace": lambda: _sync_ec_kalkulace(),
        "sync_ec_ukoly": lambda: _sync_ec_ukoly(),
        "sync_ec_zakazky": lambda: _sync_ec_zakazka_prehled(),
        "sync_ec_sklad_kmen": lambda: _sync_ec_sklad_kmen(),
        "sync_ec_ceniky": lambda: _sync_ec_ceniky(),
        "sync_ec_org_kontakt": lambda: _sync_ec_org_kontakt(),
        "sync_ec_banka": lambda: _sync_ec_banka(),
        "sync_ec_banka_delta": lambda: _sync_ec_banka(delta_days=90),
        "saldo_praha_ec": lambda: _sync_saldo_praha(_firma_cloud_db(1), "tenant.ec_saldo_fa"),
        "saldo_praha_es": lambda: _sync_saldo_praha(_firma_cloud_db(2), "tenant.es_saldo_fa"),
        "sync_ec_saldo": lambda: _sync_ec_saldo(vs_bank_tbl='TabBankVypisR', vnitro_org=1),
        "sync_es_saldo": lambda: _sync_ec_saldo(src_tbl='[DB_IS].dbo.TabSaldoFA', tgt_tbl='tenant.es_saldo_fa',
                                                vs_bank_tbl='[DB_IS].dbo.TabBankVypisR', vnitro_org=1),
        "sync_ec_denik": lambda: _sync_ec_denik(rok=2025),
        "sync_ec_denik_2026": lambda: _sync_ec_denik(rok=2026),
        "sync_es_denik": lambda: _sync_es_denik(rok=2025),
        "sync_es_denik_2026": lambda: _sync_es_denik(rok=2026),
        "sync_ec_bank_ucet": lambda: _sync_ec_bank_ucet(),
        "sync_edi_definice": lambda: _sync_edi_definice(),
        # přesunuto z ⚙ Ops akcí do řídícího centra (Marti 20.6.2026)
        "sync_zakazky": lambda: _sync_zakazky_from_helios(),
        "sync_org": lambda: _sync_org_from_ec(),
        "sync_ec_org": lambda: (_sync_ec_org_from_centrala(), _sync_ec_kontakty_from_centrala())[1],
        "sync_fin": lambda: _sync_fin_from_ec(),
        "sync_priplatky": lambda: _sync_priplatky_from_ec(),
        "sync_pasky": lambda: (_sync_pasky_from_helios(), _refresh_employee_active())[1],
        "refresh_active_status": lambda: _refresh_employee_active(),
        "sync_plan_nepritomnost": lambda: _sync_plan_nepritomnost(),
        "sync_plan_dochazka": lambda: _sync_plan_to_dochazka(),
        "sync_vyroba_plan": lambda: _sync_vyroba_plan_from_ec(),
        "sync_vytizeni_absence": lambda: _sync_absence_to_ec_vytizeni(30),
        "sync_eneschopenka": lambda: _eneschopenka_to_sick(),
        "sync_odvozy": lambda: _sync_odvozy_from_ec(),
        "sync_nabor": lambda: _sync_nabor_from_ec(),
        # OZ mirror — obnova všech zrcadel Oběhu zboží (tenant.oz_*) z Centrály (Marti 2.7.2026)
        "oz_sync_all": lambda: __import__("modules.erp.api.oz_mirror",
                                          fromlist=["sync_all"]).sync_all(tenant_id=2),
        # Mail zrcadlo — inkrementální sync schránky (Claude-23 3.7.2026). Bere posl. 100/složka.
        "sync_mail_eliska": lambda: __import__("modules.erp.api.mail_mirror",
                                               fromlist=["sync_user_job"]).sync_user_job(34, limit=100),
        # Claude-27 7.7.2026: průběžný sync p.zeman (30, CRM) + projects (111, VP).
        "sync_mail_pzeman": lambda: __import__("modules.erp.api.mail_mirror",
                                               fromlist=["sync_user_job"]).sync_user_job(30, limit=100),
        "sync_mail_projects": lambda: __import__("modules.erp.api.mail_mirror",
                                                 fromlist=["sync_user_job"]).sync_user_job(111, limit=100),
    }
    # Účto zrcadla (office Helios → cloud Helios) jako scheduled joby: "zrc_<FIRMA>_<Table>".
    # Marti 5.7.2026 — automatizace dřív ručních zrcadel + viditelný poslední běh.
    if job_key.startswith("zrc_"):
        _zp = job_key.split("_", 2)
        if len(_zp) == 3:
            return _ucto_zrcadlo_run_one(_zp[1], _zp[2])
        return (False, True, None, "špatný zrc job_key: %s" % job_key)
    fn = fnmap.get(job_key)
    if fn is None:
        return (False, True, None, "neznámý job")
    try:
        out = fn() or {}
        ok = bool(out.get("ok", True))
        done = bool(out.get("done", True))
        nums = {k: v for k, v in out.items()
                if isinstance(v, (int, float)) and not isinstance(v, bool)}
        rows = int(sum(nums.values())) if nums else None
        msg = out.get("_msg") or (", ".join("%s=%s" % (k, v) for k, v in nums.items())) or "ok"
        return (ok, done, rows, str(msg)[:600])
    except Exception as e:
        return (False, True, None, ("%s: %s" % (type(e).__name__, str(e)))[:400])


def _mirror_sched_tick():
    """Jeden tik: claim 1 dozrálý job → spusť → přeplánuj (done=interval, jinak 2 min)."""
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    jk = None
    interval = 360
    try:
        # Watchdog: uvolni joby zaseklé v running (worker se recykloval mid-run, running zůstalo true).
        # Bez tohoto je plánovač (WHERE NOT running) už nikdy nevezme → "evidentně neběží".
        # Watermark + idempotentní upsert → po uvolnění plynule naváže.
        s.execute(_t(
            "UPDATE fw.mirror_job SET running=false, last_done=false, "
            "last_status='přerušeno (recyklace workeru) — naváže', next_run_at=now(), updated_at=now() "
            "WHERE running AND started_at IS NOT NULL AND started_at < now() - interval '20 minutes'"))
        s.commit()
        row = s.execute(_t(
            "UPDATE fw.mirror_job SET running=true, started_at=now(), last_status='běží', updated_at=now() "
            "WHERE job_key = (SELECT job_key FROM fw.mirror_job "
            "  WHERE enabled AND NOT running AND (next_run_at IS NULL OR next_run_at <= now()) "
            "  ORDER BY next_run_at NULLS FIRST FOR UPDATE SKIP LOCKED LIMIT 1) "
            "RETURNING job_key, interval_min")).first()
        s.commit()
        if not row:
            return
        jk, interval = row[0], int(row[1] or 360)
    finally:
        s.close()
    ok, done, rows, msg = _mirror_run_job(jk)
    nextmin = interval if done else 2
    s2 = _g()
    try:
        s2.execute(_t(
            "UPDATE fw.mirror_job SET running=false, last_run_at=now(), last_status=:st, "
            "last_result=:r, last_rows=:rw, last_done=:d, "
            "next_run_at=now() + :nm * interval '1 minute', updated_at=now() WHERE job_key=:k"),
            {"st": ("ok" if ok else "chyba"), "r": msg, "rw": rows, "d": done,
             "nm": nextmin, "k": jk})
        s2.commit()
    finally:
        s2.close()


# ── Blue-green hlídač: B nedohnal A → push Martimu (Marti 6.7.2026, „produkce začíná") ──
# Grace 8 min od startu procesu (start ≈ deploy, protože deploy restartuje API A).
# Notify max 1× per session; reset, jakmile B==A. Bez perzistentní tabulky (proces-lokální stav).
_SECLAG = {"notified": False, "start": None}


def _api_commit(port):
    import requests as _rq
    try:
        j = _rq.get("http://127.0.0.1:%s/api/v1/api-info" % port, timeout=3).json()
        return (str(j.get("commit") or "") or None)
    except Exception:
        return None


def _maybe_notify_seclag():
    import os as _os, time as _tt
    if _SECLAG["start"] is None:
        _SECLAG["start"] = _tt.time()
    a = _api_commit(_os.environ.get("STRATEGIE_PRIMARY_PORT") or "8002")
    b = _api_commit(_os.environ.get("STRATEGIE_SECONDARY_PORT") or "8003")
    if not a or not b:
        return
    if a[:12] == b[:12]:
        _SECLAG["notified"] = False
        return
    if _SECLAG["notified"] or (_tt.time() - _SECLAG["start"]) < 480:
        return
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t2
    ds = _g()
    try:
        title = "⚠️ Záloha API B nedohnala A"
        msg = ("B běží starý kód (%s ≠ A %s) už přes 8 min. Srovnej přes "
               "⚙ Ops → \U0001f4e6 Zkopírovat aktuální verzi do zálohy (API B) — jinak "
               "může při zátěži servírovat starou verzi (blikání, chybějící joby)."
               % (b[:8], a[:8]))
        ds.execute(_t2("INSERT INTO fw.mobile_command (app_key,target_user_id,command_type,title,message,created_by) "
                       "VALUES ('mobile',:u,'claude_msg',:t,:m,NULL)"),
                   {"u": int(_DEFAULT_APPROVER_UID), "t": title[:120], "m": msg[:600]})
        ds.commit()
        _SECLAG["notified"] = True
        logger.info("[seclag] B=%s != A=%s -> notify uid %s", b[:8], a[:8], _DEFAULT_APPROVER_UID)
    finally:
        ds.close()


async def _mirror_sched_loop():
    import asyncio as _aio
    _sl_tick = 0
    while not _MIRROR_SCHED_STOP[0]:
        try:
            await _aio.sleep(30)
            loop = _aio.get_event_loop()
            await loop.run_in_executor(None, _mirror_sched_tick)
            _sl_tick += 1
            if _sl_tick % 10 == 0:  # ~každých 5 min: hlídač blue-green lagu
                await loop.run_in_executor(None, _maybe_notify_seclag)
        except _aio.CancelledError:
            break
        except Exception as e:
            logger.warning("[mirror_sched_loop] %s", e)


def _mirror_sched_start():
    import asyncio as _aio
    if _MIRROR_SCHED_TASK[0] is not None and not _MIRROR_SCHED_TASK[0].done():
        return
    _MIRROR_SCHED_STOP[0] = False
    try:
        _MIRROR_SCHED_TASK[0] = _aio.create_task(_mirror_sched_loop())
        logger.info("[mirror_sched] background loop started (30s tik)")
    except Exception as e:
        logger.warning("[mirror_sched] start failed: %s", e)


def _mirror_sched_stop_now():
    _MIRROR_SCHED_STOP[0] = True
    if _MIRROR_SCHED_TASK[0] is not None and not _MIRROR_SCHED_TASK[0].done():
        _MIRROR_SCHED_TASK[0].cancel()


@api_router.get("/app/mirror/status")
def mirror_status(req: Request):
    uid = _uid_from_token_or_cookie(req)
    if not uid or not is_marti_parent(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        rows = s.execute(_t(
            "SELECT job_key, label, grp, interval_min, enabled, running, last_status, "
            "COALESCE(last_result,''), last_rows, last_done, "
            "to_char(last_run_at,'DD.MM. HH24:MI:SS'), "
            "to_char(next_run_at,'DD.MM. HH24:MI:SS'), "
            "CASE WHEN last_run_at IS NULL THEN NULL ELSE "
            "  round(EXTRACT(EPOCH FROM (now()-last_run_at))/60.0)::int END AS age_min, "
            "CASE WHEN running AND started_at IS NOT NULL THEN "
            "  round(EXTRACT(EPOCH FROM (now()-started_at))/60.0)::int END AS run_min, "
            "COALESCE(mode,'?') AS mode "
            "FROM fw.mirror_job ORDER BY enabled DESC, grp, label")).fetchall()
        out = [{"job_key": r[0], "label": r[1], "grp": r[2], "interval_min": r[3],
                "enabled": r[4], "running": r[5], "last_status": r[6], "last_result": r[7],
                "last_rows": r[8], "last_done": r[9], "last_run": r[10], "next_run": r[11],
                "age_min": r[12], "run_min": r[13], "mode": r[14]} for r in rows]
        # OZ zrcadla (oz_mirror_def) s módem DEL/RO/RW — přehled per tabulka (Marti 6.7.2026)
        ozr = s.execute(_t(
            "SELECT oz_table, COALESCE(mode,'DEL'), COALESCE(fw_code,'(raw)'), last_rows, "
            "to_char(last_sync_at,'DD.MM. HH24:MI:SS') FROM tenant.oz_mirror_def ORDER BY mode DESC, oz_table")).fetchall()
        oz = [{"oz_table": r[0], "mode": r[1], "fw_code": r[2], "last_rows": r[3], "last_sync": r[4]} for r in ozr]
        return {"ok": True, "jobs": out, "oz_mirrory": oz}
    finally:
        s.close()


@api_router.post("/app/mirror/run")
async def mirror_run(req: Request):
    uid = _uid_from_token_or_cookie(req)
    if not uid or not is_marti_parent(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        b = await req.json()
    except Exception:
        b = {}
    jk = (str(b.get("job_key") or "").strip())
    if not jk:
        return JSONResponse({"ok": False, "error": "chybí job_key"}, status_code=400)
    # inline: spusť ihned v tomto procesu (obejde plánovač na stale blue-green sekundáru)
    if b.get("inline"):
        try:
            ok, done, rows, msg = _mirror_run_job(jk)
            from core.database_data import get_data_session as _g2
            from sqlalchemy import text as _t2
            s2 = _g2()
            try:
                s2.execute(_t2("UPDATE fw.mirror_job SET last_run_at=now(), last_status=:st, "
                               "last_result=:r, last_rows=:n, last_done=:d, updated_at=now() WHERE job_key=:k"),
                           {"st": ("ok" if ok else "chyba"), "r": str(msg)[:400], "n": (rows or 0),
                            "d": bool(done), "k": jk})
                s2.commit()
            finally:
                s2.close()
            return {"ok": ok, "done": done, "rows": rows, "msg": msg}
        except Exception as e:
            return JSONResponse({"ok": False, "error": str(e)[:300]}, status_code=500)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        # force due — plánovač ho vezme do 30 s (pokud zrovna neběží)
        s.execute(_t("UPDATE fw.mirror_job SET next_run_at=now(), updated_at=now() "
                     "WHERE job_key=:k AND NOT running"), {"k": jk})
        s.commit()
    finally:
        s.close()
    return {"ok": True}


@api_router.post("/app/mirror/auto")
async def mirror_auto(req: Request):
    uid = _uid_from_token_or_cookie(req)
    if not uid or not is_marti_parent(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        b = await req.json()
    except Exception:
        b = {}
    jk = (str(b.get("job_key") or "").strip())
    if not jk:
        return JSONResponse({"ok": False, "error": "chybí job_key"}, status_code=400)
    sets = []
    params = {"k": jk}
    if "enabled" in b:
        sets.append("enabled=:en"); params["en"] = bool(b.get("enabled"))
    if b.get("interval_min"):
        try:
            params["iv"] = max(1, int(b.get("interval_min"))); sets.append("interval_min=:iv")
        except Exception:
            pass
    if not sets:
        return JSONResponse({"ok": False, "error": "nic ke změně"}, status_code=400)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        s.execute(_t("UPDATE fw.mirror_job SET " + ", ".join(sets) +
                     ", updated_at=now() WHERE job_key=:k"), params)
        s.commit()
    finally:
        s.close()
    return {"ok": True}


@api_router.post("/hr/migrate-dochazka")
async def hr_migrate_dochazka(req: Request) -> JSONResponse:
    """Migrace EC_Dochazka (MSSQL přes EUROSOFT MCP) → tenant.att_*. Běží IN-PROCESS
    (MCP na EUROSOFT je dostupné jen uvnitř API procesu). Idempotentní dle source_id
    (opakovatelné — doimport měsíce). Auth: X-Deploy-Token. Marti 6.6.2026.
    Body: {from:'2026-01-01', to?:'2026-07-01', tenant_id:2, page:2000}."""
    import os as _os_m, json as _json_m
    token = req.headers.get("X-Deploy-Token")
    env = _os_m.environ.get("STRATEGIE_DEPLOY_TOKEN")
    if token and env and token == env:
        pass  # token (bridge / curl)
    else:
        _require_parent(_get_uid(req))  # nebo přihlášený rodič (tlačítko v UI)
    try:
        body = await req.json()
    except Exception:
        body = {}
    tenant = int(body.get("tenant_id") or 2)
    from_date = str(body.get("from") or "2026-01-01")
    to_date = str(body.get("to") or "")
    page = int(body.get("page") or 2000)

    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupné"}, status_code=503)

    def _mcp_rows(sql):
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _json_m.loads(raw) if isinstance(raw, str) else raw
        if isinstance(r, dict):
            if r.get("ok") is False:
                raise RuntimeError(str(r.get("error")))
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    return r[k]
        if isinstance(r, list):
            return r
        return []

    def _type_id(code):
        res = _pg.query_raw("SELECT id FROM tenant.att_entry_type WHERE tenant_id=:t AND code=:c",
                            {"t": tenant, "c": code})
        rows = res.get("rows") or res.get("data") or []
        return (rows[0].get("id") if rows else None)
    type_work = _type_id("work")
    type_oh = _type_id("overhead")
    if not (type_work and type_oh):
        return JSONResponse({"ok": False, "error": "chybí typy work/overhead pro tenant %s" % tenant},
                            status_code=400)

    _cm = _pg.get_session()      # @contextmanager -> vstoupíme ručně
    sess = _cm.__enter__()
    total = ins = upd = 0
    emp_cache = {}
    try:
        def emp_id(cislo):
            key = str(cislo).strip()
            if key in emp_cache:
                return emp_cache[key]
            r = sess.execute(_t("SELECT id FROM tenant.att_employee WHERE tenant_id=:t AND cislo_zam=:c"),
                             {"t": tenant, "c": key}).first()
            if not r:
                r = sess.execute(_t(
                    "INSERT INTO tenant.att_employee (tenant_id,cislo_zam,is_active,created_at,updated_at) "
                    "VALUES (:t,:c,true,now(),now()) RETURNING id"), {"t": tenant, "c": key}).first()
            emp_cache[key] = r[0]
            return r[0]
        last_id = 0
        cond_to = (" AND DatumPripadu < '%s'" % to_date) if to_date else ""
        while True:
            sql = ("SELECT TOP %d ID, CisloZam, CONVERT(varchar(10),DatumPripadu,23) d, "
                   "CONVERT(varchar(19),CasZacatek,120) z, CONVERT(varchar(19),CasKonec,120) k, "
                   "CasPauza, CasCelkemZakazka hod, CisloZakazky, LoginFrom, "
                   "CAST(VedSchvaleno AS int) ved, CAST(SefSchvaleno AS int) sef, CAST(Uzavreno AS int) uz "
                   # Jirka 27.6.2026: NEimportuj zpět naše zrcadlené řádky (Autor='STRATEGIE') — viz
                   # zpětná smyčka mirror×import (duplicitní centrala1 overhead). Originál = app záznam.
                   "FROM EC_Dochazka WHERE DatumPripadu >= '%s'%s AND ID > %d "
                   "AND ISNULL(Autor,'')<>'STRATEGIE' ORDER BY ID"
                   % (page, from_date, cond_to, last_id))
            rows = _mcp_rows(sql)
            if not rows:
                break
            for r in rows:
                rid = int(r["ID"])
                last_id = rid
                total += 1
                zak = (r.get("CisloZakazky") or "").strip()
                rezie = zak.lower() == "rezie"
                lf = (r.get("LoginFrom") or "").strip().upper()
                src = {"D": "tablet", "C": "manual", "A": "mobile_app"}.get(lf, "import")
                if int(r.get("uz") or 0):
                    st = "locked"
                elif int(r.get("ved") or 0) and int(r.get("sef") or 0):
                    st = "approved"
                else:
                    st = "pending"
                p = {"t": tenant, "emp": emp_id(r["CisloZam"]), "d": r.get("d"),
                     "et": type_oh if rezie else type_work, "h": r.get("hod"),
                     "z": r.get("z"), "k": r.get("k"), "br": int(r.get("CasPauza") or 0),
                     "proj": None if rezie else (zak or None), "st": st, "src": src, "sid": rid}
                res = sess.execute(_t(
                    "UPDATE tenant.att_entry SET employee_id=:emp,entry_date=:d,entry_type_id=:et,hours=:h,"
                    "started_at=:z,ended_at=:k,break_minutes=:br,project_ref=:proj,status=:st,source=:src,"
                    "updated_at=now() WHERE tenant_id=:t AND source_system='centrala1' AND source_id=:sid"), p)
                if (res.rowcount or 0) == 0:
                    sess.execute(_t(
                        "INSERT INTO tenant.att_entry (tenant_id,employee_id,entry_date,entry_type_id,hours,"
                        "started_at,ended_at,break_minutes,project_ref,status,source,source_system,source_id,"
                        "is_active,created_at,updated_at) VALUES (:t,:emp,:d,:et,:h,:z,:k,:br,:proj,:st,:src,"
                        "'centrala1',:sid,false,now(),now())"), p)
                    ins += 1
                else:
                    upd += 1
            sess.commit()
        # Obohať zaměstnance o jméno + napojení na usera z TabCisZam (real data).
        enriched = 0
        try:
            from sqlalchemy import text as _te
            zam = _mcp_rows("SELECT Cislo, LTRIM(RTRIM(ISNULL(Jmeno,'')+' '+ISNULL(Prijmeni,''))) AS nm, "
                            "LoginId FROM TabCisZam WHERE Cislo IS NOT NULL")
            for z in zam:
                cz = str(z.get("Cislo")).strip()
                nm = (z.get("nm") or "").strip() or None
                login = (z.get("LoginId") or "").strip() or None
                uid_m = None
                if login:
                    rr = sess.execute(_te("SELECT id FROM public.users WHERE lower(login_name)=lower(:l) LIMIT 1"),
                                      {"l": login}).first()
                    uid_m = rr[0] if rr else None
                r2 = sess.execute(_te(
                    "UPDATE tenant.att_employee SET full_name=COALESCE(:nm,full_name), "
                    "user_id=COALESCE(:u,user_id), updated_at=now() "
                    "WHERE tenant_id=:t AND cislo_zam=:cz"),
                    {"nm": nm, "u": uid_m, "t": tenant, "cz": cz})
                if (r2.rowcount or 0) > 0:
                    enriched += 1
            sess.commit()
        except Exception as _ee:
            sess.rollback()
            logger.warning("[migrate enrich] %s", _ee)
        return JSONResponse({"ok": True, "total": total, "inserted": ins, "updated": upd,
                             "employees": len(emp_cache), "enriched": enriched,
                             "tenant": tenant, "from": from_date})
    except Exception as exc:
        try:
            sess.rollback()
        except Exception:
            pass
        logger.exception("[migrate-dochazka] %s", exc)
        return JSONResponse({"ok": False, "error": str(exc), "done_total": total}, status_code=500)
    finally:
        try:
            _cm.__exit__(None, None, None)
        except Exception:
            pass


@api_router.get("/app/devices")
async def app_devices(req: Request) -> JSONResponse:
    """Přehled všech mobilních zařízení (kdo / appka / verze / nastavení). Jen rodič."""
    from core.database_data import get_data_session as _gds_dv
    from sqlalchemy import text as _sql_dv

    uid = _get_uid(req)
    _require_admin(uid)
    ds = _gds_dv()
    try:
        rows = ds.execute(_sql_dv("""
            SELECT d.id AS device_row_id, d.app_key, d.user_id,
                   COALESCE(NULLIF(TRIM(CONCAT(u.first_name,' ',u.last_name)),''),
                            u.login_name, '#'||d.user_id) AS user_name,
                   d.device_label, d.phone_number,
                   (d.phone_verified_at IS NOT NULL) AS phone_verified,
                   d.version_code, d.version_name, d.android_release,
                   d.service_enabled, d.call_log_enabled, d.notif_enabled,
                   d.fullscreen_enabled, d.server_url,
                   EXTRACT(EPOCH FROM (now() - d.last_seen_at))::int AS secs_ago,
                   to_char(d.last_seen_at,'YYYY-MM-DD HH24:MI') AS last_seen
            FROM fw.mobile_device d
            LEFT JOIN public.users u ON u.id = d.user_id
            WHERE d.removed_at IS NULL
            ORDER BY d.last_seen_at DESC NULLS LAST
        """)).mappings().all()
        return JSONResponse({"ok": True, "devices": [dict(r) for r in rows]})
    except Exception as exc:
        logger.exception("[app_devices] failed: %s", exc)
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        ds.close()


