@api_router.post("/app/command")
async def app_command_create(req: Request) -> JSONResponse:
    """Parent pošle doporučení uživateli (na mobilu dialog). Jen rodič."""
    import json as _json_cc
    from core.database_data import get_data_session as _gds_cc
    from sqlalchemy import text as _sql_cc
    uid = _get_uid(req)
    _require_admin(uid)
    try:
        body = await req.json()
    except Exception:
        body = {}
    target = body.get("target_user_id")
    ctype = (str(body.get("command_type") or "")).strip()
    if not target or not ctype:
        return JSONResponse({"ok": False, "error": "target_user_id + command_type"}, status_code=400)
    app_key = (str(body.get("app_key") or "mobile")).strip() or "mobile"
    d_title, d_msg = _CMD_DEFAULTS.get(ctype, ("Doporučení", ""))
    title = (str(body.get("title") or d_title))[:120]
    message = (str(body.get("message") or d_msg))[:600]
    payload = body.get("payload")
    ds = _gds_cc()
    try:
        new_id = ds.execute(_sql_cc("""
            INSERT INTO fw.mobile_command
              (app_key, target_user_id, command_type, title, message, payload, created_by)
            VALUES (:app,:uid,:ct,:title,:msg,
                    CASE WHEN :payload IS NULL THEN NULL ELSE CAST(:payload AS jsonb) END,
                    :by)
            RETURNING id
        """), {"app": app_key, "uid": int(target), "ct": ctype, "title": title,
               "msg": message,
               "payload": (_json_cc.dumps(payload) if payload else None),
               "by": uid}).scalar()
        ds.commit()
        return JSONResponse({"ok": True, "id": new_id})
    except Exception as exc:
        ds.rollback()
        logger.exception("[app_command_create] failed: %s", exc)
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        ds.close()


@api_router.get("/app/{app_key}/commands/pending")
async def app_commands_pending(app_key: str, req: Request) -> JSONResponse:
    """Appka načte čekající doporučení pro přihlášeného uživatele (token NEBO cookie)."""
    from core.database_data import get_data_session as _gds_cp
    from sqlalchemy import text as _sql_cp
    if not _app_key_ok(app_key):
        return JSONResponse({"ok": False, "error": "Neplatný app_key"}, status_code=400)
    uid = _uid_from_token_or_cookie(req)
    # HR presence (5.6.): tento poll běží často (á 4 s) dokud appka žije →
    # osvěžíme čerstvost telefonu (řeší řídké ~20min heartbeaty). Throttle 60s.
    try:
        from modules.hr.presence import refresh_user_phone as _cp_rp, client_ip as _cp_ip
        _cp_rp(uid, _cp_ip(req))
    except Exception:
        pass
    ds = _gds_cp()
    try:
        # Marti 7.6.: info zprávy (claude_msg) starší 24 h se samy uklidí —
        # „když už neplatí, nesmí na mobilu viset". Potvrzení (claude_confirm)
        # se uklízí při decide; TTL se jich netýká.
        try:
            ds.execute(_sql_cp(
                "UPDATE fw.mobile_command SET status='done', decided_at=now() "
                "WHERE app_key=:app AND target_user_id=:uid AND status='pending' "
                "AND command_type='claude_msg' AND created_at < now() - interval '24 hours'"),
                {"app": app_key, "uid": uid})
            ds.commit()
        except Exception:
            ds.rollback()
        rows = ds.execute(_sql_cp("""
            SELECT id, command_type, title, message, payload
            FROM fw.mobile_command
            WHERE app_key=:app AND target_user_id=:uid AND status='pending'
            ORDER BY id ASC LIMIT 20
        """), {"app": app_key, "uid": uid}).mappings().all()
        # Adaptivní interval pollu (Marti 6.6.): je-li co schválit → rychle;
        # pracuje-li Claude (nedávná aktivita) → svižně; v klidu → šetři baterii.
        if rows:
            next_poll_s = 3
        else:
            recent = False
            try:
                recent = ds.execute(_sql_cp(
                    "SELECT 1 FROM fw.claude_sql_log "
                    "WHERE created_at > now() - interval '5 minutes' LIMIT 1"
                )).first() is not None
            except Exception:
                recent = False
            next_poll_s = 6 if recent else 20
        return JSONResponse({"ok": True, "commands": [dict(r) for r in rows],
                             "next_poll_s": next_poll_s})
    except Exception as exc:
        logger.exception("[app_commands_pending] failed: %s", exc)
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        ds.close()


@api_router.post("/app/notif/reply")
async def app_notif_reply(req: Request) -> JSONResponse:
    """Odpověď na claude_msg notifikaci → zapíše do tenant.claude_chat (kanál, který Claude čte
    přes bridge) + označí mobile_command jako vyřízenou. Marti 28.6.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        body = {}
    txt = (str(body.get("text") or "")).strip()
    try:
        cid = int(body.get("id"))
    except Exception:
        cid = 0
    if not txt:
        return JSONResponse({"ok": False, "error": "empty"}, status_code=400)
    txt = txt[:4000]
    from sqlalchemy import text as _t
    cm, s = _att_session()
    try:
        tid = s.execute(_t("SELECT COALESCE(last_active_tenant_id,2) FROM public.users WHERE id=:u"),
                        {"u": uid}).scalar() or 2
        qtitle = ""
        if cid:
            qtitle = s.execute(_t("SELECT title FROM fw.mobile_command WHERE id=:i AND target_user_id=:u"),
                               {"i": cid, "u": uid}).scalar() or ""
        msg = (("[odpověď na: " + qtitle + "] ") if qtitle else "") + txt
        s.execute(_t("INSERT INTO tenant.claude_chat(tenant_id,user_id,sender,msg) VALUES (:t,:u,'user',:m)"),
                  {"t": tid, "u": uid, "m": msg})
        if cid:
            s.execute(_t("UPDATE fw.mobile_command SET status='done', decided_at=now() "
                         "WHERE id=:i AND target_user_id=:u"), {"i": cid, "u": uid})
        s.commit()
        return JSONResponse({"ok": True})
    except Exception as exc:
        s.rollback()
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        cm.__exit__(None, None, None)


@api_router.post("/app/command/{cmd_id}/result")
async def app_command_result(cmd_id: int, req: Request) -> JSONResponse:
    """Appka hlásí rozhodnutí uživatele (accept/reject). Token NEBO cookie."""
    from core.database_data import get_data_session as _gds_cr2
    from sqlalchemy import text as _sql_cr2
    uid = _uid_from_token_or_cookie(req)
    try:
        body = await req.json()
    except Exception:
        body = {}
    decision = (str(body.get("decision") or "")).strip().lower()
    status = "accepted" if decision == "accept" else (
        "rejected" if decision == "reject" else "done")
    note = (str(body.get("note") or ""))[:300] or None
    ds = _gds_cr2()
    try:
        cmd = ds.execute(_sql_cr2(
            "SELECT command_type, payload FROM fw.mobile_command "
            "WHERE id=:id AND target_user_id=:uid"
        ), {"id": int(cmd_id), "uid": uid}).mappings().first()
        ds.execute(_sql_cr2("""
            UPDATE fw.mobile_command
            SET status=:st, result_note=:note, decided_at=now()
            WHERE id=:id AND target_user_id=:uid AND status='pending'
        """), {"st": status, "note": note, "id": int(cmd_id), "uid": uid})
        ds.commit()
        # claude_confirm → potvrzení z mobilu rovnou schválí/zamítne zápis
        wres = None
        if cmd and cmd["command_type"] == "claude_confirm" and decision in ("accept", "reject"):
            payload = cmd["payload"] or {}
            if isinstance(payload, str):
                try:
                    import json as _json_cr
                    payload = _json_cr.loads(payload)
                except Exception:
                    payload = {}
            wr = payload.get("write_request_id") if isinstance(payload, dict) else None
            if wr:
                wdec = "approve" if decision == "accept" else "reject"
                wres = _apply_write_decision(int(wr), wdec, uid)
                wres.pop("code", None)
            elif isinstance(payload, dict) and payload.get("att_action"):
                # Interaktivní docházka (Marti 26.6.): Ano/Ne → reálný check-in/out
                wres = _do_att_action(payload, uid, decision)
        return JSONResponse({"ok": True, "write": wres})
    except Exception as exc:
        ds.rollback()
        logger.exception("[app_command_result] failed: %s", exc)
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        ds.close()


@api_router.post("/app/notify")
async def app_notify(req: Request) -> JSONResponse:
    """Claude (X-Deploy-Token) pošle uživateli notifikaci na mobil — „hotovo /
    výsledek / potřebuju pozornost". Vytvoří claude_msg command → appka pollne
    (á 4 s) a cinkne. Bez potvrzování (jen informace). Marti 5.6."""
    import os as _os_n
    from core.database_data import get_data_session as _gn
    from sqlalchemy import text as _tn
    token = req.headers.get("X-Deploy-Token")
    env = _os_n.environ.get("STRATEGIE_DEPLOY_TOKEN")
    if not (token and env and token == env):
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        body = {}
    try:
        uid = int(body.get("user_id") or _DEFAULT_APPROVER_UID)
    except (TypeError, ValueError):
        uid = _DEFAULT_APPROVER_UID
    title = (str(body.get("title") or "Zpráva od Claude"))[:120]
    message = (str(body.get("message") or ""))[:600]
    ds = _gn()
    try:
        nid = ds.execute(_tn("""
            INSERT INTO fw.mobile_command
              (app_key, target_user_id, command_type, title, message, created_by)
            VALUES ('mobile', :uid, 'claude_msg', :title, :msg, NULL)
            RETURNING id
        """), {"uid": uid, "title": title, "msg": message}).scalar()
        ds.commit()
        return JSONResponse({"ok": True, "id": nid})
    except Exception as exc:
        ds.rollback()
        logger.exception("[app_notify] failed: %s", exc)
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=500)
    finally:
        ds.close()


@api_router.post("/app/netscan/ingest")
async def netscan_ingest(req: Request) -> JSONResponse:
    """Mikrotik/netscan agent (X-Deploy-Token) → seznam zařízení na firemní síti.
    Body: {devices:[{mac, ip?, hostname?, ssid?, active?}]}. Aktivní = na síti =
    v budově. Upsert do fw.hr_device dle MAC (device_key='mac:<mac>'). Vlastníka
    nezná → bez vazby na uživatele (link_user=False). Marti 5.6."""
    import os as _os_ns
    token = req.headers.get("X-Deploy-Token")
    env = _os_ns.environ.get("STRATEGIE_DEPLOY_TOKEN")
    if not (token and env and token == env):
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        body = await req.json()
    except Exception:
        body = {}
    devices = body.get("devices") or []
    # (Odstraněno 26.6. — Claude-24: jednorázová diagnostika [netscan][SAMPLE] z 9.6.
    #  logovala warning každý netscan (~5 min) = šum v logu. Byte-delta presence
    #  je už hotová a běží níž, vzorek do diag logu není potřeba.)
    if not isinstance(devices, list):
        return JSONResponse({"ok": False, "error": "devices must be list"}, status_code=400)
    from modules.hr.presence import touch_device as _ni_td
    n = 0
    for d in devices:
        try:
            mac = (str(d.get("mac") or "")).strip().lower()
            if not mac or not d.get("active", True):
                continue
            host = (str(d.get("hostname") or "")[:120]) or None
            ip = (str(d.get("ip") or "")).strip() or None
            ssid = (str(d.get("ssid") or "")).strip() or None
            # Síťově objevené = na firemní síti = v budově (i drátové).
            # Vlastník neznámý → link_user=False. Kategorie 'other' (Marti
            # přeřadí v inventáři); existující typ se nepřepíše (touch_device
            # name=COALESCE, ale device_type ano — proto u nových 'other').
            _ni_td(device_key="mac:" + mac, device_type="other", name=host,
                   uid=None, ip_str=ip, source="mikrotik", ssid=ssid,
                   force_place="building", link_user=False,
                   seen_ago_s=d.get("seen_ago_s"))
            n += 1
        except Exception:
            pass
    # Marti 10.6.: byte-delta presence — accounting snapshot dává byty per IP za
    # interval. IP s byty > 0 = živé (provoz v posledních ~5 min). Uložíme k zařízení.
    try:
        traffic = body.get("traffic") or {}
        if isinstance(traffic, dict) and traffic:
            from core.database_data import get_data_session as _gd_ns
            from sqlalchemy import text as _tt_ns
            sx = _gd_ns()
            try:
                for ipx, bx in traffic.items():
                    try:
                        bi = int(bx)
                    except Exception:
                        continue
                    if bi <= 0 or not ipx:
                        continue
                    sx.execute(_tt_ns(
                        "UPDATE fw.hr_device SET last_bytes=:b, last_traffic_at=now() "
                        "WHERE last_ip=:ip"), {"b": bi, "ip": str(ipx)})
                sx.commit()
            finally:
                sx.close()
    except Exception:
        logger.exception("[netscan] traffic ingest failed")
    # Marti 7.6.: zařízení zaměstnance v síti → automatický příchod do docházky
    auto = 0
    try:
        auto = _netscan_auto_checkin()
    except Exception:
        logger.exception("[netscan] auto-checkin failed")
    # Self-heal docházky (Marti 26.6.): „aktivní/Makám" smí být JEN záznam, který už
    # začal (started_at<=now) a nemá konec (ended_at IS NULL). Budoucí plánovaný start
    # z importu ani uzavřený záznam nesmí ukazovat Makám. Běží často (každý netscan) →
    # robustní bez závislosti na úzkém půlnočním okně. Marti měl ve 3 ráno Makám.
    try:
        # Marti-AI role (smí UPDATE tenant.att_entry); strategie session má jen
        # SELECT na tenant.* → dřív padalo „permission denied for table att_entry"
        # každý netscan (error flood). Claude-24 diagnostika 26.6.
        from sqlalchemy import text as _th_ns
        # _att_session() vrací (cm, s) — dřív se tuple omylem přiřadil do _sh
        # → 'tuple' object has no attribute 'execute' každý netscan (Marti 7.7.).
        _cm_ns, _sh = _att_session()
        try:
            _sh.execute(_th_ns("UPDATE tenant.att_entry SET is_active=false, updated_at=now() "
                               "WHERE tenant_id=2 AND is_active=true "
                               "AND (ended_at IS NOT NULL OR started_at > now())"))
            _sh.commit()
        finally:
            _cm_ns.__exit__(None, None, None)
    except Exception:
        logger.exception("[netscan] att self-heal failed")
    # …a při té příležitosti hlídka anomálií (dedup v tabulce → žádný spam)
    try:
        _att_anomaly_scan()
    except Exception:
        logger.exception("[netscan] anomaly scan failed")
    # Přetažené pauzy/oběd/jednání → interaktivní „ještě? Ano/Ne" (Marti 26.6.)
    try:
        _att_break_overrun_nudge()
    except Exception:
        logger.exception("[netscan] break overrun nudge failed")
    # Marti 9.6.: živá docházka EC → naše (throttle 5 min, hybrid Fáze 1)
    try:
        _maybe_sync_ec_dochazka()
    except Exception:
        logger.exception("[netscan] ec dochazka sync failed")
    # Marti 9.6.: jemné připomenutí dlouhé běžící směny (hlasem Marti-AI, 1×/hod)
    try:
        _maybe_long_shift_nudge()
    except Exception:
        logger.exception("[netscan] long shift nudge failed")
    return JSONResponse({"ok": True, "count": n, "auto_checkin": auto})


def _netscan_auto_checkin() -> int:
    """Marti 7.6.2026: „Když se jeho mobil nebo notebook přihlásí do naší sítě,
    můžeme rovnou člověka přihlásit do docházky." Auto-příchod (source 'netscan')
    + notifikace na mobil. Pojistky: jen PRVNÍ píchnutí dne (návrat z pauzy řeší
    člověk sám), ne při nahlášené absenci, jen zařízení s reports_presence.

    Marti 12.6.2026: přítomnost zařízení v budově NENÍ oficiální docházka (jiný
    soudeček). Docházku vede STRATEGIE jako externí dodavatel personálních služeb.
    → NEpícháme automaticky; jen pošleme přátelské upozornění (1×/den/člověk).

    Marti 16.6.2026: BEZ časového omezení — 24/7. Kdo je v práci i v 1 ráno, dostane
    upozornění. Jediná pojistka je ČERSTVÝ příchod (bld_first < 45 min), aby trvale
    zapnutý NB přes noc nenotifikoval pořád dokola (i tak 1×/den dedup). Ladíme."""
    from sqlalchemy import text as _t
    cm, s = _att_session()
    done = 0
    try:
        rows = s.execute(_t(
            "SELECT DISTINCT em.id AS emp_id, em.user_id "
            "FROM fw.hr_device d "
            "JOIN tenant.att_employee em ON em.user_id = d.owner_user_id "
            "  AND em.tenant_id = :tn AND em.is_active = true "
            "LEFT JOIN fw.hr_device_category cat ON cat.code = d.device_type "
            "WHERE d.owner_user_id IS NOT NULL "
            "  AND COALESCE(cat.reports_presence, true) = true "
            "  AND d.last_place = 'building' "
            "  AND d.last_seen_at > now() - interval '12 minutes' "
            "  AND d.bld_first > now() - interval '45 minutes' "  # Marti 16.6.: jen čerstvý příchod (ne always-on NB)
            "  AND NOT EXISTS (SELECT 1 FROM tenant.att_entry x "
            "       WHERE x.tenant_id = :tn AND x.employee_id = em.id "
            "         AND x.entry_date = current_date AND x.started_at IS NOT NULL "
            "         AND x.status NOT IN ('superseded')) "
            "  AND NOT EXISTS (SELECT 1 FROM tenant.att_entry ax "
            "       JOIN tenant.att_entry_type tx ON tx.id = ax.entry_type_id "
            "       WHERE ax.tenant_id = :tn AND ax.employee_id = em.id "
            "         AND ax.entry_date = current_date "
            "         AND tx.category = 'absence' AND ax.status IN ('pending','approved')) "
            # Marti 26.6.: monitor respektuje kategorii — lidem v 'bez_automatu' check-in nenabízíme
            "  AND NOT EXISTS (SELECT 1 FROM tenant.att_user_kategorie uk "
            "       JOIN tenant.att_kategorie k ON k.id=uk.kategorie_id "
            "       WHERE uk.user_id = em.user_id AND k.kod='bez_automatu')"),
            {"tn": _ATT_TENANT}).fetchall()
        if not rows:
            s.commit()
            return 0
        _NS_TITLE = "👋 Jsi v práci?"
        for r in rows:
            # Marti 12.6.: NEpíchat automaticky — jen přátelské upozornění, 1×/den/člověk
            # (dedup přes mobile_command, bez vazby na docházkový záznam).
            already = s.execute(_t(
                "SELECT 1 FROM fw.mobile_command WHERE target_user_id=:uid "
                "AND command_type IN ('claude_msg','claude_confirm') AND title=:ti "
                "AND created_at >= date_trunc('day', now()) LIMIT 1"),
                {"uid": r[1], "ti": _NS_TITLE}).first()
            if already:
                continue
            # Interaktivní (Marti 26.6.): Ano/Ne → Ano reálně píchne příchod.
            s.execute(_t(
                "INSERT INTO fw.mobile_command (app_key, target_user_id, command_type, title, message, payload, created_by) "
                "VALUES ('mobile', :uid, 'claude_confirm', :ti, :msg, CAST(:pl AS jsonb), NULL)"),
                {"uid": r[1], "ti": _NS_TITLE,
                 "msg": "Vidím tvoje zařízení ve firemní síti. Mám ti píchnout příchod do "
                        "Docházky? Ano = píchnu ti ho hned teď, Ne = nech být. — Tvoje Marti",
                 "pl": '{"att_action":"checkin"}'})
            done += 1
        s.commit()
        return done
    except Exception:
        s.rollback()
        raise
    finally:
        cm.__exit__(None, None, None)


@api_router.get("/contact-vcard")
async def contact_vcard(req: Request):
    """Fáze (1.6.2026, Marti: "přidávat čísla do kontaktů telefonu" — callback
    caller-ID): vygeneruje vCard 3.0 (.vcf). Web nemůže psát do adresáře přímo;
    .vcf s Content-Disposition attachment → OS nabídne "Přidat do kontaktů".

    Query (vše optional): given, family, fn, org, email, url,
    tel_cell, tel_work, tel. Slouží MVP banneru (fn+tel_cell) i plnému
    kontaktu z CRM řádku (frontend namapuje pole → params).
    """
    from fastapi.responses import Response as _VResp

    _get_uid(req)  # jakýkoliv přihlášený
    q = req.query_params

    def _vesc(s):
        return (str(s or "")
                .replace("\\", "\\\\").replace(";", "\\;")
                .replace(",", "\\,").replace("\r", "").replace("\n", "\\n"))

    given = (q.get("given") or "").strip()
    family = (q.get("family") or "").strip()
    org = (q.get("org") or "").strip()
    fn = (q.get("fn") or "").strip() or (given + " " + family).strip() or org or "Kontakt"
    email = (q.get("email") or "").strip()
    url = (q.get("url") or "").strip()

    lines = ["BEGIN:VCARD", "VERSION:3.0",
             "N:%s;%s;;;" % (_vesc(family), _vesc(given)),
             "FN:%s" % _vesc(fn)]
    if org:
        lines.append("ORG:%s" % _vesc(org))
    for key, typ in (("tel_cell", "CELL"), ("tel_work", "WORK"), ("tel", "VOICE")):
        num = (q.get(key) or "").strip()
        if num:
            lines.append("TEL;TYPE=%s:%s" % (typ, _vesc(num)))
    if email:
        lines.append("EMAIL;TYPE=WORK:%s" % _vesc(email))
    if url:
        lines.append("URL:%s" % _vesc(url))
    lines.append("END:VCARD")
    vcf = "\r\n".join(lines) + "\r\n"

    safe = "".join(c for c in fn if c.isalnum() or c in " _-")[:50].strip() or "kontakt"
    return _VResp(
        content=vcf,
        media_type="text/vcard; charset=utf-8",
        headers={"Content-Disposition": 'attachment; filename="%s.vcf"' % safe},
    )


@api_router.get("/employee-doc")
async def employee_doc(req: Request):
    """Marti 10.6.2026 — personální dokument „na klik".
    ?engagement_id=&typ=smlouva|vymer|popis|dpp → branded docx ze živých dat
    (PG engagement/složky + Helios TabCisZam osobní údaje + číslo účtu).
    ACL: rodič NEBO payroll_officer (Šárka)."""
    _ab = _amb_block_others(req)
    if _ab is not None:
        return _ab
    from fastapi.responses import Response as _R
    from fastapi import HTTPException as _HX
    import json as _jdoc
    import datetime as _dtdoc
    from sqlalchemy import text as _t
    from modules.strategie_pg.application import service as _pgdoc
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.erp.api import doc_generator as _dg

    uid = _get_uid(req)
    q = req.query_params
    typ = (q.get("typ") or "smlouva").strip()
    try:
        eng_id = int(q.get("engagement_id") or 0)
    except ValueError:
        eng_id = 0
    if eng_id <= 0:
        raise _HX(status_code=400, detail="chybí engagement_id")

    cm = _pgdoc.get_session()
    s = cm.__enter__()
    try:
        allowed = bool(is_marti_parent(uid))
        if not allowed:
            er0 = s.execute(_t("SELECT id FROM tenant.att_employee WHERE tenant_id=2 AND user_id=:u"),
                            {"u": uid}).first()
            if er0:
                try:
                    po = s.execute(_t("SELECT tenant.resolve_role(2, :e, 'payroll_officer')"),
                                   {"e": er0[0]}).first()
                    allowed = bool(po and po[0] and int(po[0]) == int(er0[0]))
                except Exception:
                    allowed = False
        if not allowed:
            raise _HX(status_code=403, detail="Generování dokumentů: jen rodiče nebo payroll_officer.")

        er = s.execute(_t(
            "SELECT e.cislo_zam, e.full_name, c.code, en.engagement_type, en.pozice_text,"
            " to_char(en.smlouva_od,'YYYY-MM-DD'), to_char(en.smlouva_do,'YYYY-MM-DD'), en.uvazek_tyden_h"
            " FROM tenant.engagement en JOIN tenant.att_employee e ON e.id=en.employee_id"
            " LEFT JOIN tenant.company c ON c.id=en.company_id"
            " WHERE en.id=:i AND en.tenant_id=2 AND en.is_current=true"), {"i": eng_id}).first()
        if not er:
            raise _HX(status_code=404, detail="engagement nenalezen")
        cislo, full_name, firma, etyp, pozice, od, do, uvazek = er
        comps = {}
        for r2 in s.execute(_t(
            "SELECT wct.code, wc.amount_planned FROM tenant.wage_component wc"
            " JOIN tenant.wage_component_type wct ON wct.id=wc.component_type_id"
            " WHERE wc.engagement_id=:i AND wc.amount_planned IS NOT NULL AND wc.amount_planned<>0"),
            {"i": eng_id}).fetchall():
            comps[r2[0]] = float(r2[1])
    finally:
        cm.__exit__(None, None, None)

    nar = bydliste = ucet = None
    try:
        mcp = get_eurosoft_mcp_client()
        if mcp is not None and cislo:
            def _one(sql):
                raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                         {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
                r = _jdoc.loads(raw) if isinstance(raw, str) else raw
                rows = r.get("rows") if isinstance(r, dict) else r
                return (rows[0] if rows else None)
            z = _one("SELECT TOP 1 CONVERT(varchar(10),DatumNarozeni,23) nar, AdrTrvUliceSCisly ul,"
                     " AdrTrvMisto mi, AdrTrvPSC psc FROM TabCisZam WHERE Cislo=%d" % int(cislo))
            if isinstance(z, dict):
                nar = z.get("nar")
                ul, mi, psc = (z.get("ul") or ""), (z.get("mi") or ""), (z.get("psc") or "")
                bydliste = (ul + ", " + (psc + " " + mi).strip()).strip(", ").strip() or None
            b = _one("SELECT TOP 1 b.CisloUctu+'/'+u.KodUstavu uc FROM TabBankSpojeni b"
                     " JOIN TabCisZam z ON z.ID=b.IDZam JOIN TabPenezniUstavy u ON u.ID=b.IDUstavu"
                     " WHERE z.Cislo=%d AND b.Prednastaveno=1" % int(cislo))
            if isinstance(b, dict):
                ucet = b.get("uc")
    except Exception:
        pass

    _labels = {"premie": "Prémie", "vedeni_lidi": "Příplatek za vedení lidí",
               "individualni": "Individuální odměna", "jednatelska_odmena": "Odměna jednatele/společníka"}
    extra = [(_labels.get(k, k), v) for k, v in comps.items() if k not in ("zaklad", "os_ohodnoceni")]
    data = {
        "jmeno": (full_name or "").strip(), "narozeni": nar, "bydliste": bydliste,
        "firma": (firma or "ES"), "pozice": (pozice or "").strip(),
        "od": od, "do": do, "uvazek": uvazek,
        "zaklad": comps.get("zaklad"), "os_ohod": comps.get("os_ohodnoceni"),
        "extra": extra, "ucet": ucet, "kategorie": "",
    }
    _td = _dtdoc.date.today()
    _dg.TODAY = "%d. %s %d" % (_td.day, _dg.MESICE[_td.month], _td.year)
    try:
        fname, content = _dg.generate(data, typ)
    except ValueError as exc:
        raise _HX(status_code=400, detail=str(exc))
    # Content-Disposition musí být latin-1 → ASCII fallback + filename* UTF-8 (RFC 5987)
    import unicodedata as _ud
    from urllib.parse import quote as _q
    _ascii = _ud.normalize("NFKD", fname).encode("ascii", "ignore").decode("ascii") or "dokument.docx"
    _cd = "attachment; filename=\"%s\"; filename*=UTF-8''%s" % (_ascii, _q(fname))
    return _R(content=content,
              media_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
              headers={"Content-Disposition": _cd})


