@api_router.get("/app/banka/saldo")
def banka_saldo(req: Request):
    """Saldo: pohledávky (311 — kdo nám dluží) vs závazky (321 — komu dlužíme), po
    organizaci, s částkou po splatnosti. Marti 23.6.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    typ = (req.query_params.get("typ") or "pohledavky").strip()
    ssk = "311" if typ == "pohledavky" else "321"
    firma = (req.query_params.get("firma") or "EC").upper()
    tbl = "tenant.es_saldo_fa" if firma == "ES" else "tenant.ec_saldo_fa"
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        # ČISTÉ NETTO (ne SUM(ABS)) — EUR + CZK položky se vynetují; saldo je už v CZK (Marti 23.6.2026).
        su = s.execute(_t(
            "SELECT cislo_sal_sk, COUNT(*) n, ROUND(SUM(saldo)) suma, "
            "COUNT(*) FILTER (WHERE COALESCE(dnu_prodleni,0)>0) n_po, "
            "ROUND(SUM(saldo) FILTER (WHERE COALESCE(dnu_prodleni,0)>0)) suma_po "
            "FROM " + tbl + " WHERE COALESCE(saldo,0)<>0 AND cislo_sal_sk IN ('311','321') "
            "GROUP BY cislo_sal_sk")).mappings().all()
        sm = {r["cislo_sal_sk"]: {"pocet": int(r["n"] or 0), "suma": abs(float(r["suma"] or 0)),
                                  "pocet_po": int(r["n_po"] or 0), "suma_po": abs(float(r["suma_po"] or 0))} for r in su}
        rows = s.execute(_t(
            "SELECT s.cislo_org, COALESCE(NULLIF(o.firma,''),NULLIF(o.nazev,''),NULLIF(o.zkratka,''),'#'||s.cislo_org::text) nazev, "
            "COUNT(*) n, ROUND(ABS(SUM(s.saldo))) suma, MAX(s.dnu_prodleni) max_prodleni, "
            "ROUND(ABS(SUM(s.saldo) FILTER (WHERE COALESCE(s.dnu_prodleni,0)>0))) suma_po, "
            "ROUND(ABS(SUM(s.saldo) FILTER (WHERE NOT COALESCE(s.ma_platba_vs,false) AND NOT COALESCE(s.vnitroskupina,false)))) realne, "
            "COUNT(*) FILTER (WHERE NOT COALESCE(s.ma_platba_vs,false) AND NOT COALESCE(s.vnitroskupina,false)) n_realne, "
            "bool_or(COALESCE(s.vnitroskupina,false)) je_vnitro "
            "FROM " + tbl + " s LEFT JOIN tenant.ec_organizace o ON o.cislo_org=s.cislo_org "
            "WHERE COALESCE(s.saldo,0)<>0 AND s.cislo_sal_sk=:k "
            "GROUP BY s.cislo_org, o.firma, o.nazev, o.zkratka HAVING SUM(s.saldo)<>0 "
            "ORDER BY ABS(SUM(s.saldo) FILTER (WHERE NOT COALESCE(s.ma_platba_vs,false) AND NOT COALESCE(s.vnitroskupina,false))) DESC NULLS LAST, ABS(SUM(s.saldo)) DESC LIMIT 200"), {"k": ssk}).mappings().all()
        return {"ok": True, "typ": typ, "firma": firma,
                "souhrn": {"pohledavky": sm.get("311", {"pocet": 0, "suma": 0, "pocet_po": 0, "suma_po": 0}),
                           "zavazky": sm.get("321", {"pocet": 0, "suma": 0, "pocet_po": 0, "suma_po": 0})},
                "organizace": [dict(r) for r in rows]}
    finally:
        s.close()


@api_router.get("/app/dochazka/zakazky")
def dochazka_zakazky_ep(req: Request):
    """Docházka všech lidí s rozpadem po zakázkách (z tenant.vyroba_work + oz_zakazky).
    Přehled PŘED přenosem do staré Centrály. Marti 8.7.2026.
    Viditelnost: VŠEM přihlášeným (Marti 8.7.2026 „všem", přes Jirku) — dřív jen cockpit."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    import datetime as _dt
    s = _g()
    try:
        if not uid:
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        today = _dt.date.today()
        od = req.query_params.get("od") or today.replace(day=1).isoformat()
        do = req.query_params.get("do") or today.isoformat()
        src = (req.query_params.get("src") or "").strip()
        wh = "w.tenant_id=2 AND w.datum >= :od AND w.datum <= :do"
        params = {"od": od, "do": do}
        if src in ("app", "centrala1"):
            wh += " AND w.source_system = :src"
            params["src"] = src
        rows = s.execute(_t("""
            SELECT COALESCE(u.first_name||' '||u.last_name,'?') jmeno, w.user_id, w.cislo_zam,
                   to_char(w.datum,'YYYY-MM-DD') datum_iso, to_char(w.datum,'DD.MM.YYYY') den,
                   COALESCE(w.source_system,'?') src, trim(w.zakazka_ref) zak,
                   COALESCE(z."Nazev",'') nazev, ROUND(COALESCE(w.hodiny,0)::numeric,2) hod,
                   (SELECT string_agg(DISTINCT e.status, ',') FROM tenant.att_entry e
                      JOIN tenant.att_employee ae ON ae.id=e.employee_id
                     WHERE ae.user_id=w.user_id AND e.tenant_id=2 AND e.entry_date=w.datum) stav
            FROM tenant.vyroba_work w
            LEFT JOIN public.users u ON u.id=w.user_id
            LEFT JOIN LATERAL (SELECT "Nazev" FROM tenant.oz_zakazky z2
                               WHERE trim(z2."CisloZakazky")=trim(w.zakazka_ref) LIMIT 1) z ON true
            WHERE """ + wh + """
            ORDER BY w.datum DESC, jmeno, zak"""), params).mappings().all()
        out = [dict(r) for r in rows]
        lidi = len({r["user_id"] for r in out})
        zaks = len({r["zak"] for r in out if r["zak"]})
        hod = round(sum(float(r["hod"] or 0) for r in out), 1)
        return {"ok": True, "od": od, "do": do, "src": src, "rows": out,
                "souhrn": {"lidi": lidi, "zakazek": zaks, "hodin": hod, "radku": len(out)}}
    finally:
        s.close()


@api_router.get("/app/dochazka/lide")
def dochazka_lide_ep(req: Request):
    """Seznam lidí (kdo má výrobní záznamy) pro výběr v přehledu docházky po
    zakázkách. Kdokoli přihlášený — každý smí vidět i kolegu. Marti 8.7.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        rows = s.execute(_t(
            # Jirka 10.7.: NULL křestní (např. Brigádník Saxana) nulovalo celý concat → „?".
            "SELECT u.id user_id, COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'')||' '||COALESCE(u.last_name,'')),''),'?') jmeno "
            "FROM public.users u WHERE u.id IN ("
            "  SELECT w.user_id FROM tenant.vyroba_work w "
            "    WHERE w.tenant_id=2 AND w.user_id IS NOT NULL "
            "  UNION "
            "  SELECT ds.user_id FROM tenant.att_day_summary ds "
            "    WHERE ds.tenant_id=2 AND ds.user_id IS NOT NULL AND COALESCE(ds.cas_celkem,0)>0) "
            "ORDER BY jmeno")).mappings().all()
        me = s.execute(_t("SELECT COALESCE(first_name||' '||last_name,'?') j "
                          "FROM public.users WHERE id=:i"), {"i": uid}).scalar()
        return {"ok": True, "me": {"user_id": uid, "jmeno": me or ("uživatel %s" % uid)},
                "lide": [dict(r) for r in rows]}
    finally:
        s.close()


@api_router.get("/app/dochazka/moje")
def dochazka_moje_ep(req: Request):
    """Historie docházky s rozpadem po zakázkách. Default = přihlášený uživatel;
    ?uid=<id> ukáže kolegu (každý smí vidět kolegu — Marti 8.7.2026)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        target = int(req.query_params.get("uid") or uid)
    except Exception:
        target = uid
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    import datetime as _dt
    s = _g()
    try:
        today = _dt.date.today()
        od = req.query_params.get("od") or (today - _dt.timedelta(days=90)).isoformat()
        do = req.query_params.get("do") or today.isoformat()

        def _dlabel(iso):
            p = str(iso).split("-")
            return (p[2] + "." + p[1] + "." + p[0]) if len(p) == 3 else str(iso)

        # 1) Přítomnost (docházka) per den = att_day_summary.cas_celkem (čistý denní
        #    součet; att_entry NEsčítat — má překryvná pole work/nenarokova).
        pres = s.execute(_t(
            "SELECT to_char(ds.datum,'YYYY-MM-DD') d, "
            "       ROUND(COALESCE(ds.cas_celkem,0)::numeric,2) h "
            "FROM tenant.att_day_summary ds "
            "WHERE ds.user_id=:uid AND ds.tenant_id=2 AND COALESCE(ds.cas_celkem,0)>0 "
            "  AND ds.datum>=:od AND ds.datum<=:do"),
            {"uid": target, "od": od, "do": do}).mappings().all()

        # 2) Zakázkové segmenty (rozpad) per den z vyroba_work
        zak = s.execute(_t("""
            SELECT to_char(w.datum,'YYYY-MM-DD') datum_iso,
                   COALESCE(w.source_system,'?') src, trim(w.zakazka_ref) zak,
                   COALESCE(z."Nazev",'') nazev, ROUND(COALESCE(w.hodiny,0)::numeric,2) hod
            FROM tenant.vyroba_work w
            LEFT JOIN LATERAL (SELECT "Nazev" FROM tenant.oz_zakazky z2
                               WHERE trim(z2."CisloZakazky")=trim(w.zakazka_ref) LIMIT 1) z ON true
            WHERE w.user_id=:uid AND w.datum>=:od AND w.datum<=:do
            ORDER BY w.datum DESC, zak"""), {"uid": target, "od": od, "do": do}).mappings().all()

        days = {}
        for p in pres:
            d = p["d"]
            days[d] = {"datum_iso": d, "den": _dlabel(d),
                       "presence": float(p["h"] or 0), "zakazky": []}
        for r in zak:
            d = r["datum_iso"]
            g = days.setdefault(d, {"datum_iso": d, "den": _dlabel(d),
                                    "presence": 0.0, "zakazky": []})
            g["zakazky"].append({"zak": r["zak"] or "—", "nazev": r["nazev"],
                                 "src": r["src"], "hod": float(r["hod"] or 0)})
        # Univerzálně: zbytek přítomnosti bez zakázky = Režie (i pro lidi bez zakázek)
        for d, g in days.items():
            zh = round(sum(z["hod"] for z in g["zakazky"]), 2)
            rez = round(g["presence"] - zh, 2)
            if rez > 0.05:
                g["zakazky"].append({"zak": "REŽIE", "nazev": "Režie (bez zakázky)",
                                     "src": "rezie", "hod": rez})
            g["hod"] = round(g["presence"] if g["presence"] > 0 else zh, 2)
            g.pop("presence", None)
        out = sorted(days.values(), key=lambda x: x["datum_iso"], reverse=True)
        total = round(sum(g["hod"] for g in out), 1)
        return {"ok": True, "od": od, "do": do, "dny": out,
                "souhrn": {"dnu": len(out), "hodin": total}}
    finally:
        s.close()


