@api_router.get("/app/ucto/porovnani")
def ucto_porovnani(req: Request):
    """Účetní kontrolní vrstva: konta (stavy účtů) k 31.12.2025 — office (Helios DB_EC/IS
    přes MCP) vs cloud (UCTO_EC/ES na 188.12 přes pyodbc), po účtech + rozdíl. Bere jen
    souhrnné řádky (Stredisko prázdné) — viz docs/helios_cloud_knowhow. Marti 27.6.2026.
    Zrcadlo pro dorovnání rozdílů. Parent-only."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _g
    s = _g()
    try:
        if not _is_cockpit(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    finally:
        s.close()
    firma = (req.query_params.get("firma") or "EC").upper()
    off_pfx = _firma_src_pfx(firma)
    cloud_db = _firma_cloud_db(firma)
    idobd = _firma_idobdobi(firma, 2025)

    def _konta_sql(pfx):
        return ("WITH latest AS (SELECT LTRIM(RTRIM(k.Ucet)) AS ucet, k.KonStavDEN_MD AS md, "
                "k.KonStavDEN_Dal AS dal, k.ZustDEN_KonSt AS zust, "
                "ROW_NUMBER() OVER (PARTITION BY k.Ucet ORDER BY k.Datum DESC) rn "
                "FROM " + pfx + ".dbo.TabKontaD k WHERE k.IdObdobi=" + str(idobd) +
                " AND k.Datum<='20251231' AND (k.Stredisko IS NULL OR LTRIM(RTRIM(k.Stredisko))='')) "
                "SELECT ucet, md, dal, zust FROM latest WHERE rn=1")

    office = {}
    try:
        from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
        import json as _jx
        _mcp = get_eurosoft_mcp_client()
        if _mcp is None:
            return {"ok": False, "error": "EUROSOFT MCP nedostupný (office)"}
        _rj = _mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                  {"sql": _konta_sql(off_pfx), "db_name": "DB_EC"}, conversation_id=None)
        _r = _jx.loads(_rj) if isinstance(_rj, str) else _rj
        for _row in (_r.get("rows") if isinstance(_r, dict) else []) or []:
            office[str(_row.get("ucet")).strip()] = _row
    except Exception as e:
        return {"ok": False, "error": "office (MCP): %s" % str(e)[:200]}

    _cl = _mssql188_query(_konta_sql(cloud_db))
    if not _cl.get("ok"):
        return {"ok": False, "error": "cloud (188): %s" % _cl.get("error")}
    cloud = {}
    _ci = {c: i for i, c in enumerate(_cl.get("columns") or [])}
    for _row in _cl.get("rows") or []:
        cloud[str(_row[_ci["ucet"]]).strip()] = _row

    # názvy + STAV účtů (účetní osnova) z TabCisUctDef pro daný rok (IdObdobi) — respektuje
    # blokované (neaktivní) účty. Blokovano=1 → účet je v daném roce zablokovaný.
    nazvy = {}
    blok = {}
    try:
        _nz = _mssql188_query("SELECT LTRIM(RTRIM(CisloUcet)) AS u, MAX(NazevUctu) AS n, "
                              "MAX(CAST(Blokovano AS int)) AS b FROM " + cloud_db +
                              ".dbo.TabCisUctDef WHERE IdObdobi=" + str(idobd) +
                              " AND NazevUctu IS NOT NULL AND NazevUctu<>'' GROUP BY LTRIM(RTRIM(CisloUcet))")
        if _nz.get("ok"):
            _ni = {c: i for i, c in enumerate(_nz.get("columns") or [])}
            for _row in _nz.get("rows") or []:
                _u = str(_row[_ni["u"]]).strip()
                nazvy[_u] = _row[_ni["n"]]
                blok[_u] = int(_row[_ni["b"]] or 0)
    except Exception:
        pass

    def _f(v):
        try:
            return float(v or 0)
        except Exception:
            return 0.0
    out = []
    for _u in sorted(set(office) | set(cloud)):
        o = office.get(_u, {})
        c = cloud.get(_u)
        oz = _f(o.get("zust"))
        cz = _f(c[_ci["zust"]]) if c else 0.0
        out.append({"ucet": _u, "nazev": nazvy.get(_u, ""), "office_zust": round(oz, 2), "cloud_zust": round(cz, 2),
                    "rozdil": round(cz - oz, 2),
                    "office_md": round(_f(o.get("md")), 2), "cloud_md": round(_f(c[_ci["md"]]) if c else 0.0, 2),
                    "jen_v": "" if (o and c) else ("office" if o else "cloud")})
    out.sort(key=lambda x: abs(x["rozdil"]), reverse=True)
    # účetní osnova = celý číselník účtů (i s nulovým zůstatkem) + zůstatek z konta
    _cz = {x["ucet"]: x["cloud_zust"] for x in out}
    _oz = {x["ucet"]: x["office_zust"] for x in out}
    osnova = [{"ucet": u, "nazev": nazvy[u], "cloud_zust": _cz.get(u, 0.0), "office_zust": _oz.get(u, 0.0),
               "synt": len(u) <= 3 or (u[:3] + "000") == u, "v_konte": u in _cz,
               "blok": blok.get(u, 0)} for u in sorted(nazvy)]
    # blokovaný účet s nenulovým zůstatkem = anomálie (mělo by se prověřit)
    _blok_nenul = [o["ucet"] for o in osnova if o["blok"] and abs(o["cloud_zust"]) >= 0.01]
    sumo = round(sum(x["office_zust"] for x in out), 2)
    sumc = round(sum(x["cloud_zust"] for x in out), 2)
    # HV (tř. 5 a 6)
    def _hv(zkey):
        nak = round(sum(x[zkey] for x in out if x["ucet"][:1] == "5"), 2)
        vyn = round(sum(x[zkey] for x in out if x["ucet"][:1] == "6"), 2)
        return {"naklady": nak, "vynosy": vyn, "hv": round(-(nak + vyn), 2)}
    return {"ok": True, "firma": firma, "radky": out, "osnova": osnova,
            "souhrn": {"office_zust": sumo, "cloud_zust": sumc, "rozdil_celkem": round(sumc - sumo, 2),
                       "uctu": len(out), "uctu_s_rozdilem": sum(1 for x in out if abs(x["rozdil"]) >= 0.01),
                       "uctu_osnova": len(osnova),
                       "uctu_aktivni": sum(1 for o in osnova if not o["blok"]),
                       "uctu_blokovane": sum(1 for o in osnova if o["blok"]),
                       "blok_nenulove": _blok_nenul,
                       "hv_office": _hv("office_zust"), "hv_cloud": _hv("cloud_zust")}}


def _ucto_kateg(naz):
    n = (naz or "").lower()
    if n.startswith("fv") or "vydan" in n: return ("VF", "Vydané faktury")
    if n.startswith("fp") or "prijat" in n or "přijat" in n: return ("PF", "Přijaté faktury")
    if "banka" in n: return ("BANKA", "Banka")
    if "pokladna" in n: return ("POKL", "Pokladna")
    if "kartov" in n: return ("KARTA", "Kartové účty")
    if "mzd" in n: return ("MZDY", "Mzdy")
    if "počáteč" in n or "pocat" in n: return ("PS", "Počáteční stav")
    if "interní" in n or "intern" in n: return ("INT", "Interní doklady")
    if "zápoč" in n or "zapoc" in n: return ("ZAP", "Vzájemné zápočty")
    if "skont" in n: return ("SKON", "Skonta")
    if "sklad" in n: return ("SKLAD", "Sklady")
    return ("OST", "Ostatní")


@api_router.get("/app/ucto/mzdy")
def ucto_mzdy(req: Request):
    """Mzdový přehled (účetní pohled) — měsíčně z deníku: hrubé mzdy (521), zák. pojištění
    zaměstnavatele (524), ost. soc. náklady (527) = mzdové náklady; odvody SP+ZP (336),
    daň ze záv. čin. (342), čistá mzda k výplatě (331). Cloud Helios. Marti 27.6.2026. Parent."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _g
    s = _g()
    try:
        if not _is_cockpit(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    finally:
        s.close()
    firma = (req.query_params.get("firma") or "EC").upper()
    try:
        rok = int(req.query_params.get("rok") or 2025)
    except Exception:
        rok = 2025
    cloud_db = _firma_cloud_db(firma)
    idobd = _firma_idobdobi(firma, rok) or _firma_idobdobi(firma, 2025)
    _q = ("SELECT MONTH(d.DatumPripad) m, "
          "ROUND(SUM(CASE WHEN LEFT(LTRIM(d.UcetMD),3)='521' THEN d.CastkaMD ELSE 0 END),2) hrube, "
          "ROUND(SUM(CASE WHEN LEFT(LTRIM(d.UcetMD),3)='524' THEN d.CastkaMD ELSE 0 END),2) pojzam, "
          "ROUND(SUM(CASE WHEN LEFT(LTRIM(d.UcetMD),3)='527' THEN d.CastkaMD ELSE 0 END),2) ostsoc, "
          "ROUND(SUM(CASE WHEN LEFT(LTRIM(d.UcetDAL),3)='331' THEN d.CastkaDAL ELSE 0 END),2) cista, "
          "ROUND(SUM(CASE WHEN LEFT(LTRIM(d.UcetDAL),3)='336' THEN d.CastkaDAL ELSE 0 END),2) odvody, "
          "ROUND(SUM(CASE WHEN LEFT(LTRIM(d.UcetDAL),3)='342' THEN d.CastkaDAL ELSE 0 END),2) dan "
          "FROM " + cloud_db + ".dbo.TabDenik d WHERE d.IdObdobi=" + str(idobd) +
          " AND d.DatumPripad IS NOT NULL GROUP BY MONTH(d.DatumPripad) ORDER BY MONTH(d.DatumPripad)")
    _r = _mssql188_query(_q)
    if not _r.get("ok"):
        return {"ok": False, "error": _r.get("error")}
    _i = {c: k for k, c in enumerate(_r["columns"])}
    mes = []
    tot = {"hrube": 0.0, "pojzam": 0.0, "ostsoc": 0.0, "cista": 0.0, "odvody": 0.0, "dan": 0.0}
    for v in _r["rows"]:
        row = {"mesic": v[_i["m"]]}
        for k in tot:
            row[k] = float(v[_i[k]] or 0)
            tot[k] += row[k]
        row["naklady"] = round(row["hrube"] + row["pojzam"] + row["ostsoc"], 2)
        mes.append(row)
    # počet zaměstnanců s mzdou v roce (distinct přes mzdové složky, scopováno přes TabMzdObd.Rok)
    pocet = None
    _pc = _mssql188_query(
        "SELECT COUNT(DISTINCT s.ZamestnanecId) p FROM " + cloud_db + ".dbo.TabMzSloz s "
        "JOIN " + cloud_db + ".dbo.TabMzdObd o ON s.IdObdobi=o.IdObdobi "
        "WHERE s.ZamestnanecId IS NOT NULL AND o.Rok=" + str(rok))
    if _pc.get("ok") and _pc["rows"]:
        try:
            pocet = int(_pc["rows"][0][0])
        except Exception:
            pass
    tot = {k: round(val, 2) for k, val in tot.items()}
    tot["naklady"] = round(tot["hrube"] + tot["pojzam"] + tot["ostsoc"], 2)
    return {"ok": True, "firma": firma, "rok_cislo": rok, "mesice": mes, "rok": tot, "pocet_zamestnancu": pocet}


# === ZPRACOVÁNÍ MEZD — aktuální období (předzpracování, Marti 27.6.2026) =====
# Read-only monitor: porovná office × cloud pro běžné mzdové období (TabPredzp
# = předzpracování + TabMzSloz = vypočtené složky) → „rovná se / nerovná".
# Workflow Klárka/Petra: import → generovat (EC_ procedura) → zkontrolovat tady → smazat když nesedí.
def _mzd_sum_office(src_db, table, idobd):
    """Souhrn office tabulky přes MCP: zam / hodiny / částka pro IdObdobi (DB_IS cross-db)."""
    try:
        from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
        import json as _jx
        _mcp = get_eurosoft_mcp_client()
        if _mcp is None:
            return None
        pfx = "" if (src_db or "").upper() == "DB_EC" else "[" + src_db + "]."
        sql = ("SELECT COUNT(DISTINCT ZamestnanecId) zam, ISNULL(SUM(Hodiny),0) hod, "
               "ISNULL(SUM(CM_Castka),0) cast FROM " + pfx + "dbo.[" + table + "] "
               "WHERE IdObdobi=" + str(int(idobd)))
        _rj = _mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                  {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        _r = _jx.loads(_rj) if isinstance(_rj, str) else _rj
        rows = _r.get("rows") if isinstance(_r, dict) else _r
        if rows:
            d = rows[0]
            if isinstance(d, dict):
                return {"zam": int(d.get("zam") or 0), "hodiny": float(d.get("hod") or 0),
                        "castka": float(d.get("cast") or 0)}
            return {"zam": int(d[0] or 0), "hodiny": float(d[1] or 0), "castka": float(d[2] or 0)}
    except Exception:
        return None
    return None


def _mzd_sum_cloud(cloud_db, table, idobd):
    r = _mssql188_query("SELECT COUNT(DISTINCT ZamestnanecId) zam, ISNULL(SUM(Hodiny),0) hod, "
                        "ISNULL(SUM(CM_Castka),0) cast FROM " + cloud_db + ".dbo.[" + table + "] "
                        "WHERE IdObdobi=" + str(int(idobd)))
    if r.get("ok") and r.get("rows"):
        v = r["rows"][0]
        return {"zam": int(v[0] or 0), "hodiny": float(v[1] or 0), "castka": float(v[2] or 0)}
    return None


def _mzd_pair(src_db, cloud_db, table, idobd):
    o = _mzd_sum_office(src_db, table, idobd)
    c = _mzd_sum_cloud(cloud_db, table, idobd)
    rovna = bool(o and c and o["zam"] == c["zam"]
                 and abs(o["castka"] - c["castka"]) < 0.5
                 and abs(o["hodiny"] - c["hodiny"]) < 0.5)
    return {"office": o, "cloud": c, "rovna": rovna}


