# Worker mzdového automatu na CLOUD Heliosu (rozluštěno z Profileru DB_EC 28.6.2026).
# Per člověk 3 standardní Helios kroky = generování (INSERT TabZamVyp) + paušály
# (hp_VlozMzPausDoMzSloz) + výpočet (hp_VypocitejMzdu @Z,@O,20). 99997 = "spočítáno
# s výstrahou" → COMMIT (Helios ji vyhodí jako RAISERROR, přes TRY/CATCH = warn, ne chyba).
# Idempotentní (NOT IN TabZamVyp). Dávka TOP(@max) ať Express stihne pod HTTP timeout.
def _mzdy_worker_sql(cloud_db, idobd, maxn, only_zid=None):
    # only_zid = přepočítat JEN jednoho zaměstnance (ZamestnanecId). Bez něj = všichni chybějící.
    zfilt = ("   AND ZamestnanecId=" + str(int(only_zid)) + "\n") if only_zid else ""
    return (
        "USE " + cloud_db + ";\n"
        "SET NOCOUNT ON; SET XACT_ABORT OFF;\n"
        "SET ARITHABORT ON; SET ANSI_WARNINGS ON; SET ANSI_PADDING ON; "
        "SET CONCAT_NULL_YIELDS_NULL ON; SET NUMERIC_ROUNDABORT OFF;\n"
        "DECLARE @O INT=" + str(int(idobd)) + ";\n"
        "DECLARE @Z INT,@Err INT,@Status INT,@Info INT,@em NVARCHAR(2000);\n"
        "DECLARE c CURSOR LOCAL FAST_FORWARD FOR\n"
        " SELECT TOP (" + str(int(maxn)) + ") ZamestnanecId FROM TabZamMzd\n"
        " WHERE IdObdobi=@O AND Automat=1 AND Uzavreno=0 AND StavES IN (0,1)\n"
        "   AND ZamestnanecId NOT IN (SELECT ZamestnanecId FROM TabZamVyp WHERE IdObdobi=@O)\n"
        + zfilt +
        " ORDER BY ZamestnanecId;\n"
        "OPEN c; FETCH NEXT FROM c INTO @Z;\n"
        "WHILE @@FETCH_STATUS=0\n"
        "BEGIN\n"
        " SET @Err=0;SET @em=NULL;\n"
        " BEGIN TRY\n"
        "  BEGIN TRAN;\n"
        "  INSERT TabZamVyp (IdObdobi,ZamestnanecId) VALUES(@O,@Z);\n"
        "  EXEC hp_VlozMzPausDoMzSloz @Z,@O,0,0;\n"
        "  EXEC @Err=hp_VypocitejMzdu @Z,@O,20;\n"
        "  SELECT @Info=Info,@Status=Status FROM TabZamVyp WHERE ZamestnanecId=@Z AND IdObdobi=@O;\n"
        "  IF (@Err<>0) AND @Err NOT IN (99997) ROLLBACK ELSE COMMIT;\n"
        " END TRY\n"
        " BEGIN CATCH\n"
        "  SET @em=ERROR_MESSAGE();\n"
        "  IF @em LIKE '99997%' AND XACT_STATE()=1 COMMIT\n"
        "  ELSE IF @@TRANCOUNT>0 ROLLBACK;\n"
        " END CATCH\n"
        " FETCH NEXT FROM c INTO @Z;\n"
        "END\n"
        "CLOSE c; DEALLOCATE c;\n"
        "SELECT 1 AS hotovo;\n"
    )


# Vyčištění před regenerací (Marti 28.6.: "před insertem vyčištění smazání" = čistá voda).
# Smaže JEN regenerovaný set (Automat=1/Uzavreno=0/StavES IN (0,1)) za období: jejich složky
# (TabMzSloz) + výpočet (TabZamVyp). EC má triggery → DISABLE/ENABLE okolo (na ES no-op).
def _mzdy_clean_sql(cloud_db, idobd):
    o = str(int(idobd))
    inset = ("(SELECT ZamestnanecId FROM dbo.TabZamMzd WHERE IdObdobi=" + o +
             " AND Automat=1 AND Uzavreno=0 AND StavES IN (0,1))")
    return (
        "USE " + cloud_db + ";\nSET NOCOUNT ON;\n"
        "EXEC " + cloud_db + "..sp_executesql N'DISABLE TRIGGER ALL ON dbo.TabZamVyp';\n"
        "EXEC " + cloud_db + "..sp_executesql N'DISABLE TRIGGER ALL ON dbo.TabMzSloz';\n"
        "DELETE FROM dbo.TabMzSloz WHERE IdObdobi=" + o + " AND ZamestnanecId IN " + inset + ";\n"
        "DELETE FROM dbo.TabZamVyp WHERE IdObdobi=" + o + " AND ZamestnanecId IN " + inset + ";\n"
        "EXEC " + cloud_db + "..sp_executesql N'ENABLE TRIGGER ALL ON dbo.TabZamVyp';\n"
        "EXEC " + cloud_db + "..sp_executesql N'ENABLE TRIGGER ALL ON dbo.TabMzSloz';\n"
        "SELECT 1 AS cisto;\n")


# Vyčištění JEN JEDNOHO zaměstnance (přegenerovat jednoho člověka bez dotčení ostatních).
# Smaže jeho složky (TabMzSloz) + výpočet (TabZamVyp) za období — jen pokud je v regenerovaném
# setu (Automat=1/Uzavreno=0/StavES IN (0,1)), aby se uzavřená/ruční páska nikdy nesmazala.
def _mzdy_clean_one_sql(cloud_db, idobd, zid):
    o = str(int(idobd))
    z = str(int(zid))
    guard = (" AND ZamestnanecId IN (SELECT ZamestnanecId FROM dbo.TabZamMzd WHERE IdObdobi=" + o +
             " AND Automat=1 AND Uzavreno=0 AND StavES IN (0,1))")
    return (
        "USE " + cloud_db + ";\nSET NOCOUNT ON;\n"
        "EXEC " + cloud_db + "..sp_executesql N'DISABLE TRIGGER ALL ON dbo.TabZamVyp';\n"
        "EXEC " + cloud_db + "..sp_executesql N'DISABLE TRIGGER ALL ON dbo.TabMzSloz';\n"
        "DELETE FROM dbo.TabMzSloz WHERE IdObdobi=" + o + " AND ZamestnanecId=" + z + guard + ";\n"
        "DELETE FROM dbo.TabZamVyp WHERE IdObdobi=" + o + " AND ZamestnanecId=" + z + guard + ";\n"
        "EXEC " + cloud_db + "..sp_executesql N'ENABLE TRIGGER ALL ON dbo.TabZamVyp';\n"
        "EXEC " + cloud_db + "..sp_executesql N'ENABLE TRIGGER ALL ON dbo.TabMzSloz';\n"
        "SELECT 1 AS cisto;\n")


# PŘEDZPRACOVÁNÍ ze STRATEGIE (zdroj pravdy, Marti 28.6.). Každá složka má VLASTNÍ
# Helios CisloMS (mapa wage_component_type.code→id→wage_system_mapping.ext_code).
# Zápis PER-ŘÁDEK přes cursor (TabPredzp má zašifrovaný Helios trigger ht_InsDel_Predzp,
# který set-based INSERT...SELECT zahazuje; per-row VALUES projde, triggery NEvypínáme).
# Pevná základní (CisloMS=1) jde i do předzpracování (Marti) i na kartu ZakladniPlat pro výpočet.
# rows = list (cislo:int, cislo_ms:int, koruny:int).
def _mzdy_predzprac_sql(cloud_db, idobd, rows):
    o = str(int(idobd))
    vals = ",".join("(%d,%d,%d)" % (int(c), int(ms), int(kc or 0)) for c, ms, kc in rows)
    return (
        "USE " + cloud_db + ";\nSET NOCOUNT ON;\n"
        "IF OBJECT_ID('tempdb..#src') IS NOT NULL DROP TABLE #src;\n"
        "CREATE TABLE #src(cislo int, cislo_ms int, koruny money);\n"
        "INSERT INTO #src(cislo,cislo_ms,koruny) VALUES " + vals + ";\n"
        # čistá voda: smaž dříve zapsané STRATEGIE předzpracování za období
        "DELETE FROM dbo.TabPredzp WHERE IdObdobi=" + o + " AND Autor='STRATEGIE';\n"
        "DECLARE @id INT,@ms INT,@kc MONEY;\n"
        "DECLARE cur CURSOR LOCAL FAST_FORWARD FOR "
        "SELECT c.ID, s.cislo_ms, s.koruny FROM #src s JOIN dbo.TabCisZam c ON c.Cislo=s.cislo WHERE s.koruny<>0;\n"
        "OPEN cur; FETCH NEXT FROM cur INTO @id,@ms,@kc;\n"
        "WHILE @@FETCH_STATUS=0 BEGIN "
        "INSERT dbo.TabPredzp(IdObdobi,ZamestnanecId,CisloMS,Hodiny,Dny,Koruny,Sazba,Autor,DatPorizeni) "
        "VALUES(" + o + ",@id,@ms,0,0,@kc,0,'STRATEGIE',GETDATE()); "
        # pevná základní (1) i na kartu pro výpočet
        "IF @ms=1 UPDATE dbo.TabZamMzd SET ZakladniPlat=@kc WHERE ZamestnanecId=@id AND IdObdobi=" + o + "; "
        "FETCH NEXT FROM cur INTO @id,@ms,@kc; END\n"
        "CLOSE cur; DEALLOCATE cur;\nDROP TABLE #src;\nSELECT 1 AS hotovo;\n")


def _mzdy_predzprac_rows(firma):
    """Mzdové podmínky ze STRATEGIE → per (číslo, Helios CisloMS): složka přes
    wage_component_type.code → id → wage_system_mapping.ext_code (CisloMS).
    K nejnovějšímu asof snapshotu (číslo+firma už vyřešené)."""
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        pr = s.execute(_t(
            "SELECT sn.cislo, msm.ext_code AS cislo_ms, SUM(sn.castka) AS koruny "
            "FROM tenant.helios_wage_snapshot sn "
            "JOIN tenant.wage_component_type wct ON wct.tenant_id=2 AND wct.code=sn.slozka "
            "JOIN tenant.wage_system_mapping msm ON msm.movement_type_id=wct.id "
            "  AND msm.ext_system_code='HELIOS' AND COALESCE(msm.active,true)=true "
            "WHERE sn.tenant_id=2 AND sn.firma=:f AND sn.asof=("
            "  SELECT MAX(asof) FROM tenant.helios_wage_snapshot WHERE tenant_id=2 AND firma=:f) "
            "GROUP BY sn.cislo, msm.ext_code"), {"f": firma}).fetchall()
    finally:
        s.close()
    out = []
    for r in pr:
        try:
            c = int(str(r[0]).strip()); ms = int(r[1]); kc = int(r[2] or 0)
        except Exception:
            continue
        if kc != 0:
            out.append((c, ms, kc, 0))  # (cislo, cislo_ms, koruny, dny)
    return out


# Stravenky (Marti 28.6.): nárok = odpracované dny >4 h v docházce × konstanta 82 Kč.
# Helios složka 793 (Stravenkový paušál do limitu), Dny = počet dní, Koruny = Dny×82.
# Sazba 85→82 Kč (Marti 30.6.2026).
_STRAVENKA_KC = 82
_STRAVENKA_MS = 793
_JEDNATELE_CISLA = {2, 41, 47}  # plne stravne + odmena 693 jen tihle; ostatni 693->651 (Peta 8.7.2026)


def _mzdy_stravenky_rows(firma, rok, mesic):
    """Stravenky (MS 793) = pracovni dny (Po-Pa) MINUS dny s vyloucenou cinnosti, x 82 Kc.
    Pravidla (Peta 8.7.2026): NAROK = HPP + po zkusebni dobe + denni uvazek >= 6 h.
    Vyloucene cinnosti (den bez stravenky): dovolena, lekar, nemoc, OCR, montaz, materska.
    SD (sick day) = pritomnost -> stravenka nalezi. Cte se z att_day_summary (cinnostni dle
    DruhCinnosti) - takze rezie s pritomnou cinnosti se pocita a schovana absence ne.
    Pojistka: pocitame jen lidi s dochazkou v mesici (neaktivni bez dochazky vypadnou)."""
    import calendar as _cal
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    ry = int(rok); rm = int(mesic)
    _ld = _cal.monthrange(ry, rm)[1]
    workdays = sum(1 for _x in range(1, _ld + 1) if _cal.weekday(ry, rm, _x) < 5)  # Po-Pa
    _fd = "%04d-%02d-01" % (ry, rm)
    _lastd = "%04d-%02d-%02d" % (ry, rm, _ld)
    s = _g()
    try:
        # NAROK: HPP + po zkusebni (zkusebni_do < 1. den mesice NEBO = posl. den mesice) + uvazek >= 6 h/den
        elig = set()
        for r in s.execute(_t(
            "SELECT DISTINCT sm.helios_cislo FROM tenant.user_smlouva sm "
            "JOIN tenant.att_employee e ON e.tenant_id=2 AND e.user_id=sm.user_id "
            "LEFT JOIN tenant.engagement g ON g.employee_id=e.id AND g.is_current=true "
            "WHERE sm.tenant_id=2 AND LOWER(COALESCE(sm.typ_smlouvy,''))='hpp' "
            "  AND sm.helios_cislo IS NOT NULL "
            "  AND (g.zkusebni_do IS NULL OR g.zkusebni_do < CAST(:fd AS date) "
            "       OR g.zkusebni_do = CAST(:ld AS date)) "
            "  AND COALESCE(g.uvazek_tyden_h,40)/5.0 >= 6.0"),
                {"fd": _fd, "ld": _lastd}).fetchall():
            try:
                elig.add(int(r[0]))
            except Exception:
                pass
        # vyloucene Po-Pa dny per clovek z att_day_summary (cinnostni). Klice dictu = lide, kteri
        # v mesici maji dochazku (aktivni) -> neaktivni bez dochazky se do stravenek nedostanou.
        excl = {}
        for r in s.execute(_t(
            "SELECT cislo_zam, COUNT(*) FILTER (WHERE ("
            "   COALESCE(cas_dovolena,0)+COALESCE(cas_lekar,0)+COALESCE(cas_nemoc,0)"
            "   +COALESCE(cas_ocr,0)+COALESCE(cas_montaz,0)+COALESCE(cas_materska,0))>0) "
            "FROM tenant.att_day_summary "
            "WHERE tenant_id=2 AND rok=:y AND mesic=:mo AND EXTRACT(dow FROM datum) BETWEEN 1 AND 5 "
            "GROUP BY cislo_zam"),
            {"y": ry, "mo": rm}).fetchall():
            try:
                excl[int(r[0])] = int(r[1] or 0)
            except Exception:
                pass
    finally:
        s.close()
    out = []
    for c in elig:
        if c not in excl:           # bez dochazky v mesici (neaktivni) -> bez stravenek
            continue
        dny = workdays - excl.get(c, 0)
        if dny > 0:
            out.append((c, _STRAVENKA_MS, dny * _STRAVENKA_KC, dny))
    return out


# Benefity HO/OBL — sazby dle e-mailu Petra/Landmark (Marti 30.6.2026). Rule-based:
#  Skupina: KANCELÁŘ = att kategorie dopichavat_fond (skup24); jinak DÍLNA.
#  OBL = denní sazba × odpracované dny (kancelář 109 Kč/den, dílna 279 Kč/den). HR může
#        vypnout per osoba (benefit_volba.obl_on=false). → MS 794. Daňově uznatelné.
#  HO  = 43 Kč × hodiny úvazku/den × min(odpracované dny, 12); JEN kancelář + výjimka
#        Tomáš Bláha (ES 476 = dílna, ale má HO). → MS 795. Daňově uznatelné.
#  Obě složky PONÍŽÍ pohyblivou (432) — nedaněná náhrada za zdaněné os. ohodnocení →
#  nižší základ na SOC POJ. Cap: nech aspoň _BENEFIT_BUFFER Kč pohyblivé; OBL má PŘEDNOST
#  (ze složky os. ohodnocení se vyplácí nejdřív OBL, pak HO — Marti) → při stropu ořež HO.
_HO_MS, _OBL_MS, _POHYB_MS = 795, 794, 432
_HO_HOD_SAZBA = 43.0
_OBL_SAZBA_KANCELAR, _OBL_SAZBA_DILNA = 109.0, 279.0
_HO_DILNA_VYJIMKA = {("2", 476)}                     # Bláha ES 476 = dílna, ale má HO
_HO_BEZ_NAROKU = {("2", 442), ("2", 489)}            # Hruzova ES 442, Nepodalova ES 489 = kancelar BEZ naroku na HO (Peta 8.7.2026)
_LM_ABS_CODES = ('vacation', 'medical', 'sick', 'family_care', 'unpaid', 'maternity')


def _lm_mr(x, m):   # Excel MROUND
    import math
    return math.floor(abs(x) / m + 0.5) * m * (1 if x >= 0 else -1) if m else 0.0


def _lm_rd(x):      # Excel ROUND na celé
    import math
    return math.floor(abs(x) + 0.5) * (1 if x >= 0 else -1)


def _lm_fl(x, m):   # Excel FLOOR
    import math
    return math.floor(x / m) * m if m else 0.0


def _lm_engine(fond, odprac, dny, obl_sazba, ho_hod_narok, osoh):
    """Ověřený Landmark výpočet (= engine z Excelu, sedí 45/45). U/X/W/DPP/parking = 0.
    Vrací (OBL, HO, korekce). korekce je záporná = o kolik se poníží os. ohodnocení."""
    import math
    D = float(fond or 0); E = float(odprac or 0); F = float(dny or 0)
    N = float(obl_sazba or 0); Q = _HO_HOD_SAZBA; R = float(ho_hod_narok or 0); V = float(osoh or 0)
    if D <= 0:
        return 0.0, 0.0, 0.0
    podil = E / D
    OBL = _lm_rd(F * N)
    HOhod = _lm_mr(podil * R, 0.5)
    HO0 = _lm_rd(Q * HOhod)
    volna = math.ceil((podil * V) / 0.5) * 0.5
    opatr = volna - (OBL + HO0)
    if opatr >= 0:
        HOfin_hod = HOhod
    elif (HO0 + opatr) > 0:
        HOfin_hod = _lm_fl((HO0 + opatr) / Q, 1) if Q else 0.0
    else:
        HOfin_hod = 0.0
    HO = HOfin_hod * Q
    benefits = OBL + HO
    BO = -benefits
    BR = podil * V
    BS = (BO + BR) if BO < 0 else BR
    BT = (BS / podil) if (BO < 0 and podil) else V
    BV = BT if BT < 0 else 0.0
    korekce = _lm_rd((BT - V) - BV)
    return _lm_rd(OBL), _lm_rd(HO), korekce


def _mzdy_benefity_apply(prows, firma, rok, mesic):
    """Landmark náhrady (OBL 794 + HO 795) + korekce os. ohodnocení (432).
    Vstupy z att_entry (docházkové zrcadlo .188): odpracované dny + absence; fond z úvazku.
    Ověřená matematika _lm_engine (Excel 45/45). Loajalita (651) se řeší zvlášť."""
    import calendar as _cal
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    fkod = '1' if str(firma).upper() in ('EC', '1') else '2'
    fk_sm = 'EC' if fkod == '1' else 'ES'
    ry = int(rok); rm = int(mesic)
    ld = _cal.monthrange(ry, rm)[1]
    workdays = sum(1 for x in range(1, ld + 1) if _cal.weekday(ry, rm, x) < 5)  # Po–Pá
    s = _g()
    try:
        skup24 = set(int(r[0]) for r in s.execute(_t(
            "SELECT uk.user_id FROM tenant.att_user_kategorie uk "
            "JOIN tenant.att_kategorie k ON k.id=uk.kategorie_id "
            "WHERE k.tenant_id=2 AND k.dopichavat_fond=true AND k.aktivni=true")).fetchall())
        _pstart = "%04d-%02d-01" % (ry, rm)
        _pend = "%04d-%02d-%02d" % (ry, rm, ld)
        emp = {}
        for r in s.execute(_t(
            "SELECT sm.helios_cislo, sm.user_id, COALESCE(ge.uvazek_tyden_h,40) "
            "FROM tenant.user_smlouva sm "
            "LEFT JOIN tenant.att_employee e ON e.tenant_id=2 AND e.user_id=sm.user_id "
            "LEFT JOIN LATERAL (SELECT g.uvazek_tyden_h FROM tenant.engagement g "
            "  WHERE g.employee_id=e.id "
            "    AND (g.valid_from IS NULL OR g.valid_from <= CAST(:pend AS date)) "
            "    AND (g.valid_to IS NULL OR g.valid_to >= CAST(:pstart AS date)) "
            "  ORDER BY (g.valid_from IS NULL) ASC, g.valid_from DESC NULLS LAST, g.is_current DESC "
            "  LIMIT 1) ge ON true "
            "WHERE sm.tenant_id=2 AND sm.firma=:fk AND LOWER(COALESCE(sm.typ_smlouvy,''))='hpp' "  # nahrady JEN HPP; uvazek dle platnosti vymeru k mesici (Peta 8.7.2026)
            "  AND sm.helios_cislo IS NOT NULL"),
                {"fk": fk_sm, "pstart": _pstart, "pend": _pend}).fetchall():
            try:
                emp[int(r[0])] = (int(r[1]), float(r[2] or 40) / 5.0)
            except Exception:
                pass
        probace = set()  # zkusebni doba -> Landmark az PO ni (Peta 8.7.2026)
        _od0 = "%04d-%02d-01" % (ry, rm)
        for r in s.execute(_t(
            "SELECT sm.helios_cislo FROM tenant.user_smlouva sm "
            "JOIN tenant.att_employee e ON e.tenant_id=2 AND e.user_id=sm.user_id "
            "JOIN tenant.engagement g ON g.employee_id=e.id AND g.is_current=true "
            "WHERE sm.tenant_id=2 AND sm.firma=:fk AND sm.helios_cislo IS NOT NULL "
            "  AND g.zkusebni_do IS NOT NULL AND g.zkusebni_do >= CAST(:d0 AS date)"),
                {"fk": fk_sm, "d0": _od0}).fetchall():
            try:
                probace.add(int(r[0]))
            except Exception:
                pass
        ho_dny_by = {}; obl_off = set()
        for r in s.execute(_t(
            "SELECT cislo, COALESCE(ho_dny,0), COALESCE(obl_on,true) "
            "FROM tenant.benefit_volba WHERE tenant_id=2 AND firma=:f AND rok=:y AND mesic=:mo"),
                {"f": fkod, "y": ry, "mo": rm}).fetchall():
            try:
                c = int(r[0]); ho_dny_by[c] = int(r[1] or 0)
                if not bool(r[2]):
                    obl_off.add(c)
            except Exception:
                pass
        # odpracované dny (>4 h) — autoritativní z att_entry (jako stará verze)
        days_by = {}
        for r in s.execute(_t(
            "SELECT e.cislo_zam, COUNT(DISTINCT d.entry_date) FROM "
            "(SELECT a.employee_id, a.entry_date FROM tenant.att_entry a "
            " JOIN tenant.att_entry_type et ON et.id=a.entry_type_id "
            " WHERE et.code IN ('work','homeoffice','fond_doplneni') "
            "   AND EXTRACT(year FROM a.entry_date)=:y AND EXTRACT(month FROM a.entry_date)=:mo "
            " GROUP BY a.employee_id, a.entry_date HAVING SUM(a.hours)>4) d "
            "JOIN tenant.att_employee e ON e.id=d.employee_id WHERE e.tenant_id=2 GROUP BY e.cislo_zam"),
                {"y": ry, "mo": rm}).fetchall():
            try:
                days_by[int(r[0])] = int(r[1] or 0)
            except Exception:
                pass
        # absence HODINY cinnostne z att_day_summary (cte DruhCinnosti) — dovolena, lekar, nemoc, OCR, materska.
        # Cinnostni zdroj jako stravenky (NE att_entry, kde rezie schova absenci). Montaz = pritomnost. (Peta 8.7.2026)
        abs_by = {}
        for r in s.execute(_t(
            "SELECT cislo_zam, COALESCE(SUM(COALESCE(cas_dovolena,0)+COALESCE(cas_lekar,0)"
            "+COALESCE(cas_nemoc,0)+COALESCE(cas_ocr,0)+COALESCE(cas_materska,0)),0) "
            "FROM tenant.att_day_summary "
            "WHERE tenant_id=2 AND rok=:y AND mesic=:mo "
            "GROUP BY cislo_zam"), {"y": ry, "mo": rm}).fetchall():
            try:
                abs_by[int(r[0])] = float(r[1] or 0)
            except Exception:
                pass
    finally:
        s.close()
    if not emp:
        return prows
    osoh_by = {}
    for row in prows:
        if int(row[1]) == _POHYB_MS:
            osoh_by[int(row[0])] = float(row[2] or 0)
    add = []
    new_pohyb = {}
    for cislo, (user_id, daily_h) in emp.items():
        wd = days_by.get(cislo, 0)
        if wd <= 0:
            continue
        if cislo in probace:            # zkusebni doba -> bez Landmark nahrad (Peta 8.7.2026)
            continue
        if daily_h < 6:                 # denni uvazek < 6 h -> bez naroku (Peta 8.7.2026)
            continue
        fond = daily_h * workdays
        absh = abs_by.get(cislo, 0.0)
        # Landmark (ES Excel, radek Dvorakova): OBL = ROUND(F x sazba), F = Pocet odpracovanych dnu =
        # (fond - absence)/uvazek BEZ zaokrouhleni. Puldenni hodnoty (21,5) v Excelu vznikaji jen proto,
        # ze absence byva cely den; kdo ma castecnou absenci (napr. lekar 5h z 6h dne) ma F zlomkove
        # (Dvorakova 21,1667 -> OBL=ROUND(21,1667*109)=2307). Zaokrouhluje se az OBL na cele Kc.
        # HO a korekce se krati podilem odprac/fond z RAW hodin. (Peta 8.7.2026)
        obl_dny = ((fond - absh) / daily_h) if daily_h else 0.0
        odprac = fond - absh
        if fond <= 0 or odprac <= 0:
            continue
        V = osoh_by.get(cislo, 0.0)
        is_office = user_id in skup24
        obl_sazba = _OBL_SAZBA_KANCELAR if is_office else _OBL_SAZBA_DILNA
        obl_sazba_eff = 0.0 if cislo in obl_off else obl_sazba
        ho_elig = (is_office or ((fkod, cislo) in _HO_DILNA_VYJIMKA)) and (fkod, cislo) not in _HO_BEZ_NAROKU
        # HO „na pevno" (Peta 7.7.2026): kdo má nárok na home office (kancelář + výjimky dílna),
        # má pevně 6 HO dnů — nezávisle na self-service volbě (benefit_volba). Kdo nárok nemá, HO nedostává.
        # (Engine si to pak stejně poměrově zkrátí podle odpracovaného fondu.)
        _HO_DNY_NAPEVNO = 6
        ho_hod_narok = (_HO_DNY_NAPEVNO * daily_h) if ho_elig else 0.0
        obl, ho, korekce = _lm_engine(fond, odprac, obl_dny, obl_sazba_eff, ho_hod_narok, V)
        if obl > 0:
            add.append((cislo, _OBL_MS, int(obl), 0))
        if ho > 0:
            ho_dny_pay = int(round(ho / (_HO_HOD_SAZBA * daily_h))) if daily_h else 0
            add.append((cislo, _HO_MS, int(ho), ho_dny_pay))
        if korekce != 0 and cislo in osoh_by:
            new_pohyb[cislo] = int(round(V + korekce))
    out = []
    for row in prows:
        c = int(row[0])
        if int(row[1]) == _POHYB_MS and c in new_pohyb:
            out.append((c, _POHYB_MS, new_pohyb[c], 0))
        else:
            out.append(row)
    out.extend(add)
    return out


# ── Loajalita (přesčas u výroby) → složka 651 (prémie). Marti/Peta 3.7.2026 ────────────────
#  loajalita = (celkem odpracováno − fond z úvazku) × HodSazbaPrescas × 1,25, JEN výroba (ne skup24).
#  Celkem = tenant.att_day_summary.cas_celkem (Helios podklad, přezrcadleno @@DOCHSUM — dovolená
#  se počítá jako 8 h a vyplňuje fond, takže „celkem − fond" = skutečný přesčas, žádné zdvojení).
#  Sazba = poslední platná HodSazbaPrescas z EC_Mzdy_SumaMesic (.188). Strop koeficientu 1,25.
_LOAJALITA_KOEF = 1.25


def _mzdy_loajalita_rows(firma, rok, mesic):
    """Vrací řádky (cislo, 651, koruny, 0) pro loajalitu výrobních (přesčas nad fond).
    Přičítá se do složky 651 (prémie). Kancelář (skup24) loajalitu nemá."""
    import calendar as _cal
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    fk_sm = 'EC' if str(firma).upper() in ('EC', '1') else 'ES'
    ry = int(rok); rm = int(mesic)
    ld = _cal.monthrange(ry, rm)[1]
    workdays = sum(1 for x in range(1, ld + 1) if _cal.weekday(ry, rm, x) < 5)
    s = _g()
    try:
        skup24 = set(int(r[0]) for r in s.execute(_t(
            "SELECT uk.user_id FROM tenant.att_user_kategorie uk "
            "JOIN tenant.att_kategorie k ON k.id=uk.kategorie_id "
            "WHERE k.tenant_id=2 AND k.dopichavat_fond=true AND k.aktivni=true")).fetchall())
        _pstart = "%04d-%02d-01" % (ry, rm)
        _pend = "%04d-%02d-%02d" % (ry, rm, ld)
        emp = {}
        for r in s.execute(_t(
            "SELECT sm.helios_cislo, sm.user_id, COALESCE(ge.uvazek_tyden_h,40) "
            "FROM tenant.user_smlouva sm "
            "LEFT JOIN tenant.att_employee e ON e.tenant_id=2 AND e.user_id=sm.user_id "
            "LEFT JOIN LATERAL (SELECT g.uvazek_tyden_h FROM tenant.engagement g "
            "  WHERE g.employee_id=e.id "
            "    AND (g.valid_from IS NULL OR g.valid_from <= CAST(:pend AS date)) "
            "    AND (g.valid_to IS NULL OR g.valid_to >= CAST(:pstart AS date)) "
            "  ORDER BY (g.valid_from IS NULL) ASC, g.valid_from DESC NULLS LAST, g.is_current DESC "
            "  LIMIT 1) ge ON true "
            "WHERE sm.tenant_id=2 AND sm.firma=:fk AND COALESCE(sm.typ_smlouvy,'')<>'osvc' "  # uvazek dle platnosti vymeru k mesici (Peta 8.7.2026)
            "  AND sm.helios_cislo IS NOT NULL"),
                {"fk": fk_sm, "pstart": _pstart, "pend": _pend}).fetchall():
            try:
                emp[int(r[0])] = (int(r[1]), float(r[2] or 40) / 5.0)
            except Exception:
                pass
        celkem = {}
        for r in s.execute(_t(
            "SELECT cislo_zam, COALESCE(SUM(cas_celkem),0) FROM tenant.att_day_summary "
            "WHERE tenant_id=2 AND rok=:y AND mesic=:mo GROUP BY cislo_zam"),
                {"y": ry, "mo": rm}).fetchall():
            try:
                celkem[int(r[0])] = float(r[1] or 0)
            except Exception:
                pass
    finally:
        s.close()
    if not emp:
        return []
    sazba = {}
    try:
        rr = _mssql188_query(
            "SELECT s.CisloZam, s.HodSazbaPrescas FROM UCTO_EC.dbo.EC_Mzdy_SumaMesic s "
            "JOIN (SELECT CisloZam, MAX(Rok*100+Mesic) mx FROM UCTO_EC.dbo.EC_Mzdy_SumaMesic "
            "      WHERE HodSazbaPrescas>0 GROUP BY CisloZam) t "
            "  ON t.CisloZam=s.CisloZam AND (s.Rok*100+s.Mesic)=t.mx")
        for v in (rr.get("rows") or []):
            try:
                sazba[int(v[0])] = float(v[1] or 0)
            except Exception:
                pass
    except Exception:
        return []
    out = []
    for cislo, (user_id, daily_h) in emp.items():
        if user_id in skup24:
            continue
        c = celkem.get(cislo)
        if c is None:
            continue
        fond = daily_h * workdays
        prescas = c - fond
        if prescas <= 0.05:
            continue
        sz = sazba.get(cislo, 0.0)
        if sz <= 0:
            continue
        loaj = int(round(prescas * sz * _LOAJALITA_KOEF))
        if loaj > 0:
            out.append((cislo, 651, loaj, 0))
    return out


