# ── Odměny z Centrály (DPP typ 1/3 → 700, jednatel typ 17 → 693) → mzda. Peta 7.7.2026 ──────
#  Zdroj = tenant.att_odmena_centrala (zrcadlo EC_FinPriplatkySrazkyDefinice, plněno při @@DOCHSUM).
#  Routing firmy přes user_smlouva (helios_cislo→firma), takže EC i ES dostane jen své lidi.
#  Pozor na dvojí započtení: pokud má člověk odměnu i ručně (mzdy_rucni_slozka), sečte se —
#  proto ruční složku u lidí, co jedou z Centrály, deaktivovat.
def _mzdy_odmeny_rows(firma, rok, mesic):
    """Vrací řádky (cislo, cislo_ms, koruny, 0) pro odměny z Centrály (att_odmena_centrala),
    filtrované na danou firmu přes user_smlouva. DPP→700, jednatel→693."""
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    fk_sm = 'EC' if str(firma).upper() in ('EC', '1') else 'ES'
    ry = int(rok); rm = int(mesic)
    s = _g()
    out = []
    try:
        rows = []
        try:
            rows = s.execute(_t(
                "SELECT o.cislo_zam, o.cislo_ms, COALESCE(SUM(o.castka),0) "
                "FROM tenant.att_odmena_centrala o "
                "JOIN tenant.user_smlouva sm ON sm.tenant_id=2 "
                "  AND sm.helios_cislo::text=o.cislo_zam AND sm.firma=:fk "
                "WHERE o.tenant_id=2 AND o.rok=:y AND o.mesic=:mo "
                "GROUP BY o.cislo_zam, o.cislo_ms"),
                {"fk": fk_sm, "y": ry, "mo": rm}).fetchall()
        except Exception:
            s.rollback()  # tabulka ještě neexistuje (před prvním @@DOCHSUM) → prázdné
            rows = []
        for r in rows:
            try:
                c = int(r[0]); ms = int(r[1]); kc = int(round(float(r[2] or 0)))
            except Exception:
                continue
            if kc != 0:
                out.append((c, ms, kc, 0))
    finally:
        s.close()
    return out


# Generické příplatky/srážky (Marti 28.6.) — z wage_movement (mirror EC_FinPriplatkySrazkyDefinice)
# do mzdy přes vlastní Helios CisloMS. Autoritativní mapa = EC číselník (MzdovaSlozka+ReakceMzdy),
# zrcadlená v wage_system_mapping. VYJMA HO/OBL/korekce (typy 10/30/40 = ReakceMzdy False → benefit systém).
# Pojistka proti dvojímu započtení = NÁŠ ledger závazků tenant.zamestnanecky_zavazek (kanál 'mzda',
# stav otevreno→v_mzde→vyplaceno; čistá voda per období, 'vyplaceno' se nepřemazává), NEsaháme do EC
# příznaků (Přeneseno/DatVyplaceni). Závazek vůči zaměstnanci drží v saldu do vyplacení (Marti). Ledger
# unese i kanály faktura/objednávka (OSVČ, na více firem) — to později; teď jen kanál mzda.
def _mzdy_priplatky_rows(firma, rok, mesic, only_cislo=None):
    # only_cislo = přegenerování JEN jednoho člověka: výběr i čistá voda ledgeru se omezí
    # na jeho číslo, aby se závazky ostatních (v_mzde) nepřepsaly.
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    fkod = '1' if str(firma).upper() in ('EC', '1') else '2'
    fec = 'EC' if str(firma).upper() in ('EC', '1') else 'ES'  # company.code = 'EC'/'ES'
    oc = None
    if only_cislo is not None:
        try:
            oc = int(str(only_cislo).strip())
        except Exception:
            oc = None
    s = _g()
    try:
        # Výběr dle EC logiky (EC_Mzdy_PrepocetMesicZam): Schvaleno + platnost bracketing období,
        # ne period_month (is_recurring v mirroru není spolehlivé). konec měsíce = make_date(y,mo,1)+1měsíc-1den.
        sel_params = {"fec": fec, "y": rok, "mo": mesic}
        sel_filter = ""
        if oc is not None:
            sel_filter = "  AND ae.cislo_zam = :oc "
            sel_params["oc"] = str(oc)
        rows = s.execute(_t(
            "SELECT ae.cislo_zam AS cislo, msm.ext_code AS cislo_ms, wm.import_src_id AS ecid, "
            "  COALESCE(wm.amount, wm.hours*wm.rate, 0) AS castka, wm.zakazka_ref AS zak, wct.code AS kod "
            "FROM tenant.wage_movement wm "
            "JOIN tenant.engagement e ON e.id=wm.engagement_id "
            "JOIN tenant.company c ON c.id=e.company_id AND c.code=:fec "
            "JOIN tenant.att_employee ae ON ae.id=e.employee_id AND ae.cislo_zam ~ '^[0-9]+$' "
            "JOIN tenant.wage_component_type wct ON wct.id=wm.movement_type_id "
            "JOIN tenant.wage_system_mapping msm ON msm.movement_type_id=wct.id "
            "  AND msm.ext_system_code='HELIOS' AND COALESCE(msm.active,true) "
            "WHERE wm.tenant_id=2 AND wm.status IN ('approved','exported') "
            # VYJMA: HO/OBL/korekce (benefit systém). srazka_telefon už NEvyjímáme —
            # promítá se jako srážka do složky 953 (znaménko otočíme níž). Peta 7.7.2026.
            "  AND wct.code NOT IN ('nahrada_home_office','nahrada_obleceni','korekce_os_ohod') "
            + sel_filter +
            "  AND wm.valid_from <= (make_date(:y,:mo,1) + INTERVAL '1 month' - INTERVAL '1 day') "
            "  AND (wm.valid_to IS NULL OR wm.valid_to >= make_date(:y,:mo,1))"),
            sel_params).fetchall()
        # čistá voda: smaž alokace ZÁVAZKŮ do mzdy za období+firma (re-run při ladění); 'vyplaceno' nech být.
        # Při only_cislo se omezí jen na jeho číslo (ostatních se nedotkne).
        del_params = {"f": fkod, "y": rok, "mo": mesic}
        del_filter = ""
        if oc is not None:
            del_filter = " AND cislo=:oc"
            del_params["oc"] = oc
        s.execute(_t("DELETE FROM tenant.zamestnanecky_zavazek WHERE tenant_id=2 AND zdroj='EC_PRIPL' "
                     "AND firma=:f AND rok=:y AND mesic=:mo AND kanal='mzda' AND stav<>'vyplaceno'" + del_filter),
                  del_params)
        agg = {}
        for r in rows:
            try:
                cislo = int(str(r[0]).strip()); ms = int(r[1]); ecid = r[2]
                kc = float(r[3] or 0); zak = r[4]; kod = r[5]
            except Exception:
                continue
            if not kc:
                continue
            # Telefonní tarif (srazka_telefon): zdroj je záporný (−254), ale Helios srážku do
            # složky 953 chce KLADNĚ a odečte ji sám dle typu složky. Otočíme znaménko. Peta 7.7.2026.
            if kod == 'srazka_telefon':
                kc = -kc
            agg[(cislo, ms)] = agg.get((cislo, ms), 0) + kc
            s.execute(_t(
                "INSERT INTO tenant.zamestnanecky_zavazek (firma, cislo, rok, mesic, zdroj, zdroj_id, "
                " kanal, cilova_firma, cislo_ms, zakazka_ref, castka, stav) "
                "VALUES (:f,:c,:y,:mo,'EC_PRIPL',:zid,'mzda',:f,:ms,:zak,:kc,'v_mzde') "
                "ON CONFLICT (tenant_id, zdroj, zdroj_id, rok, mesic, kanal, cilova_firma) "
                "DO UPDATE SET castka=EXCLUDED.castka, cislo_ms=EXCLUDED.cislo_ms, stav='v_mzde', updated_at=now()"),
                {"f": fkod, "c": cislo, "y": rok, "mo": mesic,
                 "zid": (int(ecid) if ecid else None), "ms": ms,
                 "zak": (str(zak)[:40] if zak else None), "kc": kc})
        s.commit()
        return [(c, ms, int(round(v)), 0) for (c, ms), v in agg.items()]
    finally:
        s.close()


# Mapování naší absence (att_entry.code) -> Helios mzdová složka (TabPredzp.CisloMS).
# Ověřeno z reálných EC 2025 dat. sickday=odpracovaný den (Marti 30.6., neposíláme),
# osvc_absence + volno navíc 70% mimo Helios (vlastní výpočet).
_ABS_CODE_TO_MS = {"vacation": 211, "medical": 243, "sick": 200,
                   "family_care": 251, "unpaid": 246, "maternity": 255}


def _mzdy_absence_rows(firma, rok, mesic):
    """Absence z NAŠÍ docházky (att_entry) -> předzpracování Helios. KLÍČOVÁNÍ PŘES
    tenant.user_smlouva (Marti 30.6.2026): absence agreguje per USER, firemní číslo =
    user_smlouva.helios_cislo pro DANOU firmu (kde běží mzda 2026, bez kolizí), OSVČ
    (typ='osvc') VEN. Náhrady nepočítáme — Dny+Hodiny do MS, Helios dopočítá z průměru.
    Vrací (cislo, ms, koruny=0, dny, hodiny) NEBO u lékaře/OČR
    (cislo, ms, 0, dny, hodiny, datum_od, datum_do).

    Kristý 8.7.2026: LÉKAŘ (243) + OČR (251) potřebují v Heliosu OBDOBÍ (DatumOd/DatumDo),
    jinak se NEkrátí základ (na rozdíl od dovolené). Generujeme je jako SOUVISLÁ OBDOBÍ —
    navazující dny (mezera jen přes víkend = pořád jedno období) v jednom řádku, nenavazující
    úsek = další řádek. NEMOCENSKÁ (sick/200) jede stejně jako lékař/OČR — souvislé období
    s DatumOd/DatumDo (kvůli krácení základu); rozhodnutí DNP dopisuje účetní ručně. Kristý 8.7.2026."""
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    fkod = "EC" if str(firma).upper() in ("EC", "1") else "ES"
    # Jednatelé (odměna 693, bez mzdového základu) VEN z absence — Helios neumí spočítat
    # náhradu bez základu → výpočet padá. Detekce: aktivní ruční složka 693.
    _jedn = ("   AND NOT EXISTS (SELECT 1 FROM tenant.mzdy_rucni_slozka jd WHERE jd.tenant_id=2 "
             "        AND jd.firma=:f AND jd.cislo_ms=693 AND COALESCE(jd.aktivni,true)=true "
             "        AND jd.cislo=sm.helios_cislo::text) ")
    _join = ("FROM tenant.att_entry a "
             "JOIN tenant.att_entry_type et ON et.id=a.entry_type_id AND et.category='absence' "
             "JOIN tenant.att_employee e ON e.id=a.employee_id "
             "JOIN tenant.user_smlouva sm ON sm.user_id=e.user_id AND sm.tenant_id=2 "
             "   AND sm.firma=:f AND sm.typ_smlouvy<>'osvc' AND sm.helios_cislo IS NOT NULL " + _jedn +
             "WHERE a.tenant_id=2 "
             "  AND EXTRACT(year FROM a.entry_date)=:y AND EXTRACT(month FROM a.entry_date)=:mo ")
    s = _g()
    out = []
    try:
        # (A) agregát bez období — dovolená/neplacené/mateřská.
        # DOVOLENÁ (211) HODINY cinnostne z att_day_summary (cas_dovolena) — stejny zdroj jako
        # nahrady/stravenky; att_entry obcas hodi "ocasek" (napr. Bernardova 30.6. 3,38 vs cinnostne 3,20).
        # Dny + neplacene/materska zustavaji z att_entry. (Peta 8.7.2026)
        _ads_dov = {}
        for r in s.execute(_t(
            "SELECT cislo_zam, COALESCE(SUM(COALESCE(cas_dovolena,0)),0) FROM tenant.att_day_summary "
            "WHERE tenant_id=2 AND rok=:y AND mesic=:mo GROUP BY cislo_zam"),
                {"y": rok, "mo": mesic}).fetchall():
            try:
                _ads_dov[int(str(r[0]).strip())] = float(r[1] or 0)
            except Exception:
                pass
        rows = s.execute(_t(
            "SELECT sm.helios_cislo AS cislo, et.code AS code, "
            "  COUNT(DISTINCT a.entry_date) AS dny, COALESCE(SUM(a.hours),0) AS hod " + _join +
            "  AND et.code IN ('vacation','unpaid','maternity') "
            "GROUP BY sm.helios_cislo, et.code"), {"f": fkod, "y": rok, "mo": mesic}).fetchall()
        for r in rows:
            try:
                cislo = int(str(r[0]).strip()); ms = _ABS_CODE_TO_MS.get(r[1])
                dny = float(r[2] or 0); hod = float(r[3] or 0)
            except Exception:
                continue
            if r[1] == 'vacation' and _ads_dov.get(cislo, 0) > 0:  # dovolena cinnostne (ADS), ne att_entry (Peta 8.7.2026)
                hod = _ads_dov[cislo]
            if not ms or (dny <= 0 and hod <= 0):
                continue
            out.append((cislo, ms, 0, int(round(dny)), round(hod, 2)))
        # (B) lékař + OČR + NEMOCENSKÁ — SOUVISLÁ OBDOBÍ do JEDNOHO řádku s DatumOd/DatumDo
        # (Helios kvůli krácení základu potřebuje období). Navazující dny (mezera jen přes víkend)
        # = jedno období; nenavazující úsek = další řádek. DNP u nemocenské řeší účetní. Kristý 8.7.2026.
        import datetime as _dt
        drows = s.execute(_t(
            "SELECT sm.helios_cislo AS cislo, et.code AS code, a.entry_date AS den, "
            "  COALESCE(SUM(a.hours),0) AS hod " + _join +
            "  AND et.code IN ('medical','family_care','sick') "
            "GROUP BY sm.helios_cislo, et.code, a.entry_date"), {"f": fkod, "y": rok, "mo": mesic}).fetchall()
        by_key = {}
        for r in drows:
            try:
                cislo = int(str(r[0]).strip()); ms = _ABS_CODE_TO_MS.get(r[1])
                den = r[2]; hod = float(r[3] or 0)
            except Exception:
                continue
            if not ms or hod <= 0 or not den:
                continue
            by_key.setdefault((cislo, ms), []).append((den, hod))
        for (cislo, ms), items in by_key.items():
            items.sort(key=lambda x: x[0])
            p_od = p_do = None; p_hod = 0.0; p_dny = 0
            for den, hod in items:
                if p_od is None:
                    p_od = p_do = den; p_hod = hod; p_dny = 1
                    continue
                # navazuje na běžící období? (mezi p_do a den jsou jen víkendové dny)
                nav = den > p_do
                if nav:
                    d = p_do + _dt.timedelta(days=1)
                    while d < den:
                        if d.weekday() < 5:  # chybí pracovní den → nenavazuje
                            nav = False
                            break
                        d += _dt.timedelta(days=1)
                if nav:
                    p_do = den; p_hod += hod; p_dny += 1
                else:
                    out.append((cislo, ms, 0, p_dny, round(p_hod, 2), p_od.isoformat(), p_do.isoformat()))
                    p_od = p_do = den; p_hod = hod; p_dny = 1
            if p_od is not None:
                out.append((cislo, ms, 0, p_dny, round(p_hod, 2), p_od.isoformat(), p_do.isoformat()))
        return out
    finally:
        s.close()


def _mzdy_consolidate(prows):
    """Sečte koruny + dny + hodiny per (cislo, cislo_ms) — víc zdrojů do jedné Helios složky
    (např. 651 ze snapshotu premie/vedení + příplatků odměny). 5. prvek = hodiny (absence).
    Řádky S OBDOBÍM (7-tuple s datum_od = lékař/OČR) NEKONSOLIDUJEME — každé období/den má
    vlastní řádek s vlastním DatumOd/DatumDo (Kristý 8.7.2026)."""
    agg = {}
    order = []
    dated = []
    for row in prows:
        if len(row) >= 7 and row[5]:  # má DatumOd → propustit beze změny (nekonsolidovat)
            dated.append(tuple(row))
            continue
        try:
            c = int(row[0]); ms = int(row[1]); kc = int(row[2] or 0)
            dny = int(row[3] if len(row) > 3 else 0)
            hod = float(row[4]) if len(row) > 4 else 0.0
        except Exception:
            continue
        if (c, ms) not in agg:
            agg[(c, ms)] = [0, 0, 0.0]
            order.append((c, ms))
        agg[(c, ms)][0] += kc
        agg[(c, ms)][1] += dny
        agg[(c, ms)][2] += hod
    return [(c, ms, agg[(c, ms)][0], agg[(c, ms)][1], round(agg[(c, ms)][2], 2)) for (c, ms) in order] + dated


def _mzdy_predzprac_apply(cloud_db, idobd, rows, only_zid=None):
    """Zapíše předzpracování PER-ŘÁDEK přes 3-part jména (bez USE/temp/cursor) — spolehlivé
    přes API _mssql188_query a trigger-safe (single-row INSERT projde Helios triggerem).
    rows=(cislo,cislo_ms,koruny[,dny,hodiny[,datum_od,datum_do]]). Když řádek nese datum_od/datum_do
    (lékař/OČR), plníme i DatumOd/DatumDo/DochazkaOd/DochazkaDo (Helios pak ponížil základ).
    Pevná 1 i na kartu. Vrací None=OK / chybový string.
    only_zid = přegenerování JEN jednoho člověka: čistá voda předzpracování se omezí na jeho
    ZamestnanecId, aby se STRATEGIE řádky ostatních nesmazaly."""
    o = str(int(idobd))
    nr = _mssql188_query("SELECT Cislo, ID FROM " + cloud_db + ".dbo.TabCisZam")
    if not nr.get("ok"):
        return "TabCisZam: " + str(nr.get("error"))
    id_by_cislo = {}
    for v in nr.get("rows") or []:
        try:
            id_by_cislo[int(v[0])] = int(v[1])
        except Exception:
            pass
    # JEN lidé s mzdovým masterem období (TabZamMzd) = zaměstnanci s pracovním poměrem.
    # Vylučuje OSVČ/subdodavatele (Voříšek, Havlát…), kteří mají jen docházku/mzdovou podmínku,
    # ale NE mzdový master → jinak vznikne orphan TabPredzp a padne FK TabPredzp→TabZamMzd
    # (pád Heliosu 7.7.2026). Marti 7.7.2026: "ověř, jsou to opravdu jen zaměstnanci, ne OSVČ".
    _mr = _mssql188_query("SELECT ZamestnanecId FROM " + cloud_db + ".dbo.TabZamMzd WHERE IdObdobi=" + o)
    masters = set()
    for v in (_mr.get("rows") or []):
        try:
            masters.add(int(v[0]))
        except Exception:
            pass
    del_sql = "DELETE FROM " + cloud_db + ".dbo.TabPredzp WHERE IdObdobi=" + o + " AND Autor='STRATEGIE'"
    if only_zid:
        del_sql += " AND ZamestnanecId=" + str(int(only_zid))
    dw = _mssql188_query(del_sql)
    if not dw.get("ok"):
        return "DELETE: " + str(dw.get("error"))
    stmts, kart = [], []
    for row in rows:
        c, ms, kc = row[0], row[1], row[2]
        dny = row[3] if len(row) > 3 else 0
        hod = float(row[4]) if len(row) > 4 else 0.0
        dod = row[5] if len(row) > 5 else None  # DatumOd (lékař/OČR — kvůli krácení základu)
        ddo = row[6] if len(row) > 6 else None  # DatumDo
        zid = id_by_cislo.get(int(c))
        if not zid or zid not in masters or (not kc and not dny and not hod):  # jen zaměstnanci s masterem; absence = Dny+Hodiny (náhradu dopočítá Helios)
            continue
        if dod and ddo:
            # docházková absence s OBDOBÍM (lékař/OČR) → plníme DatumOd/DatumDo + DochazkaOd/DochazkaDo,
            # aby Helios ponížil základ a spočítal správnou mzdu i před ručním DNP účetní. Kristý 8.7.2026.
            stmts.append("INSERT " + cloud_db + ".dbo.TabPredzp(IdObdobi,ZamestnanecId,CisloMS,Hodiny,Dny,Koruny,DatumOd,DatumDo,DochazkaOd,DochazkaDo,Sazba,Autor,DatPorizeni) "
                         "VALUES(%s,%d,%d,%.2f,%d,%d,'%s','%s','%s','%s',0,'STRATEGIE',GETDATE());"
                         % (o, zid, int(ms), float(hod or 0), int(dny or 0), int(kc), dod, ddo, dod, ddo))
        else:
            stmts.append("INSERT " + cloud_db + ".dbo.TabPredzp(IdObdobi,ZamestnanecId,CisloMS,Hodiny,Dny,Koruny,Sazba,Autor,DatPorizeni) "
                         "VALUES(%s,%d,%d,%.2f,%d,%d,0,'STRATEGIE',GETDATE());" % (o, zid, int(ms), float(hod or 0), int(dny or 0), int(kc)))
        if int(ms) == 1:
            kart.append("UPDATE " + cloud_db + ".dbo.TabZamMzd SET ZakladniPlat=%d WHERE ZamestnanecId=%d AND IdObdobi=%s;" % (int(kc), zid, o))
    allstmts = stmts + kart
    for i in range(0, len(allstmts), 25):
        rw = _mssql188_query("SET NOCOUNT ON;\n" + "\n".join(allstmts[i:i + 25]) + "\nSELECT 1 AS done;")
        if not rw.get("ok"):
            err = str(rw.get("error"))
            if "HY007" not in err:  # HY007 = pyodbc fetch nad bez-result batchem, DML ale proběhl
                return "INSERT chunk %d: %s" % (i, err)
    return None


def _mzdy_status_check(rok, mesic):
    """Monitor výplatnic (Marti 28.6.2026): co je potřeba dořešit v Heliosu.
    (a) Helios Status != 1 (nespočítáno čistě). (b) Absence v NAŠEM registru (OČR/nemoc)
    bez odpovídající dávky na pásce (ošetřovné 205 / nemocenská 203) → 'doplnit dávky'.
    Vrací seznam k řešení (firma, číslo, jméno, problém, detail)."""
    import datetime as _dt
    import calendar as _cal
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    m_first = _dt.date(int(rok), int(mesic), 1)
    m_last = _dt.date(int(rok), int(mesic), _cal.monthrange(int(rok), int(mesic))[1])
    today = _dt.date.today()
    out = []
    for firma in ("EC", "ES"):
        try:
            _src, cdb = _zrc_dbs(firma)
            ro = _mssql188_query("SELECT IdObdobi FROM " + cdb + ".dbo.TabMzdObd WHERE Rok=%d AND Mesic=%d"
                                 % (int(rok), int(mesic)))
            if not (ro.get("ok") and ro.get("rows")):
                continue
            idobd = int(ro["rows"][0][0])
            st = _mssql188_query(
                "SELECT c.Cislo, RTRIM(c.Prijmeni)+' '+RTRIM(ISNULL(c.Jmeno,'')), v.Status, v.Info "
                "FROM " + cdb + ".dbo.TabZamVyp v JOIN " + cdb + ".dbo.TabCisZam c ON c.ID=v.ZamestnanecId "
                "WHERE v.IdObdobi=%d AND ISNULL(v.Status,0)<>1" % idobd)
            for r in (st.get("rows") or []):
                out.append({"firma": firma, "cislo": r[0], "jmeno": (r[1] or "").strip(),
                            "problem": "status", "detail": "Helios status %s (Info %s)" % (r[2], r[3])})
            # nemoc: prvních 14 dní = náhrada zaměstnavatele (213/106/882), od 15. dne ČSSZ (203);
            # docházkové 200/201 taky beru jako "řešeno". OČR = ošetřovné 205 (+201 docházka).
            # POZOR: 200/201 jsou NAŠE docházkové markery (krmíme je z předzpracování) — NEpočítají
            # se jako „dávka". Skutečná dávka = ošetřovné 205 / náhrada nemoci 213,106,882 / ČSSZ 203.
            for tbl, ms_in, label in (("att_ocr_case", "205", "ošetřovné"),
                                      ("att_sick_case", "203,213,882,106", "nemocenská/náhrada")):
                cm, s = _att_session()
                try:
                    cases = s.execute(_t(
                        "SELECT DISTINCT e.cislo_zam FROM tenant." + tbl + " c "
                        "JOIN tenant.att_employee e ON e.id=c.employee_id "
                        "WHERE c.tenant_id=2 AND c.company=:f "
                        "  AND COALESCE(c.stav,'') NOT IN ('zruseno','zamitnuto') "
                        "  AND c.datum_od <= :ml AND COALESCE(c.datum_do, :tod) >= :mf"),
                        {"f": firma, "ml": m_last, "mf": m_first, "tod": today}).fetchall()
                finally:
                    cm.__exit__(None, None, None)
                for cr in cases:
                    try:
                        cislo = int(str(cr[0]).strip())
                    except Exception:
                        continue
                    chk = _mssql188_query(
                        "SELECT COUNT(*) FROM " + cdb + ".dbo.TabMzSloz m "
                        "JOIN " + cdb + ".dbo.TabCisZam c ON c.ID=m.ZamestnanecId "
                        "WHERE m.IdObdobi=%d AND c.Cislo=%d AND m.CisloMS IN (%s)" % (idobd, cislo, ms_in))
                    has = int(chk["rows"][0][0]) if (chk.get("ok") and chk.get("rows")) else 0
                    if not has:
                        out.append({"firma": firma, "cislo": cislo, "jmeno": "",
                                    "problem": "davka",
                                    "detail": "absence v registru (%s) — chybí dávka na pásce, DOPLNIT v Heliosu" % label})
        except Exception as _e:
            out.append({"firma": firma, "cislo": 0, "jmeno": "",
                        "problem": "chyba", "detail": str(_e)[:160]})
    return {"ok": True, "rok": int(rok), "mesic": int(mesic), "pocet": len(out), "polozky": out}


def _mzdy_rucni_rows(firma):
    """Ruční mzdové složky (tenant.mzdy_rucni_slozka) → předzpracování. Durable — přežije
    přegenerování i refresh snapshotu. Marti 28.6.: odměna jednatele MS 693, DPP MS 700,
    stravenkový paušál MS 793 ap. (cislo, cislo_ms, koruny, dny)."""
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        rr = s.execute(_t(
            "SELECT cislo, cislo_ms, castka, COALESCE(dny,0) FROM tenant.mzdy_rucni_slozka "
            "WHERE tenant_id=2 AND firma=:f AND aktivni=true"), {"f": str(firma).upper()}).fetchall()
    finally:
        s.close()
    out = []
    for r in rr:
        try:
            c = int(str(r[0]).strip()); ms = int(r[1]); kc = int(r[2] or 0); dny = int(r[3] or 0)
        except Exception:
            continue
        if kc or dny:
            out.append((c, ms, kc, dny))
    return out


# (stará case-based _mzdy_absence_rows OČR/nemoc nahrazena komplexní att_entry verzí výše —
#  att_entry je autoritativní a obsahuje VŠECHNY typy absencí vč. dovolené/lékaře. 30.6.2026)


def _mzdy_refresh_zrcadla(rok, mesic):
    """V1.02 (Marti 10.7.2026) — PŘED čistou vodou obnov mzdová zrcadla z Centrály (DB_EC),
    ať dopočtové složky vstoupí do mzdy VŽDY z aktuálních dat, ne ze zastaralých/prázdných:
      • att_day_summary    → loajalita (přesčas výroby) do 651
      • att_finance_zakazek → prémie ze zakázek do 651
      • att_odmena_centrala → odměny (DPP 700 / jednatel 693)
    Nahrazuje křehké „nejdřív ručně @@DOCHSUM, pak generovat" (Peťa 7.7.). Best-effort:
    když je zdroj nedostupný, generování NESPADNE, ale chyba je VIDITELNÁ ve výsledku
    (klíč `zrcadla_warn`) — žádné tiché přeskočení. Každý sync je transakční (rollback při
    chybě), takže při výpadku zůstane poslední dobré zrcadlo."""
    warn = []
    for _nm, _fn in (("dochsum", _sync_dochazka_sumaden),
                     ("zakazky", _sync_finance_zakazek),
                     ("odmeny", _sync_odmeny_from_ec)):
        try:
            _fn(int(rok), month=int(mesic))
        except Exception as _e:
            warn.append("%s: %s" % (_nm, str(_e)[:150]))
    return warn


def _mzdy_full_run(firma, rok, mesic, force_clean=False, budget_s=22):
    """MOST @@MZDY (Marti 28.6.): čistá voda + předzpracování (benefity+stravenky+příplatky)
    + výpočet ve smyčce s časovým rozpočtem. Volat opakovaně, dokud done=False (Express je pomalý).
    Čistá voda + předzpracování jen na začátku (hot==0) nebo force_clean."""
    import time as _tm
    _src, cloud_db = _zrc_dbs(firma)
    _ro = _mssql188_query("SELECT IdObdobi FROM " + cloud_db + ".dbo.TabMzdObd WHERE Rok=" +
                          str(int(rok)) + " AND Mesic=" + str(int(mesic)))
    if not (_ro.get("ok") and _ro.get("rows")):
        return {"ok": False, "error": "období v cloud Heliosu není (TabMzdObd)"}
    idobd = int(_ro["rows"][0][0])
    _zwarn, _pwarn = [], []  # V1.02: varování z obnovy zrcadel / stavby složek (viditelná ve výsledku)

    def _counts():
        c = _mssql188_query(
            "SELECT (SELECT COUNT(*) FROM " + cloud_db + ".dbo.TabZamMzd WHERE IdObdobi=" + str(idobd) +
            " AND Automat=1 AND Uzavreno=0 AND StavES IN (0,1)) cil,"
            "(SELECT COUNT(*) FROM " + cloud_db + ".dbo.TabZamVyp WHERE IdObdobi=" + str(idobd) + ") hot,"
            "(SELECT COUNT(*) FROM " + cloud_db + ".dbo.TabZamVyp WHERE IdObdobi=" + str(idobd) + " AND Info=58801) vys")
        if c.get("ok") and c.get("rows"):
            r0 = c["rows"][0]
            return int(r0[0] or 0), int(r0[1] or 0), int(r0[2] or 0)
        return 0, 0, 0

    cil, hot, _v = _counts()
    if force_clean or hot == 0:
        cw = _mssql188_query(_mzdy_clean_sql(cloud_db, idobd))
        if not cw.get("ok"):
            return {"ok": False, "error": "vyčištění: " + str(cw.get("error"))[:200]}
        # V1.02: obnov zdrojová zrcadla (loajalita/zakázky/odměny) PŘED stavbou složek,
        # ať čistá voda nikdy nejede ze zastaralých dat. Chyby zdroje jsou viditelné (_zwarn).
        _zwarn = _mzdy_refresh_zrcadla(rok, mesic)
        _pwarn = []
        prows = _mzdy_predzprac_rows(firma)
        try:
            prows = prows + _mzdy_stravenky_rows(firma, rok, mesic)
        except Exception as _e:
            _pwarn.append("stravenky: " + str(_e)[:120])
        try:
            prows = _mzdy_benefity_apply(prows, firma, rok, mesic)
        except Exception:
            pass
        try:
            prows = prows + _mzdy_priplatky_rows(firma, rok, mesic)
        except Exception:
            pass
        try:
            prows = prows + _mzdy_loajalita_rows(firma, rok, mesic)
        except Exception as _e:
            _pwarn.append("loajalita: " + str(_e)[:120])
        try:
            prows = prows + _mzdy_finance_zakazek_rows(firma, rok, mesic)
        except Exception as _e:
            _pwarn.append("zakazky: " + str(_e)[:120])
        # V1.04 (Marti 10.7.2026): odměny z Centrály VYPNUTY — způsobovaly DVOJÍ započtení s ručními
        # složkami (Herejtová 8000 místo 4000, jednatelé/Senft 2×). Odměny (DPP 700 / jednatel 693)
        # berem z ručních složek (mzdy_rucni_slozka) = zdroj pravdy pro tento měsíc. Migrace na
        # Centrálu = až po deaktivaci ručních (Peťa 7.7. / Marti 10.7.).
        # prows = prows + _mzdy_odmeny_rows(firma, rok, mesic)
        # Absence (OČR/nemoc) → docházková MS 201/200 do předzpracování. Marti 28.6.: nechat
        # VIDITELNÉ na pásce. Helios sám náhradu nedopočítá (hodí Status 9 = „doplnit dávku"),
        # což je záměrný signál — monitor @@MZDYCHECK i Status 9 na to ukáží. Skutečný výpočet
        # dávky = doplnit v Helios modulu nepřítomnosti (TODO přímé napojení).
        try:
            prows = prows + _mzdy_absence_rows(firma, rok, mesic)
        except Exception:
            pass
        try:
            prows = prows + _mzdy_rucni_rows(firma)
        except Exception:
            pass
        try:
            # Jednatelé/společníci (odměna 693) = odměna + PLNÉ stravné, nic dalšího (dovolená/OBL/HO ne).
            # Nemají dovolenou → stravné za CELÝ pracovní fond měsíce (Po–Pá), ne jen napíchané dny. Peta 7.7.2026.
            prows = [((r[0], 432) + tuple(r[2:])) if (int(r[1]) == 693 and int(r[0]) not in _JEDNATELE_CISLA) else r for r in prows]
            _spol = set(int(r[0]) for r in prows if int(r[1]) == 693) & _JEDNATELE_CISLA
            if _spol:
                import calendar as _calsp
                _ldsp = _calsp.monthrange(int(rok), int(mesic))[1]
                _wdsp = sum(1 for _x in range(1, _ldsp + 1) if _calsp.weekday(int(rok), int(mesic), _x) < 5)
                prows = [r for r in prows if int(r[0]) not in _spol or int(r[1]) == 693]
                for _csp in _spol:
                    prows.append((_csp, _STRAVENKA_MS, _wdsp * _STRAVENKA_KC, _wdsp))
        except Exception as _e:
            _pwarn.append("jednatel_stravne: " + str(_e)[:120])
        try:
            prows = _mzdy_consolidate(prows)
        except Exception as _e:
            _pwarn.append("consolidate: " + str(_e)[:120])
        if prows:
            perr = _mzdy_predzprac_apply(cloud_db, idobd, prows)
            if perr:
                return {"ok": False, "error": "předzpracování: " + str(perr)[:200]}
    t0 = _tm.time()
    stalled = False
    while _tm.time() - t0 < budget_s:
        cil, hot, _v = _counts()
        if hot >= cil:
            break
        w = _mssql188_query(_mzdy_worker_sql(cloud_db, idobd, 8))
        if not w.get("ok"):
            return {"ok": False, "error": "worker: " + str(w.get("error"))[:200], "cil": cil, "hotovo": hot}
        cil2, hot2, _v2 = _counts()
        if hot2 <= hot:
            stalled = True
            break
    cil, hot, vys = _counts()
    return {"ok": True, "firma": firma, "idobdobi": idobd, "cil": cil, "hotovo": hot,
            "vystrahy": vys, "done": hot >= cil, "uvazlo": stalled,
            "zrcadla_warn": _zwarn, "slozky_warn": _pwarn}


@api_router.post("/app/mzdy/generuj")
def mzdy_generuj(req: Request):
    """Generování mezd na CLOUD Heliosu: jeden tok = (volitelně vyčištění) generování +
    paušály + výpočet, idempotentně, dávka po @max (frontend loopuje s progresem). Parent-only.
    ?clean=1 (1. volání cyklu) smaže regenerovaný set před insertem (čistá voda).
    Marti 28.6.2026 (propojení hp_VlozMzPausDoMzSloz + předgenerování + hp_VypocitejMzdu)."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _g
    s = _g()
    try:
        if not _is_cockpit(s, uid):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    finally:
        s.close()
    firma = (req.query_params.get("firma") or "ES").upper()
    _src, cloud_db = _zrc_dbs(firma)
    import datetime as _dt
    _now = _dt.date.today()
    try:
        rok = int(req.query_params.get("rok") or _now.year)
        mesic = int(req.query_params.get("mesic") or _now.month)
        maxn = max(1, min(20, int(req.query_params.get("max") or 8)))
    except Exception:
        rok, mesic, maxn = _now.year, _now.month, 8
    _ro = _mssql188_query("SELECT IdObdobi FROM " + cloud_db + ".dbo.TabMzdObd "
                          "WHERE Rok=" + str(rok) + " AND Mesic=" + str(mesic))
    if not (_ro.get("ok") and _ro.get("rows")):
        return {"ok": False, "error": "období v cloud Heliosu není (TabMzdObd)"}
    idobd = int(_ro["rows"][0][0])
    _zwarn, _pwarn = [], []  # V1.03: viditelná varování (obnova zrcadel / stavba složek)

    # ─── REŽIM „JEN JEDEN ČLOVĚK" (?cislo=NNN) ──────────────────────────────────
    # Přegeneruje sakumprask jednoho zaměstnance: smaže JEN jeho pásku + předzpracování,
    # připraví JEN jeho složky a nechá výpočet dopočítat JEN jeho. Ostatních se nedotkne.
    # Zrcadlí stejný postup jako celková generace (clean=1), jen omezený na jedno číslo.
    cislo_raw = (req.query_params.get("cislo") or req.query_params.get("zam") or "").strip()
    if cislo_raw:
        # V1.03 (Marti 10.7.2026): PŘEGENEROVÁNÍ JEDINCE JE VYPNUTÉ. Dávalo jiný výsledek než
        # čistá voda (jiná stavba složek) → nedá se na něj spolehnout. Tento měsíc jedeme
        # VÝHRADNĚ čistou vodou na celou firmu.
        return {"ok": False, "firma": firma, "cislo": cislo_raw, "blokovano": True,
                "error": "⛔ Přegenerování JEDNOTLIVCE je vypnuté — nelze se na něj spolehnout "
                         "(dává jiný výsledek než čistá voda). Použij Generovat mzdy → ČISTÁ VODA "
                         "na celou firmu. (V1.03, Marti 10.7.2026)"}
        try:
            cislo = int(cislo_raw)
        except Exception:
            return {"ok": False, "error": "neplatné číslo zaměstnance: " + cislo_raw}
        zr = _mssql188_query("SELECT ID FROM " + cloud_db + ".dbo.TabCisZam WHERE Cislo=" + str(cislo))
        if not (zr.get("ok") and zr.get("rows")):
            return {"ok": False, "error": "zaměstnanec č. " + str(cislo) + " není v cloud Heliosu (" + firma + ")"}
        zid = int(zr["rows"][0][0])
        # je v automaticky generovaném setu? uzavřenou/ruční pásku (mimo StavES 0,1) neregenerujeme
        gr = _mssql188_query(
            "SELECT COUNT(*) FROM " + cloud_db + ".dbo.TabZamMzd WHERE IdObdobi=" + str(idobd) +
            " AND ZamestnanecId=" + str(zid) + " AND Automat=1 AND Uzavreno=0 AND StavES IN (0,1)")
        in_set = int(gr["rows"][0][0]) if (gr.get("ok") and gr.get("rows")) else 0
        if not in_set:
            return {"ok": False, "firma": firma, "cislo": cislo,
                    "error": "č. " + str(cislo) + " není v automatické generaci "
                             "(uzavřená/ruční/mimo StavES 0,1) — samostatně přegenerovat nelze"}
        # 1) čistá voda JEN jeho (páska TabZamVyp + složky TabMzSloz)
        cw = _mssql188_query(_mzdy_clean_one_sql(cloud_db, idobd, zid))
        if not cw.get("ok"):
            return {"ok": False, "error": "vyčištění (jeden) selhalo: " + str(cw.get("error"))[:300]}
        # V1.02: i pro jednoho obnov zdrojová zrcadla, ať přegenerování jede z aktuálních dat.
        _zwarn = _mzdy_refresh_zrcadla(rok, mesic)
        _pwarn = []
        # 2) předzpracování JEN jeho — postav všechny složky jako celková generace, pak odfiltruj na číslo
        prows = _mzdy_predzprac_rows(firma)
        try:
            prows = prows + _mzdy_stravenky_rows(firma, rok, mesic)
        except Exception:
            pass  # stravenky best-effort
        try:
            prows = _mzdy_benefity_apply(prows, firma, rok, mesic)
        except Exception:
            pass  # benefity best-effort
        try:
            prows = prows + _mzdy_priplatky_rows(firma, rok, mesic, only_cislo=cislo)
        except Exception:
            pass  # příplatky/srážky best-effort (ledger jen jeho)
        try:
            prows = prows + _mzdy_absence_rows(firma, rok, mesic)
        except Exception:
            pass  # absence z naší docházky best-effort
        try:
            prows = prows + _mzdy_rucni_rows(firma)
        except Exception:
            pass  # ruční složky (odměna společníků 693, DPP 700 ap.) best-effort
        try:
            prows = prows + _mzdy_loajalita_rows(firma, rok, mesic)
        except Exception as _e:
            _pwarn.append("loajalita: " + str(_e)[:120])
        try:
            prows = prows + _mzdy_finance_zakazek_rows(firma, rok, mesic)
        except Exception as _e:
            _pwarn.append("zakazky: " + str(_e)[:120])
        # V1.04 (Marti 10.7.2026): odměny z Centrály VYPNUTY — způsobovaly DVOJÍ započtení s ručními
        # složkami (Herejtová 8000 místo 4000, jednatelé/Senft 2×). Odměny (DPP 700 / jednatel 693)
        # berem z ručních složek (mzdy_rucni_slozka) = zdroj pravdy pro tento měsíc. Migrace na
        # Centrálu = až po deaktivaci ručních (Peťa 7.7. / Marti 10.7.).
        # prows = prows + _mzdy_odmeny_rows(firma, rok, mesic)
        prows = [r for r in prows if int(r[0]) == cislo]  # JEN on
        try:
            # Jednatel/společník (odměna 693) = odměna + PLNÉ stravné (celý fond), nic dalšího. Peta 7.7.2026.
            prows = [((r[0], 432) + tuple(r[2:])) if (int(r[1]) == 693 and int(r[0]) not in _JEDNATELE_CISLA) else r for r in prows]
            _spol = set(int(r[0]) for r in prows if int(r[1]) == 693) & _JEDNATELE_CISLA
            if _spol:
                import calendar as _calsp
                _ldsp = _calsp.monthrange(int(rok), int(mesic))[1]
                _wdsp = sum(1 for _x in range(1, _ldsp + 1) if _calsp.weekday(int(rok), int(mesic), _x) < 5)
                prows = [r for r in prows if int(r[0]) not in _spol or int(r[1]) == 693]
                for _csp in _spol:
                    prows.append((_csp, _STRAVENKA_MS, _wdsp * _STRAVENKA_KC, _wdsp))
        except Exception as _e:
            _pwarn.append("jednatel_stravne: " + str(_e)[:120])
        try:
            prows = _mzdy_consolidate(prows)
        except Exception as _e:
            _pwarn.append("consolidate: " + str(_e)[:120])
        # apply vždy (i při prázdném) → smaže i jeho staré STRATEGIE předzpracování, zapíše nové
        perr = _mzdy_predzprac_apply(cloud_db, idobd, prows, only_zid=zid)
        if perr:
            return {"ok": False, "error": "předzpracování (jeden) selhalo: " + str(perr)[:300]}
        # 3) výpočet JEN jeho
        w = _mssql188_query(_mzdy_worker_sql(cloud_db, idobd, 1, only_zid=zid))
        if not w.get("ok"):
            return {"ok": False, "error": "výpočet (jeden) selhal: " + str(w.get("error"))[:300]}
        # kontrola výsledku: má teď hotovou pásku?
        hr = _mssql188_query(
            "SELECT COUNT(*), MAX(ISNULL(Status,0)), MAX(ISNULL(Info,0)) FROM " + cloud_db +
            ".dbo.TabZamVyp WHERE IdObdobi=" + str(idobd) + " AND ZamestnanecId=" + str(zid))
        hot = 0
        status = None
        info = None
        if hr.get("ok") and hr.get("rows"):
            r0 = hr["rows"][0]
            hot = int(r0[0] or 0)
            status = r0[1]
            info = r0[2]
        return {"ok": True, "firma": firma, "cislo": cislo, "idobdobi": idobd,
                "jeden": True, "hotovo": hot, "done": hot >= 1,
                "status": status, "vystraha": (int(info) if info else 0),
                "slozek": len(prows), "zrcadla_warn": _zwarn, "slozky_warn": _pwarn}
    # ─── /REŽIM „JEN JEDEN ČLOVĚK" ──────────────────────────────────────────────

    clean = (req.query_params.get("clean") or "") in ("1", "true", "ano")
    if clean:
        cw = _mssql188_query(_mzdy_clean_sql(cloud_db, idobd))
        if not cw.get("ok"):
            return {"ok": False, "error": "vyčištění selhalo: " + str(cw.get("error"))[:300]}
        # V1.03 (Marti 10.7.2026): tato FRONTENDOVÁ čistá voda dřív NEobsahovala dopočtové složky
        # (loajalita / prémie ze zakázek / odměny / jednatelské stravné) — proto do mzdy vůbec
        # nevstupovaly (Peťa je 7.7. přidal jen do @@MZDY a do „jednoho člověka", sem ne).
        # Nově: obnov zdrojová zrcadla a postav složky PŘESNĚ jako _mzdy_full_run.
        _zwarn = _mzdy_refresh_zrcadla(rok, mesic)
        _pwarn = []
        # PŘEDZPRACOVÁNÍ ze STRATEGIE: obě složky (zaklad→karta 001, os_ohodnoceni→TabPredzp 432)
        prows = _mzdy_predzprac_rows(firma)
        try:
            prows = prows + _mzdy_stravenky_rows(firma, rok, mesic)
        except Exception as _e:
            _pwarn.append("stravenky: " + str(_e)[:120])
        try:
            prows = _mzdy_benefity_apply(prows, firma, rok, mesic)
        except Exception as _e:
            _pwarn.append("benefity: " + str(_e)[:120])
        try:
            prows = prows + _mzdy_priplatky_rows(firma, rok, mesic)
        except Exception as _e:
            _pwarn.append("priplatky: " + str(_e)[:120])
        try:
            prows = prows + _mzdy_loajalita_rows(firma, rok, mesic)
        except Exception as _e:
            _pwarn.append("loajalita: " + str(_e)[:120])
        try:
            prows = prows + _mzdy_finance_zakazek_rows(firma, rok, mesic)
        except Exception as _e:
            _pwarn.append("zakazky: " + str(_e)[:120])
        # V1.04 (Marti 10.7.2026): odměny z Centrály VYPNUTY — způsobovaly DVOJÍ započtení s ručními
        # složkami (Herejtová 8000 místo 4000, jednatelé/Senft 2×). Odměny (DPP 700 / jednatel 693)
        # berem z ručních složek (mzdy_rucni_slozka) = zdroj pravdy pro tento měsíc. Migrace na
        # Centrálu = až po deaktivaci ručních (Peťa 7.7. / Marti 10.7.).
        # prows = prows + _mzdy_odmeny_rows(firma, rok, mesic)
        try:
            prows = prows + _mzdy_absence_rows(firma, rok, mesic)
        except Exception as _e:
            _pwarn.append("absence: " + str(_e)[:120])
        try:
            prows = prows + _mzdy_rucni_rows(firma)
        except Exception as _e:
            _pwarn.append("rucni: " + str(_e)[:120])
        try:
            # Jednatelé/společníci (odměna 693) = odměna + PLNÉ stravné za celý pracovní fond měsíce.
            prows = [((r[0], 432) + tuple(r[2:])) if (int(r[1]) == 693 and int(r[0]) not in _JEDNATELE_CISLA) else r for r in prows]
            _spol = set(int(r[0]) for r in prows if int(r[1]) == 693) & _JEDNATELE_CISLA
            if _spol:
                import calendar as _calsp
                _ldsp = _calsp.monthrange(int(rok), int(mesic))[1]
                _wdsp = sum(1 for _x in range(1, _ldsp + 1) if _calsp.weekday(int(rok), int(mesic), _x) < 5)
                prows = [r for r in prows if int(r[0]) not in _spol or int(r[1]) == 693]
                for _csp in _spol:
                    prows.append((_csp, _STRAVENKA_MS, _wdsp * _STRAVENKA_KC, _wdsp))
        except Exception as _e:
            _pwarn.append("jednatel_stravne: " + str(_e)[:120])
        try:
            prows = _mzdy_consolidate(prows)  # sečti víc zdrojů do jedné Helios složky
        except Exception as _e:
            _pwarn.append("consolidate: " + str(_e)[:120])
        if prows:
            perr = _mzdy_predzprac_apply(cloud_db, idobd, prows)
            if perr:
                return {"ok": False, "error": "předzpracování selhalo: " + str(perr)[:300]}

    def _counts():
        c = _mssql188_query(
            "SELECT "
            "(SELECT COUNT(*) FROM " + cloud_db + ".dbo.TabZamMzd WHERE IdObdobi=" + str(idobd) +
            " AND Automat=1 AND Uzavreno=0 AND StavES IN (0,1)) cil,"
            "(SELECT COUNT(*) FROM " + cloud_db + ".dbo.TabZamVyp WHERE IdObdobi=" + str(idobd) + ") hotovo,"
            "(SELECT COUNT(*) FROM " + cloud_db + ".dbo.TabZamVyp WHERE IdObdobi=" + str(idobd) +
            " AND Info=58801) vystrahy")
        if c.get("ok") and c.get("rows"):
            r0 = c["rows"][0]
            return int(r0[0] or 0), int(r0[1] or 0), int(r0[2] or 0)
        return 0, 0, 0

    cil, before, _v = _counts()
    if before >= cil:
        return {"ok": True, "firma": firma, "idobdobi": idobd, "cil": cil, "hotovo": before,
                "pridano": 0, "vystrahy": _v, "done": True, "uvazlo": False,
                "zrcadla_warn": _zwarn, "slozky_warn": _pwarn}
    w = _mssql188_query(_mzdy_worker_sql(cloud_db, idobd, maxn))
    if not w.get("ok"):
        return {"ok": False, "error": "worker selhal: " + str(w.get("error"))[:300]}
    cil, after, vystrahy = _counts()
    pridano = after - before
    return {"ok": True, "firma": firma, "idobdobi": idobd, "cil": cil, "hotovo": after,
            "pridano": pridano, "vystrahy": vystrahy,
            "done": (after >= cil) or (pridano == 0),
            "uvazlo": (pridano == 0 and after < cil),
            "zrcadla_warn": _zwarn, "slozky_warn": _pwarn}


# ========================= BENEFITY HO/OBL — endpointy =========================
def _benefit_user_cisla(sess, uid):
    from sqlalchemy import text as _t
    rr = sess.execute(_t(
        "SELECT DISTINCT cislo_zam FROM tenant.att_employee "
        "WHERE tenant_id=2 AND user_id=:u AND cislo_zam ~ '^[0-9]+$'"), {"u": uid}).fetchall()
    out = []
    for r in rr:
        try:
            out.append(int(r[0]))
        except Exception:
            pass
    return out


def _benefit_ho_kc_den(sess, fkod, rok, mesic):
    from sqlalchemy import text as _t
    r = sess.execute(_t(
        "SELECT kc_za_den FROM tenant.benefit_konstanta "
        "WHERE typ='HO' AND (firma IS NULL OR firma=:f) "
        "AND platnost_od<=make_date(:y,:mo,1) "
        "AND (platnost_do IS NULL OR platnost_do>=make_date(:y,:mo,1)) "
        "ORDER BY platnost_od DESC LIMIT 1"), {"f": fkod, "y": rok, "mo": mesic}).first()
    return float(r[0]) if r and r[0] else 234.0


def _benefit_presence(sess, rok, mesic):
    from sqlalchemy import text as _t
    pres = {}
    for r in sess.execute(_t(
        # Marti 29.6.: worked-days z att_entry (autoritativní), ne sparse att_day_summary
        "SELECT e.cislo_zam, COUNT(DISTINCT d.entry_date) FROM "
        "(SELECT a.employee_id, a.entry_date FROM tenant.att_entry a "
        " JOIN tenant.att_entry_type et ON et.id=a.entry_type_id "
        " WHERE et.code IN ('work','homeoffice','fond_doplneni') "
        "   AND EXTRACT(year FROM a.entry_date)=:y AND EXTRACT(month FROM a.entry_date)=:mo "
        " GROUP BY a.employee_id, a.entry_date HAVING SUM(a.hours)>4) d "
        "JOIN tenant.att_employee e ON e.id=d.employee_id "
        "WHERE e.tenant_id=2 AND e.cislo_zam IS NOT NULL GROUP BY e.cislo_zam"), {"y": rok, "mo": mesic}).fetchall():
        try:
            pres[int(r[0])] = int(r[1] or 0)
        except Exception:
            pass
    return pres


def _benefit_is_hr(uid):
    try:
        return bool(is_marti_parent(uid) or uid in _SCOPED_APPROVER_UIDS)
    except Exception:
        return False


@api_router.get("/app/benefity/lidi")
def benefity_lidi(req: Request):
    """HR: seznam všech osob (firma+číslo+jméno) k prolistování benefitů."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not _benefit_is_hr(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        rows = s.execute(_t(
            "SELECT firma, cislo FROM tenant.benefit_limit WHERE tenant_id=2 ORDER BY firma, cislo")).fetchall()
    finally:
        s.close()
    names = {}
    for fkod, db in (('1', None), ('2', None)):
        _src, cdb = _zrc_dbs('EC' if fkod == '1' else 'ES')
        nr = _mssql188_query("SELECT Cislo, RTRIM(ISNULL(Prijmeni,'')), RTRIM(ISNULL(Jmeno,'')) FROM " + cdb + ".dbo.TabCisZam")
        if nr.get("ok"):
            for v in nr.get("rows") or []:
                try:
                    names[(fkod, int(v[0]))] = (str(v[1] or '') + ' ' + str(v[2] or '')).strip()
                except Exception:
                    pass
    out = [{"firma": r[0], "cislo": int(r[1]),
            "jmeno": names.get((r[0], int(r[1])), '(č. ' + str(r[1]) + ')'),
            "firma_nazev": 'EC Control' if r[0] == '1' else 'ES System'} for r in rows]
    return {"ok": True, "lidi": out}


@api_router.get("/app/benefity/moje")
def benefity_moje(req: Request):
    """Self-service: přihlášený uživatel vidí svoje benefity HO/OBL pro období.
    HR (parent / scoped approver) může přes ?firma&cislo prolistovat kohokoliv."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauth"}, status_code=401)
    import datetime as _dt
    _now = _dt.date.today()
    try:
        rok = int(req.query_params.get("rok") or _now.year)
        mesic = int(req.query_params.get("mesic") or _now.month)
    except Exception:
        rok, mesic = _now.year, _now.month
    je_hr = _benefit_is_hr(uid)
    ov_firma = (req.query_params.get("firma") or "").strip()
    ov_cislo = req.query_params.get("cislo")
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        if je_hr and ov_firma and ov_cislo:
            try:
                cisla = [int(ov_cislo)]
            except Exception:
                cisla = []
        else:
            cisla = _benefit_user_cisla(s, uid)
        out = []
        if cisla:
            pres = _benefit_presence(s, rok, mesic)
            ffilt = ""
            params = {"y": rok, "mo": mesic, "cs": cisla}
            if je_hr and ov_firma and ov_cislo:
                ffilt = " AND l.firma=:ff"
                params["ff"] = ('1' if ov_firma.upper() in ('EC', '1') else '2')
            rows = s.execute(_t(
                "SELECT l.firma, l.cislo, l.ho_max_kc, l.obl_kc, v.ho_dny, v.obl_on "
                "FROM tenant.benefit_limit l "
                "LEFT JOIN tenant.benefit_volba v ON v.tenant_id=2 AND v.firma=l.firma AND v.cislo=l.cislo "
                "  AND v.rok=:y AND v.mesic=:mo "
                "WHERE l.tenant_id=2 AND l.cislo = ANY(:cs)" + ffilt + " ORDER BY l.firma, l.cislo"),
                params).fetchall()
            for r in rows:
                fkod = r[0]; cislo = int(r[1])
                ho_max_kc = float(r[2] or 0); obl_kc = float(r[3] or 0)
                ho_kc_den = _benefit_ho_kc_den(s, fkod, rok, mesic)
                ho_max_dny = int(-(-ho_max_kc // ho_kc_den)) if ho_kc_den else 0  # ceil (kč cap hlídá částku)
                ho_dny = int(r[4]) if r[4] is not None else min(ho_max_dny, 8 if ho_max_kc > 0 else 0)
                obl_on = bool(r[5]) if r[5] is not None else (obl_kc > 0)
                dny_pritomen = pres.get(cislo, 0)
                ho_castka = int(round(min(ho_dny * ho_kc_den, ho_max_kc)))
                out.append({
                    "firma": fkod, "cislo": cislo,
                    "ho_kc_den": ho_kc_den, "ho_max_dny": ho_max_dny,
                    "ho_dny": ho_dny, "ho_castka": ho_castka,
                    "obl_mozne": obl_kc > 0, "obl_kc": int(obl_kc), "obl_on": obl_on,
                    "obl_castka": int(obl_kc) if (obl_on and dny_pritomen >= 1) else 0,
                    "dny_pritomen": dny_pritomen,
                    "danova_uspora": int(round((ho_castka + (obl_kc if (obl_on and dny_pritomen >= 1) else 0)) * 0.15)),
                })
        return {"ok": True, "rok": rok, "mesic": mesic, "je_hr": je_hr, "polozky": out}
    finally:
        s.close()


@api_router.post("/app/benefity/moje")
async def benefity_moje_save(req: Request):
    """Self-service uložení: uživatel nastaví HO dny + OBL on/off (validace proti HR stropu)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid:
        return JSONResponse({"ok": False, "error": "unauth"}, status_code=401)
    try:
        b = await req.json()
    except Exception:
        b = {}
    try:
        firma = str(b.get("firma") or "").strip()
        firma = '1' if firma.upper() in ('EC', '1') else '2'
        cislo = int(b.get("cislo"))
        rok = int(b.get("rok")); mesic = int(b.get("mesic"))
        ho_dny = max(0, int(b.get("ho_dny") or 0))
        obl_on = bool(b.get("obl_on"))
    except Exception:
        return JSONResponse({"ok": False, "error": "bad input"}, status_code=400)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        # vlastnictví: cislo musí patřit uživateli (nebo je HR — může za kohokoliv)
        if not _benefit_is_hr(uid) and cislo not in _benefit_user_cisla(s, uid):
            return JSONResponse({"ok": False, "error": "not your number"}, status_code=403)
        lim = s.execute(_t("SELECT ho_max_kc, obl_kc FROM tenant.benefit_limit "
                           "WHERE tenant_id=2 AND firma=:f AND cislo=:c"),
                        {"f": firma, "c": cislo}).first()
        if not lim:
            return JSONResponse({"ok": False, "error": "no limit"}, status_code=404)
        ho_kc_den = _benefit_ho_kc_den(s, firma, rok, mesic)
        ho_max_dny = int(-(-float(lim[0] or 0) // ho_kc_den)) if ho_kc_den else 0  # ceil
        ho_dny = min(ho_dny, ho_max_dny)          # strop HR (částka ≤ HR drží kč cap)
        s.execute(_t(
            "INSERT INTO tenant.benefit_volba (tenant_id, firma, cislo, rok, mesic, ho_dny, obl_on, user_id) "
            "VALUES (2,:f,:c,:y,:mo,:d,:o,:u) "
            "ON CONFLICT (tenant_id, firma, cislo, rok, mesic) DO UPDATE SET "
            "ho_dny=EXCLUDED.ho_dny, obl_on=EXCLUDED.obl_on, user_id=EXCLUDED.user_id, updated_at=now()"),
            {"f": firma, "c": cislo, "y": rok, "mo": mesic, "d": ho_dny, "o": obl_on, "u": uid})
        s.commit()
        return {"ok": True, "ho_dny": ho_dny, "obl_on": obl_on}
    finally:
        s.close()


@api_router.get("/app/benefity/hr")
def benefity_hr(req: Request):
    """HR (personalistka/parent): seznam osob s benefit stropy + aktuální volbou."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not (is_marti_parent(uid) or uid in _SCOPED_APPROVER_UIDS):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    firma = (req.query_params.get("firma") or "ES").upper()
    fkod = '1' if firma in ('EC', '1') else '2'
    _src, cloud_db = _zrc_dbs('EC' if fkod == '1' else 'ES')
    import datetime as _dt
    _now = _dt.date.today()
    try:
        rok = int(req.query_params.get("rok") or _now.year)
        mesic = int(req.query_params.get("mesic") or _now.month)
    except Exception:
        rok, mesic = _now.year, _now.month
    # jména z cloud Heliosu
    names = {}
    nr = _mssql188_query("SELECT Cislo, RTRIM(ISNULL(Prijmeni,'')), RTRIM(ISNULL(Jmeno,'')) FROM " + cloud_db + ".dbo.TabCisZam")
    if nr.get("ok"):
        for v in nr.get("rows") or []:
            try:
                names[int(v[0])] = (str(v[1] or '') + ' ' + str(v[2] or '')).strip()
            except Exception:
                pass
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        ho_kc_den = _benefit_ho_kc_den(s, fkod, rok, mesic)
        rows = s.execute(_t(
            "SELECT l.cislo, l.ho_max_kc, l.obl_kc, v.ho_dny, v.obl_on "
            "FROM tenant.benefit_limit l "
            "LEFT JOIN tenant.benefit_volba v ON v.tenant_id=2 AND v.firma=l.firma AND v.cislo=l.cislo "
            "  AND v.rok=:y AND v.mesic=:mo "
            "WHERE l.tenant_id=2 AND l.firma=:f ORDER BY l.cislo"),
            {"f": fkod, "y": rok, "mo": mesic}).fetchall()
        out = []
        for r in rows:
            cislo = int(r[0]); ho_max_kc = float(r[1] or 0)
            out.append({
                "cislo": cislo, "jmeno": names.get(cislo, ''),
                "ho_max_kc": int(ho_max_kc), "ho_max_dny": int(-(-ho_max_kc // ho_kc_den)) if ho_kc_den else 0,
                "obl_kc": int(float(r[2] or 0)),
                "ho_dny": (int(r[3]) if r[3] is not None else None),
                "obl_on": (bool(r[4]) if r[4] is not None else None),
            })
        return {"ok": True, "firma": fkod, "rok": rok, "mesic": mesic, "ho_kc_den": ho_kc_den, "osoby": out}
    finally:
        s.close()


