@api_router.get("/app/vp/cockpit")
def vp_cockpit_get(req: Request):
    """VP leader cockpit — Eliška jako vedoucí vidí celý pipeline hromad (poptávka →
    vyd. poptávka → nabídka → přij./vyd. objednávky → přij./vyd. faktury → výdejky) po
    řešitelích: svoje, kolegů i celek. Živě z tenant.ec_hromada_* (mirror DB_EC).
    'Aktivní' = nesplněné za posl. 18 měsíců. Scope: rodiče + Eliška (34) + cockpit.
    Marti 5.7.2026 — příprava VP na produkci před Eliščiným návratem 17.7."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        if not (uid and (_is_parent(s, uid) or int(uid) == 34 or _is_cockpit(s, uid))):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        FAZE = ["poptavka", "vydana_poptavka", "nabidka", "prijata_obj", "vydana_obj",
                "prijemka", "vydejka", "prijata_faktura", "vydana_faktura"]
        # Jednotný zdroj = tenant.vp_pipeline (UNION oz_* zrcadel, řešitel/splněno/datum
        # normalizované; řešitel=autor u faktur/vyd.obj/výdejek/příjemek). Marti 5.7.2026.
        rows = s.execute(_t(
            "SELECT COALESCE(NULLIF(resitel,''),'—') r, faze f,"
            "  count(*) FILTER (WHERE NOT splneno AND datporizeni >= now()-interval '18 months') akt,"
            "  count(*) tot"
            " FROM tenant.vp_pipeline GROUP BY 1,faze")).fetchall()
        per = {}
        celek = {f: {"akt": 0, "tot": 0} for f in FAZE}
        for r in rows:
            res, f, akt, tot = r[0], r[1], int(r[2] or 0), int(r[3] or 0)
            per.setdefault(res, {ff: {"akt": 0, "tot": 0} for ff in FAZE})
            if f in per[res]:
                per[res][f] = {"akt": akt, "tot": tot}
            celek[f]["akt"] += akt
            celek[f]["tot"] += tot
        lidi = []
        for res, fz in per.items():
            akt_sum = sum(fz[f]["akt"] for f in FAZE)
            if akt_sum == 0:
                continue
            lidi.append({"resitel": res, "je_eliska": (res == "EKolarova"),
                         "faze": fz, "aktivni": akt_sum,
                         "celkem": sum(fz[f]["tot"] for f in FAZE)})
        lidi.sort(key=lambda x: (-x["aktivni"], -x["celkem"]))
        return {"ok": True, "faze": FAZE, "lidi": lidi, "celek": celek,
                "aktivni_celkem": sum(celek[f]["akt"] for f in FAZE)}
    finally:
        s.close()


@api_router.get("/app/platby/navrh")
def platby_navrh_get(req: Request):
    """Platební centrum (Peťa) — návrh k platbě PF (CZK + EUR) z NAŠICH dat. Otevřené saldo =
    částka faktury − naše úhrady (oz_uhrady), NE zrcadlené Helios saldo (to se nedrží — smrtelně
    důležité, viz ucto.md). Filtr = stará selekce EC_Fin_GenNavrhKPlatbe (realizováno, ne
    fin.zákaz/nehradit, obdobi>22, ne řada 52x = záloha, splatnost − dny předem). Scope: rodiče +
    cockpit + Petra (18). Marti 6.7.2026."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        if not (uid and (_is_parent(s, uid) or int(uid) == 18 or _is_cockpit(s, uid))):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        # Firma (účetní) se v EC odvozuje z ŘADY dokladu (Marti 7.7. dle Peti):
        # ES faktury jedou v EC pod zvláštními řadami 501(FPS)/531(FPZS)/541(FPOS),
        # ostatní = EC. (Helios ES = jen mzdy; ES účto je v EC → Pohoda.) Data jsou
        # v jedné DB (DB_EC), takže úhrady zůstávají firma=1 (bez cross-db).
        firma = (req.query_params.get("firma") or "all").strip()
        params = {}
        ffilter = ""
        _uf = "(CASE WHEN p.rada IN ('501','531','541') THEN 2 ELSE 1 END)"
        if firma in ("1", "2"):
            params["ff"] = int(firma)
            ffilter = " AND " + _uf + " = :ff "
        # Hranice splatnosti dle platebních dnů Út/Čt (Peta 13.7.): ber faktury se splatností
        # do 1 dne po DRUHÉM nejbližším platebním dni (dnešek se počítá jako první, je-li platební).
        # Po/Út → Čt+1 = např. 17.7.; St/Čt → další Út+1 = např. 22.7. Nahrazuje pevné „+dny předem".
        import datetime as _pdt
        _paydays = {1, 3}   # weekday Út=1, Čt=3
        _p0 = _pdt.date.today()
        while _p0.weekday() not in _paydays:
            _p0 += _pdt.timedelta(days=1)
        _p1 = _p0 + _pdt.timedelta(days=1)
        while _p1.weekday() not in _paydays:
            _p1 += _pdt.timedelta(days=1)
        params["cutoff"] = _p1 + _pdt.timedelta(days=1)
        rows = s.execute(_t(
            # paid = Helios úhrady (oz_uhrady, mirror) + náš úhradový ZÁMEK (platak_uhrada_lock,
            # zapsaný při generování platáku — přežije TRUNCATE mirroru; pojistka proti dvojí
            # platbě v dalším běhu, než banka zaúčtuje). Marti 7.7.2026.
            "WITH u AS (SELECT id_fak, SUM(castka) AS paid FROM ("
            "  SELECT id_fak, castka_po_bance AS castka FROM tenant.oz_uhrady WHERE firma=1"
            "  UNION ALL SELECT id_fak, castka FROM tenant.platak_uhrada_lock) x GROUP BY id_fak) "
            "SELECT p.mena, p.doklad, COALESCE(NULLIF(p.dodavatel,''),p.zkratka,'?') dod, "
            "  COALESCE(p.var_symbol,'') vs, to_char(p.splatnost::date,'DD.MM.YYYY') splat, "
            "  (p.splatnost::date - now()::date) dni, "
            "  ((CASE WHEN p.mena='CZK' THEN p.suma_kc ELSE p.suma_val END) - COALESCE(u.paid,0)) open_saldo, "
            "  p.poradove_cislo, COALESCE(p.popis,'') popis, " + _uf + " AS ufirma "
            "FROM tenant.oz_pf_platba p LEFT JOIN u ON u.id_fak=p.id "
            "WHERE p.realizovano=1 AND NOT p.fin_zakaz AND p.nehradit=0 AND p.suma_po_zao>0 "
            "  AND p.obdobi>22 AND p.rada NOT LIKE '52%' "
            "  AND p.splatnost::date <= :cutoff "
            "  AND ((CASE WHEN p.mena='CZK' THEN p.suma_kc ELSE p.suma_val END) - COALESCE(u.paid,0)) > 0.5 "
            + ffilter +
            "ORDER BY p.mena, p.splatnost"), params).fetchall()
        czk, eur = [], []
        for r in rows:
            it = {"doklad": r[1] or "", "dodavatel": r[2] or "", "vs": r[3] or "", "splatnost": r[4],
                  "dni": int(r[5]) if r[5] is not None else None,
                  "castka": round(float(r[6]), 2) if r[6] is not None else 0.0,
                  "cislo": r[7], "popis": (r[8] or "")[:70],
                  "firma": int(r[9]) if r[9] is not None else 1}
            (czk if r[0] == "CZK" else eur).append(it)
        return {"ok": True, "cutoff": params["cutoff"].strftime("%d.%m.%Y"),
                "czk": {"pocet": len(czk), "suma": round(sum(x["castka"] for x in czk), 2), "polozky": czk},
                "eur": {"pocet": len(eur), "suma": round(sum(x["castka"] for x in eur), 2), "polozky": eur}}
    finally:
        s.close()


@api_router.get("/app/platby/vypisy")
def platby_vypisy_get(req: Request):
    """Výpisy z banky — posledních 60 transakcí z RB API (tenant.bank_transaction_raw): datum, směr,
    částka, protiúčet, VS, zpráva + stav párování. Scope: rodiče + Petra (18) + cockpit. Marti 6.7.2026."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        if not (uid and (_is_parent(s, uid) or int(uid) == 18 or _is_cockpit(s, uid))):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        # Firma = banka účtu (bank_connection.company_id: EC=1, ES=2) + filtr měny. Marti 7.7.
        firma = (req.query_params.get("firma") or "all").strip()
        mena = (req.query_params.get("mena") or "all").strip().upper()
        params = {}
        conds = []
        if firma in ("1", "2"):
            params["ff"] = int(firma); conds.append("c.company_id = :ff")
        if mena in ("CZK", "EUR"):
            params["mm"] = mena; conds.append("COALESCE(NULLIF(t.mena,''),'CZK') = :mm")
        base = ("FROM tenant.bank_transaction_raw t "
                "LEFT JOIN tenant.bank_connection_account a ON a.id=t.account_id "
                "LEFT JOIN tenant.bank_connection c ON c.id=a.connection_id"
                + ((" WHERE " + " AND ".join(conds)) if conds else ""))
        rows = s.execute(_t(
            "SELECT to_char(t.datum,'DD.MM.YYYY') d, t.castka, COALESCE(NULLIF(t.mena,''),'CZK') mena, "
            "  COALESCE(t.smer,'') smer, COALESCE(t.protiucet,'') protiucet, COALESCE(t.vs,'') vs, "
            "  LEFT(COALESCE(t.zprava,''),70) zprava, COALESCE(t.stav_parovani,'') stav, "
            "  COALESCE(NULLIF(t.par_kategorie,''), NULLIF(t.par_zakazka,''), '') par, "
            "  COALESCE(c.company_id,1) firma " + base +
            " ORDER BY t.datum DESC, t.id DESC LIMIT 100"), params).fetchall()
        out = []
        for r in rows:
            out.append({"datum": r[0], "castka": float(r[1]) if r[1] is not None else 0.0,
                        "mena": r[2], "smer": r[3], "protiucet": r[4] or "", "vs": r[5] or "",
                        "zprava": r[6] or "", "stav": r[7] or "", "par": r[8] or "",
                        "firma": int(r[9]) if r[9] is not None else 1})
        cnt = s.execute(_t("SELECT count(*) " + base), params).scalar()
        posl = s.execute(_t("SELECT to_char(max(t.datum),'DD.MM.YYYY') " + base), params).scalar()
        return {"ok": True, "polozky": out, "posledni": posl, "total": int(cnt or 0), "shown": len(out)}
    finally:
        s.close()


@api_router.get("/app/platby/plataky")
def platby_plataky_get(req: Request):
    """Platáky (platební příkazy) — tuzemské (oz_platak_tuz) + zahraniční (oz_platak_zahr) per firma
    (company.id 1/2). Peťa je kontroluje jako ve staré Centrále (přehledy 2370/2375). „Jsou to prachy."
    Scope: rodiče + Petra (18) + cockpit. Marti 6.7.2026."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        if not (uid and (_is_parent(s, uid) or int(uid) == 18 or _is_cockpit(s, uid))):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        # SERVER-SIDE filtr firma (EC=1/ES=2) + typ (tuz/zahr). Marti 7.7.: „něco nesedí" —
        # globální LIMIT 500 přes VŠECHNY platáky ukrojil starší ES tuzemské (utopily se
        # pod novějšími EC zahraničními) → filtr ukazoval jen pár. Teď filtr běží v DB
        # a celkový počet/součet je PRAVDIVÝ (bez ohledu na zobrazených 500). ORDER dle SKUTEČNÉHO data.
        firma = (req.query_params.get("firma") or "all").strip()
        typ = (req.query_params.get("typ") or "all").strip()
        params = {}
        fw = ""
        if firma in ("1", "2"):
            params["f"] = int(firma)
            fw = " WHERE firma = :f"
        col_tuz = ("SELECT firma, 'tuz' typ, id, to_char(datum_vystaveni::date,'DD.MM.YYYY') vyst, "
                   "  to_char(datum_splatnosti::date,'DD.MM.YYYY') splat, COALESCE(odkud,'') odkud, pocet, "
                   "  castka_celkem, COALESCE(mena,'CZK') mena, COALESCE(seznam_faktur,'') sez, "
                   "  COALESCE(realizace_export,false) exp, COALESCE(autor,'') autor, datum_vystaveni::date sortd, 'helios' zdroj "
                   "FROM tenant.oz_platak_tuz" + fw)
        col_zahr = ("SELECT firma, 'zahr', id, to_char(datum_vystaveni::date,'DD.MM.YYYY'), "
                    "  to_char(datum_splatnosti::date,'DD.MM.YYYY'), COALESCE(odkud,''), pocet, "
                    "  castka_celkem, COALESCE(mena,'EUR'), COALESCE(seznam_faktur,''), "
                    "  COALESCE(realizace_export,false), COALESCE(autor,''), datum_vystaveni::date sortd, 'helios' "
                    "FROM tenant.oz_platak_zahr" + fw)
        agg_tuz = "SELECT castka_celkem, COALESCE(mena,'CZK') mena FROM tenant.oz_platak_tuz" + fw
        agg_zahr = "SELECT castka_celkem, COALESCE(mena,'EUR') mena FROM tenant.oz_platak_zahr" + fw
        # NAŠE odeslané platáky (bank_platak stav='odeslano') — pražské od 7.7. (Helios už platáky nedělá).
        _tp = (typ if typ in ("tuz", "zahr") else None)
        if _tp:
            params["tp"] = _tp
        fw_nas = " WHERE stav='odeslano'" + (" AND firma=:f" if firma in ("1", "2") else "") + (" AND typ=:tp" if _tp else "")
        col_nas = ("SELECT firma, typ, id, to_char(datum_vytvoreni,'DD.MM.YYYY'), "
                   "  to_char(datum_splatnosti,'DD.MM.YYYY'), 'RB '||COALESCE(mena,'CZK'), COALESCE(pocet_polozek,0), "
                   "  COALESCE(suma,0), COALESCE(mena,'CZK'), "
                   "  COALESCE((SELECT string_agg(COALESCE(NULLIF(l.doklad_vs,''),l.dodavatel),', ' ORDER BY l.id) "
                   "    FROM tenant.platak_uhrada_lock l WHERE l.platak_id=bp.id),''), true, "
                   "  COALESCE(poznamka,''), datum_vytvoreni::date, 'nas' "
                   "FROM tenant.bank_platak bp" + fw_nas)
        agg_nas = "SELECT suma AS castka_celkem, COALESCE(mena,'CZK') mena FROM tenant.bank_platak bp" + fw_nas
        parts, aggs = [], []
        if typ in ("all", "tuz"):
            parts.append(col_tuz); aggs.append(agg_tuz)
        if typ in ("all", "zahr"):
            parts.append(col_zahr); aggs.append(agg_zahr)
        if not parts:
            parts.append(col_tuz); aggs.append(agg_tuz)
        parts.append(col_nas); aggs.append(agg_nas)
        rows = s.execute(_t(" UNION ALL ".join(parts)
                            + " ORDER BY sortd DESC NULLS LAST, id DESC LIMIT 500"), params).fetchall()
        out = []
        for r in rows:
            out.append({"firma": int(r[0]) if r[0] is not None else 0, "typ": r[1], "id": r[2],
                        "vystaveni": r[3] or "", "splatnost": r[4] or "", "odkud": r[5] or "",
                        "pocet": int(r[6] or 0), "castka": float(r[7]) if r[7] is not None else 0.0,
                        "mena": r[8], "seznam": r[9] or "", "export": bool(r[10]), "autor": r[11] or "",
                        "zdroj": (r[13] if len(r) > 13 else "helios")})
        agg = s.execute(_t("SELECT mena, count(*) n, sum(castka_celkem) c FROM ("
                           + " UNION ALL ".join(aggs) + ") q GROUP BY mena"), params).fetchall()
        sums = {row[0]: float(row[2] or 0) for row in agg}
        total = int(sum(int(row[1]) for row in agg))
        firmy = s.execute(_t("SELECT id, code, nazev FROM tenant.company WHERE aktivni ORDER BY id")).fetchall()
        fmap = {str(int(f[0])): {"code": f[1], "nazev": f[2]} for f in firmy}
        return {"ok": True, "plataky": out, "firmy": fmap, "total": total,
                "sums": sums, "shown": len(out)}
    finally:
        s.close()


@api_router.get("/app/platby/importy")
def platby_importy_get(req: Request):
    """Importy do banky — fyzické platák soubory (.p11/.f84) k nahrání do RB.
    Naše bank_platak se souborem: stav 'vygenerovano' = čeká na import, 'odeslano' = už odesláno.
    Zdroj pravdy = adresář \\Platební příkazy\\{EC|ES}\\<datum>\\. Rodiče+Petra(18)+cockpit. Claude ID23 8.7.2026."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        if not (uid and (_is_parent(s, uid) or int(uid) == 18 or _is_cockpit(s, uid))):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        firma = (req.query_params.get("firma") or "all").strip()
        params = {}
        cond = "COALESCE(soubor_nazev,'')<>'' AND stav<>'smazano'"
        if firma in ("1", "2"):
            params["f"] = int(firma); cond += " AND firma=:f"
        rows = s.execute(_t(
            "SELECT id, firma, typ, mena, stav, COALESCE(soubor_nazev,''), COALESCE(soubor_cesta,''), "
            "  COALESCE(pocet_polozek,0), COALESCE(suma,0), to_char(datum_vytvoreni,'DD.MM.YYYY'), "
            "  to_char(created_at AT TIME ZONE 'Europe/Prague','DD.MM.YYYY HH24:MI') "
            "FROM tenant.bank_platak WHERE " + cond +
            " ORDER BY datum_vytvoreni DESC NULLS LAST, id DESC LIMIT 300"), params).fetchall()
        _fk = {1: "EC", 2: "ES"}
        out = []
        for r in rows:
            frm = int(r[1]) if r[1] is not None else 0
            out.append({"id": int(r[0]), "firma": frm, "firma_kod": _fk.get(frm, "?"),
                        "typ": r[2], "mena": r[3], "stav": r[4] or "", "soubor": r[5], "cesta": r[6],
                        "pocet": int(r[7]), "suma": float(r[8]) if r[8] is not None else 0.0,
                        "datum": r[9] or "", "vytvoreno": r[10] or ""})
        return {"ok": True, "importy": out, "pocet": len(out)}
    finally:
        s.close()


@api_router.get("/app/platby/faktury")
def platby_faktury_get(req: Request):
    """Kompletní přehled PŘIJATÝCH faktur pro Peťu (rok 2025+2026) — zaplacené i nezaplacené.
    Data z `oz_pf_platba` (EC, vč. ES řad). Firma odvozena z ŘADY (ES=501/531/541, jinak EC).
    Stav = otevřené saldo (částka − naše úhrady oz_uhrady). Marti 7.7.2026. Scope rodiče+Petra(18)+cockpit."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        if not (uid and (_is_parent(s, uid) or int(uid) == 18 or _is_cockpit(s, uid))):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        firma = (req.query_params.get("firma") or "all").strip()
        stav = (req.query_params.get("stav") or "open").strip()   # open | all
        params = {}
        _uf = "(CASE WHEN p.rada IN ('501','531','541') THEN 2 ELSE 1 END)"
        _open = "((CASE WHEN p.mena='CZK' THEN p.suma_kc ELSE p.suma_val END) - COALESCE(u.paid,0))"
        conds = ["p.realizovano=1", "p.rada NOT LIKE '52%'", "p.dat_porizeni::date >= DATE '2025-01-01'"]
        if firma in ("1", "2"):
            params["ff"] = int(firma); conds.append(_uf + " = :ff")
        if stav == "open":
            conds.append(_open + " > 0.5")
        base = ("FROM tenant.oz_pf_platba p "
                "LEFT JOIN (SELECT id_fak, SUM(castka) paid FROM ("
                "  SELECT id_fak, castka_po_bance AS castka FROM tenant.oz_uhrady WHERE firma=1"
                "  UNION ALL SELECT id_fak, castka FROM tenant.platak_uhrada_lock) x GROUP BY id_fak) u "
                "  ON u.id_fak=p.id WHERE " + " AND ".join(conds))
        s.execute(_t("CREATE TABLE IF NOT EXISTS tenant.platak_navrh "
                     "(id_fak bigint PRIMARY KEY, firma int, added_by int, added_at timestamptz DEFAULT now())"))
        s.commit()
        rows = s.execute(_t(
            "SELECT p.doklad, " + _uf + " ufirma, COALESCE(NULLIF(p.dodavatel,''),p.zkratka,'?') dod, "
            "  COALESCE(p.var_symbol,'') vs, p.mena, to_char(p.splatnost::date,'DD.MM.YYYY') splat, "
            "  (CASE WHEN p.mena='CZK' THEN p.suma_kc ELSE p.suma_val END) castka, " + _open + " open_saldo, "
            "  (p.splatnost::date - now()::date) dni, "
            "  p.rada, p.poradove_cislo, COALESCE(p.realizovano,0) realizovano, COALESCE(p.uctovano,0) uctovano, "
            "  p.fin_schvaleni schvaleno, p.fin_zakaz zakaz, EXISTS(SELECT 1 FROM tenant.platak_navrh n WHERE n.id_fak=p.id) navrh, "
            "  COALESCE(p.uziv_ok,0) uziv_ok, p.suma_uhrad, "
            "  to_char(NULLIF(p.dat_uhrady,'')::date,'DD.MM.YYYY') dat_uhrady, "
            "  EXISTS(SELECT 1 FROM tenant.platak_uhrada_lock l WHERE l.id_fak=p.id) v_plataku, "
            "  EXISTS(SELECT 1 FROM tenant.bank_transaction_raw t WHERE t.par_metoda='platak' AND t.par_doklad_id=p.id) bank_vypis, "
            "  p.skonto, to_char(NULLIF(p.skonto_do,'')::date,'DD.MM.YYYY') skonto_do, p.id id_fak, "
            # čeká na výpis = má úhradu z platáku (puvod=3) a NEMÁ úhradu z bankovního výpisu (puvod=4). Peta+Claude 14.7.2026
            "  EXISTS(SELECT 1 FROM tenant.oz_uhrady u WHERE u.id_fak=p.id AND u.puvod=3) uhr_platak, "
            "  EXISTS(SELECT 1 FROM tenant.oz_uhrady u WHERE u.id_fak=p.id AND u.puvod=4) uhr_vypis "
            + base +
            " ORDER BY p.splatnost::date DESC NULLS LAST, p.id DESC LIMIT 1000"), params).fetchall()
        out = []
        for r in rows:
            sal = float(r[7]) if r[7] is not None else 0.0
            vp = bool(r[19]); bv = bool(r[20])
            out.append({"doklad": r[0] or "", "firma": int(r[1]), "dodavatel": r[2] or "",
                        "vs": r[3] or "", "mena": r[4] or "CZK", "splatnost": r[5],
                        "castka": round(float(r[6]), 2) if r[6] is not None else 0.0,
                        "saldo": round(sal, 2), "dni": int(r[8]) if r[8] is not None else None,
                        "zaplaceno": sal <= 0.5,
                        "rada": r[9] or "", "por_cislo": r[10],
                        "realizovano": bool(r[11]), "uctovano": bool(r[12]), "schvaleno": bool(r[13]),
                        "zakaz": bool(r[14]), "navrh": bool(r[15]), "uziv_ok": bool(r[16]),
                        "suma_uhrad": round(float(r[17]), 2) if r[17] is not None else 0.0,
                        "dat_uhrady": r[18] or "", "v_plataku": vp, "bank_vypis": bv,
                        "banka_export": vp, "ceka_vypis": (bool(r[24]) and not bool(r[25])),
                        "skonto": (round(float(r[21]), 2) if r[21] is not None else None),
                        "skonto_do": r[22] or "", "id_fak": int(r[23]) if r[23] is not None else None})
        agg = s.execute(_t("SELECT p.mena, count(*) n, SUM(" + _open + ") open_sum " + base + " GROUP BY p.mena"),
                        params).fetchall()
        sums = {row[0]: {"pocet": int(row[1]), "otevreno": round(float(row[2] or 0), 2)} for row in agg}
        total = int(sum(int(row[1]) for row in agg))
        try:
            _sync_at = s.execute(_t("SELECT to_char(last_sync_at,'DD.MM. HH24:MI') FROM tenant.oz_mirror_def "
                                    "WHERE oz_table='oz_pf_platba'")).scalar()
        except Exception:
            _sync_at = None
        return {"ok": True, "faktury": out, "sums": sums, "total": total, "shown": len(out), "sync_at": _sync_at}
    finally:
        s.close()


@api_router.post("/app/platby/navrh-toggle")
async def platby_navrh_toggle(req: Request):
    """Ruční výběr faktur k platbě — zapíše/smaže příznak Návrh v tenant.platak_navrh (vzniká U NÁS, nezrcadlí se z Centrály).
    Vstup JSON: {ids:[id_fak,...], stav:'on'|'off'}. Scope rodiče+Petra(18)+cockpit. Peta+Claude 13.7.2026."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        if not (uid and (_is_parent(s, uid) or int(uid) == 18 or _is_cockpit(s, uid))):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
        try:
            body = await req.json()
        except Exception:
            body = {}
        ids = body.get("ids") or []
        stav = (body.get("stav") or "on").strip()
        ids = [int(x) for x in ids if str(x).strip() not in ("", "None", "null")]
        if not ids:
            return JSONResponse({"ok": False, "error": "žádné faktury"}, status_code=400)
        try:
            _role = s.execute(_t("SELECT current_user")).scalar()
        except Exception:
            _role = "?"
        try:
            s.execute(_t("CREATE TABLE IF NOT EXISTS tenant.platak_navrh "
                         "(id_fak bigint PRIMARY KEY, firma int, added_by int, added_at timestamptz DEFAULT now())"))
            if stav == "off":
                _res = s.execute(_t("DELETE FROM tenant.platak_navrh WHERE id_fak = ANY(:ids)"), {"ids": ids})
            else:
                _uf = "(CASE WHEN p.rada IN ('501','531','541') THEN 2 ELSE 1 END)"
                _res = s.execute(_t(
                    "INSERT INTO tenant.platak_navrh (id_fak, firma, added_by) "
                    "SELECT p.id, " + _uf + ", :uid FROM tenant.oz_pf_platba p "
                    "WHERE p.id = ANY(:ids) ON CONFLICT (id_fak) DO NOTHING"),
                    {"ids": ids, "uid": int(uid)})
            s.commit()
            _aff = _res.rowcount if _res is not None else -1
            n = s.execute(_t("SELECT count(*) FROM tenant.platak_navrh")).scalar()
        except Exception as _e:
            try:
                s.rollback()
            except Exception:
                pass
            return JSONResponse({"ok": False, "error": "DB[" + str(_role) + "]: " + str(_e)[:400], "role": _role}, status_code=200)
        return {"ok": True, "stav": stav, "dotceno": len(ids), "zapsano": int(_aff), "role": _role, "celkem_navrh": int(n or 0)}
    finally:
        s.close()


