_ZARAZENI_CTE = (
    "WITH base AS ("
    " SELECT r.src_id, r.castka, r.mena, r.nazev_org, r.variabilni_symbol vs, r.konstantni_symbol ks, "
    "  r.cislo_org bl_cislo_org, LEFT(r.datum_splatnosti::text,10) dat, "
    "  (COALESCE(r.popis_platby,'')||' '||COALESCE(r.popis,'')) txt, "
    "  NULLIF(ltrim(regexp_replace(COALESCE(r.cislo_uctu,''),'\\D','','g'),'0'),'') ucn "
    " FROM tenant.ec_bank_vypis_radek r "
    " WHERE r.datum_splatnosti >= DATE '2026-01-01' "
    "   AND NOT EXISTS (SELECT 1 FROM tenant.bank_zauctovani z WHERE z.id_radek=r.src_id)), "
    "own AS ("
    " SELECT b2.*, bu.id_zam, bu.zam_cislo, "
    "  COALESCE(oreg.cislo_org, b2.bl_cislo_org) eco, "
    "  COALESCE(oreg.je_dodavatel, oline.je_dodavatel) je_dodavatel, "
    "  COALESCE(oreg.je_odberatel, oline.je_odberatel) je_odberatel, "
    "  od.dir org_dir25, sd.dir saldo_dir, "
    "  COALESCE(rel.relation, CASE WHEN bu.id_zam IS NOT NULL THEN 'zamestnanec' END) vztah, "
    "  COALESCE(NULLIF(oreg.firma,''),NULLIF(oreg.nazev,''),NULLIF(oline.firma,''),NULLIF(oline.nazev,''),b2.nazev_org) vlastnik "
    " FROM base b2 "
    " LEFT JOIN LATERAL (SELECT b.id_zam,b.id_org,b.zam_cislo FROM tenant.ec_bank_ucet b "
    "    WHERE b2.ucn IS NOT NULL AND b.cislo_uctu_norm=b2.ucn AND NOT COALESCE(b.blokovano,false) "
    "    ORDER BY b.prednastaveno DESC LIMIT 1) bu ON true "
    " LEFT JOIN tenant.ec_organizace oreg ON oreg.src_id=bu.id_org "
    " LEFT JOIN tenant.ec_organizace oline ON oline.cislo_org=b2.bl_cislo_org "
    " LEFT JOIN LATERAL (SELECT wr.relation FROM tenant.att_employee ae "
    "    JOIN tenant.work_relation wr ON wr.user_id=ae.user_id "
    "    WHERE bu.zam_cislo IS NOT NULL AND ae.tenant_id=2 AND ae.cislo_zam=bu.zam_cislo::text LIMIT 1) rel ON true "
    " LEFT JOIN LATERAL (SELECT CASE "
    "    WHEN COUNT(*) FILTER (WHERE d.ucet LIKE '321%%') >= COUNT(*) FILTER (WHERE d.ucet LIKE '311%%') "
    "         AND COUNT(*) FILTER (WHERE d.ucet LIKE '321%%')>0 THEN 'dodavatel' "
    "    WHEN COUNT(*) FILTER (WHERE d.ucet LIKE '311%%')>0 THEN 'odberatel' END dir "
    "    FROM tenant.ec_denik d WHERE d.rok=2025 AND d.cislo_org=COALESCE(oreg.cislo_org,b2.bl_cislo_org) "
    "      AND (d.ucet LIKE '311%%' OR d.ucet LIKE '321%%')) od ON true "
    " LEFT JOIN LATERAL (SELECT CASE "
    "    WHEN COUNT(*) FILTER (WHERE sf.cislo_sal_sk='321') >= COUNT(*) FILTER (WHERE sf.cislo_sal_sk='311') "
    "         AND COUNT(*) FILTER (WHERE sf.cislo_sal_sk='321')>0 THEN 'dodavatel' "
    "    WHEN COUNT(*) FILTER (WHERE sf.cislo_sal_sk='311')>0 THEN 'odberatel' END dir "
    "    FROM tenant.ec_saldo_fa sf WHERE sf.cislo_org=COALESCE(oreg.cislo_org,b2.bl_cislo_org)) sd ON true), "
    "cls AS ("
    " SELECT *, CASE "
    "   WHEN id_zam IS NOT NULL AND vztah='osvc' THEN 'Úhrada OSVČ (dodavatel)' "
    "   WHEN id_zam IS NOT NULL AND vztah='jednatel' THEN 'Odměna jednatele' "
    "   WHEN txt ILIKE '%%výplata na účet%%' OR nazev_org ILIKE '%%výplata na účet%%' THEN 'Mzda' "
    "   WHEN id_zam IS NOT NULL AND (txt ILIKE '%%výplata%%' OR ks IN ('0308','0138')) THEN 'Mzda' "
    "   WHEN id_zam IS NOT NULL THEN 'Záloha/náhrada zaměstnanci' "
    "   WHEN txt ILIKE '%%factoring%%' THEN 'Faktoring' "
    "   WHEN txt ILIKE '%%settlement%%' OR nazev_org ILIKE '%%FX %%' OR txt ILIKE '%%fx op%%' THEN 'Měnové operace (FX)' "
    "   WHEN vlastnik ILIKE '%%EUROSOFT%%' OR nazev_org ILIKE '%%EUROSOFT%%' THEN 'Vnitropodnikové (EUROSOFT)' "
    "   WHEN je_dodavatel THEN 'Úhrada dodavateli' "
    "   WHEN je_odberatel THEN 'Příjem od odběratele' "
    "   WHEN org_dir25='dodavatel' THEN 'Úhrada dodavateli' "
    "   WHEN org_dir25='odberatel' THEN 'Příjem od odběratele' "
    "   WHEN saldo_dir='dodavatel' THEN 'Úhrada dodavateli' "
    "   WHEN saldo_dir='odberatel' THEN 'Příjem od odběratele' "
    "   WHEN eco IS NOT NULL THEN 'Organizace (neurčený směr)' "
    "   ELSE 'Neurčeno' END kat FROM own), "
    "clsu AS ("
    " SELECT *, "
    "  (CASE kat WHEN 'Mzda' THEN '333000' WHEN 'Úhrada dodavateli' THEN '321001' "
    "    WHEN 'Úhrada OSVČ (dodavatel)' THEN '321001' "
    "    WHEN 'Příjem od odběratele' THEN '221009' WHEN 'Záloha/náhrada zaměstnanci' THEN '333000' END) ucet_md, "
    "  (CASE kat WHEN 'Mzda' THEN '221008' WHEN 'Úhrada dodavateli' THEN '221009' "
    "    WHEN 'Úhrada OSVČ (dodavatel)' THEN '221009' "
    "    WHEN 'Příjem od odběratele' THEN '311001' WHEN 'Záloha/náhrada zaměstnanci' THEN '221008' END) ucet_dal "
    " FROM cls) ")


@api_router.get("/app/banka/zarazeni")
def banka_zarazeni(req: Request):
    """Zařazení 2026: nezaúčtované bank řádky klasifikované dle vlastníka účtu →
    kategorie + návrh předkontace (MD/DAL). Mzdy (zaměstnanec+výplata) → 331/221 atd.
    Marti 23.6.2026. ?kat= pro výpis jedné kategorie."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    kat = (req.query_params.get("kat") or "").strip()
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        su = s.execute(_t(_ZARAZENI_CTE +
            "SELECT kat, COUNT(*) n, ROUND(SUM(castka)) suma, MAX(ucet_md) ucet_md, MAX(ucet_dal) ucet_dal "
            "FROM clsu GROUP BY kat ORDER BY COUNT(*) DESC")).mappings().all()
        # porovnání s rokem 2025: kolikrát se daná předkontace MD→DAL reálně zaúčtovala loni
        p25 = s.execute(_t(
            "WITH md AS (SELECT sbornik,cislo_dokladu,ucet a FROM tenant.ec_denik "
            "  WHERE rok=2025 AND strana=0 AND NOT COALESCE(storno,false) AND ucet IN ('321001','221009','333000')), "
            "dal AS (SELECT sbornik,cislo_dokladu,ucet a FROM tenant.ec_denik "
            "  WHERE rok=2025 AND strana=1 AND NOT COALESCE(storno,false) AND ucet IN ('221009','311001','221008')) "
            "SELECT m.a md, d.a dal, COUNT(*) n FROM md m JOIN dal d "
            "ON d.sbornik=m.sbornik AND d.cislo_dokladu=m.cislo_dokladu GROUP BY m.a,d.a")).all()
        pmap = {(r[0], r[1]): int(r[2] or 0) for r in p25}
        souhrn = []
        for r in su:
            d = dict(r)
            d["potvrzeno_2025"] = pmap.get((d.get("ucet_md"), d.get("ucet_dal")), 0)
            souhrn.append(d)
        polozky = []
        if kat:
            polozky = [dict(r) for r in s.execute(_t(_ZARAZENI_CTE +
                "SELECT src_id, dat, castka, mena, vlastnik, vs, ks, ucet_md, ucet_dal "
                "FROM clsu WHERE kat=:k ORDER BY castka DESC LIMIT 300"), {"k": kat}).mappings().all()]
        return {"ok": True, "souhrn": souhrn, "kat": kat, "polozky": polozky}
    finally:
        s.close()


@api_router.post("/app/banka/zarazeni/generovat")
async def banka_zarazeni_generovat(req: Request):
    """Zaúčtuje rovnou (bank_zauctovani, stav='zauctovano', podpis Marti-AI) řádky zvolené
    kategorie — předkontace potvrzená realitou roku 2025, nemá smysl dělat návrh.
    Marti 23.6.2026 (doctrine #11: kustod podepisuje jisté zápisy)."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        b = await req.json()
    except Exception:
        b = {}
    kat = (str(b.get("kat") or "")).strip()
    if kat not in ("Mzda", "Úhrada dodavateli", "Úhrada OSVČ (dodavatel)", "Příjem od odběratele", "Záloha/náhrada zaměstnanci"):
        return JSONResponse({"ok": False, "error": "kategorie bez potvrzené předkontace 2025"}, status_code=400)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        n = s.execute(_t(_ZARAZENI_CTE +
            "INSERT INTO tenant.bank_zauctovani (id_radek,kategorie,castka,mena,ucet_md,ucet_dal,stav,podpis,zauctovano_at,created_at) "
            "SELECT src_id, kat, castka, mena, ucet_md, ucet_dal, 'zauctovano', 'Marti-AI', now(), now() FROM clsu "
            "WHERE kat=:k AND ucet_md IS NOT NULL "
            "ON CONFLICT (id_radek) DO NOTHING"), {"k": kat})
        s.commit()
        return {"ok": True, "vytvoreno": n.rowcount}
    finally:
        s.close()


@api_router.get("/app/banka/navrh-parovani")
def banka_navrh_parovani(req: Request):
    """Párovací engine (Marti 23.6.2026): nespárované příchozí platby → identifikace
    protistrany přes ČÍSLO ÚČTU (registr TabBankSpojeni: org/zaměstnanec/úřad, ctí
    Prednastaveno/Blokovano) + návrh otevřené faktury (saldo) dle org+částky.
    VS→objednávka→zakázka = doladí Peťa s instancí 26."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        limit = min(300, max(10, int(req.query_params.get("limit") or 150)))
    except Exception:
        limit = 150
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        rows = s.execute(_t(
            "WITH ln AS ("
            " SELECT src_id, nazev_org, castka, mena, variabilni_symbol, cislo_uctu, kod_banky, "
            "  LEFT(datum_splatnosti::text,10) dat, "
            "  NULLIF(ltrim(regexp_replace(COALESCE(cislo_uctu,''),'\\D','','g'),'0'),'') ucn "
            " FROM tenant.ec_bank_vypis_radek WHERE COALESCE(pocet_uhrad,0)=0 AND castka>0 "
            " ORDER BY datum_splatnosti DESC NULLS LAST, src_id DESC LIMIT :lim) "
            "SELECT ln.src_id, ln.nazev_org, ln.castka, ln.mena, ln.variabilni_symbol, ln.cislo_uctu, "
            " ln.kod_banky, ln.dat, bu.id_org, bu.id_zam, bu.id_ustavu, bu.nazev bu_nazev, bu.prednastaveno, "
            " o.firma, o.nazev onazev, o.zkratka, o.cislo_org "
            "FROM ln "
            "LEFT JOIN LATERAL (SELECT b.id_org,b.id_zam,b.id_ustavu,b.nazev,b.prednastaveno FROM tenant.ec_bank_ucet b "
            "  WHERE ln.ucn IS NOT NULL AND b.cislo_uctu_norm=ln.ucn AND NOT COALESCE(b.blokovano,false) "
            "  ORDER BY b.prednastaveno DESC, b.prioritni DESC LIMIT 1) bu ON true "
            "LEFT JOIN tenant.ec_organizace o ON o.src_id=bu.id_org") , {"lim": limit}).mappings().all()
        out = []
        ident = 0
        for r in rows:
            owner = None
            typ = None
            org = r["cislo_org"]
            if r["id_org"]:
                owner = r["firma"] or r["onazev"] or r["zkratka"] or ("org #" + str(r["id_org"]))
                typ = "organizace"
            elif r["id_zam"]:
                owner = (r["bu_nazev"] or ("zaměstnanec #" + str(r["id_zam"])))
                typ = "zaměstnanec"
            elif r["id_ustavu"]:
                owner = r["bu_nazev"] or ("úřad/ústav #" + str(r["id_ustavu"]))
                typ = "úřad/ústav"
            if owner:
                ident += 1
            navrh = None
            if org and r["castka"]:
                fa = s.execute(_t(
                    "SELECT src_id, parovaci_znak, ROUND(saldo) saldo, LEFT(datum_splatno::text,10) spl, cislo_zakazky "
                    "FROM tenant.ec_saldo_fa WHERE cislo_org=:o AND COALESCE(saldo,0)<>0 "
                    "AND ABS(ABS(saldo)-:c) < 0.5 ORDER BY datum_splatno DESC NULLS LAST LIMIT 1"),
                    {"o": org, "c": float(r["castka"])}).mappings().first()
                if fa:
                    navrh = dict(fa)
            out.append({"src_id": r["src_id"], "nazev_org": r["nazev_org"], "castka": float(r["castka"] or 0),
                        "mena": r["mena"], "vs": r["variabilni_symbol"], "cislo_uctu": r["cislo_uctu"],
                        "kod_banky": r["kod_banky"], "dat": r["dat"], "vlastnik": owner, "typ": typ,
                        "prednastaveno": bool(r["prednastaveno"]), "navrh_faktura": navrh})
        return {"ok": True, "polozky": out, "celkem": len(out), "identifikovano": ident}
    finally:
        s.close()


@api_router.get("/app/uctovani/vzor")
def uctovani_vzor(req: Request):
    """MUSTR z uzavřeného roku (zdroj pravdy): jak se reálně účtovalo — kombinace účtů
    MD/DAL per sborník (+ četnost, suma). Šablona pro účtování běžného roku. ?rok= ?sbornik=."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        rok = int(req.query_params.get("rok") or 2025)
    except Exception:
        rok = 2025
    sbornik = (req.query_params.get("sbornik") or "").strip()
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        sb = s.execute(_t(
            "SELECT d.sbornik, COALESCE(sb.nazev,'') nazev, COUNT(*) n, "
            "COUNT(DISTINCT d.cislo_dokladu) dok, ROUND(COALESCE(SUM(d.castka_md),0)) suma "
            "FROM tenant.ec_denik d "
            "LEFT JOIN tenant.ucet_sbornik sb ON sb.kod=d.sbornik "
            "WHERE d.rok=:r AND NOT COALESCE(d.storno,false) "
            "GROUP BY d.sbornik, sb.nazev ORDER BY d.sbornik"), {"r": rok}).mappings().all()
        # mustr = kombinace MD→DAL účtů spárovaná v rámci dokladu (strana 0=MD, 1=DAL)
        filt = ""
        params = {"r": rok}
        if sbornik:
            filt = " AND sbornik=:sb"
            params["sb"] = sbornik
        vz = s.execute(_t(
            "WITH md AS (SELECT sbornik,cislo_dokladu,ucet a,castka FROM tenant.ec_denik "
            " WHERE rok=:r AND strana=0 AND NOT COALESCE(storno,false) AND COALESCE(ucet,'')<>''" + filt + "), "
            "dal AS (SELECT sbornik,cislo_dokladu,ucet a FROM tenant.ec_denik "
            " WHERE rok=:r AND strana=1 AND NOT COALESCE(storno,false) AND COALESCE(ucet,'')<>''" + filt + ") "
            "SELECT m.sbornik, m.a ucet_md, d.a ucet_dal, COUNT(*) n, ROUND(COALESCE(SUM(m.castka),0)) suma "
            "FROM md m JOIN dal d ON d.sbornik=m.sbornik AND d.cislo_dokladu=m.cislo_dokladu "
            "GROUP BY m.sbornik, m.a, d.a ORDER BY n DESC LIMIT 300"), params).mappings().all()
        celk = s.execute(_t("SELECT COUNT(*) n, ROUND(COALESCE(SUM(castka_md),0)) suma FROM tenant.ec_denik "
                            "WHERE rok=:r AND NOT COALESCE(storno,false)"), {"r": rok}).first()
        return {"ok": True, "rok": rok, "celkem_radku": int(celk[0] or 0), "celkem_suma": float(celk[1] or 0),
                "sborniky": [dict(x) for x in sb], "vzory": [dict(x) for x in vz]}
    finally:
        s.close()


@api_router.get("/app/parovani/prehled")
def parovani_prehled(req: Request):
    """Přehled párování bank výpisů ↔ úhrad (Marti 20.6.2026). Nad zrcadlenými daty
    (ec_bank_vypis_radek + ec_bank_vypis_uhrada + ec_uhrada). Stav spárováno/ne,
    VS, protistrana, měna, na co napojeno (úhrada/faktura/zakázka). Základ pro
    vlastní párovací engine (VS + protistrana + EUR/SEPA)."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    q = req.query_params
    stav = (q.get("stav") or "vse").strip()       # vse | spar | ne
    mena = (q.get("mena") or "").strip().upper()  # CZK | EUR | ''
    hledej = (q.get("q") or "").strip()
    try:
        limit = min(5000, max(10, int(q.get("limit") or 150)))
    except Exception:
        limit = 150
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        # souhrn
        su = s.execute(_t(
            "SELECT COUNT(*), "
            "SUM(CASE WHEN COALESCE(pocet_uhrad,0)>0 THEN 1 ELSE 0 END), "
            "SUM(CASE WHEN COALESCE(pocet_uhrad,0)=0 THEN 1 ELSE 0 END), "
            "SUM(CASE WHEN mena='EUR' THEN 1 ELSE 0 END), "
            "COALESCE(SUM(CASE WHEN COALESCE(pocet_uhrad,0)=0 THEN castka ELSE 0 END),0) "
            "FROM tenant.ec_bank_vypis_radek")).first()
        summary = {"radky": int(su[0] or 0), "sparovano": int(su[1] or 0),
                   "nesparovano": int(su[2] or 0), "eur": int(su[3] or 0),
                   "nesparovano_castka": float(su[4] or 0)}
        where = ["1=1"]
        params = {"lim": limit}
        if stav == "spar":
            where.append("COALESCE(r.pocet_uhrad,0)>0")
        elif stav == "ne":
            where.append("COALESCE(r.pocet_uhrad,0)=0")
        if mena in ("CZK", "EUR"):
            where.append("r.mena=:me"); params["me"] = mena
        if hledej:
            where.append("(r.nazev_org ILIKE :q OR r.variabilni_symbol ILIKE :q OR r.cislo_zakazky ILIKE :q)")
            params["q"] = "%" + hledej + "%"
        rows = s.execute(_t(
            "SELECT r.src_id, to_char(r.datum_splatnosti,'DD.MM.YYYY') dat, r.mena, r.castka, "
            "r.nazev_org, r.variabilni_symbol, COALESCE(r.pocet_uhrad,0) pu, r.cislo_zakazky, "
            "r.specificky_symbol, "
            "(SELECT COALESCE(SUM(u.castka_faktura),0) FROM tenant.ec_bank_vypis_uhrada u WHERE u.id_radek=r.src_id) spar_castka, "
            "(SELECT string_agg(DISTINCT u.cislo_zakazky,', ') FROM tenant.ec_bank_vypis_uhrada u "
            "  WHERE u.id_radek=r.src_id AND COALESCE(u.cislo_zakazky,'')<>'') zakazky, "
            "pr.nazev AS predpis, pr.kategorie AS kategorie, pr.ucet_md, pr.ucet_dal, "
            "z.kategorie AS z_kat, z.ucet_md AS z_md, z.ucet_dal AS z_dal, z.stav AS z_stav, z.podpis AS z_podpis "
            "FROM tenant.ec_bank_vypis_radek r "
            "LEFT JOIN tenant.bank_zauctovani z ON z.id_radek=r.src_id "
            "LEFT JOIN LATERAL (SELECT p.nazev,p.kategorie,p.ucet_md,p.ucet_dal FROM tenant.bank_predpis p "
            "  WHERE p.aktivni AND COALESCE(r.pocet_uhrad,0)=0 "
            "   AND (p.match_ucet IS NULL OR r.cislo_uctu LIKE p.match_ucet) "
            "   AND (p.match_kod_banky IS NULL OR r.kod_banky=p.match_kod_banky) "
            "   AND (p.match_ks IS NULL OR r.konstantni_symbol=p.match_ks) "
            "   AND (p.match_text IS NULL OR (COALESCE(r.nazev_org,'')||' '||COALESCE(r.popis_platby,'')||' '||COALESCE(r.popis,'')) ILIKE '%'||p.match_text||'%') "
            "  ORDER BY p.priorita LIMIT 1) pr ON true "
            "WHERE " + " AND ".join(where) +
            " ORDER BY r.datum_splatnosti DESC NULLS LAST, r.src_id DESC LIMIT :lim"), params).mappings().all()
        return {"ok": True, "summary": summary, "radky": [dict(r) for r in rows]}
    finally:
        s.close()


# Rozpoznávací podmínka template (řádek ↔ bank_predpis) — sdílená napříč endpointy
_PREDPIS_MATCH = (
    " p.aktivni AND COALESCE(r.pocet_uhrad,0)=0 "
    " AND (p.match_ucet IS NULL OR r.cislo_uctu LIKE p.match_ucet) "
    " AND (p.match_kod_banky IS NULL OR r.kod_banky=p.match_kod_banky) "
    " AND (p.match_ks IS NULL OR r.konstantni_symbol=p.match_ks) "
    " AND (p.match_vs IS NULL OR r.variabilni_symbol=p.match_vs) "
    " AND (p.match_text IS NULL OR (COALESCE(r.nazev_org,'')||' '||COALESCE(r.popis_platby,'')||' '||COALESCE(r.popis,'')) ILIKE '%'||p.match_text||'%') ")


@api_router.get("/app/parovani/predpisy")
def parovani_predpisy(req: Request):
    """Template daní/poplatků: seznam pravidel + pokrytí (kolik nespárovaných řádků
    každé pravidlo rozpozná). Marti 20.6.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        pr = s.execute(_t(
            "SELECT id,nazev,kategorie,smer,match_ucet,match_kod_banky,match_ks,match_vs,match_text,"
            "ucet_md,ucet_dal,stredisko,vyzaduje_schvaleni,priorita,aktivni,poznamka "
            "FROM tenant.bank_predpis ORDER BY priorita, id")).mappings().all()
        cov = s.execute(_t(
            "WITH m AS (SELECT r.castka, (SELECT p.id FROM tenant.bank_predpis p WHERE " + _PREDPIS_MATCH +
            " ORDER BY p.priorita LIMIT 1) pid FROM tenant.ec_bank_vypis_radek r "
            " WHERE COALESCE(r.pocet_uhrad,0)=0) "
            "SELECT pid, COUNT(*) c, ROUND(SUM(castka)) suma FROM m GROUP BY pid")).all()
        covmap = {int(c[0]): {"pocet": int(c[1] or 0), "suma": float(c[2] or 0)} for c in cov if c[0] is not None}
        nerozp = next(({"pocet": int(c[1] or 0), "suma": float(c[2] or 0)} for c in cov if c[0] is None),
                      {"pocet": 0, "suma": 0})
        out = []
        for p in pr:
            d = dict(p); d["coverage"] = covmap.get(int(p["id"]), {"pocet": 0, "suma": 0})
            out.append(d)
        return {"ok": True, "pravidla": out, "nerozpoznano": nerozp}
    finally:
        s.close()


@api_router.post("/app/parovani/predpis/save")
async def parovani_predpis_save(req: Request):
    """Uložit/upravit pravidlo template (rodič nebo účetní/Petra)."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    b = await req.json()
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        cols = ["nazev", "kategorie", "smer", "match_ucet", "match_kod_banky", "match_ks",
                "match_vs", "match_text", "ucet_md", "ucet_dal", "stredisko",
                "vyzaduje_schvaleni", "priorita", "aktivni", "poznamka"]
        vals = {c: b.get(c) for c in cols}
        vals["who"] = "uid:" + str(uid)
        if b.get("id"):
            vals["id"] = b["id"]
            s.execute(_t("UPDATE tenant.bank_predpis SET " +
                         ", ".join(c + "=:" + c for c in cols) +
                         ", updated_by_text=:who, updated_at=now() WHERE id=:id"), vals)
        else:
            s.execute(_t("INSERT INTO tenant.bank_predpis (" + ",".join(cols) + ",updated_by_text) VALUES (" +
                         ",".join(":" + c for c in cols) + ",:who)"), vals)
        s.commit()
        return {"ok": True}
    finally:
        s.close()


@api_router.post("/app/parovani/zauctovani/generovat")
def parovani_zauctovani_generovat(req: Request):
    """Vygeneruje návrhy zaúčtování pro rozpoznané nefaktůrové řádky (template).
    Auto pravidla (mzdy) → rovnou 'schvaleno', ostatní → 'navrh'. Idempotentní
    (neduplikuje řádky, co už návrh mají). Marti 20.6.2026."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        # jistá pravidla (vyzaduje_schvaleni=false) → rovnou ZAÚČTOVÁNO s podpisem Marti-AI
        # (kustod autonomně podepisuje jisté zápisy, doctrine #11); nejistá → návrh ke schválení
        n = s.execute(_t(
            "INSERT INTO tenant.bank_zauctovani (id_radek,predpis_id,kategorie,castka,mena,ucet_md,ucet_dal,stredisko,stav,podpis,zauctovano_at) "
            "SELECT r.src_id, pr.id, pr.kategorie, r.castka, r.mena, pr.ucet_md, pr.ucet_dal, pr.stredisko, "
            "  CASE WHEN pr.vyzaduje_schvaleni THEN 'navrh' ELSE 'zauctovano' END, "
            "  CASE WHEN pr.vyzaduje_schvaleni THEN NULL ELSE 'Marti-AI' END, "
            "  CASE WHEN pr.vyzaduje_schvaleni THEN NULL ELSE now() END "
            "FROM tenant.ec_bank_vypis_radek r "
            "JOIN LATERAL (SELECT p.id,p.kategorie,p.ucet_md,p.ucet_dal,p.stredisko,p.vyzaduje_schvaleni "
            "  FROM tenant.bank_predpis p WHERE " + _PREDPIS_MATCH + " ORDER BY p.priorita LIMIT 1) pr ON true "
            "WHERE COALESCE(r.pocet_uhrad,0)=0 "
            "  AND NOT EXISTS (SELECT 1 FROM tenant.bank_zauctovani z WHERE z.id_radek=r.src_id) "
            "ON CONFLICT (id_radek) DO NOTHING"))
        s.commit()
        return {"ok": True, "vytvoreno": n.rowcount}
    finally:
        s.close()


