@api_router.get("/app/parovani/denik")
def parovani_denik(req: Request):
    """STRATEGIE účetní deník — reálné zápisy z auto-účtování (zdroj=bank_zauctovani).
    Dvojitý zápis MD/DAL, podpis. Souhrn po účtech MD + výpis. Marti 20.6.2026
    (volba „obojí — zrcadlit": náš deník = zdroj pravdy, Helios mirror = další krok)."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    q = req.query_params
    kat = (q.get("kategorie") or "").strip()
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        summ = s.execute(_t(
            "SELECT ucet_md, ucet_dal, kategorie, COUNT(*), ROUND(SUM(castka)) "
            "FROM tenant.ucetni_denik WHERE NOT storno GROUP BY ucet_md, ucet_dal, kategorie "
            "ORDER BY SUM(castka) DESC")).all()
        souhrn = [{"ucet_md": r[0], "ucet_dal": r[1], "kategorie": r[2],
                   "pocet": int(r[3] or 0), "suma": float(r[4] or 0)} for r in summ]
        celk = s.execute(_t(
            "SELECT COUNT(*), ROUND(SUM(castka)), SUM(CASE WHEN helios_synced THEN 1 ELSE 0 END) "
            "FROM tenant.ucetni_denik WHERE NOT storno")).first()
        where = ["NOT storno"]
        params = {}
        if kat:
            where.append("kategorie=:k"); params["k"] = kat
        rows = s.execute(_t(
            "SELECT id, to_char(datum,'DD.MM.YYYY') dat, doklad, ucet_md, ucet_dal, castka, mena, "
            "popis, kategorie, podpis, helios_synced "
            "FROM tenant.ucetni_denik WHERE " + " AND ".join(where) +
            " ORDER BY datum DESC NULLS LAST, id DESC LIMIT 200"), params).mappings().all()
        return {"ok": True,
                "celkem": {"pocet": int(celk[0] or 0), "suma": float(celk[1] or 0),
                           "helios": int(celk[2] or 0)},
                "souhrn": souhrn, "polozky": [dict(r) for r in rows]}
    finally:
        s.close()


@api_router.get("/app/uctovani/mzdy")
def uctovani_mzdy(req: Request):
    """Mzdy & odvody — naúčtováno (závazek z deníku) vs zaplaceno (úhrada z banky) po měsících.
    Marti 23.6.2026: mzdy nepočítáme (Helios), ale účtujeme do deníku a párujeme bankovní platby
    za mzdy/odvody s deníkem. Účty 333 (čisté mzdy), 336 (pojištění), 342 (daň). EC."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        rok = int(req.query_params.get("rok") or 2025)
    except Exception:
        rok = 2025
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        rows = s.execute(_t(
            "SELECT EXTRACT(month FROM datum)::int m, "
            " CASE WHEN COALESCE(ucet_md,ucet_dal) LIKE '333%' THEN '333 čisté mzdy' "
            "      WHEN COALESCE(ucet_md,ucet_dal) LIKE '336%' THEN '336 pojištění' "
            "      WHEN COALESCE(ucet_md,ucet_dal) LIKE '342%' THEN '342 daň' END kat, "
            " ROUND(SUM(CASE WHEN ucet_dal IS NOT NULL THEN castka ELSE 0 END)) nauctovano, "
            " ROUND(SUM(CASE WHEN ucet_md IS NOT NULL THEN castka ELSE 0 END)) zaplaceno "
            "FROM tenant.ucetni_denik WHERE NOT storno AND EXTRACT(year FROM datum)=:r "
            " AND zdroj NOT IN ('bank_zauctovani','es_recon') "
            " AND (COALESCE(ucet_md,ucet_dal) LIKE '333%' OR COALESCE(ucet_md,ucet_dal) LIKE '336%' "
            "      OR COALESCE(ucet_md,ucet_dal) LIKE '342%') "
            "GROUP BY 1,2 ORDER BY 1,2"), {"r": rok}).all()
    finally:
        s.close()
    out = {}
    cel = {}
    for m, kat, nau, zap in rows:
        if not kat:
            continue
        m = int(m)
        out.setdefault(m, {})[kat] = {"nauctovano": float(nau or 0), "zaplaceno": float(zap or 0),
                                      "zustatek": float((nau or 0) - (zap or 0))}
        c = cel.setdefault(kat, {"nauctovano": 0.0, "zaplaceno": 0.0, "zustatek": 0.0})
        c["nauctovano"] += float(nau or 0); c["zaplaceno"] += float(zap or 0)
        c["zustatek"] += float((nau or 0) - (zap or 0))
    mesice = [{"mesic": m, "kat": out[m]} for m in sorted(out.keys())]
    return {"ok": True, "rok": rok, "mesice": mesice, "celkem": cel}


@api_router.get("/app/uctovani/predvaha")
def uctovani_predvaha(req: Request):
    """Obratová předvaha — porovnání obratů účtů NÁŠ deník (tenant.ucetni_denik) vs
    Helios (tenant.ec_denik) za rok. Cíl (Marti 23.6.2026): ladit předkontace a doklady,
    dokud se náš obraz stavů účtů nerovná Heliosu (EC). Měřicí nástroj rekonstrukce 2025/2026."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        rok = int(req.query_params.get("rok") or 2025)
    except Exception:
        rok = 2025
    firma = (req.query_params.get("firma") or "EC").upper()
    # ES = EUROSOFT-System (es_denik / es_recon); jinak EC = EUROSOFT-Control (Marti 23.6.2026).
    if firma == "ES":
        hel_tbl = "tenant.es_denik"
        our_filt = "zdroj LIKE 'es%'"
    else:
        hel_tbl = "tenant.ec_denik"
        our_filt = "zdroj <> 'bank_zauctovani' AND zdroj NOT LIKE 'es%'"
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        hel = s.execute(_t(
            "SELECT ucet, SUM(CASE WHEN strana=0 THEN castka ELSE 0 END) md, "
            "SUM(CASE WHEN strana=1 THEN castka ELSE 0 END) dal, COUNT(*) n "
            "FROM " + hel_tbl + " WHERE rok=:r AND NOT storno AND ucet IS NOT NULL GROUP BY ucet"),
            {"r": rok}).all()
        # baseline = věrný rekon; bankovní engine-experiment (bank_zauctovani) i druhá firma
        # se z baseline vyřazují, aby se nic nezdvojilo (Marti 23.6.2026).
        nmd = s.execute(_t(
            "SELECT ucet_md u, SUM(castka) v FROM tenant.ucetni_denik "
            "WHERE NOT storno AND EXTRACT(year FROM datum)=:r AND ucet_md IS NOT NULL "
            "AND " + our_filt + " GROUP BY ucet_md"),
            {"r": rok}).all()
        ndal = s.execute(_t(
            "SELECT ucet_dal u, SUM(castka) v FROM tenant.ucetni_denik "
            "WHERE NOT storno AND EXTRACT(year FROM datum)=:r AND ucet_dal IS NOT NULL "
            "AND " + our_filt + " GROUP BY ucet_dal"),
            {"r": rok}).all()
    finally:
        s.close()
    acc = {}
    for u, md, dal, n in hel:
        acc.setdefault(str(u), {})
        acc[str(u)].update(hmd=float(md or 0), hdal=float(dal or 0), hn=int(n or 0))
    for u, v in nmd:
        acc.setdefault(str(u), {})["nmd"] = float(v or 0)
    for u, v in ndal:
        acc.setdefault(str(u), {})["ndal"] = float(v or 0)
    rows = []
    sedi = 0
    for u, d in acc.items():
        hmd = d.get("hmd", 0.0); hdal = d.get("hdal", 0.0)
        nmdv = d.get("nmd", 0.0); ndalv = d.get("ndal", 0.0)
        dmd = nmdv - hmd; ddal = ndalv - hdal
        ok = abs(dmd) < 1 and abs(ddal) < 1
        if ok and (hmd or hdal):
            sedi += 1
        rows.append({"ucet": u, "hmd": round(hmd), "hdal": round(hdal),
                     "nmd": round(nmdv), "ndal": round(ndalv),
                     "dmd": round(dmd), "ddal": round(ddal), "hn": d.get("hn", 0), "ok": ok})
    rows.sort(key=lambda r: -(abs(r["hmd"]) + abs(r["hdal"])))
    h_uctu = sum(1 for r in rows if r["hmd"] or r["hdal"])
    # Tržby (60x DAL) = skutečný firemní obrat; hrubý průtok deníku (hmd) zahrnuje
    # i počáteční stavy, převody (261) a sklad — proto je řádově vyšší (Marti 23.6.2026).
    trzby_h = round(sum(r["hdal"] for r in rows if str(r["ucet"]).startswith("60")))
    trzby_n = round(sum(r["ndal"] for r in rows if str(r["ucet"]).startswith("60")))
    return {"ok": True, "rok": rok, "ucty": rows,
            "souhrn": {"uctu_helios": h_uctu, "uctu_sedi": sedi,
                       "hmd": round(sum(r["hmd"] for r in rows)),
                       "hdal": round(sum(r["hdal"] for r in rows)),
                       "nmd": round(sum(r["nmd"] for r in rows)),
                       "ndal": round(sum(r["ndal"] for r in rows)),
                       "trzby_h": trzby_h, "trzby_n": trzby_n}}


@api_router.get("/app/uctovani/prehled")
def uctovani_prehled(req: Request):
    """Účetní modul STRATEGIE — replikovaný model: sborníky (knihy deníku) + náš deník.
    Marti 20.6.2026 (clean break: STRATEGIE účtuje přes vlastní předkontace, Helios = soustava
    účtů + mzdy). Sborníky seskupené po druhu + souhrn deníku."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        sb = s.execute(_t(
            "SELECT kod, nazev, druh, aktivni FROM tenant.ucet_sbornik ORDER BY kod")).mappings().all()
        denik = s.execute(_t(
            "SELECT COUNT(*), ROUND(COALESCE(SUM(castka),0)), "
            "COUNT(DISTINCT kategorie), SUM(CASE WHEN podpis='Marti-AI' THEN 1 ELSE 0 END) "
            "FROM tenant.ucetni_denik WHERE NOT storno")).first()
        pk = s.execute(_t(
            "SELECT sbornik_druh, kod, nazev, ucet_md, ucet_dal, popis, aktivni "
            "FROM tenant.ucet_predkontace ORDER BY sbornik_druh, kod")).mappings().all()
        rad = s.execute(_t(
            "SELECT COUNT(*), MAX(rok) FROM tenant.ucet_cislena_rada WHERE aktivni")).first()
        return {"ok": True,
                "sborniky": [dict(r) for r in sb],
                "denik": {"pocet": int(denik[0] or 0), "obrat": float(denik[1] or 0),
                          "kategorii": int(denik[2] or 0), "marti_ai": int(denik[3] or 0)},
                "predkontace": [dict(r) for r in pk],
                "rady": {"pocet": int(rad[0] or 0), "rok": int(rad[1] or 0)}}
    finally:
        s.close()


def _next_doklad_cislo(s, sbornik_kod, rok):
    """Atomicky vezme další číslo dokladu z číselné řady (posledni_cislo+1).
    Vrací formátované číslo (prefix-NNNNNN). Marti 20.6.2026 posting engine."""
    from sqlalchemy import text as _t
    row = s.execute(_t(
        "UPDATE tenant.ucet_cislena_rada SET posledni_cislo = posledni_cislo + 1 "
        "WHERE tenant_id=2 AND sbornik_kod=:k AND rok=:r AND aktivni "
        "RETURNING posledni_cislo, prefix, delka"), {"k": sbornik_kod, "r": rok}).first()
    if not row:
        return None
    num, prefix, delka = row[0], row[1], row[2]
    return (prefix or sbornik_kod) + "-" + str(num).zfill(int(delka or 6))


@api_router.post("/app/uctovani/doklad")
async def uctovani_doklad(req: Request):
    """Posting engine — zaúčtuje doklad přes sborník + řadu + předkontaci do deníku.
    Vezme číslo z řady, účty z předkontace (nebo explicitně), zapíše do ucetni_denik
    s podpisem autora. Marti 20.6.2026 (plný účtovací oběh u nás)."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    b = await req.json()
    sbornik_kod = (b.get("sbornik_kod") or "").strip()
    datum = (b.get("datum") or "").strip()
    if not sbornik_kod or not datum:
        return JSONResponse({"ok": False, "error": "sbornik_kod + datum povinné"}, status_code=400)
    try:
        castka = float(b.get("castka") or 0)
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "castka"}, status_code=400)
    mena = (b.get("mena") or "CZK").strip()
    popis = (b.get("popis") or "").strip() or None
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        ucet_md = b.get("ucet_md"); ucet_dal = b.get("ucet_dal"); kategorie = b.get("kategorie")
        if b.get("predkontace_kod"):
            pk = s.execute(_t(
                "SELECT ucet_md, ucet_dal, kod, nazev FROM tenant.ucet_predkontace "
                "WHERE tenant_id=2 AND kod=:k AND aktivni"), {"k": b["predkontace_kod"]}).first()
            if pk:
                ucet_md = ucet_md or pk[0]; ucet_dal = ucet_dal or pk[1]
                kategorie = kategorie or pk[2]
                if not popis:
                    popis = pk[3]
        try:
            rok = int(datum[:4])
        except ValueError:
            rok = 2026
        # víceřádková předkontace (legy s rozpadem DPH); fallback = jeden řádek
        legs = []
        if b.get("predkontace_kod"):
            legs = s.execute(_t(
                "SELECT poradi, ucet_md, ucet_dal, castka_typ, sazba_dph, popis "
                "FROM tenant.ucet_predkontace_radek WHERE tenant_id=2 AND predkontace_kod=:k "
                "ORDER BY poradi"), {"k": b["predkontace_kod"]}).mappings().all()

        def _amt(ca, ctyp, sazba):
            try:
                sz = float(sazba or 0)
            except (TypeError, ValueError):
                sz = 0
            if ctyp == "zaklad" and sz > 0:
                return round(ca / (1 + sz / 100.0), 2)
            if ctyp == "dph" and sz > 0:
                return round(ca - ca / (1 + sz / 100.0), 2)
            return round(ca, 2)

        cislo = _next_doklad_cislo(s, sbornik_kod, rok)
        if not cislo:
            return JSONResponse({"ok": False, "error": "číselná řada pro sborník/rok neexistuje"}, status_code=400)
        podpis = s.execute(_t(
            "SELECT COALESCE(first_name,'uid '||id::text) FROM public.users WHERE id=:u"),
            {"u": uid}).scalar() or ("uid " + str(uid))
        radky_out = []
        if legs:
            for lg in legs:
                amt = _amt(castka, lg["castka_typ"], lg["sazba_dph"])
                s.execute(_t(
                    "INSERT INTO tenant.ucetni_denik (datum, doklad, ucet_md, ucet_dal, castka, mena, popis, "
                    "kategorie, zdroj, sbornik_kod, podpis) VALUES "
                    "(:dat, :dok, :md, :dal, :ca, :me, :po, :kat, 'rucni', :sb, :pod)"),
                    {"dat": datum, "dok": cislo, "md": lg["ucet_md"], "dal": lg["ucet_dal"], "ca": amt,
                     "me": mena, "po": (popis or "") + (" — " + lg["popis"] if lg["popis"] else ""),
                     "kat": kategorie, "sb": sbornik_kod, "pod": podpis})
                radky_out.append({"ucet_md": lg["ucet_md"], "ucet_dal": lg["ucet_dal"], "castka": amt})
        else:
            s.execute(_t(
                "INSERT INTO tenant.ucetni_denik (datum, doklad, ucet_md, ucet_dal, castka, mena, popis, "
                "kategorie, zdroj, sbornik_kod, podpis) VALUES "
                "(:dat, :dok, :md, :dal, :ca, :me, :po, :kat, 'rucni', :sb, :pod)"),
                {"dat": datum, "dok": cislo, "md": ucet_md, "dal": ucet_dal, "ca": round(castka, 2),
                 "me": mena, "po": popis, "kat": kategorie, "sb": sbornik_kod, "pod": podpis})
            radky_out.append({"ucet_md": ucet_md, "ucet_dal": ucet_dal, "castka": round(castka, 2)})
        s.commit()
        return {"ok": True, "cislo": cislo, "radky": radky_out, "podpis": podpis}
    finally:
        s.close()


def _kurz_lookup(s, mena, rok, mesic, company_id=None):
    """Pevný měsíční kurz z tenant.ucet_kurz (per organizace, fallback default).
    Vrací (kurz, jednotka). CZK = 1/1."""
    from sqlalchemy import text as _t
    if (mena or "CZK") == "CZK":
        return (1.0, 1)
    row = s.execute(_t(
        "SELECT kurz, jednotka FROM tenant.ucet_kurz "
        "WHERE tenant_id=2 AND mena=:m AND rok=:r AND mesic=:me "
        "  AND (company_id=:c OR company_id IS NULL) "
        "ORDER BY company_id NULLS LAST LIMIT 1"),
        {"m": mena, "r": rok, "me": mesic, "c": company_id}).first()
    if not row:
        return (None, 1)
    return (float(row[0]), int(row[1] or 1))


@api_router.post("/app/uctovani/doklad-full")
async def uctovani_doklad_full(req: Request):
    """Plný účetní engine — doklad s položkami (per-položka DPH + předkontace),
    pevný měsíční kurz, dvojí měna (CZK+EUR), DPH rekapitulace, zápis do deníku v CZK.
    Marti 20.6.2026 (vícеměnový účetní engine; deník CZK, doklad oba pohledy)."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    b = await req.json()
    sbornik_kod = (b.get("sbornik_kod") or "").strip()
    datum = (b.get("datum") or "").strip()
    mena = (b.get("mena") or "CZK").strip().upper()
    polozky = b.get("polozky") or []
    if not sbornik_kod or not datum or not polozky:
        return JSONResponse({"ok": False, "error": "sbornik_kod + datum + položky povinné"}, status_code=400)
    # každá položka s částkou musí mít předkontaci (jinak vznikne neúčtovaný řádek)
    for _i, _p in enumerate(polozky, 1):
        try:
            _ca = float(_p.get("castka") or 0)
        except (TypeError, ValueError):
            _ca = 0
        if _ca and not (_p.get("predkontace_kod") or (_p.get("ucet_md") and _p.get("ucet_dal"))):
            return JSONResponse({"ok": False, "error": "položka " + str(_i) + " nemá předkontaci"}, status_code=400)
    company_id = b.get("company_id")
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        try:
            rok = int(datum[:4]); mesic = int(datum[5:7])
        except (ValueError, IndexError):
            return JSONResponse({"ok": False, "error": "datum"}, status_code=400)
        kurz, jednotka = _kurz_lookup(s, mena, rok, mesic, company_id)
        if kurz is None:
            return JSONResponse({"ok": False, "error": "chybí kurz pro " + mena + " " + str(mesic) + "/" + str(rok) + " (nastav v kurzech)"}, status_code=400)
        eur_kurz, eur_jed = _kurz_lookup(s, "EUR", rok, mesic, company_id)
        cislo = _next_doklad_cislo(s, sbornik_kod, rok)
        if not cislo:
            return JSONResponse({"ok": False, "error": "číselná řada pro sborník/rok neexistuje"}, status_code=400)
        podpis = s.execute(_t(
            "SELECT COALESCE(first_name,'uid '||id::text) FROM public.users WHERE id=:u"),
            {"u": uid}).scalar() or ("uid " + str(uid))
        dok = s.execute(_t(
            "INSERT INTO tenant.ucet_doklad (company_id,cislo,sbornik_kod,datum,partner_org,partner_nazev,"
            "mena,kurz,jednotka,popis,stav,podpis,porizeno_auto,realizovano_auto,realizoval_uid,realizoval_at) VALUES "
            "(:co,:ci,:sb,:dat,:po,:pn,:me,:ku,:je,:pop,'realizovano',:pod,true,true,:u,now()) RETURNING id"),
            {"co": company_id, "ci": cislo, "sb": sbornik_kod, "dat": datum,
             "po": b.get("partner_org"), "pn": b.get("partner_nazev"),
             "me": mena, "ku": kurz, "je": jednotka, "pop": (b.get("popis") or None),
             "pod": podpis, "u": uid}).scalar()

        def r2(x):
            return round(float(x or 0), 2)

        celkem_mena = 0.0; celkem_czk = 0.0
        rekap = {}
        denik_radky = 0
        for i, p in enumerate(polozky, 1):
            try:
                castka = float(p.get("castka") or 0)
            except (TypeError, ValueError):
                castka = 0.0
            sazba = float(p.get("sazba_dph") or 0)
            je_celkem = bool(p.get("je_celkem"))
            if je_celkem and sazba > 0:
                celkem_m = r2(castka); zaklad_m = r2(castka / (1 + sazba / 100.0)); dph_m = r2(celkem_m - zaklad_m)
            else:
                zaklad_m = r2(castka); dph_m = r2(castka * sazba / 100.0); celkem_m = r2(zaklad_m + dph_m)
            f = kurz / (jednotka or 1)
            zaklad_czk = r2(zaklad_m * f); dph_czk = r2(dph_m * f); celkem_czk_p = r2(zaklad_czk + dph_czk)
            predk = p.get("predkontace_kod")
            s.execute(_t(
                "INSERT INTO tenant.ucet_doklad_polozka (doklad_id,poradi,popis,predkontace_kod,sazba_dph,"
                "zaklad_mena,dph_mena,celkem_mena,zaklad_czk,dph_czk,celkem_czk) VALUES "
                "(:d,:po,:pop,:pk,:sz,:zm,:dm,:cm,:zc,:dc,:cc)"),
                {"d": dok, "po": i, "pop": p.get("popis"), "pk": predk, "sz": sazba,
                 "zm": zaklad_m, "dm": dph_m, "cm": celkem_m, "zc": zaklad_czk, "dc": dph_czk, "cc": celkem_czk_p})
            celkem_mena = r2(celkem_mena + celkem_m); celkem_czk = r2(celkem_czk + celkem_czk_p)
            k = str(int(sazba)) if sazba == int(sazba) else str(sazba)
            rk = rekap.setdefault(k, {"zaklad": 0.0, "dph": 0.0})
            rk["zaklad"] = r2(rk["zaklad"] + zaklad_czk); rk["dph"] = r2(rk["dph"] + dph_czk)
            # POZN.: doklad vzniká jako KONCEPT — do deníku se zapíše až akcí „zaúčtovat" (_doklad_post_denik)
        celkem_eur = r2(celkem_mena) if mena == "EUR" else (r2(celkem_czk / (eur_kurz / (eur_jed or 1))) if eur_kurz else None)
        s.execute(_t(
            "UPDATE tenant.ucet_doklad SET celkem_mena=:cm, celkem_czk=:cc, celkem_eur=:ce WHERE id=:id"),
            {"cm": celkem_mena, "cc": celkem_czk, "ce": celkem_eur, "id": dok})
        s.execute(_t(
            "INSERT INTO tenant.ucet_doklad_log (doklad_id,akce,stav_na,uid,podpis) "
            "VALUES (:d,'porizeno','porizeno',:u,:p), (:d,'realizovano','realizovano',:u,:p)"),
            {"d": dok, "u": uid, "p": podpis})
        s.commit()
        return {"ok": True, "id": dok, "cislo": cislo, "stav": "realizovano",
                "celkem_mena": celkem_mena, "celkem_czk": celkem_czk,
                "celkem_eur": celkem_eur, "mena": mena, "kurz": kurz,
                "rekapitulace": [{"sazba": k, "zaklad": v["zaklad"], "dph": v["dph"]} for k, v in sorted(rekap.items())],
                "podpis": podpis}
    finally:
        s.close()


def _doklad_post_denik(s, dok_id, podpis):
    """Zaúčtuje položky dokladu do deníku (CZK, přes legy předkontace). Vrací počet řádků."""
    from sqlalchemy import text as _t
    d = s.execute(_t("SELECT cislo, sbornik_kod, datum FROM tenant.ucet_doklad WHERE id=:i"), {"i": dok_id}).first()
    if not d:
        return 0
    cislo, sbornik_kod, datum = d[0], d[1], d[2]
    pol = s.execute(_t(
        "SELECT predkontace_kod, zaklad_czk, dph_czk, celkem_czk, popis "
        "FROM tenant.ucet_doklad_polozka WHERE doklad_id=:i ORDER BY poradi"), {"i": dok_id}).mappings().all()
    n = 0
    for p in pol:
        legs = []
        if p["predkontace_kod"]:
            legs = s.execute(_t(
                "SELECT ucet_md, ucet_dal, castka_typ FROM tenant.ucet_predkontace_radek "
                "WHERE tenant_id=2 AND predkontace_kod=:k ORDER BY poradi"), {"k": p["predkontace_kod"]}).mappings().all()
        if not legs:
            legs = [{"ucet_md": None, "ucet_dal": None, "castka_typ": "celkem"}]
        for lg in legs:
            amt = p["zaklad_czk"] if lg["castka_typ"] == "zaklad" else (p["dph_czk"] if lg["castka_typ"] == "dph" else p["celkem_czk"])
            if not amt:
                continue
            s.execute(_t(
                "INSERT INTO tenant.ucetni_denik (datum,doklad,ucet_md,ucet_dal,castka,mena,popis,"
                "kategorie,zdroj,sbornik_kod,podpis) VALUES "
                "(:dat,:dok,:md,:dal,:ca,'CZK',:po,:kat,'doklad',:sb,:pod)"),
                {"dat": datum, "dok": cislo, "md": lg["ucet_md"], "dal": lg["ucet_dal"], "ca": float(amt),
                 "po": p["popis"], "kat": p["predkontace_kod"], "sb": sbornik_kod, "pod": podpis})
            n += 1
    return n


def _je_uzavreno(s, datum, company_id=None):
    """True, pokud je období dokladu uzavřené (uzávěrka měsíce/čtvrtletí/roku)."""
    from sqlalchemy import text as _t
    try:
        rok = int(str(datum)[:4]); mesic = int(str(datum)[5:7])
    except (ValueError, TypeError):
        return False
    r = s.execute(_t(
        "SELECT 1 FROM tenant.ucet_uzaverka WHERE tenant_id=2 AND uzavreno AND rok=:r "
        "  AND (mesic=:m OR mesic IS NULL) AND (company_id=:c OR company_id IS NULL) LIMIT 1"),
        {"r": rok, "m": mesic, "c": company_id}).first()
    return bool(r)


@api_router.post("/app/uctovani/doklad/{dok_id}/akce")
async def uctovani_doklad_akce(dok_id: int, req: Request):
    """Workflow dokladu: odeslat / zauctovat / oductovat / odrealizovat. Audit + pojistka uzávěrky."""
    uid = _uid_from_token_or_cookie(req)
    if not _banka_can_uid(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    b = await req.json()
    akce = (b.get("akce") or "").strip()
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        d = s.execute(_t("SELECT stav, cislo, datum, company_id FROM tenant.ucet_doklad WHERE id=:i"), {"i": dok_id}).first()
        if not d:
            return JSONResponse({"ok": False, "error": "doklad nenalezen"}, status_code=404)
        stav, cislo, datum, company_id = d[0], d[1], d[2], d[3]
        podpis = s.execute(_t("SELECT COALESCE(first_name,'uid '||id::text) FROM public.users WHERE id=:u"),
                           {"u": uid}).scalar() or ("uid " + str(uid))
        novy = None; denik_radky = 0
        if akce == "odeslat":
            if stav not in ("realizovano",):
                return JSONResponse({"ok": False, "error": "odeslat lze jen z realizováno"}, status_code=400)
            novy = "odeslano"
            s.execute(_t("UPDATE tenant.ucet_doklad SET stav='odeslano', odeslal_uid=:u, odeslal_at=now() WHERE id=:i"), {"u": uid, "i": dok_id})
        elif akce == "zauctovat":
            if stav not in ("realizovano", "odeslano"):
                return JSONResponse({"ok": False, "error": "zaúčtovat lze z realizováno/odesláno"}, status_code=400)
            denik_radky = _doklad_post_denik(s, dok_id, podpis)
            novy = "uctovano"
            s.execute(_t("UPDATE tenant.ucet_doklad SET stav='uctovano', zauctoval_uid=:u, zauctoval_at=now() WHERE id=:i"), {"u": uid, "i": dok_id})
        elif akce == "oductovat":
            if stav != "uctovano":
                return JSONResponse({"ok": False, "error": "odúčtovat lze jen z účtováno"}, status_code=400)
            if _je_uzavreno(s, datum, company_id):
                return JSONResponse({"ok": False, "error": "období je uzavřené (uzávěrka) — nelze odúčtovat"}, status_code=400)
            s.execute(_t("DELETE FROM tenant.ucetni_denik WHERE doklad=:c AND zdroj='doklad'"), {"c": cislo})
            novy = "realizovano"
            s.execute(_t("UPDATE tenant.ucet_doklad SET stav='realizovano', zauctoval_uid=NULL, zauctoval_at=NULL WHERE id=:i"), {"i": dok_id})
        elif akce == "odrealizovat":
            if stav == "uctovano":
                return JSONResponse({"ok": False, "error": "nejdřív odúčtuj"}, status_code=400)
            novy = "koncept"
            s.execute(_t("UPDATE tenant.ucet_doklad SET stav='koncept' WHERE id=:i"), {"i": dok_id})
        else:
            return JSONResponse({"ok": False, "error": "neznámá akce"}, status_code=400)
        s.execute(_t("INSERT INTO tenant.ucet_doklad_log (doklad_id,akce,stav_z,stav_na,uid,podpis) "
                     "VALUES (:d,:a,:sz,:sn,:u,:p)"),
                  {"d": dok_id, "a": akce, "sz": stav, "sn": novy, "u": uid, "p": podpis})
        s.commit()
        return {"ok": True, "stav": novy, "denik_radky": denik_radky}
    finally:
        s.close()


