# ════════════════════════════════════════════════════════════════════════
# DATOVÉ SCHRÁNKY / ISDS → eNeschopenka + OČR (Marti 19.6.2026), UNIVERZÁLNĚ.
# Multi-tenant + multi-box: jeden tenant unese N datovek (EC, ES, INTERSOFT…).
# Heslo šifrované Fernetem (_vault_fernet). Čtení přes ISDS webovou službu
# (basic auth jméno+heslo). Pozn.: přesné cesty služby ověřujeme při živém
# testu (dmInfo ~ /DS/df, dmOperations ~ /DS/dz).
# ════════════════════════════════════════════════════════════════════════
_ISDS_BASE = "https://ws1.mojedatovaschranka.cz/DS"
_ISDS_NS = "http://isds.czechpoint.cz/v20"

def _isds_enc(plain: str):
    f = _vault_fernet()
    if not f or not plain:
        return None
    return f.encrypt(plain.encode("utf-8")).decode("ascii")

def _isds_dec(enc: str):
    f = _vault_fernet()
    if not f or not enc:
        return None
    try:
        return f.decrypt(enc.encode("ascii")).decode("utf-8")
    except Exception:
        return None

def _isds_soap(account: dict, path: str, body_inner: str, timeout=40):
    """Pošle SOAP request na ISDS webovou službu (basic auth). Vrací (ok, root_or_err)."""
    import requests
    from xml.etree import ElementTree as ET
    login = account.get("login_name") or ""
    pwd = _isds_dec(account.get("password_enc")) or ""
    if not login or not pwd:
        return False, "Chybí přihlašovací údaje / vault klíč."
    envelope = (
        '<?xml version="1.0" encoding="utf-8"?>'
        '<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" '
        'xmlns:p="%s"><soapenv:Header/><soapenv:Body>%s</soapenv:Body></soapenv:Envelope>'
        % (_ISDS_NS, body_inner))
    try:
        r = requests.post(_ISDS_BASE + path, data=envelope.encode("utf-8"),
                          headers={"Content-Type": "text/xml; charset=utf-8", "SOAPAction": '""'},
                          auth=(login, pwd), timeout=timeout)
        if r.status_code in (401, 403):
            return False, "ISDS odmítl přihlášení (401/403) — zkontroluj jméno/heslo (a 90denní expiraci)."
        try:
            root = ET.fromstring(r.content)
        except Exception as _pe:
            snip = (r.text or "")[:200].replace("\n", " ")
            ctype = r.headers.get("Content-Type", "?")
            return False, ("Odpověď není XML (HTTP %s, %s): %s … [%s]"
                           % (r.status_code, ctype, snip, type(_pe).__name__))
        return True, root
    except Exception as exc:
        return False, "%s: %s" % (type(exc).__name__, str(exc)[:200])

def _isds_q(el, tag):
    """Najde potomka bez ohledu na namespace."""
    for ch in el.iter():
        if ch.tag.rsplit("}", 1)[-1] == tag:
            return ch
    return None

def _isds_list_received(account: dict, days_back: int = 60):
    """GetListOfReceivedMessages → list dict {dm_id, subject, sender, delivered}."""
    import datetime as _dt
    frm = (_dt.datetime.now() - _dt.timedelta(days=days_back)).strftime("%Y-%m-%dT00:00:00")
    body = ('<p:GetListOfReceivedMessages xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">'
            '<p:dmFromTime>%s</p:dmFromTime>'
            '<p:dmToTime xsi:nil="true"/><p:dmRecipientOrgUnitNum xsi:nil="true"/>'
            '<p:dmStatusFilter>-1</p:dmStatusFilter><p:dmOffset>1</p:dmOffset>'
            '<p:dmLimit>1000</p:dmLimit></p:GetListOfReceivedMessages>' % frm)
    # GetListOfReceivedMessages = služba dmInfo → /dx (ne /dz = dmOperations).
    ok, root = _isds_soap(account, "/dx", body)
    if not ok:
        raise RuntimeError(root)
    out = []
    for rec in root.iter():
        if rec.tag.rsplit("}", 1)[-1] != "dmRecord":
            continue
        def g(t):
            e = None
            for ch in rec.iter():
                if ch.tag.rsplit("}", 1)[-1] == t:
                    e = ch; break
            return (e.text or "").strip() if e is not None and e.text else ""
        out.append({"dm_id": g("dmID"), "subject": g("dmAnnotation"),
                    "sender": g("dmSender"), "delivered": g("dmDeliveryTime")})
    return [x for x in out if x["dm_id"]]

def _isds_download(account: dict, dm_id: str):
    """MessageDownload → stáhne celou zprávu vč. příloh. Vrací (envelope_subject, [{filename, bytes}])."""
    import base64 as _b64
    body = '<p:MessageDownload><p:dmID>%s</p:dmID></p:MessageDownload>' % dm_id
    ok, root = _isds_soap(account, "/dz", body)
    if not ok:
        raise RuntimeError(root)
    subj = ""
    se = _isds_q(root, "dmAnnotation")
    if se is not None and se.text:
        subj = se.text.strip()
    files = []
    for fe in root.iter():
        if fe.tag.rsplit("}", 1)[-1] != "dmFile":
            continue
        # název: atribut dmFileDescr (může mít namespace prefix)
        fname = ""
        for k, v in fe.attrib.items():
            if k.rsplit("}", 1)[-1] == "dmFileDescr":
                fname = v; break
        enc = None
        for ch in fe.iter():
            if ch.tag.rsplit("}", 1)[-1] == "dmEncodedContent":
                enc = (ch.text or "").strip(); break
        if enc:
            try:
                files.append({"filename": fname or "priloha.bin", "bytes": _b64.b64decode(enc)})
            except Exception:
                pass
    return subj, files


def _isds_send(account, recipient_box, subject, files, dmType="V"):
    """Odešle datovou zprávu (CreateMessage, /dz) s přílohami. files=[{filename,bytes,mime}].
    Vrací (ok, dm_id_or_err). Pozn.: odeslání na OVM (ČSSZ) je zdarma; PO→PO je placené (PDZ)."""
    import base64 as _b64
    fxml = []
    first = True
    for f in files:
        b64 = _b64.b64encode(f["bytes"]).decode("ascii")
        meta = "main" if first else "enclosure"
        first = False
        mime = f.get("mime") or "application/xml"
        fxml.append(
            '<p:dmFile dmFileMetaType="%s" dmMimeType="%s" dmFileDescr="%s">'
            '<p:dmEncodedContent>%s</p:dmEncodedContent></p:dmFile>'
            % (meta, mime, (f.get("filename") or "soubor.xml"), b64))
    body = (
        '<p:CreateMessage>'
        '<p:dmEnvelope>'
        '<p:dbIDRecipient>%s</p:dbIDRecipient>'
        '<p:dmAnnotation>%s</p:dmAnnotation>'
        '<p:dmAllowSubstDelivery>1</p:dmAllowSubstDelivery>'
        '</p:dmEnvelope>'
        '<p:dmFiles>%s</p:dmFiles>'
        '</p:CreateMessage>'
        % (recipient_box, (subject or "")[:255], "".join(fxml)))
    ok, root = _isds_soap(account, "/dz", body)
    if not ok:
        return False, root
    code = ""; msg = ""; dm = ""
    for ch in root.iter():
        t = ch.tag.rsplit("}", 1)[-1]
        if t == "dmStatusCode":
            code = (ch.text or "").strip()
        elif t == "dmStatusMessage":
            msg = (ch.text or "").strip()
        elif t == "dmID":
            dm = (ch.text or "").strip()
    if code == "0000":
        return True, dm
    return False, "%s: %s" % (code, msg)


def _isds_extract_text(rb, fname):
    """Z příloh datovky vytáhne text: digitální PDF (pdfplumber) → jinak OCR → jinak decode."""
    low = (fname or "").lower()
    if low.endswith(".pdf"):
        txt = ""
        try:
            import io as _io, pdfplumber as _pp
            with _pp.open(_io.BytesIO(rb)) as pdf:
                txt = "\n".join((pg.extract_text() or "") for pg in pdf.pages)
        except Exception:
            txt = ""
        if not (txt or "").strip():
            ws = _edi_ocr_words_from_pdf(rb)
            txt = " ".join(w["t"] for w in ws)
        return txt
    if low.endswith((".xml", ".txt", ".csv", ".html")):
        try:
            return rb.decode("utf-8")
        except Exception:
            return rb.decode("latin-1", "replace")
    return ""


def _isds_attach_kind(fn, txt, subject):
    """Klasifikace přílohy datovky pro archiv/routing."""
    s = ((fn or "") + " " + (subject or "") + " " + ((txt or "")[:500])).lower()
    if "neschop" in s or "dpn" in s:
        return "neschopenka"
    if "faktura" in s or "daňový doklad" in s or "danovy doklad" in s or "zálohová" in s:
        return "faktura"
    if (fn or "").lower().endswith(".xml"):
        return "xml"
    return "jine"


def _isds_process_attachments(sp, acc, dm_id, subject=""):
    """Stáhne přílohy zprávy, pro-OCR-uje text (i skeny) a uloží do fw.isds_attachment."""
    from sqlalchemy import text as _tp
    import os.path as _op
    subj, files = _isds_download(acc, dm_id)
    subject = subject or subj
    n = 0; kinds = {}
    for f in files:
        fn = f["filename"] or "priloha.bin"
        ext = (_op.splitext(fn)[1] or "").lstrip(".").lower()
        txt = _isds_extract_text(f["bytes"], fn) or ""
        kind = _isds_attach_kind(fn, txt, subject)
        kinds[kind] = kinds.get(kind, 0) + 1
        sp.execute(_tp(
            "INSERT INTO fw.isds_attachment (account_id,dm_id,filename,ext,size_b,kind,text_obsah,ocr) "
            "VALUES (:a,:d,:fn,:ex,:sz,:k,:tx,:ocr) "
            "ON CONFLICT (account_id,dm_id,filename) DO UPDATE SET "
            "text_obsah=EXCLUDED.text_obsah, kind=EXCLUDED.kind, size_b=EXCLUDED.size_b, ocr=EXCLUDED.ocr"),
            {"a": acc["id"], "d": dm_id, "fn": fn, "ex": ext, "sz": len(f["bytes"]),
             "k": kind, "tx": txt[:200000], "ocr": (ext == "pdf" and bool(txt))})
        n += 1
    sp.commit()
    return {"ok": True, "count": n, "kinds": kinds, "subject": subject}


def _isds_parse_eneschopenka(xmlb):
    """Rozparsuje ČSSZ eNeschopenka XML (Vznik/Trvani/Ukonceni). Klíč = IdPripadu
    (stejný pro celý životní cyklus). Vrací dict s údaji o zaměstnanci a DPN."""
    from xml.etree import ElementTree as ET
    root = ET.fromstring(xmlb)
    typ = root.tag.rsplit("}", 1)[-1]

    def g(tag):
        for ch in root.iter():
            if ch.tag.rsplit("}", 1)[-1] == tag:
                return (ch.text or "").strip() if ch.text else ""
        return ""

    def gm(tags):
        for tg in tags:
            v = g(tg)
            if v:
                return v
        return ""
    adr = " ".join([x for x in [g("Ulice"), g("CisloPopisne"), g("NazevObce"),
                                 g("PostovniSmerovaciCislo")] if x]).strip()
    t = typ.lower()
    stav = "ukonceno" if "ukonceni" in t else ("trva" if "trvani" in t else "vznik")
    # typ absence: OČR (ošetřování) vs nemoc (DPN) — dle root tagu
    typ_abs = "ocr" if any(k in t for k in ("osetr", "ošetř", "potreb", "potřeb", "ocr", "pos")) else "nemoc"
    # ošetřovaná osoba (u OČR) — tolerantně
    osetr = gm(["JmenoOsetrovane", "OsetrovanaOsoba", "JmenoOsetrovaneOsoby", "JmenoDitete"])
    op = gm(["PrijmeniOsetrovane", "PrijmeniOsetrovaneOsoby", "PrijmeniDitete"])
    osetr_full = (osetr + " " + op).strip()
    return {
        "typ": typ, "stav": stav, "typ_abs": typ_abs, "osetrovana_osoba": osetr_full or None,
        "id_pripadu": g("IdPripadu"), "id_notifikace": g("IdNotifikace"),
        "cislo_rozhodnuti": g("CisloRozhodnuti"), "profese": g("Poznamka"),
        "emp_jmeno": g("Jmeno"), "emp_prijmeni": g("Prijmeni"),
        "emp_rc": g("RodneCislo"), "emp_datum_nar": g("DatumNarozeni") or None,
        "company_vs": g("VariabilniSymbol"), "company_ico": g("IdentifikacniCisloOrganizace"),
        "datum_od": gm(["DatumNeschopenOd", "DatumVznikuPotrebyOsetrovani", "DatumVznikuPotreby",
                        "DatumPotrebyOd", "DatumOd", "DatumPlatnostiOd"]) or None,
        "datum_do": gm(["DatumNeschopenDo", "DatumUkonceniPotrebyOsetrovani", "DatumUkonceniPotreby",
                        "DatumPotrebyDo", "DatumDo", "DatumPlatnostiDo"]) or None,
        "druh_nemoci": g("KodDruhuNemoci"), "prac_uraz": (g("PracovniUraz") == "A"),
        "lekar_nazev": g("NazevPzs"), "lekar_jmeno": g("JmenoLekare"), "adresa": adr,
    }


def _isds_process_eneschopenka(sp, acc, dm_id):
    """Stáhne eNeschopenku, rozparsuje a UPSERTuje podle IdPripadu (sloučí cyklus)."""
    from sqlalchemy import text as _tp
    subj, files = _isds_download(acc, dm_id)
    xmlf = next((f for f in files if (f["filename"] or "").lower().endswith(".xml")), None)
    if not xmlf:
        return {"ok": False, "error": "bez XML přílohy"}
    d = _isds_parse_eneschopenka(xmlf["bytes"])
    # CisloRozhodnuti je univerzální klíč (i Oznam, který nemá IdPripadu). Fallback IdPripadu.
    cr = d["cislo_rozhodnuti"] or (("IDP:" + d["id_pripadu"]) if d["id_pripadu"] else "")
    if not cr:
        return {"ok": False, "error": "bez CisloRozhodnuti i IdPripadu"}
    sp.execute(_tp(
        "INSERT INTO tenant.eneschopenka (tenant_id,id_pripadu,company_vs,company_ico,emp_jmeno,"
        "emp_prijmeni,emp_rc,emp_datum_nar,datum_od,datum_do,druh_nemoci,prac_uraz,profese,"
        "lekar_nazev,lekar_jmeno,adresa,stav,cislo_rozhodnuti,last_id_notifikace,last_typ,typ,osetrovana_osoba,updated_at) "
        "VALUES (2,:idp,:vs,:ico,:jm,:pr,:rc,:dn,:od,:do,:nem,:uraz,:prof,:ln,:lj,:adr,:stav,:cr,:idn,:typ,:tabs,:osetr,now()) "
        "ON CONFLICT (tenant_id,cislo_rozhodnuti) DO UPDATE SET "
        "typ=EXCLUDED.typ, "
        "osetrovana_osoba=COALESCE(NULLIF(EXCLUDED.osetrovana_osoba,''), tenant.eneschopenka.osetrovana_osoba), "
        "id_pripadu=COALESCE(NULLIF(EXCLUDED.id_pripadu,''), tenant.eneschopenka.id_pripadu), "
        "emp_rc=COALESCE(NULLIF(EXCLUDED.emp_rc,''), tenant.eneschopenka.emp_rc), "
        "emp_datum_nar=COALESCE(EXCLUDED.emp_datum_nar, tenant.eneschopenka.emp_datum_nar), "
        "profese=COALESCE(NULLIF(EXCLUDED.profese,''), tenant.eneschopenka.profese), "
        "adresa=COALESCE(NULLIF(EXCLUDED.adresa,''), tenant.eneschopenka.adresa), "
        "datum_do=COALESCE(EXCLUDED.datum_do, tenant.eneschopenka.datum_do), "
        "datum_od=COALESCE(tenant.eneschopenka.datum_od, EXCLUDED.datum_od), "
        "stav=CASE WHEN EXCLUDED.stav='ukonceno' OR tenant.eneschopenka.stav='ukonceno' THEN 'ukonceno' "
        "WHEN EXCLUDED.stav='trva' OR tenant.eneschopenka.stav='trva' THEN 'trva' ELSE EXCLUDED.stav END, "
        "druh_nemoci=COALESCE(NULLIF(EXCLUDED.druh_nemoci,''),tenant.eneschopenka.druh_nemoci), "
        "lekar_nazev=COALESCE(NULLIF(EXCLUDED.lekar_nazev,''),tenant.eneschopenka.lekar_nazev), "
        "lekar_jmeno=COALESCE(NULLIF(EXCLUDED.lekar_jmeno,''),tenant.eneschopenka.lekar_jmeno), "
        "last_id_notifikace=EXCLUDED.last_id_notifikace, last_typ=EXCLUDED.last_typ, updated_at=now()"),
        {"idp": d["id_pripadu"], "vs": d["company_vs"], "ico": d["company_ico"],
         "jm": d["emp_jmeno"], "pr": d["emp_prijmeni"], "rc": d["emp_rc"], "dn": d["emp_datum_nar"],
         "od": d["datum_od"], "do": d["datum_do"], "nem": d["druh_nemoci"], "uraz": d["prac_uraz"],
         "prof": d["profese"], "ln": d["lekar_nazev"], "lj": d["lekar_jmeno"], "adr": d["adresa"],
         "stav": d["stav"], "cr": cr, "idn": d["id_notifikace"], "typ": d["typ"],
         "tabs": d.get("typ_abs", "nemoc"), "osetr": d.get("osetrovana_osoba")})
    sp.commit()
    return {"ok": True, **d}


def _isds_classify(subject: str) -> str:
    s = (subject or "").lower()
    if "neschop" in s and "oznam" in s:
        return "eneschopenka_oznam"
    if "neschop" in s or "dpn" in s:
        return "eneschopenka"
    if "ošetřov" in s or "osetrov" in s or "očr" in s or "ocr" in s:
        return "ocr"
    return "other"


