@api_router.get("/app/edi/definice")
def edi_definice(req: Request):
    """Přehled EDI definic (+ pole/zóny při ?src_id=). Správa pro Peťu + Claude."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not _has_capability(uid, 'edi', 'read'):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    src_id = req.query_params.get("src_id")
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        if src_id:
            d = s.execute(_t(
                "SELECT src_id, partner_nazev, klic, COALESCE(dekod_typ,'marker') dekod_typ, "
                "COALESCE(verze,1) verze, aktivni, zdroj_typ, poznamka "
                "FROM tenant.edi_definice WHERE src_id=:d"), {"d": int(src_id)}).mappings().first()
            pole = s.execute(_t(
                "SELECT poradi, je_polozka, field_name, marker_od, marker_do, je_datum, "
                "zone_x, zone_y, zone_w, zone_h, anchor_text, ai_learned "
                "FROM tenant.edi_pole WHERE definice_src_id=:d ORDER BY poradi"), {"d": int(src_id)}).mappings().all()
            return {"ok": True, "definice": (dict(d) if d else None), "pole": [dict(p) for p in pole]}
        rows = s.execute(_t(
            "SELECT d.src_id, d.partner_nazev, d.klic, COALESCE(d.dekod_typ,'marker') dekod_typ, "
            "COALESCE(d.verze,1) verze, d.aktivni, d.zdroj_typ, "
            "(SELECT COUNT(*) FROM tenant.edi_pole p WHERE p.definice_src_id=d.src_id) poli, "
            "(SELECT COUNT(*) FROM tenant.edi_zpracovani_log l WHERE l.partner=d.partner_nazev) zprac "
            "FROM tenant.edi_definice d WHERE d.druh_nazev='faktura' ORDER BY d.aktivni DESC, zprac DESC")).mappings().all()
        return {"ok": True, "polozky": [dict(r) for r in rows], "count": len(rows)}
    finally:
        s.close()


@api_router.get("/app/edi/preview")
def edi_preview_ep(req: Request):
    """Otestuje definici (src_id) nad fakturou (path) BEZ zápisu. Pro „vyzkoušej"."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not _has_capability(uid, 'edi', 'read'):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    path = req.query_params.get("path") or ""
    src_id = req.query_params.get("src_id")
    if not path or not src_id:
        return JSONResponse({"ok": False, "error": "path + src_id povinné"}, status_code=400)
    try:
        from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
        mcp = get_eurosoft_mcp_client()
        if mcp is None:
            return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
        txt, words, err = _edi_read_doc(mcp, path)
        if not txt and not words:
            return JSONResponse({"ok": False, "error": err or "nepodařilo se získat text"})
        from core.database_data import get_data_session as _g
        s = _g()
        try:
            return _edi_preview(s, txt, words, int(src_id))
        finally:
            s.close()
    except Exception as exc:
        return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, exc)})


@api_router.get("/app/isds/neschopenky")
def isds_neschopenky(req: Request):
    """Registr neschopenek (sloučený dle CisloRozhodnuti) — jeden řádek na případ."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not _has_capability(uid, 'neschopenky', 'read'):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        # Marti 29.6.: sloučit datovkový registr (eneschopenka) + SMS/automat OČR
        # (att_ocr_case) — Kristýnčina OČR přišla SMSkou, ne datovkou, ať ji OČR
        # dlaždice taky ukáže. Řazení přes skrytý _sort (skutečné datum).
        rows = s.execute(_t(
            "SELECT * FROM ("
            "  SELECT id_pripadu::text id_pripadu, COALESCE(typ,'nemoc') typ, osetrovana_osoba, "
            "    emp_jmeno, emp_prijmeni, emp_rc, "
            "    to_char(datum_od,'DD.MM.YYYY') od, to_char(datum_do,'DD.MM.YYYY') do, "
            "    stav, druh_nemoci, lekar_nazev, profese, company_vs, user_id, "
            "    (datum_do - datum_od + 1) dni, datum_od _sort "
            "  FROM tenant.eneschopenka "
            "  UNION ALL "
            "  SELECT 'ocr-'||o.id, 'ocr', o.osoba_jmeno, "
            "    u.first_name, u.last_name, NULL::text, "
            "    to_char(o.datum_od,'DD.MM.YYYY'), to_char(o.datum_do,'DD.MM.YYYY'), "
            "    CASE o.stav WHEN 'ukonceno' THEN 'ukonceno' ELSE 'trva' END, "
            "    NULL::text, NULL::text, NULL::text, NULL::text, o.user_id, "
            "    (COALESCE(o.datum_do, current_date) - o.datum_od + 1), o.datum_od "
            "  FROM tenant.att_ocr_case o LEFT JOIN public.users u ON u.id=o.user_id "
            "  WHERE o.tenant_id=2"
            ") q ORDER BY _sort DESC NULLS LAST")).mappings().all()
        return {"ok": True, "polozky": [{k: v for k, v in dict(r).items() if k != '_sort'} for r in rows], "count": len(rows)}
    finally:
        s.close()


def _nempri_esc(s):
    s = "" if s is None else str(s)
    return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            .replace('"', "&quot;"))


# VS/IČ/název zaměstnavatele dle datovky (firmy)
_NEMPRI_EMPLOYER = {
    1: {"vs": "4445158191", "ico": "27960862", "nazev": "EUROSOFT - Control s.r.o.", "kodOSSZ": "342"},
    2: {"vs": "4442058998", "ico": "26411741", "nazev": "EUROSOFT - System s.r.o.", "kodOSSZ": "342"},
}


def _nempri25_ose_xml(d):
    """Sestaví NEMPRI25 datovou větu pro OSE (ošetřovné) z uloženého podání.
    d = dict řádku tenant.davka_podani. Akce dle dat: vznik (je od) + ukončení (je do)."""
    e = _nempri_esc
    emp = _NEMPRI_EMPLOYER.get(d.get("account_id") or 1, _NEMPRI_EMPLOYER[1])
    je_vznik = bool(d.get("datum_od"))
    je_ukonceni = bool(d.get("datum_do"))
    vztah = (d.get("osetrovana_vztah") or "")
    L = []
    L.append('<?xml version="1.0" encoding="UTF-8"?>')
    L.append('<NEMPRI xmlns="http://schemas.cssz.cz/nem/NEMPRI25" version="1.0" partialAccept="A">')
    L.append('<VENDOR productName="STRATEGIE" productVersion="1.0"/>')
    L.append('<datovaVeta poradoveCislo="1">')
    L.append('<dokument>')
    L.append('<kodOSSZ>%s</kodOSSZ>' % e(emp["kodOSSZ"]))
    L.append('<druhDavky>OSE</druhDavky>')
    L.append('<cisloRozhodnuti>%s</cisloRozhodnuti>' % e(d.get("identifikator")))
    L.append('</dokument>')
    L.append('<pojistenec>')
    L.append('<jmeno>%s</jmeno>' % e(d.get("emp_jmeno")))
    L.append('<prijmeni>%s</prijmeni>' % e(d.get("emp_prijmeni")))
    L.append('<rodneCislo>%s</rodneCislo>' % e((d.get("emp_rc") or "").replace("/", "")))
    L.append('</pojistenec>')
    L.append('<zamestnani>')
    L.append('<VSZamestnavatel>%s</VSZamestnavatel>' % e(emp["vs"]))
    L.append('<ICZamestnavatel>%s</ICZamestnavatel>' % e(emp["ico"]))
    L.append('<nazevZamestnavatel>%s</nazevZamestnavatel>' % e(emp["nazev"]))
    L.append('<zamestnanOd>%s</zamestnanOd>' % e(d.get("zamestnan_od") or "2020-01-01"))
    L.append('<druhCinnosti>%s</druhCinnosti>' % e(d.get("druh_cinnosti") or "1"))
    L.append('</zamestnani>')
    L.append('<davka><ose>')
    L.append('<oseVznik>%s</oseVznik>' % ("true" if je_vznik else "false"))
    L.append('<oseTrvani>false</oseTrvani>')
    L.append('<oseUkonceni>%s</oseUkonceni>' % ("true" if je_ukonceni else "false"))
    if je_vznik:
        L.append('<potvrzeniZamestnavatele>')
        L.append('<pracoval>false</pracoval>')
        L.append('<jeStudentem>false</jeStudentem>')
        L.append('<prevedenaNaJinouPraci>false</prevedenaNaJinouPraci>')
        L.append('<volnoBezNahrady>false</volnoBezNahrady>')
        L.append('</potvrzeniZamestnavatele>')
    L.append('<zadostODavku>')
    if je_vznik:
        L.append('<odeDne>%s</odeDne>' % e(d.get("datum_od")))
    if je_ukonceni:
        L.append('<doDne>%s</doDne>' % e(d.get("datum_do")))
    if je_vznik:
        L.append('<osetrovanaOsoba>')
        L.append('<jmeno>%s</jmeno>' % e(d.get("osetrovana_jmeno")))
        L.append('<prijmeni>%s</prijmeni>' % e(d.get("osetrovana_prijmeni")))
        orc = (d.get("osetrovana_rc") or "").replace("/", "")
        if orc:
            L.append('<rodneCislo>%s</rodneCislo>' % e(orc))
        L.append('<onemocnela>true</onemocnela>')
        L.append('<spolecnaDomacnost>%s</spolecnaDomacnost>'
                 % ("true" if d.get("spolecna_domacnost") else "false"))
        L.append('<jeOsamely>false</jeOsamely>')
        L.append('<vPeciDiteDo16Let>false</vPeciDiteDo16Let>')
        L.append('<narokNaPPMjinouOsobou>false</narokNaPPMjinouOsobou>')
        if vztah:
            L.append('<kodRodVztah>%s</kodRodVztah>' % e(vztah))
        L.append('</osetrovanaOsoba>')
    L.append('</zadostODavku>')
    if je_ukonceni:
        L.append('<podkladyProVyplatDavky>')
        L.append('<pracovalPoslDenPD>false</pracovalPoslDenPD>')
        L.append('<planovaneSmeny>false</planovaneSmeny>')
        L.append('<pecovalOsobne>true</pecovalOsobne>')
        L.append('<pecovalVeDnech><obdobi><od>%s</od><do>%s</do></obdobi></pecovalVeDnech>'
                 % (e(d.get("datum_od")), e(d.get("datum_do"))))
        L.append('</podkladyProVyplatDavky>')
    L.append('</ose></davka>')
    if je_vznik:
        L.append('<platebniSpojeni>')
        L.append('<vyplatitUcetCR>true</vyplatitUcetCR>')
        L.append('<vyplatitUcetCizina>false</vyplatitUcetCizina>')
        L.append('<vyplatitAdresa>false</vyplatitAdresa>')
        L.append('<vyplatitHotovost>false</vyplatitHotovost>')
        ucet = (d.get("cislo_uctu") or "")
        cislo, kod = ("", "")
        if "/" in ucet:
            cislo, kod = ucet.split("/", 1)
        L.append('<ucetCZ><ucetCislo>%s</ucetCislo><bankaKod>%s</bankaKod></ucetCZ>'
                 % (e(cislo.strip()), e(kod.strip())))
        L.append('</platebniSpojeni>')
    L.append('</datovaVeta>')
    L.append('</NEMPRI>')
    return "\n".join(L)


_NEMPRI_DRUH = {0: "NEM", 1: "OSE", 2: "OPP", 3: "PPM", 4: "DLO", 5: "VPM"}


@api_router.get("/app/davka/audit")
def davka_audit(req: Request):
    """Měsíční audit dávek: spojí datovku (neschopenky), Helios přílohy a naše podání
    přes číslo rozhodnutí → u každé události kompletnost (nic nezapomenout). Rodič/HR."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not _has_capability(uid, 'neschopenky', 'read'):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    import datetime as _dt
    q = req.query_params
    rok = int(q.get("rok") or _dt.date.today().year)
    mesic = int(q.get("mesic") or _dt.date.today().month)
    zac = "%04d-%02d-01" % (rok, mesic)
    if mesic == 12:
        kon = "%04d-01-01" % (rok + 1)
    else:
        kon = "%04d-%02d-01" % (rok, mesic + 1)
    ev = {}  # klíč = číslo rozhodnutí

    def slot(cr):
        cr = (cr or "").strip()
        if not cr:
            return None
        if cr not in ev:
            ev[cr] = {"cislo": cr, "osoba": "", "typ": "", "od": "", "do": "",
                      "datovka": False, "helios": False, "podani": False, "odeslano": False}
        return ev[cr]

    from core.database_data import get_data_session as _g
    from sqlalchemy import text as _t
    s = _g()
    try:
        # 1) datovka neschopenky (náš registr) — dle data od v měsíci
        for r in s.execute(_t(
            "SELECT cislo_rozhodnuti, emp_jmeno, emp_prijmeni, typ, "
            "to_char(datum_od,'DD.MM') od, to_char(datum_do,'DD.MM') do FROM tenant.eneschopenka "
            "WHERE datum_od >= :z AND datum_od < :k"), {"z": zac, "k": kon}).mappings():
            sl = slot(r["cislo_rozhodnuti"])
            if sl:
                sl["datovka"] = True
                sl["osoba"] = sl["osoba"] or ((r["emp_jmeno"] or "") + " " + (r["emp_prijmeni"] or "")).strip()
                sl["typ"] = sl["typ"] or ("OSE" if r["typ"] == "ocr" else "NEM")
                sl["od"] = sl["od"] or (r["od"] or ""); sl["do"] = sl["do"] or (r["do"] or "")
        # 2) naše podání
        for r in s.execute(_t(
            "SELECT identifikator, emp_jmeno, emp_prijmeni, typ_davky, stav, "
            "to_char(datum_od,'DD.MM') od, to_char(datum_do,'DD.MM') do FROM tenant.davka_podani "
            "WHERE datum_od >= :z AND datum_od < :k"), {"z": zac, "k": kon}).mappings():
            sl = slot(r["identifikator"])
            if sl:
                sl["podani"] = True
                sl["odeslano"] = sl["odeslano"] or (r["stav"] in ("odeslano", "potvrzeno"))
                sl["osoba"] = sl["osoba"] or ((r["emp_jmeno"] or "") + " " + (r["emp_prijmeni"] or "")).strip()
                sl["typ"] = sl["typ"] or (r["typ_davky"] or "")
                sl["od"] = sl["od"] or (r["od"] or ""); sl["do"] = sl["do"] or (r["do"] or "")
    finally:
        s.close()
    # 3) Helios přílohy (MCP) — dle počátku/žádosti v měsíci
    try:
        from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
        import json as _j
        mcp = get_eurosoft_mcp_client()
        if mcp is not None:
            sql = (
                "SELECT CisloRozhodnuti, DruhDavky, Zadost_Jmeno, Zadost_Prijmeni, Stav, "
                "CONVERT(varchar(10),COALESCE(PocatekNemoci,Zadost_DatumOd),104) ud "
                "FROM DB_IS.dbo.TabMzPrilohaDnp "
                "WHERE COALESCE(PocatekNemoci,Zadost_DatumOd) >= '%s' "
                "AND COALESCE(PocatekNemoci,Zadost_DatumOd) < '%s'" % (zac, kon))
            rj = mcp.call_tool_sync("eurosoft_strategie_query_raw", {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
            res = _j.loads(rj) if isinstance(rj, str) else rj
            for r in (res.get("rows") or []):
                d = dict(zip(res.get("columns") or [], r)) if isinstance(r, list) else r
                sl = slot(d.get("CisloRozhodnuti"))
                if sl:
                    sl["helios"] = True
                    sl["odeslano"] = sl["odeslano"] or (str(d.get("Stav")) in ("2", "3"))
                    try:
                        sl["typ"] = sl["typ"] or _NEMPRI_DRUH.get(int(d.get("DruhDavky")), "")
                    except Exception:
                        pass
    except Exception as _he:
        pass
    rows = list(ev.values())
    for r in rows:
        r["kompletni"] = r["helios"] and r["odeslano"]
    rows.sort(key=lambda x: (x["kompletni"], x["osoba"]))
    return {"ok": True, "mesic": mesic, "rok": rok, "polozky": rows, "count": len(rows)}


