@api_router.get("/app/ops/secondary-info")
def secondary_info(req: Request):
    """Živý stav blue-green zálohy: verze A vs B (z běžících instancí), mtime kódu
    v obou složkách (důkaz, že se kopie propsala — git sha zálohy je zmrazený),
    log kroků refreshe + čekající marker. Pro stránku /zaloha-status (progress)."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not is_marti_parent(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    import os as _os, requests as _rq, glob as _glob, datetime as _dt
    out = {"ok": True}
    for key, port in (("a", _os.environ.get("STRATEGIE_PRIMARY_PORT") or "8002"),
                      ("b", _os.environ.get("STRATEGIE_SECONDARY_PORT") or "8003")):
        try:
            out[key] = _rq.get("http://127.0.0.1:%s/api/v1/api-info" % port, timeout=3).json()
        except Exception as e:
            out[key] = {"ok": False, "error": type(e).__name__}
    # mtime klíčového souboru kódu v obou složkách = skutečný důkaz kopie
    src = _os.environ.get("STRATEGIE_PRIMARY_DIR") or r"C:\Projekty\STRATEGIE"
    dst = _os.environ.get("STRATEGIE_PREV_DIR") or r"C:\Projekty\STRATEGIE-prev"
    rel = r"modules\erp\api\router.py"

    def mt(base):
        p = _os.path.join(base, rel)
        try:
            return _dt.datetime.fromtimestamp(_os.path.getmtime(p)).strftime("%d.%m. %H:%M:%S")
        except Exception:
            return None
    out["code_primary"] = mt(src)
    out["code_prev"] = mt(dst)
    # logy: zkus env marker dir i default, vrať soubor s nejnovějším obsahem.
    cand = []
    for d in (_os.environ.get("STRATEGIE_RESTART_MARKER_DIR"), r"C:\Data\STRATEGIE\restart_markers",
              _os.path.join(src, "scripts")):
        if d and d not in cand:
            cand.append(d)

    def read_tail(fname):
        best = ("", None)
        for d in cand:
            p = _os.path.join(d, fname)
            if _os.path.isfile(p):
                try:
                    mt = _os.path.getmtime(p)
                    if best[1] is None or mt > best[1]:
                        with open(p, encoding="utf-8", errors="replace") as f:
                            best = (f.read()[-2500:], mt)
                except Exception:
                    pass
        at = _dt.datetime.fromtimestamp(best[1]).strftime("%d.%m. %H:%M:%S") if best[1] else None
        return best[0], at
    out["log"], out["log_at"] = read_tail("refresh_secondary_last.log")
    out["watcher"], out["watcher_at"] = read_tail("watcher.log")
    # zkráť watcher.log jen na řádky o refreshi (jinak je tam i restart API spam)
    if out["watcher"]:
        wl = [ln for ln in out["watcher"].splitlines() if ("refresh" in ln.lower() or "refreshsec" in ln.lower())]
        out["watcher"] = "\n".join(wl[-25:])
    pend = False
    for d in cand:
        try:
            if _glob.glob(_os.path.join(d, "*.refreshsec")):
                pend = True
                break
        except Exception:
            pass
    out["pending"] = pend
    # --- Self-heal štítku verze (jednou pro vždy, 20.6.) ---------------------
    # fw.api_version "previous" řádek (port 8003 = B) se historicky neaktualizoval
    # → štítek verze ve footeru lhal (B reálně běží povýšený kód, tabulka tvrdila
    # starou verzi). Tady při každém pohledu srovnáme previous řádek s tím, co B
    # SKUTEČNĚ hlásí (z jeho /api-info commit). Když je B v sync s current
    # (= po povýšení do zálohy), previous = current; když je B pozadu (čerstvě po
    # deployi A, před povýšením), nech štítek, jen srovnej git_sha na pravdu.
    try:
        bcommit = (out.get("b") or {}).get("commit") if isinstance(out.get("b"), dict) else None
        if bcommit:
            from core.database_data import get_data_session as _gs
            from sqlalchemy import text as _tx
            _s = _gs()
            try:
                cur = _s.execute(_tx(
                    "SELECT version_string, version_label, git_sha FROM fw.api_version "
                    "WHERE sort_order=0 AND is_active=true LIMIT 1")).mappings().first()
                prev = _s.execute(_tx(
                    "SELECT id, version_string, git_sha FROM fw.api_version "
                    "WHERE sort_order=1 LIMIT 1")).mappings().first()
                if cur and prev:
                    cur_sha = (cur["git_sha"] or "")
                    b_in_sync = bool(cur_sha) and cur_sha.startswith(str(bcommit))
                    if b_in_sync:
                        # B = current → previous řádek zrcadlí current (pravdivý štítek)
                        if (prev["version_string"] != cur["version_string"]
                                or (prev["git_sha"] or "") != cur_sha):
                            _s.execute(_tx(
                                "UPDATE fw.api_version SET version_string=:vs, "
                                "version_label=:vl, git_sha=:sha, released_at=NOW() "
                                "WHERE id=:id"),
                                {"vs": cur["version_string"], "vl": cur["version_label"],
                                 "sha": cur_sha, "id": prev["id"]})
                            _s.commit()
                            out["version_sync"] = "B v sync → štítek srovnán na %s" % cur["version_string"]
                        else:
                            out["version_sync"] = "OK (%s)" % cur["version_string"]
                    else:
                        # B pozadu (před povýšením) → aspoň git_sha ať sedí realitě B
                        if not (prev["git_sha"] or "").startswith(str(bcommit)):
                            _s.execute(_tx(
                                "UPDATE fw.api_version SET git_sha=:sha WHERE id=:id"),
                                {"sha": str(bcommit), "id": prev["id"]})
                            _s.commit()
                        out["version_sync"] = "B pozadu (commit %s) — čeká na povýšení" % bcommit
            finally:
                _s.close()
    except Exception as _e:
        out["version_sync"] = "sync skip: %s" % type(_e).__name__
    return out


@api_router.get("/app/verify-supplier")
def verify_supplier(req: Request):
    """Ověření dodavatele z registrů (ARES identita + ADIS DPH status/zveřejněné účty) —
    NAŠE vlastní ověření s razítkem. Pro stránku /overit. Marti 6.7.2026 (překvapení pro Peťu)."""
    uid = _uid_from_token_or_cookie(req)
    from core.database_data import get_data_session as _gvs
    _svs = _gvs()
    try:
        if not (is_marti_parent(uid) or _is_cockpit(_svs, uid)):
            return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    finally:
        _svs.close()
    import datetime as _dtvs
    q = (req.query_params.get("q") or "").strip().upper().replace(" ", "")
    digits = "".join(ch for ch in q.replace("CZ", "") if ch.isdigit())
    if not digits:
        return JSONResponse({"ok": False, "error": "Zadej IČO nebo DIČ."})
    ico = digits.zfill(8) if len(digits) <= 8 else digits
    from modules.erp.api.registr_verify import ares_lookup as _ar, dph_lookup as _dl
    ares = _ar(ico)
    dic = (ares.get("dic") if ares.get("ok") else None) or ("CZ" + digits)
    try:
        dph = _dl(dic)
    except Exception as _e:
        dph = {"ok": False, "error": "%s: %s" % (type(_e).__name__, str(_e)[:150])}
    return {"ok": True, "q": q, "ico": ico, "dic": dic, "ares": ares, "dph": dph,
            "overeno_at": _dtvs.datetime.now().strftime("%d.%m.%Y %H:%M")}


@api_router.post("/app/ops/secondary-refresh")
async def secondary_refresh(req: Request):
    """Spustí refresh zálohy (zapíše .refreshsec marker → RESTART-WATCHER). Pro tlačítko na stránce."""
    uid = _uid_from_token_or_cookie(req)
    if not uid or not is_marti_parent(uid):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    try:
        b = await req.json()
    except Exception:
        b = {}
    import json as _json, os as _os, datetime as _dt
    mdir = _os.environ.get("STRATEGIE_RESTART_MARKER_DIR") or r"C:\Data\STRATEGIE\restart_markers"
    try:
        from pathlib import Path as _P
        _P(mdir).mkdir(parents=True, exist_ok=True)
        ts = _dt.datetime.utcnow().strftime("%Y%m%d_%H%M%S")
        mp = _os.path.join(mdir, "%s_refreshsec.refreshsec" % ts)
        with open(mp, "w", encoding="utf-8") as f:
            f.write(_json.dumps({"deps": bool(b.get("deps")), "by": "user_%s" % uid}))
        return {"ok": True, "marker": _os.path.basename(mp)}
    except Exception as exc:
        return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, exc)})


