@api_router.post("/diag-sql")
async def diag_sql(req: Request) -> JSONResponse:
    """Claude SQL bridge (1.6.2026, Marti: "máme na to tooly ve STRATEGII"):
    read-only diagnostický SQL proti PRODUKCI přes existující tooly —
    strategie_pg.query_raw (PG) / EUROSOFT MCP strategie_query_raw (MSSQL).
    Běží na cloud APP (dosáhne na cloud SQL i MSSQL). Volá NB watcher
    (forwarder přes HTTPS). Auth: parent session NEBO X-Deploy-Token.
    Read-only guard je v query_raw (SELECT/WITH/EXPLAIN/SHOW)."""
    import os as _os_ds
    token = req.headers.get("X-Deploy-Token")
    env_token = _os_ds.environ.get("STRATEGIE_DEPLOY_TOKEN")
    actor = "token"
    if token and env_token and token == env_token:
        pass
    else:
        uid = _get_uid(req)
        _require_parent(uid)  # bridge /diag-sql = rodičovské (raw SQL proti produkci)
        actor = "user_%s" % uid

    try:
        body = await req.json()
    except Exception:
        body = {}
    sql = (str(body.get("sql") or "")).strip()
    db = (str(body.get("db") or "pg")).strip().lower()
    # Atribuce (Marti 2.6.): token auth -> ktera instance Claude (23/24)
    _inst = str(body.get("instance_id") or "").strip()
    if actor == "token" and _inst and _inst != "?":
        actor = "Claude-%s" % _inst
    # Presence board (Marti 3.6.): instance prave bezi SQL pres bridge.
    _record_instance_presence(_inst, "sql", body.get("hostname"))
    if not sql:
        return JSONResponse({"ok": False, "error": "sql chybí"}, status_code=400)

    # GO doc seal (Claude C23, 18.7.2026): zapecet docs/GO/Z_<slug>.md do g2007.znalost.
    #   @@GODOC <slug> [| <nadpis>]  -> kod=doc-go-<slug>, oblast=system-g2007, +reindex.
    # Autonomie: Claude pecetim GO dokumenty sam pres bridge (bez parent POST popupu).
    if sql.upper().startswith("@@GODOC"):
        from sqlalchemy import text as _tg
        _rest = sql[len("@@GODOC"):].strip()
        if not _rest:
            return JSONResponse({"ok": False, "error": "@@GODOC <slug> [| <nadpis>]"})
        _p = [x.strip() for x in _rest.split("|", 1)]
        _slug = _p[0].strip().lstrip("/")
        _nadpis = _p[1].strip() if len(_p) > 1 else ""
        _repo = _g2007_repo_root()
        _zdroj = "docs/GO/Z_%s.md" % _slug
        _src = _os_ds.path.join(_repo, _zdroj.replace("/", _os_ds.sep))
        if not _os_ds.path.isfile(_src):
            return JSONResponse({"ok": False, "error": "zdroj neni na serveru (deployni Z_ napred): %s" % _zdroj})
        with open(_src, "r", encoding="utf-8") as _fh:
            _obsah = _fh.read()
        if not _nadpis:
            for _ln in _obsah.splitlines():
                if _ln.startswith("# "):
                    _nadpis = _ln[2:].strip()
                    break
        _kod = "doc-go-%s" % _slug
        from core.database import get_session as _gg
        _sg = _gg()
        try:
            _oid = _sg.execute(_tg("SELECT id FROM g2007.znalost_oblast WHERE kod='system-g2007'")).scalar()
            if not _oid:
                return JSONResponse({"ok": False, "error": "oblast system-g2007 chybi"})
            _ex = _sg.execute(_tg("SELECT id FROM g2007.znalost WHERE kod=:k"), {"k": _kod}).scalar()
            if _ex:
                _sg.execute(_tg("UPDATE g2007.znalost SET oblast_id=:o, uroven='system', typ='dokument', "
                                "nadpis=:n, obsah=:c, zdroj=:z, stav='aktivni', verze_schvalena=true, "
                                "updated_at=now() WHERE kod=:k"),
                            {"o": _oid, "n": _nadpis, "c": _obsah, "z": _zdroj, "k": _kod})
                _znid = _ex
            else:
                _znid = _sg.execute(_tg("INSERT INTO g2007.znalost (oblast_id, uroven, typ, kod, nadpis, "
                                        "obsah, zdroj, stav, verze, verze_schvalena) "
                                        "VALUES (:o,'system','dokument',:k,:n,:c,:z,'aktivni','V1.0',true) "
                                        "RETURNING id"),
                                     {"o": _oid, "k": _kod, "n": _nadpis, "c": _obsah, "z": _zdroj}).scalar()
            _sg.commit()
        except Exception as _e:
            try:
                _sg.rollback()
            except Exception:
                pass
            return JSONResponse({"ok": False, "error": "GODOC upsert %s: %s" % (type(_e).__name__, str(_e)[:300])})
        finally:
            _sg.close()
        _reidx = None
        try:
            from modules.erp.api.g2007_vectors import reindex_by_kod as _ri
            _reidx = _ri(_kod)
        except Exception as _re:
            _reidx = "chyba reindex: %s" % str(_re)[:200]
        return JSONResponse({"ok": True, "kod": _kod, "id": _znid, "nadpis": _nadpis,
                             "zdroj": _zdroj, "reindexovano": _reidx})

    # Souborový most (Marti 20.6.2026): čtení reálných faktur pro EDI/auto-pořizování.
    #   @@FILES LIST <abs_cesta>            → výpis adresáře (soubor + velikost)
    #   @@FILES READ <abs_cesta_k_souboru>  → obsah souboru (text/base64)
    # Přes EUROSOFT MCP filesystem (RO namespace, base_override). Cesta musí být
    # v MCP_FS_RO_ROOTS na EC-SERVER2 (D:\data\FakturyP apod.).
    if sql.upper().startswith("@@FILES"):
        import json as _jf, os.path as _op
        parts = sql.split(None, 2)
        op = (parts[1].upper() if len(parts) > 1 else "")
        path = (parts[2].strip() if len(parts) > 2 else "")
        # @@FILES PUTREPO <rw_dest_path> <repo_rel_src>
        #   Zkopíruje JIŽ COMMITNUTÝ soubor z repo working-dir cloudu na EUROSOFT
        #   RW share (ZZ_Marti-AI RW/...) přes MCP file_write. Binárka neteče bridgem.
        #   Pro zpřístupnění souborů Marti-AI (čte z RW zóny). Marti+Kristý 22.6.2026.
        if op == "PUTREPO":
            import os as _osf, base64 as _b64f
            a = path.split(None, 1)
            if len(a) < 2:
                return JSONResponse({"ok": False, "error": "@@FILES PUTREPO <rw_dest> <repo_src>"})
            rw_dest, repo_src = a[0].strip().lstrip("/"), a[1].strip()
            repo_root = _op.abspath(_op.join(_op.dirname(__file__), "..", "..", ".."))
            src_abs = _op.normpath(_op.join(repo_root, repo_src))
            if not src_abs.startswith(repo_root) or not _op.isfile(src_abs):
                return JSONResponse({"ok": False, "error": "repo soubor nenalezen: " + repo_src})
            try:
                with open(src_abs, "rb") as _fh:
                    data = _fh.read()
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                raw = mcp.call_tool_sync("eurosoft_eurosoft_file_write",
                                         {"user_namespace": "rw", "path": rw_dest,
                                          "content": _b64f.b64encode(data).decode("ascii"),
                                          "encoding": "base64", "mode": "overwrite"},
                                         conversation_id=None)
                r = _jf.loads(raw) if isinstance(raw, str) else raw
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "MCP zápis selhal: " + str(exc)[:160]})
            if isinstance(r, dict) and r.get("ok"):
                unc = "\\\\EC-SERVER2\\Data\\ZZ_Marti-AI RW\\" + rw_dest.replace("/", "\\")
                return JSONResponse({"ok": True, "columns": ["soubor", "bytes", "unc"],
                                     "rows": [[rw_dest, len(data), unc]], "count": 1})
            return JSONResponse({"ok": False, "error": (r.get("error") if isinstance(r, dict) else "zápis na RW selhal")})
        # @@FILES WRITE <abs_file_path>\n<base64 obsah>  → zapíše binárku na RW root (base_override).
        #   Parent složka se auto-vytvoří. Pro generátor platáků (task #45): render .p11/.f84 →
        #   zápis do D:\data\RB\Platební příkazy\{EC|ES}\<RRRRMMDD>\. Marti 7.7.2026.
        if op == "WRITE":
            import base64 as _b64w, os as _osw2
            a = path.split("\n", 1)
            if len(a) < 2 or not a[0].strip():
                return JSONResponse({"ok": False, "error": "@@FILES WRITE <abs_path>\\n<base64>"})
            abs_path = a[0].strip().strip('"')
            b64c = "".join(a[1].split())
            _dir = _osw2.path.dirname(abs_path)
            _fn = _osw2.path.basename(abs_path)
            if not _dir or not _fn:
                return JSONResponse({"ok": False, "error": "neplatná absolutní cesta"})
            try:
                nbytes = len(_b64w.b64decode(b64c, validate=True))
            except Exception as _eb:
                return JSONResponse({"ok": False, "error": "špatný base64: " + str(_eb)[:80]})
            try:
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                raw = mcp.call_tool_sync("eurosoft_eurosoft_file_write",
                                         {"user_namespace": "rw", "base_override": _dir, "path": _fn,
                                          "content": b64c, "encoding": "base64", "mode": "overwrite"},
                                         conversation_id=None)
                r = _jf.loads(raw) if isinstance(raw, str) else raw
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "MCP zápis selhal: " + str(exc)[:160]})
            if isinstance(r, dict) and r.get("ok"):
                return JSONResponse({"ok": True, "columns": ["soubor", "bytes", "abs"],
                                     "rows": [[_fn, nbytes, r.get("abs_path", abs_path)]], "count": 1})
            return JSONResponse({"ok": False, "error": (r.get("error") if isinstance(r, dict) else "zápis selhal")})
        # @@FILES DEL <abs_file_path>  → smaže JEDEN soubor na RW rootu (base_override). Marti 7.7.2026.
        if op == "DEL":
            import os as _osd
            abs_path = path.strip().strip('"')
            if not abs_path:
                return JSONResponse({"ok": False, "error": "@@FILES DEL <abs_path>"})
            _dir = _osd.path.dirname(abs_path)
            _fn = _osd.path.basename(abs_path)
            if not _dir or not _fn:
                return JSONResponse({"ok": False, "error": "neplatná absolutní cesta"})
            try:
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                raw = mcp.call_tool_sync("eurosoft_eurosoft_file_delete",
                                         {"user_namespace": "rw", "base_override": _dir, "path": _fn},
                                         conversation_id=None)
                r = _jf.loads(raw) if isinstance(raw, str) else raw
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "MCP mazání selhalo: " + str(exc)[:160]})
            if isinstance(r, dict) and r.get("ok"):
                return JSONResponse({"ok": True, "columns": ["smazano"], "rows": [[abs_path]], "count": 1})
            return JSONResponse({"ok": False, "error": (r.get("error") if isinstance(r, dict) else "mazání selhalo")})
        # @@FILES PUTDOC <rw_dest_path> <doc_id>
        #   Zkopíruje dokument z úložiště (public.documents.storage_path, mimo repo)
        #   na EUROSOFT RW share přes MCP file_write. Pro zpřístupnění Marti-AI generovaných
        #   PDF/dokumentů do RW zóny (ZZ_Marti-AI RW/...). Marti 4.7.2026.
        if op == "PUTDOC":
            import base64 as _b64d
            from sqlalchemy import text as _tpd
            a = path.split(None, 1)
            if len(a) < 2:
                return JSONResponse({"ok": False, "error": "@@FILES PUTDOC <rw_dest> <doc_id>"})
            rw_dest = a[0].strip().lstrip("/")
            try:
                doc_id = int(a[1].strip())
            except ValueError:
                return JSONResponse({"ok": False, "error": "doc_id musí být číslo"})
            from core.database_data import get_data_session as _gdspd
            _dspd = _gdspd()
            try:
                drow = _dspd.execute(_tpd(
                    "SELECT storage_path FROM public.documents WHERE id=:i"),
                    {"i": doc_id}).first()
            finally:
                _dspd.close()
            if not drow or not drow[0] or not _op.isfile(drow[0]):
                return JSONResponse({"ok": False, "error": "dokument nemá soubor na disku: %s" % doc_id})
            try:
                with open(drow[0], "rb") as _fh:
                    data = _fh.read()
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                raw = mcp.call_tool_sync("eurosoft_eurosoft_file_write",
                                         {"user_namespace": "rw", "path": rw_dest,
                                          "content": _b64d.b64encode(data).decode("ascii"),
                                          "encoding": "base64", "mode": "overwrite"},
                                         conversation_id=None)
                r = _jf.loads(raw) if isinstance(raw, str) else raw
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "MCP zápis selhal: " + str(exc)[:160]})
            if isinstance(r, dict) and r.get("ok"):
                unc = "\\\\EC-SERVER2\\Data\\ZZ_Marti-AI RW\\" + rw_dest.replace("/", "\\")
                return JSONResponse({"ok": True, "columns": ["soubor", "bytes", "unc"],
                                     "rows": [[rw_dest, len(data), unc]], "count": 1})
            return JSONResponse({"ok": False, "error": (r.get("error") if isinstance(r, dict) else "zápis na RW selhal")})
        # @@FILES PUTREPODIR <rw_dest_dir> <repo_rel_dir>  — zkopíruje všechny soubory ze složky
        if op == "PUTREPODIR":
            import os as _osd, base64 as _b64d
            a = path.split(None, 1)
            if len(a) < 2:
                return JSONResponse({"ok": False, "error": "@@FILES PUTREPODIR <rw_dir> <repo_dir>"})
            rw_dir, repo_dir = a[0].strip().lstrip("/").rstrip("/"), a[1].strip()
            repo_root = _op.abspath(_op.join(_op.dirname(__file__), "..", "..", ".."))
            src_dir = _op.normpath(_op.join(repo_root, repo_dir))
            if not src_dir.startswith(repo_root) or not _op.isdir(src_dir):
                return JSONResponse({"ok": False, "error": "repo složka nenalezena: " + repo_dir})
            try:
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                done, errs = [], []
                for fn in sorted(_osd.listdir(src_dir)):
                    fp = _op.join(src_dir, fn)
                    if not _op.isfile(fp):
                        continue
                    with open(fp, "rb") as _fh:
                        data = _fh.read()
                    raw = mcp.call_tool_sync("eurosoft_eurosoft_file_write",
                                             {"user_namespace": "rw", "path": rw_dir + "/" + fn,
                                              "content": _b64d.b64encode(data).decode("ascii"),
                                              "encoding": "base64", "mode": "overwrite"},
                                             conversation_id=None)
                    rr = _jf.loads(raw) if isinstance(raw, str) else raw
                    if isinstance(rr, dict) and rr.get("ok"):
                        done.append([fn, len(data), "OK"])
                    else:
                        done.append([fn, len(data), "ERR: " + str(rr.get("error") if isinstance(rr, dict) else rr)[:60]])
                        errs.append(fn)
                return JSONResponse({"ok": True, "columns": ["soubor", "bytes", "stav"],
                                     "rows": done, "count": len(done)})
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "MCP zápis selhal: " + str(exc)[:160]})
        # @@FILES COPY <src_abs> >> <dst_ro_subpath>  — server-side kopie RW→RO přes MCP
        #   (Claude BOZP/PO úklid 2.7.2026). Čte přes base_override (funguje na RW i RO),
        #   zapisuje do RO namespace. Pro binárky přes base64. Oddělovač " >> " (cesty mají mezery).
        if op == "COPY":
            import base64 as _b64c
            if " >> " not in path:
                return JSONResponse({"ok": False, "error": "@@FILES COPY <src_abs> >> <dst_ro_subpath>"})
            src_abs, dst_rel = [x.strip() for x in path.split(" >> ", 1)]
            dst_rel = dst_rel.lstrip("/").replace("\\", "/")
            try:
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                _sb = _op.dirname(src_abs); _sf = _op.basename(src_abs)
                raw = mcp.call_tool_sync("eurosoft_eurosoft_file_read",
                                         {"user_namespace": "ro", "base_override": _sb, "path": _sf,
                                          "encoding": "base64"}, conversation_id=None)
                rr = _jf.loads(raw) if isinstance(raw, str) else raw
                if isinstance(rr, dict) and rr.get("ok") is False:
                    return JSONResponse({"ok": False, "error": "čtení RW: " + str(rr.get("error") or rr)})
                b64 = (rr.get("content") or rr.get("data") or "") if isinstance(rr, dict) else str(rr)
                nbytes = len(_b64c.b64decode(b64)) if b64 else 0
                raw2 = mcp.call_tool_sync("eurosoft_eurosoft_file_write",
                                          {"user_namespace": "ro", "path": dst_rel,
                                           "content": b64, "encoding": "base64", "mode": "overwrite"},
                                          conversation_id=None)
                r2 = _jf.loads(raw2) if isinstance(raw2, str) else raw2
                if isinstance(r2, dict) and r2.get("ok"):
                    return JSONResponse({"ok": True, "columns": ["cil", "bytes"], "rows": [[dst_rel, nbytes]], "count": 1})
                return JSONResponse({"ok": False, "error": "zápis do RO: " + str((r2.get("error") if isinstance(r2, dict) else r2))[:180]})
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, str(exc)[:160])})
        # @@FILES DIRCOPY <src_dir> >> <dst_ro_dir>  — server-side REKURZIVNÍ kopie (1 volání)
        if op == "DIRCOPY":
            if " >> " not in path:
                return JSONResponse({"ok": False, "error": "@@FILES DIRCOPY <src_dir> >> <dst_ro_dir>"})
            _sd, _dd = [x.strip() for x in path.split(" >> ", 1)]
            _dd = _dd.strip("/").replace("\\", "/")
            try:
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                raw = mcp.call_tool_sync("eurosoft_eurosoft_dir_copy",
                                         {"src_base_override": _sd.rstrip("\\/"), "dst_namespace": "ro",
                                          "dst_path": _dd}, conversation_id=None)
                r = _jf.loads(raw) if isinstance(raw, str) else raw
                if isinstance(r, dict) and r.get("ok"):
                    return JSONResponse({"ok": True, "columns": ["zkopirovano", "balast_delete", "preskoceno", "chyb"],
                                         "rows": [[r.get("copied"), r.get("junk_to_delete"), r.get("skipped_existing"), r.get("errors")]],
                                         "count": 1, "note": str(r.get("err_sample") or "")[:300]})
                return JSONResponse({"ok": False, "error": str((r.get("error") if isinstance(r, dict) else r))[:200]})
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, str(exc)[:160])})
        # @@FILES REORG <base_abs> \n <src_rel> >> <dst_rel> ...  — hromadné přejmenování/přesun v bázi
        #   (fs_reorg; SSE refresh 2.7.2026)
        if op == "REORG":
            _lines = path.splitlines()
            _base = _lines[0].strip() if _lines else ""
            _moves = []
            for ln in _lines[1:]:
                ln = ln.strip()
                if " >> " in ln:
                    s, d = ln.split(" >> ", 1)
                    _moves.append({"src": s.strip(), "dst": d.strip()})
            if not _base or not _moves:
                return JSONResponse({"ok": False, "error": "@@FILES REORG <base_abs> + řádky 'src_rel >> dst_rel'"})
            try:
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                # base_override (absolutní RO cesta) — MCP fs_reorg si RO cestu sám přemapuje
                # na namespace 'ro' (zapisovatelně). Kompatibilní se starým cached SSE spec.
                raw = mcp.call_tool_sync("eurosoft_eurosoft_fs_reorg",
                                         {"namespace": "ro", "base_override": _base.rstrip("\\/"), "moves": _moves},
                                         conversation_id=None)
                r = _jf.loads(raw) if isinstance(raw, str) else raw
                if isinstance(r, dict) and r.get("ok"):
                    return JSONResponse({"ok": True, "columns": ["cil", "stav"],
                                         "rows": (r.get("detail") or [])[:60], "count": len(r.get("detail") or []),
                                         "note": "přesunuto %s, skip %s, chyb %s" % (r.get("moved"), r.get("skipped"), r.get("errors"))})
                return JSONResponse({"ok": False, "error": str((r.get("error") if isinstance(r, dict) else r))[:200]})
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, str(exc)[:160])})
        # @@FILES RMDIR <slozka_abs> [recursive]  — smaž složku (default prázdnou; 'recursive' = i obsah)
        if op == "RMDIR":
            _arg = (parts[2] if len(parts) > 2 else "").strip()
            _rec = False
            if _arg.lower().endswith(" recursive"):
                _rec = True
                _arg = _arg[:-len(" recursive")].strip()
            _arg = _arg.splitlines()[0].strip() if _arg else ""
            if not _arg:
                return JSONResponse({"ok": False, "error": "@@FILES RMDIR <slozka_abs> [recursive]"})
            try:
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                raw = mcp.call_tool_sync("eurosoft_eurosoft_dir_delete",
                                         {"namespace": "ro", "base_override": _arg.rstrip("\\/"), "recursive": _rec},
                                         conversation_id=None)
                r = _jf.loads(raw) if isinstance(raw, str) else raw
                if isinstance(r, dict) and r.get("ok"):
                    return JSONResponse({"ok": True, "columns": ["klic", "hodnota"],
                                         "rows": [[k, str(v)] for k, v in r.items() if k != "ok"],
                                         "count": len(r) - 1})
                return JSONResponse({"ok": False, "error": str((r.get("error") if isinstance(r, dict) else r))[:200]})
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, str(exc)[:160])})
        # @@FILES COPYBATCH \n <src1> >> <dst1> \n <src2> >> <dst2> ...  — dávková kopie RW→RO
        if op == "COPYBATCH":
            import base64 as _b64cb
            body = parts[2] if len(parts) > 2 else ""
            pairs = []
            for ln in body.splitlines():
                ln = ln.strip()
                if not ln or " >> " not in ln:
                    continue
                s, d = ln.split(" >> ", 1)
                pairs.append((s.strip(), d.strip().lstrip("/").replace("\\", "/")))
            if not pairs:
                return JSONResponse({"ok": False, "error": "@@FILES COPYBATCH + řádky 'src >> dst'"})
            try:
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                rows = []
                for src_abs, dst_rel in pairs:
                    try:
                        _sb = _op.dirname(src_abs); _sf = _op.basename(src_abs)
                        raw = mcp.call_tool_sync("eurosoft_eurosoft_file_read",
                                                 {"user_namespace": "ro", "base_override": _sb, "path": _sf,
                                                  "encoding": "base64"}, conversation_id=None)
                        rr = _jf.loads(raw) if isinstance(raw, str) else raw
                        if isinstance(rr, dict) and rr.get("ok") is False:
                            rows.append([dst_rel, 0, "ERR read: " + str(rr.get("error"))[:70]]); continue
                        b64 = (rr.get("content") or rr.get("data") or "") if isinstance(rr, dict) else str(rr)
                        nbytes = len(_b64cb.b64decode(b64)) if b64 else 0
                        raw2 = mcp.call_tool_sync("eurosoft_eurosoft_file_write",
                                                  {"user_namespace": "ro", "path": dst_rel,
                                                   "content": b64, "encoding": "base64", "mode": "overwrite"},
                                                  conversation_id=None)
                        r2 = _jf.loads(raw2) if isinstance(raw2, str) else raw2
                        rows.append([dst_rel, nbytes, "OK" if (isinstance(r2, dict) and r2.get("ok")) else "ERR write: " + str((r2.get("error") if isinstance(r2, dict) else r2))[:60]])
                    except Exception as _ex:
                        rows.append([dst_rel, 0, "EXC: " + str(_ex)[:60]])
                _okc = sum(1 for r in rows if r[2] == "OK")
                return JSONResponse({"ok": True, "columns": ["cil", "bytes", "stav"], "rows": rows,
                                     "count": len(rows), "note": "%d/%d OK" % (_okc, len(rows))})
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, str(exc)[:160])})
        # @@FILES COPYDIR <src_dir> >> <dst_ro_dir>  — zkopíruje soubory ze složky RW→RO
        #   (nativní eurosoft_file_copy; SSE refresh 2.7.2026)
        #   Přeskočí balast (Thumbs.db, ~$, _files), obří (>15MB), a už existující v cíli.
        #   Dávkuje max 12 souborů/běh (kvůli 30s timeoutu) → re-spustitelné dokud "zbyva">0.
        if op == "COPYDIR":
            import base64 as _b64d2
            if " >> " not in path:
                return JSONResponse({"ok": False, "error": "@@FILES COPYDIR <src_dir> >> <dst_ro_dir>"})
            src_dir, dst_dir = [x.strip() for x in path.split(" >> ", 1)]
            src_dir = src_dir.rstrip("\\/"); dst_dir = dst_dir.strip("/").replace("\\", "/")
            try:
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                def _names(base):
                    try:
                        raw = mcp.call_tool_sync("eurosoft_eurosoft_file_list",
                                                 {"user_namespace": "ro", "base_override": base, "subpath": ""},
                                                 conversation_id=None)
                        r = _jf.loads(raw) if isinstance(raw, str) else raw
                        items = (r.get("items") or r.get("files") or r.get("entries") or []) if isinstance(r, dict) else (r or [])
                        out = []
                        for it in items:
                            if isinstance(it, dict):
                                out.append((it.get("name") or it.get("filename") or it.get("path"),
                                            it.get("type") or ("dir" if it.get("is_dir") else "file"),
                                            it.get("size") or 0))
                            else:
                                out.append((it, "file", 0))
                        return out
                    except Exception:
                        return []
                dst_have = set(n for (n, t, sz) in _names("D:\\Data\\ZZ_Marti-AI RO\\" + dst_dir.replace("/", "\\")))
                HUGE = 15 * 1024 * 1024
                rows = []; done = 0; left = 0
                for (nm, typ, sz) in _names(src_dir):
                    if typ == "dir":
                        continue
                    if nm == "Thumbs.db" or str(nm).startswith("~$"):
                        continue
                    if nm in dst_have:
                        continue
                    if done >= 20:
                        left += 1; continue
                    try:
                        # NATIVNÍ server-side kopie (shutil) — okamžitá, jakákoliv velikost
                        raw = mcp.call_tool_sync("eurosoft_eurosoft_file_copy",
                                                 {"src_base_override": src_dir, "src_path": nm,
                                                  "dst_namespace": "ro", "dst_path": dst_dir + "/" + nm,
                                                  "overwrite": True}, conversation_id=None)
                        rr = _jf.loads(raw) if isinstance(raw, str) else raw
                        if isinstance(rr, dict) and rr.get("ok"):
                            rows.append([nm, rr.get("bytes") or sz, "OK"]); done += 1
                        else:
                            rows.append([nm, sz, "ERR: " + str((rr.get("error") if isinstance(rr, dict) else rr))[:60]])
                    except Exception as _ex:
                        rows.append([nm, 0, "EXC: " + str(_ex)[:50]])
                return JSONResponse({"ok": True, "columns": ["soubor", "bytes", "stav"], "rows": rows,
                                     "count": len(rows), "note": "zkopírováno %d, zbývá %d (spusť znovu dokud 0)" % (done, left)})
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, str(exc)[:160])})
        # @@FILES COPYTREE <src_root> >> <dst_ro_root>  — REKURZIVNÍ kopie celého stromu RW→RO
        #   Zachová strukturu. Balast (_files webu, Thumbs.db, ~$, .db) → <dst>/_DELETE/.
        #   Ostatní → <dst>/. Přeskočí už existující (re-spustitelné). Cap 25 kopií/běh.
        if op == "COPYTREE":
            if " >> " not in path:
                return JSONResponse({"ok": False, "error": "@@FILES COPYTREE <src_root> >> <dst_ro_root>"})
            src_root, dst_root = [x.strip() for x in path.split(" >> ", 1)]
            src_root = src_root.rstrip("\\/"); dst_root = dst_root.strip("/").replace("\\", "/")
            try:
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                def _walk(root):
                    files = []; q = [root]; seen = 0
                    while q and seen < 3000:
                        cur = q.pop(0); seen += 1
                        raw = mcp.call_tool_sync("eurosoft_eurosoft_file_list",
                                                 {"user_namespace": "ro", "base_override": cur, "subpath": ""},
                                                 conversation_id=None)
                        r = _jf.loads(raw) if isinstance(raw, str) else raw
                        for it in ((r.get("items") or r.get("files") or r.get("entries") or []) if isinstance(r, dict) else (r or [])):
                            if isinstance(it, dict):
                                nm = it.get("name") or it.get("filename") or it.get("path")
                                typ = it.get("type") or ("dir" if it.get("is_dir") else "file"); szz = it.get("size") or 0
                            else:
                                nm, typ, szz = it, "file", 0
                            full = cur + "\\" + str(nm)
                            if typ == "dir": q.append(full)
                            else: files.append((full[len(root):].lstrip("\\/").replace("\\", "/"), szz))
                    return files
                src_files = _walk(src_root)
                have = set(rel for rel, _ in _walk("D:\\Data\\ZZ_Marti-AI RO\\" + dst_root.replace("/", "\\")))
                def _is_junk(rel):
                    low = rel.lower(); base = rel.split("/")[-1]
                    return ("_files/" in low or base == "Thumbs.db" or base.startswith("~$")
                            or base.endswith(".db") or base.endswith(".tmp"))
                rows = []; done = 0; left = 0
                for rel, szz in src_files:
                    tgt = ("_DELETE/" + rel) if _is_junk(rel) else rel
                    if tgt in have:
                        continue
                    if done >= 25:
                        left += 1; continue
                    try:
                        raw = mcp.call_tool_sync("eurosoft_eurosoft_file_copy",
                                                 {"src_base_override": src_root.rstrip("\\") + "\\" + rel.replace("/", "\\").rsplit("\\", 1)[0] if "/" in rel else src_root,
                                                  "src_path": rel.split("/")[-1],
                                                  "dst_namespace": "ro", "dst_path": dst_root + "/" + tgt,
                                                  "overwrite": True}, conversation_id=None)
                        rr = _jf.loads(raw) if isinstance(raw, str) else raw
                        if isinstance(rr, dict) and rr.get("ok"):
                            rows.append([tgt, rr.get("bytes") or szz, "OK"]); done += 1
                        else:
                            rows.append([tgt, szz, "ERR: " + str((rr.get("error") if isinstance(rr, dict) else rr))[:50]])
                    except Exception as _ex:
                        rows.append([tgt, 0, "EXC: " + str(_ex)[:50]])
                return JSONResponse({"ok": True, "columns": ["cil", "bytes", "stav"], "rows": rows[:40],
                                     "count": len(src_files), "note": "zdroj %d souborů, zkopírováno %d, zbývá %d (spusť znovu dokud 0)" % (len(src_files), done, left)})
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, str(exc)[:160])})
        # @@FILES LISTREC <abs_root>  — rekurzivní výpis (server-side BFS přes MCP file_list)
        if op == "LISTREC":
            try:
                from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
                mcp = get_eurosoft_mcp_client()
                if mcp is None:
                    return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
                root = path.rstrip("\\/")
                queue = [root]; rows = []; seen = 0
                while queue and seen < 4000:
                    cur = queue.pop(0); seen += 1
                    raw = mcp.call_tool_sync("eurosoft_eurosoft_file_list",
                                             {"user_namespace": "ro", "base_override": cur, "subpath": ""},
                                             conversation_id=None)
                    r = _jf.loads(raw) if isinstance(raw, str) else raw
                    items = (r.get("items") or r.get("files") or r.get("entries") or []) if isinstance(r, dict) else (r or [])
                    for it in items:
                        if isinstance(it, dict):
                            nm = it.get("name") or it.get("filename") or it.get("path")
                            typ = it.get("type") or ("dir" if it.get("is_dir") else "file")
                            sz = it.get("size")
                        else:
                            nm, typ, sz = it, "file", None
                        full = cur + "\\" + str(nm)
                        rel = full[len(root):].lstrip("\\/")
                        if typ == "dir":
                            queue.append(full)
                        else:
                            rows.append([rel, sz])
                return JSONResponse({"ok": True, "columns": ["rel_cesta", "velikost"], "rows": rows,
                                     "count": len(rows), "note": "%d souborů, %d složek proskenováno" % (len(rows), seen)})
            except Exception as exc:
                return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, str(exc)[:160])})
        if op not in ("LIST", "READ") or not path:
            return JSONResponse({"ok": False, "error": "@@FILES LIST|READ|COPY|COPYBATCH|LISTREC|PUTREPO|PUTREPODIR <cesta>"})
        try:
            from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
            mcp = get_eurosoft_mcp_client()
            if mcp is None:
                return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
            if op == "LIST":
                raw = mcp.call_tool_sync("eurosoft_eurosoft_file_list",
                                         {"user_namespace": "ro", "base_override": path, "subpath": ""},
                                         conversation_id=None)
                r = _jf.loads(raw) if isinstance(raw, str) else raw
                if isinstance(r, dict) and r.get("ok") is False:
                    return JSONResponse({"ok": False, "error": str(r.get("error") or r)})
                items = (r.get("items") or r.get("files") or r.get("entries") or []) if isinstance(r, dict) else (r or [])
                rows = []
                for it in items:
                    if isinstance(it, dict):
                        rows.append([it.get("name") or it.get("filename") or it.get("path"),
                                     it.get("type") or ("dir" if it.get("is_dir") else "file"),
                                     it.get("size")])
                    else:
                        rows.append([it, "", ""])
                return JSONResponse({"ok": True, "columns": ["nazev", "typ", "velikost"],
                                     "rows": rows, "count": len(rows)})
            else:
                base = _op.dirname(path); fn = _op.basename(path)
                raw = mcp.call_tool_sync("eurosoft_eurosoft_file_read",
                                         {"user_namespace": "ro", "base_override": base, "path": fn,
                                          "encoding": "base64"},
                                         conversation_id=None)
                r = _jf.loads(raw) if isinstance(raw, str) else raw
                if isinstance(r, dict) and r.get("ok") is False:
                    return JSONResponse({"ok": False, "error": str(r.get("error") or r)})
                import base64 as _b64
                b64 = (r.get("content") or r.get("data") or "") if isinstance(r, dict) else str(r)
                try:
                    rawbytes = _b64.b64decode(b64)
                except Exception:
                    rawbytes = b""
                low = fn.lower()
                if low.endswith(".pdf"):
                    text = None
                    try:
                        import io as _io, pdfplumber as _pp
                        with _pp.open(_io.BytesIO(rawbytes)) as pdf:
                            text = "\n".join((pg.extract_text() or "") for pg in pdf.pages)
                    except Exception:
                        try:
                            import io as _io2
                            from pypdf import PdfReader as _PR
                            rd = _PR(_io2.BytesIO(rawbytes))
                            text = "\n".join((p.extract_text() or "") for p in rd.pages)
                        except Exception:
                            text = None
                    if not text:
                        return JSONResponse({"ok": True, "file_read": True, "path": path, "binary": True,
                                             "length": len(rawbytes),
                                             "content": "(PDF %d B — extrakce textu selhala, asi skenovaný → OCR)" % len(rawbytes)})
                    return JSONResponse({"ok": True, "file_read": True, "path": path,
                                         "length": len(text), "content": text})
                try:
                    txt = rawbytes.decode("utf-8")
                except Exception:
                    txt = rawbytes.decode("latin-1", "replace")
                return JSONResponse({"ok": True, "file_read": True, "path": path,
                                     "length": len(txt), "content": txt})
        except Exception as exc:
            return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, exc)})

    # @@QCOPY — frontový streamovaný kopírovací engine (Claude 2.7.2026, "standard").
    #   @@QCOPY INDEX <batch> <src_root> >> <dst_ro_root>  — projde strom 1×, uloží frontu
    #   @@QCOPY RUN <batch> [n]                             — zkopíruje n pending (default 15)
    #   @@QCOPY STAT <batch>                                — stav fronty
    #   Nativní file_copy (jakákoliv velikost) + fronta v fw.file_copy_q → pod rate-limitem,
    #   re-spustitelné / plánovatelné scheduled taskem. Balast (_files/Thumbs/~$/.db) → _DELETE/.
    if sql.upper().startswith("@@QCOPY"):
        import json as _jq
        from sqlalchemy import text as _tq
        from core.database_data import get_data_session as _gq
        _rest = sql[len("@@QCOPY"):].strip()
        _sub = _rest.split(None, 1)
        _qop = (_sub[0].upper() if _sub else "")
        _qarg = (_sub[1].strip() if len(_sub) > 1 else "")
        from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
        _mcp = get_eurosoft_mcp_client()
        if _qop == "INDEX":
            if " >> " not in _qarg:
                return JSONResponse({"ok": False, "error": "@@QCOPY INDEX <batch> <src_root> >> <dst_root>"})
            _left, _dstroot = [x.strip() for x in _qarg.split(" >> ", 1)]
            _lb = _left.split(None, 1)
            _batch = _lb[0]; _srcroot = (_lb[1].strip() if len(_lb) > 1 else "").rstrip("\\/")
            _dstroot = _dstroot.strip("/").replace("\\", "/")
            if _mcp is None:
                return JSONResponse({"ok": False, "error": "MCP nedostupný"})
            def _qwalk(root):
                files = []; q = [root]; seen = 0
                while q and seen < 5000:
                    cur = q.pop(0); seen += 1
                    raw = _mcp.call_tool_sync("eurosoft_eurosoft_file_list",
                                              {"user_namespace": "ro", "base_override": cur, "subpath": ""},
                                              conversation_id=None)
                    r = _jq.loads(raw) if isinstance(raw, str) else raw
                    for it in ((r.get("items") or r.get("files") or r.get("entries") or []) if isinstance(r, dict) else (r or [])):
                        if isinstance(it, dict):
                            nm = it.get("name") or it.get("filename") or it.get("path")
                            typ = it.get("type") or ("dir" if it.get("is_dir") else "file"); szz = it.get("size") or 0
                        else:
                            nm, typ, szz = it, "file", 0
                        full = cur + "\\" + str(nm)
                        if typ == "dir": q.append(full)
                        else: files.append((cur, str(nm), full[len(root):].lstrip("\\/").replace("\\", "/"), szz))
                return files
            _fs = _qwalk(_srcroot)
            def _isjunk(rel):
                low = rel.lower(); base = rel.split("/")[-1]
                return ("_files/" in low or base == "Thumbs.db" or base.startswith("~$")
                        or base.endswith(".db") or base.endswith(".tmp"))
            _s = _gq(); _n = 0
            try:
                for (base, nm, rel, szz) in _fs:
                    tgt = ("_DELETE/" + rel) if _isjunk(rel) else rel
                    _s.execute(_tq("""INSERT INTO fw.file_copy_q(batch,src_base,src_name,dst_ns,dst_path,sz)
                        VALUES(:b,:sb,:sn,'ro',:dp,:sz) ON CONFLICT (batch,dst_path) DO NOTHING"""),
                        {"b": _batch, "sb": base, "sn": nm, "dp": _dstroot + "/" + tgt, "sz": szz})
                    _n += 1
                _s.commit()
                t = _s.execute(_tq("SELECT count(*) c, count(*) FILTER(WHERE status='pending') p FROM fw.file_copy_q WHERE batch=:b"), {"b": _batch}).first()
                return JSONResponse({"ok": True, "columns": ["batch", "prosel", "celkem_ve_fronte", "pending"],
                                     "rows": [[_batch, _n, t.c, t.p]], "count": 1,
                                     "note": "Zaindexováno. Spouštěj @@QCOPY RUN %s dokud pending=0 (klidně scheduled taskem)." % _batch})
            finally:
                _s.close()
        if _qop == "RUN":
            _ra = _qarg.split()
            _batch = _ra[0] if _ra else ""
            try: _nn = int(_ra[1]) if len(_ra) > 1 else 15
            except Exception: _nn = 15
            if _mcp is None:
                return JSONResponse({"ok": False, "error": "MCP nedostupný"})
            _s = _gq(); rows = []
            try:
                pend = _s.execute(_tq("SELECT id,src_base,src_name,dst_ns,dst_path FROM fw.file_copy_q WHERE batch=:b AND status='pending' ORDER BY id LIMIT :n"),
                                  {"b": _batch, "n": _nn}).fetchall()
                for row in pend:
                    try:
                        raw = _mcp.call_tool_sync("eurosoft_eurosoft_file_copy",
                                                  {"src_base_override": row.src_base, "src_path": row.src_name,
                                                   "dst_namespace": row.dst_ns, "dst_path": row.dst_path, "overwrite": True},
                                                  conversation_id=None)
                        rr = _jq.loads(raw) if isinstance(raw, str) else raw
                        if isinstance(rr, dict) and rr.get("ok"):
                            _s.execute(_tq("UPDATE fw.file_copy_q SET status='done',done_at=now(),err=NULL WHERE id=:i"), {"i": row.id})
                            rows.append([row.dst_path[-46:], "OK"])
                        else:
                            _e = str((rr.get("error") if isinstance(rr, dict) else rr))[:120]
                            _s.execute(_tq("UPDATE fw.file_copy_q SET status='err',err=:e WHERE id=:i"), {"i": row.id, "e": _e})
                            rows.append([row.dst_path[-40:], "ERR: " + _e[:40]])
                    except Exception as _ex:
                        _s.execute(_tq("UPDATE fw.file_copy_q SET status='err',err=:e WHERE id=:i"), {"i": row.id, "e": str(_ex)[:120]})
                        rows.append([row.dst_path[-40:], "EXC: " + str(_ex)[:40]])
                    _s.commit()
                st = _s.execute(_tq("SELECT count(*) FILTER(WHERE status='pending') p, count(*) FILTER(WHERE status='done') d, count(*) FILTER(WHERE status='err') e FROM fw.file_copy_q WHERE batch=:b"), {"b": _batch}).first()
                return JSONResponse({"ok": True, "columns": ["cil", "stav"], "rows": rows, "count": len(rows),
                                     "note": "pending %d · done %d · err %d%s" % (st.p, st.d, st.e, "" if st.p else " · HOTOVO ✓")})
            finally:
                _s.close()
        if _qop == "STAT":
            _batch = _qarg.strip()
            _s = _gq()
            try:
                st = _s.execute(_tq("SELECT status,count(*) c,COALESCE(sum(sz),0) b FROM fw.file_copy_q WHERE batch=:b GROUP BY status ORDER BY status"), {"b": _batch}).fetchall()
                return JSONResponse({"ok": True, "columns": ["status", "pocet", "bajtu"], "rows": [[r.status, r.c, r.b] for r in st], "count": len(st)})
            finally:
                _s.close()
        return JSONResponse({"ok": False, "error": "@@QCOPY INDEX <batch> <src> >> <dst> | RUN <batch> [n] | STAT <batch>"})

    # @@ISDS LIST <acct_id> [dny] / @@ISDS MSG <acct_id> <dm_id> → test datovek z bridge
    if sql.upper().startswith("@@ISDS"):
        parts = sql.split()
        op = (parts[1].upper() if len(parts) > 1 else "")
        try:
            acct_id = int(parts[2])
        except Exception:
            return JSONResponse({"ok": False, "error": "@@ISDS LIST|MSG <acct_id> [...]"})
        from core.database_data import get_data_session as _gi
        from sqlalchemy import text as _ti
        si = _gi()
        try:
            acc = si.execute(_ti(
                "SELECT id, company_label, box_id, login_name, password_enc "
                "FROM fw.isds_account WHERE id=:i"), {"i": acct_id}).mappings().first()
        finally:
            si.close()
        if not acc:
            return JSONResponse({"ok": False, "error": "účet nenalezen"})
        acc = dict(acc)
        try:
            if op == "LIST":
                days = int(parts[3]) if len(parts) > 3 else 90
                lst = _isds_list_received(acc, days_back=days)
                rows = [[m["dm_id"], (m["subject"] or "")[:50], (m["sender"] or "")[:30],
                         (m["delivered"] or "")[:16]] for m in lst]
                return JSONResponse({"ok": True, "columns": ["dm_id", "předmět", "odesílatel", "doručeno"],
                                     "rows": rows, "count": len(rows)})
            if op == "MSG":
                dm_id = parts[3]
                subj, files = _isds_download(acc, dm_id)
                rows = [["PŘEDMĚT", (subj or "")[:120]]]
                for f in files:
                    rows.append(["📎 " + (f["filename"] or "")[:50], "%d B" % len(f["bytes"])])
                if files:
                    t = _isds_extract_text(files[0]["bytes"], files[0]["filename"])
                    rows.append(["TEXT[0]", (t or "(prázdné / binární)")[:400]])
                return JSONResponse({"ok": True, "columns": ["pole", "hodnota"], "rows": rows, "count": len(rows)})
            if op == "SENDNEMPRI":
                # @@ISDS SENDNEMPRI <acct> <davka_id> <recipient_box> — explicitní příjemce
                try:
                    davka_id = int(parts[3]); recip = parts[4]
                except Exception:
                    return JSONResponse({"ok": False, "error": "@@ISDS SENDNEMPRI <acct> <davka_id> <recipient_box>"})
                from core.database_data import get_data_session as _gs2
                from sqlalchemy import text as _ts2
                ss = _gs2()
                try:
                    d = ss.execute(_ts2("SELECT * FROM tenant.davka_podani WHERE id=:i"),
                                   {"i": davka_id}).mappings().first()
                    if not d:
                        return JSONResponse({"ok": False, "error": "podání nenalezeno"})
                    xml = _nempri25_ose_xml(dict(d))
                    oks, res = _isds_send(acc, recip, "e - Podani NEMPRI25",
                                          [{"filename": "NEMPRI25.xml", "bytes": xml.encode("utf-8"),
                                            "mime": "application/xml"}])
                    if oks:
                        ss.execute(_ts2("UPDATE tenant.davka_podani SET stav='odeslano', odeslano_at=now(), "
                                        "protokol=:p WHERE id=:i"), {"p": "dmID=" + res, "i": davka_id})
                        ss.commit()
                    return JSONResponse({"ok": oks, "columns": ["k", "v"],
                                         "rows": [["odesláno", "ANO" if oks else "NE"], ["dmID/chyba", res]],
                                         "count": 2})
                finally:
                    ss.close()
            if op == "DOC":
                dm_id = parts[3]
                from core.database_data import get_data_session as _gd
                sd = _gd()
                try:
                    r = _isds_process_attachments(sd, acc, dm_id)
                finally:
                    sd.close()
                rows = [["soubory", str(r["count"])], ["druhy", str(r.get("kinds"))],
                        ["předmět", (r.get("subject") or "")[:80]]]
                return JSONResponse({"ok": True, "columns": ["k", "v"], "rows": rows, "count": len(rows)})
            if op == "DOCALL":
                from core.database_data import get_data_session as _gd
                from sqlalchemy import text as _td
                sd = _gd()
                done = 0; fil = 0; errs = []
                try:
                    msgs = sd.execute(_td(
                        "SELECT dm_id, subject FROM fw.isds_message WHERE account_id=:a ORDER BY dm_id"),
                        {"a": acct_id}).mappings().all()
                    for m in msgs:
                        try:
                            r = _isds_process_attachments(sd, acc, m["dm_id"], m["subject"] or "")
                            done += 1; fil += r["count"]
                        except Exception as _e:
                            errs.append(str(_e)[:50])
                finally:
                    sd.close()
                rows = [["zpráv zpracováno", str(done)], ["příloh uloženo", str(fil)], ["chyby", str(len(errs))]]
                for e in errs[:4]:
                    rows.append(["chyba", e])
                return JSONResponse({"ok": True, "columns": ["k", "v"], "rows": rows, "count": len(rows)})
            if op == "NESCH":
                dm_id = parts[3]
                from core.database_data import get_data_session as _gn
                sn = _gn()
                try:
                    r = _isds_process_eneschopenka(sn, acc, dm_id)
                finally:
                    sn.close()
                if not r.get("ok"):
                    return JSONResponse({"ok": False, "error": r.get("error")})
                rows = [["IdPripadu", r["id_pripadu"]], ["typ", r["typ"]], ["stav", r["stav"]],
                        ["zaměstnanec", (r["emp_jmeno"] + " " + r["emp_prijmeni"]).strip()],
                        ["RČ", r["emp_rc"]], ["od", str(r["datum_od"])], ["do", str(r["datum_do"])],
                        ["nemoc", r["druh_nemoci"]], ["lékař", r["lekar_nazev"]]]
                return JSONResponse({"ok": True, "columns": ["pole", "hodnota"], "rows": rows, "count": len(rows)})
            if op == "NESCHALL":
                from core.database_data import get_data_session as _gn
                from sqlalchemy import text as _tn
                sn = _gn()
                ok = 0; err = 0; errs = []
                try:
                    msgs = sn.execute(_tn(
                        "SELECT dm_id FROM fw.isds_message WHERE account_id=:a "
                        "AND (msg_type LIKE 'eneschopenka%' OR msg_type='ocr') ORDER BY dm_id"),
                        {"a": acct_id}).mappings().all()
                    for m in msgs:
                        try:
                            r = _isds_process_eneschopenka(sn, acc, m["dm_id"])
                            if r.get("ok"):
                                ok += 1
                            else:
                                err += 1; errs.append(r.get("error", "?"))
                        except Exception as _e:
                            err += 1; errs.append(str(_e)[:60])
                finally:
                    sn.close()
                rows = [["zpracováno OK", str(ok)], ["chyby", str(err)]]
                for e in errs[:5]:
                    rows.append(["chyba", e])
                return JSONResponse({"ok": True, "columns": ["k", "v"], "rows": rows, "count": len(rows)})
            if op == "XML":
                dm_id = parts[3]
                subj, files = _isds_download(acc, dm_id)
                xmlf = next((f for f in files if (f["filename"] or "").lower().endswith(".xml")), None)
                if not xmlf:
                    return JSONResponse({"ok": False, "error": "žádná XML příloha"})
                try:
                    xt = xmlf["bytes"].decode("utf-8")
                except Exception:
                    xt = xmlf["bytes"].decode("latin-1", "replace")
                rows = [["file", xmlf["filename"]]]
                for i in range(0, min(len(xt), 6000), 165):
                    rows.append(["xml", xt[i:i + 165]])
                return JSONResponse({"ok": True, "columns": ["k", "v"], "rows": rows, "count": len(rows)})
            if op == "RAW":
                import requests as _rq
                login = acc.get("login_name") or ""
                pwd = _isds_dec(acc.get("password_enc")) or ""
                body = ('<p:GetListOfReceivedMessages xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">'
                        '<p:dmFromTime>2026-01-01T00:00:00</p:dmFromTime>'
                        '<p:dmToTime xsi:nil="true"/><p:dmRecipientOrgUnitNum xsi:nil="true"/>'
                        '<p:dmStatusFilter>-1</p:dmStatusFilter><p:dmOffset>1</p:dmOffset>'
                        '<p:dmLimit>1000</p:dmLimit></p:GetListOfReceivedMessages>')
                env = ('<?xml version="1.0" encoding="utf-8"?>'
                       '<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" '
                       'xmlns:p="%s"><soapenv:Header/><soapenv:Body>%s</soapenv:Body></soapenv:Envelope>'
                       % (_ISDS_NS, body))
                r = _rq.post(_ISDS_BASE + "/dx", data=env.encode("utf-8"),
                             headers={"Content-Type": "text/xml; charset=utf-8", "SOAPAction": '""'},
                             auth=(login, pwd), timeout=40)
                txt = r.text or ""
                rows = [["http", str(r.status_code)]]
                for i in range(0, min(len(txt), 4000), 170):
                    rows.append(["raw", txt[i:i + 170]])
                return JSONResponse({"ok": True, "columns": ["k", "v"], "rows": rows, "count": len(rows)})
            return JSONResponse({"ok": False, "error": "@@ISDS LIST|MSG|RAW <acct_id> ..."})
        except Exception as exc:
            return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, exc)})

    # @@NEMPRI <davka_id> → vygeneruje NEMPRI25 XML pro podání (test generátoru)
    if sql.upper().startswith("@@NEMPRI"):
        parts = sql.split()
        try:
            did = int(parts[1])
        except Exception:
            return JSONResponse({"ok": False, "error": "@@NEMPRI <davka_id>"})
        from core.database_data import get_data_session as _gn
        from sqlalchemy import text as _tn
        sn = _gn()
        try:
            d = sn.execute(_tn("SELECT * FROM tenant.davka_podani WHERE id=:i"), {"i": did}).mappings().first()
            if not d:
                return JSONResponse({"ok": False, "error": "podání nenalezeno"})
            xml = _nempri25_ose_xml(dict(d))
        finally:
            sn.close()
        rows = [[ln] for ln in xml.split("\n")]
        return JSONResponse({"ok": True, "columns": ["NEMPRI25 XML"], "rows": rows, "count": len(rows)})

    # @@OCRINFO → zjistí dostupnost OCR stacku na cloudu (pro produkční instalaci)
    if sql.upper().startswith("@@OCRINFO"):
        rows = []
        for mod in ("fitz", "pytesseract", "PIL"):
            try:
                m = __import__(mod)
                rows.append([mod, "OK", str(getattr(m, "__version__", getattr(m, "version", "?")))[:30]])
            except Exception as e:
                rows.append([mod, "CHYBÍ", str(e)[:40]])
        try:
            import pytesseract as _ts
            rows.append(["tesseract-bin", "OK", str(_ts.get_tesseract_version())[:30]])
            try:
                rows.append(["jazyky", "OK", ", ".join(_ts.get_languages(config=""))[:60]])
            except Exception as le:
                rows.append(["jazyky", "?", str(le)[:40]])
        except Exception as e:
            rows.append(["tesseract-bin", "CHYBÍ", str(e)[:40]])
        return JSONResponse({"ok": True, "columns": ["komponenta", "stav", "detail"],
                             "rows": rows, "count": len(rows)})

    # @@WORDS <cesta> → slova faktury s normalizovanými rámečky (návrh pozičních zón, Tier 2)
    if sql.upper().startswith("@@WORDS"):
        parts = sql.split(None, 1)
        path = (parts[1].strip() if len(parts) > 1 else "")
        if not path:
            return JSONResponse({"ok": False, "error": "@@WORDS <cesta_k_pdf>"})
        try:
            from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
            mcp = get_eurosoft_mcp_client()
            if mcp is None:
                return JSONResponse({"ok": False, "error": "EUROSOFT MCP nedostupný"})
            _txt, words, err = _edi_read_doc(mcp, path)
            if not words:
                return JSONResponse({"ok": False, "error": err or "žádná slova (sken → OCR větev)"})
            words.sort(key=lambda w: (w["page"], round(w["cy"], 3), w["cx"]))
            rows = [[w["page"], "%.3f" % w["x0"], "%.3f" % w["y0"], "%.3f" % w["x1"], "%.3f" % w["y1"],
                     (w["t"] or "")[:40]] for w in words]
            return JSONResponse({"ok": True, "columns": ["str", "x0", "y0", "x1", "y1", "text"],
                                 "rows": rows, "count": len(rows)})
        except Exception as exc:
            return JSONResponse({"ok": False, "error": "%s: %s" % (type(exc).__name__, exc)})

    # Most k dokumentům STRATEGIE (Marti 21.6.2026): číst dokumenty nahrané v appce
    # (public.documents) — pro napojení do ISO/TISAX modulu.
    #   @@DOCS LIST <project_id>   → výpis dokumentů projektu (id, název, typ, délka textu)
    #   @@DOCS TREE <project_id>   → struktura složek (z názvu)
    #   @@DOCS READ <doc_id>       → extrahovaný text (z document_chunks) → uloží do files/
    if sql.upper().startswith("@@DOCS"):
        from core.database_data import get_data_session as _gds
        from sqlalchemy import text as _t
        parts = sql.split(None, 2)
        op = (parts[1].upper() if len(parts) > 1 else "")
        arg = (parts[2].strip() if len(parts) > 2 else "")
        if op not in ("LIST", "TREE", "READ") or not arg:
            return JSONResponse({"ok": False, "error": "@@DOCS LIST|TREE|READ <id>"})
        _sd = _gds()
        try:
            if op == "LIST":
                rows = _sd.execute(_t(
                    "SELECT id, name, file_type, COALESCE(extracted_text_length,0) "
                    "FROM public.documents WHERE project_id=:p ORDER BY id"), {"p": int(arg)}).all()
                return JSONResponse({"ok": True, "columns": ["id", "nazev", "typ", "txt_len"],
                                     "rows": [[r[0], r[1], r[2], r[3]] for r in rows], "count": len(rows)})
            if op == "TREE":
                rows = _sd.execute(_t(
                    "SELECT split_part(name,'/',2) AS slozka, count(*) AS n FROM public.documents "
                    "WHERE project_id=:p GROUP BY 1 ORDER BY n DESC"), {"p": int(arg)}).all()
                return JSONResponse({"ok": True, "columns": ["slozka", "pocet"],
                                     "rows": [[r[0], r[1]] for r in rows], "count": len(rows)})
            # READ
            did = int(arg)
            meta = _sd.execute(_t("SELECT name, file_type FROM public.documents WHERE id=:i"), {"i": did}).first()
            if not meta:
                return JSONResponse({"ok": False, "error": "doc %s nenalezen" % did})
            txt = _sd.execute(_t(
                "SELECT string_agg(content, E'\\n' ORDER BY chunk_index) FROM public.document_chunks WHERE document_id=:i"),
                {"i": did}).scalar() or ""
            head = "# %s (doc id %s, %s)\n\n" % (meta.name, did, meta.file_type)
            body = head + txt
            return JSONResponse({"ok": True, "file_read": True, "path": "doc_%s.txt" % did,
                                 "content": body, "length": len(body)})
        finally:
            _sd.close()

    # Re-index existujícího dokumentu do document_vectors (Marti 5.7.2026, pro Claude-27
    # F5 TISAX): smaže staré chunky/vektory a spustí znovu extract→chunk→embed.
    #   @@RAGINDEX <doc_id>
    if sql.upper().startswith("@@RAGINDEX"):
        from core.database_data import get_data_session as _gds
        from sqlalchemy import text as _t
        parts = sql.split(None, 1)
        arg = (parts[1].strip() if len(parts) > 1 else "")
        if not arg.isdigit():
            return JSONResponse({"ok": False, "error": "@@RAGINDEX <doc_id>"})
        did = int(arg)
        _sd = _gds()
        try:
            meta = _sd.execute(_t("SELECT id, name, file_type FROM public.documents WHERE id=:i"),
                               {"i": did}).first()
            if not meta:
                return JSONResponse({"ok": False, "error": "doc %s nenalezen" % did})
            _sd.execute(_t("DELETE FROM public.document_vectors WHERE chunk_id IN "
                           "(SELECT id FROM public.document_chunks WHERE document_id=:i)"), {"i": did})
            _sd.execute(_t("DELETE FROM public.document_chunks WHERE document_id=:i"), {"i": did})
            _sd.commit()
        finally:
            _sd.close()
        try:
            from modules.rag.application.service import process_document as _procdoc
            _procdoc(did)
        except Exception as e:
            return JSONResponse({"ok": False, "error": "reindex %s selhal: %s" % (did, e)})
        _sd2 = _gds()
        try:
            nv = _sd2.execute(_t(
                "SELECT count(*) FROM public.document_vectors v "
                "JOIN public.document_chunks c ON c.id=v.chunk_id WHERE c.document_id=:i"),
                {"i": did}).scalar()
        finally:
            _sd2.close()
        return JSONResponse({"ok": True, "doc_id": did, "name": meta.name, "vectors": nv})

    # Diagnostika/spuštění mirror jobu v procesu (Marti 5.7.2026): obejde plánovač,
    # vrátí reálný výsledek/chybu. @@MIRRORRUN <job_key>
    if sql.upper().startswith("@@MIRRORRUN"):
        _jk = sql[len("@@MIRRORRUN"):].strip()
        if not _jk:
            return JSONResponse({"ok": False, "error": "@@MIRRORRUN <job_key>"})
        try:
            _ok, _done, _rows, _msg = _mirror_run_job(_jk)
            from core.database_data import get_data_session as _gmr
            from sqlalchemy import text as _tmr
            _smr = _gmr()
            try:
                _smr.execute(_tmr(
                    "UPDATE fw.mirror_job SET last_run_at=now(), last_status=:st, last_result=:r, "
                    "last_rows=:n, last_done=:d, running=false, updated_at=now() WHERE job_key=:k"),
                    {"st": ("ok" if _ok else "chyba"), "r": str(_msg)[:400], "n": (_rows or 0),
                     "d": bool(_done), "k": _jk})
                _smr.commit()
            finally:
                _smr.close()
            return JSONResponse({"ok": bool(_ok), "job": _jk, "done": bool(_done),
                                 "pocet_radku": _rows, "msg": str(_msg)[:300]})
        except Exception as _emr:
            return JSONResponse({"ok": False, "job": _jk,
                                 "error": "%s: %s" % (type(_emr).__name__, str(_emr)[:280])})

    # Feedback z dokumentace/portálu (Marti 21.6.2026): co lidé i auditoři napsali.
    #   @@FEEDBACK            → posledních 100 (nové první)
    #   @@FEEDBACK NOVE       → jen nevyřízené
    if sql.upper().startswith("@@FEEDBACK"):
        from core.database_data import get_data_session as _gfb
        from sqlalchemy import text as _t
        only_new = sql.upper().split(None, 1)[1].strip().startswith("NOVE") if len(sql.split(None, 1)) > 1 else False
        _sf = _gfb()
        try:
            where = "WHERE stav<>'vyrizeno'" if only_new else ""
            rows = _sf.execute(_t(
                "SELECT id, tenant_id, zdroj, typ, COALESCE(jmeno,'') , COALESCE(doc_key,''), stav, "
                "left(text,180), to_char(created_at,'DD.MM HH24:MI') FROM tenant.doc_feedback "
                + where + " ORDER BY (stav='nove') DESC, (zdroj='auditor') DESC, created_at DESC LIMIT 100")).all()
            return JSONResponse({"ok": True,
                                 "columns": ["id", "tenant", "zdroj", "typ", "jmeno", "doc", "stav", "text", "kdy"],
                                 "rows": [list(r) for r in rows], "count": len(rows)})
        finally:
            _sf.close()

    # Autonomní email přes Marti-AI (Marti 24.6.2026: pověřil Claude informovat
    # zodpovědné lidi v průběhu / před koncem práce). Odesílá přes Marti-AI personu
    # (queue_email, from_identity=persona → worker pošle přes její schránku).
    # Autonomní (token-auth, bez approval banneru), audit do fw.claude_email_log.
    #   @@EMAIL {"to":"x@y.cz","subject":"...","body":"...","cc":["..."],"reason":"..."}
    #   @@DOCHAZKA <rok> <mesic|ROK>  → srovnaná docházka z EC_Dochazka (fond per úvazek) → att_entry+summary
    if sql.upper().startswith("@@DOCHAZKA"):
        import datetime as _dtd
        parts = sql.split()
        try:
            rok = int(parts[1]) if len(parts) > 1 else _dtd.date.today().year
        except Exception:
            return JSONResponse({"ok": False, "error": "@@DOCHAZKA <rok> <mesic|ROK>"})
        marg = parts[2] if len(parts) > 2 else str(_dtd.date.today().month)
        if marg.upper() in ("ROK", "ALL", "*"):
            _last = _dtd.date.today().month if rok == _dtd.date.today().year else 12
            res = []
            for mm in range(1, _last + 1):
                try:
                    res.append(_sync_dochazka_ec(rok, mm))
                except Exception as _me:
                    res.append({"ok": False, "mesic": mm, "error": str(_me)[:150]})
            return JSONResponse({"ok": True, "rok": rok, "mesice": res})
        try:
            mesic = int(marg)
        except Exception:
            return JSONResponse({"ok": False, "error": "@@DOCHAZKA <rok> <mesic|ROK>"})
        return JSONResponse(_sync_dochazka_ec(rok, mesic))

    #   @@VYRWSYNC [frm] [to]  → EC_Dochazka → tenant.vyroba_work (zakázka+činnost+čas jako joby)
    #   Backfill po měsících (frm/to YYYY-MM-DD); bez argumentů = posledních 3 dny. Neruší docházku.
    if sql.upper().startswith("@@VYRWSYNC"):
        parts = sql.split()
        _frm = parts[1] if len(parts) > 1 else None
        _to = parts[2] if len(parts) > 2 else None
        _ec = _sync_vyroba_work_ec(frm=_frm, to=_to)
        _app = _sync_vyroba_work_app(frm=_frm, to=_to)
        return JSONResponse({"ok": bool(_ec.get("ok") and _app.get("ok")), "ec": _ec, "app": _app})

    #   @@ORIENT <doména>  → načte doménové prostředí (identita+znalosti+tooly) z tenant.domain_env
    #   do session Clauda. Sdílené s Marti-AI GO režimem. Bez argumentu = obecná + seznam domén.
    if sql.upper().startswith("@@ORIENT"):
        from core.database_data import get_data_session as _gdo
        from sqlalchemy import text as _to
        parts = sql.split()
        # Univerzální objektiv (gap #1, 18.7.2026): volitelný token @<entita>
        # (@claude / @marti-ai) → táž orientace, jiný objektiv. Bez tokenu beze změny.
        _ent = ""
        _kdo = ""
        _domtok = []
        for _p in parts[1:]:
            if _p.startswith("@"):
                _ent = _p[1:].strip()
            else:
                _domtok.append(_p)
        _dom = _domtok[0].upper() if _domtok else ""
        _s = _gdo()
        try:
            r = _s.execute(_to(
                "SELECT domain_key, nazev, work_block, znalosti, tools FROM tenant.domain_env "
                "WHERE tenant_id=2 AND active AND domain_key=:d LIMIT 1"), {"d": _dom}).first()
            if not r and _dom:
                r = _s.execute(_to(
                    "SELECT domain_key, nazev, work_block, znalosti, tools FROM tenant.domain_env "
                    "WHERE tenant_id=2 AND active AND domain_key='' LIMIT 1")).first()
            dostupne = [(x[0] or "(obecná)") for x in _s.execute(_to(
                "SELECT domain_key FROM tenant.domain_env WHERE tenant_id=2 AND active ORDER BY domain_key")).fetchall()]
            _kmap = ""
            if r:
                _kh = _s.execute(_to(
                    "SELECT name, hook FROM tenant.knowledge WHERE tenant_id=2 AND active AND domain_key=:d ORDER BY name"),
                    {"d": r[0] or ""}).fetchall()
                if _kh:
                    _kmap = "\n\n=== MAPA JEDNOTEK (natáhni plný obsah: @@KNOW <název>) ===\n" + "\n".join(
                        ["- %s — %s" % (x[0], x[1]) for x in _kh])
            if _ent:
                _er = _s.execute(_to(
                    "SELECT nazev, popis FROM g2007.entita "
                    "WHERE lower(nazev)=lower(:e) AND stav='aktivni' LIMIT 1"), {"e": _ent}).first()
                if _er:
                    _kdo = "=== KDO JSI (objektiv) ===\n%s\n\n" % (_er[1] or _er[0])
                else:
                    _kdo = "=== KDO JSI (objektiv) ===\n(entita '%s' není v g2007.entita)\n\n" % _ent
        finally:
            _s.close()
        if not r:
            return JSONResponse({"ok": True, "columns": ["orient"],
                                 "rows": [["Doména '%s' nenalezena. Dostupné: %s" % (_dom, ", ".join(dostupne))]]})
        _txt = ("%sDOMÉNA: %s (%s)\nDostupné domény: %s\n\n=== IDENTITA ===\n%s\n\n=== ZNALOSTI ===\n%s\n\n=== TOOLY ===\n%s%s"
                % (_kdo, r[0] or "(obecná)", r[1] or "", ", ".join(dostupne),
                   r[2] or "", r[3] or "", r[4] or "", _kmap))
        _rows = [[_txt[i:i + 150]] for i in range(0, len(_txt), 150)]
        return JSONResponse({"ok": True, "columns": ["orient"], "rows": _rows})

    #   @@MAP [doména]  → scopovaná mapa hooků jednotek (index jako MEMORY.md). Bez arg = vše.
    if sql.upper().startswith("@@MAP"):
        from core.database_data import get_data_session as _gmp
        from sqlalchemy import text as _tmp
        parts = sql.split()
        _dm = parts[1].upper() if len(parts) > 1 else None
        _s = _gmp()
        try:
            if _dm:
                rows = _s.execute(_tmp(
                    "SELECT domain_key, name, hook FROM tenant.knowledge "
                    "WHERE tenant_id=2 AND active AND domain_key=:d ORDER BY name"), {"d": _dm}).fetchall()
            else:
                rows = _s.execute(_tmp(
                    "SELECT domain_key, name, hook FROM tenant.knowledge "
                    "WHERE tenant_id=2 AND active ORDER BY domain_key, name")).fetchall()
        finally:
            _s.close()
        if not rows:
            return JSONResponse({"ok": True, "columns": ["mapa"],
                                 "rows": [["Mapa je zatím prázdná" + ((" pro doménu " + _dm) if _dm else "") + "."]]})
        out = [["[%s] %s — %s" % (r[0] or "-", r[1], r[2])] for r in rows]
        return JSONResponse({"ok": True, "columns": ["mapa (@@KNOW <název>)"], "rows": out})

    #   @@STAV  → dávka živého stavu (čas + otevřené + poslední práce). Gap #2, 18.7.2026.
    #   @@ORIENT dá identitu/doménu, @@STAV dá ŽIVÁ DATA (ne jen instrukci "zjisti si").
    if sql.upper().startswith("@@STAV"):
        from core.database_data import get_data_session as _gst
        from sqlalchemy import text as _tst
        _s = _gst()
        try:
            _now = _s.execute(_tst(
                "SELECT to_char(now() AT TIME ZONE 'Europe/Prague','DD.MM.YYYY HH24:MI'), "
                "EXTRACT(dow FROM now() AT TIME ZONE 'Europe/Prague')::int")).first()
            _cal = _s.execute(_tst(
                "SELECT is_workday, is_holiday, holiday_name FROM tenant.att_calendar_day "
                "WHERE tenant_id=2 AND day=(now() AT TIME ZONE 'Europe/Prague')::date LIMIT 1")).first()
            _cnt = _s.execute(_tst(
                "SELECT (SELECT COUNT(*) FROM tenant.task WHERE tenant_id=2 AND stav=0), "
                "(SELECT COUNT(*) FROM tenant.user_todo WHERE tenant_id=2 AND NOT done)")).first()
            _awl = _s.execute(_tst(
                "SELECT to_char(ts AT TIME ZONE 'Europe/Prague','DD.MM HH24:MI'), actor, "
                "COALESCE(oblast,''), LEFT(COALESCE(akce,''),60) "
                "FROM tenant.ai_work_log ORDER BY ts DESC LIMIT 4")).fetchall()
        finally:
            _s.close()
        _DNY = ["neděle", "pondělí", "úterý", "středa", "čtvrtek", "pátek", "sobota"]
        _den = _DNY[_now[1]] if (_now and _now[1] is not None) else ""
        _prac = ""
        if _cal is not None:
            if _cal[1]:
                _prac = " · svátek%s" % ((" (" + _cal[2] + ")") if _cal[2] else "")
            elif _cal[0]:
                _prac = " · pracovní den"
            else:
                _prac = " · volno"
        _lines = ["=== ŽIVÝ STAV ==="]
        _lines.append("⏰ %s, %s%s" % (_now[0] if _now else "?", _den, _prac))
        _lines.append("📋 Otevřené: %s úkolů (task) · %s todo" % (
            _cnt[0] if _cnt else 0, _cnt[1] if _cnt else 0))
        _lines.append("🕘 Poslední zaznamenaná práce (ai_work_log):")
        if _awl:
            for _r in _awl:
                _lines.append("  - %s [%s] %s%s" % (
                    _r[0], _r[1] or "?", _r[3] or "", (" · " + _r[2]) if _r[2] else ""))
        else:
            _lines.append("  (žádné záznamy)")
        _lines.append("→ Hlouběji: @@ORIENT <doména> · @@MAP · g2007_hledej(dotaz)")
        _txt = "\n".join(_lines)
        _rows = [[_txt[i:i + 150]] for i in range(0, len(_txt), 150)]
        return JSONResponse({"ok": True, "columns": ["stav"], "rows": _rows})

    #   @@KNOW <název>  → natáhne plný obsah jednotky know-how (lazy load do session)
    if sql.upper().startswith("@@KNOW") and not sql.upper().startswith("@@KNOWEMBED"):
        from core.database_data import get_data_session as _gkn
