def _sync_odmeny_from_ec(year: int = 2026, month=None) -> dict:
    """Peta 7.7.2026 — odměny z Centrály (EC_FinPriplatkySrazkyDefinice, DB_EC) → tenant.att_odmena_centrala.
    Bere schválené záznamy AKTIVNÍ pro období (PlatnostOd<=konec, PlatnostDo IS NULL nebo >=začátek),
    pokrývá i opakující se pod starším rokem. Mapa typ→složka: DPP typ 1 a 3 → 700 (typ 3 = hodinová,
    částka = Hodiny×Sazba), jednatelská odměna typ 17 → 693. Idempotentní. Zdroj pravdy = Centrála."""
    import json as _j
    import calendar as _cal
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        raise RuntimeError("EUROSOFT MCP nedostupné")
    ry = int(year); rm = int(month) if month else 1
    ld = _cal.monthrange(ry, rm)[1]
    d_start = "%04d-%02d-01" % (ry, rm)
    d_end = "%04d-%02d-%02d" % (ry, rm, ld)
    # typ→CisloMS: DPP (1,3)→700, jednatel (17)→693. částka = Castka, nebo Hodiny*Sazba (typ 3 hodinová).
    sql = ("SELECT CisloZam cz, "
           "  CASE WHEN Typ IN (1,3) THEN 700 WHEN Typ=17 THEN 693 END AS cms, "
           "  SUM(CASE WHEN Castka IS NOT NULL AND Castka<>0 THEN Castka "
           "           ELSE ISNULL(Hodiny,0)*ISNULL(Sazba,0) END) AS castka "
           "FROM EC_FinPriplatkySrazkyDefinice "
           "WHERE Typ IN (1,3,17) AND ISNULL(Schvaleno,0)=1 "
           "  AND PlatnostOd <= '" + d_end + "' "
           "  AND (PlatnostDo IS NULL OR PlatnostDo >= '" + d_start + "') "
           "GROUP BY CisloZam, CASE WHEN Typ IN (1,3) THEN 700 WHEN Typ=17 THEN 693 END "
           "HAVING SUM(CASE WHEN Castka IS NOT NULL AND Castka<>0 THEN Castka "
           "               ELSE ISNULL(Hodiny,0)*ISNULL(Sazba,0) END) <> 0")
    raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                             {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
    r = _j.loads(raw) if isinstance(raw, str) else raw
    rows = []
    if isinstance(r, dict):
        if r.get("ok") is False:
            raise RuntimeError(str(r.get("error")))
        for k in ("rows", "data", "result", "records"):
            if isinstance(r.get(k), list):
                rows = r[k]
                break
    elif isinstance(r, list):
        rows = r

    def f(v):
        try:
            return round(float(v), 2)
        except (TypeError, ValueError):
            return 0.0

    cm = _pg.get_session()
    s = cm.__enter__()
    n = 0
    mm = int(month) if month else 0
    try:
        s.execute(_t(
            "CREATE TABLE IF NOT EXISTS tenant.att_odmena_centrala ("
            " tenant_id integer NOT NULL,"
            " cislo_zam text NOT NULL,"
            " rok integer NOT NULL,"
            " mesic integer NOT NULL,"
            " cislo_ms integer NOT NULL,"
            " castka numeric(14,2) NOT NULL DEFAULT 0,"
            " synced_at timestamptz DEFAULT now(),"
            " PRIMARY KEY (tenant_id, cislo_zam, rok, mesic, cislo_ms))"))
        if month:
            s.execute(_t("DELETE FROM tenant.att_odmena_centrala WHERE tenant_id=2 AND rok=:y AND mesic=:m"),
                      {"y": ry, "m": mm})
        else:
            s.execute(_t("DELETE FROM tenant.att_odmena_centrala WHERE tenant_id=2 AND rok=:y"), {"y": ry})
        for row in rows:
            try:
                cz = int(row.get("cz")); cms = int(row.get("cms"))
            except (TypeError, ValueError):
                continue
            s.execute(_t(
                "INSERT INTO tenant.att_odmena_centrala (tenant_id, cislo_zam, rok, mesic, cislo_ms, castka, synced_at) "
                "VALUES (2, :cz, :y, :m, :cms, :castka, now()) "
                "ON CONFLICT (tenant_id, cislo_zam, rok, mesic, cislo_ms) DO UPDATE SET "
                " castka=EXCLUDED.castka, synced_at=now()"),
                {"cz": str(cz), "y": ry, "m": mm, "cms": cms, "castka": f(row.get("castka"))})
            n += 1
        s.commit()
        return {"ok": True, "rows": len(rows), "upserted": n}
    except Exception:
        s.rollback()
        raise
    finally:
        cm.__exit__(None, None, None)


def _sync_deti(preview: bool = False) -> dict:
    """Marti/Kristý 23.6.2026: plošná migrace dětí/rodinných příslušníků z Helios
    TabZamRPr (DB_EC = firma EC, DB_IS = firma ES) → tenant.user_self_child.
    Mapování rodič→uživatel přes Cislo (TabCisZam.ID=ZamestnanecId → Cislo) →
    tenant.att_employee.cislo_zam → user_id (ověřeno 0 kolizí). Dedup: poslední
    IdObdobi per RodneCislo dítěte. Idempotentní: nevkládá, pokud uživatel už má
    dítě se shodným RČ (normalizováno) — neduplikuje ani ručně zadané (Marti, Nina).
    preview=True → jen spočítá (found/matched/unmatched/new/exists), NIC nezapíše.
    RČ se NIKAM neloguje (jen normalizace v paměti pro dedup)."""
    import json as _j
    import re as _re
    import time as _tm
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        raise RuntimeError("EUROSOFT MCP nedostupné")

    def rows_of(db, _tries=4):
        sql = (
            "SELECT z.Jmeno jm, z.Prijmeni pr, z.RodneCislo rc, "
            "CONVERT(varchar(10), z.DatumNarozeni, 23) dn, z.Vztah vz, c.Cislo pc "
            "FROM [" + db + "].dbo.TabZamRPr z "
            "JOIN [" + db + "].dbo.TabCisZam c ON c.ID = z.ZamestnanecId "
            "JOIN (SELECT RodneCislo, MAX(IdObdobi) mx FROM [" + db + "].dbo.TabZamRPr "
            "      WHERE RodneCislo IS NOT NULL AND RodneCislo <> '' GROUP BY RodneCislo) m "
            "  ON m.RodneCislo = z.RodneCislo AND m.mx = z.IdObdobi"
        )
        last = None
        for _i in range(_tries):
            try:
                raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                         {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
                r = _j.loads(raw) if isinstance(raw, str) else raw
                if isinstance(r, dict):
                    if r.get("ok") is False:
                        raise RuntimeError(str(r.get("error")))
                    for k in ("rows", "data", "result", "records"):
                        if isinstance(r.get(k), list):
                            return r[k]
                    return []
                if isinstance(r, list):
                    return r
                return []
            except Exception as e:
                last = e
                _tm.sleep(1.5)
        raise RuntimeError("MCP read selhalo (%s): %s" % (db, last))

    def norm_rc(v):
        return _re.sub(r"\D", "", str(v or ""))

    # sběr z obou DB + dedup podle RČ dítěte (poslední vyhrává)
    by_rc = {}
    for db in ("DB_EC", "DB_IS"):
        for row in rows_of(db):
            rc = norm_rc(row.get("rc"))
            if len(rc) < 6:
                continue
            by_rc[rc] = row

    cm = _pg.get_session()
    s = cm.__enter__()
    found = len(by_rc)
    matched = unmatched = new = exists = 0
    try:
        umap = {}
        for er in s.execute(_t("SELECT cislo_zam, max(user_id) FROM tenant.att_employee "
                               "WHERE tenant_id=2 AND cislo_zam IS NOT NULL GROUP BY cislo_zam")).fetchall():
            umap[str(er[0]).strip()] = er[1]
        for rc, row in by_rc.items():
            uid = umap.get(str(row.get("pc") or "").strip())
            if not uid:
                unmatched += 1
                continue
            matched += 1
            ex = s.execute(_t(
                "SELECT 1 FROM tenant.user_self_child WHERE tenant_id=2 AND user_id=:u "
                "AND regexp_replace(COALESCE(birth_number,''),'\\D','','g')=:rc LIMIT 1"),
                {"u": uid, "rc": rc}).first()
            if ex:
                exists += 1
                continue
            new += 1
            if preview:
                continue
            jm = str(row.get("jm") or "").strip()
            pr = str(row.get("pr") or "").strip()
            nm = (jm + " " + pr).strip() or "(dítě)"
            vz = str(row.get("vz") or "").strip()
            rel = "dítě" if vz in ("0", "") else "rodinný příslušník"
            s.execute(_t(
                "INSERT INTO tenant.user_self_child "
                "(tenant_id, user_id, child_name, birth_date, birth_number, is_dependent, relation, note) "
                "VALUES (2, :u, :nm, :bd, :rc, true, :rel, 'import Helios 23.6.2026')"),
                {"u": uid, "nm": nm, "bd": (row.get("dn") or None),
                 "rc": (str(row.get("rc") or "").strip() or None), "rel": rel})
        if preview:
            s.rollback()
        else:
            s.commit()
        return {"ok": True, "found": found, "matched": matched, "unmatched": unmatched,
                "new": new, "exists": exists, "preview": preview}
    except Exception:
        s.rollback()
        raise
    finally:
        cm.__exit__(None, None, None)


def _att_anomaly_scan(notify: bool = True) -> dict:
    """Marti 7.6.2026: „systém si má všímat nestandardností a sám upozorňovat."
    Pravidla (z reálných nálezů — Petra: píchnuto v budoucnosti, 23h směny):
      R1 budouci_zaznam  — presence záznam s časem v budoucnosti
      R2 dlouha_smena    — hours > 12
      R3 zapomenuty_odchod — otevřená směna ze včerejška a starší
      R4 prace_pri_absenci — presence záznam v den schválené absence
    Dedup přes tenant.att_anomaly (UNIQUE rule+entry). Notifikace: dotyčný
    + kontrola docházky (resolve_role attendance_supervisor)."""
    from sqlalchemy import text as _t
    cm, s = _att_session()
    found = 0
    notified = 0
    try:
        rows = s.execute(_t("""
            WITH kand AS (
              SELECT e.id, e.employee_id, 'budouci_zaznam' AS rule,
                     to_char(e.entry_date, 'DD.MM.') || ' záznam v budoucnosti ('
                       || COALESCE(to_char(e.started_at,'HH24') || ':' || to_char(e.started_at,'MI'), '?')
                       || '–' || COALESCE(to_char(e.ended_at,'HH24') || ':' || to_char(e.ended_at,'MI'), '…') || ')' AS detail
              FROM tenant.att_entry e
              JOIN tenant.att_entry_type et ON et.id = e.entry_type_id
              WHERE e.tenant_id = 2 AND COALESCE(e.source_system,'') NOT IN ('ec_sumaden','absence_req','centrala1') AND et.category = 'presence'
                AND e.entry_date > current_date AND e.started_at IS NOT NULL
                AND e.status NOT IN ('superseded','announced')
              UNION ALL
              SELECT e.id, e.employee_id, 'dlouha_smena',
                     to_char(e.entry_date, 'DD.MM.') || ' směna ' || round(e.hours::numeric,1) || ' h ('
                       || COALESCE(to_char(e.started_at,'HH24') || ':' || to_char(e.started_at,'MI'), '?')
                       || '–' || COALESCE(to_char(e.ended_at,'HH24') || ':' || to_char(e.ended_at,'MI'), '?') || ')'
              FROM tenant.att_entry e
              JOIN tenant.att_entry_type et ON et.id = e.entry_type_id
              WHERE e.tenant_id = 2 AND COALESCE(e.source_system,'') NOT IN ('ec_sumaden','absence_req','centrala1') AND et.category = 'presence'
                AND e.hours > 12 AND e.status NOT IN ('superseded','announced')
              UNION ALL
              SELECT e.id, e.employee_id, 'zapomenuty_odchod',
                     to_char(e.entry_date, 'DD.MM.') || ' otevřená směna od '
                       || COALESCE(to_char(e.started_at,'HH24') || ':' || to_char(e.started_at,'MI'), '?')
                       || ' — chybí odchod'
              FROM tenant.att_entry e
              JOIN tenant.att_entry_type et ON et.id = e.entry_type_id
              WHERE e.tenant_id = 2 AND e.is_active = true AND e.ended_at IS NULL
                AND e.entry_date < current_date
                -- Marti 27.6.: import z Centrály (centrala1) a režie (overhead) NEJSOU zapomenutý
                -- odchod → jinak supervizor (Marti) dostával bogus notifikace o cizích směnách.
                AND COALESCE(e.source_system,'') NOT IN ('ec_sumaden','absence_req','centrala1','import')
                AND et.code IN ('work','homeoffice')
              UNION ALL
              SELECT min(e.id), e.employee_id, 'nepotvrzeny_den',
                     to_char(e.entry_date, 'DD.MM.') || ' nepotvrzená docházka'
              FROM tenant.att_entry e
              JOIN tenant.att_entry_type et ON et.id = e.entry_type_id
              WHERE e.tenant_id = 2 AND COALESCE(e.source_system,'') NOT IN ('ec_sumaden','absence_req','centrala1') AND et.category = 'presence' AND e.started_at IS NOT NULL
                AND e.status NOT IN ('superseded','announced')
                AND e.entry_date < current_date
                AND e.entry_date >= GREATEST(current_date - 14, DATE '2026-06-06')
                AND NOT EXISTS (SELECT 1 FROM tenant.att_day_confirm c
                                WHERE c.tenant_id = 2 AND c.employee_id = e.employee_id
                                  AND c.day = e.entry_date)
              GROUP BY e.employee_id, e.entry_date
              UNION ALL
              SELECT e.id, e.employee_id, 'prace_pri_absenci',
                     to_char(e.entry_date, 'DD.MM.') || ' píchnutá práce v den nahlášené nepřítomnosti'
              FROM tenant.att_entry e
              JOIN tenant.att_entry_type et ON et.id = e.entry_type_id
              WHERE e.tenant_id = 2 AND COALESCE(e.source_system,'') NOT IN ('ec_sumaden','absence_req','centrala1') AND et.category = 'presence' AND e.started_at IS NOT NULL
                AND e.status NOT IN ('superseded','announced')
                AND EXISTS (SELECT 1 FROM tenant.att_entry a2
                            JOIN tenant.att_entry_type t2 ON t2.id = a2.entry_type_id
                            WHERE a2.tenant_id = 2 AND a2.employee_id = e.employee_id
                              AND a2.entry_date = e.entry_date AND t2.category = 'absence'
                              AND a2.status IN ('pending','approved'))
              UNION ALL
              -- R6 dlouha_pauza (Marti 29.6.): zapomenuté přepnutí z pauzy zpět → break > 2 h
              -- tiše sežere odpracované hodiny (Petra 25.6.: 6,3h break). Záchranná síť pro VŠECHNY
              -- (vč. OSVČ — pauzy jim necháváme, jen hlídáme zapomenuté). Práh 2 h = nad legitimní oběd.
              SELECT e.id, e.employee_id, 'dlouha_pauza',
                     to_char(e.entry_date, 'DD.MM.') || ' dlouhá pauza ' || round(e.hours::numeric,1) || ' h ('
                       || COALESCE(to_char(e.started_at,'HH24') || ':' || to_char(e.started_at,'MI'), '?')
                       || '–' || COALESCE(to_char(e.ended_at,'HH24') || ':' || to_char(e.ended_at,'MI'), '…')
                       || ') — zapomenuté přepnutí zpět do práce?'
              FROM tenant.att_entry e
              JOIN tenant.att_entry_type et ON et.id = e.entry_type_id
              WHERE e.tenant_id = 2 AND et.code = 'break'
                AND e.hours > 2 AND e.status NOT IN ('superseded','announced')
                AND e.entry_date >= GREATEST(current_date - 14, DATE '2026-06-06')
            )
            INSERT INTO tenant.att_anomaly (tenant_id, employee_id, entry_id, rule, detail)
            SELECT 2, k.employee_id, k.id, k.rule, k.detail FROM kand k
            ON CONFLICT (tenant_id, rule, entry_id) DO NOTHING
            RETURNING employee_id, rule, detail
        """)).fetchall()
        found = len(rows)
        if rows and notify:
            for r in rows:
                emp_id, rule, detail = r[0], r[1], r[2]
                info = s.execute(_t(
                    "SELECT em.user_id, COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')),''), em.full_name) "
                    "FROM tenant.att_employee em LEFT JOIN public.users u ON u.id = em.user_id "
                    "WHERE em.id = :e"), {"e": emp_id}).first()
                emp_uid = info[0] if info else None
                emp_name = (info[1] if info else None) or ("zaměstnanec " + str(emp_id))
                targets = set()
                if emp_uid:
                    targets.add(int(emp_uid))
                # nepotvrzený den = osobní zodpovědnost (Fáze 1) → jen dotyčný.
                # Marti 10.7.: ostatní nesrovnalosti chodí EDITORŮM oprav dle
                # působnosti (Peťa=kanceláře, Míša+Dušan=výroba), už NE supervizorovi.
                if rule != "nepotvrzeny_den":
                    eds = _att_fix_editors_for_emp(s, emp_id)
                    if eds:
                        targets |= eds
                    else:
                        targets.add(1)  # fallback — ať se chyba nikdy neztratí
                for uid2 in sorted(targets):
                    mine = (emp_uid is not None and uid2 == int(emp_uid))
                    if rule == "nepotvrzeny_den":
                        ti = "🖊 Potvrď si docházku"
                        msg = (detail + " — otevři Docházku, zkontroluj den a potvrď ho. "
                               "Bez potvrzení tě nepustím píchnout další příchod. — Tvoje Marti")
                    else:
                        ti = "⚠ Docházka — nesrovnalost"
                        msg = (("V docházce mám nesrovnalost: " + detail + " — mrkni na to, nebo mi napiš a opravíme to spolu.")
                               if mine else
                               (emp_name + ": " + detail))
                    s.execute(_t(
                        "INSERT INTO fw.mobile_command (app_key, target_user_id, command_type, title, message, created_by) "
                        "VALUES ('mobile', :uid, 'claude_msg', :ti, :msg, NULL)"),
                        {"uid": uid2, "ti": ti, "msg": msg[:600]})
                    notified += 1
        s.commit()
    except Exception:
        s.rollback()
        raise
    finally:
        cm.__exit__(None, None, None)
    return {"found": found, "notified": notified}


def _sync_org_from_ec() -> dict:
    """Marti 7.6.2026 (Fáze A org struktury v2, dle konzultace Marti-AI):
    zrcadlo EC_OrgPost / EC_OrgPostZam / EC_OrgPostKlobouk → tenant.org_*.
    Idempotentní upsert dle ec_id. Centrála zůstává master (Fáze A)."""
    import json as _json_o
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        raise RuntimeError("EUROSOFT MCP nedostupné")

    def rows_of(sql):
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _json_o.loads(raw) if isinstance(raw, str) else raw
        if isinstance(r, dict):
            if r.get("ok") is False:
                raise RuntimeError(str(r.get("error")))
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    return r[k]
        return r if isinstance(r, list) else []

    posts = rows_of("SELECT ID, Nazev, ID_NadrazenyPost pec, Divize, Poradi, Produkt, "
                    "CAST(Aktivni AS int) akt FROM EC_OrgPost")
    assigns = rows_of("SELECT ID, ID_Post pid, CisloZam, CAST(ISNULL(Zastupce1,0) AS int) z1, "
                      "CAST(ISNULL(Zastupce2,0) AS int) z2, CAST(ISNULL(Potencialni,0) AS int) pot, "
                      "CONVERT(varchar(10),PlatnostOd,23) od, CONVERT(varchar(10),PlatnostDo,23) pdo, "
                      "CAST(Aktivni AS int) akt FROM EC_OrgPostZam")
    hats = rows_of("SELECT ID, ID_Post pid, Nazev, CAST(A1_UcelFirmy AS nvarchar(max)) a1, "
                   "CAST(A2_UcelPracovniPozice AS nvarchar(max)) a2, CAST(B1_Umisteni AS nvarchar(max)) b1, "
                   "CAST(B2_Predpoklady AS nvarchar(max)) b2, CAST(B3_Pravomoci AS nvarchar(max)) b3, "
                   "CAST(B4_Zodpovednosti AS nvarchar(max)) b4 FROM EC_OrgPostKlobouk")

    cm = _pg.get_session()
    s = cm.__enter__()
    np_ = na = nh = 0
    try:
        # 1) posty (bez parentů)
        for p in posts:
            if not str(p.get("Nazev") or "").strip():
                continue
            s.execute(_t(
                "INSERT INTO tenant.org_post (tenant_id, ec_id, nazev, divize, poradi, produkt, aktivni) "
                "VALUES (2, :ec, :nz, :dv, :po, :pr, :ak) "
                "ON CONFLICT (tenant_id, ec_id) DO UPDATE SET nazev = EXCLUDED.nazev,"
                " divize = EXCLUDED.divize, poradi = EXCLUDED.poradi, produkt = EXCLUDED.produkt,"
                " aktivni = EXCLUDED.aktivni, updated_at = now()"),
                {"ec": p.get("ID"), "nz": str(p.get("Nazev")).strip(), "dv": p.get("Divize"),
                 "po": (str(p.get("Poradi") or "")[:20] or None), "pr": (str(p.get("Produkt") or "")[:160] or None),
                 "ak": bool(int(p.get("akt") or 0))})
            np_ += 1
        # 2) parenty (druhý průchod přes ec mapping)
        for p in posts:
            if p.get("pec"):
                s.execute(_t(
                    "UPDATE tenant.org_post SET parent_post_id = "
                    " (SELECT id FROM tenant.org_post WHERE tenant_id = 2 AND ec_id = :pec) "
                    "WHERE tenant_id = 2 AND ec_id = :ec"),
                    {"pec": p.get("pec"), "ec": p.get("ID")})
        # 3) obsazení (employee dle cislo_zam, chybějící založ)
        emp_cache = {}

        def emp_id(cislo):
            key = str(cislo).strip()
            if not key:
                return None
            if key in emp_cache:
                return emp_cache[key]
            r = s.execute(_t("SELECT id FROM tenant.att_employee WHERE tenant_id = 2 AND cislo_zam = :c"),
                          {"c": key}).first()
            if not r:
                r = s.execute(_t(
                    "INSERT INTO tenant.att_employee (tenant_id, cislo_zam, is_active, created_at, updated_at) "
                    "VALUES (2, :c, true, now(), now()) RETURNING id"), {"c": key}).first()
            emp_cache[key] = r[0]
            return r[0]

        for a in assigns:
            eid = emp_id(a.get("CisloZam"))
            if eid is None:
                continue
            zr = 1 if int(a.get("z1") or 0) else (2 if int(a.get("z2") or 0) else 0)
            s.execute(_t(
                "INSERT INTO tenant.org_post_assign (tenant_id, ec_id, post_id, employee_id,"
                " zastupce_role, potencialni, platnost_od, platnost_do, aktivni) "
                "SELECT 2, :ec, p.id, :emp, :zr, :pot, :od, :pdo, :ak "
                "FROM tenant.org_post p WHERE p.tenant_id = 2 AND p.ec_id = :pid "
                "ON CONFLICT (tenant_id, ec_id) DO UPDATE SET post_id = EXCLUDED.post_id,"
                " employee_id = EXCLUDED.employee_id, zastupce_role = EXCLUDED.zastupce_role,"
                " potencialni = EXCLUDED.potencialni, platnost_od = EXCLUDED.platnost_od,"
                " platnost_do = EXCLUDED.platnost_do, aktivni = EXCLUDED.aktivni, updated_at = now()"),
                {"ec": a.get("ID"), "emp": eid, "zr": zr, "pot": bool(int(a.get("pot") or 0)),
                 "od": (a.get("od") or None), "pdo": (a.get("pdo") or None),
                 "ak": bool(int(a.get("akt") or 0)), "pid": a.get("pid")})
            na += 1
        # 4) klobouky → markdown
        for h in hats:
            parts = []
            for key, title in (("a1", "Účel firmy"), ("a2", "Účel pozice"), ("b1", "Umístění"),
                               ("b2", "Předpoklady"), ("b3", "Pravomoci"), ("b4", "Zodpovědnosti")):
                v = str(h.get(key) or "").strip()
                if v:
                    parts.append("## " + title + "\n" + v)
            body = "\n\n".join(parts) or None
            s.execute(_t(
                "INSERT INTO tenant.org_post_hat (tenant_id, ec_id, post_id, nazev, body_markdown) "
                "SELECT 2, :ec, p.id, :nz, :bd "
                "FROM tenant.org_post p WHERE p.tenant_id = 2 AND p.ec_id = :pid "
                "ON CONFLICT (tenant_id, ec_id) DO UPDATE SET post_id = EXCLUDED.post_id,"
                " nazev = EXCLUDED.nazev, body_markdown = EXCLUDED.body_markdown, updated_at = now()"),
                {"ec": h.get("ID"), "nz": (str(h.get("Nazev") or "")[:300] or None),
                 "bd": body, "pid": h.get("pid")})
            nh += 1
        s.commit()
    except Exception:
        s.rollback()
        raise
    finally:
        cm.__exit__(None, None, None)
    return {"posts": np_, "assigns": na, "hats": nh}


def _sync_zakazky_from_helios() -> dict:
    """Marti 7.6.2026: zrcadlo zakázek Helios → tenant.zakazka (píchání na
    zakázky VR/SW/PR/Rezie). Idempotentní upsert, ⚙ ops akce sync_zakazky.
    Píchatelná = _DochPrihlaseni=1 ∧ _Uzavreno=0 ∧ _Zruseno=0 ∧ Ukonceno=0."""
    import json as _json_z
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        raise RuntimeError("EUROSOFT MCP nedostupné")
    sql = ("SELECT z.CisloZakazky c, LEFT(z.Nazev, 200) n, z.Ukonceno uk, "
           "CAST(ISNULL(x._Uzavreno,0) AS int) uz, CAST(ISNULL(x._DochPrihlaseni,0) AS int) doch, "
           "x._GarantCisloZam g, x._sefmonterCislo sm "
           "FROM TabZakazka z LEFT JOIN TabZakazka_EXT x ON x.ID = z.ID "
           "WHERE ISNULL(x._Zruseno,0) = 0 AND z.Ukonceno = 0 AND z.CisloZakazky IS NOT NULL")
    raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                             {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
    r = _json_z.loads(raw) if isinstance(raw, str) else raw
    rows = []
    if isinstance(r, dict):
        if r.get("ok") is False:
            raise RuntimeError(str(r.get("error")))
        for k in ("rows", "data", "result", "records"):
            if isinstance(r.get(k), list):
                rows = r[k]
                break
    elif isinstance(r, list):
        rows = r

    def _typ(c):
        cu = (c or "").upper()
        if cu.startswith("VR"):
            return "VR"
        if cu.startswith("SW"):
            return "SW"
        if cu.startswith("PR"):
            return "PR"
        if "REZ" in cu:
            return "REZIE"
        return "OST"

    cm = _pg.get_session()
    sess = cm.__enter__()
    n = 0
    try:
        sess.execute(_t(
            "CREATE TABLE IF NOT EXISTS tenant.zakazka ("
            " tenant_id bigint NOT NULL, cislo varchar(40) NOT NULL, nazev text,"
            " typ varchar(10), pichatelna boolean NOT NULL DEFAULT false,"
            " vyrobne_uzavrena boolean, ucetni_stav smallint,"
            " garant_cislo_zam int, sefmonter_cislo_zam int,"
            " synced_at timestamptz DEFAULT now(),"
            " PRIMARY KEY (tenant_id, cislo))"))
        # plný mirror otevřeného setu: co už není open/píchatelné, zhasne
        sess.execute(_t("UPDATE tenant.zakazka SET pichatelna = false WHERE tenant_id = 2"))
        for row in rows:
            c = str(row.get("c") or "").strip()
            if not c:
                continue
            sess.execute(_t(
                "INSERT INTO tenant.zakazka (tenant_id, cislo, nazev, typ, pichatelna,"
                " vyrobne_uzavrena, ucetni_stav, garant_cislo_zam, sefmonter_cislo_zam, synced_at) "
                "VALUES (2, :c, :n, :ty, :pi, :vu, :us, :g, :sm, now()) "
                "ON CONFLICT (tenant_id, cislo) DO UPDATE SET nazev = EXCLUDED.nazev,"
                " typ = EXCLUDED.typ, pichatelna = EXCLUDED.pichatelna,"
                " vyrobne_uzavrena = EXCLUDED.vyrobne_uzavrena, ucetni_stav = EXCLUDED.ucetni_stav,"
                " garant_cislo_zam = EXCLUDED.garant_cislo_zam,"
                " sefmonter_cislo_zam = EXCLUDED.sefmonter_cislo_zam, synced_at = now()"),
                {"c": c, "n": row.get("n"), "ty": _typ(c),
                 "pi": bool(int(row.get("doch") or 0)) and not bool(int(row.get("uz") or 0)),
                 "vu": bool(int(row.get("uz") or 0)), "us": int(row.get("uk") or 0),
                 "g": row.get("g"), "sm": row.get("sm")})
            n += 1
        sess.commit()
    except Exception:
        sess.rollback()
        raise
    finally:
        cm.__exit__(None, None, None)
    return {"synced": n}


def _sync_ec_org_from_centrala() -> dict:
    """Marti 9.6.2026: zrcadlo organizací z Centrály (TabCisOrg + TabCisOrg_EXT)
    z OBOU instancí (DB_EC=EC, DB_IS=IS) → tenant.ec_org. Kurátorovaný výběr pro
    objednávky/fakturaci živnostníků + kontakty do mobilu. Zdroj pravdy zůstává
    na straně EUROSOFTU. Idempotentní upsert dle (tenant_id, source_db, ec_id).
    ⚙ ops akce sync_ec_org. Per-source commit (chyba v IS nezhodí EC)."""
    import json as _json_o
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        raise RuntimeError("EUROSOFT MCP nedostupné")

    def rows_of(sql):
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _json_o.loads(raw) if isinstance(raw, str) else raw
        if isinstance(r, dict):
            if r.get("ok") is False:
                raise RuntimeError(str(r.get("error")))
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    return r[k]
        return r if isinstance(r, list) else []

    org_part = (
        "SELECT o.ID id, o.CisloOrg cislo, LEFT(ISNULL(o.Nazev,''),255) nazev,"
        " LEFT(ISNULL(o.DruhyNazev,''),100) druhy, LEFT(ISNULL(o.Jmeno,''),100) jmeno,"
        " LEFT(ISNULL(o.Prijmeni,''),100) prijmeni, LEFT(ISNULL(o.ICO,''),20) ico,"
        " LEFT(ISNULL(o.DIC,''),15) dic, LEFT(ISNULL(o.Misto,''),100) misto,"
        " LEFT(ISNULL(o.PSC,''),10) psc, LEFT(ISNULL(o.UliceSCisly,''),237) ulice,"
        " LEFT(ISNULL(o.IdZeme,''),3) zeme, LEFT(ISNULL(o.Region,''),15) region,"
        " LEFT(ISNULL(o.Kontakt,''),40) kontakt,"
        " CAST(ISNULL(o.JeOdberatel,0) AS int) odb, CAST(ISNULL(o.JeDodavatel,0) AS int) dod,"
        " CAST(ISNULL(o.JePartner,0) AS int) par, CAST(ISNULL(o.Agent,0) AS int) agent,"
        " CAST(ISNULL(o.Stav,0) AS int) stav, CAST(ISNULL(o.PravniForma,0) AS int) pf,"
        " LEFT(ISNULL(o.FormaUhrady,''),30) uhrada, ISNULL(o.LhutaSplatnosti,0) splat,"
        " LEFT(ISNULL(o.Mena,''),3) mena, LEFT(ISNULL(o.Jazyk,''),15) jazyk,"
        " ISNULL(o.NadrizenaOrg,0) nadr,")
    # EXT (objednávky/kontakty) má bohaté sloupce jen DB_EC; DB_IS má EXT prázdné
    # (jen ID + SystemRowVersion) → pro IS dáme NULL/0 a EXT nejoinujeme.
    ext_ec = (
        " LEFT(ISNULL(e._Objednavky_Email,''),60) oemail,"
        " LEFT(ISNULL(e._Objednavky_Telefon,''),20) otel,"
        " LEFT(ISNULL(e._Objednavky_Fax,''),20) ofax, LEFT(ISNULL(e._Zkratka_nazvu,''),15) zkr,"
        " LEFT(ISNULL(e._Teritorium,''),20) terit, LEFT(ISNULL(e._Stredisko,''),30) stred,"
        " CAST(ISNULL(e._JeDopravce,0) AS int) dopravce,"
        " LEFT(ISNULL(e._PoznamkaOrg,''),1000) pozn,")
    ext_none = " '' oemail, '' otel, '' ofax, '' zkr, '' terit, '' stred, 0 dopravce, '' pozn,"
    dz_part = " CONVERT(varchar(19), o.DatZmeny, 120) dz"

    cm = _pg.get_session()
    s = cm.__enter__()
    counts = {}
    errors = []
    try:
        s.execute(_t(
            "CREATE TABLE IF NOT EXISTS tenant.ec_org ("
            " tenant_id bigint NOT NULL, source_db varchar(4) NOT NULL, ec_id int NOT NULL,"
            " cislo_org int, nazev text, druhy_nazev text, jmeno text, prijmeni text,"
            " ico varchar(20), dic varchar(15),"
            " misto text, psc varchar(10), ulice text, zeme varchar(3), region varchar(15),"
            " kontakt text,"
            " je_odberatel boolean, je_dodavatel boolean, je_partner boolean,"
            " agent boolean, je_dopravce boolean,"
            " stav smallint, pravni_forma smallint,"
            " forma_uhrady varchar(30), lhuta_splatnosti smallint,"
            " mena varchar(3), jazyk varchar(15), nadrizena_org int,"
            " obj_email text, obj_telefon varchar(40), obj_fax varchar(40), zkratka varchar(20),"
            " teritorium varchar(20), stredisko varchar(40), poznamka text,"
            " dat_zmeny timestamptz, synced_at timestamptz DEFAULT now(),"
            " PRIMARY KEY (tenant_id, source_db, ec_id))"))
        s.commit()

        ins = _t(
            "INSERT INTO tenant.ec_org (tenant_id, source_db, ec_id, cislo_org, nazev, druhy_nazev,"
            " jmeno, prijmeni, ico, dic, misto, psc, ulice, zeme, region, kontakt,"
            " je_odberatel, je_dodavatel, je_partner, agent, je_dopravce, stav, pravni_forma,"
            " forma_uhrady, lhuta_splatnosti, mena, jazyk, nadrizena_org,"
            " obj_email, obj_telefon, obj_fax, zkratka, teritorium, stredisko, poznamka,"
            " dat_zmeny, synced_at) "
            "VALUES (2, :src, :id, :cislo, :nazev, :druhy, :jmeno, :prijmeni, :ico, :dic,"
            " :misto, :psc, :ulice, :zeme, :region, :kontakt,"
            " :odb, :dod, :par, :agent, :dopravce, :stav, :pf,"
            " :uhrada, :splat, :mena, :jazyk, :nadr,"
            " :oemail, :otel, :ofax, :zkr, :terit, :stred, :pozn,"
            " NULLIF(:dz,'')::timestamptz, now()) "
            "ON CONFLICT (tenant_id, source_db, ec_id) DO UPDATE SET"
            " cislo_org=EXCLUDED.cislo_org, nazev=EXCLUDED.nazev, druhy_nazev=EXCLUDED.druhy_nazev,"
            " jmeno=EXCLUDED.jmeno, prijmeni=EXCLUDED.prijmeni, ico=EXCLUDED.ico, dic=EXCLUDED.dic,"
            " misto=EXCLUDED.misto, psc=EXCLUDED.psc, ulice=EXCLUDED.ulice, zeme=EXCLUDED.zeme,"
            " region=EXCLUDED.region, kontakt=EXCLUDED.kontakt,"
            " je_odberatel=EXCLUDED.je_odberatel, je_dodavatel=EXCLUDED.je_dodavatel,"
            " je_partner=EXCLUDED.je_partner, agent=EXCLUDED.agent, je_dopravce=EXCLUDED.je_dopravce,"
            " stav=EXCLUDED.stav, pravni_forma=EXCLUDED.pravni_forma,"
            " forma_uhrady=EXCLUDED.forma_uhrady, lhuta_splatnosti=EXCLUDED.lhuta_splatnosti,"
            " mena=EXCLUDED.mena, jazyk=EXCLUDED.jazyk, nadrizena_org=EXCLUDED.nadrizena_org,"
            " obj_email=EXCLUDED.obj_email, obj_telefon=EXCLUDED.obj_telefon, obj_fax=EXCLUDED.obj_fax,"
            " zkratka=EXCLUDED.zkratka, teritorium=EXCLUDED.teritorium, stredisko=EXCLUDED.stredisko,"
            " poznamka=EXCLUDED.poznamka, dat_zmeny=EXCLUDED.dat_zmeny, synced_at=now()")

        for src, dbp, has_ext in (("EC", "", True), ("IS", "DB_IS.dbo.", False)):
            if has_ext:
                q = (org_part + ext_ec + dz_part
                     + " FROM %sTabCisOrg o LEFT JOIN %sTabCisOrg_EXT e ON e.ID = o.ID" % (dbp, dbp))
            else:
                q = org_part + ext_none + dz_part + " FROM %sTabCisOrg o" % dbp
            try:
                data = rows_of(q)
            except Exception as exc:
                errors.append("%s: %s" % (src, exc))
                continue
            n = 0
            for o in data:
                oid = o.get("id")
                if oid is None:
                    continue
                s.execute(ins, {
                    "src": src, "id": int(oid), "cislo": o.get("cislo"),
                    "nazev": o.get("nazev"), "druhy": o.get("druhy"),
                    "jmeno": o.get("jmeno"), "prijmeni": o.get("prijmeni"),
                    "ico": o.get("ico"), "dic": o.get("dic"), "misto": o.get("misto"),
                    "psc": o.get("psc"), "ulice": o.get("ulice"), "zeme": o.get("zeme"),
                    "region": o.get("region"), "kontakt": o.get("kontakt"),
                    "odb": bool(int(o.get("odb") or 0)), "dod": bool(int(o.get("dod") or 0)),
                    "par": bool(int(o.get("par") or 0)), "agent": bool(int(o.get("agent") or 0)),
                    "dopravce": bool(int(o.get("dopravce") or 0)),
                    "stav": int(o.get("stav") or 0), "pf": int(o.get("pf") or 0),
                    "uhrada": o.get("uhrada"), "splat": int(o.get("splat") or 0),
                    "mena": o.get("mena"), "jazyk": o.get("jazyk"),
                    "nadr": int(o.get("nadr") or 0),
                    "oemail": o.get("oemail"), "otel": o.get("otel"), "ofax": o.get("ofax"),
                    "zkr": o.get("zkr"), "terit": o.get("terit"), "stred": o.get("stred"),
                    "pozn": o.get("pozn"), "dz": o.get("dz") or "",
                })
                n += 1
            s.commit()
            counts[src] = n
    except Exception:
        s.rollback()
        raise
    finally:
        cm.__exit__(None, None, None)
    return {"counts": counts, "errors": errors}


def _classify_spojeni(val: str) -> str:
    """Klasifikace hodnoty spojení na typ kanálu (robustně podle obsahu,
    nezávisle na EUROSOFT číselníku Druh, který míchá)."""
    v = (val or "").strip().lower()
    if not v:
        return "jine"
    if "@" in v and "." in v.split("@")[-1]:
        return "email"
    if v.startswith("www") or v.startswith("http") or ".cz" in v or ".com" in v or ".de" in v:
        if "@" not in v:
            return "web"
    digits = sum(1 for c in v if c.isdigit())
    compact = "".join(c for c in v if not c.isspace())
    if digits >= 6 and compact and digits >= len(compact) * 0.5:
        return "telefon"
    return "jine"


def _sync_ec_kontakty_from_centrala() -> dict:
    """Marti 9.6.2026: Fáze 1 zrcadla kontaktů — osoby (TabCisKOs + TabCisZam)
    a spojení (TabKontakty, polymorfní na org/osoba/zam) z Centrály → tenant.ec_osoba
    + tenant.ec_spojeni. Zdroj pravdy zůstává EUROSOFT. Klasifikace typu kanálu
    podle obsahu. Per-source (EC + IS) s vlastním try. Idempotentní upsert."""
    import json as _json_k
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        raise RuntimeError("EUROSOFT MCP nedostupné")

    def rows_of(sql):
        raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                 {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
        r = _json_k.loads(raw) if isinstance(raw, str) else raw
        if isinstance(r, dict):
            if r.get("ok") is False:
                raise RuntimeError(str(r.get("error")))
            for k in ("rows", "data", "result", "records"):
                if isinstance(r.get(k), list):
                    return r[k]
        return r if isinstance(r, list) else []

    cm = _pg.get_session()
    s = cm.__enter__()
    counts = {"osoby": 0, "spojeni": 0}
    errors = []
    try:
        s.execute(_t(
            "CREATE TABLE IF NOT EXISTS tenant.ec_osoba ("
            " tenant_id bigint NOT NULL, source_db varchar(4) NOT NULL,"
            " kind varchar(4) NOT NULL, ec_id int NOT NULL, cislo_zam int,"
            " jmeno text, prijmeni text, titul_pred varchar(40), titul_za varchar(40),"
            " synced_at timestamptz DEFAULT now(),"
            " PRIMARY KEY (tenant_id, source_db, kind, ec_id))"))
        s.execute(_t(
            "CREATE TABLE IF NOT EXISTS tenant.ec_spojeni ("
            " tenant_id bigint NOT NULL, source_db varchar(4) NOT NULL, ec_id int NOT NULL,"
            " org_ec_id int, kos_ec_id int, zam_ec_id int,"
            " druh smallint, typ varchar(10), hodnota text, hodnota2 text, popis text,"
            " synced_at timestamptz DEFAULT now(),"
            " PRIMARY KEY (tenant_id, source_db, ec_id))"))
        s.execute(_t("CREATE INDEX IF NOT EXISTS ix_ec_spojeni_org ON tenant.ec_spojeni (tenant_id, source_db, org_ec_id)"))
        s.commit()

        ins_kos = _t(
            "INSERT INTO tenant.ec_osoba (tenant_id, source_db, kind, ec_id, jmeno, prijmeni,"
            " titul_pred, titul_za, synced_at) "
            "VALUES (2, :src, 'kos', :id, :jm, :pr, :tp, :tz, now()) "
            "ON CONFLICT (tenant_id, source_db, kind, ec_id) DO UPDATE SET jmeno=EXCLUDED.jmeno,"
            " prijmeni=EXCLUDED.prijmeni, titul_pred=EXCLUDED.titul_pred, titul_za=EXCLUDED.titul_za,"
            " synced_at=now()")
        ins_zam = _t(
            "INSERT INTO tenant.ec_osoba (tenant_id, source_db, kind, ec_id, cislo_zam, jmeno, prijmeni, synced_at) "
            "VALUES (2, :src, 'zam', :id, :cislo, :jm, :pr, now()) "
            "ON CONFLICT (tenant_id, source_db, kind, ec_id) DO UPDATE SET cislo_zam=EXCLUDED.cislo_zam,"
            " jmeno=EXCLUDED.jmeno, prijmeni=EXCLUDED.prijmeni, synced_at=now()")
        ins_sp = _t(
            "INSERT INTO tenant.ec_spojeni (tenant_id, source_db, ec_id, org_ec_id, kos_ec_id, zam_ec_id,"
            " druh, typ, hodnota, hodnota2, popis, synced_at) "
            "VALUES (2, :src, :id, :org, :kos, :zam, :druh, :typ, :val, :val2, :popis, now()) "
            "ON CONFLICT (tenant_id, source_db, ec_id) DO UPDATE SET org_ec_id=EXCLUDED.org_ec_id,"
            " kos_ec_id=EXCLUDED.kos_ec_id, zam_ec_id=EXCLUDED.zam_ec_id, druh=EXCLUDED.druh,"
            " typ=EXCLUDED.typ, hodnota=EXCLUDED.hodnota, hodnota2=EXCLUDED.hodnota2,"
            " popis=EXCLUDED.popis, synced_at=now()")

        for src, dbp in (("EC", ""), ("IS", "DB_IS.dbo.")):
            try:
                kos = rows_of(
                    "SELECT ID id, LEFT(ISNULL(Jmeno,''),100) jm, LEFT(ISNULL(Prijmeni,''),100) pr,"
                    " LEFT(ISNULL(TitulPred,''),40) tp, LEFT(ISNULL(TitulZa,''),40) tz"
                    " FROM %sTabCisKOs" % dbp)
                for o in kos:
                    if o.get("id") is None:
                        continue
                    s.execute(ins_kos, {"src": src, "id": int(o["id"]), "jm": o.get("jm"),
                                        "pr": o.get("pr"), "tp": o.get("tp"), "tz": o.get("tz")})
                    counts["osoby"] += 1
                zam = rows_of(
                    "SELECT ID id, Cislo cislo, LEFT(ISNULL(Jmeno,''),100) jm, LEFT(ISNULL(Prijmeni,''),100) pr"
                    " FROM %sTabCisZam" % dbp)
                for o in zam:
                    if o.get("id") is None:
                        continue
                    s.execute(ins_zam, {"src": src, "id": int(o["id"]), "cislo": o.get("cislo"),
                                        "jm": o.get("jm"), "pr": o.get("pr")})
                    counts["osoby"] += 1
                sp = rows_of(
                    "SELECT ID id, ISNULL(IDOrg,0) org, ISNULL(IDCisKOs,0) kos, ISNULL(IDCisZam,0) zam,"
                    " ISNULL(Druh,0) druh, LEFT(ISNULL(Spojeni,''),255) val,"
                    " LEFT(ISNULL(Spojeni2,''),255) val2, LEFT(ISNULL(Popis,''),255) popis"
                    " FROM %sTabKontakty" % dbp)
                for o in sp:
                    if o.get("id") is None:
                        continue
                    s.execute(ins_sp, {
                        "src": src, "id": int(o["id"]),
                        "org": int(o.get("org") or 0) or None,
                        "kos": int(o.get("kos") or 0) or None,
                        "zam": int(o.get("zam") or 0) or None,
                        "druh": int(o.get("druh") or 0),
                        "typ": _classify_spojeni(o.get("val")),
                        "val": o.get("val"), "val2": o.get("val2"), "popis": o.get("popis")})
                    counts["spojeni"] += 1
                s.commit()
            except Exception as exc:
                s.rollback()
                errors.append("%s: %s" % (src, str(exc)[:160]))
    except Exception:
        s.rollback()
        raise
    finally:
        cm.__exit__(None, None, None)
    return {"counts": counts, "errors": errors}


def _norm_phone(v: str):
    import re as _re
    s = _re.sub(r"[\s\-\(\)\.]", "", v or "")
    if not s:
        return None
    if s.startswith("00"):
        s = "+" + s[2:]
    if not s.startswith("+"):
        digits = _re.sub(r"\D", "", s)
        if len(digits) == 9 and digits[0] in "67":
            s = "+420" + digits
        elif len(digits) >= 11:
            s = "+" + digits
        elif len(digits) == 9:
            s = "+420" + digits
        else:
            return None
    if _re.match(r"^\+[1-9]\d{7,14}$", s):
        return s
    return None


def _norm_email(v: str):
    s = (v or "").strip().lower()
    if "@" in s and "." in s.split("@")[-1]:
        return s
    return None


def _norm_web(v: str):
    s = (v or "").strip().lower().rstrip("/")
    for p in ("https://", "http://"):
        if s.startswith(p):
            s = s[len(p):]
    if s.startswith("www."):
        s = s[4:]
    return s or None


def _purpose_from_popis(popis: str):
    p = (popis or "").lower()
    if "objedn" in p:
        return "objednavky"
    if "faktur" in p or "účet" in p or "ucet" in p:
        return "fakturace"
    return None


def _derive_kontakty() -> dict:
    """Marti 9.6.2026: Fáze 2 derivace — zrcadlo (ec_org/ec_osoba/ec_spojeni)
    → univerzální vrstva (subjekt + kanál + vazba s vlastnictvím/účely/proveniencí).
    Normalizace (E.164 / lowercase email) → dedup kanálů. Matching zaměstnanců na
    naše users přes att_employee. Cut-over A: source='erp', priority 10 (ruční
    override bude mít vyšší). Idempotentní (upserty + cache). ⚙ derive_kontakty."""
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t

    cm = _pg.get_session()
    s = cm.__enter__()
    res = {"subjekty": 0, "kanaly": 0, "vazby": 0, "matchnuto_user": 0}
    try:
        # firmy EC/ES pro ownership zaměstnanců
        co = {r[0]: r[1] for r in s.execute(_t(
            "SELECT code, id FROM tenant.company WHERE tenant_id=2")).fetchall()}
        co_by_src = {"EC": co.get("EC"), "IS": co.get("ES")}
        # mapování číslo zaměstnance → user_id (doctrine #24: scalar, bez fan-out)
        empmap = {}
        for r in s.execute(_t(
            "SELECT cislo_zam, user_id FROM tenant.att_employee "
            "WHERE tenant_id=2 AND user_id IS NOT NULL AND cislo_zam IS NOT NULL")).fetchall():
            empmap.setdefault(str(r[0]), r[1])

        # preload existující subjekty (ec-klíč) + kanály (dedup) do cache
        subj_cache = {}
        for r in s.execute(_t(
            "SELECT ec_source, ec_kind, ec_id, id FROM tenant.subjekt "
            "WHERE tenant_id=2 AND ec_id IS NOT NULL")).fetchall():
            subj_cache[(r[0], r[1], int(r[2]))] = r[3]
        user_subj = {}
        for r in s.execute(_t(
            "SELECT user_id, id FROM tenant.subjekt WHERE tenant_id=2 AND user_id IS NOT NULL")).fetchall():
            user_subj[r[0]] = r[1]
        kanal_cache = {}
        for r in s.execute(_t(
            "SELECT typ, value_normalized, id FROM tenant.kontakt_kanal WHERE tenant_id=2")).fetchall():
            kanal_cache[(r[0], r[1])] = r[2]

        def get_subj(kind, src, eckind, ecid, name, user_id=None):
            key = (src, eckind, int(ecid))
            if key in subj_cache:
                sid = subj_cache[key]
                if user_id and user_id not in user_subj:
                    user_subj[user_id] = sid
                return sid
            # osoba zaměstnance s user matchem → kanonický subjekt usera (1 člověk = 1 subjekt)
            if user_id and user_id in user_subj:
                sid = user_subj[user_id]
                subj_cache[key] = sid
                return sid
            sid = s.execute(_t(
                "INSERT INTO tenant.subjekt (tenant_id, kind, display_name, user_id, ec_source, ec_kind, ec_id) "
                "VALUES (2, :k, :nm, :u, :src, :ek, :ec) RETURNING id"),
                {"k": kind, "nm": (name or "").strip()[:200] or None, "u": user_id,
                 "src": src, "ek": eckind, "ec": int(ecid)}).first()[0]
            subj_cache[key] = sid
            if user_id:
                user_subj[user_id] = sid
                res["matchnuto_user"] += 1
            res["subjekty"] += 1
            return sid

        def get_kanal(typ, raw):
            if typ == "email":
                norm = _norm_email(raw)
            elif typ == "telefon":
                norm = _norm_phone(raw)
            elif typ == "web":
                norm = _norm_web(raw)
            else:
                norm = (raw or "").strip().lower() or None
            if not norm:
                norm = (raw or "").strip().lower() or None
            if not norm:
                return None
            key = (typ, norm)
            if key in kanal_cache:
                return kanal_cache[key]
            kid = s.execute(_t(
                "INSERT INTO tenant.kontakt_kanal (tenant_id, typ, value_raw, value_normalized) "
                "VALUES (2, :t, :vr, :vn) ON CONFLICT (tenant_id, typ, value_normalized) "
                "DO UPDATE SET value_raw=EXCLUDED.value_raw RETURNING id"),
                {"t": typ, "vr": (raw or "").strip()[:300], "vn": norm[:300]}).first()[0]
            kanal_cache[key] = kid
            res["kanaly"] += 1
            return kid

        def link(subj_id, kanal_id, ownership, company_id, purpose, popis, primary=False):
            skid = s.execute(_t(
                "INSERT INTO tenant.subjekt_kanal (tenant_id, subjekt_id, kanal_id, ownership_type,"
                " ownership_company_id, is_primary, source, source_priority, carddav_sync, popis) "
                "VALUES (2, :s, :k, :ow, :co, :pr, 'erp', 10, true, :po) "
                "ON CONFLICT (tenant_id, subjekt_id, kanal_id) DO UPDATE SET updated_at=now() RETURNING id"),
                {"s": subj_id, "k": kanal_id, "ow": ownership, "co": company_id,
                 "pr": primary, "po": (popis or "")[:255] or None}).first()[0]
            res["vazby"] += 1
            if purpose:
                s.execute(_t(
                    "INSERT INTO tenant.subjekt_kanal_purpose (subjekt_kanal_id, purpose_code) "
                    "VALUES (:s, :p) ON CONFLICT DO NOTHING"), {"s": skid, "p": purpose})
            return skid

        # A) subjekty organizací + jejich objednávkové email/telefon (účel objednavky)
        for o in s.execute(_t(
            "SELECT source_db, ec_id, nazev, jmeno, prijmeni, obj_email, obj_telefon "
            "FROM tenant.ec_org WHERE tenant_id=2")).fetchall():
            nm = (o[2] or "").strip() or ((o[4] or "") + " " + (o[3] or "")).strip()
            sid = get_subj("organizace", o[0], "org", o[1], nm)
            if o[5]:
                kid = get_kanal("email", o[5])
                if kid:
                    link(sid, kid, "firma", None, "objednavky", "objednávkový email", True)
            if o[6]:
                kid = get_kanal("telefon", o[6])
                if kid:
                    link(sid, kid, "firma", None, "objednavky", "objednávkový telefon", True)
            if res["vazby"] % 500 == 0:
                s.commit()
        s.commit()

        # B) subjekty osob (kos) + zaměstnanců (zam, match na user)
        for o in s.execute(_t(
            "SELECT source_db, kind, ec_id, cislo_zam, jmeno, prijmeni FROM tenant.ec_osoba "
            "WHERE tenant_id=2")).fetchall():
            nm = ((o[5] or "") + " " + (o[4] or "")).strip()
            if o[1] == "zam":
                uid = empmap.get(str(o[3])) if o[3] is not None else None
                get_subj("osoba", o[0], "zam", o[2], nm, user_id=uid)
            else:
                get_subj("osoba", o[0], "kos", o[2], nm)
            if res["subjekty"] % 1000 == 0:
                s.commit()
        s.commit()

        # C) spojení → kanály + vazby (org → kos → zam priorita)
        for sp in s.execute(_t(
            "SELECT source_db, typ, hodnota, popis, org_ec_id, kos_ec_id, zam_ec_id "
            "FROM tenant.ec_spojeni WHERE tenant_id=2 AND hodnota<>''")).fetchall():
            src, typ, val, popis = sp[0], sp[1], sp[2], sp[3]
            sid = None
            ownership, company_id = "firma", None
            if sp[4]:
                sid = subj_cache.get((src, "org", int(sp[4])))
            if sid is None and sp[5]:
                sid = subj_cache.get((src, "kos", int(sp[5])))
            if sid is None and sp[6]:
                sid = subj_cache.get((src, "zam", int(sp[6])))
                # zaměstnanec = firemní vlastnictví dané firmy (EC/ES)
                company_id = co_by_src.get(src)
            if sid is None:
                continue
            kid = get_kanal(typ if typ in ("email", "telefon", "web") else "jine", val)
            if kid is None:
                continue
            link(sid, kid, ownership, company_id, _purpose_from_popis(popis), popis)
            if res["vazby"] % 500 == 0:
                s.commit()
        s.commit()
    except Exception:
        s.rollback()
        raise
    finally:
        cm.__exit__(None, None, None)
    return res


def _sync_absence_to_ec_vytizeni(dnu_zpet: int = 14) -> dict:
    """JEDNOSMĚRNÝ sync (Marti 28.6.2026): naše plánované absence
    (tenant.att_planned_absence = NAŠE pravda, plněná naší appkou) →
    st.EC_Vytizeni_NepritomnostSTRATEGIE v DB_EC, odkud (po přesměrování
    dbo.ECv_Vytizeni_SeznamNepritomnost) čte Excel 'Plánování vytížení'.
    Čteme jen z PG, píšeme jen do st — st nikdo nečte zpátky k nám → BEZ REKURZE.
    Originál dbo.EC_Dochazka_PlanNepritomnost se nepoužívá (zakázán)."""
    import json as _jv
    import datetime as _dtv
    from sqlalchemy import text as _tv
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        return {"ok": False, "error": "EUROSOFT MCP nedostupné"}

    def _ecw(s):
        rj = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                                {"sql": s, "db_name": "DB_EC"}, conversation_id=None)
        r = (_jv.loads(rj) if isinstance(rj, str) else rj) or {}
        if r.get("ok") is False:
            raise RuntimeError(str(r.get("error") or r.get("message"))[:200])
        return r

    # 1) NAŠE absence z PG (jen číselné EC cislo_zam; recent + budoucnost)
    cm, s = _att_session()
    try:
        rows = s.execute(_tv(
            "SELECT (e.cislo_zam)::int AS cislo, pa.datum::text AS d, "
            "       pa.druh_kod AS druh, COALESCE(pa.hodiny,0)::int AS hod "
            "FROM tenant.att_planned_absence pa "
            "JOIN tenant.att_employee e "
            "  ON e.cislo_zam = pa.cislo_zam AND e.tenant_id = pa.tenant_id "
            "WHERE pa.tenant_id = 2 AND pa.datum >= CURRENT_DATE - :db "
            "  AND e.cislo_zam ~ '^[0-9]+$' "
            "ORDER BY cislo, d"), {"db": int(dnu_zpet)}).fetchall()
    finally:
        cm.__exit__(None, None, None)

    _DOW = {0: "Po", 1: "Út", 2: "St", 3: "Čt", 4: "Pá", 5: "So", 6: "Ne"}
    # 1b) barva per DruhCinnosti = kanonická z EC originálu (EC_Dochazka_PlanNepritomnost.Barva,
    # nejčastější barva na druh). Bez ní Excel „Plánování vytížení" nedobarví činnosti/druhy
    # nepřítomnosti → rozpadlé statistiky (reklamace Pillár 30.6.). View bere pn.Barva → MUSÍME plnit.
    _BARVA_DEF = "FFDCA5"
    barva_by = {}
    try:
        rb = _ecw("SELECT DruhCinnosti, Barva FROM (SELECT DruhCinnosti, Barva, "
                  "ROW_NUMBER() OVER (PARTITION BY DruhCinnosti ORDER BY COUNT(*) DESC) rn "
                  "FROM dbo.EC_Dochazka_PlanNepritomnost WHERE Barva IS NOT NULL AND Barva<>'' "
                  "GROUP BY DruhCinnosti, Barva) t WHERE rn=1")
        for rr in (rb.get("rows") or []):
            try:
                barva_by[int(rr.get("DruhCinnosti"))] = (str(rr.get("Barva") or "").strip()[:10]) or _BARVA_DEF
            except Exception:
                pass
    except Exception:
        pass
    # 2) přepiš st tabulku (jednosměrně): DELETE + batch INSERT
    _ecw("DELETE FROM st.EC_Vytizeni_NepritomnostSTRATEGIE")
    vals, n = [], 0

    def _flush(vv):
        if not vv:
            return 0
        _ecw("INSERT INTO st.EC_Vytizeni_NepritomnostSTRATEGIE"
             "(CisloZam,DatumPripadu,DenVTydnu,DruhCinnosti,PocetHodin,Barva) VALUES "
             + ",".join(vv))
        return len(vv)

    for r in rows:
        try:
            cislo = int(r[0]); d = str(r[1])[:10]; druh = int(r[2]); hod = int(r[3] or 0)
        except Exception:
            continue
        wd = _dtv.date.fromisoformat(d).weekday()
        barva = barva_by.get(druh, _BARVA_DEF) or _BARVA_DEF
        vals.append("(%d,'%s',N'%s',%d,%d,N'%s')" % (cislo, d, _DOW.get(wd, ""), druh, hod, barva))
        if len(vals) >= 200:
            n += _flush(vals); vals = []
    n += _flush(vals)
    return {"ok": True, "vlozeno": n, "dnu_zpet": int(dnu_zpet), "barev": len(barva_by)}


def _sync_vyroba_plan_from_ec() -> dict:
    """Marti 8.6.2026: read-only zrcadlo plánu výroby (EC_Vytizeni_PlanMonteri,
    živý systém za Excelem 'Plánování vytížení') → tenant.vyroba_plan. Řádek =
    montér × zakázka × den × hodiny. Okno today..+60 dní (DELETE+reload).
    CisloZam → user_id přes tenant.att_employee. DB_EC zůstává zdroj pravdy."""
    import json as _json_v
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        raise RuntimeError("EUROSOFT MCP nedostupné")
    sql = ("SELECT m.ID id, m.CisloZam cz, "
           "LTRIM(RTRIM(ISNULL(z.Prijmeni,'') + ' ' + ISNULL(z.Jmeno,''))) zam, "
           "m.CisloZakazky ck, LEFT(ISNULL(v.Nazev,''),200) nz, "
           "CONVERT(varchar(10), m.Datum, 23) dt, m.PocetHodin hod, "
           "CAST(ISNULL(m.JsemMonter,0) AS int) jm, m.Typ typ "
           "FROM EC_Vytizeni_PlanMonteri m "
           "LEFT JOIN EC_Vytizeni_Zakazky v ON v.CisloZakazky = m.CisloZakazky "
           "LEFT JOIN TabCisZam z ON z.Cislo = m.CisloZam "
           "WHERE m.Datum >= CAST(GETDATE() AS DATE) "
           "AND m.Datum < DATEADD(day, 100, CAST(GETDATE() AS DATE))")
    raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                             {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
    r = _json_v.loads(raw) if isinstance(raw, str) else raw
    rows = []
    if isinstance(r, dict):
        if r.get("ok") is False:
            raise RuntimeError(str(r.get("error")))
        for k in ("rows", "data", "result", "records"):
            if isinstance(r.get(k), list):
                rows = r[k]
                break
    elif isinstance(r, list):
        rows = r

    cm = _pg.get_session()
    sess = cm.__enter__()
    n = 0
    try:
        sess.execute(_t(
            "CREATE TABLE IF NOT EXISTS tenant.vyroba_plan ("
            " tenant_id bigint NOT NULL, ext_id bigint NOT NULL,"
            " cislo_zam int, zam_jmeno text, user_id bigint, cislo_zakazky varchar(40),"
            " zakazka_nazev text, datum date, pocet_hodin numeric(6,2),"
            " je_monter boolean, typ varchar(20),"
            " synced_at timestamptz DEFAULT now(),"
            " PRIMARY KEY (tenant_id, ext_id))"))
        sess.execute(_t(
            "ALTER TABLE tenant.vyroba_plan ADD COLUMN IF NOT EXISTS zam_jmeno text"))
        sess.execute(_t(
            "CREATE INDEX IF NOT EXISTS ix_vyroba_plan_user_datum"
            " ON tenant.vyroba_plan (tenant_id, user_id, datum)"))
        # mapa CisloZam -> user_id z docházky
        umap = {}
        for er in sess.execute(_t(
            "SELECT cislo_zam, user_id FROM tenant.att_employee"
            " WHERE tenant_id = 2 AND user_id IS NOT NULL")).mappings().all():
            umap[str(er["cislo_zam"]).strip()] = er["user_id"]
        # okno today.. čistě přerovnat
        sess.execute(_t("DELETE FROM tenant.vyroba_plan"
                        " WHERE tenant_id = 2 AND datum >= CURRENT_DATE"))
        for row in rows:
            cz = row.get("cz")
            uid = umap.get(str(cz).strip()) if cz is not None else None
            sess.execute(_t(
                "INSERT INTO tenant.vyroba_plan (tenant_id, ext_id, cislo_zam, zam_jmeno, user_id,"
                " cislo_zakazky, zakazka_nazev, datum, pocet_hodin, je_monter, typ, synced_at)"
                " VALUES (2, :eid, :cz, :zam, :uid, :ck, :nz, :dt, :hod, :jm, :typ, now())"
                " ON CONFLICT (tenant_id, ext_id) DO UPDATE SET cislo_zam = EXCLUDED.cislo_zam,"
                " zam_jmeno = EXCLUDED.zam_jmeno,"
                " user_id = EXCLUDED.user_id, cislo_zakazky = EXCLUDED.cislo_zakazky,"
                " zakazka_nazev = EXCLUDED.zakazka_nazev, datum = EXCLUDED.datum,"
                " pocet_hodin = EXCLUDED.pocet_hodin, je_monter = EXCLUDED.je_monter,"
                " typ = EXCLUDED.typ, synced_at = now()"),
                {"eid": row.get("id"), "cz": cz,
                 "zam": (str(row.get("zam")).strip() or None) if row.get("zam") is not None else None,
                 "uid": uid,
                 "ck": (str(row.get("ck")).strip() if row.get("ck") is not None else None),
                 "nz": row.get("nz"), "dt": row.get("dt"), "hod": row.get("hod"),
                 "jm": bool(int(row.get("jm") or 0)), "typ": row.get("typ")})
            n += 1
        sess.commit()
    except Exception:
        sess.rollback()
        raise
    finally:
        cm.__exit__(None, None, None)
    return {"synced": n}


def _sync_odvozy_from_ec() -> dict:
    """Marti 8.6.2026: read-only zrcadlo odvozů (ECv_Vytizeni_Odvozy) →
    tenant.vyroba_odvoz. Okno -7 dní..budoucnost. RTF adresa očištěná na text."""
    import json as _json_o, re as _re_o
    from modules.conversation.application.eurosoft_mcp_client import get_eurosoft_mcp_client
    from modules.strategie_pg.application import service as _pg
    from sqlalchemy import text as _t
    mcp = get_eurosoft_mcp_client()
    if mcp is None:
        raise RuntimeError("EUROSOFT MCP nedostupné")

    def _rtf(s):
        if not s:
            return ""
        x = str(s)
        x = _re_o.sub(r"\{\\(?:fonttbl|colortbl|stylesheet|generator|\*)[^{}]*\}", " ", x)
        x = _re_o.sub(r"\\par[d]?\b", "\n", x)
        x = _re_o.sub(r"\\'[0-9a-fA-F]{2}", "", x)
        x = _re_o.sub(r"\\[a-zA-Z]+-?[0-9]* ?", "", x)
        x = x.replace("{", "").replace("}", "")
        lines = [ln.strip() for ln in x.split("\n")]
        lines = [ln for ln in lines if ln]
        return " · ".join(lines)[:220]

    sql = ("SELECT ID id, CisloZakazky ck, CONVERT(varchar(10), DatumOdvozu, 23) dt, "
           "LEFT(ISNULL(Poznamka,''),500) pozn, AdresaDoruceni adr "
           "FROM ECv_Vytizeni_Odvozy "
           "WHERE DatumOdvozu >= DATEADD(day,-7,CAST(GETDATE() AS DATE))")
    raw = mcp.call_tool_sync("eurosoft_strategie_query_raw",
                             {"sql": sql, "db_name": "DB_EC"}, conversation_id=None)
    r = _json_o.loads(raw) if isinstance(raw, str) else raw
    rows = []
    if isinstance(r, dict):
        if r.get("ok") is False:
            raise RuntimeError(str(r.get("error")))
        for k in ("rows", "data", "result", "records"):
            if isinstance(r.get(k), list):
                rows = r[k]
                break
    elif isinstance(r, list):
        rows = r

    cm = _pg.get_session()
    sess = cm.__enter__()
    n = 0
    try:
        sess.execute(_t(
            "CREATE TABLE IF NOT EXISTS tenant.vyroba_odvoz ("
            " tenant_id bigint NOT NULL DEFAULT 2, ext_id bigint NOT NULL,"
            " cislo_zakazky varchar(40), datum_odvozu date, poznamka text,"
            " adresa text, synced_at timestamptz DEFAULT now(),"
            " PRIMARY KEY (tenant_id, ext_id))"))
        sess.execute(_t("DELETE FROM tenant.vyroba_odvoz WHERE tenant_id = 2"))
        for row in rows:
            sess.execute(_t(
                "INSERT INTO tenant.vyroba_odvoz (tenant_id, ext_id, cislo_zakazky, datum_odvozu, poznamka, adresa, synced_at)"
                " VALUES (2, :eid, :ck, :dt, :pz, :ad, now())"),
                {"eid": row.get("id"),
                 "ck": (str(row.get("ck")).strip() if row.get("ck") is not None else None),
                 "dt": row.get("dt"), "pz": row.get("pozn"),
                 "ad": _rtf(row.get("adr"))})
            n += 1
        sess.commit()
    except Exception:
        sess.rollback()
        raise
    finally:
        cm.__exit__(None, None, None)
    return {"synced": n}


def _ops_pending_for_instance(iid: str) -> list:
    """Vrátí pending ops pro instanci a označí je 'ack' (picked_at). Watcher je
    provede + reportne přes /ops/{id}/result. Best-effort."""
    target = "instance:%s" % iid
    try:
        from core.database_data import get_data_session as _gp_op
        from sqlalchemy import text as _tp_op
        s = _gp_op()
        try:
            rows = s.execute(_tp_op(
                "SELECT id, action_key, params FROM fw.ops_request "
                "WHERE target = :t AND status = 'pending' ORDER BY id ASC"
            ), {"t": target}).mappings().all()
            out = [dict(r) for r in rows]
            if out:
                ids = [r["id"] for r in out]
                s.execute(_tp_op(
                    "UPDATE fw.ops_request SET status='ack', picked_at=now() "
                    "WHERE id = ANY(:ids)"
                ), {"ids": ids})
                s.commit()
            # přidej op-handler key z registru (watcher ví, co dělat)
            for r in out:
                meta = _OPS_ACTIONS.get(r["action_key"], {})
                r["op"] = meta.get("op")
            return out
        finally:
            s.close()
    except Exception:
        return []


@api_router.post("/ops/request")
async def ops_request(req: Request) -> JSONResponse:
    """Parent požádá o pojmenovanou ops akci (z whitelistu). Cloud akce běží
    hned; remote jdou do fronty pro agenta. Vše do fw.ops_request (audit)."""
    uid = _get_uid(req)
    _require_parent(uid)  # produkční ops akce (restart/deploy infra) = rodičovské
    try:
        body = await req.json()
    except Exception:
        body = {}
    action_key = str(body.get("action_key") or "").strip()
    meta = _OPS_ACTIONS.get(action_key)
    if not meta:
        return JSONResponse({"ok": False, "error": "neznámá akce (mimo whitelist)"}, status_code=400)

    # jméno žadatele pro audit
    name = None
    try:
        from core.database_core import get_core_session as _gcs_op
        from modules.core.infrastructure.models_core import User as _U_op
        _cs = _gcs_op()
        try:
            u = _cs.query(_U_op).filter_by(id=uid).first()
            if u:
                name = (u.short_name or getattr(u, "first_name", None) or ("#%s" % uid))
        finally:
            _cs.close()
    except Exception:
        pass

    from core.database_data import get_data_session as _gp_or
    from sqlalchemy import text as _tp_or
    s = _gp_or()
    try:
        rid = s.execute(_tp_or(
            "INSERT INTO fw.ops_request (action_key, target, status, requested_by_user_id, requested_by_name) "
            "VALUES (:ak, :tg, 'pending', :uid, :nm) RETURNING id"
        ), {"ak": action_key, "tg": meta["target"], "uid": uid, "nm": name}).scalar()
        s.commit()
    finally:
        s.close()

    # Cloud akce → spustit hned inline.
    if not meta.get("remote"):
        # _ops_execute_cloud dělá BLOKUJÍCÍ self-HTTP (refresh_secondary health-check A→A
        # :8002). V async handleru by zablokoval event loop → vlastní api-info se neobslouží
        # → ReadTimeout → B NIKDY nedožene A (Marti 7.7.). Pustit MIMO smyčku (threadpool),
        # ať zůstane volná pro obsloužení self-callu.
        from starlette.concurrency import run_in_threadpool as _ritp_ops
        result = await _ritp_ops(_ops_execute_cloud, action_key, rid, uid)
        return JSONResponse(jsonable_encoder({"ok": True, "request_id": rid,
                                              "remote": False, **result}))
    # Remote akce → ve frontě, agent si ji vyzvedne v heartbeatu (do ~30 s).
    return JSONResponse({"ok": True, "request_id": rid, "remote": True,
                         "message": "Příkaz zařazen — %s provede do ~30 s." % meta["target"]})


def _ops_refresh_secondary(force: bool = False) -> dict:
    """Blue-green: zkopíruje AKTUÁLNÍ (ověřenou) verzi produkce do zálohy a restartuje API-B.
    Záloha (STRATEGIE-prev) = zmrazená stabilní verze, na kterou Caddy přeroutuje usery, když
    deploy odstřelí API-A. Tlačítkem ji povýšíme na současný stav. Spouští skript
    scripts/refresh_secondary.ps1 NA POZADÍ (detached) — robocopy celého repa trvá dlouho,
    nesmí blokovat HTTP handler (12.6. timeout). Výstup do scripts/refresh_secondary_last.log.
    Záloha NENÍ git checkout (fyzická kopie) → proto kopie, ne git pull.
    force=True: přeskoč jen VERZNÍ pojistku (A commit != HEAD), ne zdravotní (Marti 6.7. — proti tichému failu).
    KAŽDÉ blokování pojistky se LOGUJE do refresh_secondary_last.log (viditelné na /zaloha-status)."""
    import subprocess as _sp, os as _os, datetime as _dt0
    src = _os.environ.get("STRATEGIE_PRIMARY_DIR") or r"C:\Projekty\STRATEGIE"

    def _rlog(_msg):
        try:
            with open(_os.path.join(src, "scripts", "refresh_secondary_last.log"), "a",
                      encoding="utf-8") as _lf:
                _lf.write("[%s] %s\n" % (_dt0.datetime.now().strftime("%Y-%m-%d %H:%M:%S"), _msg))
        except Exception:
            pass

    if not _os.path.isdir(src):
        return {"ok": False, "result": "zdrojová (primární) složka neexistuje: %s" % src}
    # POJISTKA (Marti 5.7.2026): NEPOVYŠUJ zálohu B, když API A není zdravé NEBO neběží na
    # aktuální verzi pracovního adresáře. Jinak bychom rozbité/neověřené A propsali do B a
    # přišli o blue-green fallback (A i B dole). B povyš jen z PROKAZATELNĚ dobrého A.
    import requests as _rq_rs
    aport = _os.environ.get("STRATEGIE_PRIMARY_PORT") or "8002"
    try:
        _dir_sha = _sp.check_output(["git", "-C", src, "rev-parse", "--short", "HEAD"],
                                    stderr=_sp.DEVNULL, timeout=5).decode().strip()
    except Exception:
        _dir_sha = ""
    # Health-check je SELF-request A→A (:8002). Pod zátěží občas nestihne 4s timeout
    # (ReadTimeout) → refresh se zbytečně zruší a B NIKDY nedožene A (Marti 7.7.). Proto
    # 3 pokusy s delším timeoutem a krátkou pauzou — přechodná špička refresh nezablokuje.
    import time as _time_rs
    _ai = None
    _hexc = None
    for _attempt in range(3):
        try:
            _ai = _rq_rs.get("http://127.0.0.1:%s/api/v1/api-info" % aport, timeout=8).json()
            break
        except Exception as _e_rs:
            _hexc = _e_rs
            _ai = None
            if _attempt < 2:
                _time_rs.sleep(1.5)
    if not (isinstance(_ai, dict) and _ai.get("ok")):
        _why = type(_hexc).__name__ if _hexc else "nehlásí OK"
        _msg = ("POJISTKA (zdravotní): API A (:%s) neodpovídá ani po 3 pokusech (%s) — refresh zálohy "
                "ZRUŠEN, ať nepropíšeme rozbité A do B. Ověř, že A zdravě běží, pak zkus znovu. "
                "(force NEobchází zdravotní pojistku.)" % (aport, _why))
        _rlog(_msg)
        return {"ok": False, "result": _msg}
    _a_sha = (_ai.get("commit") or "").strip()
    if _dir_sha and _a_sha and not (_a_sha.startswith(_dir_sha) or _dir_sha.startswith(_a_sha)):
        if force:
            _rlog("POJISTKA (verzní) PŘESKOČENA na force: A=%s != HEAD=%s (A je zdravé, operátor "
                  "vynutil). Povyšuji zálohu z pracovního adresáře." % (_a_sha, _dir_sha))
        else:
            _msg = ("POJISTKA (verzní): API A běží na verzi A=%s, ale pracovní adresář je na HEAD=%s "
                    "— A ještě nenaběhlo na aktuální kód (typicky pár sekund po deployi, nebo série "
                    "deployů). Počkej, až A restartuje na HEAD, a zkus znovu; NEBO force (pokud víš, "
                    "že A je v pořádku). Refresh ZRUŠEN — DŮVOD ZALOGOVÁN." % (_a_sha, _dir_sha))
            _rlog(_msg)
            return {"ok": False, "result": _msg}
    # A je zdravé a běží na aktuální verzi → bezpečné povýšit zálohu B.
    # API jako služba NEMÁ z web handleru práva spustit nssm/detached proces (12.6. doctrine).
    # Proto zapíšeme MARKER → STRATEGIE-RESTART-WATCHER (privilegovaný) spustí refresh_secondary.ps1.
    import json as _json, datetime as _dt
    try:
        from modules.conversation.application import deployment_service as _dep
        mdir = _dep.MARKER_DIR
    except Exception:
        from pathlib import Path as _Path
        mdir = _Path(_os.environ.get("STRATEGIE_RESTART_MARKER_DIR") or r"C:\Data\STRATEGIE\restart_markers")
    try:
        mdir.mkdir(parents=True, exist_ok=True)
        ts = _dt.datetime.utcnow().strftime("%Y%m%d_%H%M%S")
        mp = mdir / ("%s_refreshsec.refreshsec" % ts)
        mp.write_text(_json.dumps({"deps": False, "by": "ops", "force": bool(force)}), encoding="utf-8")
        _rlog("Marker zapsán (%s%s) → RESTART-WATCHER spustí refresh zálohy."
              % (mp.name, " [FORCE]" if force else ""))
        return {"ok": True, "result": "Marker zapsán (%s) → RESTART-WATCHER spustí stop API-B → "
                "kopie repa → start API-B (~30-90 s). Pak klikni Kontrola zálohy."
                % mp.name}
    except Exception as exc:
        return {"ok": False, "result": "Marker se nepodařilo zapsat: %s: %s"
                % (type(exc).__name__, exc)}


def _ops_secondary_status() -> dict:
    """Kontrola blue-green zálohy: běží API-B? z jaké složky/verze? + log posledního refreshe.
    Volá /api/v1/api-info na obě porty (A:8002, B:8003) z localhostu."""
    import os as _os, requests as _rq, datetime as _dt
    src = _os.environ.get("STRATEGIE_PRIMARY_DIR") or r"C:\Projekty\STRATEGIE"
    aport = _os.environ.get("STRATEGIE_PRIMARY_PORT") or "8002"
    bport = _os.environ.get("STRATEGIE_SECONDARY_PORT") or "8003"
    parts = []

    def info(port):
        try:
            j = _rq.get("http://127.0.0.1:%s/api/v1/api-info" % port, timeout=3).json()
            return "BĚŽÍ (dir=%s, commit=%s, instance=%s)" % (j.get("dir"), j.get("commit"), j.get("instance"))
        except Exception as e:
            return "NEDOSTUPNÉ (%s)" % type(e).__name__
    parts.append("API-A (%s): %s" % (aport, info(aport)))
    parts.append("API-B (%s): %s" % (bport, info(bport)))
    log = _os.path.join(src, "scripts", "refresh_secondary_last.log")
    if _os.path.isfile(log):
        try:
            mt = _dt.datetime.fromtimestamp(_os.path.getmtime(log)).strftime("%d.%m. %H:%M")
            with open(log, encoding="utf-8", errors="replace") as f:
                tail = f.read().strip()
            parts.append("LOG refreshe (%s): %s" % (mt, (tail[-500:] or "(prázdný)")))
        except Exception as e:
            parts.append("LOG chyba: %s" % e)
    else:
        parts.append("LOG refreshe NEEXISTUJE → tlačítko 'Zkopírovat do zálohy' ještě neproběhlo")
    return {"ok": True, "result": " || ".join(parts)}


def _ops_caddy_pin_failover() -> dict:
    """Přidá failover na primární (8002) k version-pinned routám v ŽIVÉM Caddyfile
    (C:\\caddy\\Caddyfile). Důvod: pin na 'previous' při zastavené B = mrtvá instance
    (past 14.6.2026). Cílený string-replace (zachová lokální timeouty/keepalive/lb_try —
    NEPŘEPISUJEME celý soubor!). Idempotentní. Backup + caddy validate + reload; při
    chybě validace rollback. Cesty/exe konfigurovatelné env."""
    import subprocess as _sp, os as _os, shutil as _sh, time as _tm
    cfg = _os.environ.get("STRATEGIE_CADDYFILE") or r"C:\caddy\Caddyfile"
    caddy = _os.environ.get("STRATEGIE_CADDY_EXE") or "caddy"
    if not _os.path.isfile(cfg):
        return {"ok": False, "result": "Caddyfile nenalezen: %s" % cfg}
    try:
        with open(cfg, "r", encoding="utf-8") as f:
            txt = f.read()
    except Exception as exc:
        return {"ok": False, "result": "čtení Caddyfile selhalo: %s" % exc}
    _hb = ("\n        lb_policy first\n        lb_try_duration 5s\n        lb_try_interval 250ms\n"
           "        health_uri /api/v1/health\n"
           "        health_interval 3s\n        health_timeout 2s\n        health_status 2xx\n"
           "        fail_duration 10s\n        max_fails 1")
    # matcher line -> (already-done marker, replacement)
    targets = [
        ("@versionPrevious localhost:8003 {", "@versionPrevious localhost:8003 localhost:8002 {",
         "@versionPrevious localhost:8003 localhost:8002 {" + _hb),
        ("@versionOlder1 localhost:8004 {", "@versionOlder1 localhost:8004 localhost:8002 {",
         "@versionOlder1 localhost:8004 localhost:8002 {" + _hb),
        ("@versionOlder2 localhost:8005 {", "@versionOlder2 localhost:8005 localhost:8002 {",
         "@versionOlder2 localhost:8005 localhost:8002 {" + _hb),
    ]
    new = txt
    changed = []
    for old_line, done_marker, repl in targets:
        if done_marker in new:
            continue  # idempotence — failover už tam je
        if old_line in new:
            new = new.replace(old_line, repl, 1)
            changed.append(old_line.split()[0])
    if new == txt:
        return {"ok": True, "result": "Failover už je nastaven (žádná změna)."}
    bak = cfg + ".bak_failover_" + _tm.strftime("%Y%m%d_%H%M%S")
    try:
        _sh.copyfile(cfg, bak)
        with open(cfg, "w", encoding="utf-8") as f:
            f.write(new)
    except Exception as exc:
        return {"ok": False, "result": "zápis Caddyfile selhal: %s" % exc}
    # Reload BEZ závislosti na caddy.exe v PATH: primárně Caddy admin API
    # (POST localhost:2019/load, text/caddyfile → adapt+validace+apply atomicky).
    # Fallback na CLI (s hledáním exe). Při chybě rollback ze zálohy.
    admin = _os.environ.get("STRATEGIE_CADDY_ADMIN") or "http://localhost:2019"
    reload_ok = False
    reload_msg = ""
    try:
        import urllib.request as _u, urllib.error as _ue
        rq = _u.Request(admin.rstrip("/") + "/load", data=new.encode("utf-8"),
                        headers={"Content-Type": "text/caddyfile"}, method="POST")
        with _u.urlopen(rq, timeout=30) as resp:
            if 200 <= getattr(resp, "status", 200) < 300:
                reload_ok = True
                reload_msg = "admin API /load OK"
            else:
                reload_msg = "admin /load HTTP %s" % getattr(resp, "status", "?")
    except Exception as _adm_exc:
        # admin API selhalo (HTTPError = nevalidní config; jinak nedostupné) →
        # zkus CLI fallback. HTTPError tělo si vytáhneme pro diagnostiku.
        try:
            import urllib.error as _ue2
            if isinstance(_adm_exc, _ue2.HTTPError):
                _b = ""
                try:
                    _b = _adm_exc.read().decode("utf-8", "replace")[:200]
                except Exception:
                    pass
                # nevalidní config → rollback hned (CLI by dopadl stejně)
                _sh.copyfile(bak, cfg)
                return {"ok": False, "result": "admin /load odmítl config (%s): %s → rollback"
                        % (_adm_exc.code, _b)}
        except Exception:
            pass
        reload_msg = "admin API nedostupné (%s)" % type(_adm_exc).__name__
    if not reload_ok:
        # CLI fallback — najdi caddy.exe
        exe = None
        for c in (_os.environ.get("STRATEGIE_CADDY_EXE"), "caddy",
                  r"C:\caddy\caddy.exe", r"C:\Tools\caddy.exe",
                  r"C:\Program Files\Caddy\caddy.exe"):
            if not c:
                continue
            if c == "caddy":
                w = _sh.which("caddy")
                if w:
                    exe = w
                    break
            elif _os.path.isfile(c):
                exe = c
                break
        if exe:
            try:
                rr = _sp.run([exe, "reload", "--config", cfg], capture_output=True,
                             text=True, timeout=60, encoding="utf-8", errors="replace")
                if rr.returncode == 0:
                    reload_ok = True
                    reload_msg = "CLI reload OK (%s)" % exe
                else:
                    reload_msg = "CLI reload FAIL: %s" % ((rr.stderr or rr.stdout or "")[-160:])
            except Exception as exc:
                reload_msg = "CLI reload ERR: %s" % exc
    if not reload_ok:
        # Soubor je upravený a platný, jen se nepodařilo reloadnout → necháme edit
        # (zafunguje po restartu STRATEGIE-CADDY), ale ohlásíme to.
        return {"ok": False, "result": "Edit OK, ale reload se nepovedl: %s. "
                "Caddyfile je upravený (failover přidán) — stačí restart služby "
                "STRATEGIE-CADDY. Backup: %s" % (reload_msg, bak)}
    return {"ok": True, "result": "Failover přidán (%s) + reload OK [%s]. Backup: %s"
            % (", ".join(changed) or "0", reload_msg, bak)}


def _ops_caddy_add_ucto() -> dict:
    """Přidá do ŽIVÉHO Caddyfile (C:\\caddy\\Caddyfile) blok pro
    'ucto.strategie-ai.com' → reverse_proxy na lokální Guacamole (127.0.0.1:8080),
    HTTPS+Let's Encrypt automaticky. Bez IP allowlistu (2FA řeší Guacamole TOTP;
    IP doplníme 1 změnou až budeme mít IP účetní). Idempotentní (kontrola bloku).
    Backup + reload přes admin API /load s rollbackem při nevalidním configu.
    Cloud Helios pro účetní (Martia+Peta) přes prohlížeč, bez VPN. Marti 7.7.2026."""
    import os as _os, shutil as _sh, time as _tm
    cfg = _os.environ.get("STRATEGIE_CADDYFILE") or r"C:\caddy\Caddyfile"
    if not _os.path.isfile(cfg):
        return {"ok": False, "result": "Caddyfile nenalezen: %s" % cfg}
    try:
        with open(cfg, "r", encoding="utf-8") as f:
            txt = f.read()
    except Exception as exc:
        return {"ok": False, "result": "čtení Caddyfile selhalo: %s" % exc}
    import re as _re
    # Guacamole běží pod kontextem /guacamole/ (Tomcat), root vrací 404 → přesměruj / na
    # /guacamole/. Ostatní cesty (vč. /guacamole/websocket-tunnel) jdou přes reverse_proxy.
    block = (
        "\nucto.strategie-ai.com {\n"
        "    # Cloud Helios pro účetní (Martia+Peta) přes Guacamole, bez VPN.\n"
        "    # 2FA řeší Guacamole (TOTP). IP allowlist doplníme až budeme mít IP účetní.\n"
        "    @root path /\n"
        "    redir @root /guacamole/\n"
        "    reverse_proxy 127.0.0.1:8080 {\n"
        "        header_up Host {host}\n"
        "        header_up X-Real-IP {remote_host}\n"
        "    }\n"
        "}\n"
    )
    if "redir @root /guacamole/" in txt:
        return {"ok": True, "result": "Blok ucto.strategie-ai.com (s přesměrováním na /guacamole/) už v Caddyfile je (žádná změna)."}
    if "ucto.strategie-ai.com {" in txt:
        # starší blok bez přesměrování → nahraď celý ucto blok (od hlavičky po samostatné '}')
        new = _re.sub(r"\n?ucto\.strategie-ai\.com \{.*?\n\}\n", block, txt, count=1, flags=_re.S)
        _upd = "aktualizován (přidáno přesměrování / → /guacamole/)"
    else:
        new = txt.rstrip("\n") + "\n" + block
        _upd = "přidán"
    bak = cfg + ".bak_ucto_" + _tm.strftime("%Y%m%d_%H%M%S")
    try:
        _sh.copyfile(cfg, bak)
        with open(cfg, "w", encoding="utf-8") as f:
            f.write(new)
    except Exception as exc:
        return {"ok": False, "result": "zápis Caddyfile selhal: %s" % exc}
    admin = _os.environ.get("STRATEGIE_CADDY_ADMIN") or "http://localhost:2019"
    try:
        import urllib.request as _u, urllib.error as _ue
        rq = _u.Request(admin.rstrip("/") + "/load", data=new.encode("utf-8"),
                        headers={"Content-Type": "text/caddyfile"}, method="POST")
        with _u.urlopen(rq, timeout=30) as resp:
            if 200 <= getattr(resp, "status", 200) < 300:
                return {"ok": True, "result": "Blok ucto.strategie-ai.com %s + reload OK "
                        "(admin /load). / → /guacamole/. HTTPS/Let's Encrypt automaticky. Backup: %s" % (_upd, bak)}
            return {"ok": False, "result": "admin /load HTTP %s" % getattr(resp, "status", "?")}
    except Exception as _adm_exc:
        try:
            import urllib.error as _ue2
            if isinstance(_adm_exc, _ue2.HTTPError):
                _b = ""
                try:
                    _b = _adm_exc.read().decode("utf-8", "replace")[:200]
                except Exception:
                    pass
                _sh.copyfile(bak, cfg)
                return {"ok": False, "result": "admin /load odmítl config (%s): %s → rollback"
                        % (_adm_exc.code, _b)}
        except Exception:
            pass
    # admin API nedostupné → soubor upravený a platný, jen restart služby
    return {"ok": False, "result": "Edit OK (blok přidán), ale admin /load nedostupné — "
            "stačí Restart-Service STRATEGIE-CADDY. Backup: %s" % bak}


